typedef long long ll;

using namespace std;
vector<vector<ll>>dp;
ll n,m;
vector<vector<ll>> edge;
vector<ll>lmul,rmul;
ll dfs0(ll par,ll node)
{
  int ip=edge[node].size();
  for(auto itr=edge[node].begin();itr!=edge[node].end();itr++)
  {
    int idx=itr-edge[node].begin();
    if(par==*itr)ip=idx;
  }
  if(dp[node][ip]!=-1)return dp[node][ip];
  ll res=1;
  for(auto nn:edge[node])
  {
    if(nn==par)continue;
    res=(ll)res*(dfs0(node,nn)+1)%m;
  }
  dp[node][ip]=res;
  return res;
}
ll dfs(ll par,ll node)
{
  int ip=edge[node].size();
  for(auto itr=edge[node].begin();itr!=edge[node].end();itr++)
  {
    int idx=itr-edge[node].begin();
    if(par==*itr)ip=idx;
  }
  if(dp[node][ip]!=-1)return dp[node][ip];
  ll mul=1;
  lmul.assign(edge[node].size(),0);
  rmul.assign(edge[node].size(),0);
  for(auto itr=edge[node].begin();itr!=edge[node].end();itr++)
  {
    int idx=itr-edge[node].begin();
    lmul[idx]=mul;
    mul=mul*(dfs(node,*itr)+1)%m;
  }
  mul=1;
  for(auto itr=edge[node].rbegin();itr!=edge[node].rend();itr++)
  {
    int idx=edge[node].rend()-itr-1;
    rmul[idx]=mul;
    mul=mul*(dfs(node,*itr)+1)%m;
  }
  for(auto itr=edge[node].begin();itr!=edge[node].end();itr++)
  {
    int idx=itr-edge[node].begin();
    dp[node][idx]=lmul[idx]*rmul[idx]%m;
  }
  dp[node][(int)edge[node].size()]=mul;
  return dp[node][ip];
}
int main()
{
  ios::sync_with_stdio(false);
  cin.tie(0);
  cin>>n>>m;
  edge.resize(n);
  dp.resize(n);
  rep(i,n-1)
  {
    ll a,b;
    cin>>a>>b;
    a--;b--;
    edge[a].push_back(b);
    edge[b].push_back(a);
  }
  rep(i,n)
  {
    dp[i].assign((int)edge[i].size()+1,-1);
  }
  dfs0(-1,0);
  rep(i,n)
  {
    cout<<dfs(-1,i)<<"\n";
  }
  cout<<flush;
  return 0;

}

