using namespace std;

map<pair<int, int>, pair<int, int>> memo;
vector<int> g[100010];
int M;

// white, black
pair<int, int> dfs(int p, int u) {
    if (memo.count({p, u})) return memo[{p, u}];
    int all_white = 1;
    int at_least_one_black = 0;
    for (int v : g[u]) {
        if (v == p) continue;
        auto res = dfs(u, v);
        int white = res.first;
        int black = res.second;
        int old_all_white = all_white;
        all_white = (all_white * white) % M;
        at_least_one_black = (at_least_one_black * (black % M + white % M) % M + old_all_white * black % M) % M;
    }
    return memo[{p, u}] = make_pair(all_white, (all_white + at_least_one_black) % M);
}

int main(int argc, char *argv[])
{
    int N;
    cin >> N >> M;
    for (int i = 1; i < N; i++) {
        int a, b;
        cin >> a >> b;
        a--; b--;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    for (int i = 0; i < N; i++) {
        auto res = dfs(-1, i);
        //memo[i].first = -1;
        int black = res.second;
        cout << black << endl;
    }
    return 0;
}

