#include <bits/stdc++.h>
using namespace std;

const int N = 1e5+5;
int n, m;
vector<int> v[N];
int dp[N], ans[N];


#define int long long
int MOD;

void dfs1(int node, int parent = -1) {
	long long tot = 1;
	for(int it : v[node]) {
		if(it == parent)continue;
		dfs1(it, node);
		tot *= (1 + dp[it]);
		tot %= m;
	}
	dp[node] = tot;
}

void dfs2(int node, int parent = -1) {
	ans[node] = dp[node];
	for(auto it : v[node]) {
		if(it == parent)continue;
		if(dp[node] <= 1 + dp[it]) {
			dp[node] *= m;	
		} 
		dp[node] /= 1 + dp[it];
		dp[it] *= 1 + dp[node];
		dfs2(it, node);	
		if(dp[it] <= 1 + dp[node]) {
			dp[it] *= m;
		}
		dp[it] /= 1 + dp[node];
		dp[node] *= 1 + dp[it];
	}	
}


int32_t main()
{
	ios::sync_with_stdio(false);
	cin.tie(nullptr);

	cin >> n >> m;	
	MOD = m;
	for(int i = 0; i < n - 1; i++) {
		int a, b;
		cin >> a >> b;
		v[a].push_back(b);
		v[b].push_back(a);
	}	

	dfs1(1);
	dfs2(1);		
	for(int i = 1; i <= n; i++) {
		cout << ans[i]%m << '\n';
	}
	return 0;
}

