using namespace std;
#define N 100005
#define v1 2*node
#define v2 2*node+1
#define med l+(r-l)/2
typedef long long ll;
typedef pair<int,int> pii;
vector<int> adj[N];
int n,m,res[N];
ll dp[N];
map<int,int> mapa[N];
vector<ll> st[N];
void update(int id, int node, int l, int r, int pos, int val){
    if(l == r){ st[id][node] = val%m; return; }
    if(pos <= med) update(id,v1,l,med,pos,val);
    else update(id,v2,med+1,r,pos,val);
    st[id][node] = st[id][v1]*st[id][v2]%m;
}
void upd(int u, int v, int val){
    update(u,1,0,adj[u].size()-1,mapa[u][v],val);
}
void dfs(int u, int p){
    dp[u] = 1;
    for(int v : adj[u]){
        if(v == p) continue;
        dfs(v,u);
        dp[u] = dp[u]*(1+dp[v])%m;
        upd(u,v,1+dp[v]);
    }
}
void go(int u, int p){
    res[u] = dp[u];
    for(int v : adj[u]){
        if(v == p) continue;
        upd(u,v,1);
        int ant = dp[v], cur = st[u][1]+1;
        dp[v] = dp[v]*cur%m;
        upd(v,u,cur);
        go(v,u);
        upd(v,u,1);
        dp[v] = ant;
        upd(u,v,ant+1);
    }
}
int main(){
    cin >> n >> m;
    for(int i = 0,u,v; i < n-1; i++){
        cin >> u >> v; u--,v--;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    for(int i = 0; i < n; i++){
        for(int j = 0; j < (int)adj[i].size(); j++)
            mapa[i][adj[i][j]] = j;
        st[i].resize(4*adj[i].size(),1);
    }
    dfs(0,-1);
    go(0,-1);
    for(int i = 0; i < n; i++)
        cout << res[i] << endl;
    return 0;
}

