void dfs1(int u, int p){
   for(auto v : vec[u]){
      if(v!=p) dfs1(v, u);
   }
   dp1[u]=1;
   sum[u].push_back({1,1});
   for(auto &v : vec[u])
      if(v == p) swap(v, vec[u].back());
   for(auto v : vec[u]){
      if(v!=p){
         dp1[u]*=(1+dp1[v]);
         dp1[u]%=M;
         sum[u].push_back({dp1[u], 1});
      }
   }
   sum[u].push_back({1, 1});
   for(int i=vec[u].size(); i>0; i--){
      int v = vec[u][i-1];
      if(v!=p){
         sum[u][i].second = (sum[u][i+1].second*(1+dp1[v]))%M;
      }
   }
   //printf(">%d %d\n", u, dp1[u]);
}
void dfs2(int u, int p, int indx){
   dp2[u]=1;
   //printf(">%d %d ", u, indx);
   if(p!=0){
      //printf("%d %d ",sum[p][indx-1].first, sum[p][indx+1].second);
      dp2[u]+= dp2[p] *(sum[p][indx-1].first * sum[p][indx+1].second);
      dp2[u]%=M;
   }
   //printf("%d\n", u, dp2[u]);
   for(int i=0; i<vec[u].size(); i++){
      int v = vec[u][i];
      if(v!=p) dfs2(v, u, i+1);
   }
}
