void dfs1(int x, int p=-1){
  dp1[x]=1;
  for(auto c:edges[x]){
    if(c==p)continue;

    dfs1(c, x);
    dp1[x] *= dp1[c];
    dp1[x] %= m;
  }
  dp1[x]++;
}

void dfs2(int x, int p=-1){
  if(p==-1)dp2[x]=1;
  int ec = edges[x].size();
  vector<ll>lprod(ec, 1);
  rep(i, ec){
    int to = edges[x][i];
    if(i)lprod[i] *= lprod[i-1];
    if(p==to)continue;
    lprod[i] *= dp1[to];
    lprod[i] %= m;
  }

  vector<ll> rprod(ec, 1);
  rrep(i, ec){
    int to = edges[x][i];
    if(i<ec-1)rprod[i] *= rprod[i+1];
    if(to==p)continue;
    rprod[i]*=dp1[to];
    rprod[i] %= m;
  }

  rep(i, ec){
    int to = edges[x][i];
    if(to==p)continue;

    dp2[to] = 1;
    if(i)dp2[to] *= lprod[i-1];
    if(i<ec-1)dp2[to] *= rprod[i+1];
    dp2[to] %= m;
    dp2[to] = (dp2[to]*dp2[x]+1)%m;
    dfs2(to, x);
  }
}

ll ans[MAXN];
void  dfs3(int x, int p=-1){
    ans[x] = dp2[x];
    for(auto to: edges[x]){
      if(to==p)continue;
      ans[x] *= dp1[to];
      ans[x]%=m;
      dfs3(to, x);
    }
}

