using namespace std;

#define MAXN 110000

ll n,m;
vector<vector<int>>edges(MAXN);

ll dp1[MAXN];
ll dp2[MAXN];
void dfs1(int x=1, int p =-1){
  dp1[x]=1;
  for(auto c: edges[x]){
    if(c==p)continue;
    dfs1(c, x);
    dp1[x] *= dp1[c];
    dp1[x] %= m;
  }
  dp1[x]++;
  dp1[x] %= m;
}

void dfs2(int x=1, int p=-1){
  if(p==-1)dp2[x]=1;

  int ec = edges[x].size();
  vector<ll>lprod(ec, 1);
  rep(i, ec){
    int c = edges[x][i];
    if(i)lprod[i] *= lprod[i-1];
    if(c==p)continue;
    lprod[i] *= dp1[c];
    lprod[i] %= m;
  }

  vector<ll>rprod(ec, 1);
  rrep(i, ec){
    int c = edges[x][i];
    if(i<ec-1)rprod[i] *= rprod[i+1];
    if(c==p)continue;
    rprod[i] *= dp1[c];
    rprod[i] %= m;
  }

  rep(i, ec){
    int c = edges[x][i];
    if(c==p)continue;
    dp2[c]=dp2[x];
    if(i)dp2[c] *= lprod[i-1];
    dp2[c] %= m;
    if(i<ec-1)dp2[c] *= rprod[i+1];
    dp2[c] %= m;
    dp2[c] = (dp2[c] + 1) % m;
    dfs2(c, x);
  }
}

vector<ll>ans(MAXN);
void dfs3(int x=1, int p=-1){
  ans[x] = dp2[x];
  for(auto c: edges[x]){
    if(c==p)continue;
    ans[x] *= dp1[c];
    ans[x] %= m;
    dfs3(c, x);
  }
}

