    for(int i = n-1; i >= 0; i--){
        vr[i] = vr[i+1]*(dp[u[i]]+1);
        vr[i] %= M;
    }
    for(int i = 0; i < n; i++){
        dp1[u[i]] = (dp1[v]);
        dp1[u[i]] *= (vl[i]*vr[i+1])%M;
