int getid(int i, int u)
{
	if(edge[i][0] == u) return 0;
	else return 1;
}

llint dfs(llint e, llint id)
{
	if(memo[e][id]) return memo[e][id];

	llint v = edge[e][id];
	llint ret = 1;
	for(int i = 0; i < G[v].size(); i++){
		if(G[v][i] == e) continue;
		ret *= dfs(G[v][i], 1-getid(G[v][i], v))+1, ret %= mod;
	}
	return memo[e][id] = ret;
}

