void dfs(int u) {
    for (int i=0;i<ch[u].size();i++) {
        int v=ch[u][i];
        if (pa[u]==v) continue;
        pa[v]=u;
        pos[v]=i;
        dfs(v);
    }
}

int go_down(int u) {
    if (down[u]>=0) return down[u];
    for (int i=0;i<ch[u].size();i++) {
        int v=ch[u][i];
        if (pa[u]==v) {
            if (pre[u].size()==0) pre[u].push_back(1);
            else pre[u].push_back(pre[u][pre[u].size()-1]);
            continue;
        }
        int t=1;
        if (pre[u].size()>0) t=pre[u][pre[u].size()-1];
        pre[u].push_back((1LL*t*(go_down(v)+1))%m);
    }
    for (int i=ch[u].size()-1;i>=0;i--) {
        int v=ch[u][i];
        if (pa[u]==v) {
            if (suf[u].size()==0) suf[u].push_back(1);
            else suf[u].push_back(suf[u][suf[u].size()-1]);
            continue;
        }
        int t=1;
        if (suf[u].size()>0) t=suf[u][suf[u].size()-1];
        suf[u].push_back((1LL*t*(go_down(v)+1))%m);
    }
    return down[u]=pre[u][pre[u].size()-1];
}

int go_up(int u) {
    if (up[u]>=0) return up[u];
    if (u==0) return 1;
    int f=pa[u];
    int ret=1;
    /*cout<<u<<" "<<f<<" "<<pos[u]<<"      "<<pa[u]<<endl;
    for (int i=0;i<pre[f].size();i++) cout<<pre[f][i]<<" ";cout<<endl;
    for (int i=0;i<suf[f].size();i++) cout<<suf[f][i]<<" ";cout<<endl;*/
    if (pos[u]-1>=0) ret=(1LL*ret*pre[f][pos[u]-1])%m;
    if ((int)suf[f].size()-pos[u]-2>=0) ret=(1LL*ret*suf[f][suf[f].size()-pos[u]-2])%m;
    //cout<<"       "<<ret<<endl;
    if (f!=0) {
        ret=(1LL*ret*(go_up(f)+1))%m;
    }
    return up[u]=ret;
}

