ll phi(ll x)
{
	ll rv = x;
	for (ll i = 2; i * i <= x; i++)
	{
		if (x % i == 0)
		{
			while (x % i == 0)
			{
				x /= i;
			}
			rv -= (rv / i);
		}
	}
	if (x > 1)
	{
		rv -= rv / x;
	}
	return rv;
}

//FUNCTIONS
ll dfs(ll parent, ll child)
{
	ll rv = 1;
	fr(i, 0, adj[child].size())
	{
		if (adj[child][i] != parent)
		{
			rv = mul(dfs(child, adj[child][i]) + 1, rv);
		}
	}
	dp[child] = rv;
	return rv;
}
void dfs2(ll parent, ll child)
{
	ll product = 1;
	vll suffix;
	vll prefix;
	fr(i, 0, adj[child].size())
	{
		if (adj[child][i] != parent)
		{
			prefix.pb(product);
			product = mul(product, dp[adj[child][i]] + 1);
		}
		else
		{
			prefix.pb(product);
		}
	}

	product = 1;
	fr2(i, adj[child].size() - 1, 0)
	{
		if (adj[child][i] != parent)
		{
			suffix.pb(product);
			product = mul(product, dp[adj[child][i]] + 1);
		}
		else
		{
			suffix.pb(product);
		}
	}
	reverse(suffix.begin(), suffix.end());

	fr(i, 0, adj[child].size())
	{
		if (adj[child][i] != parent)
		{
			dp2[adj[child][i]] = mul(prefix[i], suffix[i]);
			dp2[adj[child][i]] = mul(dp2[adj[child][i]], (1 + dp2[child]));
			dfs2(child, adj[child][i]);
		}
	}
}

void dfs3(ll parent, ll child)
{
	fr(i, 0, adj[child].size())
	{
		if (adj[child][i] != parent)
		{
			dfs3(child, adj[child][i]);
		}
	}
	ans[child] = mul(dp[child], 1 + dp2[child]);
}
