ll ans[101010];

ll solve(int v,int p){
  ll res=1;
  for(int i=0;i<G[v].size();i++){
    int u=G[v][i];
    if(u==p) continue;
    dp[v][i]=solve(u,v);
    (res*=(dp[v][i]+1))%=M;
  }
  return res;
}

void solve2(int v,int p,ll tot){
  int siz=G[v].size();
  rep(i,siz){
    if(G[v][i]==p) dp[v][i]=tot;
  }
  vector<ll> L(siz),R(siz);
  L[0]=1;
  for(int i=1;i<siz;i++){
    L[i]=L[i-1]*(dp[v][i-1]+1)%M;
  }
  R[siz-1]=1;
  for(int i=siz-2;i>=0;i--){
    R[i]=R[i+1]*(dp[v][i+1]+1)%M;
  }
  rep(i,siz){
    if(G[v][i]==p) continue;
    ll tmp=L[i]*R[i]%M;
    solve2(G[v][i],v,tmp);
  }
}

