      r.push_back(dp[u] + 1);
    }
  }
  r.push_back(1);

  REP(i, 1, l.size()) {
    l[i] *= l[i - 1];
    l[i] %= M;
  }

  for (ll i = (ll) r.size() - 2; i >= 0; i--) {
    r[i] *= r[i + 1];
    r[i] %= M;
  }

  REP(i, 0, E[v].size()) {
    ll u = E[v][i];
    if (u == p) continue;
    ll y = l[i] * r[i + 1] % M;
    ll z = ((x * y % M) + 1) % M;
    dfs2(u, v, z);
  }
}

int main(void) {
  cin >> N >> M;
  REP(i, 0, N - 1) {
    ll x, y;
    cin >> x >> y;
    x--;
    y--;
    E[x].push_back(y);
    E[y].push_back(x);
  }

  dfs(0, -1);
  dfs2(0, -1, 1);

  REP(i, 0, N) cout << ans[i] << endl;
}

