int n, m;
class Edge{
public:
	long long cost, num;
	int from, to;
	Edge(long long c, int f, int t, long long n){
		cost = c;
		from = f;
		to = t;
		num = n;
	}
};
typedef vector<Edge> Edges;
typedef vector<Edges> Graph;
void readGraph(Graph &g, int E, bool D, bool C){ // E:NumofEdges, D:Directed, C:Costed
	for(int i=0; i<E; ++i){
		Edge e(0, 0, 0, -1);
		if(!C) cin >> e.from >> e.to;
		else cin >> e.from >> e.to >> e.cost;
		--e.from;
		--e.to;
		g[e.from].push_back(e);
		if(!D){
			swap(e.from, e.to);
			g[e.from].push_back(e);
		}
	}
}

long long func(Graph &g, int v, int p){
//	cout << v << " " << p << "\n";
	if(g[v][p].num != -1) return g[v][p].num;
	long long res = 1;
	int w = g[v][p].to;
	for(int i=0; i<g[w].size(); ++i){
		if(g[w][i].to == v) continue;
		res *= func(g, w, i);
		res %= m;
	}
	res = (res + 1) % m;
//	cout << v << " " << p << " " << res << "\n";
	return g[v][p].num = res;
}

int main(){
	cin.tie(0);
	ios::sync_with_stdio(false);
	cin >> n >> m;
	Graph g(n);
	readGraph(g, n-1, false, false);
	for(int i=0; i<n; ++i)
		for(int j=0; j<g[i].size(); ++j)
			func(g, i, j);
	for(int i=0; i<n; ++i){
		long long ans = 1;
		for(int j=0; j<g[i].size(); ++j){
			ans *= g[i][j].num;
			ans %= m;
		}
		cout << ans << "\n";
	}
}

