void dfs2(int cur, int pre, ll p) {
    int n = E[cur].size();

	REP(i, n) if(E[cur][i] == pre) dp[cur][i] = p;

	vector<ll> L(n), R(n);

	REP(i, n) {
		L[i] = (i ? L[i - 1] : 1) * (1 + dp[cur][i]) % mo;
