struct DP {
  mint dp;
  DP(mint dp=1):dp(dp) {}
  DP operator+(const DP& a) const {
    return DP(dp*a.dp);
  }
  DP addRoot() const {
    return DP(dp+1);
  }
};

vector<DP> dp[MAX_N];
