        // cout << "node: " << node << ". mp1: " << mp1[adj[node][i]] << ". mp2: " << mp2[adj[node][i]] << endl;
        children[node].push_back(adj[node][i]);

        ways *= (1 + dp[adj[node][i]]);
        vals.push_back(1 + dp[adj[node][i]]);
        ways %= m;
        c++;
    }
    prefix[node].resize(vals.size() + 1);
    suffix[node].resize(vals.size() + 1);
    prefix[node][0] = suffix[node][0] = 1;
    for (int i = 1; i < prefix[node].size(); i++)
    {
        prefix[node][i] = prefix[node][i - 1] * vals[i - 1];
        prefix[node][i] %= m;
    }
    // cout << "node: " << node << ". prefix" << endl;
    // for (auto& num : prefix[node])
    // {
    //     cout << num << " ";
    // }
    // cout << endl;
    for (int i = 1; i < suffix[node].size(); i++)
    {
        suffix[node][i] = suffix[node][i - 1] * vals[vals.size() - i];
        suffix[node][i] %= m;
    }
    // cout << "node: " << node << ". suffix" << endl;
    // for (auto& num : suffix[node])
    // {
    //     cout << num << " ";
    // }
    // cout << endl;

    dp[node] = ways;
