        //     coef[node] %= m;
        // }
        // cout << "node: " << node << ". mp1: " << mp1[node] << ". mp2: " << mp2[node] << endl;

        coef[node] *= prefix[p][index];
        coef[node] %= m;
        coef[node] *= suffix[p][children[p].size() - index - 1];
        coef[node] %= m;

        coef[node] += 1;
        coef[node] %= m;
    }
    // cout << "node: " << node << ". coef: " << coef[node] << endl;
    ans[node] *= coef[node];
    ans[node] %= m;

    int i = 0;
    for (auto& v : adj[node])
    {
        if (v == p)
            continue;
        dfs2(v, node, i);
        i++;
    }
}

