const int maxn = 1e5+5;
int parent[maxn], child[maxn], dp1[maxn], mod;
VI pre[maxn], suf[maxn], dp2[maxn], G[maxn];

int getpre(const int u, const int i)
{ return i >= 0 ? pre[u][i] : 1; }
int getsuf(const int u, const int i)
{ return suf[u][i]; }

int dfs1(const int u, const int p)
{
    parent[u] = p;
    int& ans = dp1[u];
    if (-1 == ans) {
        int n = 0;
        FOR_ALL(v,G[u]) if (*v != p) {
            dfs1(*v,u); child[*v] = n++;
        }
        pre[u] = suf[u] = VI(n+1,1);
        int i = 0;
        FOR_ALL(v,G[u]) if (*v != p) {
            pre[u][i] = 1LL * getpre(u,i-1) * dp1[*v] % mod;
            pre[u][i] += getpre(u,i-1);
            pre[u][i] %= mod;
            i++;
        }
        i = n-1;
        FOR_ALLR(v,G[u]) if (*v != p) {
            suf[u][i] = 1LL * getsuf(u,i+1) * dp1[*v] % mod;
            suf[u][i] += getsuf(u,i+1);
            suf[u][i] %= mod;
            i--;
        }
        ans = getpre(u,n-1);
    }
    return ans;
}

int dfs2(const int u, const int c)
{
    if (u == 0)
        return 0;
    if (dp2[u].empty())
        dp2[u] = VI(G[u].size(),-1);
    int& ans = dp2[u][c];
    if (-1 == ans) {
        ans  = 1LL * getpre(u,c-1) * getsuf(u,c+1) % mod;
        ans += 1LL * ans * dfs2(parent[u],child[u]) % mod;
        ans %= mod;
    }
    return ans;
}

