ll phi(ll x)
{
	ll rv = x;
	for (ll i = 2; i * i <= x; i++)
	{
		if (x % i == 0)
		{
			while (x % i == 0)
			{
				x /= i;
			}
			rv -= (rv / i);
		}
	}
	if (x > 1)
	{
		rv -= rv / x;
	}
	return rv;
