ll powm(ll a, int e, ll mod){
    if(a==0)return 0;
    if(e==0)return 1;
    if(e%2==0){
        ll tmp=powm(a, e/2, mod);
        return (tmp*tmp)%mod;
    }
    ll tmp=powm(a, e/2, mod);
    return (((tmp*tmp)%mod)*a)%mod;
}

template<typename T>
T extgcd(T a,T b,T& x, T& y){
	T d=a;
	if(b!=0){
		d = extgcd(b, a%b, y, x);
		y -= (a/b) * x;
	}
	else{
		x = 1; y = 0;
	}
	return d;
}
template<typename T>
T mod_inv(T a,T m){
	T x,y;
	extgcd(a,m,x,y);
	return (m+x%m)%m;
}


vll rev(vll v){
    int l=sz(v);
    vll tmp(l);
    bool zero=false;
    rep(i,l)if(v[i]==0){
        zero=true;
        ll p=1;
        rep(j,l)if(j!=i)p=(p*v[i])%M;
        tmp[i]=p;
        break;
    }
    if(!zero){
        rep(i,l)tmp[i]=1;
        vll x=v;
        rep(k,sz(pr)){
            ll p=pr[k];
            vi ct(l);
            rep(i,l){
                while(x[i]%p==0){
                    ct[i]++;
                    x[i]/=p;
                }
            }
            int sum=0;
            rep(i,l)sum+=ct[i];
            rep(i,l){
                ct[i]=sum-ct[i];
                tmp[i]=(tmp[i]*powm(p, ct[i], M))%M;
            }
        }
        ll prod=1;
        rep(i,l)prod=(prod*x[i])%M;
        rep(i,l){
            tmp[i]=(tmp[i]*prod)%M;
            tmp[i]=(tmp[i]*mod_inv(x[i],(ll)M))%M;
        }
    }
    return tmp;
}

