ll N;
ll M;
ll MAX=10E+5;
vvll edge(MAX);
vector<vector<bool>> flag(MAX);
vvll black(MAX);
vll cnt(MAX);

void search(ll pre, ll index){
  if(flag[pre][index]) return;
  flag[pre][index] = true;
  ll pos = edge[pre][index];
  for(int i=0; i<cnt[pos]; ++i){
    if(edge[pos][i]==pre) continue;
    search(pos, i);
    black[pre][index] *= (black[pos][i]+1);
    black[pre][index] %= M;
  }
  return;
}

