int main()
{
   int N,M; cin>>N>>M;
   Graph G(N);
   for(int i=0;i<N-1;i++){
      int a,b; cin>>a>>b;
      a--; b--;
      G[a].push_back(b);
      G[b].push_back(a);
   }

   vector<int> dp(N);
   function<int(int,int)> dfs=[&](int v,int p)
   {
      int res=1;
      for(int u:G[v]) if(u!=p) res=(Lint)res*(dfs(u,v)+1)%M;
      return dp[v]=res;
   };
   vector<int> ans(N);
   function<void(int,int)> reroot=[&](int v,int p)
   {
      int N=G[v].size();
      vector<int> L(N+1,1),R(N+1,1);
      for(int i=0;i<N;i++){
         int u=G[v][i];
         L[i+1]=(Lint)L[i]*(dp[u]+1)%M;
      }
      for(int i=N-1;i>=0;i--){
         int u=G[v][i];
         R[i]=(Lint)(dp[u]+1)*R[i+1]%M;
      }
      ans[v]=R[0];
      for(int i=0;i<N;i++) if(G[v][i]!=p){
         int u=G[v][i]; int tmp=dp[v];
         dp[v]=(Lint)L[i]*R[i+1]%M;
         reroot(u,v);
         dp[v]=tmp;
      }
   };
   dfs(0,-1); reroot(0,-1);
   for(int i=0;i<N;i++) cout<<ans[i]<<endl;
   return 0;
}

