struct SegTree{
    vector<ll> p, s;
    ll pr = 1;

    void build(vector<ll> &o){
        p[0] = s[s.size() - 1] = 1;
        for(ll i = 1; i < o.size(); ++i) p[i] = p[i - 1] * o[i - 1] % m;
        for(ll i = ll(o.size()) - 2; i >= 0; --i) s[i] = s[i + 1] * o[i + 1] % m;
    }

    SegTree(){}

    SegTree(vector<ll> &o){
        if(o.empty()) o.push_back(1);
        for(ll e: o) pr = pr * e % m;
        p.resize(o.size());
        s.resize(o.size());
        build(o);
    }

    ll q(ll i){
        return p[i] * s[i] % m;
    }
};

ll dp[MAXN];
ll num[MAXN];
ll ans[MAXN];
vector<ll> g[MAXN];
SegTree *children[MAXN];
ll p[MAXN];

void dfs(ll v, ll pr = -1){
    p[v] = pr;
    ll c = 1;
    vector<ll> ch;
    for(ll to: g[v]){
        if(to == pr) continue;
        dfs(to, v);
        c = c * dp[to] % mod;
        num[to] = ch.size();
        ch.push_back(dp[to]);
    }
    children[v] = new SegTree(ch);
    dp[v] = c + 1;
}

void dfs2(ll v, ll fp, bool root = false){
    ll p_pr = fp;
    if(root){
        ans[v] = (dp[v] - 1 + m) % m;
    }else {
        ll ch_pr = children[v]->pr;
        //p_pr = children[p[v]]->q(1, 0, pall, 0, num[v]) % m;
        //p_pr = (p_pr * children[p[v]]->q(1, 0, pall, num[v] + 1, pall) % m * fp % m) % m;
        p_pr = fp;
        ans[v] = ch_pr * p_pr % m;
    }
    for(ll to: g[v]){
        if(to == p[v]) continue;

        dfs2(to, (p_pr * children[v]->q(num[to]) % m + 1) % m);
    }
}

