ll f(vector <vector <int> > &ad,int p,int x,int *par,ll *fs){
	if(fs[x]!=-1)
		return fs[x];
	par[x]=p;
	ll sum=1;
	for(int i=0;i<ad[x].size();i++){
		if(ad[x][i]==p)
			continue;
		sum=(sum*(f(ad,x,ad[x][i],par,fs)+1))%m;
	}
	fs[x]=sum;
	return sum;
}
ll g(vector <vector <int> > &ad,int x,int *par,ll *gs,ll *fs){
	if(gs[x]!=-1)
		return gs[x];
	ll sum=1;
	int p=par[x];
	for(int i=0;i<ad[p].size();i++){
		if(ad[p][i]==x)
			continue;
		if(ad[p][i]==par[p]){
			sum=(sum*(g(ad,p,par,gs,fs)+1))%m;
		}
		else{
			sum=(sum*(f(ad,par[ad[p][i]],ad[p][i],par,fs)+1))%m;
		}
	}
	gs[x]=sum;
	return sum;
}
