#define black first
#define white second

struct Task {
    int N;
    long long modulo;
    vector< vector<int> > adj;
    vector< vector<int> > children;
    vector< vector< pair<int, int>> > prefix;
    vector< vector< pair<int, int>> > suffix;
    vector< pair<int, int> > down;
    vector< pair<int, int> > up;

    void readInput() {
        N = readInt();
        modulo = readInt();
        adj.resize(N);

        for (int i = 0; i < N - 1; ++i) {
            int u = readInt() - 1, v = readInt() - 1;
            adj[u].push_back(v);
            adj[v].push_back(u);
        }

        down.resize(N);
        up.resize(N);
        children.resize(N);
        prefix.resize(N);
        suffix.resize(N);
    }

    int mul(int a, int b) {
        return (1LL * a * b) % modulo;
    }

    int add(int a, int b) {
        return (a + b) % modulo;
    }

    void mergeDown(pair<int, int>& u, const pair<int, int>& v) {
        u.black = mul(u.black, add(v.white, v.black));
        u.white = mul(u.white, v.white);
    }

    void mergeUp(pair<int, int>& u, const pair<int, int>& v) {
        u.white = mul(u.white, v.white);
        u.black = mul(u.black, v.black);
    }

    void dfsDown(int u, int p) {
        down[u] = {1, 1};

        for (int v : adj[u]) {
            if (v != p) {
                dfsDown(v, u);
                children[u].push_back(v);
                mergeDown(down[u], down[v]);
            }
        }
    }

    void dfsUp(int u, int parent) {
        if (parent == -1) {
            up[u] = {1, 1};
        }

        for (int i = 0; i < size(children[u]); ++i) {
            pair<int, int> p = up[u];
            int v = children[u][i];

            if (i - 1 >= 0) {
                mergeUp(p, prefix[u][i - 1]);
            }

            if (i + 1 < size(suffix[u])) {
                mergeUp(p, suffix[u][i + 1]);
            }

            up[v] = {p.black + p.white, p.white};
            dfsUp(v, u);
        }
    }

    void solve() {
        dfsDown(0, -1);

        for (int u = 0; u < N; ++u) {
            pair<int, int> p = {1, 1};
            prefix[u].resize(size(children[u]));
            suffix[u].resize(size(children[u]));

            for (int k = 0; k < size(children[u]); ++k) {
                int v = children[u][k];
                mergeDown(p, down[v]);
                prefix[u][k] = p;
            }

            p = {1, 1};

            for (int k = size(children[u]) - 1; k >= 0; --k) {
                int v = children[u][k];
                mergeDown(p, down[v]);
                suffix[u][k] = p;
            }
        }

        dfsUp(0, -1);

        for (int i = 0; i < N; ++i) {
            int result = mul(up[i].black, down[i].black);
            cout << result << endl;
        }

    }

    void perform() {
        readInput();
        solve();
    }
};

int main()
{
    Task task;
    task.perform();

    return 0;
}

