ll M;
ll solve(int idx,int prev)
{
    if(adj[idx].size()==1 && adj[idx][0]==prev) return 1;
    if(memo[idx]!=-1) return memo[idx];

    ll ret=1;

    for(int i=0;i<adj[idx].size();i++)
    {
        if(adj[idx][i]!=prev)
        {
            ret=(ret%M*(1+solve(adj[idx][i],idx))%M)%M;
        }
    }

    //cout<<idx<<" "<<color<<" "<<prev<<" "<<ret<<endl;
    return memo[idx]=ret%M;
}
