//returns (black, white)
pair<int, int> dfs(int v, int parent) {
    int all_white = 1, sth_black = 0;
    for(int nei: edges[v]) {
        if(nei != parent) {
            auto p = dfs(nei, v);
            sth_black = ((ll)sth_black*(p.first + p.second)%m + all_white*p.first%m)%m;
            all_white = (ll)all_white*p.second%m;
        }
    }
    return {(all_white+sth_black)%m, all_white};
}

