const int N = 1e5 + 5;
int n, mod, dp[N], sol[N];
vector<int> g[N], prefix[N], suffix[N];

int add(int a, int b)
{
    return (a + b) % mod;
}

int sub(int a, int b)
{
    return (a - b + mod) % mod;
}

int mul(int a, int b)
{
    return (1ll * a * b) % mod;
}

void dfs(int node, int parent)
{
    prefix[node] = vector<int>(g[node].size());
    suffix[node] = vector<int>(g[node].size());
    int cur = 1;
    for(int i = 0; i < g[node].size(); i++)
    {
        int child = g[node][i];
        if(child != parent) {
            dfs(child, node);
            cur = mul(cur, dp[child]);
        }
        prefix[node][i] = cur;
    }
    cur = 1;
    for(int i = (int)g[node].size() - 1; i >= 0; i--)
    {
        int child = g[node][i];
        if(child != parent)
            cur = mul(cur, dp[child]);
        suffix[node][i] = cur;
    }
    dp[node] = add(1, cur);
}

int solve(int node, int parent)
{
    sol[node] = dp[node];
    for(int i = 0; i < g[node].size(); i++)
    {
        int child = g[node][i];
        if(child != parent)
        {
            //save data
            int dp1 = dp[node], dp2 = dp[child];

            //change dp[node]
            int p = i ? prefix[node][i - 1] : 1;
            int s = i + 1 < g[node].size() ? suffix[node][i + 1] : 1;
            dp[node] = mul(p, s);
            dp[node] = mul(dp[node], dp[parent]);
            dp[node] = add(dp[node], 1);

            //change dp[child]
            dp[child] = sub(dp[child], 1);
            dp[child] = mul(dp[child], dp[node]);
            dp[child] = add(dp[child], 1);

            //solve
            solve(child, node);

            //undo data
            dp[node] = dp1;
            dp[child] = dp2;
        }
    }
}

