            (tmp *= rec1(to, pos)) %= mod;
        }
        (res += tmp) %= mod;
    }
    // この頂点を白でぬる場合
    (res += 1) %= mod;
    return dp1[pos] = res;
}

ll rec2(int eid, int ang){ // angは0ならfirstにいるという意味
    if(dp2[eid][ang] >= 0) return dp2[eid][ang];
    ll res = 0;
    int pos = (ang == 0) ? es[eid].first : es[eid].second;
    int par = (ang == 1) ? es[eid].first : es[eid].second;

    // par方面だけ削除した結果を出して終了
    int par_graph_idx = from_pos_to_graph_id[pos][par];
    res = muls[pos][par_graph_idx];
    if(pos != 0){
        // par方面だけ削除して、本来のparの方向の結果を掛け算する
        int next_edge = G[pos][from_pos_to_graph_id[pos][pars[pos]]].second;
