ll f(int u, int p=-1) {
    ll ans = 1;

    int D = nxt[u].size();
    rep(i,D){
        int v = nxt[u][i];
        if (v == p) {
            pi[u] = i;
            continue;
        }
        if (dp[u][i] == -1) {
            dp[u][i] = f(v,u);
        }
        (ans *= (dp[u][i] + 1)) %= MOD;
    }

    return ans;
}

void solve(int N,int M,vi& x,vi& y) {
    MOD = M;

    nxt.resize(N);
    dp.resize(N);
    degr.resize(N);
    pi.resize(N);

    rep(i,N-1){
        int u=x[i]-1, v=y[i]-1;
        nxt[u].pb(v);
        nxt[v].pb(u);
    }
    rep(i,N) {
        degr[i] = nxt[i].size();
        dp[i].assign(degr[i], -1);
    }

    vii order(N);
    rep(i,N) order[i] = ii(degr[i], i);
    sort(ALL(order), greater<ii>());

    vll ans(N);

    for (ii x: order) {
        int u = x.second, D = x.first;
        ans[u] = f(u);

        vll acc_left(D+1), acc_right(D+1);
        acc_left[0] = acc_right[D] = 1;
        for (int i=0; i<D; ++i) {
            acc_left[i+1] = (acc_left[i] * (dp[u][i] + 1)) % MOD;
        }
        for (int i=D-1; i>=0; --i) {
            acc_right[i] = (acc_right[i+1] * (dp[u][i] + 1)) % MOD;
        }
        rep(i,D) {
            int v = nxt[u][i];
            int j = pi[u];
            dp[v][j] = (acc_left[i] * acc_right[i+1]) % MOD;
        }
    }

    rep(u,N) {
        printf("%lld\n", ans[u]);
    }
}

