}
void dfs2(int u = 0, mint pa = 1) {
    int ord = adj[u].size();
    int ch_size = ord + int(par[u] == -1) + 1;
    vector<mint> pre(ch_size, 1), suf(ch_size, 1);
    for (int i = 0, j = 1; i < ord; i++) {
        if (adj[u][i] != par[u]) {
            pre[j] = pre[j - 1] * dp[adj[u][i]];
            j++;
        }
    }
    for (int i = ord - 1, j = ch_size - 2; i >= 0; i--) {
        if (adj[u][i] != par[u]) {
            suf[j] = suf[j + 1] * dp[adj[u][i]];
            j--;
        }
    }
    // cout << "dfs at " << u << ":\n";
