ll func(vvl &G, vl &DP, ll s, ll p) {
  ll ans = 1;
  AUTO(g, G[s]) {
    if (g == p)
      continue;
    ans *= (func(G, DP, g, s) + 1) % MOD;
    ans %= MOD;
  }
  return DP[s] = ans;
}

void func2(vvl &G, vl &DP, vl &DP2, ll s, ll p) {
  DP2[s] = 1;
  AUTO(g, G[s]) {
    DP2[s] *= (DP[g] + 1) % MOD;
    DP2[s] %= MOD;
  }

  ll n = G[s].size();
  vl lft(n), rht(n);
  REP(i, n) {
    lft[i] = (DP[G[s][i]] + 1) % MOD;
    rht[i] = (DP[G[s][i]] + 1) % MOD;
  }
  FOR(i, 1, n) {
    lft[i] *= lft[i - 1];
    lft[i] %= MOD;
  }
  RREP(i, n - 1) {
    rht[i] *= rht[i + 1];
    rht[i] %= MOD;
  }

  REP(i, n) if (G[s][i] != p) {
    DP[s] = 1;
    if (i > 0)
      DP[s] *= lft[i - 1];
    if (i + 1 < n)
      DP[s] *= rht[i + 1];
    DP[s] %= MOD;
    // 自分の子を呼ぶたびにDP[s]を変えてるのが味噌of味噌
    func2(G, DP, DP2, G[s][i], s);
  }
}

