const int A = 1e5+5;
ll n, mod, dp[A], sol[A];
vector <int> v[A], pref[A], suff[A];
int mul(int a, int b) {return (1ll * (a % mod) * (b % mod)) % mod;}
int add(int a, int b) {return (mod + (a % mod) + (b % mod)) % mod;}
void dfs(int node, int par)
{
	dp[node] = 1;
	int sz = v[node].size();
	pref[node].resize(sz);
	suff[node].resize(sz);
	for (int i = 0; i < sz; i++)
	{
		int to = v[node][i];
		if (to != par)
		{
			dfs(to, node);
			dp[node] = mul(dp[node], dp[to]);
		}
		pref[node][i] = dp[node];
	}
	dp[node] = add(dp[node], 1);
	int suf = 1;
	for (int i = sz-1; ~i; i--)
	{
		int to = v[node][i];
		if (to != par)
			suf = mul(suf, dp[to]);
		suff[node][i] = suf;
	}
}
void solve(int node, int par)
{
	sol[node] = add(dp[node], -1);
	int sz = v[node].size();
	for (int i = 0; i < sz; i++)
	{
		int to = v[node][i];
		if (to == par) continue;
		int tmp_node = dp[node], tmp_to = dp[to];
		dp[node] = mul(i? pref[node][i-1] : 1, i+1 == sz? 1 : suff[node][i+1]);
		dp[node] = add(1, mul(dp[node], dp[par]));
		dp[to] = add(mul(add(dp[to], -1), dp[node]), 1);
		solve(to, node);
		dp[node] = tmp_node, dp[to] = tmp_to;
	}
}
