	int next, to;
	edge(int N=0,int T=0):next(N),to(T){}
}e[MAXN<<1];
int fir[MAXN], num = 0;
inline void join(int a, int b)
{
	e[++num].next = fir[a];
	fir[a] = num;
	e[num].to = b;
}

int f[MAXN], g[MAXN], ans[MAXN], pre[MAXN], suf[MAXN], t[MAXN];
