void dfs1(int u, int fa)
{
	int cnt = 0;
	f[u]    = 1;
	in[u].push_back(1);
	for(int i=fir[u]; i; i=e[i].next)
	{
		int v = e[i].to;
		if(v == fa) continue;
		dfs1(v, u);
		f[u] = mul(f[u], add(f[v], 1));
		cnt++;
		in[u].push_back(v);
	}
	pre[0] = suf[cnt+1] = 1;
	for(int i=1; i<=cnt; i++)
		pre[i] = mul(pre[i-1], add(f[in[u][i]], 1));
	for(int i=cnt; i>=1; i--)
		suf[i] = mul(suf[i+1], add(f[in[u][i]], 1));
	for(int i=1; i<=cnt; i++)
		t[in[u][i]] = mul(pre[i-1], suf[i+1]);
}
