    int to = edges[x][i];
    if(to==p)continue;
    ll pr = 1;
    if(i)pr *= lprod[i-1] % m;
    if(i<edges[x].size()-1)pr *= rprod[i+1] % m;
    dp2[to] = (dp2[x] * pr+1)%m;
    dfs2(to, x);
  }
}

ll ans[MAXN];
void dfs3(int x, int p=-1){
  ans[x] = dp2[x];
  for(auto to:edges[x]){
    if(to==p)continue;
    ans[x] *= dp1[to];
    ans[x] %= m;
    dfs3(to, x);
  }
}

