ll dfs(int now,int par){
  ll res=1;
  for(int nex:g[now]){
    if(nex==par) continue;
    ll z=dfs(nex,now);
    child[now].push_back(z);
    res=res*(z+1)%M;
  }
  res=(res+M)%M;
  return dp[now]=res;
}

void solve(int now,int par,ll pans){
  if(par!=-1){
    ll res=(pans+1)%M;
    for(int i=0;i<child[now].size();i++){
      res=(res*(child[now][i]+1))%M;
    }
    ans[now]=res;
  }

  int n=child[now].size();
  vector<ll> left(n+2),right(n+2);
  left[0]=1;
  right[n+1]=1;
  for(int i=1;i<=n;i++) left[i]=(left[i-1]*(child[now][i-1]+1)%M)%M;
  for(int i=n;i>=1;i--) right[i]=(right[i+1]*(child[now][i-1]+1)%M)%M;

  int p=0;
  for(int i=0;i<g[now].size();i++){
    if(g[now][i]==par){
      p=1;
      continue;
    }
    solve(g[now][i],now,((left[i-p]*right[i+2-p])%M*(pans+1)%M)%M);
  }
}

