ll dfs(int v, int p, vector<vector<int>> &G) {
    ll ret = 1;
    dp[v].resize(G[v].size());
    for(int i = 0; i < G[v].size(); i++) {
        if (G[v][i] == p) {
            P[v] = i;
            continue;
        }
