  for (int i = 1; i < num; i++) ldp[i] = ldp[i] * ldp[i - 1] % M;
  for (int i = num - 2; i >= 0; i--) rdp[i] = rdp[i] * rdp[i + 1] % M;

  for (int i = 0; i < num; i++) {
    if (G[n][i] != pre) {

      dp[n] = 1;
      if (i - 1 >= 0) dp[n] = dp[n] * ldp[i - 1] % M;
      if (i + 1 <= num - 1) dp[n] = dp[n] * rdp[i + 1] % M;

      dfs2(G[n][i], n);
    }
  }
}

