void dfs2(ll x, ll last = -1){
    if(last == -1)dp2[x] = 1;
    vector<ll> lprod= vector<ll>(edge[x].size(), 1);
    vector<ll> rprod= vector<ll>(edge[x].size(), 1);
    for(ll i = 0;i < edge[x].size();i++){
        ll to = edge[x][i];
        if(i-1 >= 0)lprod[i] = lprod[i-1];
        if(to == last)continue;
        lprod[i] *= dp1[to];lprod[i] %= m;
    }
    for(ll i = (ll)edge[x].size() - 1;i >= 0;i--){
        ll to = edge[x][i];
        if(i+1 < rprod.size())rprod[i] = rprod[i+1];
        if(to == last)continue;
        rprod[i] *= dp1[to];rprod[i] %= m;
    }
    for(ll i = 0;i < edge[x].size();i++){
        ll to = edge[x][i];
        if(to == last)continue;
        ll rest_prod = 1;
        if(i-1 >= 0)rest_prod = rest_prod * lprod[i-1] % m;
        if(i+1 < rprod.size())rest_prod = rest_prod * rprod[i+1] % m;
        dp2[to] = (dp2[x] * rest_prod + 1) % m;
        dfs2(to, x);
    }
}

