void dfs1(const vector<vector<long>> &adj_lists, long M, vector<long> &dp1s,
          long i, vector<long> &us) {
  const long N = adj_lists.size();
  long dp = 1;
  us[i] = 1;
  for (long j : adj_lists[i]) {
    if (!us[j]) {
      dfs1(adj_lists, M, dp1s, j, us);
      dp = dp * (dfs1(adj_lists, M, dp1s, j, us) + 1) % M;
    //   dp = dp * (dp1s[j] + 1);
    }
  }
  dp1s[i] = dp;
}

void dfs2(const vector<vector<long>> &adj_lists, long M, vector<long> &dp1s,
          vector<long> &dp2s, long i, vector<long> &us) {
  const long N = adj_lists.size();
  // calculate dp1s[i] and dps2[i]
  long dp = 1;
  us[i] = 1;
  for (long j : adj_lists[i]) {
    dp = dp * (dp1s[j] + 1) % M;
    // dp = dp * (dp1s[j] + 1);
  }
  dp1s[i] = dp;
  dp2s[i] = dp;

//   printf("i = %ld\n", i);
//   for (long j = 0; j < N; j++) {
//     printf("j = %ld, dp1s[j] = %ld\n", j, dp1s[j]);
//   }

  // calculate accls, accrs to facilitate calculation of
  // dp1s[i] when calling dfs2 on i's neighbours
  const long K = adj_lists[i].size();
  vector<long> accls(K, 0), accrs(K, 0);
  for (long k = 0; k < K; k++) {
    const long j = adj_lists[i][k];
    accls[k] = dp1s[j] + 1;
    accrs[k] = dp1s[j] + 1;
  }
  for (long k = 1; k < K; k++) {
    accls[k] = accls[k] * accls[k - 1] % M;
  }
  for (long k = K - 2; k >= 0; k--) {
    accrs[k] = accrs[k] * accrs[k + 1] % M;
  }
  for (long k = 0; k < K; k++) {
    const long j = adj_lists[i][k];
    if (!us[j]) {
      dp1s[i] = (k > 0 ? accls[k - 1] : 1) * (k + 1 < K ? accrs[k + 1] : 1) % M;
      dfs2(adj_lists, M, dp1s, dp2s, j, us);
    }
  }
}

