  long w=1;
  for(int i=0;i<sz;i++)
  {
    int ch=adj[vert][i];
    if(ch!=par)
    {
      dfs1(ch,vert);
      w*=(dp1[ch]+1)%m;
      w%=m;
    }
  }
  dp1[vert]=w;
}


void dfs2(int vert, int parval, int par)
{
  int sz=adj[vert].size();
  long w=1;
  w=(dp1[vert]*((1+parval)%m))%m;
  dp2[vert]=w;
  vector<int> child;
  for(int i=0;i<sz;i++)
  {
    if(adj[vert][i]!=par)
      child.push_back(adj[vert][i]);
  }
  sz=child.size();
  vector<int> pre(sz,1), suf(sz,1);
  for(int i=1;i<sz;i++)
  {
    pre[i]=(pre[i-1]*((dp1[child[i-1]]+1)%m))%m;
  }
  for(int i=sz-2;i>=0;i--)
  {
    suf[i]=(suf[i+1]*((dp1[child[i+1]]+1)%m))%m;
  }
  for(int i=0;i<sz;i++)
  {
    int u=child[i];
    int pv=(((pre[i]*suf[i])%m)*((parval+1)%m))%m;
    dfs2(u,pv,vert);
  }


}


