long long M;
struct TreeDP{
	typedef long long vint;
	static const int maxN=110000;
	struct edge{
		int to;
		int rev;
		// ここに何かをもたせたいときはその都度編集する
		edge(int a,int b){to=a;rev=b;}
		edge(){to=rev=0;}
	};
	vector<edge>g[maxN];
	vector<int>lp;
	vector<int>rp;
	vector<vint>L[maxN];
	vector<vint>R[maxN];
	int N;
	vint dfs(int a,int b){
		L[a][0]=R[a][0]=1;
		while(lp[a]<g[a].size()&&b!=lp[a]){
			// 例: EDPC V: Subtree
			L[a][lp[a]+1]=L[a][lp[a]]*(1+dfs(g[a][lp[a]].to,g[a][lp[a]].rev))%M;
			lp[a]++;
		}
		while(rp[a]<g[a].size()&&b!=g[a].size()-1-rp[a]){
			R[a][rp[a]+1]=R[a][rp[a]]*(1+dfs(g[a][g[a].size()-1-rp[a]].to,g[a][g[a].size()-1-rp[a]].rev))%M;
			rp[a]++;
		}
		if(b==-1)return L[a][g[a].size()];
		else return L[a][b]*R[a][g[a].size()-b-1]%M;
	}

	// 何か重みのある辺が追加したいときはここを変える
	// 各辺について2度以上呼ばないようにする
	void add_edge(int from,int to){
		g[from].push_back(edge(to,g[to].size()));
		g[to].push_back(edge(from,g[from].size()-1));
	}
	vector<vint> solve(int n){
		N=n;
		for(int i=0;i<n;i++){
			L[i]=vector<vint>(g[i].size()+1);
			R[i]=vector<vint>(g[i].size()+1);
		}
		lp=vector<int>(n);
		rp=vector<int>(n);
		vector<vint>ret(n);
		for(int i=0;i<n;i++){
			ret[i]=dfs(i,-1);
		}
		return ret;
	}
};

