  sz[curr] = edges[curr].size();
  if(curr != 1)
  sz[curr]--;
  int Val = 0;
  for(int i=0;i<edges[curr].size();i++){
    if(edges[curr][i] != par){
      dfs1(edges[curr][i],curr,Val++);
      dp1[curr] = (1LL*dp1[curr]*((1 + dp1[edges[curr][i]])%M))%M;
      pref[curr].push_back(dp1[curr]);
    }
  }
  int currVal = 1;
  for(int i=edges[curr].size()-1;i>=0;i--){
    if(edges[curr][i] != par){
      currVal = (1LL*currVal*((1 + dp1[edges[curr][i]])%M))%M;
      suff[curr].push_back(currVal);
    }
  }
}
void dfs2(int curr,int par)
{
  if(curr != 1){
    int currVal;
    if(sz[par] == 1){
      currVal = 1;
    }
    else{
      if(which[curr] == 0){
        currVal = suff[par][sz[par]-2-which[curr]];
      }
      else if(which[curr] == sz[par] - 1){
        currVal = pref[par][which[curr]-1];
      }
      else{
        currVal = (1LL*pref[par][which[curr]-1]*suff[par][sz[par]-2-which[curr]])%M;
      }
    }
    dp2[curr] = (1LL*dp2[par]*currVal)%M;
    dp2[curr] = (dp2[curr] + 1)%M;
  }
  else{
    dp2[curr] = 1;
  }
  for(int i=0;i<edges[curr].size();i++){
    if(edges[curr][i] != par){
      dfs2(edges[curr][i],curr);
    }
  }
}
