using namespace std;
typedef long long ll;

vector<int> adj[100005];
int pai[100005];
ll mod, down[100005], up[100005];

ll solve(int u, int p = 0){
    pai[u] = p;
    ll res = 1;
    for(int v : adj[u])
        if(v != p)
            res *= (1 + solve(v, u));
    return down[u] = res;
}

void go(int u, int p = 0){
    vector<ll> vec;
    for(int v : adj[u])
        if(v != p)
            vec.push_back(1 + down[v]);

    vector<ll> pref(vec), suff(vec);
    for(int i = 1; i < pref.size(); i++)
        pref[i] = (pref[i]*pref[i-1])%mod;
    for(int i = int(suff.size()) - 2; i >= 0; i--)
        suff[i] = (suff[i]*suff[i+1])%mod;

    for(int i = 0; i < adj[u].size(); i++){
        int v = adj[u][i];
        ll esq = (i-1 >= 0 ? pref[i-1] : 1);
        ll dir = (i+1 < vec.size() ? suff[i+1] : 1);
        up[v] = (1 + esq*dir)%mod;
    }
}

