    }
    int root = 1;
    for(int i = 1; i <= n; i++)
        if(!pai[i]){
            solve(i);
            root = i;
        }
    for(int i = 1; i <= n; i++)
        up[i] = 1;
    go(root);
    for(int i = 1; i <= n; i++){
        ll res = (down[i] * up[i])%mod;
        cout << res << endl;
    }
    return 0;
}

