ll dfs(int nd, int parent)
{
  ll black = 1;

  for(auto adj : t[nd])
  {
    if(adj == parent) continue;
    ll ways = dfs(adj, nd);
    black = black*(ways + 1)%mod;
  }
  dp[nd] = black;
  return dp[nd];
}

void dfs1(int nd, int parent)
{
  auto I = find(t[nd].begin(), t[nd].end(), parent);
  if (I != t[nd].end()) t[nd].erase(I);

  if((int)t[nd].size() >= 1)
  {
    int n= t[nd].size();
    vector<ll> L(n, 0) , R(n, 0);
    L[0] = 1;
    R[n-1] = 1;
    for(int i=1; i<n; i++)
      L[i] = L[i-1] * (dp[t[nd][i-1]]+1) %mod;
    for(int i=n-2; i>=0; i--) 
      R[i] = R[i+1] * (dp[t[nd][i+1]]+1) % mod;

    for(int i=0; i<n; i++)
    {
      int y = t[nd][i];
      dp1[y] = (dp1[nd] +1) * L[i]%mod*R[i]%mod;
      dfs1(y, nd);
    }
  }
}

