void dfs1(int x, int p = -1) {
    d[x] = 1;
    for (int i = 0; i < adj[x].size(); i++) if (adj[x][i] != p) {
        dfs1(adj[x][i], x);
        d[x] *= d[adj[x][i]] + 1;
        d[x] %= m;
    }
}

void dfs2(int x, int p = -1) {
    int pi = -1;
    for (int i = 0; i < adj[x].size(); i++) if (adj[x][i] == p) pi = i;
    int len = adj[x].size() + (pi == -1);
    long long pfx[len], sfx[len];
    pfx[0] = sfx[len - 1] = 1;
    for (int i = 0, l = 0, r = len - 1; i < adj[x].size(); i++) if (adj[x][i] != p) {
        pfx[l + 1] = pfx[l] * (d[adj[x][i]] + 1);
        pfx[l + 1] %= m;
        sfx[r - 1] = sfx[r] * (d[adj[x][i]] + 1);
        sfx[r - 1] %= m;
        l++; r--;
    }
    for (int i = 0, l = 0; i < adj[x].size(); i++) if (adj[x][i] != p) {
        u[adj[x][i]] = (u[x] * pfx[l] % m * sfx[l + 1] % m + 1) % m;
        dfs2(adj[x][i], x);
        l++;
    }
}

