const int maxn = 1e5 + 7;
vector<int> graph[maxn];

int dp[maxn][2], ans[maxn];

void dfs(int u, int p)
{
    dp[u][1] = 1;
    int cnt = 0;
    for(int &v: graph[u])
        if(v != p)
        {
            dfs(v, u);
            dp[u][0] += dp[v][0] + dp[v][1];
            dp[u][0] %= mod;
            dp[u][1] *= (dp[v][1] + 1);
            dp[u][1] %= mod;
            cnt++;
        }
}

void dfs2(int u, int p, int val)
{
    ans[u] = (val + 1);
    ans[u] %= mod;
    int cnt = 0, prf = 1;
    vector<int> pref, suff, tmp;
    for(int &v: graph[u])
        if(v != p)
        {
            ans[u] *= (dp[v][1] + 1);
            ans[u] %= mod;
            int t = (dp[v][1] + 1);
            t %= mod;
            prf *= t;
            prf %= mod;
            pref.pb(prf);
            tmp.pb(t);
            cnt++;
        }
    reverse(tmp.begin(), tmp.end());
    int s = 1;
    for(int &e: tmp)
    {
        s *= e;
        s %= mod;
        suff.pb(s);
    }
    reverse(suff.begin(), suff.end());
    int i = 0;
    for(int &v: graph[u])
        if(v != p)
        {
            int pf = (i > 0 ? pref[i-1] : 1);
            int sf = (i < cnt-1 ? suff[i+1] : 1);
            int t = pf * sf * (val + 1);
            t %= mod;
            dfs2(v, u, t);
            i++;
        }
}

