int lp[100005];
long long biok[100005];
vector <long long> bios[100005], biop[100005];
long long modz(long long x, long long y)
{
	if(x + y >= MOD)
	{
		return x+y-MOD;
	}
	return x+y;
}
long long f(int poz, int p)
{
	v.push_back(make_pair(poz, p));
	long long u = 1;
	for(int i = 0; i < s[poz].size(); i++)
	{
		if(s[poz][i] != p)
		{
			lp[s[poz][i]] = i;
			u *= f(s[poz][i], poz);
			u %= MOD;
		}
	}
	if(p != -1)
	{
		return biok[poz] = modz(u, 1);
	}
	else
	{
		return u;
	}
}
void r(int poz, int p)
{
	for(int j = 1; j <= s[poz].size(); j++)
	{
		if(s[poz][j-1] != p)
		{
		    biop[poz].push_back(biop[poz][j-1] * biok[s[poz][j-1]]);
		}
		else
		{
			biop[poz].push_back(biop[poz][j-1] * modz(biop[p][lp[poz]] * bios[p][lp[poz]+1], 1));
		}
		biop[poz][j] %= MOD;
	}
	for(int j = s[poz].size()-1; j >= 0; j--)
	{
		if(s[poz][j] != p)
		{
		    bios[poz][j] = bios[poz][j+1] * biok[s[poz][j]];
		}
		else
		{
			bios[poz][j] = bios[poz][j+1] * modz(biop[p][lp[poz]] * bios[p][lp[poz]+1], 1);
		}
		bios[poz][j] %= MOD;
	}
}
