void dfs1(int x,int par){
	int mul=1;
	for(auto to:g[x]){
		if(to!=par){
			dfs1(to,x);
			mul=(ll)mul*(dp[to]+1)%mod;
		}
	}
	if(g[x].size()>1||par==-1)dp[x]=(mul)%mod;
	else dp[x]=1;
}
void dfs2(int x,int par){
	ans[x]=dp[x];
	vector<int>son;
	for(auto to:g[x])son.push_back(dp[to]+1);
	vector<int>pre(son.size()+3),suf(son.size()+3);
	suf[son.size()]=1;
	for(int i=0;i<son.size();i++)pre[i]=(ll)(i==0?1:pre[i-1])*son[i]%mod;
	for(int i=son.size()-1;i>=0;i--)suf[i]=(ll)suf[i+1]*son[i]%mod;
	int pos=0;
	for(auto to:g[x]){
		if(to==par){
			pos++;
			continue;
		}
		int val=(ll)(pos==0?1:pre[pos-1])*(pos==g[x].size()-1?1:suf[pos+1])%mod;
		int dpto=dp[to],dpx=dp[x];
		dp[x]=val;
		dp[to]=(ll)dp[to]*(dp[x]+1)%mod;
		if(to!=par)dfs2(to,x);
		dp[x]=dpx;dp[to]=dpto;
		pos++;
	}
}
