ll res_run(ll cur, ll parent) {
	// dp tells me how many possibilities are below
	// parent tells me how many are up

	if(parent != -1 && dp[cur][parent] != -1)
		return dp[cur][parent];

	ll foo = 1;

	for(const auto it : adj[cur]) {
		if(it != parent) {
			foo = (foo * (res_run(it, cur) + 1));
			if(foo >= M)
				foo %= M;
		}
	}

	dp[cur][parent] = foo;
	return foo;
}

