    r[vs-1]=(1+dp[v[id][vs-1]])%m;
    if(v[id][vs-1]==par)r[vs-1]=1;
    for(ll i=vs-2;i>=0;i--){
        ll res=1+dp[v[id][i]];
        if(v[id][i]==par)res=1;
        r[i]=(r[i+1]*res)%m;
