struct edge{
	int next,to;
}a[N<<1];
int head[N],cnt;
inline void add(int u,int v){
	a[++cnt].to=v;
	a[cnt].next=head[u];
	head[u]=cnt;
}
int n,Mod;
int f[N],g[N],ans[N];
void dfs(int x,int fa){
	f[x]=1;
	vector<int>suf,pre;
	pre=vector<int>();
	suf=vector<int>();
	for (int i=head[x];i;i=a[i].next){
		int y=a[i].to;
		if (y==fa) continue;
		dfs(y,x);
		f[x]=1ll*f[x]*(f[y]+1)%Mod;
		suf.push_back(f[y]+1);
		pre.push_back(f[y]+1);
	}
	int now=0,nowf=1;
	for (int i=suf.size()-2;i>=0;--i)
		suf[i]=1ll*suf[i+1]*suf[i]%Mod;
	for (int i=head[x];i;i=a[i].next){
		int y=a[i].to;
		if (y==fa) continue;
		g[y]=nowf;
		if (now!=suf.size()-1) g[y]=1ll*g[y]*suf[now+1]%Mod;
		nowf=1ll*nowf*pre[now]%Mod;
		++now;
	}
}
void dp(int x,int fa,int s){
	int k=1ll*(s+1)*g[x]%Mod;
	ans[x]=1ll*(k+1)*f[x]%Mod;
	for (int i=head[x];i;i=a[i].next){
		int y=a[i].to;
		if (y==fa) continue;
		dp(y,x,k);
	}
}
