int n;

ll m;

ll prod (ll a, ll b)
{
    if(b == 0)
        return 0;
    if(b & 1)
        return (prod(a, (b ^ 1)) + a) % m;
    ll pr = prod(a, (b >> 1));
    return pr * 2 % m;
}

vector <int> edges[N_MAX];

vector <int> sons[N_MAX];

bool visited[N_MAX];

void dfs (int node)
{
    visited[node] = true;
    for(int u : edges[node])
        if(visited[u] == false)
        {
            sons[node].push_back(u);
            dfs(u);
        }
}

ll up[N_MAX], down[N_MAX];

void computeDown (int node)
{
    down[node] = 1;
    for(int u : sons[node])
    {
        computeDown(u);
        down[node] = prod(down[node], (down[u] + 1));
    }
}

ll dw[N_MAX];

void computeUp (int node)
{
    up[node] = (up[node] + 1) % m;
    dw[sons[node].size()] = 1;
    for(int i = sons[node].size() - 1; i >= 0; i--)
        dw[i] = prod(dw[i + 1], (down[sons[node][i]] + 1));
    ll dw1 = 1;
    for(int i = 0; i < sons[node].size(); i++)
    {
        int u = sons[node][i];
        up[u] = prod(prod(dw1, dw[i + 1]), up[node]);
        dw1 = prod(dw1, (down[u] + 1));
        computeUp(u);
    }
}

