    down[cur] = 1;
    for (int i: e[cur]) if (i!=fa) {
        dfs1(i, cur);
        down[cur] = down[cur] * (down[i]+1) % m;
    }
}
void dfs2(int cur,int fa,LL up) {
    ans[cur] = down[cur] * (up+1) % m;

    int sz = (int)e[cur].size();
    vector<LL> fr, bk;
    fr = vector<LL> (sz);
    bk = vector<LL> (sz);
    REP(i,0,sz-1)               fr[i] = (i>0 ? fr[i-1] : 1LL)    * (e[cur][i]==fa ? (up+1) : (down[e[cur][i]]+1)) % m;
    for (int i=sz-1; i>=0; i--) bk[i] = (i<sz-1 ? bk[i+1] : 1LL) * (e[cur][i]==fa ? (up+1) : (down[e[cur][i]]+1)) % m;

    REP(i,0,sz-1) if (e[cur][i]!=fa) {
        LL nup = 1LL;
        if (i>0) nup = nup * fr[i-1] % m;
        if (i<sz-1) nup = nup * bk[i+1] % m;
        dfs2(e[cur][i], cur, nup);
    }
}
