void dfs(int u, int p){
	dp[u][1] = dp[u][0] = 1;
	int b = dp[u][1];
	int w = dp[u][0];
	for(auto i: g[u]){
		if(i == p)	continue;
		dfs(i, u);
		dp[u][0] = (w + dp[i][0] + dp[i][1] - 1 + m) % m;
		dp[u][1] = (b + b*dp[i][1]) % m;
		w = dp[u][0];
		b = dp[u][1];
	}
}

void dfs1(int u, int p){
	vector<pi> v;
	int cw = 1, cb = 1;
	for(int i = g[u].size()-1; i >= 0; i--){
		int x = i;	i = g[u][x];
		if(i == p){i = x;	continue;}
		int tw = (cw + dp[i][0] + dp[i][1] - 1 + m) % m;
		int tb = (cb + cb*dp[i][1]) % m;
		v.push_back(make_pair(tw, tb));
		cw = tw;	cb = tb;
		i = x;
	}
	cw = dp[u][0], cb = dp[u][1];
	reverse(v.begin(), v.end());
	int l = g[u].size();
	for(int i = 0, ct = 0; i < (int)g[u].size(); i++){
		int x = i;	i = g[u][x];
