			sb = sw = 1;
		else{
			++ct;
			sw = v[ct].fi; sb = v[ct].se; 
		}
		// MERGE PREFIX SUFFIX
		int mw = (cw + sw - 1 + m) % m;
		int mb = (cb*sb) % m;
		// MERGE ENDS 
		int tw = (cw + dp[i][0] + dp[i][1] - 1 + m) % m;
		int tb = (cb + cb*dp[i][1]) % m;
		ans[i][0] = (dp[i][0] + mw + mb - 1 + m) % m;
		ans[i][1] = (dp[i][1] + dp[i][1]*mb) % m;
		dp[i][0] = (1 + mw + mb - 1 + m) % m;
		dp[i][1] = (1 + mb) % m;
		dfs1(i, u);
		cw = tw;	cb = tb;
		i = x;
	}
}

