    return (a + b)%mod;
}

int mul(int a, int b)
{
    a = (a + mod)%mod;
    b = (b + mod)%mod;
    return (1ll*a*b)%mod;
}

void dfs(int node, int par)
{
    prefix[node] = vector<int>(adj[node].size());
    suffix[node] = vector<int>(adj[node].size());
    int cur = 1;
    for(int i=0; i < adj[node].size(); i++)
    {
        int child = adj[node][i];
        if(child != par)
        {
            dfs(child, node);
            cur = mul(cur, dp[child]);
        }
        prefix[node][i] = cur;
    }
    dp[node] = add(1, cur);
    cur = 1;
    for(int i = (int)adj[node].size() - 1; i>=0; i--)
    {
        int child = adj[node][i];
        if(child != par)
            cur = mul(cur, dp[child]);
        suffix[node][i] = cur;
    }
}

void solve(int node, int par)
{
    sol[node] = dp[node];
    for(int i = 0; i < adj[node].size(); i++)
    {
        int child = adj[node][i];
        if(child == par) continue;
        int dp1 = dp[node], dp_child = dp[child];
        dp[node] = dp[par];
        if(i)
            dp[node] = mul(dp[node], prefix[node][i-1]);
        if(i + 1 < adj[node].size())
            dp[node] = mul(dp[node], suffix[node][i+1]);

        dp[node] = add(1, dp[node]);

        dp[child] = add(-1, dp[child]);
        dp[child] = mul(dp[child], dp[node]);
        dp[child] = add(1, dp[child]);

        solve(child, node);

        dp[node] = dp1;
        dp[child] = dp_child;
    }
}

