using namespace std;

template<typename T,typename Y>
struct Rerooting{

	using F =function<T(T,T)>;
	using G =function<T(T,Y)>;

	vector<vector<int>>g;
	vector<vector<T>>dp;
	vector<T>ans;
	const F merge;
	const G add_root;
	const T identity;

	Rerooting(int n,const F &merge,const G &add_root,const T &identity):merge(merge),add_root(add_root),identity(identity){
		g.resize(n);
		dp.resize(n);
		ans.resize(n,identity);
	}

	void add_edge(int u,int v){
		g[u].emplace_back(v);
	}

	void build(int root=0){
		dfs1(root);
		dfs2(root,identity);
	}

	T dfs1(int v,int par=-1){
		T cul = identity;
		dp[v].resize(g[v].size(),identity);
		for(int i=0;i<g[v].size();++i){
			int u =g[v][i];
			if(u==par)continue;
			dp[v][i]=dfs1(u,v);
			cul=merge(cul,dp[v][i]);
		}
		return add_root(cul,v);
	}

	void dfs2(int v,const T &val ,int par=-1){
		for(int i=0;i<g[v].size();++i){
			if(g[v][i]==par){
				dp[v][i]=val;
			}
		}
		vector<T>dp_l(g[v].size()+1,identity),dp_r(g[v].size()+1,identity);
		for(int i=0;i<g[v].size();++i){
			dp_l[i+1]=merge(dp_l[i],dp[v][i]);
		}
		for(int i=g[v].size()-1;i>=0;--i){
			dp_r[i]=merge(dp_r[i+1],dp[v][i]);
		}

		ans[v]=add_root(dp_l[g[v].size()],v);

		for(int i=0;i<g[v].size();++i){
			int u=g[v][i];
			if(u==par)continue;
			dfs2(u,add_root(merge(dp_l[i],dp_r[i+1]),v),v);
		}
	}
};

void solve()
{
	int n,m;
	cin>>n>>m;
	Rerooting<ll,ll>tree(n,[&](ll a,ll b){return a*b%m;},[&](ll a,ll b){return (a+1)%m;},1);
	rep(i,n-1){
		int x,y;
		cin>>x>>y;
		x--;y--;
		tree.add_edge(x,y);
		tree.add_edge(y,x);
	}
	tree.build();
	rep(i,n)cout<<(tree.ans[i]-1+m)%m<<"\n";
}

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(0);
	cout << fixed << setprecision(15);
	solve();
