const int nax = 1e5 + 5;

int n, mod;
vector<int> graph[nax];
pair<int, int> down[nax], up[nax];
vector<vector<int>> children;
vector<vector<pair<int, int>>> pref, suf;

int mul(int a, int b)
{
    a = (ll) a * b % mod;

    return a;
}

int add(int a, int b)
{
    a += b;

    if(a >= mod)
        a -= mod;

    return a;
}

pair<int, int> merge(const pair<int, int> &a, const pair<int, int> &b)
{
    pair<int, int>p{1, 0};
    p.all_white = mul(a.all_white, b.all_white);
    p.sth_is_black = add(mul(a.all_white, b.sth_is_black), mul(a.sth_is_black, add(b.all_white, b.sth_is_black)));

    return p;
}

pair<int, int> process(pair<int, int> p)
{
    return {p.all_white, add(p.all_white, p.sth_is_black)};
}

void dfs_one(int nod, int dad)
{
    pair<int, int> p{1, 0};

    for(int x : graph[nod])
    {
        if(x != dad)
        {
            children[nod].push_back(x);
            dfs_one(x, nod);
            p = merge(p, down[x]);
        }
    }

    down[nod] = process(p);
}

void dfs_two(int nod, int dad)
{
    for(int i = 0; i < (int) children[nod].size(); i++)
    {
        pair<int, int> p = {1, 0};

        if(i)
            p = merge(p, pref[nod][i - 1]);
        if(i != (int) children[nod].size() - 1)
            p = merge(p, suf[nod][i + 1]);

        int child = children[nod][i];

        if(nod != 1)
            p = merge(p, up[nod]);

        up[child] = process(p);

        dfs_two(child, nod);
    }
}

int main()
{
    cin >> n >> mod;

    for(int i = 0; i < n - 1; i++)
    {
        int a, b;

        cin >> a >> b;

        graph[a].push_back(b);
        graph[b].push_back(a);
    }
    children.resize(n + 1);
    pref.resize(n + 1);
    suf.resize(n + 1);

    dfs_one(1, -1);
    for(int i = 1; i <= n; i++)
    {
        int m = children[i].size();
        pair<int, int> p = {1, 0};

        for(int j = 0; j < m; j++)
        {
            p = merge(p, down[children[i][j]]);
            pref[i].push_back(p);
        }

        p = {1, 0};

        for(int j = m - 1; j >= 0; j--)
        {
            p = merge(p, down[children[i][j]]);
            suf[i].push_back(p);
        }
        reverse(suf[i].begin(), suf[i].end());
    }

    dfs_two(1, -1);

    for(int i = 1; i <= n; i++)
    {
        pair<int, int> p = {1, 0};

        if(i != 1)
            p = merge(p, up[i]);

        if(children[i].size())
            p = merge(p, pref[i].back());

        p = process(p);
        cout << p.sth_is_black << '\n';
    }

    return 0;
}

