        g[b-1].push_back(make_pair(a-1, i));
    }

    ll cnt[4]={0};
    dfs( -1, 0, cnt );

    dfs2( -1, 0 );

    for(i=0; i<n; i++) {
        printf("%lld\n", ans[i]);
    }

    return 0;
}

