void dfs(ll u, ll p=-1) {
    blackdown[u] = 1;
    for (int i = 0; i < g[u].size(); i++) {
        if (g[u][i] == p)
            continue;
        ll to = g[u][i];
        dfs(to, u);
        blackdown[u] = (blackdown[u] * (blackdown[to] + 1)) % m;
    }
}


ll pw(ll x, ll y, ll md) {
    if (y == 0)
        return 1;
    ll tmp;
    if (y % 2 == 0) {
        tmp = pw(x, y / 2, md);
        return (tmp * tmp) % md;
    } else {
        tmp = pw(x, y - 1, md);
        return (tmp * x) % md;
    }
}


ll get(ll a, ll b) {
    ll a1, b1, m1;
    ll t = __gcd(__gcd(a, b), m);
    a1 = a / t;
    b1 = b / t;
    m1 = m / t;
    return (a1 * pw(b1, eul[m1] - 1, m1)) % m1;
}


void dfss(ll u, ll p=-1) {
    if (p != -1)
        ans[u] = (blackdown[u] + (get(ans[p], blackdown[u] + 1) * blackdown[u])) % m;
    else
        ans[u] = blackdown[u];
    for (int i = 0; i < g[u].size(); i++)
        if (g[u][i] != p)
            dfss(g[u][i], u);
}


