const int N=1e5+4;

int mod;

vector<int> v[N];

vector<int> suf[N],pre[N];

int up[N],dp[N];

int add(int a,int b)
{
	a+=b;

	if(a>=mod)
	a-=mod;

	return a;
}

void mul_self(int &a,int b)
{
	a=(1LL*a*b)%mod;
}

void dfs(int node,int par)
{
	dp[node]=1;

	for(int it:v[node])
	if(it!=par)
	{
		dfs(it,node);

		mul_self(dp[node],add(dp[it],1));
	}

	int sz=(int)v[node].size();

	pre[node].resize(sz); suf[node].resize(sz);

	rep(i,0,sz)
	{
		int x=v[node][i];

		pre[node][i]=1;

		if(i!=0)
		pre[node][i]=pre[node][i-1];

		if(x==par)
		continue;

		mul_self(pre[node][i],add(dp[x],1));
	}

	for(int i=sz-1;i>=0;i--)
	{
		int x=v[node][i];

		suf[node][i]=1;

		if(i!=sz-1)
		suf[node][i]=suf[node][i+1];

		if(x==par)
		continue;

		mul_self(suf[node][i],add(dp[x],1));
	}
}

void dfs1(int node,int par)
{
	int sz=(int)v[node].size();

	rep(i,0,sz)
	{
		int x=v[node][i];

		if(x==par)
		continue;

		int here=1;

		if(par!=-1)
		here=up[par]+1;

		if(here>=mod)
		here-=mod;

		if(i!=0)
		mul_self(here,pre[node][i-1]);

		if(i!=sz-1)
		mul_self(here,suf[node][i+1]);

		here++;

		if(here>=mod)
		here-=mod;

		up[x]=here;

		dfs1(x,node);
	}
}

int main()
{
