		v[a].pb(b); v[b].pb(a);
	}

	dfs(1,-1);

	up[1]=1;

	dfs1(1,-1);

	rep(i,1,n+1)
	{
		int ans=(1LL*dp[i]*up[i])%mod;

		//cout<<i<<" "<<dp[i]<<" "<<up[i]<<endl;

		priln(ans);
	}

    return 0;
}

#include <iostream>
