using namespace std;

#define REP(i, n) for(int i = 0; i < (int)(n); ++i)
#define FOR(i, m, n) for(int i = (int)(m); i < (int)(n); ++i)

int M;

// まず頂点 0 が黒である場合の答えを求める (木DP)
void dfs(int curr, int par, vector<long long>& dp, vector<vector<int>>& G)
{
    dp[curr] = 1;
    for(int v: G[curr]){
        if(v != par){
            dfs(v, curr, dp, G);
            dp[curr] *= dp[v]+1;
            dp[curr] %= M;
        }
    }
}

// 次に、上の結果を用いて全ての頂点についての答えを求める (全方位木DPと言われる所以)
void dfs_all(int curr, int par, vector<long long>& ans, vector<long long>& dp, vector<vector<int>>& G)
{
    ans[curr] = 1;
    for(int v: G[curr]){
        ans[curr] *= dp[v]+1;
        ans[curr] %= M;
    }

    // 頂点を curr -> v に変えるために下準備
    int n = G[curr].size();
    // lft[i]: (dp[c1]+1)*...*(dp[ci]+1)
    // rht[i]: (dp[ci]+1)*...*(dp[cn]+1)
    vector<long long> lft(n), rht(n);
    REP(i, n) lft[i] = rht[i] = dp[G[curr][i]]+1;
    FOR(i, 1, n){
        lft[i] *= lft[i-1];
        lft[i] %= M;
    }
    for(int i = n-2; i >= 0; --i){
        rht[i] *= rht[i + 1];
        rht[i] %= M;
    }

    REP(i, n){  // G[curr][i] を次の頂点にする場合
        if(G[curr][i] != par){
            dp[curr] = 1;
            if(i > 0) dp[curr] *= lft[i-1];
            dp[curr] %= M;
            if(i+1 < n) dp[curr] *= rht[i+1];
            dp[curr] %= M;
            dfs_all(G[curr][i], curr, ans, dp, G);
        }
    }
}

int main()
{
    int N;
    cin >> N >> M;
    vector<vector<int>> G(N);
    REP(i, N-1){
        int x, y;
        cin >> x >> y;
        --x, --y;
        G[x].push_back(y);
        G[y].push_back(x);
    }

    // dp[i]: 頂点を i とする部分木に置いて、i が黒色に塗られており、
    //        かつ黒色の頂点を辿って全ての黒色の頂点に行ける塗り方の組合せ
    vector<long long> dp(N), ans(N);
    dfs(0, -1, dp, G);
    dfs_all(0, -1, ans, dp, G);

    REP(i, N) cout << ans[i] << endl;

    return 0;
}

