#include <bits/stdc++.h>
using namespace std;

long long M;
/* Rerooting: 全方位木 DP
    問題ごとに以下を書き換える
    - 型DPと単位元
    - 型DPに対する二項演算 merge
    - まとめたDPを用いて新たな部分木のDPを計算する add_root
    計算量: O(N)
*/
struct Rerooting {
    /* start 問題ごとに書き換え */
    struct DP {  // DP の型
        long long dp;
        DP(long long dp_) : dp(dp_) {}
    };
    const DP identity = DP(1);                                                           // 単位元はしっかり定義する(末端でもadd_rootされるので注意)
    function<DP(DP, DP, long long)> merge = [](DP dp_cum, DP d, long long cost) -> DP {  // d:辺eに対応する部分木のdpの値  cost:eのコスト
        return DP((dp_cum.dp * (d.dp)) % M);
    };
    function<DP(DP)> add_root = [](DP d) -> DP {  // まとめたDPを用いて、新たな部分木のDPを計算する
        return DP(d.dp + 1);
    };
    /* end 問題ごとに書き換え */

    // グラフの定義
    struct Edge {
        int from;
        int to;
        long long cost;
    };
    using Graph = vector<vector<Edge>>;

    vector<vector<DP>> dp;  // dp[v][i]: vから出るi番目の有向辺に対応する部分木のDP
    vector<DP> ans;         // ans[v]: 頂点vを根とする木の答え
    Graph G;

    Rerooting(int N) : G(N) {
        dp.resize(N);
        ans.assign(N, identity);
    }

    void add_edge(int a, int b, long long c = 1) {
        G[a].push_back({a, b, c});
    }
    void build() {
        dfs(0);            // 普通に木DP
        bfs(0, identity);  // 残りの部分木に対応するDPを計算
    }

    DP dfs(int v, int p = -1) {  // 頂点v, 親p
        DP dp_cum = identity;
        int deg = G[v].size();
        dp[v] = vector<DP>(deg, identity);
        for (int i = 0; i < deg; i++) {
            int u = G[v][i].to;
            if (u == p) continue;
            dp[v][i] = dfs(u, v);
            dp_cum = merge(dp_cum, dp[v][i], G[v][i].cost);
        }
        return add_root(dp_cum);
    }
    void bfs(int v, const DP& dp_p, int p = -1) {
        int deg = G[v].size();
        for (int i = 0; i < deg; i++) {  // 前のbfsで計算した有向辺に対応する部分木のDPを保存
            if (G[v][i].to == p) dp[v][i] = dp_p;
        }

        vector<DP> dp_l(deg + 1, identity), dp_r(deg + 1, identity);  // 累積的なDP
        for (int i = 0; i < deg; i++) {
            dp_l[i + 1] = merge(dp_l[i], dp[v][i], G[v][i].cost);
        }
        for (int i = deg - 1; i >= 0; i--) {
            dp_r[i] = merge(dp_r[i + 1], dp[v][i], G[v][i].cost);
        }
        ans[v] = add_root(dp_l[deg]);
        for (int i = 0; i < deg; i++) {
            int u = G[v][i].to;
            if (u == p) continue;
            bfs(u, add_root(merge(dp_l[i], dp_r[i + 1], 0)), v);  // 累積同士のmergeなので、edgeは適当に
        }
    }
};

int main() {
    int N;
    cin >> N >> M;
    Rerooting reroot(N);
    for (int i = 0; i < N - 1; i++) {
        int u, v;
        cin >> u >> v;
        u--, v--;
        reroot.add_edge(u, v);
        reroot.add_edge(v, u);
    }
    reroot.build();

    for (int i = 0; i < N; i++) {
        cout << (reroot.ans[i].dp - 1 + M) % M << endl;
    }
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

const int mxN = 1e5 + 5;
int N, mod;
vector<int> adj[mxN];
ll dp[mxN], answer[mxN];

void dfs(int u, int p)
{
	dp[u] = 1;
	for (int v : adj[u])
	{
		if (v == p)
			continue;
		dfs(v, u);
		dp[u] = (dp[u] * dp[v]) % mod;
	}
	dp[u] = (dp[u] + 1) % mod;
}

void rec(int u, int p, ll ways)
{
	vector<ll> pref, suff;
	pref.push_back(1);
	for (int v : adj[u])
	{
		if (v == p)
			continue;
		pref.push_back(dp[v]);
		suff.push_back(dp[v]);
	}
	suff.push_back(1);
	for (int i = 1; i < (int)pref.size(); i++)
	{
		pref[i] = pref[i] * pref[i - 1] % mod;
	}
	for (int i = (int)suff.size() - 2; i >= 0; i--)
	{
		suff[i] = suff[i] * suff[i + 1] % mod;
	}
	answer[u] = pref.back() * ways % mod;
	int i = 0;
	for (int v : adj[u])
	{
		if (v == p)
			continue;
		ll new_ways = pref[i] * suff[i + 1] % mod;
		new_ways = new_ways * ways % mod;
		new_ways = (new_ways + 1) % mod;
		rec(v, u, new_ways);
		i++;
	}
}

int main()
{
	ios_base::sync_with_stdio(false);

	cin >> N >> mod;
	for (int i = 0; i < N - 1; i++)
	{
		int u, v;
		cin >> u >> v;
		u--;
		v--;
		adj[u].push_back(v);
		adj[v].push_back(u);
	}
	dfs(0, -1);
	rec(0, -1, 1);
	for (int i = 0; i < N; i++)
	{
		cout << answer[i] << '\n';
	}

	return 0;
}

