        x--;
        y--;
        G[x].push_back(y);
        G[y].push_back(x);
    }
    queue<int> qu;
    vector<int> order;//(N, 0);
    vector<int> parent(N, -1);
    qu.push(0);
    while(!qu.empty()) {
        int cur = qu.front();
        //cout << cur << endl;
        qu.pop();
        order.push_back(cur);

        for(auto v: G[cur]) {
            if(parent[cur] == v) continue;
            parent[v] = cur;
            qu.push(v);
        }
    }
//    cout << order.size() << endl;
    reverse(order.begin(), order.end());


    vector<LL> dpA(N, 1), dpB(N, 1);
    for(auto v: order) {
        //cout <<"  "<< v << endl;
        dpA[v] ++;
        int to = parent[v];
        if(to == -1) continue;
        dpA[to] *= dpA[v];
        dpA[to] %= M;
    }
    reverse(order.begin(), order.end());
    for(int i=0; i<N; i++) {
        //cout << dpA[i] << endl;
    }

    function<LL(LL, LL)> oper = [&] (LL a, LL b) -> LL {
        return a * b % M;
    };
    LL id = 1;
    vector<int> ans(N, 0);
    for(auto v: order) {
        LL cur = dpA[v] - 1;
        ans[v] = cur * dpB[v] % M;
        vector<LL> matome;
        for(auto u: G[v]) {
            if(parent[v] == u) continue;
            matome.push_back(dpA[u]);
        }
        //cout <<v << " " <<  matome.size() << endl;
        if(matome.empty()) continue;
        matome.push_back(dpB[v]);
        SegmentTree<LL> seg(matome.size(), oper, id);
        for(int i=0; i<matome.size(); i++)
            seg.update(i, matome[i]);
        vector<LL> score;
        for(int i=0; i<matome.size(); i++) {
            LL tmp = seg.query(0,i) * seg.query(i+1,matome.size()) % M;
            //cout << i << " " << tmp << " " << matome[i] << endl;
            score.push_back(tmp);
        }
        int iter = 0;
        for(int i=0; i<G[v].size(); i++) {
            int u = G[v][i];
            if(parent[v] == u) continue;
            dpB[u] = score[iter] + 1;
            iter++;
        }



    }
    for(int i=0; i<N; i++)
        cout << ans[i] << endl;



    return 0;
}

