  vector<int> acm(n + 1, 1), bcm(n + 1, 1);
  for (int i = 1; i <= n; i++) {
    acm[i] = mul(acm[i - 1], dp[cld[i - 1]] + 1);
    bcm[i] = mul(bcm[i - 1], dp[cld[n - i]] + 1);
  }
  for (int i = 0; i < n; i++) {
    int tmp = ep[crr] + 1;
    if (i) tmp = mul(tmp, acm[i]);
    if (n - i) tmp = mul(tmp, bcm[n - 1 - i]);
    ep[cld[i]] = tmp;
  }
  for (int nxt : cld) {
      efs(nxt, crr);
    }
