using namespace std;
vector<vector<int>> G;
vector<long long> L, D, U;
int M;
void recur(int n, int l)
{
    if (L[n] >= 0) return;
    L[n] = l;
    for (int t : G[n]) recur(t, l+1);
    long long k = 1;
    for (int t : G[n]) if (L[t] == l + 1) k = (k * (D[t] + 1)) % M;
    D[n] = k;
}
long long up(int n)
{
    if (U[n] >= 0) return U[n];
    int parent = -1;
    for (int t : G[n]) if (L[t] == L[n] - 1) parent = t;
    if (parent == -1) {
        return U[n] = 1;
    }
    long long ans = 1;
    for (int t : G[parent]) if (n != t) {
        if (L[t] == L[parent] + 1)
            ans = ans * (D[t] + 1) % M;
        else
            ans = ans * (up(t) + 1) % M;
    }
    return U[n] = (ans + 1) % M;
}
int main()
{
    int N; cin >> N >> M;
    G.resize(N);
    L.resize(N, -1);
    U.resize(N, -1);
    D.resize(N, -1);
    for (int i = 0; i < N - 1; i++) {
        int x, y; cin >> x >> y; x--, y--;
        G[x].push_back(y);
        G[y].push_back(x);
    }
    recur(0, 0);
    for (int i = 0; i < N; i++) {
        cout << D[i] * up(i) % M << '\n';
    }
    return 0;
}

