using namespace std::string_literals;
using ll = int64_t;
using vecint = vector<int>;
using vecll = vector<ll>;
using boost::irange;

using T = tuple<ll,ll>;
T dfs1(const vector<vecint>& g, vector<T>& dp, ll m, int i, int p=-1) {
  ll already = 0;
  ll now = 1;
  for(auto&& to:g[i]) {
    if (to == p) continue;
    ll x,y;
    tie(x,y) = dfs1(g, dp, m, to, i);
    already += x + y;
    already %= m;
    now *= y + 1;
    now %= m;
  }
  dp[i] = make_tuple(already, now);
  return make_tuple(already, now);
}

void dfs2(const vector<vecint>& g, vector<T>& dp, vecll& ans, ll alp, ll nwp, ll m, int i, int p=-1) {
  ll already = alp;
  int n=g[i].size();
  vecll tmp1, tmp2;
  tmp1.push_back((alp + nwp) % m);
  tmp2.push_back((nwp + 1) % m);
  for(int j=n-1; j>=0; --j) {
    int to = g[i][j];
    if(to == p) continue;
    ll alc, nwc;
    tie(alc, nwc) = dp[to];
    already += alc;
    already %= m;
    ll nx1 = (tmp1.back() + (alc + nwc)) % m;
    tmp1.push_back(nx1);
    ll nx2 = tmp2.back() * (nwc + 1) % m;
    tmp2.push_back(nx2);
  }
  tmp1.pop_back();
  tmp2.pop_back();
  boost::reverse(tmp1);
  boost::reverse(tmp2);
  ll res = alp + nwp;
  ll ppal = 0;
  ll ppnw = 1;
  int cnt=0;
  for(auto&& j:irange(0,n)) {
    int to = g[i][j];
    if(to == p) continue;
    ll alc, nwc;
    tie(alc, nwc) = dp[to];
    ll tmp = (alc + nwc) % m;
    res += tmp;
    res %= m;
    ll alx = (ppal + tmp1[cnt]) % m;
    ll nwx = ppnw * tmp2[cnt] % m;
    dfs2(g, dp, ans, alx, nwx, m, to, i);
    ppal += alc + nwc;
    ppal %= m;
    ppnw *= nwc + 1;
    ppnw %= m;
    ++cnt;
  }
  ans[i] = res;
}

int main()
{
  ll n,m;
  cin>>n>>m;
  vector<vecint> g(n);
  for(auto&& i:irange(0l,n-1)) {
    int x,y;
    cin>>x>>y;
    --x;--y;
    g[x].push_back(y);
    g[y].push_back(x);
  }
  vector<T> dp1(n);
  ll x,y;
  tie(x,y) = dfs1(g, dp1, m, 0);
  vecll dp2(n);
  dfs2(g, dp1, dp2, 0, 0, m, 0);
  ll total = (x+y) % m;
  for(auto&& e:dp2) {
    cout<<(total+m-e)%m<<endl;
  }
  return 0;
}

