void dfs2(int c,int p=-1){//木DPした結果から計算
	ans[c] = 1;
	for(auto to:G[c]) ( ans[c] *= dp[to]+1LL ) %= M;

	int n = G[c].size();
	vector<ll> l(n),r(n);
	for(int i=0;i<n;i++) l[i] = r[i] = ( dp[G[c][i]] + 1LL ) % M;
	for(int i=1;i<n;i++) ( l[i] *= l[i-1] ) %= M;
