            p = merge(p, pref[a][i -1]);
        }
        if(i != downs[a].size() - 1){
            p = merge(p, suf[a][i + 1]);
        }
        if(a != 1){
            p = merge(p, up[a]);
        }
        int b = children[a][i];
        up[b] = process(p);
        dfsTwo(b, a);
    }
}



