inline void add(int u,int v) 
{
    to[tot]=v;
    nxt[tot]=first[u];
    first[u]=tot++;
    to[tot]=u;
    nxt[tot]=first[v];
    first[v]=tot++;
}
void dfs(int root,int fa) 
{
    int tot=0;
    f[root]++;
    for(int i=first[root];i;i=nxt[i])
    {
        if(to[i]!=fa) 
        {
            dfs(to[i],root);
            f[root]=f[root]*f[to[i]]%m;
        }
    }
    for(int i=first[root];i;i=nxt[i]) 
    	if(to[i]!=fa) 
    		p[++tot]=to[i];
    f[root]++;f[root]%=m;
    pr[0]=su[tot+1]=1;
    for(int i=1;i<=tot;i++) 
    	pr[i]=pr[i-1]*f[p[i]]%m;
    for(int i=tot;i>=1;i--) 
    	su[i]=su[i+1]*f[p[i]]%m;
    for(int i=1;i<=tot;i++) 
    	g[p[i]]=pr[i-1]*su[i+1]%m;
}
void dfs2(int root,int fa) 
{
    if(root==1) 
    	ans[root]=1;
    else 
    	ans[root]=(g[root]*ans[fa]+1)%m;
