	cin >> n >> m;
	for (int i = 0; i < n - 1; i++) {
		int a, b;
		cin >> a >> b;
		a--;
		b--;
		t[b].push_back(a);
		t[a].push_back(b);
	}
	rec(0, -1);
	solve(0, -1, 0);
	for (int i = 0; i < n; i++) {
		printf("%lld\n", ans[i]);
	}
	return 0;
}

