int n, MOD, up[N];
vector <int> q[N];
map <int, int> p[N], s[N];

void dfs(int v, int par) {
    int x = 0;
    p[v][0] = 1;
    for (auto i : q[v]) {
        if (i == par) {
            continue;
        }
        dfs(i, v);
        x++;
        int t = sz(q[i]) - 1;
        p[v][x] = p[v][x - 1] * (p[i][t] + 1) % MOD;
    }
    s[v][x + 1] = 1;
    for (int i = sz(q[v]) - 1; i >= 0; i--) {
        int to = q[v][i];
        if (to == par) {
            continue;
        }
        int t = sz(q[to]) - 1;
        s[v][x] = s[v][x + 1] * (p[to][t] + 1) % MOD;
        x--;
    }
}

void calc(int v, int par) {
    int x = 0;
    for (auto i : q[v]) {
        if (i == par) {
            continue;
        }
        x++;
        int t = sz(q[i]) - 1;
        int tmp = p[v][x - 1] * s[v][x + 1] % MOD;
        up[i] = (up[v] * tmp % MOD + 1) % MOD;
        calc(i, v);
    }
}

