void DFS(int u)
{
    int top=0;
    f[u].back()=1;
    for (int v:adj[u]) {
        if (par[u]==v) continue;
        ++top;
        id[v]=top;
        par[v]=u;
        DFS(v);
        f[u].back()=f[u].back()*(f[v].back()+1) mod base;
    }
    top=0;
    for (int v:adj[u]) if (par[v]==u){
        st[++top]=f[v].back()+1;
    }
    L[0]=R[top+1]=1;
    FOR(i,1,top)
        L[i]=L[i-1]*st[i] mod base;
    FORR(i,top,1) {
        f[u][i]=L[i-1]*R[i+1] mod base;
        R[i]=R[i+1]*st[i] mod base;
    }
}
void GetRes(int u)
{
    int tmp=1;
    if (u!=1) {
        int pos=id[u];
        tmp=(f[par[u]][pos]+1) mod base;
        f[u].back()=f[u].back()*tmp mod base;
