void dp_dfs(ll u, ll par){
    if(par>0){
        dp[u] = (a[u] * ((a[par]/a[u]+1)%m))%m;
    }else{
        dp[u] = a[u];
    }
    for(auto & to : tree[u]){
        if(to!=par){
            dp_dfs(to,u);
        }
    }
}

