    vector<ll> l(n), r(n);

    for (int i = 0; i < n; i++) {
        l[i] = r[i] = (dp[v][i] + 1) % M;
    }

    for (int i = 1; i < n; i++) {
        l[i] *= l[i - 1];
        l[i] %= M;
    }
    for (int i = n - 2; i >= 0; i--) {
        r[i] *= r[i + 1];
        r[i] %= M;
    }

    for (int i = 0; i < n; i++) {
        int nv = G[v][i];
        if (nv == p) continue;

        ll dp_v = 1;
        if (i != 0) {
            dp_v *= l[i - 1];
            dp_v %= M;
        }
        if (i != n - 1) {
            dp_v *= r[i + 1];
            dp_v %= M;
        }
        dfs2(nv, v, dp_v);

