        }
    }
    for (int i = n - 1; i >= 0; i--) {
        int v = tree[u][i];
        if (v == p) {
            if (i == n - 1) {
                R[u].push_back(1);
            } else {
                R[u].push_back(R[u].back());
            }
        }
        if (R[u].size() == 0) {
            R[u].push_back(dp[v] + 1);
        } else {
