    int res = 1;
    for (auto v: adj[u]) {
        if (v == p) continue;
        dp[u][v] = dfs1(dp, adj, M, v, u) + 1;
        res = (res * dp[u][v]) % M;
    }
    return res;
}

void dfs2(VVLL &dp, VVI &adj, VLL &res, int M, int u, int p) {
    int n = adj[u].size();
    VLL back(n, 1);
    for (int i = n - 1; i >= 0; i--) {
        int v = adj[u][i];
        back[i-1] = (back[i] * dp[u][v]) % M;
    }
    LL acc = 1;
    for (int i = 0; i < n; i++) {
        int v = adj[u][i];
        dp[v][u] = (acc * back[i] + 1) % M;
        if (v != p)
            dfs2(dp, adj, res, M, v, u);
        acc = (acc * dp[u][v]) % M;
    }

    res[u] = acc;
}

