void dfs2(int u, int p)
{
	int len = tree[u].size();
	ll left[len], right[len];
	for (int i = 0; i < len; i++)
	{
		int v = tree[u][i];
		left[i] = (i == 0) ? ((1 + in[v]) % m) : ((left[i - 1] * ((1 + in[v]) % m)) % m);
	}
	for (int i = len - 1; i >= 0; i--)
	{
		int v = tree[u][i];
		right[i] = (i == len - 1) ? ((1 + in[v]) % m) : ((((1 + in[v]) % m) * right[i + 1]) % m);
	}
	//cout << u << " " << len << endl;
