template <typename Monoid >
struct SegmentTree{
  using F = function< Monoid(Monoid,Monoid) >;

  int sz;
  vector<Monoid> seg;

  const F f;
  const Monoid M;

  SegmentTree(int n,const F f,const Monoid &M) : f(f),M(M){
    sz = 1;
    while(sz<n) sz<<=1;
    seg.assign(sz*2,M);
  }
  void set(int k,const Monoid &v){
    seg[k+sz] = v;
  }
  void build(){
    for(int k=sz-1;k>0;k--){
      seg[k] = f(seg[2*k],seg[2*k+1]);
    }
  }
  void update(int k,const Monoid &v){
    k += sz;
    seg[k] = v;
    while(k >>= 1){
      seg[k] = f(seg[2*k],seg[2*k+1]);
    }
  }
  Monoid que(int a,int b){
    Monoid L=M,R=M;
    for(a+=sz, b+=sz;a<b;a>>=1,b>>=1){
      if(a&1) L = f(L,seg[a++]);
      if(b&1) R = f(seg[--b],R);
    }
    return f(L,R);
  }
  Monoid operator[](const int &k) const{
    return seg[k+sz];
  }
};
vector<vector<ll>> dp(MAX,vector<ll>(2,0));
vector<vector<ll>> G(MAX);
vector<ll> ans(MAX);
ll dfs(ll v,ll c,ll pre){
  ll res = 1;
  for(auto nv:G[v]){
    ll tmp = 0;
    if(nv==pre) continue;
    tmp += dfs(nv,1,v);
    if(c==0){
      tmp += dfs(nv,0,v);
    }
    tmp %= MOD;
    res = (res*tmp)%MOD;
  }
  return dp[v][c] = res;
}
void solve(ll v,ll pre){
  ll m = G[v].size();
  SegmentTree<ll> seg0(m,[&](ll x,ll y){return (x*y)%MOD;},1);
  SegmentTree<ll> seg1(m,[&](ll x,ll y){return (x*y)%MOD;},1);
  ll now_0 = dp[v][0],now_1 = dp[v][1];
  dp[v][0] = dp[v][1] = 1;
  for(ll i=0;i<m;i++){
    dp[v][0] = (dp[v][0] * (dp[G[v][i]][0] + dp[G[v][i]][1])) % MOD;
    dp[v][1] = (dp[v][1] * dp[G[v][i]][1]) % MOD;
    seg0.update(i,(dp[G[v][i]][0] + dp[G[v][i]][1]) % MOD);
    seg1.update(i,(dp[G[v][i]][1]) % MOD);
  }
  ans[v] = dp[v][0];
  for(ll i=0;i<m;i++){
    ll nv = G[v][i];
    if(nv==pre) continue;
    ll pre0=dp[v][0],pre1=dp[v][1];
    dp[v][0] = dp[v][1] = 1;

    dp[v][0] = (dp[v][0]*seg0.que(0,i))%MOD;
    dp[v][1] = (dp[v][1]*seg1.que(0,i))%MOD;


