      dp[v][0] = (dp[v][0]*seg0.que(i+1,m))%MOD;
      dp[v][1] = (dp[v][1]*seg1.que(i+1,m))%MOD;
    }
    solve(nv,v);
    dp[v][0] = pre0;
    dp[v][1] = pre1;
  }
  dp[v][0] = now_0;
  dp[v][1] = now_1;
}
