            revp[v][i] = multiply(revp[v][i+1], dp[to] + 1);
        else
            revp[v][i] = revp[v][i+1];
    }
    for(int i = 0; i < g[v].size(); ++i) {
        int to = g[v][i];
        if(to != par)
            exc[to] = multiply(i ? p[v][i-1] : 1, revp[v][i+1]);
