  id.resize(N);
  lpMemo.resize(N), rpMemo.resize(N);

  auto addEdge = [&](int u, int v) {
    id[u][v] = G[u].size();
    G[u].push_back(v);
  };

  rep(i, N - 1) {
    int x, y;
