sll extGCD(sll a,sll b,sll &x,sll &y)
{
  if(b==0)
  {
    x=1;
    y=0;
    return a;
  }
  sll d = extGCD(b,a%b,y,x);
  y-=a/b*x;
  return d;
}

// n_gcd/a(mod M)を計算する
ull div(ull n_gcd,ull a)
{
  sll x,y;
  sll gcd = extGCD((sll)a,(sll)M,x,y);
  //ax+My=gcd(a,M)
  if(n_gcd!=gcd)return INF;//不定性があるので決定しない
  //ax==n_gcd(mod M)
  while(x<0)
  {
    x += M;
  }
  return x%M;
}

ull calc_comb_R(int idx);
ull calc_comb_L(int idx)
{
  if(comb_L[idx]==INF)
  {
    comb_L[idx] = 1;
    int point = edge[idx].first;
    if(comb[point]!=INF&&comb_R[idx]!=INF
      &&comb[point]!=0&&comb_R[idx]!=0)
    {
      comb_L[idx] = div(comb[point],comb_R[idx]);
      if(comb_L[idx]==INF)
      {
        comb_L[idx]=1;
      }
      else
      {
        comb_L[idx] = (comb_L[idx]+1)%M;
        return comb_L[idx];
      }
    }
    for(ull j=0;j<edge_idx[point].size();++j)
    {
      if(edge_idx[point][j]==idx)continue;
      if(edge[edge_idx[point][j]].first==point)
      {
        comb_L[idx] = (comb_L[idx]*calc_comb_R(edge_idx[point][j]))%M;
      }
      else
      {
        comb_L[idx] = (comb_L[idx]*calc_comb_L(edge_idx[point][j]))%M;
      }
      if(comb_L[idx]==0)
      {
        break;
      }
    }
    comb_L[idx] = (comb_L[idx]+1)%M;
    if(comb_R[idx]!=INF)
    {
      comb[point]=((comb_L[idx]+M-1)*comb_R[idx])%M;
    }
    if(comb[point]!=INF&&comb[point]!=0
       &&comb_L[idx]!=1)
    {
      comb_R[idx]=div(comb[point],(comb_L[idx]+M-1)%M);
    }
  }
  return comb_L[idx];
}
ull calc_comb_R(int idx)
{
  if(comb_R[idx]==INF)
  {
    comb_R[idx] = 1;
    int point = edge[idx].second;
    if(comb[point]!=INF&&comb_L[idx]!=INF
      &&comb[point]!=0&&comb_L[idx]!=0)
    {
      comb_R[idx] = div(comb[point],comb_L[idx]);
      if(comb_R[idx]==INF)
      {
        comb_R[idx]=1;
      }
      else
      {
        comb_R[idx] = (comb_R[idx]+1)%M;
        return comb_R[idx];
      }
    }
    for(ull j=0;j<edge_idx[point].size();++j)
    {
      if(edge_idx[point][j]==idx)continue;
      if(edge[edge_idx[point][j]].first==point)
      {
        comb_R[idx] = (comb_R[idx]*calc_comb_R(edge_idx[point][j]))%M;
      }
      else
      {
        comb_R[idx] = (comb_R[idx]*calc_comb_L(edge_idx[point][j]))%M;
      }
      if(comb_R[idx]==0)
      {
        break;
      }
    }
    comb_R[idx] = (comb_R[idx]+1)%M;
    if(comb_L[idx]!=INF)
    {
      comb[point]=((comb_R[idx]+M-1)*comb_L[idx])%M;
    }
    if(comb[point]!=INF&&comb[point]!=0
       &&comb_R[idx]!=1)
    {
      comb_L[idx]=div(comb[point],(comb_R[idx]+M-1)%M);
    }
  }
  return comb_R[idx];
}

int main()
{
  ull i,j,k,N;
  int x,y;
  cin >> N >> M;
  edge_idx.resize(N);
  comb_L.resize(N-1,INF);
  comb_R.resize(N-1,INF);
  comb.resize(N,INF);
  for(i=0;i<N-1;++i)
  {
    cin >> x >> y;
    edge.push_back(make_pair(x-1,y-1));
    edge_idx[x-1].push_back(i);
    edge_idx[y-1].push_back(i);
  }

  for(i=0;i<N;++i)
  {
    if(comb[i]==INF)
    {
      comb[i] = 1;
      for(j=0;j<edge_idx[i].size();++j)
      {
        if(edge[edge_idx[i][j]].first==i)
        {
          if(comb_L[edge_idx[i][j]]!=INF)
          {
            comb[i] = ((comb_L[edge_idx[i][j]]+M-1)*calc_comb_R(edge_idx[i][j]))%M;
            break;
          }
          else if(j+1==edge_idx[i].size())
          {
            comb_L[edge_idx[i][j]] = (comb[i]+1)%M;
          }
          comb[i] = (comb[i]*calc_comb_R(edge_idx[i][j]))%M;
        }
        else
        {
          if(comb_R[edge_idx[i][j]]!=INF)
          {
            comb[i] = ((comb_R[edge_idx[i][j]]+M-1)*calc_comb_L(edge_idx[i][j]))%M;
            break;
          }
          else if(j+1==edge_idx[i].size())
          {
            comb_R[edge_idx[i][j]] = (comb[i]+1)%M;
          }
          comb[i] = (comb[i]*calc_comb_L(edge_idx[i][j]))%M;
        }
        if(comb[i]==0)
        {
          //0~jの積でMの倍数になったので残りのエッジの逆は全て1
          for(k=j+1;k<edge_idx[i].size();++k)
          {
            if(edge[edge_idx[i][k]].first==i)
            {
              comb_L[edge_idx[i][k]] = 1;
            }
            else
            {
              comb_R[edge_idx[i][k]] = 1;
            }
          }
          //jはMの約数なので先頭に持ってきておいてもう一度計算する時に0になりやすくなるようにする
          if(j)
          {
            int k_idx=edge_idx[i][j];
            for(ull k=j;k>0;--k)
            {
              edge_idx[i][k]=edge_idx[i][k-1];
            }
            edge_idx[i][0]=k_idx;
          }
          break;
        }
      }
    }
    cout << comb[i] << endl;
  }

  return 0;
}

