ll mod;
ll parent[1000001];
ll pparent[1000001];
void dfs(ll u,ll par)
{
    dp[u] = 1;
    ll i;
    vi pref;
    vi suff;
    for(i=0;i<arr[u].size();i++)
    {
        ll v = arr[u][i];
        if(v!=par)
        {
            dfs(v,u);
            dp[u] = (dp[v]+1)*dp[u]%mod;
            pref.pb(dp[v]+1);
            suff.pb(dp[v]+1);
        }
    }
    for(i=1;i<pref.size();i++)
    {
        pref[i] = (pref[i]*pref[i-1])%mod;
    }
    for(i=int(suff.size())-2;i>=0;i--)
    {
        suff[i] = (suff[i]*suff[i+1])%mod;
    }
    ll prev = 0;
    for(i=0;i<arr[u].size();i++)
    {
        ll v = arr[u][i];
        if(v!=par)
        {
            if(prev-1<0 and prev+1>=suff.size())
                continue;
            else if(prev-1<0)
                parent[v] = suff[prev+1];
            else if(prev+1>=suff.size())
                parent[v] = pref[prev-1];
            else
                parent[v] = (suff[prev+1]*pref[prev-1])%mod;
            prev++;
        }
    }
}
void dfs1(ll u,ll par)
{

    ll i;
    for(i=0;i<arr[u].size();i++)
    {
        ll v = arr[u][i];
        if(v!=par)
        {
            pparent[v] = ((1+pparent[u])*max(1LL,parent[v]))%mod;
            dfs1(v,u);
        }
    }
}
