long long dfsDown(int root, int m) {
    long long temp = 1;
    for(int node: v[root]) {
        if (fatherOf[root] == node) {
            continue;
        }
        fatherOf[node] = root;
        temp = temp * (1+dfsDown(node, m));
    }
    down[root] = temp;
    return down[root];
}

