const int MAXN = 1e5+5;
int dp[MAXN],prop[MAXN],m;
vector<int> adj[MAXN], child[MAXN];
vector<int> pmul[MAXN], smul[MAXN];
int madd (int a, int b) {
  int sum = a + b;
  return sum >= m ? sum-m : sum;
}
void self_madd (int &a, int b) {
  a = madd(a,b);
}
int mmult (int a, int b) {
  ll prod = (ll)a*b;
  return prod >= m ? prod%m : prod;
}
void self_mmult (int &a, int b) {
  a = mmult(a,b);
}
void dfs (int cur, int p) {
  dp[cur] = 1; prop[cur] = 1;
  for (int i : adj[cur]) if (i != p){
    dfs(i,cur);
    child[cur].push_back(i);
    self_mmult(dp[cur],dp[i]+1);
    pmul[cur].push_back(dp[cur]);
  }
  int temp = 1; smul[cur].resize(child[cur].size());
  for (int i = child[cur].size()-1; i >= 0; i--) {
    self_mmult(temp,dp[child[cur][i]]+1);
    smul[cur][i] = temp;
  }
}
int dv (int cur, int i) {
  return madd(mmult(mmult(prop[cur],(i ? pmul[cur][i-1] : 1)),(i == child[cur].size()-1 ? 1 : smul[cur][i+1])),1); //sketchy
}
void dfs2(int cur, int p) {
  for (int i = 0; i < child[cur].size(); i++) {
    int mul = dv(cur,i);
    self_mmult(dp[child[cur][i]],mul);
    self_mmult(prop[child[cur][i]],mul);
    dfs2(child[cur][i],cur);
  }
}
