vector<ll> dp[MAX_V], pL[MAX_V], pR[MAX_V];

//dfs1(v,i)+1の積 (kを除く)
inline ll prod(int v, int k)
{
  return pL[v][k] * pR[v][k + 1] % m;
}

//上から下
ll dfs1(int p, int v)
{
  ll res = 1;
  rep(i, E[v].size())
  {
    if (E[v][i] == p)
      continue;
    dp[v][i] = dfs1(v, E[v][i]);
    res *= (dp[v][i] + 1);
    res %= m;
  }

  //左右からの累積積を作っておく

  pL[v][0] = 1;
  rep(i, E[v].size())
  {
    if (E[v][i] == p)
      pL[v][i + 1] = pL[v][i];
    else
      pL[v][i + 1] = pL[v][i] * (dp[v][i] + 1) % m;
  }
  pR[v][E[v].size()] = 1;
  for (int i = E[v].size(); i > 0; --i)
  {
    if (E[v][i] == p)
      pR[v][i - 1] = pR[v][i];
    else
      pR[v][i - 1] = pR[v][i] * (dp[v][i - 1] + 1) % m;
  }

  return res;
}

//下から上
void dfs2(int p, int v, ll add)
{
  //上から持ってきた値を清算
  rep(i, E[v].size())
  {
    if (E[v][i] == p)
    {
      dp[v][i] = add;
      break;
    }
  }

  rep(i, E[v].size())
  {
    if (E[v][i] == p)
      continue;
    dfs2(v, E[v][i], prod(v, i) * (add + 1) % m);
  }
}

