ll n, m;
//dp...各ノードが黒の場合の組み合わせ数
vector<ll> dp;
vector<vector<int>> graph;

ll dfs(int c, int p) {
	ll s = 1;
	for (auto e : graph[c]) {
		if (e == p) continue;
		ll v = dfs(e, c) + 1;
		s *= v;
		s %= m;
	}
	dp[c] = s;
	return dp[c];
}

void dfs2(int c, int p, ll r) {

	//親の組み合わせ分だけかける
	dp[c] *= r + 1;
	dp[c] %= m;

	//dpには親以外の全組み合わせの積が入っている
	//親のdp[p]=r
	//foreach 子の dpを取得
	int edges = graph[c].size();
	vector<ll> pos(edges, 0);
	vector<ll> neg(edges, 0);
	//全ノードの現在の組み合わせ数を取得
	for (int i = 0; i < edges; i++) {
		if (graph[c][i] == p) {
			pos[i] = neg[i] = (r + 1) % m;
		}
		else {
			pos[i] = neg[i] = dp[graph[c][i]] + 1;
		}
	}
	//累積積を計算
	for (int i = 0; i < edges-1; i++) {
		(pos[i + 1] *= pos[i]) %= m;
		(neg[edges - i - 2] *= neg[edges - i - 1]) %= m;
	}

	for (int i = 0; i < edges; i++) {
		if (graph[c][i] == p) continue;
		ll cr = 1;
		if (i > 0) cr *= pos[i - 1];
		if (i < edges - 1) cr *= neg[i + 1];
		cr %= m;
		dfs2(graph[c][i], c, cr);
	}
}

int main() {
