	graph.resize(n);
	rep(i, n - 1) {
		int x, y;
		cin >> x >> y;
		x--; y--;
		graph[x].push_back(y);
		graph[y].push_back(x);
	}
	dp.resize(n, 0);
	dfs(0, -1);
	dfs2(0, -1, 0);
	rep(i, n) {
		cout << dp[i] << endl;
	}
	return 0;
}

