using namespace std;
typedef long long ll;

int V, Mod;
vector<vector<int>*> *es;
vector<int> *par;
vector<ll> *dp0, *dp1;

void dfs1(int u, int p)
{
	par->at(u) = p;
	es->at(u)->erase(find(es->at(u)->begin(), es->at(u)->end(), p));
	for (auto v : *(es->at(u))) dfs1(v, u);
}
ll dfs2(int u)
{
	dp0->at(u) = 1L;
	for (auto v : *(es->at(u))) dp0->at(u) = dp0->at(u) * (dfs2(v) + 1) % Mod;
	return dp0->at(u);
}
void dfs3(int u)
{
	auto W = es->at(u)->size();
	auto x = new vector<ll>(W + 1, 1); // x[i] = t[0]*...*t[i-1], x[i+1]=x[i]*t[i]
	auto y = new vector<ll>(W + 1, 1); // y[i] = t[i]*...*t[W-1], y[i]=y[i+1]*t[i]
	for (int i = 0; i < W; i++) x->at(i + 1) = x->at(i) * (dp0->at(es->at(u)->at(i)) + 1) % Mod;
	for (int i = W - 1; i >= 0; i--) y->at(i) = y->at(i + 1) * (dp0->at(es->at(u)->at(i)) + 1) % Mod;
	for (int i = 0; i < W; i++) dp1->at(es->at(u)->at(i)) = (dp1->at(u) + 1) * x->at(i) % Mod * y->at(i + 1) % Mod;
	for (int v : *(es->at(u))) dfs3(v);
}

int main()
{
	cin.tie(0);
	ios::sync_with_stdio(false);
	cin >> V >> Mod;
	es = new vector<vector<int>*>();
	par = new vector<int>(V, 0);
	dp0 = new vector<ll>(V, 0);
	dp1 = new vector<ll>(V, 0);
	for (size_t i = 0; i < V; i++) es->at(i) = new vector<int>();
	for (size_t i = 0; i < V - 1; i++)
	{
		int x, y; cin >> x >> y;
		es->at(x - 1)->push_back(y - 1);
		es->at(y - 1)->push_back(x - 1);
	}
	dfs1(0, -1);
	dfs2(0);
	dfs3(0);
	for (size_t u = 0; u < V; u++) cout << dp0->at(u) * (dp1->at(u) + 1) % Mod << endl;
    return 0;
}

