const int MAX_N = 100005; /* to be set */

ll m;

struct dataset {
    ll dp;
    dataset(ll dp = 1) : dp(dp) {}
    dataset operator+ (const dataset& a) const { /* merge nodes */
        return dataset((dp % m)*((a.dp) % m) % m);
    }
    dataset addRoot() const { /* include parent */
        return dataset((dp + 1) % m);
    }
};

vector<int> g[MAX_N];
vector<dataset> dp[MAX_N];
dataset ans[MAX_N];

dataset dfs1(int v, int p = -1) {
    dataset dpsum;
    dp[v] = vector<dataset> (g[v].size());

    rep(i, g[v].size()) {
        int u = g[v][i];
        if(u == p) continue;
        dp[v][i] = dfs1(u, v);
        dpsum = dpsum + dp[v][i];
    }
    return dpsum.addRoot();
}

void dfs2(int v, const dataset& dpParent = dataset(), int p = -1) {
    int deg = g[v].size();
    rep(i, deg) if(g[v][i] == p) dp[v][i] = dpParent;

    vector<dataset> dpSum_Left(deg+1), dpSum_Right(deg+1);
    rep(i,deg) dpSum_Left[i+1] = dpSum_Left[i] + dp[v][i];
    rrep(i, deg) dpSum_Right[i] = dpSum_Right[i+1] + dp[v][i];

    ans[v] = dpSum_Left[deg].addRoot();

    rep(i,deg) {
        int u = g[v][i];
        if(u == p) continue;
        dataset d = dpSum_Left[i] + dpSum_Right[i+1];
        dfs2(u, d.addRoot(), v);
    }
}

