using namespace std;

int n;

ll m;

vector <int> edges[N_MAX];

vector <int> sons[N_MAX];

bool visited[N_MAX];

void dfs (int node)
{
    visited[node] = true;
    for(int u : edges[node])
        if(visited[u] == false)
        {
            sons[node].push_back(u);
            dfs(u);
        }
}

ll up[N_MAX], down[N_MAX];

void computeDown (int node)
{
    down[node] = 1;
    for(int u : sons[node])
    {
        computeDown(u);
        down[node] = down[node] * (down[u] + 1) % m;
    }
}

void computeUp (int node)
{
    up[node] = (up[node] + 1) % m;
    ll pre = 1;
    for(auto u : sons[node])
    {
        up[u] = up[u] * pre % m;
        pre = pre * (down[u] + 1) % m;
    }
    reverse(sons[node].begin(), sons[node].end());
    ll suf = 1;
    for(auto u : sons[node])
    {
        up[u] = up[u] * suf % m;
        up[u] = up[u] * up[node] % m;
        suf = suf * (down[u] + 1) % m;
    }
    for(auto u : sons[node])
        computeUp(u);
}

