int dpin[N], dpout[N];
int n;

void dfs1(int u, int p){
	dpin[u] = 1;	
	for (int v : gr[u]){
		if (v != p){
			dfs1(v, u);
			dpin[u] = mul(dpin[u], add(dpin[v], 1)); 
		}
	}
}

int dfs2(int u, int p){
	if (!p)
		dpout[u] = 0;
	vi black;
	for (int v : gr[u]){
		if (v != p){
			black.pb(1+dpin[v]);
		}
	}
	vector<int> pref;
	deque<int> suff;
	int m = sz(black);
	int curr = 1;
	rep(i, m){
		curr = mul(curr, black[i]);
		pref.pb(curr); 
	}
	curr = 1;
	RF(i, m-1, 0){
		curr = mul(curr, black[i]);
		suff.pf(curr);
	}
	int idx = 0;
	for (int v : gr[u]){
		if (v != p){
			int pre = (idx == 0) ? 1: pref[idx-1];
			int suf = (idx == m-1) ? 1 : suff[idx+1];
			dpout[v] = mul(dpout[u]+1, pre);
			dpout[v] = mul(dpout[v], suf);
			dfs2(v, u);
			idx++;
		}
	}
}

