		add_edge(a,b);
		add_edge(b,a);
	}
	dfs1(1,0);
	dfs2(1,0);
	for(LL i = 1;i <= n;i ++) printf("%lld\n",ans[i] * (dp[i] - 1 + N) % N);
	return 0;
}

