void dfs(int s,int f)
{
    dp[s]=1;
    for(int i=0; i<v2[s].size(); ++i)
        if(v2[s][i]!=f)
        {
            dfs(v2[s][i],s);
            dp[s]=dp[s]*(dp[v2[s][i]]+1)%m;
        }
}

void dfs2(int s,int f,ll now)
{
    ll pre[v2[s].size()];
    ll nxt[v2[s].size()];
    for(int i=(int)v2[s].size()-1; i>=0; --i)
    {
        if(v2[s][i]!=f) nxt[i]=dp[v2[s][i]]+1;
        else nxt[i]=now;
        if(i+1<v2[s].size()) nxt[i]=nxt[i]*nxt[i+1]%m;
    }
    ll ans=now;
    for(int i=0; i<v2[s].size(); ++i)
    {
        if(v2[s][i]!=f)
        {
            if(v2[s].size()!=1){
                pre[i]=dp[v2[s][i]]+1;
                if(i==0) ans=(nxt[i+1]+1)%m;
                else{
                    pre[i]=pre[i]*pre[i-1]%m;
                    if(i+1==v2[s].size()) ans=(pre[i-1]+1)%m;
                    else ans=(pre[i-1]*nxt[i+1]+1)%m;
                }
            }
            dp[v2[s][i]]=dp[v2[s][i]]*ans%m;
            dfs2(v2[s][i],s,ans);
        }
        else pre[i]=i?now+pre[i-1]:now;
    }
}

