void calc(int u, int p){
  dp[u] = 1;
  for(int v: g[u]){
    if(v== p) continue;
    calc(v,u);
    dp[u] = (1LL*dp[u]*(dp[v]+1));
  }
}


void change_root(int r, int v){
  ll dpr = dp[r], dpv = dp[v];
  dpr = dpr/(dp[v]+1);
  dp[v] = (dp[v]*(dpr+1))%m;

//  (dp[v]*(dpr+1)
}


void dfs(int u, int p){
  for(int v: g[u]){
    if(v== p) continue;
    change_root(u, v);
    dfs(v,u);
  }
}




