void dfs2(int v,int p){
    int sz=g[v].size();
    vector<ll> l(sz),r(sz);
    rep(i,sz){
        l[i]=dp[g[v][i]]+1;
        r[i]=l[i];
    }
    rep(i,sz-1) l[i+1]*=l[i],l[i+1]%=M;
