ll m;

ll dfs(ll node, ll edge){//nodeへ辺edgeを通して至る
  bool dir = (edges[edge].second == node); //正方向かどうか
  if(dir){
    if(dp1[edge]!=-1) return dp1[edge];
    if(connected[node].size()==1) return dp1[edge] = 2;
    ll res = 1;
    for(ll k: connected[node]){
      if(k==edge) continue;
      res *= (edges[k].first==node) ? dfs(edges[k].second,k) : dfs(edges[k].first,k), res %= m;
    }
    res++, res %= m;
    return dp1[edge] = res;
  }else{
    if(dp2[edge]!=-1) return dp2[edge];
    if(connected[node].size()==1) return dp2[edge] = 2;
    ll res = 1;
    for(ll k: connected[node]){
      if(k==edge) continue;
      res *= (edges[k].first==node) ? dfs(edges[k].second,k) : dfs(edges[k].first,k), res %= m;
    }
    res++, res %= m;
    return dp2[edge] = res;
  }
}

