void dfs2(int v,int pre,Mint coeff){
    ans[v]=dp[v]*coeff;
    vector<Mint> dps;
    for(int to:g[v])if(to!=pre)dps.push_back(dp[to]+1);
    dps.push_back(coeff);
    vector<Mint> l(dps.size()+1,1),r(dps.size()+1,1);
