//    cout << endl;

    int m = children.size();

    vector<ll> prefix(m), suffix(m);
    for(int i = 0; i < m; i++) {
        int v = children[i];
        prefix[i] = ((in[v] + 1) * (i > 0 ? prefix[i - 1] : 1)) % mod;
        prefix[i] %= mod;
//        cout << prefix[i] << " ";
    }
//    cout << endl;
    for(int i = m - 1; i >= 0; i--) {
        int v = children[i];
        suffix[i] = ((in[v] + 1) * (i < m - 1 ? suffix[i + 1] : 1)) % mod;
        suffix[i] %= mod;
