    int nxt = tr[now][i];
    if(nxt == prev) continue;
    dfs1(nxt, now, tr);
  }
  for(int i=0;i<SZ(tr[now]);++i) {
    int nxt = tr[now][i];
    if(nxt == prev) continue;
    cntb[now] *= (cntb[nxt] + 1);
