  ansb[now] = cntb[now] * (parb + 1) % MOD;
  answ[now] = (cntw[now] + (parb + parw)) % MOD;
  vll mull(SZ(tr[now])+2, 1), mulr(SZ(tr[now])+2, 1);
  for(int i=0;i<SZ(tr[now]);++i) {
