void dfs1(int v, int p) {
    parent[v] = p;
    dp1[v] = 1;
    FORE (x, G[v]) {
        if (x == p) continue;
        dfs1(x, v);
        (dp1[v] *= dp1[x]+1) %= MOD;
        child[v].push_back(x);
    }
}

void dfs2(int v) {
    dp2[v] = dp2[parent[v]];
    if (parent[v] != v) {
