void build(int s, int node, int l, int r)
{
   if(l > r)
      return ;

   if(l == r)
   {
      tree[s][node] = pre[s][l]+1;
      return;
   }

   int mid = (l+r)/2;
   build(s, 2*node, l, mid);
   build(s, 2*node+1, mid+1, r);
   tree[s][node] = (tree[s][2*node]*tree[s][2*node+1])%M;
}


void build_util(int s)
{
   int sz = pre[s].size();
   if(!sz) return ;
   tree[s].resize(4*sz, 1);
   build(s, 1, 0, sz-1);
}

int query(int s, int node, int st, int en, int l, int r)
{
   if(l > r)
      return 1;

   if(st > r || en < l)
      return 1;

   if(st >= l && en <= r)
      return tree[s][node];

   int mid = (st+en)/2;
   int p1 = query(s, 2*node, st, mid, l, r);
   int p2 = query(s, 2*node+1, mid+1, en, l, r);
   return (p1*p2)%M;
}


