         ways[s] = (ways[s]*(ways[adj[s][i]]+1))%M;
         pre[s].pb(ways[adj[s][i]]);
      }
   }
   build_util(s);
}

int cal_fun(int s, int par)
{
   bool is_par_done = false;
   for(int i=0;i<adj[s].size();i++)
   {
      if(adj[s][i] == par){ is_par_done = true; continue; }
      ans[s] = (ans[s]*(ways[adj[s][i]]+1))%M;
      int l1, r1, l2, r2;
      if(!is_par_done)
         l1 = 0, r1 = i-1, l2=i+1, r2 = (int)pre[s].size()-1;
      else l1 = 0, r1 = i-2, l2 = i, r2 = (int)pre[s].size()-1;
      ans[adj[s][i]] = (ways_up[s]+1)*((query(s, 1,  0, (int)pre[s].size()-1, l1, r1)*query(s,1, 0, (int)pre[s].size()-1, l2, r2))%M)%M+1;
      ways_up[adj[s][i]] = ans[adj[s][i]]-1;
      cal_fun(adj[s][i], s);
   }

}




