		int x, y;
		cin >> x >> y;
		x--; y--;
		G[x].push_back(y);
		G[y].push_back(x);
	}
	dfs(0, -1);
	dfs2(0, -1, 0);
	for (int i = 0; i < N; i++) cout << dp2[i] << endl;
}

