	REP(i, g[v].size()) {
		ll c = (g[v][i].cap + 1) % m;
		l[i + 1] = c * l[i] % m;
		c = (g[v][g[v].size() - 1 - i].cap + 1) % m;
		r[g[v].size() - i - 1] = c * r[g[v].size() - i] % m;
