const int N = 1e5+10;
vector<int> adj[N];
int waysSub[N], ways[N];
int n, mod;

void dfs(int node, int par) {
    for(int i = 0; i < (int)adj[node].size(); ++i) {
        if(adj[node][i] == par) {
            adj[node].erase(adj[node].begin()+i);
            break;
        }
    }
    waysSub[node] = 1;
    for(int to : adj[node]) {
        dfs(to, node);
        waysSub[node] *= waysSub[to]+1;
        waysSub[node] %= mod;
    }
}

void dfs2(int node, int currWays) {
    ways[node] = currWays*(waysSub[node])%mod;
    vector<int> prefix(adj[node].size());
    vector<int> suffix(adj[node].size());
    int prod = 1;
    for(int i = 0; i < (int)adj[node].size(); ++i) {
        const int to = adj[node][i];
        prod *= waysSub[to]+1;
        prod %= mod;
        prefix[i] = prod;
    }
    prod = 1;
    for(int i = (int)adj[node].size()-1; i >= 0; --i) {
        const int to = adj[node][i];
        prod *= waysSub[to]+1;
        prod %= mod;
        suffix[i] = prod;
    }
    for(int i = 0; i < (int)adj[node].size(); ++i) {
        const int to = adj[node][i];
        int currVal = 1;
        if(i) {
            currVal *= prefix[i-1];
            currVal %= mod;
        }
        if(i+1 < (int)adj[node].size()) {
            currVal *= suffix[i+1];
            currVal %= mod;
        }
        dfs2(to, (currWays*currVal+1)%mod);
    }
}

