void dfs1(int pos, int par){ 

  int product = 1LL;

  for(auto ne : to[pos] ){ 

    if( ne == par ){ continue;} 

    dfs1(ne,pos);

    product = (product*dp1[ne])%m;

  }

  dp1[pos] = (product+1)%m;
  return;
} 

void dfs2(int pos, int par){ 
  //posの子供たちについて考える

  if( par == -1 ){ dp2[pos] = 1LL; return;}

  int res = 1LL;

  int e = to[pos].size();

  vector<int> l_product(e,1);
  vector<int> r_product(e,1);

  for(int i = 0; i < e; i++){ 

    if( i-1  >= 0 ){ l_product[i] = l_product[i-1];}

    if( to[pos][i] == par ){ continue;} 

    l_product[i] = (l_product[i]*dp1[to[pos][i]]) % m;

  }

  for(int i = e-1; i >= 0; i--){ 

    if( i+1 < e ){ r_product[i] = r_product[i+1];}

    if( to[pos][i] == par ){ continue;} 

    r_product[i] = (r_product[i]*dp1[to[pos][i]])%m;

  }


  for(int i = 0; i < e; i++){ 

    int res = 1LL;

    if( to[pos][i] == par ){ continue;} 

    if( i-1 >= 0 ){ res *= l_product[i-1];}
    if( i+1 < e  ){ res *= r_product[i+1];}

    res %= m;

    res = ( res * dp2[pos] + 1 ) % m;

    dp2[to[pos][i]] = res;

    dfs2( to[pos][i],pos);

  }

 return ; 

}

