        else
            pr[t-1] = 1LL;
    }

    pl[0] %= m;
    pr[t-1] %= m;

    for(i=1;i<t;i++)
    {
        if(g[node][i] != par)
        {
            pl[i] = pl[i-1] * (f[g[node][i]]+1LL);
            pl[i] %= m;
        }
        else
            pl[i] = pl[i-1];
    }

    for(i=t-2;i>=0;i--)
    {
        if(g[node][i] != par)
        {
            pr[i] = pr[i+1] * (f[g[node][i]]+1LL);
            pr[i] %= m;
        }
        else
        {
            pr[i] = pr[i+1];
        }
