ll mod,n;
vector<vector<int>> g;
vector<ll> dp,par,ans;



ll dfs(int pre,int now){
    ll ret=1;
    for(auto to:g[now])if(to!=pre){
        par[to]=now;
        ret=ret*(1+dfs(now,to))%mod;
    }
    return dp[now]=ret;
}

void fill_dp(int now){
    // cout<<now<<" : "<<dp[now]<<endl;
    int m=(int)g[now].size();
    vector<ll> l(m),r(m);
    l[0]=dp[g[now][0]]+1;
    r[m-1]=dp[g[now][m-1]]+1;
    for(int i=1;i<m;i++) l[i]=l[i-1]*(dp[g[now][i]]+1)%mod;
    for(int i=m-2;i>=0;i--) r[i]=r[i+1]*(dp[g[now][i]]+1)%mod;
    ans[now]=1;
    for(auto to:g[now]) ans[now]=ans[now]*(dp[to]+1)%mod;
    rep(i,m)if(par[now]!=g[now][i]){
        dp[now]=1;
        if(i>0) dp[now]=dp[now]*l[i-1]%mod;
        if(i<m-1) dp[now]=dp[now]*r[i+1]%mod;
        fill_dp(g[now][i]);
    }
}

