#include <cassert>

#include <stdio.h>

using namespace std;

vector< vector<int> > adj;
vector< vector<int> > adj_count;
vector< long long > ans;
vector< bool > visited;


int M;

long long dfs1(int u) {
  // cout << "v1" << u << endl;
  visited[u] = true;
  long long a = 1;
  int c = 0;
  for (auto v: adj[u]) {
    // cout << "ds " << u << " " << v << endl;
    if (!visited[v]) {
      auto r = dfs1(v) + 1;
      a = (a * r) % M;
      adj_count[u][c] = r % M;
    }
    c++;
  }

  return a;
}

void dfs2(int u, long long father) {
  // cout << "v2 " << u << " " << father << endl;
  visited[u] = true;


  int le = adj[u].size();

  if (le==0) {
    ans[u] = 1;
    return;
  }

  vector<long long> l( le, 1 );
  vector<long long> r( le, 1 );
  vector<long long> f( le, 1 );

  for(auto i=0; i<le; i++) {
    auto v = adj[u][i];
    if (visited[v]) adj_count[u][i] = father+1;
    // cout << "ac " << adj_count[u][i] << endl;

    if (i>0) 
      l[i] = (l[i-1] * adj_count[u][i] ) % M; 
    else
      l[i] = adj_count[u][0] % M;
  }

  r[le-1] = adj_count[u][le-1] % M;
  if (le > 1) f[le-1] = l[le-2]; else f[le-1]= 1;

  for(auto i=le-2; i >=0; i--) {
    auto v = adj[u][i];
    r[i] = (r[i+1] * adj_count[u][i] ) % M;
    if (i > 0) f[i] = (l[i-1] * r[i+1] ) % M;
    else f[i] = r[i+1] % M;
  }


  assert(r[0] == l[le-1]);
  ans[u] = r[0];

  for(auto i=0; i<le; i++) {
    // cout << "fi" << i << " " << f[i] << endl;
    auto v = adj[u][i];
    if (!visited[v])  dfs2(v,  f[i]);
  }
}

int main() {
  int N;
  cin >> N >> M;

  adj.assign(N, {});
  adj_count.assign(N, {});
  ans.assign(N, 0);
  visited.assign(N, false);

  for(int i=0; i < N-1; i++) {
    int u, v;
    cin >> u >> v;
    u--;
    v--;
    adj[u].push_back(v);
    adj_count[u].push_back(0);
    adj[v].push_back(u);
    adj_count[v].push_back(0);
  }

  dfs1(0);
  visited.assign(N, false);
  dfs2(0, 0);
  for(auto i=0; i<N; i++) cout << ans[i] << endl;
  return 0;
}

#include <bits/stdc++.h>

using namespace std;

typedef long long LL;

int n, m;
vector<int> ch[100010];
int pa[100010];
vector<int> pre[100010], suf[100010];
int pos[100010];
int down[100010], up[100010];

void dfs(int u) {
    for (int i=0;i<ch[u].size();i++) {
        int v=ch[u][i];
        if (pa[u]==v) continue;
        pa[v]=u;
        pos[v]=i;
        dfs(v);
    }
}

int go_down(int u) {
    if (down[u]>=0) return down[u];
    for (int i=0;i<ch[u].size();i++) {
        int v=ch[u][i];
        if (pa[u]==v) {
            if (pre[u].size()==0) pre[u].push_back(1);
            else pre[u].push_back(pre[u][pre[u].size()-1]);
            continue;
        }
        int t=1;
        if (pre[u].size()>0) t=pre[u][pre[u].size()-1];
        pre[u].push_back((1LL*t*(go_down(v)+1))%m);
    }
    for (int i=(int)ch[u].size()-1;i>=0;i--) {
        int v=ch[u][i];
        if (pa[u]==v) {
            if (suf[u].size()==0) suf[u].push_back(1);
            else suf[u].push_back(suf[u][suf[u].size()-1]);
            continue;
        }
        int t=1;
        if (suf[u].size()>0) t=suf[u][suf[u].size()-1];
        suf[u].push_back((1LL*t*(go_down(v)+1))%m);
    }
    return down[u]=pre[u][pre[u].size()-1];
}

int go_up(int u) {
    if (up[u]>=0) return up[u];
    if (u==0) return 0;
    int f=pa[u];
    int ret=1;
    if (pos[u]-1>=0) ret=(1LL*ret*pre[f][pos[u]-1])%m;
    if ((int)suf[f].size()-pos[u]-2>=0) ret=(1LL*ret*suf[f][(int)suf[f].size()-pos[u]-2])%m;
    ret=(1LL*ret*(go_up(f)+1))%m;
    return up[u]=ret;
}

int main() {
    cin>>n>>m;
    for (int i=0;i<n-1;i++) {
        int x, y;
        scanf("%d%d", &x, &y);
        ch[x-1].push_back(y-1);
        ch[y-1].push_back(x-1);
    }
    if (n==1) {
        cout<<1<<endl;
        return 0;
    }
    memset(pa,-1,sizeof(pa));
    dfs(0);
    memset(down,-1,sizeof(down));
    memset(up,-1,sizeof(up));
    for (int i=0;i<n;i++) go_down(i);
    cout<<go_down(0)<<endl;
    for (int i=1;i<n;i++) cout<<(1LL*go_down(i)*(1+go_up(i)))%m<<endl;
}

