void gao2(int x){
	for(int i=0;i!=v[x].size();++i){
		if(fa2[x]==v[x][i]) continue;
		fa2[v[x][i]]=x;
		gao2(v[x][i]);
	}
}

long long suan1(int x){
	if(dp1[x]!=0)	return dp1[x];
	dp1[x]=1;
	for(int i=0;i!=v[x].size();++i){
		if(v[x][i]==fa1[x]) continue;
		dp1[x]*=suan1(v[x][i])+1;
		dp1[x]%=m;
	}
	return dp1[x];
