long long suan2(int x){
	if(dp2[x]!=0)	return dp2[x];
	dp2[x]=1;
	for(int i=0;i!=v[x].size();++i){
		if(v[x][i]==fa2[x]) continue;
		dp2[x]*=suan2(v[x][i])+1;
		dp2[x]%=m;
	}
	return dp2[x];
}

