int N, M;

typedef vector<long long> vi;
typedef vector<vi> vvi;

long long MOD;
vvi g;
vvi pref;
vvi suf;
long long down[MAX + 1];
long long up[MAX + 1];

void fix( int x )
{
	for( auto &y : g[x] ) {
		auto it = find( g[y].begin(), g[y].end(), x );
		if( it != g[y].end() ) {
			g[y].erase( it );
		}
        fix( y );
    }
}

void dfs( int x )
{
    down[x] = 1;
    for( auto &y : g[x] ) {
        dfs( y );
        down[x] = down[x] * (down[y] + 1) % MOD;
    }
    int sz = g[x].size();
    pref[x].resize( sz + 1 );
    suf[x].resize( sz + 1 );
    pref[x][0] = suf[x][sz] = 1;
    for( int i = 0; i < sz; i++ ) {
        pref[x][i + 1] = pref[x][i] * (1 + down[ g[x][i] ]) % MOD;
    }
    for( int i = sz-1; i >= 0; i-- ) {
        suf[x][i] = suf[x][i + 1] * (1 + down[ g[x][i] ]) % MOD;
    }
}

void dfs1( int x )
{
