ll mod;
vector<vector<int>> G;
vector<vector<ll>> dp, dpl, dpr;
ll dfs(int u, int p) {
  dp[u].assign(G[u].size(), 0);
  dpl[u].assign(G[u].size()+1, 0);
  dpr[u].assign(G[u].size()+1, 0);
  ll res = 1;
  rep(i, G[u].size()) {
    int v = G[u][i];
    if(v != p) {
      dp[u][i] = dfs(v, u) % mod;
      res = (res % mod) * (dp[u][i] + 1) % mod;
    }
  }
  return res;
}
void bfs() {
  queue<tuple<int, int, int>> que; // u, p, i
  que.emplace(0, -1, 0);
  while(!que.empty()) {
    auto el = que.front(); que.pop();
    int u = get<0>(el);
    int p = get<1>(el);
    int j = get<2>(el);
    int sz = G[u].size();
    rep(i, sz) {
      int v = G[u][i];
      if(v == p) {
        dp[u][i] = dpl[v][j] * dpr[v][j+1] % mod;
      } else {
        que.emplace(v, u, i);
      }
    }
    dpl[u][0] = dpr[u][sz] = 1;
    rep(i, sz) {
      dpl[u][i+1] = (dpl[u][i] * ((dp[u][i] + 1) % mod)) % mod;
      dpr[u][sz-i-1] = (dpr[u][sz-i] * (dp[u][sz-i-1] + 1) % mod) % mod;
    }
  }
}
