ll rec(ll x, ll n) {
	if (dp[x][n] + 1) return dp[x][n];
	ll y, nn;
	tie(y, nn) = adj[x][n];
	if (!chk[y]) {
		chk[y] = 1;
		ll adjs = adj[y].sz;
		as1[y].res(adjs);
		as2[y].res(adjs);
		as1[y][0] = 1;
		as2[y][adjs - 1] = 1;
		FOR(i, 1, adjs - 1) as1[y][i] = (as1[y][i - 1] * rec(y, i - 1)) % M;
		rFOR(i, 0, adjs - 2) as2[y][i] = (as2[y][i + 1] * rec(y, i + 1)) % M;
	}
	return dp[x][n] = (as1[y][nn] * as2[y][nn] + 1) % M;
}

void Solve() {

	cin >> N >> M;
	adj.asn(N, vpl());
	dp.asn(N, vll());
