		adj[y].pb(mp(x, adj[x].sz - 1));
		dp[x].pb(-1);
		dp[y].pb(-1);
	}
	REP(i, N) {
		ll tmp = 1;
		REP(j, adj[i].sz) tmp = (tmp * rec(i, j)) % M;
		sal(tmp);
	}

}

