typedef pair<long long int, long long int> P;

long long int INF = 1e18;
long long int MOD = 1e9 + 7;

long long int N, M;

vector<int> E[110000], memo[110000];
long long int ans[110000];

long long int func(int pos, int pre){
  long long int ret = 1;
  for(int i = 0; i < E[pos].size(); i++){
    int to = E[pos][i];
    if(to != pre){
      memo[pos][i] = func(to, pos);
      ret *= memo[pos][i];
      ret %= M;
    }
  }
  return (ret + 1) % M;
}

void func2(int pos, int pre, long long int patt){
  ans[pos] = 1;
  for(int i = 0; i < E[pos].size(); i++){
    int to = E[pos][i];
    if(to == pre){
      memo[pos][i] = patt;
    }
    ans[pos] *= memo[pos][i];
    ans[pos] %= M;
  }
  long long int L[E[pos].size() + 1], R[E[pos].size() + 1];
  L[0] = 1;
  for(int i = 0; i < E[pos].size(); i++){
    L[i + 1] = L[i] * memo[pos][i] % M;
  }
  R[E[pos].size()] = 1;
  for(int i = E[pos].size() - 1; i >= 0; i--){
    R[i] = R[i + 1] * memo[pos][i] % M;
  }
  for(int i = 0; i < E[pos].size(); i++){
    int to = E[pos][i];
    if(to != pre){
      func2(to, pos, (L[i] * R[i + 1] + 1) % M);
    }
  }
}

