      cout << endl;
      cout << "R_prod check" << endl;
      for(int i = 0; i < (int)to[a].size(); i++){ 
        cout << r_prod[i] << " ";
      }

    }
    cout << endl;

  } 




  for(int j = 0; j  < (int)to[a].size(); j++){ 

    int res = 1LL;

    if( to[a][j] == par ){ continue;} 

    if( j-1 >= 0 ){ res *= l_prod[j-1];}
    if( j+1 < to[a].size()){ res *= r_prod[j+1];}

    res %= m;

    res = (res*dp2[a])%m;

    res = ( res+1 ) % m;

    dp2[to[a][j]] = res;
    //+1済み

    dfs2(to[a][j],a);

  }

  return ;
}


//３つ目のdfs 
void dfs3(int a, int par){ 

  int res = dp2[a];

  for(auto ne : to[a] ){ 

    if( ne == par ){ continue;} 

    res *= dp1[ne];
    res %= m;

    dfs3(ne,a);

  }

  ans[a] = res%m;

  return ;
}


