#define INF 1000000000000000LL

using namespace std;

#define MAXN 110000

ll dp1[MAXN];
ll dp2[MAXN];
ll ans[MAXN];
ll n, m;
vector<vector<int>>edges(MAXN);

void dfs1(int now=1, int p=-1){
  dp1[now]=1;
  for(auto c: edges[now]){
    if(c==p)continue;
    dfs1(c, now);
    dp1[now]*=dp1[c];
    dp1[now]%=m;
  }
  dp1[now]++;
}

void dfs2(int now=1, int p=-1){
  if(p==-1)dp2[now]=1;

  int ec = edges[now].size();

  vector<ll>lprod(ec, 1);
  rep(i, ec){
    int c = edges[now][i];
    if(i)lprod[i] *= lprod[i-1];
    if(c==p)continue;
    lprod[i]*=dp1[c];
    lprod[i]%=m;
  }

  vector<ll>rprod(ec, 1);
  rrep(i, ec){
    int c = edges[now][i];
    if(i<ec-1)rprod[i] *= rprod[i+1];
    if(c==p)continue;
    rprod[i] *= dp1[c];
    rprod[i] %= m;
  }

  rep(i, ec){
    int c = edges[now][i];
    if(c==p)continue;
    dp2[c] = dp2[now];
    if(i)dp2[c] = dp2[c] * lprod[i-1] % m;
    if(i<ec-1)dp2[c] = dp2[c] * rprod[i+1] % m;
    dp2[c]++;
    dfs2(c, now);
  }
}

void dfs3(int now=1, int p=-1){
  ans[now] = dp2[now];
  for(auto c: edges[now]){
    if(c==p)continue;
    ans[now] *= dp1[c];
    ans[now] %= m;
    dfs3(c, now);
  }
}

