const int mxn = 100010;
ll dp[mxn], tmp[mxn], ans[mxn], mod;
int N;

vector<int> adj[mxn];

void dfs_dp(int node, int parent)
{
	for(auto x:adj[node])
		if(x!=parent) dfs_dp(x, node);

	dp[node] = 1ll; 
	for(auto x:adj[node])
		if(x!=parent) dp[node]*=(dp[x]+1), dp[node]%=mod;
}

void dfs_ans(int node, int parent, ll val_of_parent=0ll)
{ 
	ans[node] = val_of_parent+1;
	for(auto x:adj[node])
		if(x!=parent) ans[node]*=(dp[x]+1), ans[node]%=mod;

	int sz_child = (int) adj[node].size();

	vector<int> pre(sz_child, 1ll);
	vector<int> suff(sz_child, 1ll);

	pre[0] = dp[adj[node][0]]+1;
	for(int i=1; i<sz_child; i++) 
		pre[i] = pre[i-1]*(dp[adj[node][i]]+1)%mod;

	suff[sz_child-1] = dp[adj[node][sz_child-1]]+1;
	for(int i=sz_child-2; i>=0; i--)
		suff[i] = suff[i+1]*(dp[adj[node][i]]+1)%mod;

	for(int i=0; i<sz_child; i++) {
		int next = adj[node][i];
		ll new_val = val_of_parent+1;
		if(i==0) new_val = new_val*suff[i+1]%mod;
		else if(i==sz_child-1) new_val = new_val*pre[i-1]%mod;
		else new_val = (new_val*pre[i-1]%mod)*suff[i+1]%mod;
		dfs_ans(next, node, new_val);
	}
}

void process(int root)
{
	dfs_dp(root, -1);
	for(int i=1; i<=N; i++) tmp[i] = dp[i];
	dfs_ans(root, -1);
}

