	cin>>N>>mod;
	for(int i=0; i<N-1; i++) {
		int x, y; cin>>x>>y;
		adj[x].push_back(y);
		adj[y].push_back(x);
	}

	process(1);

	for(int i=1; i<=N; i++)
		cout << ans[i] << '\n';

	return 0;
}

