const int NNODES = 1e5 + 6;
vector<int> v[NNODES];
int fatherOf[NNODES];

int down[NNODES];
int up[NNODES];
int prefix[NNODES], suffix[NNODES];

int dfsDown(int root, int m) {
    vector<int> l;
    int temp = 1;
    for(int node: v[root]) {
        if (fatherOf[root] == node) {
            continue;
        }
        fatherOf[node] = root;
        temp = ((temp % m) * (1 + dfsDown(node, m)) % m ) % m;

        // calculate prefix, suffix
        l.push_back(node);
    }

    int t = 1;
    for (int i = 0; i < l.size(); i++) {
        // pair<int, int> a(root, l[i]);
        prefix[l[i]] = t;
        t = ((t%m) * ((1 + down[l[i]])%m)) % m;
        // printf("sss %d, %d, %lld\n", root, l[i], prefix[{root, l[i]}]);
    }
    t = 1;
    for (int i = l.size()-1; i >= 0; i--) {
        // pair<int, int> a(root, l[i]);
        suffix[l[i]] = t;
        t = ((t%m) * ((1 + down[l[i]])%m)) % m;
    }
    down[root] = temp%m;
    return down[root];
}


