    }

    void add_edge2(int v1, int v2, int cost = 0){
        add_edge(v1, v2, cost);
        add_edge(v2, v1, cost);
    }

    void dfs(int v = 0, int p = -1){
        par[v] = p;
        dp[v] = 1;
        for(auto e: G[v]) if(e.to != par[v]){
            dfs(e.to, v);
            dp[v] *= 1 + dp[e.to];
            dp[v] %= mod;
        }
    }

    void dfs2(int v = 0){
        ans[v] = dp[v];
        dp2[v] = 0;
        if(par[v] != -1){

            dp2[v] = 1;

            dp2[v] *= 1 + dp2[par[v]];
            for(auto e: G[par[v]]){
                if(e.to != par[par[v]] && e.to != v){
                    dp2[v] *= 1 + dp[e.to];
                    dp2[v] %= mod;
                }
            }

            ans[v] *= 1 + dp2[v];
            ans[v] %= mod;
        }
        for(auto e: G[v]) if(e.to != par[v]) dfs2(e.to);
    }

    void calcans(){
        dfs();
        dfs2();
        //REP(i, V) cout << dp[i] << "," << dp2[i] << "," << ans[i] << endl;
        REP(i, V) cout << ans[i] << endl;
    }

};


