#include <bits/stdc++.h>
using namespace std;
using ll = long long;

const int MAX = 1e5;

int N, M;
vector<int> G[MAX];

ll dp[MAX];

int it;
ll memo[MAX * 2];

ll dfs1(int v, int prev) {
	ll res = 1;
	for (auto to : G[v]) if (to != prev) {
		int id = it++;
		memo[id] = dfs1(to, v);
		(res *= memo[id] + 1) %= M;
	}
	return res;
}

vector<ll> x[MAX];

void get(int v, int prev) {
	int sz = G[v].size();
	x[v].assign(sz - (prev != -1), 0);
	int id = 0;
	for (auto to : G[v]) if (to != prev) {
		x[v][id++] = memo[it++];
		get(to, v);
	}
}

void dfs2(int v, int prev, ll tmp) {
	int sz = G[v].size() + (prev == -1);
	vector<ll> l(sz, 1), r(sz, 1);
	for (int i = 1; i < sz; i++) {
		l[i] = l[i - 1] * (x[v][i - 1] + 1) % M;
	}
	for (int i = sz - 1; i > 0; i--) {
		r[i - 1] = r[i] * (x[v][i - 1] + 1) % M;
	}
	int id = 0;
	for (auto to : G[v]) if (to != prev) {
		int i = id++;
		ll t = (tmp * l[i] % M * r[i + 1] + 1) % M;
		dp[to] = x[v][i] * t % M;
		dfs2(to, v, t);
	}
}

int main()
{
	cin >> N >> M;
	for (int i = 0; i < N - 1; i++) {
		int a, b;
		cin >> a >> b; a--, b--;
		G[a].push_back(b);
		G[b].push_back(a);
	}
	dp[0] = dfs1(0, -1); it = 0;
	get(0, -1);
	dfs2(0, -1, 1);
	for (int i = 0; i < N; i++) {
		cout << dp[i] << endl;
	}
	return 0;
}

