// Solution to https://atcoder.jp/contests/dp/tasks/dp_v
#include <algorithm>
#include <cassert>
#include <iostream>
#include <vector>
using namespace std;

int N, MOD;
vector<vector<int>> adj;

// up[node] = number of ways to color the subtree of node that its parent is responsible for, empty coloring included.
// down[node] = number of ways to paint node's subtree where node must be painted black.
vector<int> up, down;

void solve_down(int node, int parent) {
    down[node] = 1;

    // Erase the edge from node to parent.
    if (parent >= 0)
        adj[node].erase(find(adj[node].begin(), adj[node].end(), parent));

    for (int child : adj[node]) {
        solve_down(child, node);
        down[node] = (long long) down[node] * (down[child] + 1) % MOD;
    }
}

void solve_up(int node) {
    int n = adj[node].size();
    vector<int> prefix(n, 1), suffix(n, 1);

    for (int i = 0; i + 1 < n; i++)
        prefix[i + 1] = (long long) prefix[i] * (down[adj[node][i]] + 1) % MOD;

    for (int i = n - 1; i > 0; i--)
        suffix[i - 1] = (long long) suffix[i] * (down[adj[node][i]] + 1) % MOD;

    // Note that both prefix[i] and suffix[i] exclude i.
    for (int i = 0; i < n; i++)
        up[adj[node][i]] = (1 + (long long) prefix[i] * suffix[i] % MOD * up[node]) % MOD;

    for (int child : adj[node])
        solve_up(child);
}

int main() {
    scanf("%d %d", &N, &MOD);
    adj.assign(N, {});

    for (int i = 0; i < N - 1; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        a--; b--;
        adj[a].push_back(b);
        adj[b].push_back(a);
    }

    up.assign(N, 1);
    down.assign(N, 1);
    solve_down(0, -1);
    solve_up(0);

    for (int i = 0; i < N; i++)
        printf("%lld\n", (long long) up[i] * down[i] % MOD);
}

