using namespace std;
int N; 
long long M; 
vector<int> E[100010];
long long root0[100010], inv[100010], ans[100010];
void dfs1(int now, int parent){
	long long tmp = 1LL; 
	for(int i : E[now]){
		if(i == parent) continue; 
		dfs1(i, now); 
		tmp *= root0[i] + 1; 
		tmp %= M; 
	}
	if(now == 0){
		ans[0] = tmp; inv[0] = 1; 
	}
	root0[now] = tmp;
	return;
}
void dfs2(int now, int parent){
	vector<long long> left, right; 
	long long tmp = 1; 
	left.push_back(1); 
	for(int i = 0; i < (int) E[now].size(); i++){
		if(E[now].at(i) == parent){
			left.push_back(tmp); continue; 
		}
		tmp *= root0[E[now].at(i)] + 1; tmp %= M; 
		left.push_back(tmp); 
	}
	tmp = 1; right.push_back(1); 
	for(int i = E[now].size() - 1; i >= 0; i--){
		if(E[now].at(i) == parent){
			right.push_back(tmp); continue; 
		}
		tmp *= root0[E[now].at(i)] + 1; tmp %= M; 
		right.push_back(tmp); 
	}
	reverse(right.begin(), right.end()); 
	for(int i = 0; i < (int) E[now].size(); i++){
		if(E[now].at(i) == parent) continue; 
		inv[E[now].at(i)] = left[i] % M * right[i+1] % M; 
		if(now != -1){
			inv[E[now].at(i)] *= inv[now]; inv[E[now].at(i)] %= M;  
		}
		inv[E[now].at(i)] ++; inv[E[now].at(i)] %= M; 
		ans[E[now].at(i)] = root0[E[now].at(i)] * inv[E[now].at(i)] % M; 
		dfs2(E[now].at(i), now); 
	}
	return; 
}
int main(){
	cin >> N >> M; 
	for(int i = 0; i < N-1; i++){
		int x, y; cin >> x >> y; 
		x--; y--; 
		E[x].push_back(y); E[y].push_back(x); 
	}
	dfs1(0, -1); 
	dfs2(0, -1); 
	for(int i = 0; i < N; i++){
		cout << ans[i] << "\n"; 
	}
}

