// find_by_order(k) – ফাংশনটি kth ordered element এর একটা পয়েন্টার রিটার্ন করে। অর্থাৎ তুমি চাইলেই kth ইন্ডেক্সে কি আছে, সেটা জেনে ফেলতে পারছো!
// order_of_key(x) – ফাংশনটি x এলিমেন্টটা কোন পজিশনে আছে সেটা বলে দেয়।
//*//**___________________________________________________**/
const int N = 100006;
int n, Mod;
vector<int> g[N];
ll ans[N];
vector<ll> L[N], R[N];

void dfs(int a, int par) {
  L[a].resize(g[a].size() + 2);
  R[a].resize(g[a].size() + 2);
  L[a].front() = 1;
  R[a].back() = 1;
  for (int b : g[a]) {
    if (b != par)dfs(b, a);
  }

  for (int i = 0; i < (int)g[a].size(); i++) {
    int b = g[a][i];
    L[a][i + 1] = L[a][i];
    if (b == par)continue;
    L[a][i + 1] *= (L[b].back() + 1);
    L[a][i + 1] %= Mod;
  }
  for (int i = 0; i < (int)g[a].size(); i++) {
    int id = (int)g[a].size() - i - 1;
    int b = g[a][id];
    R[a][id + 1] = R[a][id + 2];
    if (b == par)continue;
    R[a][id + 1] *= (L[b].back() + 1);
    L[a][id + 1] %= Mod;
  }
  L[a].back() = R[a].front() = R[a][1];
}

void solve(int a, int par, ll K) {
  ans[a] = K * L[a].back() % Mod;
  for (int i = 0; i < (int)g[a].size(); i++) {
    int b = g[a][i];
    if (b == par)continue;
    ll x = L[a][i] * R[a][i + 2] % Mod;
    solve(b, a, (K * x + 1) % Mod);
  }
}

