int temp[100055][2];

void rdfs(int v, int par = -1, int painted = 1, int notPainted = 1) {
	res[v] = 1ll * dp[v][1] * (painted + notPainted - (par == -1)) % MOD;

//	cerr << v + 1 << " " << dp[v][0] << " " << dp[v][1] << " " << temp[v][0] << " " << temp[v][1] << endl;

	{
		int lPainted = (painted + notPainted - (par == -1)) % MOD;
		int lNotPainted = notPainted;

		for (auto u : g[v]) if (u != par) {
			temp[u][0] = lNotPainted;
			temp[u][1] = lPainted;

			lPainted = (1ll * lPainted * (dp[u][0] + dp[u][1])) % MOD;
			lNotPainted = (1ll * lNotPainted * dp[u][0]) % MOD;
		}
	}

	reverse(g[v].begin(), g[v].end());

	{
		int rPainted = 1;
		int rNotPainted = 1;

		for (auto u : g[v]) if (u != par) {
			temp[u][0] = 1ll * temp[u][0] * rNotPainted % MOD;
