//const int128_t INF = std::numeric_limits<int64_t>::max();
//const double EPS = 1.0e-15;

Tree_New tree(MAX_N);
std::vector<std::unordered_map<int, int>> edge_mp;

int128_t dfs(int128_t node, int128_t id);

int128_t calc_acl(int128_t node, int128_t id) {
    assert(id < tree.G[node].size());
    if (id == -1) { return 1; }
    if (dp_acl[node][id] != -1) { return dp_acl[node][id]; }

    int128_t ret = calc_acl(node, id - 1) * (dfs(node, id) + 1);
    return dp_acl[node][id] = ret % M;
}

int128_t calc_acr(int128_t node, int128_t id) {
    assert(0 <= id);
    if (id == tree.G[node].size()) { return 1; }
    if (dp_acr[node][id] != -1) { return dp_acr[node][id]; }

    int128_t ret = calc_acr(node, id + 1) * (dfs(node, id) + 1);
    return dp_acr[node][id] = ret % M;
}

int128_t dfs(int128_t node, int128_t id) {
    assert(0 <= id && id < tree.G[node].size());
    if (dp[node][id] != -1) { return dp[node][id]; }

    int128_t pid = edge_mp[tree.G[node][id].to][node];
    int128_t ret = calc_acl(tree.G[node][id].to, pid - 1) * calc_acr(tree.G[node][id].to, pid + 1);
    return dp[node][id] = ret % M;
}

