const int MAXN=1e5+10;
ll n,m,f1[MAXN],f2[MAXN],up[MAXN];
vector <ll> pre[MAXN],suf[MAXN],node[MAXN];
void dfs_dp_init(int now,int fa)
{
	f1[now]=1;
	for(int i=0;i<node[now].size();i++)
	{
		ll to=node[now][i];
		if(to==fa)
			continue;
		dfs_dp_init(to,now);
		f1[now]=(f1[now]*(f1[to]+1))%m;
	}
	ll sum=1;
	for(int i=0;i<node[now].size();i++)
	{
		ll to=node[now][i];
		if(to!=fa)
			sum=(sum*(f1[to]+1))%m;
		pre[now].push_back(sum);
	}
	sum=1;
	for(int i=node[now].size()-1;i>=0;i--)
	{
		ll to=node[now][i];
		if(to!=fa)
			sum=(sum*(f1[to]+1))%m;
		suf[now].push_back(sum);
	}
}
void dfs_dp(int now,int fa)
{
	for(int i=0;i<node[now].size();i++)
	{
		ll to=node[now][i];
		if(to==fa)
			continue;
		f2[to]=f1[to],up[to]=up[now]+1;
		if(i)
			up[to]=(up[to]*pre[now][i-1])%m;
		if(i!=node[now].size()-1)
			up[to]=(up[to]*suf[now][node[now].size()-i-2])%m;
		dfs_dp(to,now);
	}
}
