void search(ll pre, ll index){
  if(flag[pre][index]) return;
  flag[pre][index] = true;
  ll pos = edge[pre][index];
  for(int i=0; i<edge[pos].size(); ++i){
    if(edge[pos][i]==pre) continue;
    search(pos, i);
    black[pre][index] *= (black[pos][i]+1);
    gray[pre][index] += gray[pos][i];
    black[pre][index] %= M;
    //gray[pre][index] %= M;
  }
  gray[pre][index] += black[pre][index]-1;
  gray[pre][index] %= M;
  return;
}

