void dfs2(int at,int par) {
	ncur=0;
	REPSZ(i,adj[at]) {
		int to=adj[at][i]; if(to==par) continue;
		cur[ncur++]=to;
	}
	REP(i,ncur) val[i]=(1+wayssubtree[cur[i]])%MOD;
	pref[0]=waysabove[at]; REP(i,ncur) pref[i+1]=(ll)pref[i]*val[i]%MOD;
	suff[ncur]=1; for(int i=ncur-1;i>=0;--i) suff[i]=(ll)suff[i+1]*val[i]%MOD;
	REP(i,ncur) {
		int to=cur[i];
		waysabove[to]=(1+(ll)pref[i]*suff[i+1])%MOD;
	}
	REPSZ(i,adj[at]) {
		int to=adj[at][i]; if(to==par) continue;
		dfs2(to,at);
	}
}

