const int INF = 1e9;
const int MAX = 1e5+3;
int MOD = 1e9+7;
int n, M;
vector<int> adj[MAX];
vector<int> ways;
vector<int> ways_up;
vector<int> pre[MAX];
vector<int> tree[MAX];
vector<int> ans;

void build(int s, int node, int l, int r)
{
   if(l > r)
      return ;

   if(l == r)
   {
      tree[s][node] = pre[s][l]+1;
      return;
   }

   int mid = (l+r)/2;
   build(s, 2*node, l, mid);
   build(s, 2*node+1, mid+1, r);
   tree[s][node] = (tree[s][2*node]*tree[s][2*node+1])%M;
}


void build_util(int s)
{
   int sz = pre[s].size();
   if(!sz) return ;
   tree[s].resize(4*sz, 1);
   build(s, 1, 0, sz-1);
}

int query(int s, int node, int st, int en, int l, int r)
{
   if(l > r)
      return 1;

   if(st > r || en < l)
      return 1;

   if(st >= l && en <= r)
      return tree[s][node];

   int mid = (st+en)/2;
   int p1 = query(s, 2*node, st, mid, l, r);
   int p2 = query(s, 2*node+1, mid+1, en, l, r);
   return (p1*p2)%M;
}


void dfs(int s, int par)
{
   for(int i=0;i<adj[s].size();i++)
   {
      if(adj[s][i] != par)
      {
         dfs(adj[s][i], s);
         ways[s] = (ways[s]*(ways[adj[s][i]]+1))%M;
         pre[s].pb(ways[adj[s][i]]);
      }
   }
   build_util(s);
}

int cal_fun(int s, int par)
{
   bool is_par_done = false;
   for(int i=0;i<adj[s].size();i++)
   {
      if(adj[s][i] == par){ is_par_done = true; continue; }
      ans[s] = (ans[s]*(ways[adj[s][i]]+1))%M;
      int l1, r1, l2, r2;
      if(!is_par_done)
         l1 = 0, r1 = i-1, l2=i+1, r2 = (int)pre[s].size()-1;
      else l1 = 0, r1 = i-2, l2 = i, r2 = (int)pre[s].size()-1;
