		dp[u] = dp[u] * (dp[v] + 1) % m;
	}
	pre[u].resize(G[u].size());
	suf[u].resize(G[u].size());
	for(int i=0;i<(int)G[u].size();i++)
		pre[u][i] = (i ? pre[u][i-1] : 1) * (G[u][i] == p ? 1 : dp[G[u][i]] + 1) % m;
	for(int i=(int)G[u].size()-1;i>=0;i--)
		suf[u][i] = (i < (int)G[u].size()-1 ? suf[u][i+1] : 1) * (G[u][i] == p ? 1 : dp[G[u][i]] + 1) % m;

}

void dfs1(int u, int p = -1) {
	if(p == -1) up[u] = 1;
	for(int i=0;i<(int)G[u].size();i++) if(G[u][i] != p) {
		int v = G[u][i];
		up[v] = (1 + up[u] * (i ? pre[u][i-1] : 1) % m * (i == (int)G[u].size()-1 ? 1 : suf[u][i+1]) % m) % m;
		dfs1(v, u);
	}
}

