#define N 100007

int n;
ll m;
vector<P> g[N];

ll memo[2*N];
ll dfs(int v, int p, int e) {
  if(memo[e] != -1) {
    return memo[e];
  }
  ll r = 1;
  repe(&pr, g[v]) {
    int w = pr.first, d = pr.second;
    if(w == p) continue;
    r *= 1 + dfs(w, v, d);
    r %= m;
  }
  return memo[e] = r;
}

int main() {
  scanf("%d %lld", &n, &m);
  rep(i, n-1) {
    int x, y; scanf("%d %d", &x, &y); --x; --y;
    g[x].push_back(P(y, 2*i));
    g[y].push_back(P(x, 2*i+1));
  }
  rep(i, 2*n) memo[i] = -1;
  rep(v, n) {
    ll r = 1;
    repe(&p, g[v]) {
      int w = p.first, d = p.second;
      r *= 1 + dfs(w, v, d);
      r %= m;
    }
    printf("%lld\n", r);
  }
  return 0;
}

