void dfs_down(int x, int pa){
    down[x] = 1;
    par[x] = pa;
    E[x].erase(remove(all(E[x]), pa), E[x].end());
    for(auto e : E[x]){
        dfs_down(e,x);
        down[x] = down[x] * (down[e] + 1) % M;
    }
}

void dfs_up(int x, int pa){
    int K = sz(E[x]);
    for(int i=0;i<K;i++) L[i] = R[i] = 1;
    if( K ){
        L[0] = down[E[x][0]] + 1; R[K-1] = down[E[x][K-1]] + 1;
        for(int i=1;i<K;i++) L[i] = L[i-1] * (down[E[x][i]]+1) % M;
        for(int i=K-2;i>=0;i--) R[i] = R[i+1] * (down[E[x][i]]+1) % M;
        for(int i=0;i<K;i++){
            int e = E[x][i];
            up[e] = 1 + up[x] * (i-1>=0?L[i-1]:1) % M * (i+1<K?R[i+1]:1) % M;
            up[e] %= M;
        }
    }

    for(auto e : E[x])if(e!=pa){
        dfs_up(e,x);
    }
}

