#include <iostream>
#include <vector>
using namespace std;
using Graph = vector<vector<int>>;

long long M;
int N;
Graph G;

// dp[v][to] := 有効辺 (v, to) について to 側の木についての解
vector<vector<long long>> dp;
vector<long long> res;

long long rec(int v, int p = -1) {
    long long res = 1;
    dp[v].assign(G[v].size(), 1);
    for (int i = 0; i < G[v].size(); ++i) {
        int to = G[v][i];
        if (to == p) continue;
        dp[v][i] = (rec(to, v) + 1) % M;
        res = res * dp[v][i] % M;
    }
    return res;
}

void rerec(int v, long long pval = 0, int p = -1) {
    int s = G[v].size();
    for (int i = 0; i < s; ++i) {
        int to = G[v][i];
        if (to == p) dp[v][i] = (pval + 1) % M;
    }

    // 累積積
    vector<long long> left(s+1, 1), right(s+1, 1);
    for (int i = 0; i < s; ++i) {
        left[i+1] = (left[i] * dp[v][i]) % M;
        right[i+1] = (right[i] * dp[v][s-i-1]) % M;

        //cout << v << ", " << G[v][i] << ": " << dp[v][i] << endl;
    }
    res[v] = left[s];

    // それぞれ
    for (int i = 0; i < s; ++i) {
        int to = G[v][i];
        if (to == p) continue;
        long long toval = left[i] * right[s-i-1] % M;
        rerec(to, toval, v);
    }
}

void solve() {
    res.assign(N, 1);
    dp.assign(N, vector<long long>());
    rec(0);
    rerec(0);
    for (int v = 0; v < N; ++v) cout << res[v] << endl;

}

int main() {
    while (cin >> N >> M) {
        G.assign(N, vector<int>());
        for (int i = 0; i < N-1; ++i) {
            int x, y; cin >> x >> y; --x, --y;
            G[x].push_back(y); G[y].push_back(x);
        }
        solve();
    }
}

