typedef long long ll;
const ll MOD = 1000000007;
ll mod;

using namespace std;

vector<vector<int> > t(100005);
vector<int> a(100005), dp(100005, -1);

int dfs(int node, int p = -1) {
    if (dp[node] != -1) return dp[node];
    ll ans = 1;
    for (auto c : t[node]) {
        if (c == p) continue;
        ans = (ans * (1LL + dfs(c, node))) % mod;
    }
    dp[node] = ans;
    return (int)ans;
}

void reroot(int node, int p = -1) {
    // first find the answer assuming node is root
    if (p != -1) {
        // calculate the new answer for p
        dp[p] = -1;
        dp[p] = dfs(p, node);
    }
    // find the answer assuming node is root
    ll ans = 1;
    for (auto c : t[node]) {
        ans = (ans * (1LL + dp[c])) % mod;
    }
    dp[node] = a[node] = ans;
    // make every child except p the new root
    for (auto c : t[node]) {
        if (c == p) continue;
        ll tmp1 = dp[node];
        ll tmp2 = dp[c];
        reroot(c, node);
        dp[node] = tmp1;
        dp[c] = tmp2;
    }
    return;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    cin >> n >> mod;

    for (int i = 0; i < n - 1; i++) {
        int u, v;
        cin >> u >> v;
        u--, v--;
        t[u].push_back(v);
        t[v].push_back(u);
    }

    a[0] = dfs(0);

    reroot(0);

    for (int i = 0; i < n; i++) {
        cout << a[i] << endl;
    }

    return 0;
}

