/*
AC
辺に関するdp（辺より先の部分木に関するdp）
dp[p][i] = pから出るi番目の辺より奥の部分木の塗り方の総数。
	v[p][i]が白のとき、それ以降はすべて白なので1通り。
	v[p][i]が黒のとき、v[p][i]から出る辺で行き先がp以外ものについての塗り方の制約は無い。
実はこのままだとTLEする。
隣接点が極端に多い点があったら、掛け算の回数がn^2に近くなってしまう。mが素数ならmod mでの逆元を用いて計算量を短縮できるが、ここではmは一般の数なのでそれも出来ない。
解決方法：配列のうち 1 要素を除いた積を取る
	順方向と逆方向の累積積を持っておけば[$ O(1)]で求まる
	ru:順方向
	ru2:逆方向

変数は全部long long使うべき
*/

ll n,m,visited[100010]={};
vector<ll> v[100010],v_rev[100010],dp[100010],ru[100010],ru2[100010];

ll f(ll p,ll rev,bool begin){
	ll next=1;
	int k = v[p].size();
	if(k==0 || visited[p]<k){//pに隣接する未探索の辺があったら
		rep(i,k){
			if(i==rev)continue;
			if(dp[p][i]==-1){
				dp[p][i] = (f(v[p][i], v_rev[p][i], false) + 1) % m;
				visited[p]++;
			}
			next=(next*dp[p][i]) % m;
		}
	}else{//pに隣接する全ての辺についてdpが確定したら
		if(visited[p]==k){//累積和未計算
			ru[p][0]=dp[p][0];
			reg(i,1,k-1)ru[p][i]=(dp[p][i]*ru[p][i-1]) % m;
			ru2[p][k-1]=dp[p][k-1];
			irep(i,k-1)ru2[p][i]=(dp[p][i]*ru2[p][i+1]) % m;
			visited[p]+=10;
		}
		if(begin){//最初だけは全方向の積が答え
			next=ru[p][k-1];
		}else{
			if(rev>0)next=ru[p][rev-1];
			if(rev<k-1)next=(next*ru2[p][rev+1]) % m;
		}
	}
	return next;
}

int main(void){
	cin>>n>>m;
	rep(i,n-1){
		int x,y;
		cin>>x>>y;
		v[x].push_back(y);
		v[y].push_back(x);
		v_rev[x].push_back(v[y].size()-1);
		v_rev[y].push_back(v[x].size()-1);
		dp[x].push_back(-1);
		dp[y].push_back(-1);
		ru[x].push_back(-1);
		ru[y].push_back(-1);
		ru2[x].push_back(-1);
		ru2[y].push_back(-1);
	}
	//
	reg(i,1,n){
		cout<<f(i,1e9,true)<<endl;
	}
	return 0;
}

