void dfs(int v,int pre){
  for(int nv : g[v]){
    if(nv==pre)continue;
    dfs(nv,v);
  }
  dp[v]=1;
  for(int nv : g[v]){
    if(nv==pre)continue;
    (dp[v]*=(dp[nv]+1))%=mod;
  }
