  int sz=ch.size();
  vector<ll> prf(sz+1,1);
  vector<ll> suf(sz+1,1);
  rep(i,sz){
    prf[i+1]=prf[i]*(dp[ch[i]]+1)%mod;
  }
  for(ll i=sz-1;i>=0;i--){
    suf[i]=suf[i+1]*(dp[ch[i]]+1)%mod;
  }

  rep(i,sz){
    ll nt0=(((t0+1)*prf[i])%mod)*suf[i+1]%mod;
    dfs2(ch[i],v,nt0);
  }
}

