using namespace std;
using ll=long long;
using Graph=vector<vector<int>>;
#define INF 1000000000000000000
#define MOD 1000000007

ll M;
map<int,map<int,ll>> m;
vector<ll> ans;

ll solve(Graph &G,int v,int p){
  ll ret=1;
  bool flag=false;
  for(auto nv:G.at(v)){
    if(nv==p){
      continue;
    }
    flag=true;
    ret*=(solve(G,nv,v)+1);
    ret%=M;
  }
  if(flag){
    return m[p][v]=ret;
  }else{
    return m[p][v]=1;
  }
}

void dfs(Graph &G,int v,int p){
  int n=G.at(v).size();
  vector<ll> left(n,1),right(n,1);
  for(int i=1;i<n;i++){
    left.at(i)=left.at(i-1)*(m[v][G.at(v).at(i-1)]+1)%M;
  }
  for(int i=n-2;i>=0;i--){
    right.at(i)=right.at(i+1)*(m[v][G.at(v).at(i+1)]+1)%M;
  }
  for(int i=0;i<n;i++){
    if(G.at(v).at(i)==p){
      continue;
    }
    m[G.at(v).at(i)][v]=(left.at(i)*right.at(i))%M;
  }
  for(int i=0;i<n;i++){
    if(G.at(v).at(i)==p){
      continue;
    }
    dfs(G,G.at(v).at(i),v);
  }
}

