    G.at(x).push_back(y);
    G.at(y).push_back(x);
  }

  ans.resize(N);
  ans.at(0)=solve(G,0,-1);
  dfs(G,0,-1);

  cout<<ans.at(0)<<endl;
  for(int i=1;i<N;i++){
    ans.at(i)=1;
    for(auto nv:m[i]){
      ans.at(i)*=nv.second+1;
      ans.at(i)%=M;
    }
    cout<<ans.at(i)<<endl;
  }
}

