void dfs_down(int u,int p=-1)
{
    down[u] = 1; /// color this node black

    for(int v:adj[u])
    {
        if(v!=p)
        {
            dfs_down(v,u);

            down[u] = mul(down[u],1+down[v]);
        }
    }

    int sz = adj[u].size();

    pref[u].resize(sz);
    suf[u].resize(sz);

    for(int i=0;i<sz;i++)
    {
        int prv = 1 , cur = 1;
        int v = adj[u][i];

        if(i != 0) prv = pref[u][i-1];
        if(v != p) cur = 1 + down[v];

        cur %= mod;

        pref[u][i] = mul(prv,cur);
    }

    for(int i=sz-1;i>=0;i--)
    {
        int prv = 1 , cur = 1;
        int v = adj[u][i];

        if(i != sz-1) prv = suf[u][i+1];
        if(v != p) cur = 1 + down[v];

        cur %= mod;

        suf[u][i] = mul(prv,cur);
    }
}

void dfs_up(int u,int p=-1)
{
    if(p == -1) up[u] = 1; /// as he has no brothers , initializing his answer

    int sz = (int)adj[u].size();
    for(int i=0;i<sz;i++)
    {
        int v = adj[u][i];

        if(v!=p)
        {
            int way1 = 1 ; /// parent is white
            int way21 = 1 , way22 = 1;

            if(i != 0)    way21 = pref[u][i-1];
            if(i != sz-1) way22 = suf[u][i+1];

            up[v] = way1 + mul(up[u],mul(way21,way22));
            up[v] %= mod;

            dfs_up(v,u);
        }
    }
}

void INIT(int len)
{
    adj = VVI(len);
    pref = VVI(len);
    suf = VVI(len);
    down = VI(len);
    up = VI(len);
}

