struct SegTree{
    vector<ll> t;

    void build(ll v, ll l, ll r, vector<ll> &o){
        if(l + 1 == r){
            t[v] = o[l];
            return;
        }
        ll mid = (l + r) >> 1;
        build(v << 1, l, mid, o);
        build(v << 1 | 1, mid, r, o);
        t[v] = t[v << 1] * t[v << 1 | 1] % m;
    }

    SegTree(){}

    SegTree(vector<ll> &o){
        if(!o.empty()) {
            t.resize(o.size() * 2);
            build(1, 0, o.size(), o);
        }
    }

    ll q(ll v, ll l0, ll r0, ll l, ll r){
        if(l >= r) return 1;
        if(l == l0 && r == r0) return t[v];
        ll mid = (l0 + r0) >> 1;
        return q(v << 1, l0, mid, l, min(mid, r)) * q(v << 1 | 1, mid, r0, max(mid, l), r) % m;
    }
};

