const int NMAX = 1e5 + 5;

int n, MOD;
vector<int> adj[NMAX];
int down[NMAX];
int up[NMAX];

void mul(int &a, int b) {
  a = (1LL * a * b) % MOD;
}

void add(int &a, int b) {
  a = (a + b) % MOD;
}

int prev(const vector<int> &v, int i) {
  return (i == 0) ? 1 : v[i - 1];
}

int next(const vector<int> &v, int i) {
  return (i == (int)v.size() - 1) ? 1 : v[i + 1];
}

void dfs(int node, int parent, int type) {
  if (type == 0) {
    down[node] = up[node] = 1;
    for (int &x : adj[node]) {
      if (x == parent) {
        continue;
      }
      dfs(x, node, type);
      mul(down[node], down[x] + 1);
    }
    return;
  }
  vector<int> pref_prod(adj[node].size() - 1, 1);
  vector<int> suff_prod(adj[node].size() - 1, 1);
  for (int i = 0, idx = 0; i < (int)adj[node].size(); ++i) {
    int x = adj[node][i];
    if (x != parent) {
      pref_prod[idx] = 1LL * prev(pref_prod, idx) * (down[x] + 1) % MOD;
      ++idx;
    }
  }
  for (int i = adj[node].size() - 1, idx = i - 1; i >= 0; --i) {
    int x = adj[node][i];
    if (x != parent) {
      suff_prod[idx] = 1LL * next(suff_prod, idx) * (down[x] + 1) % MOD;
      --idx;
    }
  }
  for (int i = 0, idx = 0; i < (int)adj[node].size(); ++i) {
    int x = adj[node][i];
    if (x != parent) {
      add(up[x], (1LL * up[node] * prev(pref_prod, idx) % MOD) * next(suff_prod, idx) % MOD);
      ++idx;
      dfs(x, node, type);
    }
  }
}

