    //累積積を求めるよ
    vector<ll> l(sizev), r(sizev);
    ll sum=1;
    for(int i=0;i<sizev;i++){
        sum*=dp[v[k][i]]+1;
        sum%=MOD;
        l[i]=sum;
    }
    sum=1;
    for(int i=sizev-1;i>=0;i--){
        sum*=dp[v[k][i]]+1;
        sum%=MOD;
        r[i]=sum;
    }
    /*
    cout<<k<<"\n";
    debug(l);
    debug(r);
    */
    //累積積を求めたよ
    for(int i=0;i<sizev;i++){
        if(v[k][i]==prev)continue;
        //それぞれの子供に対してその子供の情報を除いた組み合わせをO(1)で渡す
        dp[k]=1;
        if(i){
            dp[k]*=l[i-1];
            dp[k]%=MOD;
        }
        if(sizev>i+1){
            dp[k]*=r[i+1];
            dp[k]%=MOD;
        }
        dfs2(v[k][i],k);
    }
}
