int n, M;
vector<vector<int>> g;
vector<int> dp;

void add_self(int &a, int b)
{
	a += b;
	a %= M;
}

void mul_self(int &a, int b)
{
	a = (ll)a * b % M;
}

void dfs(int s, int par)
{
	// dugbe(s);
	// dugbe(par);
	dp[s] = 1;
	for (auto e: g[s])
	{
		if (e == par)
			continue;
		dfs(e, s);
		mul_self(dp[s], 1 + dp[e]);
	}

	// dp[s] now stores the no. of black trees where
	// 's' is the root.
}

void sum_dp(int s, int par, int val)
{
	// cout << "s : " << s << " par : " << par << " val : " << val << "\n";

	// val is the number of black trees where 's' is a leaf.

	int len = (int)g[s].size();
	vector<int> lef(len + 1, 1), rig(len + 1, 1);
	forl(i, 1, len + 1)
	{
		int e = g[s][i - 1];
		lef[i] = lef[i - 1];
		if (e != par)
			mul_self(lef[i], 1 + dp[e]);
		// lef[k] represents pi(dp[k - 1])
	}
	for (int i = len - 1; i >= 0; --i)
	{
		int e = g[s][i];
		rig[i] = rig[i + 1];
		if (e != par)
			mul_self(rig[i], 1 + dp[e]);
		// rig[k] represents rev_pi(dp[k])
	}
	// forl(i, 0, len + 1)
	// {
	// 	cout << i << " : " << lef[i] << " " << rig[i] << "\n";
	// }
	forl(i, 0, len)
	{
		int e = g[s][i];
		if (e == par)
			continue;

		int rem_prod = lef[i];
		mul_self(rem_prod, rig[i + 1]);
		mul_self(rem_prod, val);

		mul_self(dp[e], rem_prod + 1);

		sum_dp(e, s, rem_prod + 1);
	}
}

