void dfs1(int v, int from = -1){
  val[v] = 1;
  for(auto to : g[v]) if(to != from) {
    dfs1(to, v);
    val[v] *= val[to];
    val[v] %= m;
  }
  val[v] += 1;
}

void dfs2(int v, int from = -1, long pre = 1){
  ans[v] = pre * (val[v] - 1 + m) % m;
dbg(v,from,pre,val[v]);
  vector<int> tos;
  for(auto to : g[v]) if(to != from) tos.pb(to);

  int ts = tos.size();
  vector<long> ml(tos.size() + 1, 1), mr(tos.size() + 1, 1);
  rep(i,ts) ml[i+1] = (ml[i] * val[tos[i]]) % m;
  for(int i=ts-1; i>=0; i--) mr[i] = (mr[i+1] * val[tos[i]]) % m;

  rep(i,ts){
    dfs2(tos[i], v, pre * ml[i] * mr[i+1] + 1);
  }
}


