void dfs2(int s, int prev, vector<vector<int>>& graph, vector<ll>& dp, vector<ll>& ans, ll prev_comb) {
    vector<ll> values;
    vector<int> edges;
    for(auto next: graph[s]) {
        if(next != prev) {
            values.push_back(dp[next]);
            edges.push_back(next);
        }
    }

    int size = values.size();
    if(size == 0) return;

    vector<ll> prod_forward(size+2, 1), prod_backward(size+2, 1);
    for(int i=1; i<=size; i++) {
        prod_forward[i] = (1+values[i-1]) * prod_forward[i-1] % M;
        prod_backward[size-i+1] = (1+values[size-i]) * prod_backward[size-i+2] % M;
    }

    for(int i=1; i<=size; i++) {
        ans[edges[i-1]] =  (((prev_comb * prod_forward[i-1] %M) * prod_backward[i+1]) % M + 1) * values[i-1] % M;
        dfs2(edges[i-1], s, graph, dp, ans, (prod_forward[i-1] * prod_backward[i+1] % M + 1));
    }
}

