#define N_ 101000
long long D[N_], Mod, DD[N_];
vector<int>E[N_], Ch[N_];
int n, LL[N_], RR[N_], w[N_];
long long UP[N_];
void DFS(int a, int pp) {
	for (auto &x : E[a]) {
		if (x == pp)continue;
		DFS(x, a);
		Ch[a].push_back(x);
	}
	long long s = 1;
	for (auto &x : Ch[a]) {
		s = s*D[x]%Mod;
	}
	D[a] = (s + 1) % Mod;
}
void Go(int a, int pp, long long up) {
	if (a == 1) {
		DD[a] = D[a];
	}
	if (Ch[a].empty())return;
	int cnt = 0;
	for (auto &x : Ch[a]) {
		w[++cnt] = x;
	}
	long long s = 1;
	int i;
	LL[0] = RR[cnt + 1] = 1;
	for (i = 1; i <= cnt; i++) {
		s = s * D[w[i]] % Mod;
		LL[i] = s;
	}
	s = 1;
	for (i = cnt; i >= 1; i--) {
		s = s * D[w[i]] % Mod;
		RR[i] = s;
	}
	for (i = 1; i <= cnt; i++) {
		long long t = (LL[i - 1] * RR[i + 1] % Mod*up + 1) % Mod;
		UP[w[i]] = t;
		DD[w[i]] = ((D[w[i]] + Mod - 1)*t + 1) % Mod;
	}
	for (auto &x : Ch[a]) {
		Go(x, a, UP[x]);
	}
}
