using PII = pair<int, int>;
using LL = long long;

const int MOD = 1e9 + 7;
const int INF = 0x3f3f3f3f;
const LL LLINF = 0x3f3f3f3f3f3f3f3f;
const int MAX_N = 100005;

vector<int> G[MAX_N];
LL dp[MAX_N], dp2[MAX_N];

struct Solution {
    int N, M;

    void dfs1(int v, int p) {
        dp[v] = 1;
        for(int u : G[v]) {
            if(u != p) {
                dfs1(u, v);
                dp[v] = dp[v] * (dp[u] + 1) % M;
            }
        }
    }

    void dfs2(int v, int p) {
        int d = G[v].size();
        vector<LL> prefix(d, 1), suffix;

        for(int i : range(d)) {
            int u = G[v][i];
            prefix[i] = (u == p) ? dp2[v] + 1 : dp[u] + 1;
        }
        suffix = prefix;

        for(int i : range(1, d)) {
            prefix[i] = prefix[i] * prefix[i - 1] % M;
        }
        for(int i : range(d - 2, -1, -1)) {
            suffix[i] = suffix[i] * suffix[i + 1] % M;
        }

        for(int i : range(d)) {
            int u = G[v][i];
            if(u != p) {
                LL p = (i > 0) ? prefix[i - 1] : 1;
                LL s = (i < d - 1) ? suffix[i + 1] : 1;
                dp2[u] = p * s % M;
            }
        }

        for(int u : G[v]) {
            if(u != p) {
                dfs2(u, v);
            }
        }
    }

    Solution(int) {
        read(N, M);
        for(repeat(N - 1)) {
            int u, v;
            read(u, v);
            G[u].push_back(v);
            G[v].push_back(u);
        }

        dfs1(1, 0);
        dfs2(1, 0);
        for(int i : range(1, N + 1)) {
            print(dp[i] * (dp2[i] + 1) % M);
        }
    }
};

int main() {
    int T = 1;
    //cin >> T;
    for(int i = 1; i <= T; ++i) {
        ignore = Solution(i);
    }
    return 0;
}

