    int a,b;
    REP(i,N-1){
        cin >> a >> b;
        edge[--a].emplace_back(--b);
        edge[b].emplace_back(a);
    }
    dfs(0,-1);
    dfs_with_rerooting(0,-1,-1);


    for(auto a:ans){
        cout << a << bn;
    }
}

