long long int func(int pos, int pre){

	long long int ret = 1;

	for(int i = 0; i < E[pos].size(); i++){
		if(pre == E[pos][i].to){
			continue;
		}
		if(E[pos][i].S == -1){
			E[pos][i].S = func(E[pos][i].to, pos);
		}
		ret *= (E[pos][i].S + 1);
	}
	return ret;
}

