void DFS1(ll i,ll p)
{
    for(auto j:Adj[i])
        if(j!=p)
            DFS1(j,i) , mul_self(Dp1[i],Dp1[j]+1);

    ll W = Adj[i].size();

    Pref[i].resize(W);
    Suff[i].resize(W);

    for(ll k=0;k<W;k++)
    {
        ll j = Adj[i][k];
        Pref[i][k] = ( j != p ? Dp1[j] + 1 : 1 );
        if(k-1>=0)  mul_self(Pref[i][k],Pref[i][k-1]);
    }

    for(ll k=W-1;k>=0;--k)
    {
        ll j = Adj[i][k];
        Suff[i][k] = ( j != p ? Dp1[j] + 1 : 1 );
        if(k+1<W)   mul_self(Suff[i][k],Suff[i][k+1]);
    }
}

void DFS2(ll i,ll p)
{
    ll k = -1;
    ll W = Adj[i].size();

    for(auto j:Adj[i])
        if(k++,j!=p)
        {
            ll L = k > 0 ? Pref[i][k-1] : 1 ;
            ll R = k+1 < W ? Suff[i][k+1] : 1 ;

            Dp2[j] = 1 + mul( Dp2[i] , mul(L,R) );

            DFS2(j,i);
        }
}

