        }else{
            lmul[i]=(lmul[i-1]*(dp[v[id][i-1]]+1))%m;
        }
    }
    rmul[vs]=1;
    for(ll i=vs-1;i>=0;i--){
        if(v[id][i]==par){
            rmul[i]=(rmul[i+1]*(d_par+1))%m;
        }else{
            rmul[i]=(rmul[i+1]*(dp[v[id][i]]+1))%m;
        }
    }
    rep(i,0,vs-1){
        ll x=v[id][i];
        if(x==par)continue;
        ll res=(lmul[i]*rmul[i+1]%m)%m;
        dfs2(x,id,res);
    }
