void downPaths(int a, int parent)
{
    for (auto i : adj[a])
        if (i != parent)
        {
            downPaths(i, a);
            down[a] = (ll)(down[a] * (down[i] + 1)) % mod;
        }
}

void upPaths(int a, int parent)
{
    vector<int> children;
    for (int i : adj[a])
        if (i != parent)
            children.pb(i);

    int suffix[children.size() + 2], prefix[children.size() + 2];
    prefix[0] = suffix[children.size() + 1] = 1;

    for (int i = 0; i < children.size(); i++)
    {
        prefix[i + 1] = (ll)(prefix[i] * (down[children[i]] + 1)) % mod;
        suffix[children.size() - i] = (ll)(suffix[children.size() - i + 1] * (down[children[children.size() - i - 1]] + 1)) % mod;
    }

    for (int i = 0; i < children.size(); i++)
    {
        ll res = (prefix[i] * suffix[i + 2]) % mod;
        res = (ll)(res * up[a] + 1) % mod;
        up[children[i]] = res;
        upPaths(children[i], a);
    }
}

