void dfs1(int x,int last=-1){
    ll prod=1;
    for(auto to:edge[x]){
        if(to==last) continue;
        dfs1(to,x);
        prod=prod*dp1[to]%m;
    }
    dp1[x]=prod+1;dp1[x]%=m;
}
void dfs2(int x,int last=-1){
    if(last==-1) dp2[x]=1;
    vector<ll> lcnt(edge[x].size(),1);
    vector<ll> rcnt(edge[x].size(),1);
    for(ll i=0;i<(int)edge[x].size();i++){
        int to=edge[x][i];
        if(i-1>=0) lcnt[i]=lcnt[i-1];
        if(to==last) continue;
        lcnt[i]*=dp1[to];lcnt[i]%=m;
    }
    for(ll i=(int)edge[x].size()-1;i>=0;i--){
        int to=edge[x][i];
        if(i+1<rcnt.size()) rcnt[i]=rcnt[i+1];
        if(to==last) continue;
        rcnt[i]*=dp1[to];rcnt[i]%=m;
    }
    for(ll i=0;i<(int)edge[x].size();i++){
        int to=edge[x][i];
        if(to==last) continue;
        ll rest=1;
        if(i-1>=0) rest=rest*lcnt[i-1]%m;
        if(i+1<(int)edge[x].size()) rest=rest*rcnt[i+1]%m;
        dp2[to]=(dp2[x]*rest+1)%m;
        dfs2(to,x);
    }
