using namespace std;
typedef long long ll;

int n, m;
vector<int> g[100005];
vector<ll> dp[100005]; // indices correspond to g

ll solve(int s, int p) {
	ll cres = 1;
	for (int i = 0; i < g[s].size(); ++i) {
		int a = g[s][i];
		if (a == p) continue;
		if (dp[s][i] < 0) {
			dp[s][i] = solve(a, s);
		}
		assert(dp[s][i] >= 0);

		cres *= (dp[s][i] + 1); // can drop the entire subtree
		cres %= m;
	}
	return cres%m;
}

