			dp[i].push_back(-1);
		}
	}
	for (int i = 1; i <= n; ++i) {
		solve(i, -1);
	}
	for (int i = 1; i <= n; ++i) {
		ll res = 1;
		for (int j = 0; j < g[i].size(); ++j) {
			assert(dp[i][j] >= 0);
