void dfs1( ll v, ll p )
{
  used[v] = true;

  dp[v] = mint(1,M);

  for( auto u : G[v] ) if( u != p )
  {
    dfs1( u, v );

    dp[v] *= dp[u]+mint(1,M);
  }

  return;
}

void dfs2( ll v, ll p, mint par )
{
  used[v] = true;

  std::vector<mint> left( G[v].size()+1, mint( 1, M ) ), right( G[v].size()+1, mint( 1, M ) );

  rep( i, G[v].size() )
    left[i+1] = left[i]*(G[v][i]==p ? par+1 : dp[G[v][i]]+mint(1,M));

  for( int i = G[v].size()-1; i >= 1; --i )
    right[i-1] = right[i]*(G[v][i]==p ? par+1 : dp[G[v][i]]+mint(1,M));

  rep( i, G[v].size() ) if( G[v][i] != p )
    dfs2( G[v][i], v, left[i]*right[i] );

  dp[v] *= par+mint(1,M);

  return;
}

