ll solve(ll start, ll now, ll edge){ //nowが白の場合も含めた場合の数
    //if(dp.at(edge) != -1) return dp.at(edge);
    used.at(now) = true;
    ll ans=1;
    for(auto e : G.at(now)) {
        if(!used.at(e.fi)) {
            if(dp.at(e.se) != -1) (ans *= dp.at(e.se))%=M;
            else (ans *= solve(start,e.fi,e.se))%=M;
        }
    }
    if(start != now) (++ans)%=M;
    if(edge != MAX_N*2) dp.at(edge) = ans;
    used.at(now) = false;
    return ans;
}

