void update (int v, int p = -1) {
	for (int i = 0; i < g[v].size(); i++) {
		int to = g[v][i];
		if (to != p) {
			dp[to] = (dp[v] / (dp[to] + 1) + 1) * dp[to] % mod;
			update (to, v);
		}
	}
}

