const int MAX = 1E5 + 100;
int n, m;
vvi adj(MAX);
vi up(MAX), dp(MAX), dp2(MAX);

void DFS(int u, int p) {
	dp[u] = 1;
	for(int v : adj[u]) {
		if(v == p)
			continue;
		DFS(v, u);
		dp[u] = ((dp[v] + 1) * dp[u]) % m;
	}
}

void calc_up(int u, int p) {
	vi children;
	for(int v : adj[u]) {
		if(v == p)
			continue;
		children.pb(v);
	}
	int siz = sz(children);
	vi pref(siz + 1), suff(siz + 1);
	pref[0] = 1;
	suff[siz] = 1;
	for(int i = 0; i < siz; i++) {
		int v = children[i];
		pref[i + 1] = (pref[i] * (dp[v] + 1)) % m;
		//debug(u, i, pref[i + 1]);
	}
	for(int i = siz - 1; i >= 0; i--) {
		int v = children[i];
		suff[i] = (suff[i + 1] * (dp[v] + 1)) % m;
		//debug(u, i, suff[i + 1]);
	}
	for(int i = 0; i < siz; i++) {
		int v = children[i];
		up[v] = (pref[i] * suff[i + 1]) % m;
		up[v] = ((up[u] + 1) * up[v]) % m;
	}
	for(int v : children)
		calc_up(v, u);
}

