int gpref(int u, int i,int c){
	if(i-1 >= 0)
		return pref[u][c][i-1]%m;
	return 1;
}

int gsuf(int u, int i,int c){
	if(i+1 < suf[u][c].size())
		return suf[u][c][i+1]%m;
	return 1;
}

int dfs(int u, int p, int c){
	if(dp[u][c]  != -1) return dp[u][c]%m;
	dp[u][c] = 1;
	for(int v : adj[u]){
		if(v == p) continue;
		int res = 0;
		if(c == 0){//negro
			res = (dfs(v,u,0) + dfs(v,u,1))%m;
			dp[u][c] = (dp[u][c] * res) % m;
		}
		else{
			res = dfs(v,u,1)%m;
			dp[u][c] = (dp[u][c] * res)%m;
		}

		pref[u][c].pb(res);
		suf[u][c].pb(res);
	}
	//pref
	for(int i =1; i < pref[u][c].size(); i++) pref[u][c][i] = (pref[u][c][i] * pref[u][c][i-1])%m;
	for(int i = suf[u][c].size()-2; i >=0; i--) suf[u][c][i] = (suf[u][c][i] * suf[u][c][i+1])%m;
	return dp[u][c]%m;
}

void dfs2(int u, int p){
	//if(u!= 1){
	dp[u][0] = (dp[u][0] * (dp[p][0]+dp[p][1]) % m) %m;
	ans[u] = dp[u][0]%m;
	//}
	for(int i =0; i < adj[u].size(); i++){
		int v = adj[u][i];
		if(v == p) continue;
		int og = dp[u][0],og2 = dp[u][1];
		dp[u][0] = (gpref(u,i,0) * gsuf(u,i,0))%m;
		dp[u][1] = (gpref(u,i,1) * gsuf(u,i,1))%m;
		dfs2(v,u);
		dp[u][0] = og;
		dp[u][1] = og2;
	}
}

