void dfs1(int x,int fa){
	father[x]=fa;
	ll ret=1ll;
	for(int i=0;i<g[x].size();i++){
		int to=g[x][i];
		if(to==fa) continue;
		dfs1(to,x);
		ret=(ret*(dp[to][0]+1ll)%mod)%mod;
	}
	dp[x][0]=ret;
}

void dfs2(int x,int fa){
	vector <int> v1,v2; 
	for(int i=0;i<g[x].size();i++){
		int to=g[x][i];
		if(to==fa){
			v1.pb(1ll);
			continue;
		}
		v1.pb(dp[to][0]+1);
	}
	for(int i=1;i<g[x].size();i++) v1[i]=(v1[i-1]*v1[i])%mod;
	for(int i=g[x].size()-1;i>=0;i--){
		int to=g[x][i];
		if(to==fa){
			v2.pb(1ll);
			continue;
		}
		v2.pb(dp[to][0]+1); 
	}
	for(int i=g[x].size()-2;i>=0;i--) v2[i]=(v2[i+1]*v2[i])%mod;
	for(int i=0;i<g[x].size();i++){
		int to=g[x][i];
		if(to==fa) continue;
		ll res=1ll;
		if(i>0) res=(res*v1[i-1])%mod;
		if(i<g[x].size()-1) res=(res*v2[i+1])%mod;
		res=(res*dp[x][1])%mod;
		res=(res+1ll)%mod;
		dp[to][1]=res;
		dfs2(to,x);
	}
}

