ll M;
const ll border = 1e9 + 7;

vl below;
vvl adj;
vvl tree;

ll first_dfs(ll cur, ll parent) {
	ll foo = 1;

	for(auto it : adj[cur]) {
		if(it != parent) {
			foo *= first_dfs(it, cur) + 1;
			foo %= M;
			tree[cur].pb(it);
		}
	}

	below[cur] = foo;
	return foo;
}

vl res;
void second_dfs(ll cur, ll parent, ll value) {
	TR(cur);
	TR(parent);
	TR(value);
	res[cur] = value * below[cur];
	res[cur] %= M;

	if(sz(tree[cur]) == 0){
		return;
	}

	vl prefix(sz(tree[cur]));
	vl suffix(sz(tree[cur]));

	prefix[0] = 1;
	TR(prefix[0]);

	FOR(i,1,sz(tree[cur])) {
		prefix[i] = prefix[i-1] * (below[tree[cur][i-1]] + 1);
		prefix[i] %= M;
		TR(below[tree[cur][i-1]]);
		TR(prefix[i]);
	}

	suffix[sz(tree[cur]) - 1] = 1;
	TR(suffix[sz(tree[cur]) - 1]);

	FORD(i,0,sz(tree[cur]) - 1) {
		suffix[i] = suffix[i+1] * (below[tree[cur][i+1]] + 1);
		suffix[i] %= M;
		TR(suffix[i]);
	}

	FOR(i,0,sz(tree[cur])) {
		second_dfs(tree[cur][i], cur, (value * prefix[i] * suffix[i] + 1) % M );
	}
}

