long long dp[500005],fish,Ans[500005];
int nex[500005],las[500005],Arrive[500005],Con,N;
vector <long long> Son[100005],Sum[100005],Suf[100005];
void jt(int x,int y)
{
	Con++;
	nex[Con]=las[x];
	las[x]=Con;
	Arrive[Con]=y;
}
void dfs(int Now,int fa)
{
	dp[Now]=1;int cnt=0;
	for (int i=las[Now];i;i=nex[i])
	  {
	  	if (Arrive[i]!=fa)
	  	{
	  	  dfs(Arrive[i],Now);
	  	  cnt++;
		  dp[Now]=dp[Now]*(dp[Arrive[i]]+1)*1ll%fish;
		  Son[Now].push_back(Arrive[i]);
		  Suf[Now].push_back(0);
		  Sum[Now].push_back(0);
	    }
    }
    for (int i=0;i<cnt;i++)
     {
     	if (i==0) Sum[Now][i]=1;else Sum[Now][i]=Sum[Now][i-1];
     	Sum[Now][i]=Sum[Now][i]*1ll*(dp[Son[Now][i]]+1)%fish;
	 }
	for (int i=cnt-1;i>=0;i--)
	  {
	  	if (i==cnt-1)
	  	Suf[Now][i]=1;
	  	else Suf[Now][i]=Suf[Now][i+1];
	  	Suf[Now][i]=Suf[Now][i]*1ll*(dp[Son[Now][i]]+1)%fish;
	  }
}
void Change(int u,long long v)
{
	Ans[u]=dp[u]*1ll*(v+1)%fish;
	for (int i=Son[u].size()-1;i>=0;i--)
	{
		int Arr=Son[u][i];
		Change(Arr,((i==0)?1:Sum[u][i-1])*1ll*((i==(Son[u].size()-1))?1:Suf[u][i+1])%fish*(v+1)%fish);
	}
}
