typedef long long llong;
typedef vector<int> VI;
typedef vector<VI> VVI;

#define MAXN 100004
int N, MOD;
VI adj[MAXN];

inline int add(int x, int y) {
   return (x + y) % MOD;
}

inline int mult(int x, int y) {
   return (x * 1LL * y) % MOD;
}

int dp_down[MAXN];
VI prefix_dp_down[MAXN];
VI suffix_dp_down[MAXN];
void dfs1(int u, int p = 0) {
   for (int& v : adj[u]) {
      if (v == p) {
         // place parent as first adjacent... the rest with be children
         if (adj[u].front() != v)
            swap(adj[u].front(), v);
         break;
      }
   }

   dp_down[u] = 1;
   FOR(j, 1, SZ(adj[u])-1) {
      int v = adj[u][j];
      dfs1(v, u);
      dp_down[u] = mult(dp_down[u], 1 + dp_down[v]);
   }

   prefix_dp_down[u].push_back(1);
   for(int j = 1; j < SZ(adj[u]); ++j) {
      int v = adj[u][j];
      prefix_dp_down[u].push_back(
         mult(prefix_dp_down[u].back(), 1 + dp_down[v])
      );
   }
   suffix_dp_down[u].push_back(1);
   for (int j = SZ(adj[u])-1; j >= 1; --j) {
      int v = adj[u][j];
      suffix_dp_down[u].push_back(
         mult(suffix_dp_down[u].back(), 1 + dp_down[v])
      );
   }
}

int ans[MAXN];
void dfs2(int u, int p = 0, int up_factor = 1) {
   ans[u] = up_factor * dp_down[u];

   for(int j = 1; j < SZ(adj[u]); ++j) {
      int v = adj[u][j];
      dfs2(v, u,
           add(1,
               mult(up_factor,
                    mult( prefix_dp_down[u][j-1],
                          suffix_dp_down[u][ SZ(adj[u])-j-1  ] ) )
           )
      );
   }

}

