using namespace std;

vector< vector<int> > adj;
vector< vector<int> > adj_count;
vector< long long > ans;
vector< bool > visited;
int M;

long long dfs1(int u) {
  visited[u] = true;
  long long acc = 1;
  for (auto i=0; i< adj[u].size(); i++) {
    auto v = adj[u][i];

    if (!visited[v]) {
      adj_count[u][i] = (dfs1(v) + 1) % M;
      acc = ( acc *  adj_count[u][i] ) % M;
    }
  }

  return acc;
}

void dfs2(int u, long long father) {
  visited[u] = true;

  int le = adj[u].size();

  vector<long long> l( le+1, 1 );
  vector<long long> r( le+1, 1 );
  long long acc = 1;
  for(auto i=0; i<le; i++) {
    auto v = adj[u][i];
    if (visited[v]) adj_count[u][i] = father+1;
    acc = (acc * adj_count[u][i]) % M;
    l[i] = acc;
  }

  acc = 1;
  for(auto i=le-1; i >=0; i--) {
    acc = (acc * adj_count[u][i]) % M;
    r[i]= acc;
  }

  ans[u] = r[0];

  for(auto i=0; i<le; i++) {
    auto v = adj[u][i];
    auto lv = (i > 0)?(l[i-1]):(1);
    auto rv = (i <le-1)?(r[i+1]):(1);
    if (!visited[v])  dfs2(v,  (lv*rv)%M);
  }
}

int main() {
  int N;
  cin >> N >> M;

  adj.assign(N, {});
  adj_count.assign(N, {});
  ans.assign(N, 0);
  visited.assign(N, false);

  for(int i=0; i < N-1; i++) {
    int u, v;
    cin >> u >> v; u--; v--;
    adj[u].push_back(v);
    adj_count[u].push_back(0);
    adj[v].push_back(u);
    adj_count[v].push_back(0);
  }

  dfs1(0);
  visited.assign(N, false);
  dfs2(0, 0);
  for(auto i=0; i<N; i++) cout << ans[i] << endl;
  return 0;
}

