// g[vi] = 1 + (pref[i-1]*suff[i+1]*g[u])
// Why ? either you color the parent or not
//
// pref[i] = (1 + f[v1])*(1 + f[v2])*....*(1 + f[vi])
// suff[i] = (1 + f[vi])*(1 + f[vi+1])*....*(1 + f[vn])
// where v1, v2, .. vn are childs of u
// base case f[leave] = 1, g[root] = 1

const int N = (int)1e5 + 10;
int n, m;
vector <vector <int>> adj;
vector <bool> vis;
vector <int> post_order, pre_order;
int f[N], g[N];
int pref[N], suff[N];

int mul(int a, int b) {
   return int(1ll*a*b % m);
}
int add(int a, int b) {
   return (a + b)%m;
}

void dfs(int u, int pr) {
   vis[u] = true;
   pre_order.push_back(u);
   for (vector <int>::iterator it = adj[u].begin(); it != adj[u].end(); ++it) {
      int v = *it;
      if (v == pr) {
         adj[u].erase(it);
         break;
      }
   }
   for (int v : adj[u])
      if (!vis[v]) dfs(v, u);
   post_order.push_back(u);
}

void solve() {
   vis.assign(n, false);
   dfs(0, -1);

   for (int u : post_order) {
      f[u] = 1;
      for (int v : adj[u])
         f[u] = mul(f[u], add(1, f[v]));
   }

   for (int u : pre_order) {
      if (u == 0) g[u] = 1;

      for (int i = 0; i < (int)adj[u].size(); ++i) {
         int v = adj[u][i];
         if (i == 0)
            pref[i] = add(1, f[v]);
         else
            pref[i] = mul(pref[i-1], add(1, f[v]));
      }
      for (int i = (int)adj[u].size() - 1; i >= 0; --i) {
         int v = adj[u][i];
         if (i == (int)adj[u].size() - 1)
            suff[i] = add(1, f[v]);
         else
            suff[i] = mul(suff[i+1], add(1, f[v]));
      }
      for (int i = 0; i < (int)adj[u].size(); ++i) {
         int v = adj[u][i];
         int down = 1;
         if (i)
            down = mul(down, pref[i-1]);
         if (i != (int)adj[u].size() - 1)
            down = mul(down, suff[i+1]);

         g[v] = add(1, mul(down, g[u]));
      }
   }

   for (int i = 0; i < n; ++i) {
      cout << mul(f[i], g[i]) << '\n';
   }
}

