  ll combinations = 1;
  for (auto& ncid : G[cur]) {
    int n = get<0>(ncid);
    if (n == last) continue;
    ll c = dfs(n, cur);
    get<1>(ncid) = c;
    combinations = mul(combinations, add(c, 1));
  }
  return combinations;
}

void dfs2(int cur, int last, ll lcc)
{
  static Segtree<ll, 100000, &mul, 1> tree;

  tree.init();
  for (auto& ncid : G[cur]) {
    int n = get<0>(ncid);
    ll c;
    if (n == last) {
      c = lcc;
    }
    else {
      c = get<1>(ncid);
    }
    get<2>(ncid) = tree.add(add(c, 1));
  }
  // printf("tree.build()\n");
  tree.build();

  for (auto& ncid : G[cur]) {
    int n = get<0>(ncid);
    if (n == last) continue;
    int i = get<2>(ncid);
    ll cnc = mul(tree.query(0, i), tree.query(i+1, G[cur].size()));
    get<3>(ncid) = cnc;
  }
  ans[cur] = tree.query(0, G[cur].size());
  for (auto& ncid : G[cur]) {
    int n = get<0>(ncid);
    if (n == last) continue;
    ll cnc = get<3>(ncid);
    dfs2(n, cur, cnc);
  }
}

