		cin >> x >> y;
		x--; y--;
		childs[x].push_back(y);
		childs[y].push_back(x);
	}
	treeconstruct();
	DP0.resize(N,-1);
	cout << dp0(0) << endl;
	DP1.resize(N,-1);
	for (ll node = 1; node < N; node++) {
		ll ans = ((dp1(node)+1) * dp0(node)) % M;
		cout << ans << endl;
	}
	return 0;
}

