        L[0] = 1;
        for(int i = 1; i < len; i++){
            L[i] = L[i - 1]*(down[v[nod][i - 1]] + 1)%mod;
        }

        R[len - 1] = 1;
        for(int i = len - 2; i >= 0; i--){
            R[i] = R[i + 1]*(down[v[nod][i + 1]] + 1)%mod;
        }

        for(int i = 0; i < len; i++){

            int it = v[nod][i];

            up[it] = (up[nod] + 1)*L[i]%mod*R[i]%mod;

            dfs2(it,nod);
        }
    }


