std::vector<long long> topo;
std::vector<long long> res;
long long dfs(long long num)//sorts topologically and evaluates number of ways
{
	vis[num]=1;
	long long len  = 0;
	ways[num]=1;
	for(auto it:g[num])
	{
		if(!vis[it])
		{
			par[it]=num;
			ll tmp=(1+dfs(it));
			ways[num]=pro(ways[num],(tmp%mod));
			if(tmp%mod==0){++len;}
			else{res[num]=((res[num]*ways[it])%mod);}
		}
	}
	if(len>1){res[num]=0;}
	topo.pb(num);
	return ways[num];
}
pii eu(long long a,long long b)//extended eucledian to find inverse modulo coprime numbers needn't be prime
{
	if(a==0){return {0,1};}
	if(b==0){return {1,0};}
	long long q=(a/b),r=(a%b);
	pii t=eu(b,r);
	return {t.y,((t.x)-(q*(t.y)))};

}
long long inv(long long num)
{
	if(__gcd(num,mod)!=1){return 0;}
	pii ans=eu(num,mod);
	ans.x=((((ans.x)%mod)+mod)%mod);
	return ans.x;
}
