	dp[0]=ways[0];
	for(auto it:topo)
	{
		if(it==0){continue;}
		long long p=par[it];
		long long den=((1+ways[it])%mod),num=dp[p];long long g=__gcd(mod,den);
		if(den==0)
		{
			ll mult=((res[p]+1)%mod);
			res[it]=pro(res[it],mult);
			dp[it]=pro(ways[it],mult);
			continue;
