		if(g!=1){
			den/=g;
			num/=g;
		}
		ll mult=(pro(num,inv(den))+1)%mod;
		res[it]=((res[it]*mult)%mod);
		dp[it]=pro(ways[it],mult);
	}
	for(auto it:dp){cout<<it<<"\n";}
}
