ll memo[100100],calc[100100];
bool done[100100];

ll treedp(int v, int p){
	int i;
	ll t=1ll;
	if(!(d[v]<0)){
		return memo[v];
	}
	d[v] = d[p]+1;
	pr[v] = p;
	for(i=(g[v].l_ength()-1); i>=0; --i){
		if(g[v][i] == p){
			continue;
		}
		calc[g[v][i]] = t;
		mul_mod(t,(treedp(g[v][i],v)+1)%mod);
		mul_mod(memo[v],(treedp(g[v][i],v)+1)%mod);
	}
	t = 1ll;
	for(i=0; i<g[v].l_ength(); ++i){
		if(g[v][i] == p){
			continue;
		}
		mul_mod(calc[g[v][i]],t);
		mul_mod(t,(treedp(g[v][i],v)+1)%mod);
	}
	return memo[v];
}

ll solve(int v){
	if(done[v]){
		return calc[v];
	}
	done[v] = true;
	if(v == 0){
		calc[v] = 0ll;
