using namespace std;
typedef long long ll;

int n,m;
vector<vector<int>> tree;
vector<ll> node; // iを根とする部分木でiが黒に塗られる組数
vector<ll> ans;

void dfs1(int v, int p = -1) {
    ll res = 1;
    for (int &u : tree[v]) {
        if (u == p) continue;
        dfs1(u, v);
        res *= (node[u] + 1) % m;
        res %= m;
    }
    node[v] = res;
}

void dfs2(int v, ll d_par, int p = -1) {
    // v における答えの計算
    ans[v] = 1;
    for (int &u : tree[v]) {
        if (u == p) {
            ans[v] *= (d_par + 1) % m;
            ans[v] %= m;
        }
        else {
            ans[v] *= (node[u] + 1) % m;
            ans[v] %= m;
        }
    }
    // 左右からの累積演算を用いて子に送る d_par の計算
    // lf[i] : [:i-1]の演算結果
    // ri[i] : [i+1:]の演算結果
    int e = 1; // 演算の単位元 ( maxの場合 -INF )
    vector<ll> lf(tree[v].size(), e), ri(tree[v].size(), e);
    for (int i = 1; i < tree[v].size(); i++) {
        if (tree[v][i - 1] == p) continue;
        lf[i] = ((node[tree[v][i - 1]] + 1) % m) * lf[i - 1] % m;
    }
    for (int i = tree[v].size() - 2; i >= 0; i--) {
        if (tree[v][i + 1] == p) continue;
        ri[i] = ((node[tree[v][i + 1]] + 1) % m) * ri[i + 1] % m;
    }
    for (int i = 0; i < tree[v].size(); i++) {
        if (tree[v][i] == p) continue;
        dfs2(tree[v][i], (lf[i] * ri[i] % m) * (p >= 0 ? (d_par + 1) % m : e) % m, v);
    }
}

