class amint{
    public:
        long long x;
        static long long mod;
        static void set_mod(long long m) { mod = m; }

    amint(long long _x = 0) : x((_x%mod+mod)%mod) {}

    amint operator-() const{
        return amint(-x);
    }
    amint& operator+=(const amint& a){
        if((x += a.x) >= mod) x -= mod;
        return *this;
    }
    amint& operator-=(const amint& a){
        if((x += mod-a.x) >= mod) x -= mod;
        return *this;
    }
    amint& operator*=(const amint& a){
        (x *= a.x) %= mod;
        return *this;
    }
    amint operator+(const amint& a) const{
        amint res(*this);
        return res+=a;
    }
    amint operator-(const amint& a) const{
        amint res(*this);
        return res-=a;
    }
    amint operator*(const amint& a) const{
        amint res(*this);
        return res*=a;
    }
    amint pow(long long x) const{
        if(!x) return 1;
        amint a = pow(x>>1);
        a *= a;
        if(x&1) a *= *this;
        return a; 
    }
    amint inv() const{
        long long a = x, b = mod, u = 1, v = 0, t;
        while(b > 0){
            t = a / b;
            swap(a -= t * b, b);
            swap(u -= t * v, v);
        }
        return amint(u);
    }
    amint& operator/=(const amint& a){
        return (*this) *= a.inv();
    }
    amint operator/(const amint& a) const{
        amint res(*this);
        return res/=a;
    }
    friend istream& operator>>(istream& is, amint& m){
        long long x; is >> x; m = x;
        return is;
    }
    friend ostream& operator<<(ostream& os, const amint& m){
        os << m.x; return os;
    }
};
