#include<bits/stdc++.h>
using namespace std;
#define ll long long int
#define white first
#define black second
#define pi pair<int, int>

int M;

pi dfsBottomUp(vector<int> edges[], int sv, int parent, ll dp[][2]){

    // If we paint the current node as white,
    // then all of its children must be white as well
    // If we paint the current node as black,
    // then the children can be either black or white

    pi ans;
    ll white = 1, black = 1;
    for(int child: edges[sv]){
        if(child == parent)
            continue;
        pi childAns = dfsBottomUp(edges, child, sv, dp);
        ll childBlack = childAns.black,
           childWhite = childAns.white;
        white = (white*childWhite);
        black = (black*(childBlack + childWhite));
    }

    ans.black = black;
    ans.white = white;
    dp[sv][0] = white;
    dp[sv][1] = black;
    return ans;
}

void dfsTopDown(vector<int> edges[], int sv, int parent,
                ll dp[][2], ll ans[], ll wp, ll bp){

    ll w, b;
    if(sv == 0){
        w = dp[0][0];
        b = dp[0][1];
    }
    else{
        ll ww = wp/dp[sv][0];
        ll bb = bp/(dp[sv][0] + dp[sv][1]);
        w = ww*dp[sv][0];
        b = dp[sv][1]*(ww + bb);
    }
    ans[sv] = b;

    for(int child: edges[sv]){
        if(child == parent)
            continue;
        dfsTopDown(edges, child, sv, dp, ans, w, b);
    }

}

