using Graph = adjacency_list<nullptr_t>;

lli M;
lli mult_modm(lli a, lli b) {
  return (a * b) % M;
}
using Product = segment_tree<lli, decltype(&mult_modm)>;

void solve(int N, Graph const &G) {
  auto const tree = make_rooted_tree(G, 0);
  vector<Product> dr;
  REP(u, N) {
    dr.push_back(make_segment_tree(mult_modm, 1LL, 1+tree.children[u].size()));
  }
  RREP(i, tree.size) {
    size_t u = tree.topo[i];
    REP(j, tree.children[u].size()) {
      size_t v = tree.children[u][j];
      dr[u].update(j, dr[v].query() + 1);
    }
  }

  vector<lli> dpar(N);
  dpar[0] = 0;
  REP(i, N-1) {
    size_t u = tree.topo[i];
    REP(j, tree.children[u].size()) {
      size_t v = tree.children[u][j];
      lli lhs = dr[u].query(0, j), rhs = dr[u].query(j+1, tree.children[u].size());
      dpar[v] = mult_modm(dpar[u]+1, mult_modm(lhs, rhs));
    }
  }
  REP(u, N) {
    cout << mult_modm(dr[u].query(), dpar[u]+1) << endl;
  }
}

