vector<vector<int>> g, pref, suff;
vector<int> dp, ans;

void dfs1(int v, int p = -1) {
	pref[v].resize(g[v].size(), 1);
	suff[v].resize(g[v].size(), 1);
	for (int i = 0; i < g[v].size(); i++) {
		int u = g[v][i];
		if (u != p) {
			dfs1(u, v);
			dp[v] = dp[v] * (dp[u] + 1) % MOD;
		}
	}
	for (int i = 0, j = (int) g[v].size() - 1; i < g[v].size(); i++, j--) {
		int u1 = g[v][i];
		int u2 = g[v][j];
		if (u1 != p) {
			pref[v][i] = (i ? pref[v][i - 1] : 1) * (dp[u1] + 1) % MOD;
		}
		else {
			pref[v][i] = (i ? pref[v][i - 1] : 1);
		}
		if (u2 != p) {
			suff[v][j] = (j != (int)g[v].size() - 1 ? suff[v][j + 1] : 1) * (dp[u2] + 1) % MOD;
		}
		else {
			suff[v][j] = (j != (int)g[v].size() - 1 ? suff[v][j + 1] : 1);
		}
	}
}

void dfs2(int v, int p = -1, int up = 0) {
	ans[v] = (up + 1) * dp[v] % MOD;
	for (int i = 0; i < g[v].size(); i++) {
		int u = g[v][i];
		if (u != p) {
			int val = (up + 1) * (i ? pref[v][i - 1] : 1) % MOD;
			val = val * (i == (int)g[v].size() - 1 ? 1 : suff[v][i + 1]) % MOD;
			dfs2(u, v, val);
		}
	}
}

