void dfs0(int cur, int pre, vector<ll> &res, const Graph &G, const int M) {
    for (int nx : G[cur]) {
        if (nx == pre) continue;
        dfs0(nx, cur, res, G, M);
        (res[cur] *= res[nx] + 1) %= M;
    }
}

void dfs1(int cur, int pre, ll pass, vector<ll> &res, const Graph &G, const int M) {
    (res[cur] *= pass + 1) %= M;
    int len = G[cur].size();
    vector<ll> pro0(len+1), pro1(len+1);
    pro0[0] = pro1[len] = 1;
    for (int i=1; i<len+1; ++i) {
        if (G[cur][i-1] == pre) pro0[i] = pro0[i-1] * (pass + 1) % M;
        else pro0[i] = pro0[i-1] * (res[G[cur][i-1]] + 1) % M;
    }
    for (int i=len-1; i>=0; --i) {
        if (G[cur][i] == pre) pro1[i] = pro1[i+1] * (pass + 1) % M;
        else pro1[i] = pro1[i+1] * (res[G[cur][i]] + 1) % M;
    }
    for (int i=0; i<len; ++i) {
        int nx = G[cur][i];
        if (nx == pre) continue;
        dfs1(nx, cur, pro0[i] * pro1[i+1] % M, res, G, M);
    }
}

void solve() {
    int N, M;
    cin >> N >> M;
    Graph G(N);
    for (int i=0; i<N-1; ++i) {
        int x, y;
        cin >> x >> y;
        G[x-1].push_back(y-1);
        G[y-1].push_back(x-1);
    }

    vector<ll> res(N, 1);
    dfs0(0, -1, res, G, M);
    dfs1(0, -1, 0, res, G, M);
    for (ll x : res) cout << x << '\n';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout << fixed << setprecision(20);

    solve();

