struct Node{
    int no;
    int par;
    int sum;
    int top;
    vector<Node*> child;
    void build(int i){
        no=i;par=i;sum=0;top=0;
    }
    vector<int> left,right;
    map<int,int> pos;
};
void dfs(Node& node){
    int n=node.child.size();
    if(n==1&&node.par!=node.no){
        node.sum=1;
        return;
    }
    int sum=1;
    rep(i,n){
        if(node.child[i]->no!=node.par){
            dfs(*node.child[i]);
            sum*=node.child[i]->sum+1;
            sum%=MOD;
        }
        node.left[i+1]=sum;
    }
    node.sum=sum;
    sum=1;
    for(int i=n-1;i>=0;--i){
        if(node.child[i]->no!=node.par){
            dfs(*node.child[i]);
            sum*=node.child[i]->sum+1;
            sum%=MOD;
        }
        node.right[i+1]=sum;
    }
}
