ll MOD;

const int MAX_N = 112345;
vector<int> g[MAX_N];

ll dp1[MAX_N];
ll dp2[MAX_N];
int parent[MAX_N];

vector< int > childs[MAX_N];
vector< ll > prod_l[MAX_N];
vector< ll > prod_r[MAX_N];

ll calc_X(int v, int key) {
  int pos = lower_bound(ALL(childs[v]), key) - childs[v].begin();
  ll X = prod_l[v][pos] * prod_r[v][pos+1] % MOD;
  // cout << "MOD=" << MOD << endl;
  // pv(ALL(childs[v]));
  // pv(ALL(prod_l[v]));
  // pv(ALL(prod_r[v]));
  // cout << "calc X=" << X << endl;
  return X;
}

void ready_X(int v, int prev) {
  vector< pair<int, ll> > c;
  for (int u : g[v])  {
    if (u != prev) {
      c.push_back({u, 1+dp1[u]});
    } else {
      c.push_back({u, calc_X(u, v)});
    }
  }
  sort(ALL(c));
  int M = (int)c.size();
  vector<ll> l(M+1);
  vector<ll> r(M+1);
  l[0] = 1;
  for (int i = 0; i < M; i++) { l[i+1] = l[i] * c[i].second % MOD; }
  r[M] = 1;
  for (int i = M-1; i >= 0; i--) { r[i] = r[i+1] * c[i].second % MOD; }

  vector<int> child;
  REP(i, M) child.push_back(c[i].first);
  childs[v] = child;
  prod_l[v] = l;
  prod_r[v] = r;
}

void dfs1(int v, int prev) {
  parent[v] = prev;
  ll res = 1;
  for (int u : g[v]) if (u != prev) {
    dfs1(u, v);
    res *= (1 + dp1[u]);
    res %= MOD;
  }
  dp1[v] = res;
}

void dfs2(int v) {
  if (dp2[v] != -1) return;
  if (parent[v] == -1) {
    dp2[v] = dp1[v] % MOD;
    ready_X(v, -1);
    return;
  }
  dfs2(parent[v]);
  ll X = calc_X(parent[v], v);
  // ll X2 = dp2[parent[v]] / (1+dp1[v]);
  // cout << "actual   X=" << X << endl;
  // cout << "expected X=" << X2 % MOD << endl;
  ll res = 1;
  for (int u : g[v]) {
    if (u != parent[v]) {
      res *= (1+dp1[u]);
    } else {
      res *= (1+X);
    }
    res %= MOD;
  }
  dp2[v] = res;
  ready_X(v, parent[v]);
}

int main2() {
  REP(i, MAX_N) g[i].clear();
  CLR(dp1, 0);
  CLR(dp2, -1);
  REP(i, MAX_N) {
    childs[i].clear();
    prod_l[i].clear();
    prod_r[i].clear();
  }
  int N = nextInt();
  MOD = nextInt();

  REP(i, N-1) {
    int a = nextInt() - 1;
    int b = nextInt() - 1;
    g[a].push_back(b);
    g[b].push_back(a);
  }

  if (N==1) {
    cout << 1 % MOD << endl;
    return 0;
  }
  if (N==2) {
    cout << 2 % MOD << endl;
    cout << 2 % MOD << endl;
    return 0;
  }

  int root = -1;
  REP(i, N) if (g[i].size() >= 2) { root = i; break; }
  dfs1(root, -1);
  REP(i, N) {
    dfs2(i);
    printf("%d\n", (int)dp2[i]);
  }
  return 0;
}

