int dfs(int p, int x){
  if(dp[{p, x}]) return dp[{p, x}];
  long long int r = 1;
  for(int y: G[x]){
    if(y == p) continue;
    r = r * (1 + dfs(x, y)) % m;
  }
  return dp[{p, x}] = r;
}

