constexpr int MAXN = 100000;

vector<int> adj[MAXN + 2];
int dp[MAXN + 2], ans[MAXN + 2], M;

void dfs1(int u, int w) {
	dp[u] = 1;
	for(int v : adj[u]) {
		if(v != w) {
			dfs1(v, u);
			dp[u] = (ll)dp[u] * dp[v] % M;
		}
	}
	dp[u]++;
}

#define pb push_back

void dfs2(int u, int w) {
	int oldv = dp[u];
	ans[u] = (ll)(dp[u] + M - 1) * dp[w] % M;
	int sz = adj[u].size();
	int *head = new int[sz * 2], *tail = head + sz;
	head[0] = 1;
	for(int i = 0; i + 1 < sz; i++) {
		int v = adj[u][i];
		head[i + 1] = (ll)dp[v] * head[i] % M;
	}
	tail[sz - 1] = 1;
	for(int i = sz - 1; i > 0; i--) {
		int v = adj[u][i];
		tail[i - 1] = (ll)dp[v] * tail[i] % M;
	}
	for(int i = 0; i < sz; i++) {
		int v = adj[u][i];
		if(v != w) {
			dp[u] = ((ll)head[i] * tail[i] + 1) % M;
			dfs2(v, u);
		}
	}
	dp[u] = oldv;
}

