const ll MOD = 1e9 + 7;

int dx[4] = {-1, 0, 1, 0};
int dy[4] = {0, -1, 0, 1};

const int MAXN = 1e5 + 10;
vector<vector<int>> g(MAXN);
vector<unordered_map<int, ll>> dp(MAXN);

int N, M;

ll dfs(int x, int par) {
  auto it = dp[x].find(par);
  if (it != dp[x].end()) {
    return it->second;
  }

  ll rb = 1;
  for (int child : g[x]) {
    if (child != par) {
      rb = (rb * (1 + dfs(child, x))) % M;
    }
  }
  return dp[x][par] = rb;
}

