using namespace std;

long long MOD = 1000000007, n, m;
vector<long long> black, ans, parent;
vector<vector<long long>> adj;
vector<long long> vlist;

void solve(long long id) {
	vlist.push_back(id);
	black[id] = 1;

	for (auto p : adj[id]) {
		if (parent[p] == -1) {
			parent[p] = id;
			solve(p);
			black[id] = (black[id] * (black[p] + 1)) % MOD;
		}
	}
}


long long mul_inv(long long a, long long b)
{
	long long b0 = b, t, q;
	long long x0 = 0, x1 = 1;
	if (b == 1) return 1;
	while (a > 1) {
		q = a / b;
		if (b == 0) return -1;
		t = b, b = a % b, a = t;
		t = x0, x0 = x1 - q * x0, x1 = t;
	}
	if (x1 < 0) x1 += b0;
	return x1;
}

long long division(long long a, long long b, long long p) {		// (a / b) mod p = ((a mod p) * (b^(-1) mod p)) mod p
	long long ans, inv;

	if (a % b == 0) return a / b;
	inv = mul_inv(b, p);
	if (inv == -1) return 0;
	ans = ((a % p) * inv) % p;
	return ans;
}



int main()
{
	ios::sync_with_stdio(false);
	cin.tie(0);

	long long i, j, k, a, b, x, p, id;
	cin >> n >> MOD;
	adj.resize(n + 1);

	for (i = 0; i < n - 1; i++) {
		cin >> a >> b;
		adj[a].push_back(b);
		adj[b].push_back(a);
	}

	parent.assign(n + 1, -1);
	parent[1] = 0;
	black.resize(n + 1);
	solve(1);

	ans.resize(n + 1);
	ans[1] = black[1];
	for (i = 1; i < n; i++) {
		id = vlist[i];
		p = parent[id];
		x = (division(ans[p], black[id] + 1, MOD) + 1) % MOD;
		ans[id] = (x * black[id]) % MOD;
	}

	for (i = 1; i <= n; i++) cout << ans[i] << "\n";


	return 0;
}

