}
}
using unweighted_graph_n::UnWeightedGraph;
using unweighted_graph_n::make_unweighted_graph;

signed main(){
	int N, M; cin >> N >> M;
	auto g = make_unweighted_graph(N);
	rep(i, N-1) {
		int x, y; cin >> x >> y; x--, y--;
		g.add_edge(x, y);
		g.add_edge(y, x);
	}
	vector<ll> dp1(N, 1);
	auto dfs1 = [&](auto&& f, int v, size_t par = 1e9) -> ll {
		ll& res = dp1[v];
		for (auto x : g.e[v]) {
			if (x.to == par) continue;
			res *= f(f, x.to, v) + 1;
			res %= M;
		}
		return res;
	};
	dfs1(dfs1, 0);
	vector<ll> dp2(N, 1);
	auto dfs2 = [&](auto&& f, int v, size_t par = 1e9, ll d = 0) -> ll {
		ll& res = dp2[v];
		res = dp1[v] * (d + 1) % M;
		// dump(v, d);
		const size_t sz = g.e[v].size() + 1;
		vector<ll> sum1(sz, 1);
		vector<ll> sum2(sz, 1);
		{
			int i = 1;
			int j = 0;
			for (auto x : g.e[v]) {
				if (x.to == par) {
					sum1[i++] = d + 1;
					sum2[j++] = d + 1;
				} else {
					sum1[i++] = dp1[x.to] + 1;
					sum2[j++] = dp1[x.to] + 1;
				}
			}
		}
		reps(i, 1, sz) {
			sum1[i] *= sum1[i-1];
			sum1[i] %= M;
		}
		rrep(i, sz-1) {
			sum2[i] *= sum2[i+1];
			sum2[i] %= M;
		}
		// dump(v, sum1, sum2);
		{
			int i = -1;
			for (auto x : g.e[v]) {
				i++;
				if (x.to == par) continue;
				f(f, x.to, v, (sum1[i] * sum2[i + 1]) % M);
			}
		}
		return res;
	};
	dfs2(dfs2, 0);
	// dump(dp2);
	for (auto x : dp1) {
		assert(0 <= x && x < M);
	}
	for (auto x : dp2) {
		assert(0 <= x && x < M);
		cout << x << endl;
	}
	return 0;
}

