/* do your best */

void dfs1(int cur, int par, vector<vector<int>> &g, vector<lint> &dp) {
    lint ret = 1;
    for (auto nxt : g[cur]) {
        if (nxt == par) continue;
        dfs1(nxt, cur, g, dp);
        ret *= (dp[nxt] + 1);
        ret %= MOD;
    }
    dp[cur] = ret;
}

void dfs2(int cur, int par, vector<vector<int>> &g, vector<lint> &dp, vector<lint> &ans, lint Dpar) {
    lint ret = (Dpar + 1)%MOD;
    if (Dpar == -1) ret = 1;
    vector<int> chs;
    for (auto nxt : g[cur]) {
        if (nxt == par) continue;
        ret *= (dp[nxt] + 1);
        ret %= MOD;
        chs.push_back(nxt);
    }
    ans[cur] = ret;

    // 左右から累積
    size_t sz = chs.size();
    vector<lint> accLeft(sz + 2, 1);
    vector<lint> accRight(sz + 2, 1);
    for (int i = 1; i <= sz; i++) {
        accLeft[i] = (dp[chs[i - 1]] + 1);
        accRight[i] = (dp[chs[i - 1]] + 1);
    }

    for (int i = 1; i <= sz; i++) {
        accLeft[i] *= accLeft[i - 1];
        accLeft[i] %= MOD;
    }

    for (int i = sz; i >= 1; i--) {
        accRight[i] *= accRight[i + 1];
        accRight[i] %= MOD;
    }

    for (int i = 1; i <= sz; i++) {
        lint nxtDpar = accLeft[i - 1] % MOD * accRight[i + 1] % MOD;
        int nxt = chs[i - 1];
        if (Dpar != -1) {
        nxtDpar *= (Dpar + 1);
        nxtDpar %= MOD;
        }
        if (nxt == par) continue;
        dfs2(nxt, cur, g, dp, ans, nxtDpar);
    }
}

int main() {

    int n; cin >> n;
    cin >> MOD;
    vector<vector<int>> g(n);
    for (int i = 0; i < n - 1; i++) {
        int a, b; cin >> a >> b;
        a--;
        b--;
        g[a].push_back(b);
        g[b].push_back(a);
    }

    vector<lint> dp(n);
    vector<lint> ans(n);
    dfs1(0, -1, g, dp);
    dfs2(0, -1, g, dp, ans, -1);
    for (int i = 0; i < n; i++) {
        cout << ans[i] << endl;
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

ll n, m;
vector<vector<ll> > adj(100001);
vector<ll> dp, ans;

void dfs1(ll x, ll p) {
	for (ll c : adj[x]) {
		if (c == p) continue;
		dfs1(c, x);
		dp[x] *= dp[c] + 1; dp[x] %= m;
	}
	return;
}

void dfs2(ll x, ll p) {
	ll l = adj[x].size();
	vector<ll> cuml(l+2, 1);
	vector<ll> cumr(l+2, 1);
	for (ll i = 0; i < l; ++i) cuml[i+1] = (cuml[i] * (dp[adj[x][i]] + 1)) % m;
	for (ll i = l-1; i >= 0; --i) cumr[i+1] = (cumr[i+2] * (dp[adj[x][i]] + 1)) % m;
	ll pres_x = dp[x];
	for (ll i = 0; i < l; ++i)
	{
		ll c = adj[x][i];
		if (c == p) continue;
		ll pres_c = dp[c];
		dp[x] = (cuml[i] * cumr[i+2]) % m;
		dp[c] *= dp[x] + 1;
		dp[c] %= m;
		ans[c] = dp[c];
		dfs2(c, x);
		dp[x] = pres_x;
		dp[c] = pres_c;
	}
	return;
}

int main() {
	cin >> n >> m;
	dp.resize(n, 1);
	ans.resize(n, 0);
	for (ll i = 0; i < n-1; ++i)
	{
		ll a, b; cin >> a >> b;
		adj[a-1].push_back(b-1);
		adj[b-1].push_back(a-1);
	}
	dfs1(0, -1);
	ans[0] = dp[0];
	dfs2(0, -1);
	for (ll x : ans) cout << x << "\n";
	return 0;
}

