    return a;
}

int mul(int a, int b) {

    return ((ll)a * b) % mod;
}

int get(vector<int> bit, int x) {

    int ans = 1;
    for(int i = x; i > 0; i -= i & -i)
        ans = mul(ans, bit[i]);
    return ans;
}

void upd(vector<int> &bit, int x, int y) {

    for(int i = x; i <= bit.size(); i += i & -i)
        bit[i] = mul(bit[i], y);
}

void make_down(int u, int p) {

    down[u] = 1;
    for(int v: graph[u]) {
        if(v != p) {
            make_down(v, u);
            down[u] = mul(down[u], add(1, down[v]));
        }
    }
}

void make_up(int u, int p) {

    int n = graph[u].size();
    if(p != -1)
        n--;

    vector<int> arr(n);
    vector<int> pre(n);
    vector<int> suf(n);
    int br = 0;
    for(int v: graph[u])
        if(v != p)
            arr[br++] = v;

    for(int i = 0; i < n; i++) {
        int j = n - i - 1;
        pre[i] = add(1, down[arr[i]]);
        suf[j] = add(1, down[arr[j]]);
        if(i) {
            pre[i] = mul(pre[i], pre[i - 1]);
            suf[j] = mul(suf[j], suf[j + 1]);
        }
    }

    for(int i = 0; i < n; i++) {
        if(!i && i == n - 1)
            up[arr[i]] = add(1, up[u]);
        else if(!i)
            up[arr[i]] = add(1, mul(up[u], suf[i + 1]));
        else if(i == n - 1)
            up[arr[i]] = add(1, mul(up[u], pre[i - 1]));
        else
            up[arr[i]] = add(1, mul(up[u], mul(pre[i - 1], suf[i + 1])));
        make_up(arr[i], u);
    }
}

