  for (int i = 0; i < deg; i++) L[i + 1] = add(L[i], root(dp1[c[v][i]]));
  for (int i = deg - 1; i >= 0; i--) R[i] = add(R[i + 1], root(dp1[c[v][i]]));
  for (int i = 0; i < deg; i++){
    dp2[c[v][i]] = add(root(dp2[v]), add(L[i], R[i + 1]));
    dfs2(dp1, dp2, c, c[v][i]);
