    int N;
    vi bit;
    Binary_indexed_tree(int n):N(n){
        bit.resize(N+1,0);
    }
    void add(int x,int a){
        for(x;x<=N;x+=(x&-x)) bit[x]+=a;
    }
    ll sum(int x){
        ll ret=0;
        for(x;x>0;x-=(x&-x)) ret+=bit[x];
        return ret;
    }
    ll lower_bound(ll X){
        if(sum(N)<X) return -1;
        ll ret=0,memo=1,sum=0;
        while(memo*2<=N) memo*=2;
        while(memo>0){
            if(memo+ret<=N&&sum+bit[memo+ret]<X){
                sum+=bit[memo+ret];
                ret+=memo;
            }
            memo/=2;
        }
        return ret+1;
    }
};
struct Union_Find{
    ll N;
    vi par;
    vi siz;
    Union_Find(int n):N(n){
        par.resize(N);
        siz.resize(N,1);
        rep(i,0,N) par[i]=i;
    }
    ll root(ll X){
        if(par[X]==X) return X;
        return par[X]=root(par[X]);
    }
    bool same(ll X,ll Y){
        return root(X)==root(Y);
    }
    void unite(ll X,ll Y){
        X=root(X);
        Y=root(Y);
        if(X==Y) return;
        par[X]=Y;
        siz[Y]+=siz[X];
        siz[X]=0;
    }
    ll size(ll X){
        return siz[root(X)];
    }
};
long long modpow(long long a, long long n, long long mod) {
    long long res = 1;
    while (n > 0) {
        if (n & 1) res = res * a % mod;
        a = a * a % mod;
        n >>= 1;
    }
    return res;
}
vi fac,finv,inv;
void COMinit() {
    fac.resize(MAX);
    finv.resize(MAX);
    inv.resize(MAX);
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}
ll COM(ll n,ll r){
    if(n<r||n<0||r<0) return 0;
    return fac[n]*finv[r]%MOD*finv[n-r]%MOD;
}
void dfs(ll X,vii &edge,vector<bool> &F,vi &ans,ll M){
    F[X]=0;
    rep(i,0,edge[X].size()){
        ll Y=edge[X][i];
        if(F[Y]){
            dfs(Y,edge,F,ans,M);
            ans[X]*=ans[Y]+1;
            ans[X]%=MOD;
        }
    }
}
void reroot(ll X,vii &edge,vector<bool> &F,vi &ans,ll M,ll plus){
    F[X]=0;
    vi memo;
    rep(i,0,edge[X].size()){
        ll Y=edge[X][i];
        if(F[Y]) memo.pb(ans[Y]+1);
    }
    vi dp(memo.size()+1,1),cp(memo.size()+1,1);
    rep(i,0,memo.size()) dp[i+1]=dp[i]*memo[i]%M;
    per(i,memo.size()-1,0) cp[i]=cp[i+1]*memo[i]%M;
    ans[X]=ans[X]*plus%M;
    ll cnt=0;
    rep(i,0,edge[X].size()){
        ll Y=edge[X][i];
        if(F[Y]){
            reroot(Y,edge,F,ans,M,dp[cnt]*cp[cnt+1]%M%M*plus%M+1);
            cnt++;
        }
    }
}
