}

void dfs2(ll v,ll par){
    mark[v] = true;
    dp[v] += (dp[par] % MOD * poww((dp[v] + 1),MOD - 2,MOD)) % MOD * dp[v] % MOD;
    dp[v] %= MOD;
    for(auto u:adj[v]) {
        if(mark[u])
            continue;
        dfs2(u,v);
    }
}

