void DFS(int u, int par)
{
    int pos = -1, sz = a[u].size();
    p[u] = par;
    for(int i = 0; i < sz; ++i)
    {
        int v = a[u][i];
        if(v == par) {pos = i; continue;}
        DFS(v, u);
    }
    if(pos != -1) a[u][pos] = a[u].back(), a[u].pop_back(), --sz;
    f[u] = 1;
    for(int v: a[u]) f[u] = (f[u] * (f[v] + 1)) % mod;
}

void DFS2(int u)
{
     if(a[u].empty()) return;
     int sz = a[u].size();
     vector<ll> pre(sz), suf(sz);
     for(int i = 0; i < sz; ++i)
     {
         int v = a[u][i];
         if(i) pre[i] = pre[i - 1] * (f[i] + 1) % mod;
         else pre[i] = (f[i] + 1) % mod;
     }
     for(int i = sz - 1; i > 0; --i)
     {
         int v = a[u][i];
         if(i < sz - 1) suf[i] = suf[i + 1] * f[i] % mod;
         else suf[i] = (f[i] + 1) % mod;
     }
     for(int i = 0; i < sz; ++i)
     {
         int v = a[u][i];
         ll Pre = 1, Suf = 1;
         if(i) Pre = pre[i - 1];
         if(i < sz - 1) Suf = suf[i + 1];
         g[v] = (Pre * Suf % mod) * (g[u] + 1) % mod;
         DFS2(v);
     }
}

