    --x;--y;
    g[x].push_back(y);
    g[y].push_back(x);
  }
  vector<T> dp1(n);
  ll x,y;
  tie(x,y) = dfs1(g, dp1, m, 0);
  vecll dp2(n);
  dfs2(g, dp1, dp2, 0, 0, m, 0);
  ll total = (x+y) % m;
  for(auto&& e:dp2) {
    cout<<(total+m-e)%m<<endl;
  }
  return 0;
}

