ll get(ll u, ll to) {
    if (pmult[u].size() == 1)
        return 1;
    if (tto[to] == 0)
        return smult[u][1];
    if (tto[to] == pmult[u].size() - 1)
        return pmult[u][pmult[u].size() - 2];
    return (pmult[u][tto[to] - 1] * smult[u][tto[to] + 1]) % m;
}


