void dfs_zero(int node, int p) {
	dp[node]= dp[node] = 1LL;

	int x = 1;
	dps[node].pb(1);
	for(int i:g[node]) {
		if(i == p) continue;

		dfs_zero(i, node);
		ind[i] = x;

		dps[node].pb((dp[i] + 1)%mod);

		dp[node] *= (dp[i] + 1)%mod;
		dp[node] %= mod;
		x++;
	}

	dps[node].pb(1);

	pr[node].resize(dps[node].size(), 1);
	sf[node].resize(dps[node].size(), 1);

	pr[node][0] = dps[node][0] % mod;
	for(int i=1;i<dps[node].size();i++) {
		pr[node][i] = (pr[node][i-1] * dps[node][i])%mod;
	}

	sf[node][dps[node].size()-1] = dps[node][dps[node].size()-1] % mod;
	for(int i=dps[node].size()-2;i>=0;i--) {
		sf[node][i] = (sf[node][i+1] * dps[node][i])%mod;
	}
}

void dfs_one(int node, int p, ll carry0=1LL) {
	dpresult[node] = (dp[node] * carry0)%mod;

	for(int i:g[node]) {
		if(i == p) continue;

		int cr = ind[i];

		//cout<<"At index "<<cr<<" calling "<<i<<"\n";

		ll tmp0 = carry0 * (pr[node][cr-1] * sf[node][cr+1])%mod;
		tmp0 = (tmp0+1)%mod;

		dfs_one(i, node, tmp0);
	}
}

