int dfs1(int p, int v) {
	int i, ret = 1;
	rep(i, et[v].size()) {
		int nv = et[v][i];
		if (nv == p) continue;
		ret *= dfs1(v, nv) + 1;
		ret %= mod;
	}
	return dp1[v] = ret;
}

//ppDp … pの親を根としたとき、pを白く塗り、pの親を黒く塗る方法の数
void dfs2(int pp, int p, int v, int ppDp) {
	int i;
	int res = 1;

	dp2[v] = dp1[v];
	if (p != -1) {
		rep(i, et[p].size()) {
			int u = et[p][i];
			if (u == v || u == pp) continue;
			res *= dp1[u] + 1;
			res %= mod;
		}
		res *= ppDp;
		res %= mod;
		res = (res + 1) % mod;
	}
	dp2[v] *= res;
	dp2[v] %= mod;

	rep(i, et[v].size()) {
		int nv = et[v][i];
		if (nv == p) continue;
		dfs2(p, v, nv, res);
	}
}

