using namespace std;
int N, M;
vector<vector<int>> graph;
vector<int> down, up;
int recur1(int node, int prev)
{
    long long a = 1;
    for (int next : graph[node]) {
        if (next == prev) continue;
        a = a * recur1(next, node) % M;
    }
    return down[node] = (a + 1) % M;
}
void recur2(int node, int prev)
{
    if (prev == -1) up[node] = 1;
    vector<int> C, A, L, R;
    for (int next : graph[node]) {
        if (next == prev) continue;
        C.push_back(next);
        A.push_back(down[next]);
    }
    int n = A.size();
    L.resize(n+2), R.resize(n+2);
    L[0] = L[n+1] = R[0] = R[n+1] = 1;
    for (int i = 0; i < n; i++) {
        L[i+1] = (long long)A[i] * L[i] % M;
    }
    for (int i = n-1; i >= 0; i--) {
        R[i+1] = (long long)A[i] * R[i+2] % M;
    }
    for (int i = 0; i < n; i++) {
        up[C[i]] = ((long long)up[node] * L[i+1-1] % M * R[i+1+1] + 1) % M;
    }
    for (int next : C) {
        recur2(next, node);
    }
}
int main()
{
    cin >> N >> M;
    graph.resize(N);
    for (int i = 0; i < N-1; i++) {
        int x, y; cin >> x >> y; x--, y--;
        graph[x].push_back(y);
        graph[y].push_back(x);
    }
    down.resize(N), up.resize(N);
    recur1(0, -1);
    recur2(0, -1);
    for (int i = 0; i < N; i++) {
        cout << (down[i] + M - 1LL) * up[i] % M << endl;
    }
    return 0;
}

