//区間加算区間最小
const ll N_ = 1<<18;
ll seg[2 * N_ - 1], lazy[2 * N_ - 1];
void eval(ll k, ll l, ll r){
  if(lazy[k] == 0) return;
  seg[k] += lazy[k];
  if(r - l > 1){
    lazy[2 * k + 1] += lazy[k];
    lazy[2 * k + 2] += lazy[k];
  }
  lazy[k] = 0;
}

void add(ll a, ll b, ll x, ll k = 0, ll l = 0, ll r = N_){
  eval(k, l, r);
  if(r <= a || b <= l) return;
  if(a <= l && r <= b){
    lazy[k] += x;
    eval(k, l, r);
    return;
  }
  add(a, b, x, 2 * k + 1, l, (l + r) / 2);
  add(a, b, x, 2 * k + 2, (l + r) / 2, r);
  eval(k, l, r);
  seg[k] = min(seg[2 * k + 1], seg[2 * k + 2]);
  return;
}

ll getminimum(ll a, ll b, ll k = 0, ll l = 0, ll r = N_){
  if(r <= a || b <= l) return INFL;
  eval(k, l, r);
  if(a <= l && r <= b) return seg[k];
  ll val = getminimum(a, b, 2 * k + 1, l, (l + r) / 2);
  ll var = getminimum(a, b, 2 * k + 2, (l + r) / 2, r);
  return min(val, var);
}



