unsigned long long M;

struct Vertex {
	std::vector<int> connected_to;
	std::vector<unsigned long long> black_coloring;
};

unsigned long long traverse(int node, int no_backtrack,  std::vector<struct Vertex>& vec) {
	struct Vertex& n = vec[node];
	unsigned long long ret = 1;
	if (n.black_coloring.size() == 0) {
		n.black_coloring.resize(n.connected_to.size());
		for (int i = 0; i < n.connected_to.size(); ++i) {
			n.black_coloring[i] = ULLONG_MAX;
		}
	}
	for (int i = 0; i < n.connected_to.size(); ++i) {
		if (n.connected_to[i] == no_backtrack) {
			continue;
		}
		if (n.black_coloring[i] == ULLONG_MAX) {
			n.black_coloring[i] = traverse(n.connected_to[i], node, vec);
		}
		ret*= n.black_coloring[i] + 1;
		ret%= M;
	}
	ret%= M;
	return ret;
}

