    vector<int> cumr(deg[v] + 1,1);
    rep(i,deg[v]) cuml[i + 1] = cuml[i] * (dp[v][i] + 1) % MOD;
    for (int i = deg[v] - 1; i >= 0; i--) cumr[i] = cumr[i + 1] * (dp[v][i] + 1) % MOD;
    answer[v] = cumr[0];
    rep(i,deg[v]) {
        int e = G[v][i];
        if (e == p) continue;
        dfs2(e,cuml[i] * cumr[i + 1] % MOD,v);
    }
}

int main() {
    int n; cin >> n >> MOD;
    rep(_,n - 1) {
        int a,b; cin >> a >> b;
        a --; b --;
        G[a].push_back(b);
        G[b].push_back(a);
    }

    rep(i,n) {
        deg[i] = G[i].size();
        vector<int> a(deg[i],1);
        dp[i] = a;
    }

    dfs1(0);
    dfs2(0);
    rep(i,n) cout << answer[i] << endl;
}

