    dp1(1, -1);

    memset(bd2, 0, sizeof(bd2));
    bd2[1] = 1;
    dp2(1, -1);

    for (int i=1; i<=n; i++) {
        cout << (bd1[i]*bd2[i])%M << "\n";
    }
}

