struct node
{
	int u,v,next;
};
node t[200020];
void build(ll u1,ll v1,ll tot)
{
	t[tot].u=u1;t[tot].v=v1;
	t[tot].next=head[u1];head[u1]=tot;
}
void dfs(ll fa,ll p)
{
	ll cnt=0;
	f[p]=1;
	for(int i=head[p];i;i=t[i].next)
	{
		if(t[i].v!=fa)
		{
			t1[p].push_back(t[i].v);
			dfs(p,t[i].v);
			(f[p]*=(f[t[i].v]+1))%=mod;
			l[p].push_back(0);
			r[p].push_back(0);
			cnt++;
		}
	}
	for(int i=0;i<cnt;i++)
	{
		l[p][i]=(i==0)?1:l[p][i-1];
		(l[p][i]*=(f[t1[p][i]]+1))%=mod;
	}
	for(int i=cnt-1;i>=0;i--)
	{
		r[p][i]=(i==cnt-1)?1:r[p][i+1];
		(r[p][i]*=(f[t1[p][i]]+1))%=mod;
	}
}
void dfs1(ll fa,ll p,ll sum)
{
	ans[p]=(f[p]*(sum+1))%mod;
	for(int i=0;i<t1[p].size();i++)
	{
		int sum1=(i==0)?1:l[p][i-1],sum2=(i==t1[p].size()-1)?1:r[p][i+1];
		dfs1(p,t1[p][i],(sum1%mod*sum2%mod*(sum+1))%mod);
	}
}
