int binpow (int a, int n) {
	if (n == 0)
		return 1;
	if (n % 2 == 1)
		return (binpow (a, n - 1) * a) % m;
	else {
		int b = binpow (a, n / 2);
		return (b * b) % m;
	}
}

int phi (int x) {
	int res = x;
	for (int i = 2; i * i <= x; ++i)
		if (x % i == 0) {
			while (x % i == 0)
				x /= i;
			res -= res / i;
		}
	if (x > 1)
		res -= res / x;
	return res;
}

void dfs (int v, int p = -1) {
	dp[v] = 1;
	for (int i = 0; i < g[v].size(); i++) {
		int to = g[v][i];
		if (to == p) continue;
		dfs(to, v);
		dp[v] = dp[v] * (dp[to] + 1) % m;
	}
}

void update (int v, int p, int w) {
	for (int i = 0; i < g[v].size(); i++) {
		int to = g[v][i];
		if (to == p) continue;
		ans[to] = (w / (dp[to] + 1) % m + 1) % m * dp[to] % m;
		update (to, v, ans[to]);
	}
}

