        if(i-1 >= 0) lprod[i] = lprod[i-1];
        if(to == p) continue;
        (lprod[i] *= dp1[to]) %= M;
    }

    for(ll i = m-1; i >= 0; i--) {
        ll to = g[x][i];
        if(i+1 <= m-1) rprod[i] = rprod[i+1];
        if(to == p) continue;
        (rprod[i] *= dp1[to]) %= M;
    }

    rep(i, m) {
        ll to = g[x][i];
        if(to == p) continue;

        ll prod = dp2[x];
        if(i-1 >= 0) (prod *= lprod[i-1]) %= M;
        if(i+1 <= m-1) (prod *= rprod[i+1]) %= M;
        dp2[to] = (prod + 1) % M;
        dfs2(to, x);
    }
}

void dfs3(ll x, ll p = -1) {
    ans[x] = dp2[x];
    for(auto to : g[x]) {
        if(to == p) continue;
        ans[x] *= dp1[to];
        ans[x] %= M;
        dfs3(to, x);
    }
}

