    for (int i = 1; i <= cnt; i++) pre[i] = pre[i - 1] * f[p[i]] % m;
    for (int i = cnt; i >= 1; i--) suf[i] = suf[i + 1] * f[p[i]] % m;
    for (int i = 1; i <= cnt; i++) g[p[i]] = pre[i - 1] * suf[i + 1] % m;
