int cnt;
int head[100005];
void ins(int u,int v)
{
	cnt++;
	e[cnt].to=v;
	e[cnt].next=head[u];
	head[u]=cnt;
}
long long low[100005];
long long up[100005];
long long ans[100005];
void dfs1(int u,int fa)
{
	low[u]=1;
	for(int i=head[u];i;i=e[i].next)
	{
		int v=e[i].to;
		if(v==fa) continue;
		dfs1(v,u);
		low[u]=MOD(low[u]*(low[v]+1));
	}
}
long long ksm(long long a,long long x)
{
	long long base=1;
	while(x)
	{
		if(x&1) base=MOD(base*a);
		a=MOD(a*a);
		x>>=1;
	}
	return base;
}
void dfs2(int u,int fa)
{
	up[u]=1;
	if(fa==0) up[u]=1;
	else up[u]=MOD(MOD(up[fa]*low[fa]*ksm(low[u]+1,mod-2)+1));
	ans[u]=MOD(low[u]*up[u]);
	for(int i=head[u];i;i=e[i].next)
	{
		int v=e[i].to;
		if(v==fa) continue;
		dfs2(v,u);
	}
}
