vector<vector<int>> tree;

vector<int> dp;
vector<bool> visited;
vector<int> res;

int dfs(int start) {
    if (!visited[start]) {
        visited[start] = true;
        if (tree[start].empty())
            dp[start] = 1;
        else {
            long long cnt = 1LL;
            for (int child : tree[start])
                if (!visited[child])
                    cnt = (cnt * (dfs(child) + 1)) % m;

            dp[start] = (int)cnt;
        }
    }

    return dp[start];
}

void solve(int node, int parent) {
    if (parent == -1)
        res[node] = dp[node];
    else
        res[node] = (res[parent] / (dp[node] + 1) + 1) * dp[node];

    for (int child : tree[node])
        if (child != parent)
            solve(child, node);
}

