ll solve(int u, int p = 0){
    pai[u] = p;
    ll res = 1;
    for(int v : adj[u])
        if(v != p)
            res *= (1 + solve(v, u));
    return down[u] = res;
}

void go(int u, int p = 0){
    vector<ll> vec, nodes;
    for(int v : adj[u])
        if(v != p){
            nodes.push_back(v);
            vec.push_back(1 + down[v]);
        }

    vector<ll> pref(vec), suff(vec);
    for(int i = 1; i < pref.size(); i++)
        pref[i] = (pref[i]*pref[i-1])%mod;
    for(int i = int(suff.size()) - 2; i >= 0; i--)
        suff[i] = (suff[i]*suff[i+1])%mod;

    for(int i = 0; i < nodes.size(); i++){
        int v = nodes[i];
        ll esq = (i-1 >= 0 ? pref[i-1] : 1);
        ll dir = (i+1 < vec.size() ? suff[i+1] : 1);
        //cout << u << " setando up de " << v << endl;
        up[v] = (1 + esq*dir*up[u] )%mod;
