ll dfs1(int u, int f) //first dp
{
	//debug(u);
	ll &ret = dp[u];
	ret = 1;
	//vals.clear();
	vector<ll> vals;
	for(int v:G[u])
	{
		if(v == f) {vals.pb(1); continue;}
		ll dpv = (dfs1(v, u)+1)%M;
		ret *= dpv;
		ret %= M;
		vals.pb(dpv);
	}
	int sz = G[u].size();
	//debug(sz);
	pre[u].resize(sz); //RE
	suf[u].resize(sz);
