	{
		pre[u][i] = i ? (pre[u][i-1]*vals[i]) : vals[i];
		suf[u][sz-1-i] = i ? (suf[u][sz-i]*vals[sz-1-i]) : vals[sz-1-i];
	}
	return ret;
}


