vector<ll> tree[100001];
ll n, M;
ll bd1[100001], bd2[100001], presum[100001], sufsum[100001];

void dp1(ll n, ll par) {
    bd1[n] = 1;
    for (auto ch:tree[n]) {
        if (ch!=par) {
            dp1(ch, n);
            bd1[n] *= (bd1[ch]+1);
            bd1[n] %= M;
        }
    }
}

void dp2(ll n, ll par) {
    ll prev = 1;
    for (int i=0; i<tree[n].size(); i++) {
        if (tree[n][i]!=par) {
            presum[tree[n][i]] = prev;
            prev *= bd1[tree[n][i]]+1;
            prev %= M;
        }   
    }

    prev = 1;
    for (int i=tree[n].size()-1; i>=0; i--) {
        if (tree[n][i]!=par) {
            sufsum[tree[n][i]] = prev;
            prev *= bd1[tree[n][i]]+1;
            prev %= M;
        }   
    }

    for (auto ch:tree[n]) {
        if (ch!=par) {
            bd2[ch] = (presum[ch]*(sufsum[ch]*bd2[n])%M+1)%M;
            dp2(ch, n);
        }
    }
}

