void dfs_one(int u, int p) {
    dp[u] = 1;
    for (int v : adj[u]) {
        if (v == p) {
            continue;
        }
        dfs_one(v, u);
        dp[u] = (dp[u] * dp[v]) % mod;
    }
    dp[u] = (dp[u] + 1) % mod;
}

void dfs_two(int u, int p, ll ways) {
    vector<ll> pref, suff;
    pref.push_back(1);
    for (int v : adj[u]) {
        if (v == p) {
            continue;
        }
        pref.push_back(dp[v]);
        suff.push_back(dp[v]);
    }
    suff.push_back(1);
    for (int i = 1; i < (int) pref.size(); i++) {
        pref[i] = (pref[i] * pref[i - 1]) % mod;
    }
    for (int i = (int) suff.size() - 2; i >= 0; i--) {
        suff[i] = (suff[i] * suff[i + 1]) % mod;
    }
    ans[u] = pref.back() * ways % mod;
    int i = 0;
    for (int v : adj[u]) {
        if (v == p) {
            continue;
        }
        ll new_ways = pref[i] * suff[i + 1] % mod;
        new_ways = new_ways * ways % mod;
        new_ways++;
        new_ways %= mod;
        dfs_two(v, u, new_ways);
        i++;
    }
}

