vvi adj(MAXN);
int N,MOD;
int BLK = 500;

int dfs(int u, int p, int col) {
    if(dp[u][col].count(p))
        return dp[u][col][p];

    int blks = ((int)adj[u].size() + BLK-1) / BLK;
    ll res=1;

    FOR(i,blks) {
        int from = adj[u][i*BLK];
        int idx_to = min( (i+1)*BLK-1, (int)adj[u].size()-1 );
        int to = adj[u][idx_to];

        if(from<=p && p<=to) {
            for(auto to : adj[u])
                if(to!=p)
                    res = res * dfs(to, u, col) % MOD;
            continue;
        }

        if(dp_blk[u][col][i]<0) {
            int rez=1;
            for(auto to : adj[u])
                if(to!=p)
                    rez = rez * dfs(to, u, col) % MOD;
            dp_blk[u][col][i] = rez;
        }

        res = res*dp_blk[u][col][i] % MOD;
    }

    if(p>=1 && col==0)
        res += dfs(u, p, 1);

    return dp[u][col][p]=res%MOD;
}

