  Solver2(LL n, LL m) : n(n), mod(m), ans(n), t(n){};

  void solve() {
    for (int i = 0; i < n - 1; ++i) {
      int a, b;
      cin >> a >> b;
      --a;
      --b;
      t[a].push_back({b, (int)t[b].size(), 1});
      t[b].push_back({a, (int)t[a].size() - 1, 1});
    }
