int64 dfs1(int32 v, int32 p, int32 c){ // c== 1 -> black
	if(~dp1[v][c]) return dp1[v][c];
	dp1[v][c] = 1;
	REP(i, G[v].size()){
		if(G[v][i] == p) continue;
		int64 x = 0;
		REP(j, c+1){
			x += dfs1(G[v][i], v, j);
		}
		dp1[v][c] = dp1[v][c]*x%M;
	}
	return dp1[v][c];
