int64 dfs2(int32 v, int32 p, int64 val){
	if(~dp2[v]) return dp2[v];
	dp2[v] = 0;
	if(p == -1){
		dp2[v] = dfs1(v, p, 1);
	}else{
		dp2[v] = dfs1(v, p, 1)*val%M;
	}
	vector<int64> mul1(G[v].size()+1,1 ), mul2(G[v].size()+1, 1);
	REP(i, G[v].size()){
		if(G[v][i] == p){
			mul1[i+1] = val;
			mul2[G[v].size()-i] = val;
		}else{
			mul1[i+1] = dfs1(G[v][i], v, 0)+dfs1(G[v][i], v, 1);
			mul2[G[v].size()-i] = mul1[i+1];
		}
	}
	REP(i, G[v].size()) mul1[i+1] = mul1[i+1]*mul1[i]%M;
	REP(i, G[v].size()) mul2[i+1] = mul2[i+1]*mul2[i]%M;

	REP(i, G[v].size()){
		if(G[v][i] == p) continue;
		int64 mul = mul1[i]*mul2[G[v].size()-i-1]%M;
		mul = (mul+1)%M;
		dfs2(G[v][i], v, mul);
	}
	return dp2[v];
}

