            ll ways = (1 + par_ans);
            ways = (cno > 0) ? (ways * prefix[cno - 1]) % m : ways ;
            ways = (cno < sz(suffix) - 1) ? (ways * suffix[cno + 1]) % m : ways ;
            solve2(child, vis, m, ways);
            cno++;
        }
    }
}

