#define MAX (ll)1e5 + 10
ll n, M;

// number of ways of painting the subtree rooted at i; 0 =black,1=white
v dp(MAX, 0);

void dfs(vv &adjList, ll curr, ll prev) {
    dp[curr] = 1;

    for (auto neigh : adjList[curr]) {
        if (neigh == prev)
            continue;
        dfs(adjList, neigh, curr);
        dp[curr] *= (dp[neigh] + 1);
        dp[curr] %= M;
    }
}

v answer(MAX, 0);

// find answers while changing the root
void dfs2(vv &adjList, ll leftpart, ll curr, ll prev) {
    answer[curr] = (leftpart * dp[curr]) % M;

    v bacchas;

    v vals;
    deque<ll> prefixProd, suffixProd;

    for (auto neigh : adjList[curr]) {
        if (neigh == prev)
            continue;

        bacchas.push_back(neigh);
    }

    for (auto neigh : bacchas) {
        ll x = dp[neigh] + 1;

        if (sz(prefixProd))
            prefixProd.push_back((x * prefixProd.back()) % M);
        else
            prefixProd.push_back((x) % M);
    }

    reverse(all(bacchas));

    for (auto neigh : bacchas) {
        ll x = dp[neigh] + 1;
        if (sz(suffixProd))
            suffixProd.push_front((x * suffixProd.front()) % M);
        else
            suffixProd.push_front((x) % M);
    }

    for (ll i = 0; i < sz(bacchas); i++) {
        ll lp = leftpart;

        if (i > 0) {
            lp *= prefixProd[i - 1];
            lp %= M;
        }
        if (i < sz(bacchas) - 1) {
            lp *= suffixProd[i + 1];
            lp %= M;
        }
        lp++;
        lp %= M;

        dfs2(adjList, lp, bacchas[i], curr);
    }
}

