    for (ll i = 0; i < m; i++) {
        ll a, b;
        cin >> a >> b;
        adjList[a].push_back(b);
        adjList[b].push_back(a);
    }
    dfs(adjList, 1, -1);
    dfs2(adjList, 1, 1, -1);
    for (ll i = 1; i <= n; i++) {
        cout << answer[i] << endl;
    }
}

