int binpow(int a, int n)
{
	int res = 1;
	while(n)
	{
		if(n&1)
		{
			n--;
			res*=a;
			res%=mdd;
		}
		n/=2;
		a*=a;
		a%=mdd;
	}
	return res;
}

void dfs(int v, int pred = 0)
{
	dp[v] = 1;
	dp[v] %= mdd;
	FOR(0, i, edge[v].size())
	{
		int to = edge[v][i];
		if(to == pred) continue;
		dfs(to, v);
		dp[v] *= (dp[to] + 1) % mdd;
		dp[v] %= mdd;
	}
}

void dfs2(int v, int pred = 0)
{
	if(v == 1) dp2[v] = 1;
	dp2[v] %= mdd;
	FOR(0, i, edge[v].size())
	{
		int to = edge[v][i];
		if(to == pred) continue;
		dp2[to] = 1 + (dp[v] * binpow((dp[to] + 1), phi - 1) % mdd * (dp2[v]) % mdd) % mdd;
		dp2[to] %= mdd;
		dfs2(to, v);
	}
}

