int DFS(int i, int pre) {
    subt[i] = 1;
    for(int j : adj[i]) if(j != pre)
        subt[i] = (subt[i] * (1+DFS(j, i))) % mod;
    return subt[i];
}

void dfs(int i, int pre, int anc) {
    pos[i] = (++anc * subt[i]) % mod;
    int t = adj[i].size(), val[t];
    for(int j = 0; j < t; j++) {
        if(adj[i][j] == pre)
            val[j] = anc;
        else
            val[j] = subt[adj[i][j]]+1;
    }

    int mul[t][2];
    mul[0][0] = mul[t-1][1] = 1;
    for(int j = 1; j < t; j++)
        mul[j][0] = (mul[j-1][0]*val[j-1]) % mod;
    for(int j = t-2; j > -1; j--)
        mul[j][1] = (mul[j+1][1]*val[j+1]) % mod;

    for(int j = 0; j < t; j++)
        if(adj[i][j] != pre)
            dfs(adj[i][j], i, (mul[j][0]*mul[j][1]) % mod);
}

