using mint = mod_int_64;

mint dp[101000];
mint dp2[101000];

mint rec(vector<vector<int>> &tree, int cur, int par){
  dp[cur] = 1;

  for(auto next : tree[cur]){
    if(next == par) continue;
    dp[cur] *= (rec(tree,next,cur)+1);
  }

  return dp[cur];
}

mint rec2(vector<vector<int>> &tree, int cur, int par, int index, mint val=0){
  int c = tree[cur].size();
  if(par != -1) --c;

  SegmentTree<mint> prod = SegmentTree<mint>(c,1,[&](mint a, mint b){return a*b;}, [&](mint a, mint b){return b;});

  REP(i,c){
    prod.update(i,dp[tree[cur][i]]+1);
  }

  int i = 0;
  for(auto next : tree[cur]){
    if(next == par) continue;
    dp2[next] = val * prod.query(0,i) * prod.query(i+1,c) + 1;

    rec2(tree, next, cur, i, dp[next]);
    ++i;
  }

  return dp2[cur];
}

