vector<int> H[100000];
int F[100000], G[100000];
int T1[100002], T2[100002];

int dfs1(int u, int p) {
  int f = 1;
  H[u].erase(find(H[u].begin(), H[u].end(), p));
  for (auto v : H[u])
    f = mul(f, 1 + dfs1(v, u));
  return F[u] = f;
}

void dfs2(int u) {
  auto m = (int) H[u].size();
  T1[0] = 1 + G[u];
  G[u] = mul(1 + G[u], F[u]);
  for (auto i = 1; i <= m; ++i)
    T1[i] = mul(T1[i - 1], 1 + F[H[u][i - 1]]);
  T2[m + 1] = 1;
  for (auto i = m; i; --i)
    T2[i] = mul(T2[i + 1], 1 + F[H[u][i - 1]]);
  for (auto i = 1; i <= m; ++i)
    G[H[u][i - 1]] = mul(T1[i - 1], T2[i + 1]);
  for (auto v : H[u])
    dfs2(v);
}

