int N, M;
int K[100001];
int to[200001], ne[200001], he[100001], num[200001];
int dame[100001];
int S1[200001], S2[200001];

int dfs(int v, int prev) {
	auto s1 = S1 + K[v - 1];
	auto s2 = S2 + K[v - 1];
	int sm = K[v] - K[v - 1];
	if (dame[v]) {
		if (dame[v] >= 2) {
			ll tmp = dfs(to[dame[v]], dame[v] ^ 1);
			int k = sm - num[dame[v]];
			for (int i = k - 1; i < sm; i++) {
				s1[i] = s1[i] * tmp % M;
			}
			s2[k - 1] = tmp;
			tmp = s2[sm - 1];
			for (int i = sm - 2; i >= 0; i--) {
				tmp = tmp * s2[i] % M;
				s2[i] = tmp;
			}
			dame[v] = -1;
		}

		ll ret = 1;
		if (prev >= 2) {
			int k = sm - num[prev];
			if (k >= 2) ret *= s1[k - 2];
			if (k < sm) ret *= s2[k];
			ret %= M;
		}
		else ret = s1[sm - 1];

		return ret + 1;
	}
	dame[v] = prev;
	ll ret = 1;
	int k = 0;
	for (int i = he[v]; i; i = ne[i]) {
		int tmp = 1;
		if (i != prev) {
			tmp = dfs(to[i], i ^ 1);
			ret = ret * tmp % M;
		}
		s1[k] = ret;
		s2[k++] = tmp;
	}
	if (prev == -1) {
		ll tmp2 = s2[sm - 1];
		for (int i = k - 2; i >= 0; i--) {
			tmp2 = tmp2 * s2[i] % M;
			s2[i] = tmp2;
		}
	}
	return ret + 1;
}

