void dfs2(int i,ll p_res = 1,int p = -1) {
    if (p != -1) d[i].push_back(P(p_res+1,p));
    int n = d[i].size();
    vector<ll> prod_l(n+1,1),prod_r(n+1,1);
    for (int x = 0;x < n;++x) {
        prod_l[x+1] = prod_l[x]*d[i][x].first%m;
        prod_r[n-1-x] = prod_r[n-x]*d[i][n-1-x].first%m;
    }
    dp[i] = prod_r[0];
    for (int j = 0;j < n;++j) {
        int x = d[i][j].second;
        if (x != p) dfs2(x,prod_l[j]*prod_r[j+1]%m,i);
    }
}

