typedef pair<int, int> P;

vector<vector<ll>> g;
// 0: white
// 1: black

ll dp[100100];
ll N, M;

void dfs1(int idx, int par = -1) {
    dp[idx] = 1;

    for (int i = 0; i < g[idx].size(); i++) {
        int to = g[idx][i];
        if (to == par) continue;
        dfs1(to, idx);
        dp[idx] *= dp[to] + 1;
        dp[idx] %= M;
    }
}

ll ans[100100];
void dfs2(int idx, int par = -1) {
    ans[idx] = 1; 
    for (int i = 0; i < g[idx].size(); i++) {
        int to = g[idx][i];
        ans[idx] *= dp[to] + 1;
        ans[idx] %= M;
    }

    // 子供の数
    int n = g[idx].size();
    vector<ll> lft(n), rht(n);
    for (int i = 0; i < n; i++) {
        lft[i] = rht[i] = dp[g[idx][i]] + 1;
    }
    for (int i = 1; i < n; i++) {
        lft[i] *= lft[i - 1];
        lft[i] %= M;
    }
    for (int i = n - 2; i >= 0; i--) {
        rht[i] *= rht[i + 1];
        rht[i] %= M;
    }

    rep(i, n) {
        if (g[idx][i] == par) continue;

        // dp を更新する
        dp[idx] = 1;

        // 左に他の子供がいる場合
        if (i) {
            dp[idx] *= lft[i - 1];
            dp[idx] %= M;
        }

        // 右に他の子供がいる場合
        if (i + 1 < n) {
            dp[idx] *= rht[i + 1];
            dp[idx] %= M;
        }

        // 潜る
        dfs2(g[idx][i], idx);
    }
}

