#include<bits/stdc++.h>
using namespace std;
#define MAXN 100000
#define LL long long int

int N, M;
LL up[MAXN + 3], down[MAXN + 3], answer[MAXN + 3], prefix[MAXN + 3], suffix[MAXN + 3];
vector<int> adj[MAXN + 3], children[MAXN + 3];

void fillChildren(int prev, int u) {
    for (int i = 0; i < adj[u].size(); i++) {
        int v = adj[u][i];
        if (v != prev) {
            children[u].push_back(v);
            fillChildren(u, v);
        }
    }
}

void fillDown(int prev, int u) {
    down[u] = 1;
    for (int i = 0; i < children[u].size(); i++) {
        int v = children[u][i];

        fillDown(u, v);

        down[u] *= (1 + down[v]);
        down[u] %= M;
    }
}

void fillUp(int prev, int u) {
    if (children[u].size() > 0) {
        int childrenCount = children[u].size();

        prefix[0] = (1 + down[children[u][0]]);
        for (int i = 1; i < children[u].size(); i++) {
            prefix[i] = prefix[i - 1] * (1 + down[children[u][i]]);
            prefix[i] %= M;
        }

        suffix[childrenCount - 1] = (1 + down[children[u][childrenCount - 1]]);
        for (int i = childrenCount - 2; i >= 0; i--) {
            suffix[i] = suffix[i + 1] * (1 + down[children[u][i]]);
            suffix[i] %= M;
        }

        for (int i = 0; i < childrenCount; i++) {
            int v = children[u][i];

            LL pref = (i == 0 ? 1 : prefix[i - 1]);
            LL suf = (i == childrenCount - 1 ? 1 : suffix[i + 1]);

            up[v] = (pref * suf)%M;
            up[v] *= (1 + up[u]);
            up[v] %= M;

            fillUp(u, v);
        }
    }
}

void fillAnswer() {
    for (int i = 1; i <= N; i++) {
        answer[i] = down[i] * (1 + up[i]);
        answer[i] %= M;
    }
}

