        int x, y;

        cin >> x >> y;
        adj[x].push_back(y);
        adj[y].push_back(x);
    }

    fillChildren(1, 1);
    fillDown(1, 1);

    up[1] = 0;
    fillUp(1, 1);

    fillAnswer();

