template<typename T>
struct rerooting {
    using F1 = function<T(T, int)>;
    using F2 = function<T(T, T)>;

    int n;
    F1 f, g; // f : pre-merge, g : post-merge
    F2 merge;
    T id;
    vector<vector<int>> graph;
    vector<vector<T>> dp;

    rerooting(int n, F1 f, F1 g, F2 merge, T id)
        : n(n), f(f), g(g), merge(merge), id(id), graph(n), dp(n) {}

    void add_edge(int u, int v) {
        graph[u].push_back(v);
        graph[v].push_back(u);
    }

    T dfs1(int v, int p = -1) {
        int deg = graph[v].size();
        dp[v].resize(deg);
        T dp_cum = id;
        for (int i = 0; i < deg; ++i) {
            if (graph[v][i] == p) continue;
            dp[v][i] = dfs1(graph[v][i], v);
            dp_cum = merge(dp_cum, f(dp[v][i], graph[v][i]));
        }
        return g(dp_cum, v);
    }

    void dfs2(int v, T dp_p, int p = -1) {
        int deg = graph[v].size();
        for (int i = 0; i < deg; ++i) {
            if (graph[v][i] == p) {
                dp[v][i] = dp_p;
                break;
            }
        }
        vector<T> dp_l(deg + 1, id), dp_r(deg + 1, id);
        for (int i = 0; i < deg; ++i) dp_l[i+1] = merge(dp_l[i], f(dp[v][i], graph[v][i]));
        for (int i = deg - 1; i >= 0; --i) dp_r[i] = merge(f(dp[v][i], graph[v][i]), dp_r[i+1]);
        for (int i = 0; i < deg; ++i) {
            if (graph[v][i] == p) continue;
            dfs2(graph[v][i], g(merge(dp_l[i], dp_r[i+1]), v), v);
        }
    }

    void build() {
        dfs1(0);
        dfs2(0, id);
    }

    T solve(int v) {
        T ans = id;
        int deg = graph[v].size();
        for (int i = 0; i < deg; ++i) {
            ans = merge(ans, f(dp[v][i], graph[v][i]));
        }
        return g(ans, v);
    }
};

int main() {
    ios::sync_with_stdio(false);
