    int n, m;
    cin >> n >> m;
    auto f = [&](ll a, int b) { (void) b; return (a + 1) % m; };
    auto g = [&](ll a, int b) { (void) b; return a; };
    auto merge = [&](ll a, ll b) { return (a * b) % m; };
    rerooting<ll> re(n, f, g, merge, 1);

