int n, m;
vector<vector<int>> tree;
vector<int> dp;

void dfs(int node, int parent) {
    long long cnt = 1;
    for (int child : tree[node]) {
        if (child != parent) {
            dfs(child, node);
            cnt *= dp[child] + 1;
            cnt %= m;
        }
    }

    dp[node] = cnt;
}

void update(int node, int parent) {
    int k = tree[node].size();
    vector<int> pref_prods, suff_prods;

    pref_prods.reserve(k + 1);
    pref_prods.push_back(1);
    for (int i = 0; i < k; ++i)
        pref_prods.push_back((long long)pref_prods.back() * (dp[tree[node][i]] + 1) % m);

    suff_prods.reserve(k + 1);
    suff_prods.push_back(1);
    for (int i = k - 1; i >= 0; --i)
        suff_prods.push_back((long long)suff_prods.back() * (dp[tree[node][i]] + 1) % m);

    reverse(suff_prods.begin(), suff_prods.end());
    for (int i = 0, j = 0; i < k; ++i) {
        if (tree[node][i] != parent) {
            dp[tree[node][i]] = ((long long)pref_prods[j] * suff_prods[j + 1] + 1 % m) * dp[tree[node][i]] % m;
            update(tree[node][i], node);
            ++j;
        }
    }
}

