    for(int i=deg-2; i>=0; i--) (r[i] *= r[i+1]) %= MOD;

    for(int i=0; i<deg; i++){
        if(adj[v][i] != p){
            ll add_c = 1;
            if(i != 0) (add_c *= l[i-1]) %= MOD;
            if(i != deg-1) (add_c *= r[i+1]) %= MOD;
            Rev(v, adj[v][i],add_c);
        }
    }
