std::vector<std::deque<int>> g, pre, suf;
std::vector<i64> q, r;
i64 mod;

i64 dfs(int v, int p) {
    i64 ret = 1;
    pre[v].push_back(1);
    suf[v].push_back(1);
    std::vector<i64> cs;
    for (int c : g[v]) {
        if (c == p) continue;
        i64 cf = dfs(c, v) + 1;
        ret = ret * cf % mod;
        cs.push_back(cf);
    }
    int len = cs.size();
    for (int i = 0; i < len; i++) {
        pre[v].push_back(pre[v].back() * cs[i] % mod);
        suf[v].push_front(suf[v].front() * cs[len - 1 - i] % mod);
    }
    return q[v] = ret;
}

void dfs2(int v, int p, i64 ot) {
    r[v] = ot * q[v] % mod;
    int j = 0;
    for (int i = 0; i < g[v].size(); i++) {
        int c = g[v][i];
        if (c == p) continue;
        dfs2(c, v, (ot * pre[v][j] % mod * suf[v][j + 1] % mod + 1) % mod);
        j++;
    }
}

