#include <bits/stdc++.h>

using namespace std;

//#define FILE_IO

class Integer {
public:
    //Pregateste clasa pentru interactiunea cu un modul - ii calculeaza phi-ul si descompunerea in factori primi
    static void prepare_MOD(int mod) {
        MOD = mod;
        phi = MOD;
        p_sz = 0;
        memset(p, 0, sizeof p);
        for (int i = 2; i * i <= mod; ++ i)
            if (mod % i == 0) {
                p[p_sz ++] = i;
                phi /= i;
                phi *= (i - 1);

                while (mod % i == 0)
                    mod /= i;
            }

        if (mod > 1) {
            p[p_sz ++] = mod;
            phi /= mod;
            phi *= (mod - 1);
            mod = 1;
        }
    }

    Integer() {
        memset(k, 0, sizeof k);
        val = 1;
    }

    Integer(const int &arg) {
        memset(k, 0, sizeof k);
        val = arg;
        if(val == 0)
        {
            for(int i = 0; i < p_sz; i++)
                k[i] = int(1e6);
            return;
        }
        for (int i = 0; i < p_sz; ++ i) {
            while (val % p[i] == 0) {
                val /= p[i];
                ++ k[i];
            }
        }
        val %= MOD;
    }

    Integer operator*(const Integer &arg) const {
        Integer ans;
        for (int i = 0; i < p_sz; ++ i)
            ans.k[i] = k[i] + arg.k[i];
        ans.val = (1LL * val * arg.val) % MOD;
        return ans;
    }

    Integer operator/(const Integer &arg) const {
        Integer ans;
        for (int i = 0; i < p_sz; ++ i)
            ans.k[i] = k[i] - arg.k[i];
        ans.val = (1LL * val * inv(arg.val)) % MOD;
        return ans;
    }

    //Returneaza numarul complet - cu tot cu factorii primi tinuti separat
    int to_int() {
        int ans = val;
        for (int i = 0; i < p_sz; ++ i)
            ans = (1LL * ans * expo(p[i], k[i])) % MOD;
        return ans;
    }
private:
    static const int FACTMAX = 9;
    static int MOD;
    static int phi;
    static int p[FACTMAX];
    static int p_sz;

    //Returneaza a ^ b prin exponentiere rapida
    static int expo(int a, int b) {
        if (!b)
            return 1 % MOD;
        else if (b & 1)
            return (1LL * expo(a, b - 1) * a) % MOD;
        else {
            int aux = expo(a, b >> 1);
            return (1LL * aux * aux) % MOD;
        }
    }

    //Returneaza inversul modular al lui x
    static int inv(int x) {
        return expo(x, phi - 1);
    }

    //X = (facts, val)
    int k[FACTMAX]; // = facts
    int val;
};

int Integer :: MOD;
int Integer :: phi;
int Integer :: p[FACTMAX];
int Integer :: p_sz;

