    for(auto nxt: edg[nod])
    {
        if(nxt == fth)  continue;
        DFS(nxt, nod);
        dpdown[nod][0] = dpdown[nod][0] * dpdown[nxt][0];
        dpdown[nod][1] = dpdown[nod][1] * Integer(dpdown[nxt][1].to_int() + dpdown[nxt][0].to_int());
    }
}

void DFS2(int nod, int fth, Integer dpup[2])
{
    sol[nod] = ((dpdown[nod][1] * dpup[0]).to_int() + (dpdown[nod][1] * dpup[1]).to_int()) % M;
    Integer dpup0 = dpup[0] * dpdown[nod][0];
    Integer dpup1 = dpdown[nod][1] * Integer(dpup[0].to_int() + dpup[1].to_int());
    for(auto nxt: edg[nod])
