    --x, --y;
    tree[x].push_back(y);
    tree[y].push_back(x);
  }

  prod1.resize(N);
  prod2.resize(N);

  rec(tree, 0, -1);
  fill(ALL(visit),false);
  rec2(tree, 0, -1, 0);

  REP(i,N){
    LLI ans = ((dp2[i]+1)%M * dp[i]) % M;
    cout << ans << endl;
  }

  return 0;
}

