ll solve1(int i){
	ll& ret=dp1[i];
	if(ret!=-1ll) return ret;
	ret=1;
	for(int next:adj[i]){
		if(next!=p[i]){
			ret=(ret*(1+solve1(next)))%m;
		}
	}
	return ret;
}
//i를 색칠하고 i를 root로 하는 트리의 여집합(그것 역시 트리)을 칠하는 가짓수
ll solve2(int i){
	ll& ret=dp2[i];
	if(ret!=-1ll) return ret;
	if(i==1) return ret=1;
	ret=1;
	int j=p[i];
	ret=(ret*solve2(j))%m;
	//여기서 시간초과가 난다..같은 j가 여러 케이스에서 방문되고 j의 간선이 많을때
	//j -연결- 1,2,3,,k-1,k,k+1,..i : 현재 next=k일 때 l[k-1]과 r[k+1]를 저장해 놓자
	//dfs로 계산
	for(int next:adj[j]){
		if(next!=i && next!=p[j]) ret=(ret*(1+solve1(next)))%m; 
	}
	ret=(ret+1)%m;
	return ret;
}

void f(int i){
	int len=adj[i].size();
	l[0]=1;
	for(int k=0;k<len;k++){
		if(adj[i][k]==p[i]){l[k+1]=l[k]; continue;}
		l[k+1]=(l[k]*(1+dp1[adj[i][k]]))%m;
	}
	r[len+1]=1;
	for(int k=len;k>=1;k--){
		if(adj[i][k-1]==p[i]){r[k]=r[k+1]; continue;}
		r[k]=(r[k+1]*(1+dp1[adj[i][k-1]]))%m;
	}
	for(int k=1;k<=len;k++){
		int next=adj[i][k-1];
		if(next==p[i]) continue;
		dp2[next]=(1+dp2[i]*(l[k-1]*r[k+1])%m)%m;
	}
	for(int next:adj[i]){
		if(next!=p[i]) f(next);
	}
}

void dfs(int i,int prev){
	p[i]=prev;
	for(int next:adj[i])
		if(next!=prev) dfs(next,i);
}

