void dfs1(int v, int pr) {
	for (auto u : g[v]) {
		if (u == pr) continue;
		dfs1(u, v);
	}
	dp[v] = 1;
	for (auto u : g[v]) {
		if (u == pr) continue;
		dp[v] = (dp[v] * 1ll * (dp[u] + 1)) % mod;
	}
}

void dfs2(int v, int pr, int up) {
	ans[v] = ((up + 1) * 1ll * dp[v]) % mod;
	for (int i = 0; i < SZ(g[v]); i++) {
		if (g[v][i] == pr) {
			swap(g[v][i], g[v][SZ(g[v]) - 1]);
			break;
		}
	}
	vector<int> suff(SZ(g[v]), 1);
	for (int i = SZ(g[v]) - 3; i >= 0; i--) { 
		suff[i] = ((dp[g[v][i + 1]] + 1) * 1ll * suff[i + 1]) % mod;
	}
	int pref = (up + 1);
	for (int i = 0; i < SZ(g[v]) - 1; i++) {
		int u = g[v][i];
		dfs2(u, v, (pref * 1ll * suff[i]) % mod);
		pref = (pref * 1ll * (dp[u] + 1)) % mod;
	}
}

