void calc(){
    for(int i = 1; i <= n; i++){
        ll mul = 1;
        for(int j = 0; j < ad[i].size(); j++){
            mp[i][ad[i][j]] = j;
            mul = mul*(d[ad[i][j]] + 1);
            mul %= mod;
            pre[i].push_back(mul);
        }
        mul = 1;
        for(int j = ad[i].size() - 1;j >= 0; j--){
            mul = mul*(d[ad[i][j]] + 1);
            mul %= mod;
            suf[i].push_back(mul);
        }
    }
}

ll pr(int a, int ind){
    if(ind < 0){
        return 1;
    }else{
        return pre[a][ind];
    }
}

ll sf(int a, int ind){
    ind = suf[a].size() - ind - 1;
    if(ind < 0){
        return 1;
    }else{
        return suf[a][ind];
    }
}



void dfs1(int a, int par){
    d[a] = 1;
    if(adj[a].size() == 1 && par != -1){
        return;
    }
    for(int i: adj[a]){
        if(i != par){
            ad[a].push_back(i);
            dfs1(i, a);
            d[a] *= (d[i] + 1);
            d[a] %= mod;
        }
    }
}

void dfs2(int a, int par, ll pard){
    ans[a] = 1;
    for(int i: adj[a]){
        if(i != par)
            ans[a] *= (d[i] + 1);
        ans[a] %= mod;
    }
    ans[a] *= (pard + 1);
    ans[a] %= mod;
    for(int i: adj[a]){
        if(i == par) continue;
        ll pardi = 1;
        pardi *= pr(a, mp[a][i] - 1);
        pardi %= mod;
        pardi *= sf(a, mp[a][i] + 1);
        pardi %= mod;
        pardi *= pard + 1;
        pardi %= mod;
        dfs2(i, a, pardi);
    }
}

