ll dfs(int now, int par) {
  int idx = -1;
  if (par >= 0) {
    idx = edge2idx[pii(par, now)];
  }
  dp[idx] = 1;
  rep (i, G[now].size()) {
    if (G[now][i] == par) continue;
    ll temp = (dfs(G[now][i], now) + 1) % MOD;
    if (idx >= 0) {
      (dp[idx] *= temp) %= MOD;
    }
  }
  if (idx >= 0) {
    return dp[idx];
  }
}

ll dfs2(int now, int par) {
  int n = G[now].size();
  vl sum1(n + 1, 1), sum2(n + 1, 1);
  rep (i, n) {
    int v = G[now][i];
    sum1[i + 1] = sum1[i] * (dp[edge2idx[pii(now, v)]] + 1) % MOD;
  }
  rrep (i, n) {
    int v = G[now][i];
    sum2[i] = sum2[i + 1] * (dp[edge2idx[pii(now, v)]] + 1) % MOD;
  }
  rep (i, n) {
    int v = G[now][i];
    int idx = edge2idx[pii(v, now)];
    if (dp[idx] >= 0) continue;
    dp[idx] = sum1[i] * sum2[i + 1] % MOD;
  }
  rep (i, n) {
    if (G[now][i] == par) continue;
    dfs2(G[now][i], now);
  }
}

