}
void dfs2(int x,int fa,int sum)
{
	ans[x]=f[x]*sum%mod;
	//printf("dfs2(%d,%d,%d)\n",x,fa,sum);
	qzh[x].resize(sz[x]),hzh[x].resize(sz[x]);
	int last=1;
	for(int i=0;i<sz[x];i++)
	{
		int y=v[x][i];
		if(y==fa) 
		{
			qzh[x][i]=last;
			continue;
		}
		qzh[x][i]=(f[y]+1)*last%mod;
		last=qzh[x][i];
	}
	last=1;
	if(sz[x])
	{
		for(int i=sz[x]-1;i>=0;i--)
		{
			int y=v[x][i];
			if(y==fa) 
			{
				hzh[x][i]=last;
				continue;
			}
			hzh[x][i]=(f[y]+1)*last%mod;
			last=hzh[x][i];
		}
	}
	for(int i=0;i<sz[x];i++)
	{
		int y=v[x][i];
		if(y==fa) continue;
		int nxs=sum;
		if(i>0) nxs=nxs*qzh[x][i-1]%mod;
		if(i<sz[x]-1) nxs=nxs*hzh[x][i+1]%mod;
		dfs2(y,x,nxs+1);
	}
}
