template<typename T>
struct cummurative_mul {
    vector<T> fronts_;
    vector<T> backs_;
    int n_;

    cummurative_mul(const vector<T>& vs) {
        fronts_.resize(vs.size(), 1);
        backs_.resize(vs.size(), 1);
        int n_ = vs.size();
        fronts_[0] = vs[0];
        backs_[n_ - 1] = vs[n_ - 1];
        for (int i = 0; i < n_ -1; i++) {
            fronts_[i + 1] = fronts_[i] * vs[i + 1];
            backs_[n_ - i - 2] = backs_[n_ - i - 1] * vs[n_ - i - 2];
        }
    }

    T excepts(int index) {
        ll i = 1;
        if (index > 0) i *= fronts_[index - 1];
        if (index < n_ - 1) i *= backs_[index + 1];
        return i;
    }
};


void publish_core(int current, int from) {
    vector<ll> vv;
    for (int i = 0; i < g[current].size(); i++) {
        vv.push_back(dp[g[current][i]][current]);
    }
    auto mm = cummurative_mul<ll>(vv);
    for (int i = 0; i < g[current].size(); i++) {
        if (g[current][i] == from) continue;
        ll v = mm.excepts(i);
        dp[current][g[current][i]] = v + 1;
        publish_core(g[current][i], current);
    }
}


void publish(int current) {
    vector<ll> vv;
    for (int i = 0; i < g[current].size(); i++) {
        vv.push_back(dp[g[current][i]][current]);
    }
    auto mm = cummurative_mul<ll>(vv);
    for (int i = 0; i < g[current].size(); i++) {
        ll v = mm.excepts(i);
        dp[current][g[current][i]] = v + 1;
        publish_core(g[current][i], current);
    }
}

ll dfs(int current, int from) {
	if (dp[current].count(from)) {
		return dp[current][from];
	}
	ll v = 1;
	for (auto to : g[current]) {
		if (to == from) continue;
        ll d  = dfs(to, current);
        v *= d;
		v %= m;
	}
	if (from != -1) {
		v++;
	}
	dp[current][from] = v % m;
	return dp[current][from];
}

ll dfs2(int current) {
    ll v = 1;
    for (auto to : g[current]) {
        ll d = dfs(to, current);
        v *= d;
        v %= m;
    }
    return v % m;
}

