        cin >> x >> y;
        tree[x - 1].push_back(y - 1);
        tree[y - 1].push_back(x - 1);
    }

    dp.resize(n);
    dfs(0, -1);
    update(0, -1);
    for (int i = 0; i < n; ++i)
        cout << dp[i] << "\n";

    return 0;
}

