template <class T>
class segtree
{
public:
  lli n;
  vector<T> dat;
  function<T(T, T)> func;
  T dummy;
  segtree<T>(lli _n, T ini, function<T(T, T)> f, T dummy) : func(f), dummy(dummy)
  {
    n = 1;
    while (n < _n)
    {
      n = n * 2;
    }
    dat.assign(2 * n - 1, ini);
  }
  void update(lli k, T a)
  {
    k += n - 1;
    dat[k] = a;
    while (k > 0)
    {
      k = (k - 1) / 2;
      dat[k] = func(dat[k * 2 + 1], dat[k * 2 + 2]);
    }
  }
  T query(int a, int b)
  {
    return query(a, b, 0, 0, n);
  }
  // [a,b)の何かを求める.
  T query(int a, int b, int k, int l, int r)
  {
    //交差しないときはダミー
    if (r <= a || b <= l)
      return dummy;
    if (a <= l && r <= b)
      return dat[k];
    else
    {
      T vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
      T vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
      return func(vl, vr);
    }
  }
  T get(int a)
  {
    return query(a, a + 1, 0, 0, n);
  }
};
lli dfs1(int u, int p)
{
  // uがblack

  lli ret = 1; /* 全部white */
  for (auto s : e[u])
  {
    if (s == p)
      continue;
    ret *= (dfs1(s, u) + 1);
    ret %= M;
  }
  dp[u] = ret;
  return ret;
}
void dfs2(int u, int p, lli val)
{
  // uがblack

  lli ret = 1; /* 全部white */
  for (auto s : e[u])
  {
    if (s == p)
    {
      ret *= val + 1;
    }
    else
    {
      ret *= (dp[s] + 1);
    }
    ret %= M;
  }
  ans[u] = ret;
  auto f = [](lli a, lli b) { return (a * b) % M; };
  lli first = 1;
  segtree<lli> seg(e[u].size(), first, f, first);
  rep(i, e[u].size()) if (e[u][i] != p) seg.update(i, dp[e[u][i]] + 1);

  rep(i, e[u].size())
  {
    int s = e[u][i];
    if (s == p)
      continue;
    lli v = seg.query(0, i) * seg.query(i + 1, e[u].size()) % M * (val + 1) % M;
    dfs2(s, u, v);
  }
}
void solve(long long N, long long MM, std::vector<long long> x,
           std::vector<long long> y)
{
  M = MM;
  rep(i, N - 1) e[x[i] - 1].push_back(y[i] - 1);
  rep(i, N - 1) e[y[i] - 1].push_back(x[i] - 1);
  dfs1(0, -1);
  dfs2(0, -1, 0);
  rep(i, N)
  {
    cout << ans[i] << endl;
  }
}

