template <typename T>
class func{
public: // 0-index
	vector<T> datf,datb;
	T M,initial;
	int n;
	T f(T a,T b){
		return (a*b) % M;
	}
	void final_updete(int j,T x){
		for(int i=j;i<n;i++) (datf[i] *= x ) %= M;
		for(int i=j;i>=0;i--) (datb[i] *= x ) %= M;
	}
	void init(int n_,T initial_,T M_){
		M = M_;
		n = n_;
		initial = initial_;
		datf.resize(n,initial);
		datb.resize(n,initial);
	}
	void update(int i,T x){
		datb[i] = x;
		datf[i] = x;
	}
	void calc(){
		for(int i=1;i<n;i++) datf[i] = f(datf[i],datf[i-1]);
		for(int i=n-2;i>=0;i--)datb[i] = f(datb[i],datb[i+1]);
	}
	T get_b(int i){
		if(i>=n || i<0) return initial;
		return datb[i];
	}
	T get_f(int i){
		if(i>=n || i<0) return initial;
		return datf[i];
	}
	T get_except(int i){
		return f(get_f(i-1),get_b(i+1));
	}
	T get_all(){
		return datb[0];
	}
};

vector<int> leaf(const vector<int> &u,const vector<int> &v){
	int N = u.size() + 1;
	vector<int> G(N,0),res;
	for(int i=0;i<N-1;i++){
		G[u[i]]++;
		G[v[i]]++;
	}
	for(int i=0;i<N;i++){
		if(G[i] == 1){
			res.push_back(i);
		}
	}
	return res;
}

vector< pair<int,int> > leaf_to_root(const vector<int> &u,const vector<int> &v,const int root){
	// return <parent,child>
	int yet = 1000000000;
	vector<int> d(u.size()+1,yet);
	vector< pair<int,int> > res;
	queue<int> Q;
	Q.push(root);
	d[root] = 0;
	vector< vector<int> > G(u.size()+1);
	for(int i=0;i<u.size();i++){
		G[u[i]].push_back(v[i]);
		G[v[i]].push_back(u[i]);
	}
	while( Q.size() ){
		int now = Q.front();
		Q.pop();
		for(auto nex:G[now]){
			if(d[nex]!=yet)continue;
			d[nex] = d[now] + 1;
			Q.push(nex);
			res.push_back( make_pair(now,nex) );
		}
	}
	reverse(res.begin(), res.end());
	return res;
}


