int add(int a, int b)
{
	a = (a + mod) % mod;
	b = (b + mod) % mod;
	return (a + b) % mod;
}

int mul(int a, int b)
{
	return (1ll * a * b) % mod;
}

void dfs(int node, int parent)
{
	int cur = 1;
	for(int i = 0; i < g[node].size(); i++)
	{
		int child = g[node][i];
		if(child != parent){
			dfs(child, node);
			cur = mul(cur, dp[child]);
		}
		pre[node].push_back(cur);
	}
	cur = 1;
	for(int i = (int)g[node].size() - 1; i >= 0; i--)
	{
		int child = g[node][i];
		if(child != parent){
			cur = mul(cur, dp[child]);
		}
		suf[node].push_front(cur);
	}
	dp[node] = add(1, cur);
}

void dfs2(int node, int parent, int val_parent)
{
	dp[node] = add(dp[node], -1);
	dp[node] = mul(dp[node], val_parent);
	dp[node] = add(dp[node], 1);
	sol[node] = dp[node];
	for(int i = 0; i < g[node].size(); i++)
	{
		int child = g[node][i];
		if(child != parent){
			int p = 1, s = 1;
			if(i)
				p = pre[node][i - 1];
			if(i + 1 < g[node].size())
				s = suf[node][i + 1];
			dfs2(child, node, add(1, mul(mul(p, s), val_parent)));
		}
	}
}

