void dfs2(int u,int p, ll arriba){
	vi nodes;
	for(auto &v : graph[u]){
		if(v == p)continue;
		nodes.pb(v);
	}
	if(nodes.empty())return;
	vector<ll> l(nodes.size()),r(nodes.size());
	l[0] = (dp1[nodes[0]]+1);
	r[nodes.size()-1] = (dp1[nodes.back()]+1);
	forn(i,1,nodes.size()){
		l[i] = ((l[i-1]%M)*(dp1[nodes[i]]+1))%M;
	}
	forr(i,nodes.size()-2,0){
		r[i] = ((r[i+1]%M)*(dp1[nodes[i]]+1))%M;
	}
	int cnt = 0;
	for(auto &v : graph[u]){
		if(v == p)continue;
		ll p1 = (cnt-1 < 0) ? 1 : l[cnt-1];
		ll p2 = (cnt+1 >= nodes.size()) ? 1 : r[cnt+1];
		ll sum = ((p1%M)*(p2%M))%M;
		dp3[v] = ((sum%M)*(arriba%M))%M; dp3[v]++;
		dp3[v] %= M;
		dfs2(v,u,dp3[v]);
	}
