void dfs1(int node, int pn)
{
  dp1[node] = 1;
  for(int i=0;i<adj[node].size();i++)
    if(adj[node][i] != pn)
    {
      dfs1(adj[node][i], node);
      dp1[node] = (dp1[node] * (1 + dp1[adj[node][i]])) % mod;
    }
  return;
}


void dfs2(int node, int pn)
{
  dp2[node] = dp1[node];

  ll int prev=1, front=1;

  pre[node].resize(adj[node].size());
  suf[node].resize(adj[node].size());

  for(int i=0;i<adj[node].size();i++)
  {
    if(adj[node][i] != pn)
    {
      pre[node][i] = (prev * (1+dp1[adj[node][i]])) % mod;
      prev = pre[node][i];
    }
    pre[node][i] = prev;
  }

  for(int i=adj[node].size()-1;i>=0;i--)
  {
    if(adj[node][i] != pn)
    {
      suf[node][i] = (front * (1+dp1[adj[node][i]])) % mod;
      front = suf[node][i];
    }
    suf[node][i] = front;
  }

  for(int i=0;i<adj[node].size();i++)
    if(adj[node][i] != pn)
    {
      ll int mul = 1;
      if(i != 0)
        mul = (mul * pre[node][i-1]) % mod;
      if(i != adj[node].size()-1)
        mul = (mul * suf[node][i+1]) % mod;

      ll int a = dp1[node];
      dp1[node] = mul;
      ll int b = dp1[adj[node][i]];
      dp1[adj[node][i]] = (dp1[adj[node][i]] * (1+dp1[node])) % mod;
      dfs2(adj[node][i], node);
      dp1[adj[node][i]] = b;
      dp1[node] = a;
    }
  return;
}


