struct SegTree{
    vector<ll> p, s;
    ll pr = 1;

    void build(vector<ll> &o){
        p[0] = s[s.size() - 1] = 1;
        for(ll i = 1; i < o.size(); ++i) p[i] = p[i - 1] * o[i - 1] % m;
        for(ll i = ll(o.size()) - 2; i >= 0; --i) s[i] = s[i + 1] * o[i + 1] % m;
    }

    SegTree(){}

    SegTree(vector<ll> &o){
        if(o.empty()) o.push_back(1);
        for(ll e: o) pr = pr * e % m;
        p.resize(o.size());
        s.resize(o.size());
        build(o);
    }

    ll q(ll i){
        return p[i] * s[i] % m;
    }
};

