void dfs_in(int u, int p) {
    in[u] = 1;
    for(int v : adj[u]) {
        if(v == p) continue;
        dfs_in(v, u);

        in[u] *= (in[v] + 1) % mod;
        in[u] %= mod;
    }

}

void dfs_out(int u, int p) {

    for(int v : adj[u]) { //childs of u
        if(v == p) continue;

        ll brothers = 1LL;

        for(int b : adj[u]) { //brothers of u
            if(b == v || b == p) continue;

            brothers *= (in[b] + 1) % mod;
            brothers %= mod;
        }

        out[v] = 1 + (brothers * out[u]) % mod;
        out[v] %= mod;
        dfs_out(v, u);
    }
}

