struct Factorial {

  int modpow(int& a, u64 n) noexcept {
    if (n == 0) return 1;
    auto t = modpow(a, n / 2);
    t = (int)((i64)t * t % mod);
    if (n & 1) t = (int)((i64)t * a % mod);
    return t;
  }

