    f.reserve(count + 1);
    fi.reserve(count + 1);

    f.push_back(1);
    fi.push_back(1);
    FOR(i, 1, count + 1) {
      f.push_back((int)(((i64)f[i - 1] * i) % mod));
      fi.push_back(modpow(f[i], mod - 2));
      //cout << i << " " << f[i] << " " << fi[i] << newl;
