    for (int b:edges[a])
    {
        if (b==parent)
            continue;

        children[a].push_back(b);
        dfs_one(b,a);
        p=merge(p,down[b]);
        downs[a].push_back(down[b]);
    }

    down[a]=process(p);
}

void dfs_two (int a,int parent)
{
    for (int i=0;i<children[a].size();i++)
    {
        pair <int,int> p{1,0};
        if (i!=0)
            p=merge(p,pref[a][i-1]);
        if (i!=downs[a].size()-1)
            p=merge(p,suf[a][i+1]);
        if (a!=1)
            p=merge(p,up[a]);

        int b=children[a][i];
        up[b]=process(p);
        dfs_two(b,a);
    }
}
int main()
{
    //freopen("input.txt","r",stdin);
    //freopen("output.txt","w",stdout);
    ios_base::sync_with_stdio(false);

    int n;
    cin >> n >> mod;

    for (int i = 1;i < n; i++)
    {
        int a,b;
        cin >> a >> b;
        edges[a].push_back(b);
        edges[b].push_back(a);
    }

    dfs_one(1,-1);

    for (int a=1;a<=n;a++)
    {
        int k=downs[a].size();
        pair <int,int> p(1,0);
        for (int i=0;i<k;i++)
        {
            p=merge(p,downs[a][i]);
            pref[a].push_back(p);
        }

        p = {1,0};
        for (int i=k-1;i>=0;i--)
        {
            p=merge(p,downs[a][i]);
            suf[a].push_back(p);
        }

        reverse(suf[a].begin(),suf[a].end());
    }

    dfs_two(1,-1);

    for (int a=1;a<=n;a++)
    {
        pair <int,int> p{1,0};
        if (a!=1)
            p=merge(p,up[a]);
        if (children[a].size()!=0)
            p=merge(p,pref[a].back());
        p=process(p);
        cout << p.second << endl;
    }
}

