using namespace std;

const int maxm=1e5+10;

int N,Mod,head[maxm],tot;
int Father[maxm],Step;
long long DP[maxm],DP2[maxm];
vector<long long> Num[maxm],Left[maxm],Right[maxm];

struct edge{
	int To;
	int Next;
	# define To(x) Edge[x].To
	# define Next(x) Edge[x].Next
}Edge[maxm<<1];

inline void Add_Edge(int From,int To){Edge[++tot]=(edge){To,head[From]};head[From]=tot;return;}
inline void Insert_Edge(int x,int y){Add_Edge(x,y),Add_Edge(y,x);return;}

void Dfs(int now){
	DP[now]=1;
	for(int i=head[now];i;i=Next(i)){
		if(To(i)==Father[now]) continue;
		Father[To(i)]=now;
		Dfs(To(i));
		DP[now]=(DP[now]*(1+DP[To(i)]))%Mod;
		Num[now].push_back((1+DP[To(i)])%Mod);
	}
	return;
}

inline void Work(int now){
	register int i;
	register long long Result;
	sort(Num[now].begin(),Num[now].end());
	Result=1;
	Left[now].push_back(1);
	for(i=0;i<Num[now].size();i++){
		Result=(Result*Num[now][i]);
		Left[now].push_back(Result);
	}
	Result=1;
	Right[now].push_back(1);
	for(i=Num[now].size()-1;i>=0;i--){
		Result=(Result*Num[now][i]);
		Right[now].push_back(Result);
	}
	return;
}

void Dfs2(int now){
	if(now==1){
		DP2[now]=DP[now];
		Work(now);
	}else{
		long long Now;
		Step=(lower_bound(Num[Father[now]].begin(),Num[Father[now]].end(),DP[now]+1)-Num[Father[now]].begin());
		Now=(Left[Father[now]][Step]*Right[Father[now]][Num[Father[now]].size()-Step-1])%Mod;
		Num[now].push_back((Now+1)%Mod);
		DP2[now]=(Now+1)*DP[now]%Mod;
		Work(now);
	}
	for(int i=head[now];i;i=Next(i)){
		if(To(i)==Father[now]) continue;
		Dfs2(To(i));
	}
	return;
}

int main(){
	register int i;
	int x,y;
	long long Result;
	scanf("%d%d",&N,&Mod);
	for(i=1;i<N;i++){
		scanf("%d%d",&x,&y);
		Insert_Edge(x,y);
	}
	Dfs(1);
	Dfs2(1);
	for(i=1;i<=N;i++){
		printf("%lld\n",DP2[i]);
	}
	return 0;
}

