template<typename T>
struct treeDP{
  vvl G;
  T INIT, ZERO;
  vector<T> TMP_DATA, dat;
  function<T(T, T)> f;
  function<T(T)> g;
  treeDP(ll n, T init, T zero, function<T(T, T)> func, function<T(T)> func2):f(func), g(func2){
    G.resize(n+1, vector<ll>(0));
    dat.resize(n+1, zero);
    TMP_DATA.resize(n+1, zero);
    INIT = init, ZERO = zero;
  }

  inline void dfs(ll now, ll from){
    ll cnt = 0;
    for(int i=0;i<G[now].size();i++){
      if(G[now][i]==from) continue;
      dfs(G[now][i], now);
      TMP_DATA[now] = f(TMP_DATA[now], g(TMP_DATA[G[now][i]]));
      cnt++;
    }
    if(cnt==0) TMP_DATA[now] = INIT;
  }

  inline void dfs2(ll now, ll from, T rev){
    vector<T> left, right;
    for(int i=0;i<G[now].size();i++){
      ll to = G[now][i];
      if(to==from) continue;
      left.push_back(g(TMP_DATA[to]));
      ll s = left.size();
      if(s!=1) left[s-1] = f(left[s-1], left[s-2]);
    }
    for(int i=0;i<G[now].size();i++){
      ll to = G[now][G[now].size()-1-i];
      if(to==from) continue;
      right.push_back(g(TMP_DATA[to]));
      ll s = right.size();
      if(s!=1) right[s-1] = f(right[s-1], right[s-2]);
    }

    dat[now] = f((left.size()==0?ZERO:left[left.size()-1]), rev);

    ll cnt = 0;
    for(int i=0;i<G[now].size();i++){
      ll to = G[now][i];
      if(to==from) continue;
      T tmp = rev;
      if(cnt!=0) tmp = f(tmp, left[cnt-1]);
      if(cnt!=right.size()-1) tmp = f(tmp, right[right.size()-2-cnt]);
      dfs2(to, now, g(tmp));
      cnt++;
    }
  }

  void insert(ll a, ll b){ G[a].push_back(b);G[b].push_back(a); }

  void calc(){
    ll root = -1;
    for(int i=1;i<=G.size();i++) {
      if(G[i].size()==1) {
        root = i;
        break;
      }
    }
    dfs(root, -1);
    dfs2(root, -1, INIT);
  }
  T & operator [](int i){return dat[i];}
};

ll mg(ll a, ll b){
  return (a*b)%P;
}
ll st(ll a){
  return (a+1)%P;
}

int main(int argc, char const *argv[]) {
  ll n;std::cin >> n >> P;
  treeDP<ll> tdp(n+1, 1, 1, mg, st);

  re(i, n-1){
    ll a, b;scanf("%lld %lld", &a, &b);
    tdp.insert(a, b);
  }
  tdp.calc();
  for(int i=1;i<=n;i++) std::cout << tdp[i] << '\n';
}

