void dfs1(ll v,ll par)
{
    in[v] = 1;
    for(auto it: adj[v]) if(it != par){
        dfs1(it,v);
        in[v] = (in[v] * (1 + in[it]) % m) % m;
    }
}
void dfs2(ll v,ll par)
{
    ll sz = adj[v].size();
    vi pre(sz), suf(sz);
    for(ll i = 0;i < sz;i += 1){
        auto it = adj[v][i];
        if(it == par){
            if(i) pre[i] = pre[i - 1];
            else
                pre[i] = 1;
        }
        else{
            if(i) pre[i] = (pre[i - 1] * (1 + in[it])) % m;
            else
                pre[i] = (1 + in[it]) % m;
        }
    }

    for(ll i = sz - 1;i >= 0;i -= 1){
        auto it = adj[v][i];
        if(it == par){
            if(i < sz - 1) suf[i] = suf[i + 1];
            else
                suf[i] = 1;
        }
        else{
            if(i < sz - 1) suf[i] = (suf[i + 1] * (1 + in[it])) % m;
            else
                suf[i] = (1 + in[it]) % m;
        }
    }

    ll Pre, Suf;
    for(ll i = 0;i < sz;i += 1){
        auto it = adj[v][i];
        if(it == par) continue;
        Pre = Suf = 1;
        if(i) Pre = pre[i - 1];
        if(i < sz - 1)
            Suf = suf[i + 1];
        out[it] = (((out[v] * Pre) % m * Suf) % m + 1) % m;
        dfs2(it,v);
    }
}
