	int cur=1;
	for(int i=0;i<G[v].size();i++)
	{
		ll u=G[v][i];
		if(u==p)
		{
			pre.push_back(cur);
			continue;
		}
		cur=cur*(1+dp[u])%MOD;
		pre.push_back(cur);
	}
	cur=1;
	for(int i=G[v].size()-1;i>=0;i--)
	{
		int u=G[v][i];
		if(u==p)
