inline ll add(ll a, ll b)
{
    ll x = a + b;
    if (x >= m)
    {
        x -= m;
    }
    return x;
}

ll dfs(int i)
{
    if (dp[i] != 0)
    {
        return dp[i];
    }
    if (v[i].size() == 1 && i != 1)
    {
        pre[i] = 1;
        suf[i] = 1;
        dp[i] = 1;
        return 1LL;
    }
    visited[i] = 1;
    ll s = 1;
    for (auto ch : v[i])
    {
        if (!visited[ch])
        {
            ll x = add(1, dfs(ch));
            s = (s * x) % m;
        }
    }
    ll a = 1, b = 1;
    for (int j = 0; j < v[i].size(); j++)
    {
        int ch = v[i][j];
        pre[ch] = a;
        if (!visited[ch])
        {
            ll x = add(1, dfs(ch));
            a = (a * x) % m;
        }
    }
    for (int j = v[i].size() - 1; j >= 0; j--)
    {
        int ch = v[i][j];
        suf[ch] = b;
        if (!visited[ch])
        {
            ll x = add(1, dfs(ch));
            b = (b * x) % m;
        }
    }
    dp[i] = s;
    visited[i] = 0;
    return s;
}

