struct Edge {
    int src, dst;
    ll w;
    Edge(int _s, int _d, ll _w = -1) : src(_s), dst(_d), w(_w) {}
    Edge() : w(-1) {}
};

int N, MOD;
vector<vector<Edge>> adj;

ll Dfs(const int p, const int v) {
    ll res = 1;
    for (auto &&e : adj[v]) {
        if (e.dst == p) continue;
        if (e.w == -1) e.w = Dfs(v, e.dst);
        (res *= (e.w + 1)) %= MOD;
    }
    return res % MOD;
}

