        for (auto &&e : adj[v])
            if (e.w == -1) e.w = Dfs(e.src, e.dst);
    }

    for (int v = 0; v < N; ++v) {
        ll ans = 1;
        for (const auto &e : adj[v])
            (ans *= (e.w + 1)) %= MOD;
