void dfs(long long curr , long long par){
	cnt += 1;
	num[curr] = cnt;
	renum[cnt] = curr;
	for(long long i : graph[curr]){
		if(i == par){
			continue;
		}
		dfs(i,curr);
	}
}

long long getans1(long long curr , long long st){
	if(curr == vals[st].size()){
		return 1;
	}
	if(dpr[st][curr] != -1){
		return dpr[st][curr];
	}
	long long ret = getans1(curr+1,st)*(vals[st][curr]+1);
	return dpr[st][curr] = ret%m;
}

long long getans2(long long curr , long long st){
	if(curr == -1){
		return 1;
	}
	if(dpl[st][curr] != -1){
		return dpl[st][curr];
	}
	long long ret = getans2(curr-1,st)*(vals[st][curr]+1);
	return dpl[st][curr] = ret%m;
}

