struct Task {
    int N;
    long long modulo;
    vector< vector<int> > adj;
    vector< vector<int> > children;
    vector< vector< pair<int, int>> > prefix;
    vector< vector< pair<int, int>> > suffix;
    vector< pair<int, int> > down;
    vector< pair<int, int> > up;

    void readInput() {
        N = readInt();
        modulo = readInt();
        adj.resize(N);

        for (int i = 0; i < N - 1; ++i) {
            int u = readInt() - 1, v = readInt() - 1;
            adj[u].push_back(v);
            adj[v].push_back(u);
        }

        down.resize(N);
        up.resize(N);
        children.resize(N);
        prefix.resize(N);
        suffix.resize(N);
    }

    int mul(int a, int b) {
        return (1LL * a * b) % modulo;
    }

    int add(int a, int b) {
        return (a + b) % modulo;
    }

    void merge(pair<int, int>& u, const pair<int, int>& v) {
        u.black = mul(u.black, add(v.white, v.black));
        u.white = mul(u.white, v.white);
    }

    void dfsDown(int u, int p) {
        down[u] = {1, 1};

        for (int v : adj[u]) {
            if (v != p) {
                dfsDown(v, u);
                children[u].push_back(v);
                merge(down[u], down[v]);
                // down[u].black = mul(down[u].black, add(down[v].white, down[v].black));
                // down[u].white = mul(down[u].white, down[v].white);
            }
        }
    }

    void dfsUp(int u, int parent) {
        if (parent == -1) {
            up[u] = {1, 1};
        }

        for (int i = 0; i < size(children[u]); ++i) {
            pair<int, int> p = up[u];
            int v = children[u][i];
            BUG(u); BUG(v); BUG(i);
            BUG(up[u]);
            BUG(p);

            if (i - 1 >= 0) {
            BUG(prefix[u][i - 1]);
                p.black = mul(p.black, prefix[u][i - 1].black);
                BUG(p);
            }

            if (i + 1 < size(suffix[u])) {
            BUG(suffix[u][i + 1]);
                p.black = mul(p.black, suffix[u][i + 1].black);
                BUG(p);
            }

            up[v] = {p.black + p.white, p.white};
            BUG(up[v]);
            dfsUp(v, u);
        }
    }

    void solve() {
        dfsDown(0, -1);

        // calculate prefix and suffix of downs
        for (int u = 0; u < N; ++u) {
            pair<int, int> p = {1, 1};
            prefix[u].resize(size(children[u]));
            suffix[u].resize(size(children[u]));

            for (int k = 0; k < size(children[u]); ++k) {
                int v = children[u][k];
                merge(p, down[v]);
                prefix[u][k] = p;
            }

            p = {1, 1};

            for (int k = size(children[u]) - 1; k >= 0; --k) {
                int v = children[u][k];
                merge(p, down[v]);
                suffix[u][k] = p;
            }
        }

        dfsUp(0, -1);

        for (int i = 0; i < N; ++i) {
            BUG(i);
            BUG(up[i].black); BUG(down[i].black);
            int result = mul(up[i].black, down[i].black);

            cout << result << endl;
        }

    }

    void perform() {
        readInput();
        solve();
    }
};

int main()
{
    Task task;
    task.perform();

    return 0;
}

