int N, MOD;
std::vector<std::vector<int>> G;
std::vector<std::vector<ll>> dp;

ll dfs(const int v, const int p = -1) {
  ll res = 1;
  rep(i, sz(G[v])) {
    if ( G[v][i] == p ) continue;
    dp[v][i] = dfs(G[v][i], v);
    res *= (dp[v][i] + 1 ) % MOD;
    res %= MOD;
  }
  return res % MOD;
}

void rev(const int v, const int p = -1, const ll add = 0) {
  rep(i, sz(G[v])) {
    if (G[v][i] == p) {
      dp[v][i] = add;
      break;
    }
  }

  const int deg = G[v].size();
  std::vector<ll> l(deg), r(deg);
  for (int i = 0; i < deg; ++i) r[i] = ((l[i] = (dp[v][i] + 1)) %= MOD);
  for (int i = 1; i < deg; ++i) (l[i] *= l[i - 1]) %= MOD;
  for (int i = deg - 2; 0 <= i; --i) (r[i] *= r[i + 1]) %= MOD;

  for (int i = 0; i < deg; ++i) {
    if (G[v][i] == p) continue;
    ll add_c = 1;
    if (i != 0) (add_c *= l[i - 1]) %= MOD;
    if (i != deg - 1) (add_c *= r[i + 1]) %= MOD;
    rev(G[v][i], v, add_c);
  }
  return;
}

int main() {
