int dfs(int v, int p) {
	dp[v] = 1;
	vector<int> childs;

	for(int x : G[v])
		if(x != p) {
			mult(dp[v], 1+dfs(x,v));
			tab[x] = childs.size();
			childs.push_back(x);
			ps[v].push_back(dp[v]);

		}

	int aux = 1;
	for(int i = (int)childs.size()-1; i >= 0; i--) {
		int x = childs[i];
		mult(aux, 1+dp[x]);
		ss[v].push_back(aux);
	}

	return dp[v];
}

void dfs2(int v, int p) {
	ans[v] = dp[v];
	if(v != p) {
		int idx = tab[v];

		int prefVal = idx ? ps[p][idx-1] : 1;
		int sufVal = (int)ss[p].size()-2-idx < 0 ? 1 : ss[p][(int)ss[p].size()-2-idx];

		mult(prefVal, sufVal);

		int tot = (1+prefVal)%m;
		ans[v] = ((ll)ans[v]*tot)%m;
		ps[v].push_back(ans[v]);

		ss[v].insert(ss[v].begin(), 1);

		for(int i = 0; i < ss[v].size(); i++)
			mult(ss[v][i], tot);
	}

	for(int x : G[v])
		if(x != p)
			dfs2(x,v);
}

