void dfs(int pos) {
	used[pos] = true;
	long long V = 1;
	for (int i = 0; i < X[pos].size(); i++) {
		if (used[X[pos][i]] == true) continue;
		Y[pos].push_back(X[pos][i]);
		dfs(X[pos][i]);
		V *= (dp[X[pos][i]] + 1); V %= mod;
	}
	dp[pos] = V;
}

void dfs2(int pos, long long ret) {
	vector<long long>L(Y[pos].size(), 0), R(Y[pos].size(), 0);
	for (int i = 0; i < Y[pos].size(); i++) { L[i] = 0; R[i] = 0; }
	long long V1 = 1;
	for (int i = 0; i < Y[pos].size(); i++) {
		V1 *= (dp[Y[pos][i]] + 1LL); V1 %= mod;
		L[i] = V1;
	}
	long long V2 = 1;
	for (int i = Y[pos].size() - 1; i >= 0; i--) {
		V2 *= (dp[Y[pos][i]] + 1LL); V2 %= mod;
		R[i] = V2;
	}

	for (int i = 0; i < Y[pos].size(); i++) {
		long long G1 = 1; if (i >= 1) G1 = L[i - 1];
		long long G2 = 1; if (i < (int)Y[pos].size() - 1) G2 = R[i + 1];
		ans[Y[pos][i]] = (((G1 * G2) % mod) * ret + 1); ans[Y[pos][i]] %= mod;
	}
	for (int i = 0; i < Y[pos].size(); i++) dfs2(Y[pos][i], ans[Y[pos][i]]);
}

