using namespace std;
const int N = 2e5 + 5;

int n, mod, dp[N], ans[N];
vector<int> adj[N], prefix[N], suffix[N];

int add(int a, int b){
    a = (a + mod) % mod;
    b = (b + mod) % mod;
    return (a + b) % mod;
}

int mul(int a, int b){
    a = (a + mod) % mod;
    b = (b + mod) % mod;
    return 1ll * a * b % mod;
}

void dfs(int node, int par){
    prefix[node] = vector<int>(adj[node].size());
    suffix[node] = vector<int> (adj[node].size());
    int cur = 1;
    for(int i = 0; i < adj[node].size(); i++){
        int child = adj[node][i];
        if(child != par){
            dfs(child, node);
            cur = mul(cur, dp[child] + 1);
        }
        prefix[node][i] = cur;
    }
    dp[node] = cur;
    cur = 1;
    for(int i = (int) adj[node].size() - 1; i >= 0; i--){
        int child = adj[node][i];
        if(child != par){
            cur = mul(cur, dp[child] + 1);
        }
        suffix[node][i] = cur;
     }
}

void solve(int node, int par){
    ans[node] = dp[node];
    for(int i = 0; i < adj[node].size(); i++){
        int child = adj[node][i];
        if(child == par) continue;
        int dp_node = dp[node], dp_child = dp[child];
        dp[node] = 1;
        if(i){
            dp[node] = mul(dp[node], prefix[node][i - 1]);
        }
        if(i + 1 < adj[node].size()){
            dp[node] = mul(dp[node], suffix[node][i + 1]);
        }
        dp[node] = mul(dp[node], dp[par] + 1);
        // dp[node] = add(1, dp[node]);

        dp[child] = mul(dp[child], 1 + dp[node]);

        solve(child, node);

        dp[node] = dp_node;
        dp[child] = dp_child;
    }
}


