#include <bits/stdc++.h>
using namespace std;
const int maxn = 100100;
vector<int> e[maxn];
vector<int> all[maxn], l[maxn], r[maxn];
int pi[maxn], f[maxn], g[maxn];
int M;
void init(int x){
  for(int v : e[x]){
    if(v == pi[x]) continue;
    pi[v] = x;
    init(v);
  }
  for(int v : e[x]){
    if(v == pi[x]) all[x].push_back(1);
    else all[x].push_back(f[v]);
  }
  int sz = all[x].size();
  l[x].resize(sz);
  r[x].resize(sz);
  int mull = 1, mulr = 1;
  for(int i = 0; i < sz; i++){
    mull = 1ll * mull * all[x][i] % M;
    mulr = 1ll * mulr * all[x][sz - 1 - i] % M;
    l[x][i] = mull;
    r[x][sz - 1 - i] = mulr;
  }
  g[x] = mull;
  f[x] = mull + 1;
  if(f[x] >= M) f[x] -= M;
}
int mul(long long a, long long b){
  return a * b % M;
}
void fix(int x, int ml = 1){
  int sz = e[x].size();
  for(int i = 0; i < sz; i++){
    int v = e[x][i];
    if(v == pi[x]) continue;
    int mull = i ? l[x][i - 1] : 1;
    int mulr = (i+1<sz) ? r[x][i + 1] : 1;
    int ncontrib = mul(mul(mull, mulr), ml) + 1;
    if(ncontrib >= M) ncontrib -= M;
    g[v] = mul(g[v], ncontrib);
    fix(v, ncontrib);
  }
}   
int main(){
  int n; cin >> n >> M;
  for(int i = 0; i < n - 1; i++){
    int x, y; cin >> x >> y;
    e[x].push_back(y);
    e[y].push_back(x);
  }
  init(1);
  fix(1);
  for(int i = 1; i <= n; i++) cout << g[i] << endl;
  return 0;
}

