void DFS(int x, int p, int T) {
    ans[x] = dp[x] * (T + 1) % mod;
    vector<int> L(G[x].size());
    vector<int> R(G[x].size());
    for(int i = 0; i < (int)G[x].size(); i++) {
        int v = (G[x][i] == p ? T : dp[G[x][i]]) + 1;
        if(i) L[i] = L[i - 1] * v % mod;
        else {
            L[i] = v;
        }
    }
    for(int i = (int)G[x].size() - 1; i >= 0; i--) {
        int v = (G[x][i] == p ? T : dp[G[x][i]]) + 1;
        if(i != (int)G[x].size() - 1) R[i] = R[i + 1] * v % mod;
        else {
            R[i] = v;
        }
    }
    for(int i = 0; i < (int)G[x].size(); i++) {
        int y = G[x][i];
        if(y == p) continue;
        int ll = i == 0 ? 1 : L[i - 1];
        int rr = i == (int)G[x].size() - 1 ? 1 : R[i + 1];
        DFS(y, x, ll * rr % mod);
    }

}

