#define ll long long int
#define white first
#define black second
#define pi pair<int, int>

int M;

pi dfs(vector<int> edges[], int sv, int parent){

    // If we paint the current node as white,
    // then all of its children must be white as well
    // If we paint the current node as black,
    // then the children can be either black or white

    pi ans;
    ll white = 1, black = 1;
    for(int child: edges[sv]){
        if(child == parent)
            continue;
        pi childAns = dfs(edges, child, sv);
        ll childBlack = childAns.black,
           childWhite = childAns.white;
        white = (white*childWhite)%M;
        black = (black*(childBlack + childWhite)%M)%M;
    }

    ans.black = black;
    ans.white = white;
    return ans;
}

void subtree(vector<int> edges[], int n){

    // O(n*n)
    // Consider each node as root node and find the number of ways to paint
    // it black
    vector<int> ans(n);
    for(int i=0; i<n; i++){
        ll black = dfs(edges, i, -1).black;
        ans[i] = black;
    }
    for(int num: ans)
        cout<<num<<endl;

}

