// x; 対象のノード
// p: 親ノード
int64_t Query(int x, int p) {
    int64_t retval = 1;
    int L = node[x].dp.size();
    for(int i = 0; i < L; i++) {
        if(node[x].edge[i] == p) continue;
        if(node[x].dp[i] < 0) node[x].dp[i] = Query(node[x].edge[i], x);
        retval *= (node[x].dp[i] + 1);
        retval %= M;
    }
    return retval;
}

