vector<int> adj[100001];
ll m;
int n;
vector<ll> dp1(100001),dp2(100001);
int vis[100001];
void solve1(int i)
{
  vis[i]=1;
  dp1[i]=1;
  for(int x: adj[i])
  {
    if(!vis[x])
    {
      solve1(x);
      dp1[i]=(dp1[i]*(1+dp1[x]))%m;
    }
  }
}
ll solve2(int i,ll parans)
{
  vis[i]=1;
  dp2[i]=(dp1[i]*(1+parans))%m;
  vector<ll> prefix,suffix;
  for(int ch: adj[i])
  {
    if(!vis[ch]){
    prefix.push_back(dp1[ch]+1);
    suffix.push_back(dp1[ch]+1);
    }
  }
  for(int j=1;j<prefix.size();j++)
  {
    prefix[j]=(prefix[j]*prefix[j-1])%m;
  }
  for(int j=suffix.size()-2;j>=0;j--)
  {
    suffix[j]=(suffix[j]*suffix[j+1])%m;
  }
  int cno=0;
  for(int ch: adj[i])
  {
    if(!vis[ch])
    {
      ll ways=(1+parans);
      ll x=(cno>0)?(prefix[cno-1]):1;
      ll y=(cno<suffix.size()-1)?(suffix[cno+1]):1;
      ways=(((ways*x)%m)*y)%m;
      solve2(ch,ways);
      cno++;
    }
  }
}
int main()
{
  cin>>n;
  cin>>m;
  for(int i=1;i<n;i++)
  {
    int x,y;
    cin>>x>>y;
    adj[x].push_back(y);
    adj[y].push_back(x);
  }
  memset(vis,0,sizeof(vis));
  solve1(1);
  memset(vis,0,sizeof(vis));
  solve2(1,0);
  for(int i=1;i<=n;i++)
  cout<<dp2[i]<<endl;
  return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef pair<ll, ll> P;

int N, M;
vector<int> adj[110000];
ll dp1[110000];
ll dp2[110000];

void dfs(int nd, int prv = -1) {
	ll res = 1;
	for (int child : adj[nd]) {
		if (child == prv) continue;
		dfs(child, nd);
		res *= dp1[child];
		res %= M;
	}
	dp1[nd] = (res + 1) % M;
}

void dfs2(int nd, int prv = -1) {
	if (prv == -1) dp2[nd] = 1;
	vector<ll> lprod = vector<ll>(adj[nd].size(), 1);
	vector<ll> rprod = vector<ll>(adj[nd].size(), 1);
	for (int i = 0; i < adj[nd].size(); i++) {
		int child = adj[nd][i];
		if (i - 1 >= 0) lprod[i] = lprod[i - 1];
		if (child == prv) continue;
		lprod[i] *= dp1[child]; lprod[i] %= M;
	}
	for (int i = (int)adj[nd].size() - 1; i >= 0; i--) {
		int child = adj[nd][i];
		if (i + 1 < adj[nd].size()) rprod[i] = rprod[i + 1];
		if (child == prv) continue;
		rprod[i] *= dp1[child]; rprod[i] %= M;
	}
	for (int i = 0; i < adj[nd].size(); i++) {
		int child = adj[nd][i];
		if (prv == child) continue;
		ll rest_prod = 1;
		if (i - 1 >= 0) rest_prod = rest_prod * lprod[i - 1] % M;
		if (i + 1 < adj[nd].size()) rest_prod = rest_prod * rprod[i + 1] % M;
		dp2[child] = (rest_prod * dp2[nd] + 1) % M;
		dfs2(child, nd);
	}
}

ll ans[110000];
void dfs3(int nd, int prv = -1) {
	ans[nd] = dp2[nd];
	for (int child : adj[nd]) {
		if (child == prv) continue;
		ans[nd] *= dp1[child];
		ans[nd] %= M;
		dfs3(child, nd);
	}
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);
	cin >> N >> M;
	for (int i = 0; i < N - 1; i++) {
		int a, b; cin >> a >> b;
		a--, b--;
		adj[a].push_back(b);
		adj[b].push_back(a);
	}
	dfs(0);
	dfs2(0);
	dfs3(0);

	for (int i = 0; i < N; i++) cout << ans[i] << '\n';
	return 0;
}

