int n, m;
std::vector<std::vector<int> > G;
int dp[100000];

int dfs(int p, int x){
  long long int r = 1;
  for(int y: G[x]){
    if(y == p) continue;
    r = r * (1 + dfs(x, y)) % m;
  }
  return dp[x] = r;
}

void dfs2(int p, int x){
  int ans = (long long int) dp[x] * (p == -1 ? 1 : (dp[p]+1)) % m;
  std::vector<int> prod(G[x].size()+1);
  prod[0] = 1;
  int i = 1;
  for(int y: G[x]){
    prod[i] = (long long) prod[i-1] * (dp[y] + 1) % m;
    i++;
  }
  std::vector<int> rprod(G[x].size()+1);
  rprod[G[x].size()] = 1;
  i = G[x].size()-1;
  for(auto j = G[x].crbegin(); j != G[x].crend(); ++j){
    rprod[i] = (long long) rprod[i+1] * (dp[*j] + 1) % m;
    i--;
  }
  i = 1;
  for(int y: G[x]){
    if(y != p){
      dp[x] = (long long) prod[i-1] * rprod[i] % m;
      dfs2(x, y);
    }
    i++;
  }
  dp[x] = ans;
}

