  G.resize(n);
  for(int i = 0; i < n - 1; i++){
    int a, b;
    scanf("%d%d", &a, &b);
    G[b-1].push_back(a-1);
    G[a-1].push_back(b-1);
  }

  dfs(-1, 0);
  dfs2(-1, 0);

  for(int i = 0; i < n; i++) printf("%d\n", dp[i]);

  return 0;
}

