using namespace std;
long long n,m,x,y,ans[111111],dp[111111],pre[222222],suf[222222],a[222222],cnt;
vector<long long> g[111111];
void dfs(long long i,long long fa)
{
	dp[i]=1;
	for (long long j=0;j<g[i].size();j++)
	{
		long long to=g[i][j];
		if (to==fa) continue;
		dfs(to,i);
		dp[i]=dp[i]*(dp[to]+1)%m;
	}
}
void dft(long long i,long long fa)
{
	long long pcnt=cnt,ncnt,fo,anp,ant,anr;
	ans[i]=dp[i];
	for (long long j=0;j<g[i].size();j++)
	{
		long long to=g[i][j];
		a[++cnt]=dp[to]+1;
	}
	ncnt=cnt;
	pre[pcnt+1]=a[pcnt+1];
	for (long long j=pcnt+2;j<=ncnt;j++) pre[j]=pre[j-1]*a[j]%m;
	suf[ncnt]=a[ncnt];
	for (long long j=ncnt-1;j>pcnt;j--) suf[j]=suf[j+1]*a[j]%m;
	fo=pcnt;
	for (long long j=0;j<g[i].size();j++)
	{
		long long to=g[i][j];
		fo++;
		if (to==fa) continue;
		if (fo>pcnt+1) anp=pre[fo-1];
		else anp=1;
		if (fo<ncnt) anp=anp*suf[fo+1]%m;
		ant=dp[to];anr=dp[i];
		dp[i]=anp;
		dp[to]=dp[to]*(dp[i]+1)%m;
		dft(to,i);
		dp[i]=anr;dp[to]=ant;
	}
}
