using namespace std;
#define AC 0
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	int n, m;
	cin >> n >> m;
	vector< vector<int> > t(n);
	vector<int> dp(n, 1), ans(n);
	for (int i = 0, x, y; i < n - 1; i++) {
		cin >> x >> y;
		t[x - 1].push_back(y - 1);
		t[y - 1].push_back(x - 1);
	}
	function<void(int, int)> dfs = [&](int u, int p) {
		for (int i = 0; i < t[u].size(); i++)
			if (t[u][i] != p) {
				dfs(t[u][i], u);
				dp[u] = 1ll * dp[u] * (dp[t[u][i]] + 1) % m;
			}
	};
	dfs(0, -1);
	function<void(int, int, int)> solve = [&](int u, int p, int up) {
		ans[u] = 1ll * dp[u] * up % m;
		vector<int> child;
		for (int i = 0; i < t[u].size(); i++)
			if (t[u][i] != p)
				child.push_back(t[u][i]);
		vector<int> pre(child.size() + 1, 1), suf(child.size() + 1, 1);
		for (int i = 0; i < child.size(); i++) pre[i + 1] = 1ll * pre[i] * (dp[child[i]] + 1) % m;
		for (int i = child.size() - 1; i >= 0; i--) suf[i] = 1ll * suf[i + 1] * (dp[child[i]] + 1) % m;
		for (int i = 0; i < child.size(); i++) solve(child[i], u, (1ll * up * pre[i] % m * suf[i + 1] + 1) % m);
	};
	solve(0, -1, 1);
	for (int i = 0; i < n; i++) cout << ans[i] << '\n';
	return AC;
}

