llint modpow(llint a, llint n)
{
	if(n == 0) return 1;
	if(n % 2){
		return ((a%mod) * (modpow(a, n-1)%mod)) % mod;
	}
	else{
		return modpow((a*a)%mod, n/2) % mod;
	}
}

int getid(int i, int u)
{
	if(edge[i][0] == u) return 0;
	else return 1;
}

void dfs(llint e, llint id)
{
	llint v = edge[e][id];
	for(int i = 0; i < G[v].size(); i++){
		if(G[v][i] == e) continue;
		dfs(G[v][i], 1-getid(G[v][i], v));

	}
	llint ret = 1;
	for(int i = 0; i < G[v].size(); i++){
		ret *= dp[G[v][i]][1-getid(G[v][i], v)]+1, ret %= mod;
	}
	dp[e][id] = ret;
}


void dfs2(llint e, llint id)
{
	llint v = edge[e][id];

	llint mul = 1;
	for(int i = 0; i < G[v].size(); i++){
		mul *= dp[G[v][i]][1-getid(G[v][i], v)]+1, mul %= mod;
	}
	for(int i = 0; i < G[v].size(); i++){
		if(G[v][i] == e) continue;
		llint tmp = mul * modpow(dp[G[v][i]][1-getid(G[v][i], v)]+1, mod-2) % mod;
		dp[G[v][i]][getid(G[v][i], v)] = tmp;
	}
	for(int i = 0; i < G[v].size(); i++){
		if(G[v][i] == e) continue;
		dfs2(G[v][i], 1-getid(G[v][i], v));
	}
}

