int N, M;

struct Graph{
    vector<vector<int>> es;
    vector<vector<ll>> l, r;
    vector<ll> dw, up;
    const int n;

    Graph(int n) : n(n){
        es.resize(n);
        l.resize(n), r.resize(n);
        dw.resize(n), up.resize(n);
    }

    void add_edge(int from, int to, bool directed = false){
        es[from].pb(to);
        if(!directed) es[to].pb(from);
    }

    ll dfs1(int now, int pre){
        l[now].resize(sz(es[now])+1), r[now].resize(sz(es[now])+1);
        l[now][0] = 1;
        rep(i, sz(es[now])){
            int e = es[now][i];
            if(e == pre) l[now][i+1] = l[now][i];
            else l[now][i+1] = l[now][i]*(dfs1(e, now)+1)%M;
        }
        r[now][sz(es[now])] = 1;
        rep3(i, sz(es[now])-1, 0){
            int e = es[now][i];
            if(e == pre) r[now][i] = r[now][i+1];
            else r[now][i] = r[now][i+1]*(dw[e]+1)%M;
        }
        return dw[now] = r[now][0];
    }

    void dfs2(int now, int pre){
        rep(i, sz(es[now])){
            int e = es[now][i];
            if(e == pre) continue;
            up[e] = l[now][i]*r[now][i+1]%M;
            up[e] *= up[now]+1, up[e] %= M;
            dfs2(e, now);
        }
    }

    void solve(int root = 0){
        up[root] = 0;
        dfs1(root, -1), dfs2(root, -1);
        rep(i, n){
            cout << dw[i]*(up[i]+1)%M << endl;
        }
    }
};

int main(){
    cin >> N >> M;
    Graph G(N);
    rep(i, N-1){
        int u, v; cin >> u >> v; u--, v--;
        G.add_edge(u, v);
    }
    G.solve();
}

