//MODULAR ARITHMATIC
int mmod = 1000000007;

int add(int a, int b, int m=mmod) {
	return (a%m + b%m)%m;
}

int sub(int a, int b, int m=mmod) {
    return (a%m - b%m + m)%m;
}

int mul(int a, int b, int m=mmod) {
	return ((a%m) * (b%m) % m);
}

int pwr(int a, int b, int m=mmod) {
    a %= m;
    int r = 1;
    while (b) {
		if (b&1) r = r*a%m;
		b >>= 1;
		a = a*a%m;
    }
    return r;
}

int inv(int a, int m=mmod) {
	return pwr(a, m-2, m);
}

#define all_white first
#define sth_is_black second

const int N = 100009;
vi adj[N], child[N];
ii down[N], up[N];
vii downs[N], pref[N], suf[N];

ii merge(const ii& a, const ii& b) {
	pair<int,int> p;
    p.all_white = mul(a.all_white, b.all_white);
    p.sth_is_black = add(
        mul(a.sth_is_black, add(b.all_white, b.sth_is_black)),
        mul(a.all_white, b.sth_is_black)
    );
    return p;
}

ii process(ii p) {
	return {p.all_white, add(p.sth_is_black, p.all_white)};
}

void dfs1(int v, int par) {
	ii p = {1, 0};
	for (int u: adj[v]) {
		if (u != par) {
			child[v].PB(u);
			dfs1(u, v);
			p = merge(p, down[u]);
			downs[v].PB(down[u]);
		}
	}
	down[v] = process(p);
}

void dfs2(int v, int par) {
	for (int i = 0; i < (int)child[v].size(); i++) {
		ii p{1, 0};
		if (i != 0) {
			p = merge(p, pref[v][i-1]);
		}
		if (i != (int) downs[v].size() - 1) {
			p = merge(p, suf[v][i+1]);
		}
		if (v != 1) {
			p = merge(p, up[v]);
		}
		int u = child[v][i];
		up[u] = process(p);
		dfs2(u, v);
	}
}

