	FAST_IO;

	int n, m;
	cin >> n >> m;
	mmod = m;
	for (int i = 0; i < n-1; i++) {
		int x, y;
		cin >> x >> y;

		adj[x].PB(y);
		adj[y].PB(x);
	}

	dfs1(1, -1);

	for (int v = 1; v <= n; v++) {
		int k = downs[v].size();
		assert(k == (int) child[v].size());
		ii p{1, 0};
		for (int i = 0; i < k; i++) {
			p = merge(p, downs[v][i]);
			pref[v].PB(p);
		}
		p = {1, 0};
		for (int i = k-1; i >= 0; i--) {
			p = merge(p, downs[v][i]);
			suf[v].PB(p);
		}
		reverse(ALL(suf[v]));
	}
	dfs2(1, -1);
	for (int v = 1; v <= n; v++) {
		ii p{1, 0};
		if (v != 1) {
			p = merge(p, up[v]);
		}
		if (!child[v].empty()) {
			p = merge(p, pref[v].back());
		}
		p = process(p);
		cout << p.sth_is_black << endl;
	}
}

