int dp1[100005];
int dp2[100005];

int dfs1(int v, int p) {
    int ret = 1;
    FORE(w, g[v]) {
        if (w == p) continue;
        ch[v].push_back(w);
        ret *= dfs1(w, v) + 1;
        ret %= M;
    }
    return dp1[v] = ret;
}

void dfs2(int v, int prop) {
    // dump(v, prop);
    int tmp = 1;
    vector<int> left(SZ(ch[v])), right(SZ(ch[v]));
    REP(i, SZ(ch[v])) {
        int w = ch[v][i];
        tmp = (tmp * (dp1[w] + 1)) % M;
        left[i] = (i > 0 ? left[i - 1] : 1) * (dp1[w] + 1) % M;
    }
    dp2[v] = tmp * (prop + 1) % M;
    REPR(i, SZ(ch[v]) - 1) {
        int w = ch[v][i];
        right[i] = (i + 1 < SZ(ch[v]) ? right[i + 1] : 1) * (dp1[w] + 1) % M;
    }

    REP(i, SZ(ch[v])) {
        int w = ch[v][i];
        int L = (i > 0 ? left[i - 1] : 1);
        int R = (i + 1 < SZ(ch[v]) ? right[i + 1] : 1);
        // dump(L, R, prop + 1, w);
        int prop_next = L * R % M * (prop + 1) % M;
        dfs2(w, prop_next);
    }
}

