int add(int a, int b) {

    a += b;
    if(a >= mod)
        a -= mod;
    return a;
}

int mul(int a, int b) {

    return ((ll)a * b) % mod;
}

int get(vector<int> bit, int x) {

    int ans = 1;
    for(int i = x; i > 0; i -= i & -i)
        ans = mul(ans, bit[i]);
    return ans;
}

void upd(vector<int> &bit, int x, int y) {

    for(int i = x; i <= bit.size(); i += i & -i)
        bit[i] = mul(bit[i], y);
}

void make_down(int u, int p) {

    down[u] = 1;
    for(int v: graph[u]) {
        if(v != p) {
            make_down(v, u);
            down[u] = mul(down[u], add(1, down[v]));
        }
    }
}

void make_up(int u, int p) {

    vector<int> bit1(graph[u].size(), 1);
    vector<int> bit2(graph[u].size(), 1);
    vector<int> arr(graph[u].size());
    int br = 1;
    for(int v: graph[u]) {
        if(v != p) {
            int ans = 1;
            for(int k: graph[u])
                if(k != p && k != v)
                    ans = mul(ans, add(1, down[k]));
            up[v] = add(1, mul(up[u], ans));
            make_up(v, u);
        }
    }
}

