ll inv(ll a, ll n = MOD - 2) {
    cerr << a << ' ';
    ll res = 1;
    for (; n; a = (a * a) % MOD, n >>= 1)
        if (n & 1)
            res = (res * a) % MOD;
    cerr << res << '\n';
    return res;
}

vector<vii> adj;
vll res0, res1;
ll dfs0(int curr = 0, int prev = -1) {
    ll ans = 1;
    for (int node : adj[curr]) {
        if (node == prev) continue;
        (ans *= 1 + dfs0(node, curr)) %= MOD;
    }
    res0[curr] = ans;
}

void dfs1(int curr = 0, int prev = -1) {
    if (prev != -1) {
        (res1[curr] *= res1[prev]) %= MOD;
        (++res1[curr]) %= MOD;
    }
    stack<ll> s;
    ll prod = 1;
    for (int i = adj[curr].size() - 1; i >= 0; i--) {
        if (adj[curr][i] == prev) continue;
        s.push(prod);
        (prod *= 1 + res0[adj[curr][i]]) %= MOD;
    }
    prod = 1;
    for (int node : adj[curr]) {
        if (node == prev) continue;
        res1[node] *= (prod * s.top()) % MOD;
        s.pop();
        (prod *= 1 + res0[node]) %= MOD;
        dfs1(node, curr);
    }
}

