#include<bits/stdc++.h>

using namespace std;
typedef long long ll;
typedef long double ld;

const int N = 1e5 + 5;
int n, mod;
vector<int> g[N], pre[N], suf[N];
int dp[N], sol[N];

int add(int a, int b)
{
	return (a + b) % mod;
}

int sub(int a, int b)
{
	return (a - b + mod) % mod;
}

int mul(int a, int b)
{
	return (1ll * a  * b) % mod;
}

void dfs(int node, int parent)
{
	pre[node].resize(g[node].size());
	suf[node].resize(g[node].size());
	int cur = 1;
	for(int i = 0; i < g[node].size(); i++)
	{
		int child = g[node][i];
		if(child != parent)
		{
			dfs(child, node);
			cur = mul(cur, dp[child]);
		}
		pre[node][i] = cur;
	}
	cur = 1;
	for(int i = (int)g[node].size() - 1; i >= 0; i--)
	{
		int child = g[node][i];
		if(child != parent)
			cur = mul(cur, dp[child]);
		suf[node][i] = cur;
	}
	dp[node] = add(1, cur);
}

//dp[node] = p * s + 1
//dp[child] = (dp[child] - 1) * dp[parent] + 1
void dfs2(int node, int parent)
{
	sol[node] = dp[node];
	for(int i = 0; i < g[node].size(); i++)
	{
		int child = g[node][i];
		if(child != parent)
		{
			//save data
			int dp1 = dp[node], dp2 = dp[child];

			//update dp[node]
			int p = i ? pre[node][i - 1] : 1, s = (i + 1 < g[node].size()) ? suf[node][i + 1] : 1;
			dp[node] = add(mul(dp[parent], mul(p, s)), 1);

			//update child
			dp[child] = add(mul(sub(dp[child], 1), dp[node]), 1);

			//dfs
			dfs2(child, node);

			//undo data
			dp[node] = dp1, dp[child] = dp2;
		}
	}
}


