using namespace std;
using Int = long long;
Int N, M;
vector<vector<int>> adj;
vector<unordered_map<int, Int>> sub;
vector<Int> prod;

Int dfs(int node, int parent) {
  if (parent >= 0) {
    auto it = sub[parent].find(node);
    if (it != sub[parent].end()) return it->second;
  }
  Int r = 1;
  for (int child : adj[node]) {
    if (child == parent) continue;
    r = r * (1 + dfs(child, node));
  }
  if (parent >= 0) {
    sub[parent][node] = r % M;
  } else {
    prod[node] = r;
  }
  return r % M;
};

void solve() {
  dfs(0, -1);
  auto dfs2 = [&](auto rec, int node, int parent) -> void {
    if (parent >= 0) {
      prod[node] = sub[parent][node] +
                   prod[parent] / (1 + sub[parent][node]) * sub[parent][node];
    }
    for (int child : adj[node]) {
      if (child == parent) continue;
      rec(rec, child, node);
    }
  };
  dfs2(dfs2, 0, -1);
  for (int i = 0; i < N; ++i) {
    cout << prod[i] % M << "\n";
  }
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  cin >> N >> M;
  adj.resize(N);
  sub.resize(N);
  prod.resize(N, 0);
  for (int i = 0; i < N - 1; i++) {
    int x, y;
    cin >> x >> y;
    x--;
    y--;
    adj[x].push_back(y);
    adj[y].push_back(x);
  }
  solve();
}

