    }
    comb_L[idx] = (comb_L[idx]+1)%M;
  }
  return comb_L[idx];
}
ull calc_comb_R(int idx)
{
  if(comb_R[idx]==INF)
  {
    comb_R[idx] = 1;
    int point = edge[idx].second;
    for(ull j=0;j<edge_idx[point].size();++j)
    {
      if(edge_idx[point][j]==idx)continue;
      if(edge[edge_idx[point][j]].first==point)
      {
        comb_R[idx] = (comb_R[idx]*calc_comb_R(edge_idx[point][j]))%M;
      }
      else
      {
        comb_R[idx] = (comb_R[idx]*calc_comb_L(edge_idx[point][j]))%M;
      }
      if(comb_R[idx]==0)
      {
        if(j)
        {
          int k_idx=edge_idx[point][j];
          for(ull k=j;k>0;--k)
          {
            edge_idx[point][k]=edge_idx[point][k-1];
          }
          edge_idx[point][0]=k_idx;
        }
        break;
      }
    }
    comb_R[idx] = (comb_R[idx]+1)%M;
  }
  return comb_R[idx];
}

int main()
{
  ull i,j,N;
  int x,y;
  cin >> N >> M;
  edge_idx.resize(N);
  comb_L.resize(N-1,INF);
  comb_R.resize(N-1,INF);
  for(i=0;i<N-1;++i)
  {
    cin >> x >> y;
    edge.push_back(make_pair(x-1,y-1));
    edge_idx[x-1].push_back(i);
    edge_idx[y-1].push_back(i);
  }

  for(i=0;i<N;++i)
  {
    ull c = 1;
    for(j=0;j<edge_idx[i].size();++j)
    {
      if(edge[edge_idx[i][j]].first==i)
      {
        c = (c*calc_comb_R(edge_idx[i][j]))%M;
      }
      else
      {
        c = (c*calc_comb_L(edge_idx[i][j]))%M;
      }
      if(c==0)break;
    }
    cout << c << endl;
  }

  return 0;
}

