void dfs1(int x, int p = -1) {
    d[x] = 1;
    for (int i = 0; i < adj[x].size(); i++) if (adj[x][i] != p) {
        dfs1(adj[x][i], x);
        d[x] *= d[adj[x][i]] + 1;
        d[x] %= m;
    }
}

void dfs2(int x, int p = -1) {
    int len = adj[x].size() + (x == 0);
    long long pfx[len], sfx[len];
    pfx[0] = sfx[len - 1] = 1;
    for (int i = 0, l = 0; i < adj[x].size(); i++) if (adj[x][i] != p) {
        pfx[l + 1] = pfx[l] * (d[adj[x][i]] + 1) % m;
        l++;
    }
    for (int i = adj[x].size() - 1, r = len - 1; i >= 0; i--) if (adj[x][i] != p) {
        sfx[r - 1] = sfx[r] * (d[adj[x][i]] + 1) % m;
        r--;
    }
    for (int i = 0, l = 0; i < adj[x].size(); i++) if (adj[x][i] != p) {
        u[adj[x][i]] = (u[x] * pfx[l] % m * sfx[l + 1] + 1) % m;
        dfs2(adj[x][i], x);
        l++;
    }
}

