typedef long long ll;

#define REP(i,n)   for(int i=0; i<(int)(n); i++)
#define FOR(i,b,e) for(int i=(b); i<=(int)(e); i++)
#define DUMP(a, n) REP(i, n) printf("%lld%c", a[i], i + 1 == n ? '\n' : ' ')
#define DUMP2D(a, n, m) REP(i, n) REP(j, m) printf("%d%c", a[i][j], j + 1 == m ? '\n' : ' '); puts("")

const int N_MAX = 1e5;
const int M_MAX = 1e9;

int N, M;
int x[N_MAX];
int y[N_MAX];

//------------------------------------------------------------------------------
struct edge {
  int from;
  int to;
  int i;
};

const int V_MAX = N_MAX;
const int E_MAX = (V_MAX - 1) * 2;

int V, E;
vector<edge> G[V_MAX];
edge es[E_MAX];

void add_edge(int i) {
  int from = x[i] - 1;
  int to = y[i] - 1;
  edge e1 = { from, to, i };
  edge e2 = { to, from, V - 1 + i };
  es[e1.i] = e1;
  es[e2.i] = e2;
  G[from].push_back(e1);
  G[to].push_back(e2);
}

//------------------------------------------------------------------------------
ll dp[E_MAX];

void dfs(int id) {
  if (dp[id] >= 0) return;
  dp[id] = 1;
  int p = es[id].from;
  int v = es[id].to;
  REP(i, G[v].size()) {
    edge e = G[v][i];
    int u = e.to;
    if (u == p) continue;
    dfs(e.i);
    dp[id] = dp[id] * (dp[e.i] + 1) % M;
  }
}

ll count_by_v(int v) {
  ll ret = 1;
  REP(i, G[v].size()) {
    edge e = G[v][i];
    ret = ret * (dp[e.i] + 1) % M;
  }
  return ret;
}

void solve() {
  V = N;
  E = (N - 1) * 2;
  REP(i, N - 1) add_edge(i);
  fill(dp, dp + E, -1);
  REP(i, E) dfs(i);
  // DUMP(dp, E);
  REP(v, V) {
    ll ans = count_by_v(v);
    printf("%lld\n", ans);
  }
}

void input() {
  scanf("%d%d", &N, &M);
  REP(i, N - 1) scanf("%d%d", x + i, y + i);
}

int main() {
  input();
  solve();
  return 0;
}

