            children[u].pb(v);
            par[v] = u;
            cost[v] = el.second;
            _dfs_tree(v, u);
        }
        pos[u] = _counter;
        psize[u] = pos[u] - ord[u];
    }

    void _dfs_et(int u){
        et_fpos[u] = euler_tour.size();
        euler_tour.pb(u);
        each(v, children[u]){
            _dfs_et(v);
            euler_tour.pb(u);
        }
    }

    int lca(int u, int v){
        if (u==v) return u;
        if (et_fpos[u]>et_fpos[v]) swap(u, v);
        return dfstrv[_seg.query(et_fpos[u], et_fpos[v])];
    }

    int dist(int u, int v){
        int p = lca(u, v);
        return depth[u] + depth[v] - 2*depth[p];
    }
    int ldist(int u, int v){  // length dist
        int p = lca(u, v);
        return ldepth[u] + ldepth[v] - 2*ldepth[p];
    }
    pair<int, int> diameter(){
        int u, v;
        int max_len = *max_element(all(ldepth));
        rep(i, n){
            if(ldepth[i]==max_len){
                u = i; break;
            }
        }
        int md = -1;
        rep(i, n){
            int d = ldist(u, i);
            if (d>md){ v = i; md = d; }
        }
        return mp(u, v);
    }

    bool is_leaf(int u){
        return (sz(children[u])==0);
    }

