        r[v][e[v].size()-1-i] = r[v][e[v].size()-1-i] * dp[e[v][i]] % m;
    }
}

void dfr(int v, ll pre) {
    dp[v] = (dp[v] - 1 + m) % m;
    dp[v] = dp[v] * pre % m;

    rep(i,e[v].size()) {
        if (e[v][i] == par[v]) continue;
