int add(int a , int b){
	a += b;
	if(a >= m){
		a -= m;
	}
	return a;
}

int mult(int a , int b){
	a = (long long) a * b % m;
	return a;
}

int getans(int curr , int tag){
	if(curr == dp2[tag].size()){
		return 1;
	}
	if(dp2[tag][curr] != -1){
		return dp2[tag][curr];
	}
	int ret = add(getans(curr+1,tag),mult(vals2[tag][curr],getans(curr+1,tag)));
	return dp2[tag][curr] = ret;
}

int getans2(int curr , int tag){
	if(curr == -1){
		return 1;
	}
	if(dp3[tag][curr] != -1){
		return dp3[tag][curr];
	}
	int ret = add(getans2(curr-1,tag),mult(vals2[tag][curr],getans2(curr-1,tag)));
	return dp3[tag][curr] = ret;
}

