	vector<int> vals;
	for(int i : graph[curr]){
		if(i != par){
			dfs(i,curr);
			vals.push_back(dp[i]);
		}
	}
	vals2[curr] = vals;
	dp2[curr].assign(vals.size(),-1);
	dp3[curr].assign(vals.size(),-1);
	dp[curr] = getans(0,curr);
