ll dfs(int v, int prev) {
	if (memo[v]) {
		if (dame[v] == prev) return S1[v][E[v].size()];
		ll ret = 1;
		if (prev) {
			int k = lower_bound(E[v].begin(), E[v].end(), prev) - E[v].begin();
