void dfs1(int v, int u = -1){
  dp[v] = 1;
  vfor(c,dist[v]){
    if(c == u)continue;
    dfs1(c,v);
    dp[v] *= (dp[c]+1);
    dp[v] %= mod;
  }
}
vi ans;
void dfs2(int v, int u = -1){
  ans[v] = 1;
  vfor(c, dist[v]){
    ans[v] *= (dp[c] + 1);
    ans %= mod;
  }
  int n = sz(dist[v]);
  vi pht(n), qht(n);
  rep(i,0,n-1)pht[i] = qht[i] = (dp[dist[v][i]] + 1 ) % mod;
  rep(i,1,n-1){
    pht[i] *= pht[i-1]
    pht[i] %= mod;
  }
  repdown(i,n-2,0){
     qht[i] *= qht[i+1];
     qht[i] %= mod;
  }
  rep(i,0,n-1){
    if(dist[v][i] == u)continue;
    dp[v] = 1;
    if(i)
    {
      dp[v] *= pht[i-1];
      dp[v] %= mod;
    }
    if(i+1 < n){
      dp[v] *= qht[i+1];
      dp[v] %= mod;
    }
    dfs2(dist[v][i], v);
  }
}

