    dp1[x] %= m;
  }
  dp1[x]++;
}

ll dp2[MAXN];
void dfs2(int x, int p=-1){
  if(p==-1)dp2[x]=1;
  int ec=edges[x].size();

  vector<ll> lprod;
  rep(i, ec){
    int c = edges[x][i];

    if(i)lprod.push_back(lprod.back());
    else lprod.push_back(1);

    if(c==p)continue;
    if(i)lprod.back() *= dp1[c];
    lprod.back() %= m;
  }

  vector<ll> rprod;
  rrep(i, ec){
    int c = edges[x][i];
    if(i<ec-1)rprod.push_back(rprod.back());
    else rprod.push_back(1);

    if(c==p)continue;
    if(i)rprod.back() *= dp1[c];
    rprod.back() %= m;
  }
  reverse(rprod.begin(), rprod.end());

  rep(i, ec){
    int c = edges[x][i];
    if(c==p)continue;
    dp2[c] = dp2[x];
    if(i)dp2[c] *= lprod[i-1];
    if(i<ec-1)dp2[c] *= rprod[i+1];
    dp2[c]++;
    dp2[c]%=m;
    dfs2(c, x);
  }
}

ll ans[MAXN];
void dfs3(int now, int p=-1){
  ans[now] = dp2[now];
  for(auto c:edges[now]){
    if(c==p)continue;
    ans[now] *= dp1[c];
    dfs3(c, now);
  }
}

