int dfs(int i, int p){
    if(SZ(g[i]) == 1 && i != 0)return a[i] = 2;
    a[i] = 1;
    for(auto x : g[i]){
        if(x == p)continue;
        a[i] = (a[i]*dfs(x,i))%mod;
    }
    a[i]++;
    return a[i];
}


void solve(int i, int p, int cur){
    STree st(n);
    st.upd(p,cur);
    for(auto x : g[i])if(x != p){
        st.upd(x,a[x]);
    }
    res[i] = st.query(0,n);
    for(auto x : g[i])if(x != p){
        st.upd(x,1);
        solve(x,i,(st.query(0,n)+1)%mod);
        st.upd(x,a[x]);
    }
}


