struct mint {
	using T = long long;
	static int MOD;
	T n;
public:
	static void set_mod(int _MOD) { MOD = _MOD; }
	mint(T x = 0)noexcept :n(x% MOD) { if (n < 0)n += MOD; }
	mint operator+()const noexcept { return *this; }
	mint operator-()const noexcept { return n ? MOD - n : 0; }
	mint& operator++()noexcept { if (MOD <= ++n)n = 0; return *this; }
	mint& operator--()noexcept { if (n <= 0)n = MOD; n--; return *this; }
	mint operator++(int)noexcept { mint t = *this; ++* this; return t; }
	mint operator--(int)noexcept { mint t = *this; --* this; return t; }
	mint next()const noexcept { return ++mint(*this); }
	mint pred()const noexcept { return --mint(*this); }
	mint operator+(const mint& m)const noexcept { return mint(*this) += m; }
	mint operator-(const mint& m)const noexcept { return mint(*this) -= m; }
	mint operator*(const mint& m)const noexcept { return mint(*this) *= m; }
	mint operator/(const mint& m)const noexcept { return mint(*this) /= m; }
	mint& operator+=(const mint& m)noexcept { n += m.n; if (n >= MOD)n -= MOD; return *this; }
	mint& operator-=(const mint& m)noexcept { n -= m.n; if (n < 0)n += MOD; return *this; }
	mint& operator*=(const mint& m)noexcept { n = n * m.n % MOD; return *this; }
	mint& operator/=(const mint& m)noexcept {
		assert(m.n);
		T a = m.n, b = MOD, u = 1, v = 0;
		while (b) {
			T t = a / b;
			a -= t * b; swap(a, b);
			u -= t * v; swap(u, v);
		}
		n = n * u % MOD;
		if (n < 0)n += MOD;
		return *this;
	}
	bool operator==(const mint& m)const noexcept { return n == m.n; }
	bool operator!=(const mint& m)const noexcept { return n != m.n; }
	mint pow(mint m)const noexcept {
		mint t = n, res = 1; while (m.n > 0) { if (m.n & 1)res *= t; t *= t; m.n >>= 1; } return res;
	}
	mint operator^(mint m)const noexcept { return pow(m); }
};
