struct DP {
	mint dp; bool flag;
	DP(mint _dp = 1, bool _flag = false) :dp(_dp), flag(_flag) {}
	DP operator+(const DP& d)const {
		return DP(*this) += d;
	}
	DP& operator+=(const DP& d) {
		dp *= d.dp + d.flag;
		return *this;
	}
	DP add_root()const {
		DP res = *this;
		res.flag = true;
		return res;
	}
};
ostream& operator<<(ostream& os, const DP& d) {
	return os << '(' << d.dp << ')';
}

