  static const int MAX = 100010;
  int N, M;
  vector<vector<int>> G;
  vector<vector<ll>> dp, dpl, dpr;

  void init() {
    cin >> N >> M;
    G.resize(N);
    dp.resize(N);
    dpl.resize(N);
    dpr.resize(N);
    int x, y;
    rep(i, N-1) {
      cin >> x >> y;
      x--;
      y--;
      G[x].push_back(y);
      G[y].push_back(x);
    }
  }

  ll dfs(int s, int p) {
    ll res = 1;
    dp[s].resize(G[s].size());
    rep(i, G[s].size()) {
      int t = G[s][i];
      if(t != p) {
        dp[s][i] = dfs(t, s);
      }
      res *= (dp[s][i] + 1);
      res %= M;
    }
    return res;
  }

  void dfs2(int s, int p, ll s2p) {
    int sz = G[s].size();
    dpl[s].resize(sz+1);
    dpr[s].resize(sz+1);
    dpl[s][0] = 1;
    dpr[s][sz] = 1;
    rep(i, sz) if(G[s][i] == p) dp[s][i] = s2p % M;
    rep(i, sz) {
      dpl[s][i+1] = dpl[s][i] * (dp[s][i] + 1) % M;
      dpr[s][sz-i-1] = dpr[s][sz-i] * (dp[s][sz-i-1] + 1) % M;
    }
    rep(i, sz) {
      int t = G[s][i];
      if(t != p) {
        dfs2(t, s, dpl[s][i] * dpr[s][i+1] % M);
      }
    }
  }

  void solve() {
    dfs(0, -1);
    dfs2(0, -1, 0);
    rep(i, N) cout << dpl[i][G[i].size()] << endl;
  }
