int M;

void dfs(int u, int par) {
    dp[u] = 1 % M;
    for(auto&v: g[u]) {
        if(v == par) continue;
        dfs(v, u);
        pref[v] = dp[u];
        dp[u] = (dp[u] * (1ll + dp[v])) % M;
    }
    int temp = (1 % M);
    for(int i=g[u].size()-1; i>=0; --i) {
        if(g[u][i] == par) continue;
        suff[g[u][i]] = temp;
        temp = (temp * (1ll + dp[g[u][i]])) % M;
    }
    assert(dp[u] == temp);
}

void dfs2(int u, int par, int mul) {
    ans[u] = (dp[u] * 1ll * mul) % M;
    for(auto&v: g[u]) {
        if(v == par) continue;
        //root u->v
        int olddpu = dp[u];

        dp[u] = (((pref[v] * 1ll * suff[v]) % M) * mul) % M;

        dfs2(v, u, (1ll + dp[u])%M);
        //root v->u
        dp[u] = olddpu;
    }
}

