vector<int> edge[101000];
ll stateNum1[101000];
ll stateNum2[101000];

ll dfs1(int s, int prev){
    ll res = 1;  // 自分が黒に塗られた場合
    for(auto v: edge[s]){
        if(v == prev){
            continue;
        }
        res = mul(res, dfs1(v, s));
    }
    res = add(res, 1);   // 自分が塗られない場合を足す。
    stateNum1[s] = res;
    return res;
}

void dfs2(int s, int prev, ll prevState){
    int n = edge[s].size();

    ll *hist1, *hist2;
    hist1 = new ll[n];   // i番目より前
    hist2 = new ll[n];   // i番目より後
    hist1[0] = 1;

    for(int i = 0; i < n-1; i++){
        int v = edge[s][i];
        ll tmp;
        if(v == prev) {
            tmp = mul(hist1[i], prevState);
        }
        else{
            tmp = mul(hist1[i], stateNum1[v]);
        }
        hist1[i+1] = tmp;
    }

    hist2[n-1] = 1;
    for(int i = n-2; i >= 0; i--){
        int v = edge[s][i+1];
        ll tmp;
        if(v == prev) {
            tmp = mul(hist2[i+1], prevState);
        }
        else{
            tmp = mul(hist2[i+1], stateNum1[v]);
        }
        hist2[i] = tmp;
    }
//    for(int i = 0; i < n; i++){
//        cout << s << " " << hist1[i] << " " << hist2[i] << endl;
//    }

    ll res = 1;
    for(auto v: edge[s]){
        if(v == prev){
            res = mul(res, prevState);
        }
        else{
            res = mul(res, stateNum1[v]);
        }
    }
    stateNum2[s] = res;
    for(int i = 0; i < n; i++){
        int v = edge[s][i];
        if(v == prev){
            continue;
        }
        ll newPrevState = add(mul(hist1[i], hist2[i]), 1);
        dfs2(v, s, newPrevState);
    }
    delete[] hist1;
    delete[] hist2;
}


