ull calc_comb_to(int point,int prev)
{
  ull pattern=1;
  for(ull i=0;i<edge_idx[point].size();++i)
  {
    if(edge[edge_idx[point][i]].first==point)
    {
      if(edge[edge_idx[point][i]].second!=prev)
      {
        comb_R[edge_idx[point][i]] = calc_comb_to(edge[edge_idx[point][i]].second,point);
        pattern = (pattern*comb_R[edge_idx[point][i]])%M;
      }
    }
    else
    {
      if(edge[edge_idx[point][i]].first!=prev)
      {
        comb_L[edge_idx[point][i]] = calc_comb_to(edge[edge_idx[point][i]].first,point);
        pattern = (pattern*comb_L[edge_idx[point][i]])%M;
      }
    }
  }
  return (pattern+1)%M;
}

void calc_comb(int point,int prev)
{
  ull pattern = 1;
  unordered_map<ull,ull> mp;
  for(ull i=0;i<edge_idx[point].size();++i)
  {
    if(edge[edge_idx[point][i]].first==point)
    {
      if(edge[edge_idx[point][i]].second!=prev)
      {
        auto itr = mp.find(comb_R[edge_idx[point][i]]);
        if(itr==mp.end())
        {
          mp[comb_R[edge_idx[point][i]]]=pattern;
          for(ull j=i+1;j<edge_idx[point].size();++j)
          {
            if(edge[edge_idx[point][j]].first==point)
            {
              mp[comb_R[edge_idx[point][i]]] = (mp[comb_R[edge_idx[point][i]]]*comb_R[edge_idx[point][j]])%M;
