          }
          mp[comb_R[edge_idx[point][i]]] = (mp[comb_R[edge_idx[point][i]]]+1)%M;
        }
        comb_L[edge_idx[point][i]] = mp[comb_R[edge_idx[point][i]]];
        comb[edge[edge_idx[point][i]].second] = (comb_L[edge_idx[point][i]]*(comb_R[edge_idx[point][i]]+M-1))%M;
        calc_comb(edge[edge_idx[point][i]].second,point);
      }
      pattern = (pattern*comb_R[edge_idx[point][i]])%M;
    }
    else
    {
      if(edge[edge_idx[point][i]].first!=prev)
      {
        auto itr = mp.find(comb_L[edge_idx[point][i]]);
        if(itr==mp.end())
