void add(int &x, int y) { x = (x + y) % mod; }
void Sup(int pre, int u)    {
    up[u] = 1;
    for(int v: vi[u]) if(v != pre)  {
        Sup(u, v);
        up[u] = 1ll * up[u] * (up[v] + 1) % mod;
    }
}
void Sdown(int pre, int u, int val)  {
    down[u] = (val + 1) % mod;
    int cnt = 0;    pref[0] = 1;
    for(int v: vi[u]) if(v != pre)
        cnt ++, pref[cnt] = 1ll * pref[cnt - 1] * (up[v] + 1) % mod;
    int tmp =  1ll;
    for(int i = vi[u].size() - 1; i >= 0; --i) {
        int v = vi[u][i];
        if(v != pre) {
            cnt --;
            child[u].pb(1ll * pref[cnt] * tmp % mod);
            tmp = 1ll * tmp * (up[v] + 1) % mod;
        }
    }
    reverse(child[u].begin(), child[u].end());
    cnt = -1;
    for(int v: vi[u]) if(v != pre)
        cnt ++, Sdown(u, v, 1ll * child[u][cnt] * down[u] % mod);
}
