inline int add (int a, int b) {
   a += b;
   if (a >= mod) a -= mod;
   return a;
}

inline int mult (int a, int b) {
   return 1ll * a * b % mod;
}

void dfs1 (int v = 1, int pr = 0) {
   dp1[v] = 1;
   p[v] = pr;
   for (int i = 0; i < sz (g[v]); i ++) {
      int to = g[v][i];
      if (to == pr) continue;
      dfs1 (to, v);
      dp1[v] = mult (dp1[v], add (dp1[to], 1));
   }
   for (int i = 0; i < sz (g[v]); i ++) {
      int to = g[v][i];
      if (to == pr) {
         pref[i] = (i ? pref[i - 1] : 1);
         continue;
      }
      pref[i] = mult ((i ? pref[i - 1] : 1), add (dp1[to], 1));
   }
   for (int i = sz (g[v]) - 1; i >= 0; i --) {
      int to = g[v][i];
      if (to == pr) {
         suff[i] = (i == sz (g[v]) - 1 ? 1 : suff[i + 1]);
         continue;
      }
      suff[i] = mult ((i == sz (g[v]) - 1 ? 1 : suff[i + 1]), add (dp1[to], 1));
   }
   for (int i = 0; i < sz (g[v]); i ++) {
      int to = g[v][i];
      if (to == pr) continue;
      int l = (i == 0 ? 1 : pref[i - 1]);
      int r = (i == sz (g[v]) - 1 ? 1 : suff[i + 1]);
      sum[to] = mult (l, r);
   }
}

int calc (int v) {
   if (dp2[v] != -1) return dp2[v];
   dp2[v] = 1;
   if (v == 1) return dp2[v];
   dp2[v] = sum[v];
   /*for (auto to : g[p[v]]) {
      if (to == v || to == p[p[v]]) continue;
      dp2[v] = mult (dp2[v], add (dp1[to], 1));
   } */
   dp2[v] = mult (dp2[v], calc (p[v]));
   dp2[v] = add (dp2[v], 1);
   return dp2[v];
}

