const int N = 1e5+10;

int M;
int add(int a, int b) {return (a+b)%M;}
int sub(int a, int b) {return (a+M-b)%M;}
int mult(ll a, ll b) {return (a*b)%M;}

int n, dp[N], ans[N], par[N];
// dp[s] - # ways to have subtrees black including s
// par[s] - # ways to have parent of s and anything not a child of s (including s itself) black
vector<int> g[N], pre[N], suf[N];

void preprocess(int s, int p = 0) {
	int id = -1;
	REP(i, g[s].size()) {
		if(g[s][i] == p) {
			id = i;
		}
	}
	if(id != -1) {
		g[s].erase(g[s].begin()+id);
	}

	int children = g[s].size();
	pre[s].resize(children);
	suf[s].resize(children);

	for(int v : g[s]) {
		preprocess(v, s);
	}
}

void dfs(int s, int p = 0) {
	dp[s] = 1;
	for(int v : g[s]) {
		dfs(v, s);
		dp[s] = mult(dp[s], add(dp[v], 1));
	}
	int children = g[s].size();
	if(children) {
		pre[s][0] = add(dp[g[s][0]], 1);
		FOR(i, 1, children-1) pre[s][i] = mult(pre[s][i-1], add(dp[g[s][i]], 1));

		suf[s][children-1] = add(dp[g[s][children-1]], 1);
		FORD(i, children-2, 0) suf[s][i] = mult(suf[s][i+1], add(dp[g[s][i]], 1));

		// DEBUG(s);
		// for(int x : pre[s]) cout << x << ' ';
		// cout << endl;
		// for(int x : suf[s]) cout << x << ' ';
		// cout << endl;
	}

}

void dfs2(int s, int p = 0) {
	if(p == 0) {
		ans[s] = dp[s];
		par[s] = 1;
	} else {
		ans[s] = mult(dp[s], add(par[s], 1));
	}
	int children = g[s].size();
	REP(i, children) {
		int v = g[s][i];
		int leftHalf = i ? pre[s][i-1] : 1;
		int rightHalf = i < children-1 ? suf[s][i+1] : 1;
		par[v] = mult(add(par[s], p ? 1 : 0), mult(leftHalf, rightHalf));
		dfs2(v, s);
	}
}

