const int N = 5*(int)1e5 + 10;
int mod;

int n, ways[N], ans[N];
vector<int> v[N];

void dfs(int s, int p){
   ways[s] = 1;

   if (p != -1){
      v[s].erase(find(v[s].begin(), v[s].end(), p));
   }

   for(auto i: v[s]){
      if(i != p){
         dfs(i, s);
         ways[s] *= (1 + ways[i]);
         ways[s] %= mod;
      }
   }
}

void dfs2(int s, int p, int up){

   vector<int> pref, suff;

   int vals = 1;
   for (int i = 0; i < (int)(v[s].size()); ++i)
   {
      int curr = v[s][i];
      vals *= ways[curr] + 1;
      vals %= mod;
      pref.push_back(vals);
   }

   vals = 1;
   for (int i = (int)(v[s].size())-1; i >= 0; --i)
   {
      int curr = v[s][i];
      vals *= ways[curr] + 1;
      vals %= mod;
      suff.push_back(vals);      
   }
   reverse(suff.begin(), suff.end());

   int backup = ways[s];
   for (int i = 0; i < (int)(v[s].size()); ++i)
   {
      int curr = v[s][i];
      int prefix = 1, suffix = 1;
      if (i-1 >= 0){
         prefix = pref[i-1];
      }
      if (i+1 < (int)(suff.size())){
         suffix = suff[i+1];
      }

      int purana = ways[curr];

      ways[s] = (prefix * suffix * up % mod);
      ways[s] %= mod; 

      ways[curr] *= 1 + ways[s];
      ways[curr] %= mod;
      ans[curr] = ways[curr];

      dfs2(curr, s, 1 + ways[s]);

      ways[s] = backup;
      ways[curr] = purana;
   }

}

