    rep(i, 0, N - 1) {
        cin >> u >> v;
        --u, --v;
        graph[u].push_back(v);
        graph[v].push_back(u);
    }
    vector<bool> visited(N, false);
    vector<ll> dp(N);
    dfs1(graph, visited, dp, 0);
    visited = vector<bool>(N, false);
    vector<ll> ans(N);
    dfs2(graph, visited, dp, ans, 0, -1);
    rep(i, 0, N) {
        cout << ans[i] << endl;
    }
    return 0;
}

