void dfs1(int x){
    for(auto e : E[x]) dfs1(e);
    down[x] = 1;
    for(auto e : E[x]) down[x] = down[x] * (1 + down[e]) % mod;
    for(auto& e : L[x]) e = 1;
    for(auto& e : R[x]) e = 1;
    if( sz(E[x]) > 0 ) L[x][0] = down[E[x][0]] + 1;
    if( sz(E[x]) > 0 ) R[x][sz(E[x])-1] = down[E[x][sz(E[x])-1]] + 1;
    for(int i=1;i<sz(E[x]);i++) L[x][i] = L[x][i-1] * (down[E[x][i]]+1) % mod;
    for(int i=sz(E[x])-2; i>=0; i--) R[x][i] = R[x][i+1] * (down[E[x][i]]+1) % mod;
}
void dfs2(int x){
    if( x == 1 ) up[x] = 0;
    else{
        int p = pa[x];
        up[x] = up[p] + 1;
        int idx = lower_bound(all(E[p]), x) - E[p].begin();
        if( idx-1 >= 0 ) up[x] = up[x] * L[p][idx-1] % mod;
        if( idx+1 < sz(E[p]) ) up[x] = up[x] * R[p][idx+1] % mod;
    }
    for(auto e : E[x]) dfs2(e);
}

