#include <bits/stdc++.h>

using namespace std;

long long n, m;
long long x, y;
long long i;

vector<vector<long long>> tree;

vector<long long> dp;
vector<bool> visited;
vector<long long> res;

long long modinv(long long a, long long b) { return 1 < a ? b - modinv(b % a, a) * b / a : 1; }

long long dfs(long long start) {
    if (!visited[start]) {
        visited[start] = true;
        if (tree[start].empty())
            dp[start] = 1;
        else {
            long long cnt = 1;
            for (long long child : tree[start])
                if (!visited[child])
                    cnt = (cnt * (dfs(child) + 1)) % m;

            dp[start] = cnt;
        }
    }

    return dp[start];
}

void solve(long long node, long long parent) {
    if (parent == -1)
        res[node] = dp[node];
    else {
        long long factor = __gcd(res[parent], dp[node] + 1);
        long long num = res[parent] / factor;
        long long den = (dp[node] + 1) / factor;

        res[node] = (((num * modinv(den, m) + 1) % m) * dp[node]) % m;
    }

    for (long long child : tree[node])
        if (child != parent)
            solve(child, node);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> m;

    tree.resize(n);
    for (i = 0; i < n - 1; ++i) {
        cin >> x >> y;
        tree[x - 1].push_back(y - 1);
        tree[y - 1].push_back(x - 1);
    }

    dp.resize(n);
    visited.resize(n);
    dfs(0);

    res.resize(n);
    solve(0, -1);

    for (i = 0; i < n; ++i)
        cout << res[i] << '\n';
}

