const int N = 200005;
int a[N], n, m, k;
vi g[N], pre[N], suf[N];
vpi v[N];

int dfs(int i, int p)
{
     for (auto x : g[i])
     {
          if (x != p)
          {
               v[i].pb({dfs(x, i) + 1, x});
          }
     }

     int s = 1;
     pre[i].pb(1);
     suf[i].pb(1);
     for (auto &x : v[i])
     {
          s *= x.F;
          s %= m;
          pre[i].pb(s);
     }
     s = 1;
     for (int j = sz(v[i]) - 1; j >= 0; j--)
     {
          s *= v[i][j].F;
          s %= m;
          suf[i].pb(s);
     }
     reverse(all(suf[i]));
     return s;
}

void dfs1(int i, int val)
{
     val %= m;
     if (!sz(v[i]))
     {
          a[i] = val + 1;
          return ;
     }
     int ans = (val + 1) * (pre[i].back());

     a[i] = ans % m;

     int l = sz(v[i]);
     for (int j = 0; j < l; j++)
     {
          int prod = (pre[i][j] * suf[i][j + 1]) % m;
          dfs1(v[i][j].S, (val + 1)*prod);
     }

}

