void dfs2(int u, int p = -1) {
    ans[u] = 1;
    for (auto v: adj[u])
        ans[u] = ans[u] * (dp[u][v] + 1) % M;

    int n = adj[u].size();
    VLL left(n), right(n);
    forn(i, 0, n) left[i] = right[i] = dp[u][adj[u][i]] + 1;
    forn(i, 1, n) left[i] = left[i] * left[i-1] % M;
    for (int i = n - 2; i >= 0; i--)
        right[i] = right[i] * right[i + 1] % M;

    forn(i, 0, n) {
        int v = adj[u][i];
        if (v != p) {
            dp[v][u] = 1;
