template <typename T>
void rooting(Tree<T> &tree, int cur, int par = -1){
  if(par != -1){
    for(auto it = tree[cur].begin(); it != tree[cur].end(); ++it){
      if(it->to == par){
        tree[cur].erase(it);
        break;
      }
    }
  }

  for(auto &e : tree[cur]){
    rooting(tree, e.to, cur);
  }
}




template <typename T, typename U, typename Merge, typename F, typename G>
struct Rerooting{
  int N;
  Tree<T> tree;
  U id;
  Merge merge;
  F f;
  G g;

  std::vector<int> p;

  std::vector<std::vector<U>> dp;
  std::vector<U> result;

  Rerooting(Tree<T> tree, U id, Merge merge, F f, G g):
    N(tree.size()), tree(tree), id(id), merge(merge), f(f), g(g), p(N, -1), dp(N), result(N, id)
  {
    rooting(0);
    rec1(0);
    rec2(0, -1, id);
    for(int i = 0; i < N; ++i){
      for(int j = 0; j < (int)tree[i].size(); ++j){
        result[i] = merge(result[i], f(dp[i][j], tree[i][j]));
      }

      result[i] = g(result[i], i);
    }
  }

  void rooting(int cur, int par = -1){
    p[cur] = par;

    dp[cur].assign((int)tree[cur].size(), id);

    for(auto &e : tree[cur]){
      if(e.to == par){
        std::swap(e, *tree[cur].rbegin());
        break;
      }
    }

    for(auto &e : tree[cur]){
      if(e.to == par) continue;
      rooting(e.to, cur);
    }
  }

  U rec1(int cur, int par = -1){
    U acc = id;

    for(int i = 0; i < (int)tree[cur].size(); ++i){
      auto &e = tree[cur][i];
      if(e.to == par) continue;
      dp[cur][i] = rec1(e.to, cur);
      acc = merge(acc, f(dp[cur][i], e));
    }

    return g(acc, cur);
  }

  void rec2(int cur, int par, U value){
    int l = tree[cur].size();

    if(tree[cur].size() and tree[cur].back().to == par){
      dp[cur].back() = value;
      l -= 1;
    }

    std::vector<U> left(l+1, id), right(l+1, id);

    for(int i = 0; i < l-1; ++i){
      auto &e = tree[cur][i];
      left[i+1] = merge(left[i], f(dp[cur][i], e));
    }

    for(int i = l-1; i >= 1; --i){
      auto &e = tree[cur][i];
      right[i-1] = merge(right[i], f(dp[cur][i], e));
    }

    for(int i = 0; i < l; ++i){
      auto &e = tree[cur][i];

      auto v = merge(left[i], right[i]);
      if(par != -1) v = merge(v, f(value, tree[cur].back()));

      rec2(e.to, cur, g(v, cur));
    }
  }
};






















