  for(int i=n;i>=1;i--) right[i]=(right[i+1]*(child[now][i-1]+1)%M)%M;

  int p=0;
  for(int i=0;i<g[now].size();i++){
    if(g[now][i]==par){
      p=1;
      continue;
    }
    solve(g[now][i],now,((left[i-p]*right[i+2-p])%M*(pans+1)%M)%M);
  }
}

