{
    if(from!=-1 && graph[tmp].size()==1){
        dp[tmp] = 1;
        return;
    }

    dp[tmp] = 1;
    for(auto& to: graph[tmp]){
        if(to != from){
            dfs(graph, dp, to, tmp, M);
            dp[tmp] *= dp[to]+1;
            dp[tmp] %= M;
        }
