}

void dfs2(Graph& graph, vector<ll>& dp, vector<ll>& ans, int tmp, int from, ll p, ll M)
{
    ++p;
    ans[tmp] = dp[tmp] * p % M;
    vector<ll> s(graph[tmp].size()+1);
    s.back() = 1;
    for(int i=graph[tmp].size()-1; i>=0; i--){
        int v = graph[tmp][i];
        s[i] = (v==from) ? s[i+1] : s[i+1] * (dp[v]+1);
        s[i] %= M;
    }

    for(int i=0; i<graph[tmp].size(); i++){
        int v = graph[tmp][i];
        if(v == from) continue;
        dfs2(graph, dp, ans, v, tmp, p*s[i+1]%M, M);
        p *= dp[v]+1;
        p %= M;
    }
}

