const int BLOCK = 350;
LL block[BLOCK + 5];

void build(int a) {
	for(int i = 0;i <= 350;i++) block[i] = 1;
	for(int i = 0;i < vec[a].size();i++) {
		int nx = vec[a][i];
		block[i / BLOCK] = block[i / BLOCK] * (dp[nx] + 1)% MOD;
	}
}

LL query(int a,int idx) {
	LL res = 1;
	for(int i = 0;i <= 350;i++) {
		if(i == idx / BLOCK) {
			for(int j = i * BLOCK;j < min((int)vec[a].size(), (i + 1) * BLOCK);j++) {
				if(j == idx) continue;
				res = res * (dp[vec[a][j]] + 1) % MOD;
			}
		}
		else res = res * block[i] % MOD;
	}
	return res;
}

