inline void Link(int u, int v) {
	e[++tot].to = v; e[tot].nex = head[u]; head[u] = tot;
}
void dfs(int u, int fa) {
	f[u] = 1, ::fa[u] = fa;
	int tot = 0;
	for (int i = head[u]; i; i = e[i].nex) {
		int v = e[i].to;
		if (v == fa)continue;
		dfs(v, u), V[u].push_back(v), ++tot;
		L[u].push_back(0), R[u].push_back(0);
		f[u] = (f[u] * 1ll * (f[v] + 1)) % mo;
	}
	for (int i = 0; i < tot; ++i) {
		L[u][i] = (i == 0) ? 1 : L[u][i - 1];
		(L[u][i] *= 1ll * (f[V[u][i]] + 1)) %= mo;
	}
	for (int i = tot - 1; i >= 0; --i) {
		R[u][i] = (i == (tot - 1)) ? 1 : R[u][i + 1];
		(R[u][i] *= 1ll * (f[V[u][i]] + 1)) %= mo;
	}
}

