long long getans(int curr , int tag){
	if(curr == dp2[tag].size()){
		return 1;
	}
	if(dp2[tag][curr] != -1){
		return dp2[tag][curr];
	}
	long long ret = getans(curr+1,tag) + vals2[tag][curr]*getans(curr+1,tag);
	ret %= m;
	return dp2[tag][curr] = ret;
}

long long getans2(int curr , int tag){
	if(curr == -1){
		return 1;
	}
	if(dp3[tag][curr] != -1){
		return dp3[tag][curr];
	}
	long long ret = getans2(curr-1,tag) + vals2[tag][curr]*getans2(curr-1,tag);
	ret %= m;
	return dp3[tag][curr] = ret;
}

