vector<vector<int>> pref;
vector<vector<int>> suf;
void dfs(int u, int parent){
	for(int v:a[u]){
		if(v==parent)continue;
		tree[u].pb(v);
		dfs(v,u);
	}

}
void solve_down(int u){
	pref[u].assign(SZ(tree[u]),0);	
	suf[u].assign(SZ(tree[u]),0);
	down[u]=1;
	for(int v:tree[u]){
		solve_down(v);
		down[u]=mul(down[u],add(1,down[v]));
	}
	for(int i=0;i<tree[u].size();i++){
		int v=tree[u][i];
		pref[u][i]=add(1,down[v]);
		if(i!=0){
			pref[u][i]=mul(pref[u][i-1],pref[u][i]);
		}
	}
	for(int i=SZ(tree[u])-1;i>=0;i--){
		int v=tree[u][i];
		suf[u][i]=add(1,down[v]);
		if(i!=SZ(tree[u])-1){
			suf[u][i]=mul(suf[u][i+1],suf[u][i]);
		}
	}
}
void solve_up(int u){
	int sz = tree[u].size();
	if(u==0)up[u]=1;
	for(int i=0;i<sz;i++){
		int v=tree[u][i];
		up[v]=up[u];
		if(i-1>=0)up[v]=mul(up[v],pref[u][i-1]);
		if(i+1<sz)up[v]=mul(up[v],suf[u][i+1]);
		up[v]=add(up[v],1);
		solve_up(v);
	}
}
