#define ll long long 

vector<int> tree[100001];

ll dp1[100001];
ll dp2[100001];


void solve2(int src,vector<bool> vis, ll m,ll ans){

    vis[src]=true;
    dp2[src]=(dp1[src]*((1+ans)%m))%m;

    vector<ll> suffix;
    vector<ll> prefix;

    for(auto child : tree[src]){

        if(!vis[child]){
        suffix.push_back(1+dp1[child]);
        prefix.push_back(1+dp1[child]);
        }

    }

    for(int i=1;i<prefix.size();i++){
        prefix[i]=(prefix[i]*prefix[i-1])%m;
    }

    for(int i=suffix.size()-2;i>=0;i--){

        suffix[i]=(suffix[i]*suffix[i+1])%m;

    }


    int cno=0;

    for(auto child : tree[src]){

        ll ways=(1+ans)%m;
        if(!vis[child]){
        ways=(cno==0)?ways:ways*prefix[cno-1];
        ways=ways%m;
        ways=(cno==suffix.size()-1)?ways:ways*suffix[cno+1];
        ways=ways%m;

        solve2(child,vis,m,ways);

        }

    }




}


void solve1(int src ,vector<bool> vis, ll m){

    vis[src]=true;
    dp1[src]=1;

    for(auto child: tree[src]){
        if(!vis[child]){
            solve1(child,vis,m);
            dp1[src]=(dp1[src]*(1+dp1[child]))%m;

        }
    }

}

