class VSubtree {
public:
    void solve() {
        int N = in.readInt(), M = in.readInt();
        mod = M;
        arri u, v;
        in.readArrays(N - 1, u, v);
        decreaseByOne(u, v);
        Graph<BiEdge> graph(N);
        for (int i : range(N - 1)) {
            graph.addEdge(u[i], v[i]);
        }
        arr<modint> dp(N, modint(0)), ans(N, modint(0));
        RecursiveFunction dfs_one = [&](auto const& self, int u, int par) -> void {
            dp[u] = modint(1);
            for (auto& e : graph[u]) {
                int v = e.to;
                if (v == par)
                    continue;
                self(v, u);
                dp[u] *= dp[v];
            }
            dp[u] += 1;
        };
        RecursiveFunction dfs_two = [&](auto const& self, int u, int par, modint ways) -> void {
            vector<modint> pref, suf;
            pref.emplace_back(modint(1));
            for (auto& e : graph[u]) {
                int v = e.to;
                if (v == par)
                    continue;
                pref.emplace_back(dp[v]);
                suf.emplace_back(dp[v]);
            }
            suf.emplace_back(modint(1));
            for (int i : range(1, (int) pref.size())) {
                pref[i] = pref[i] * pref[i - 1];
            }
            for (int i : RevRange((int) suf.size() - 1, 0)) {
                suf[i] = suf[i] * suf[i + 1];
            }
            int i = 0;
            ans[u] = pref.back() * ways;
            for (auto e : graph[u]) {
                int v = e.to;
                if (v == par)
                    continue;
                modint new_ways = ways * pref[i] * suf[i + 1] + 1;
                self(v, u, new_ways);
                ++i;
            }
        };
        dfs_one(0, -1);
        dfs_two(0, -1, modint(1));
        for (int i : range(N))
            out.printLine(ans[i]);
    }
};


