long long subtreeCount[100100];
long long revtreeCount[100100];
vector<long long> prodL[100100], prodR[100100];
vector<int> adj[100100];
int n, m, parent[100100];

void calcSTC(int v, int p) {
    long long ans = 1;
    parent[v] = p;
    for (int u : adj[v])
        if (u != p) { calcSTC(u, v); ans = ans * (1 + subtreeCount[u]) % m; }
    subtreeCount[v] = ans;
}

void calcRTC(int v, int p) {
    long long ans = 1;
    if (p != -1) {
        auto it = find(adj[p].begin(), adj[p].end(), v);
        assert (it != adj[p].end());
        int j = it - adj[p].begin();
        ans = ans * prodL[p][j] % m * prodR[p][j] % m;
        ans = ans * revtreeCount[p] % m;
        ans++;
    }
    revtreeCount[v] = ans;
    for (int u : adj[v]) if (u != p) calcRTC(u, v);
}

int main() {
    cin >> n >> m;
    for (int i = 1; i < n; i++) {
        int x, y; cin >> x >> y;
        x--; y--;
        adj[x].push_back(y);
        adj[y].push_back(x);
    }

    calcSTC(0, -1);
    for (int i = 0; i < n; i++) {
        int sz = adj[i].size();
        prodL[i].resize(sz); prodR[i].resize(sz);
        long long acc = 1;
        for (int j = 0; j < sz; j++) {
            prodL[i][j] = acc;
            if (adj[i][j] != parent[i])
                acc = acc * (1 + subtreeCount[adj[i][j]]) % m;
        }
        acc = 1;
        for (int j = sz-1; j >= 0; j--) {
            prodR[i][j] = acc;
            if (adj[i][j] != parent[i])
                acc = acc * (1 + subtreeCount[adj[i][j]]) % m;
        }
        // for (int j = 0; j < sz; j++) cerr << i << ' ' << j << ' ' << prodL[i][j] << ' ' << prodR[i][j] << endl;
    }

    calcRTC(0, -1);
    // for (int i = 0; i < n; i++) cerr << i << " " << revtreeCount[i] << endl;
    for (int i = 0; i < n; i++) {
        cout << subtreeCount[i] * revtreeCount[i] % m << endl;
    }
}

