    for (int w : g[v]) if (w != p) {
      dfs(dfs, w, v);
      (dp[v] *= dp[w]) %= m;
      chi[v].push_back(w);
    }
    dp[v] = (dp[v] + 1) % m;
  };
  dfs(dfs, 0, -1);
  for (int v = 0; v < n; ++v) {
    sort(begin(chi[v]), end(chi[v]));
  }
  V< unique_ptr<ST> > st(n);
  for (int v = 0; v < n; ++v) {
    st[v] = make_unique<ST>(chi[v].size());
    for (int i = 0; i < st[v]->n; ++i) {
      (*st[v])[i] = dp[chi[v][i]];
    }
    st[v]->build();
  }
  V<lint> dp1(n, 1), dp2(n, 1);
  auto dfs1 = [&](const auto& dfs1, int v, int p) -> void {
    for (int w : chi[v]) {
      (dp1[v] *= dp[w]) %= m;
    }
    if (p != -1) {
      // for (int u : chi[p]) if (u != v) {
      //   (dp2[v] *= dp[u]) %= m;
      // }
      int i = distance(begin(chi[p]), lower_bound(begin(chi[p]), end(chi[p]), v));
      (dp2[v] *= st[p]->get(0, i)) %= m;
      (dp2[v] *= st[p]->get(i + 1, st[p]->n)) %= m;
      (dp2[v] *= dp2[p]) %= m;
      (dp2[v] += 1) %= m;
    }
    (dp1[v] *= dp2[v]) %= m;
    for (int w : chi[v]) {
      dfs1(dfs1, w, v);
    }
  };
  dfs1(dfs1, 0, -1);
  for (int v = 0; v < n; ++v) {
    cout << dp1[v] << '\n';
  }
}

