void dfs0(int u, int f) {
    fa[u] = f;
    for (auto v: G[u]) {
        if (v != f) {
            son[u].push_back(v);
            dfs0(v, u);
        }
    }
}
vector <long long> pre[N], suf[N];
long long down[N], up[N];
void dfs1(int u) {
    int sz = son[u].size();
    pre[u].resize(sz);
    suf[u].resize(sz);
    down[u] = 1;
    for (auto v: son[u]) {
        dfs1(v);
        down[u] = (1 + down[v]) * down[u] % p;
    }
    for (int i = 0; i < sz; i++) {
        pre[u][i] = 1 + down[son[u][i]];
        if (i != 0) pre[u][i] = pre[u][i] * (pre[u][i - 1]) % p;
    }
    for (int i = sz - 1; i >= 0; i--) {
        suf[u][i] = 1 + down[son[u][i]];
        if (i != sz - 1) suf[u][i] = suf[u][i] * (suf[u][i + 1]) % p;
    }
}
void dfs2(int u) {
    if (u == 1) up[u] = 1;    // we are at the root
    int sz = son[u].size();
    for (int i = 0; i < sz; i++) {
        int v = son[u][i];
        up[v] = up[u];
        if (i != 0) up[v] = (up[v] * pre[u][i - 1]) % p;
        if (i != sz - 1) up[v] = (up[v] * suf[u][i + 1]) % p;
        up[v] = (up[v] + 1) % p;
        dfs2(v);
    }
}
