    y--;  // NOTE : modified input
    xs.push_back(x);
    ys.push_back(y);
  }

  // create tree
  vector<long> ps(N, -1), stack;
  vector<vector<long>> css(N, vector<long>()), adj_lists(N, vector<long>());
  for (long i = 0; i < N - 1; i++) {
    const long x = xs[i], y = ys[i];
    adj_lists[x].push_back(y);
    adj_lists[y].push_back(x);
  }
  stack.push_back(0);
  ps[0] = -1;
  while (!stack.empty()) {
    const long i = stack.back();
    stack.pop_back();
    for (long j : adj_lists[i]) {
      if (j != ps[i]) {
        ps[j] = i;
        css[i].push_back(j);
        stack.push_back(j);
      }
    }
  }
  //   for (long i = 0; i < N; i++) {
  //     printf("i = %ld, ps[i] = %ld, css[i] = { ", i, ps[i]);
