  vector<long> dp1s(N, -1), dp2s(N, -1), dp3s(N, -1), dp4s(N, -1);
  // calculate dp1s
  stack.push_back(0);
  while (!stack.empty()) {
    const long i = stack.back();
    long ok = 1, dp = 1;
    for (long j : css[i]) {
      if (dp1s[j] >= 0) {
        dp = (dp * (dp1s[j] + 1)) % M;
      } else {
        stack.push_back(j);
        ok = 0;
      }
    }
    if (ok) {
      dp1s[i] = dp;
      stack.pop_back();
    }
  }
//   for (long i = 0; i < N; i++) {
//     printf("i = %ld, dp1s[i] = %ld\n", i, dp1s[i]);
//   }
  // calculate dp2s
  for (long i = 0; i < N; i++) {
    if (ps[i] >= 0) {
      long dp = 1;
      for (long j : css[ps[i]]) {
        if (j != i) {
          dp = (dp * (dp1s[i] + 1)) % M;
        }
      }
      dp2s[i] = dp;
    } else {
      dp2s[i] = 1;
    }
  }
//   for (long i = 0; i < N; i++) {
//     printf("i = %ld, dp2s[i] = %ld\n", i, dp2s[i]);
