  // calculate dp3s
  stack.push_back(0);
  while (!stack.empty()) {
    const long i = stack.back();
    long dp;
    if (ps[i] >= 0) {
      dp = (dp2s[i] * dp3s[ps[i]] + 1) % M;
    } else {
      dp = 1;
    }
    dp3s[i] = dp;
    stack.pop_back();
    for (long j : css[i]) {
      stack.push_back(j);
    }
  }
