ll n, m;

vector<vector<int>> g;

vector<ll> dp;
vector<vector<ll>> ch_vs;
vector<vector<ll>> cumprod_left, cumprod_right;
vector<ll> ans;

void b2t(int i, int p = -1) {
    for (int j = 0; j < g[i].size(); j++) {
        if (g[i][j] == p) {
            swap(g[i][j], g[i].back());

            g[i].pop_back();

            break;
        }
    }

    int k = g[i].size();

    ch_vs[i].reserve(k);

    for (int to : g[i]) {
        b2t(to, i);

        ch_vs[i].push_back(dp[to] + 1);
    }

    dp[i] = 1;
    for (int j = 0; j < k; j++) {
        dp[i] = (dp[i] * ch_vs[i][j]) % m;
    }

    cumprod_left[i].resize(k + 1, 1);
    cumprod_right[i].resize(k + 1, 1);

    for (int j = 0; j < k; j++) {
        cumprod_left[i][j + 1] = (cumprod_left[i][j] * ch_vs[i][j]) % m;
        cumprod_right[i][k - j - 1] = (cumprod_right[i][k - j] * ch_vs[i][k - j - 1]) % m;
    }
}

void t2b(int i, ll x = 0) {
    ans[i] = dp[i] * (x + 1) % m;

    int k = g[i].size();
    for (int j = 0; j < k; j++) {
        t2b(g[i][j], (x + 1) * cumprod_left[i][j] % m * cumprod_right[i][j + 1] % m);
    }
}

