void dfs(int u, int par = 0)
{
    dp[u][0] = 1;
    for (int v : g[u]) if (v != par) {
        dfs(v, u);
        dp[u][0] = ((long) dp[u][0] * (1 + dp[v][0])) % MOD;
    }
}

void dfs_res(int u, int par = 0)
{
    vector<int> childs;
    for (int v : g[u]) if (v != par) childs.push_back(v);

    pre[0] = suf[childs.size()] = 1;
    for (int i = 0; i < (int) childs.size(); ++i) pre[i + 1] = ((long) pre[i] * (1 + dp[childs[i]][0])) % MOD;
    for (int i = childs.size() - 1; i >= 0; --i) suf[i] = ((long) suf[i + 1] * (1 + dp[childs[i]][0])) % MOD;
    for (int i = 0; i < (int) childs.size(); ++i)
        dp[childs[i]][1] = 1 + ((((long) pre[i] * suf[i + 1]) % MOD) * (long) dp[u][1]) % MOD;
    for (int v : childs) dfs_res(v, u);
}

