	return (a+b)%m;
}
llint mul(llint a,llint b) {
	return (a*b)%m;
}
llint get_p(llint x,llint y) {
	if(y==0) return 1LL;
	if(y==1) return x;
	if(p[make_pair(x,y)]) return p[make_pair(x,y)];
	llint r=get_p(x,y/2);
	if(y%2) return mul(mul(r,r),x);
	return mul(r,r);
}
llint divide(llint a,llint b) {
	//cout << a << " " << b << "\n";
	llint g1=__gcd(a,b);
	a/=g1;
	b/=g1;
	llint g=__gcd(b,m);
	llint a2=a/g,b2=b/g,m2=m/g;
	return mul(a2,get_p(b2,m2-2));
}
llint rek(int x,int a,int par) {
	if(dp[x][a]!=-1) return dp[x][a];
	llint ret=1;
	for(int i=0;i<v[x].size();i++) {
		if(v[x][i]==par) continue;
		llint ret2=0;
		ret2=sum(ret2,rek(v[x][i],0,x));
		if(a) ret2=sum(ret2,rek(v[x][i],1,x));
		if(a) c[v[x][i]]=ret2;
		ret=mul(ret,ret2);
	}
	//cout << x << " " << prev << " " << a << " " << ret << "\n";
	dp[x][a]=ret;
	return ret;
}
void dfs(int x,int par) {
	if(x==0) sol[x]=dp[0][1];
	else {
		sol[x]=mul(dp[x][1],divide(dp[par][1],dp[x][1]+max(0LL,dp[x][0]))+1);
		dp[x][1]=sol[x];
		//cout << dp[x][1] << " " << dp[par][1]/(dp[x][1]+max(0LL,dp[x][0]))+1 << "\n";
	}
	for(int i=0;i<v[x].size();i++) {
		if(v[x][i]==par) continue;
		dfs(v[x][i],x);
	}
}
