void dfs2(vvl &graph, ll pos, ll par = -1){
    ll n = graph[pos].size();
    if(n == 0){
        dp[pos] = sub[pos];
        return ;
    }
    vector<ll> cum(n+1), cum2(n+1), num(n);
    cum[0] = 1;
    cum2[n] = 1;
    num[n-1] = 1;
    ll ans = 1;

    rep(i, n){
        ll to = graph[pos][i];
        if(to == par){
            num[i] = dp[pos];
            continue;
        }
        num[i] = sub[to] + 1;
        ans = (ans * (sub[to] + 1)) % m;
    }
    rep(i,n)cum[i+1] = (cum[i] * num[i]) % m;
    rreps(i,n)cum2[i-1] = (cum2[i] * num[i-1]) % m;
    // debug(pos);print(num);print(cum);print(cum2);
    sub[pos] = ans;
