int dp1[100005];
int dp2[100005];
int m;
void solve1(vector<vector<int> >& tree, vector<bool>& visited, int curr_node) {
	visited[curr_node] = true;
	int ans = 1;
	for (auto child : tree[curr_node]) {
		if (!visited[child]) {
			solve1(tree, visited, child);
			ans *= (1 + dp1[child]);
			ans %= m;
		}
	}
	dp1[curr_node] = ans;
	dp1[curr_node] %= m;
}

void solve2(vector<vector<int> >& tree, vector<bool>& visited, int curr_node, int parent_answer) {

	visited[curr_node] = true;
	dp2[curr_node] = (1 + parent_answer) * dp1[curr_node];
	dp2[curr_node] %= m;

	vector<int> prefix, suffix;
	for (auto child : tree[curr_node]) {
		if (!visited[child]) {
			prefix.pb((1 + dp1[child]));
			suffix.pb((1 + dp1[child]));
		}
	}
	for (int i = 1; i < prefix.size(); i++) {
		prefix[i] *= prefix[i - 1];
		prefix[i] %= m;
	}
	for (int i = suffix.size() - 2; i >= 0; i--) {
		suffix[i] *= suffix[i + 1];
		suffix[i] %= m;
	}
	int node_no = 0;
	for (auto child : tree[curr_node]) {
		if (!visited[child]) {
			int ways = (1 + parent_answer);
			ways = (node_no > 0) ? (ways * prefix[node_no - 1]) : ways;
			ways = (node_no < suffix.size() - 1) ? (ways * suffix[node_no + 1]) : ways;
			solve2(tree, visited, child, ways);
			node_no++;
		}

	}
}

