void rec(int cur, int par) {
	dp[cur] = 1;
	for (int i = 0; i < t[cur].size(); i++) {
		if (t[cur][i] == par) 
			swap(t[cur][i], t[cur][t[cur].size() - 1]);
		if (t[cur][i] == par) break;
		rec(t[cur][i], cur);
		dp[cur] *= (dp[t[cur][i]] + 1) % m;
		dp[cur] %= m;
	}
	if (par != -1)
		t[cur].pop_back();
}

void solve(int cur, int par, ll pval) {
	ans[cur] = dp[cur] * (pval + 1);
	ans[cur] %= m;
	vll le(t[cur].size()), ri(t[cur].size());
	if (t[cur].size() > 0) {
		le[0] = dp[t[cur][0]] + 1;
		ri[t[cur].size() - 1] = dp[t[cur][t[cur].size() - 1]] + 1;
	}
	for (int i = 1; i < t[cur].size(); i++) {
		le[i] = le[i - 1] * (dp[t[cur][i]] + 1);
		le[i] %= m;
		ri[t[cur].size() - i - 1] = 
			(dp[t[cur].size() - i - 1] + 1) * ri[t[cur].size() - i];
		ri[i] %= m;
	}
	// for (int i = 0; i < t[cur].size(); i++) {
	// 	cout << le[i] << " " << ri[i] << endl;
	// }
	// cout << endl;
	for (int i = 0; i < t[cur].size(); i++) {
		ll left = 1;
		ll right = 1;
		if (i > 0) left = le[i - 1];
		if (i < t[cur].size() - 1) right = ri[i + 1];
		solve(t[cur][i], cur, ((pval + 1) * left * right) % m);
	}
}

