const int N = 1e5 + 1;
int n, mod;
vi adj[N];
ll up[N], down[N], sibling[N];

void dfs(int u, int p) {
	down[u] = 1;
	vector<pair<int, ll>> child;
	for (int v : adj[u]) if (v != p) {
		dfs(v, u);
		down[u] = down[u] * (1 + down[v]) % mod;
		child.emplace_back(v, down[v] + 1);
	}

	int m = child.size();
	if (m) {
		vll prefix(m+1), suffix(m+1);
		prefix[0] = suffix[m] = 1;
		for (int i = 1; i <= m; i++)
			prefix[i] = prefix[i-1] * child[i-1].second % mod;
		for (int i = m-1; i >= 0; i--)
			suffix[i] = suffix[i+1] * child[i].second % mod;
		for (int i = 0; i < m; i++)
			sibling[child[i].first] = prefix[i] * suffix[i+1] % mod;
	}
}

void dfs2(int u, int p) {
	up[u] = 1 + up[p] * sibling[u] % mod;
	for (int v : adj[u]) if (v != p)
		dfs2(v, u);
}

int main() {
	//~ ios::sync_with_stdio(0);
	//~ cin.tie(0);
