	for (int i = 0; i < n-1; i++) {
		int u, v;
		scanf("%d%d", &u, &v);
		adj[u].push_back(v);
		adj[v].push_back(u);
	}

	for (int i = 1; i <= n; i++) sibling[i] = 1;
	dfs(1, 0);
	dfs2(1, 0);
	//for (int u = 1; u <= n; u++) printf("%lld %lld %lld\n", up[u], down[u], sibling[u]);
	for (int u = 1; u <= n; u++)
		printf("%lld\n", up[u] * down[u] % mod);
}

