typedef long long ll;

const int MAX_N = 100000;

int n; 
ll m;
vector<int> graph[MAX_N];
vector<ll> dp[MAX_N];
int pi[MAX_N];

ll dfs(int v, int p=-1) {
    ll ret = 1LL;
    for(int i=0;i<graph[v].size();++i) {
        int u = graph[v][i];
        if(u == p) {
            pi[v] = i;
            continue;
        }
        dp[v][i] = dfs(u, v);
        ret *= dp[v][i] + 1LL;
        ret %= m;
    }
    return ret;
}

void bfs(int v, int *ans, ll res_p=0, int p=-1) {
    if(p != -1) {
        dp[v][pi[v]] = res_p;
    }
    vector<ll> dpl(graph[v].size()+1, 1LL);
    for(int i=0;i<graph[v].size();++i) {
        dpl[i+1] = dpl[i] * (dp[v][i]+1LL) % m;
    }
    vector<ll> dpr(graph[v].size()+1, 1LL);
    for(int i=graph[v].size()-1;i>=0;--i) {
        dpr[i] = dpr[i+1] * (dp[v][i]+1LL) % m;
    }
    ans[v] = dpr[0];
    for(int i=0;i<graph[v].size();++i) {
        int u = graph[v][i];
        if(u == p) continue;
        bfs(u, ans, dpl[i]*dpr[i+1]%m, v);
    }
}

