void dfs1(int a, int par ){ 

  int res = 1LL;

  for(auto ne : to[a] ){ 

    if( ne == par ){ continue;} 

    dfs1(ne,a);

    res = ( res * dp1[ne] ) % m;

    // +1済み
  }

  dp1[a] = (res+1)%m;

  return;
} 






//2つ目のdfs2
void dfs2(int a,int par){ 

  if( par == -1 ){ dp2[a] = 1LL;}

  vector<int> l_prod(101010,1);
  vector<int> r_prod(101010,1);

  for(int i = 0; i < (int)to[a].size(); i++){ 

    int res = 1LL;

    if( i-1 >= 0 ){ res *= l_prod[i-1];}

    if( to[a][i] != par ){ res *= dp1[to[a][i]];}

    res %= m;

    l_prod[i] = res;

  }

  for(int i = (int)to[a].size()-1; i >= 0; i--){ 

    int res = 1LL;

    if( to[a][i] != par ){ res *= dp2[to[a][i]];}

    res  *= r_prod[i+1];

    res %= m;

    r_prod[i] = res;
  }

  for(int j = 0; j  < (int)to[a].size(); j++){ 

    int res = 1LL;

    if( to[a][j] == par ){ continue;} 

    if( j-1 >= 0 ){ res *= l_prod[j-1];}
    res *= r_prod[j+1];

    res %= m;

    res = (res*dp2[a])%m;

    res = ( res+1 ) % m;

    dp2[to[a][j]] = res;
    //+1済み

    dfs2(to[a][j],a);

  }

  return ;
}


//３つ目のdfs 
void dfs3(int a, int par){ 

  int res = dp2[a];

  for(auto ne : to[a] ){ 

    if( ne == par ){ continue;} 

    res *= dp1[ne];
    res %= m;

    dfs3(ne,a);

  }

  ans[a] = res%m;

  return ;
}


