void solve(long long id) {
	vlist.push_back(id);
	black[id] = 1;

	for (auto p : adj[id]) {
		if (parent[p] == -1) {
			parent[p] = id;
			solve(p);
			black[id] = (black[id] * (black[p] + 1)) % MOD;
		}
	}
}


long long mul_inv(long long a, long long b)
{
	long long b0 = b, t, q;
	long long x0 = 0, x1 = 1;
	if (b == 1) return 1;
	while (a > 1) {
		q = a / b;
		if (b == 0) return -1;
		t = b, b = a % b, a = t;
		t = x0, x0 = x1 - q * x0, x1 = t;
	}
	if (x1 < 0) x1 += b0;
	return x1;
}

long long division(long long a, long long b, long long p) {		// (a / b) mod p = ((a mod p) * (b^(-1) mod p)) mod p
	long long ans, inv;

	if (a % b == 0) return a / b;
	if ((a + p) % b == 0) return (a + p) / b;
	inv = mul_inv(b, p);
	if (inv == -1) return 0;
	ans = ((a % p) * inv) % p;
	return ans;
}



int main()
{
