	black.resize(n + 1);
	solve(1);

	ans.resize(n + 1);
	ans[1] = black[1];
	for (i = 1; i < n; i++) {
		id = vlist[i];
		p = parent[id];
		x = (division(ans[p], black[id] + 1, MOD) + 1) % MOD;
		ans[id] = (x * black[id]) % MOD;
	}

	for (i = 1; i <= n; i++) cout << ans[i] << "\n";


	return 0;
}

