const int N = 1e5;
LL dp[N + 5];
vector<LL> vec[N + 5];
LL up[N + 5];
LL MOD;

LL ST[4 * N + 5];

void dfs(int idx,int pre) {
	dp[idx] = 1;
	for(int i = 0;i < vec[idx].size();i++) {
		int nx = vec[idx][i];
		if(nx == pre) continue;
		dfs(nx,idx);
		dp[idx] = dp[idx] * (dp[nx] + 1) % MOD;
	}
}

void build(int a, int idx,int l,int r) {
	if(l > r) return ;
	if(l == r){
		ST[idx] = (dp[vec[a][l]] + 1) % MOD;
		return ;
	}
	int mid = (l + r) / 2;
	build(a,2 * idx, l, mid), build(a,2 * idx + 1,mid + 1,r);
	ST[idx] = ST[2 * idx] * ST[2 * idx + 1] % MOD;
}

LL query(int idx,int l,int r,int tar) {
	if(r < tar || l > tar) return ST[idx];
	if(l == tar && r == tar) return 1;
	int mid = (l + r) / 2;
	return query(2 * idx,l,mid,tar) * query(2 * idx + 1,mid + 1,r,tar) % MOD;
}

void dfs2(int idx,int pre) {
	if(idx != pre) swap(up[idx], dp[pre]);
	build(idx,1,0,(int)vec[idx].size() - 1);
	for(int i = 0;i < vec[idx].size();i++) {
		int nx = vec[idx][i];
		if(nx == pre) continue;
//		cout<<"NX "<<nx<<" "<<(query(1,0,vec[idx].size() - 1, i) + 1)<<endl;
		up[nx] = (query(1,0,(int)vec[idx].size() - 1, i)) % MOD;
	}
	for(int i = 0;i < vec[idx].size();i++) {
		int nx = vec[idx][i];
		if(nx == pre) continue;
		dfs2(nx,idx);
	}
	if(idx != pre) swap(up[idx], dp[pre]);
}

