	for (ll i = 1; i < n; i++) {
		cin >> f >> s;
		gr[f].pb(s);
		gr[s].pb(f);
	}

	bool vis[n + 1];
	memset(vis, 0 , sizeof vis);

	solve1(1, vis);
	memset(vis, 0 , sizeof vis);

	solve2(1, vis, 0);
	for (ll i = 1; i <= n; i++)
		cout << dp2[i] % m << endl;
	return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

vector<ll> adj[100005];
ll pai[100005];
ll mod, down[100005], up[100005];

ll solve(ll u, ll p = 0){
    pai[u] = p;
    ll res = 1;
    for(ll v : adj[u])
        if(v != p)
            res *= (1 + solve(v, u));
    return down[u] = res;
}

void go(ll u, ll p = 0){
    vector<ll> vec, nodes;
    for(ll v : adj[u])
        if(v != p){
            nodes.push_back(v);
            vec.push_back(1 + down[v]);
        }

    vector<ll> pref(vec), suff(vec);
    for(ll i = 1; i < pref.size(); i++)
        pref[i] = (pref[i]*pref[i-1])%mod;
    for(ll i = ll(suff.size()) - 2; i >= 0; i--)
        suff[i] = (suff[i]*suff[i+1])%mod;

    for(ll i = 0; i < nodes.size(); i++){
        ll v = nodes[i];
        ll esq = (i-1 >= 0 ? pref[i-1] : 1);
        ll dir = (i+1 < vec.size() ? suff[i+1] : 1);
        esq = (esq*dir)%mod;
        //cout << u << " setando up de " << v << endl;
        up[v] = (1 + ((esq*up[u])%mod) )%mod;
    }

    for(ll v : nodes)
        go(v, u);
}

int main(){
    ll n; cin >> n >> mod;
    for(ll i = 0; i < n-1; i++){
        ll u, v; cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    ll root = 1;
    for(ll i = 1; i <= n; i++)
        if(!pai[i]){
            solve(i);
            root = i;
        }
    for(ll i = 1; i <= n; i++)
        up[i] = 1;

    go(root);
    // for(ll i = 1; i <= n; i++)
