void dfs2(int now, int par,int nowdp=0) {
	int N = G[now].size();
	vector<int>dpl(N), dpr(N);
	rep(i, N) {
		int u = G[now][i];
		if (u == par) {
			dpl[i] = dpr[i] = (nowdp + 1) % mod;
			dp1[now] *= nowdp + 1;
			dp1[now] %= mod;
		}
		else {
			dpl[i] = dpr[i] = (dp1[u] + 1) % mod;
		}
	}
	rep(i, N - 1)dpl[i + 1] = dpl[i + 1] * dpl[i] % mod;
