ll dp1[maxn];

vector<ll>g[maxn];
bool used[maxn];

void dfs(ll u){
	used[u] = 1;
	dp[u] = 1;
	for (ll v : g[u]) {
		if (used[v]) continue;
		dfs(v);
		dp[u] = mul(dp[u], 1 + dp[v]);
	}
}


void dfs1(ll u) {
	used[u] = 1;
	vector<ll>vec;
	for (ll v : g[u]) {
		if (used[v]) continue;
		vec.push_back(v);
	}
	if (vec.size() == 0) return;
	vector<ll>pref(vec.size()), suf(vec.size());
	for (ll i = 0; i < pref.size(); i++) {
		pref[i] = mul((i ? pref[i - 1] : 1LL), (1 + dp[vec[i]]) % mod);
	}
	suf.back() = (dp[vec.back()] + 1) % mod;
	for (ll i = (ll)vec.size() - 2; i >= 0; i--) {
		suf[i] = mul(suf[i + 1], (1 + dp[vec[i]]) % mod);
	}
	vector<ll>kek(vec.size());
	for (ll i = 0; i < kek.size(); i++) {
		kek[i] = mul((i ? pref[i - 1] : 1LL), ((ll)kek.size() - i - 1 ? suf[i + 1] : 1LL));
	}

	for (ll i = 0; i < vec.size(); i++) {
		ll v = vec[i];
		dp1[v] = (1 + mul(kek[i], dp1[u])) % mod;
		dfs1(v);
	}
}


