    // 葉から DFS
    std::stack<int> Stk;
    REP(i, n) if(ChildSize[i] == 0) Stk.push(i);
    while(not Stk.empty()){
        int v = Stk.top(); Stk.pop();

        for(int par : Edge[v]) if(Depth[par] < Depth[v]){

            (DP[par] *= (DP[v] + 1)) %= m;

            Child[par].push_back(v);
            S[par].push_back(DP[v] + 1);

            if((--ChildSize[par]) == 0) Stk.push(par);

            break;
        }
    }


    std::vector<lli> T; EP.assign(n, 1);
    Stk.push(root);
    while(not Stk.empty()){
        int v = Stk.top(); Stk.pop();

        const int nn = S[v].size();
        if(nn == 0) continue;

        T.resize(nn);  T[nn-1] = 1;
        for(int x = nn - 1; x - 1 >= 0; --x) T[x-1] = (T[x] * S[v][x]) % m;


        lli left = 1;
        for(int x = 0; x < nn; ++x){
            EP[Child[v][x]] = (left * T[x]) % m;
            (EP[Child[v][x]] *= EP[v])++; EP[Child[v][x]] %= m;
            Stk.push(Child[v][x]);
            (left *= S[v][x]) %= m;
        }
    }

    REP(i, n) printf("%lld\n", (DP[i] * EP[i]) % m);


    return 0;
}

