void dfs2(int node,int par = -1)
{
    res[node] = dp[node][1];

    vi p1,p2;
    vi s1,s2;

    for(auto x : g[node]) p1.pb(dp[x][0]),p2.pb((dp[x][0] + dp[x][1])%MOD);

    s1 = p1;
    s2 = p2;

    int sz = p1.size();

    if(sz == 1 && par == -1)
    {
        int x = g[node][0];

        dp[x][1] = (dp[x][1]*2)%MOD;

        dfs2(x,node);

        return;
    }
    else if(sz == 1) return;

    for(int i=1;i<sz;i++)
    {
        p1[i] = (p1[i-1]*p1[i])%MOD;
        p2[i] = (p2[i-1]*p2[i])%MOD;
    }

    reverse(s1.begin(),s1.end());
    reverse(s2.begin(),s2.end());

    for(int i=1;i<sz;i++)
    {
        s1[i] = (s1[i-1]*s1[i])%MOD;
        s2[i] = (s2[i-1]*s2[i])%MOD;
    }

    reverse(s1.begin(),s1.end());
    reverse(s2.begin(),s2.end());

    int idd = 0;

    for(auto x : g[node]) if(x != par)
    {   
        int save[2];
        f(i,2) save[i] = dp[node][i];

        if(idd == 0) dp[node][0] = s1[1],dp[node][1] = s2[1];
        else if(idd == sz-1) dp[node][0] = p1[sz-2],dp[node][1] = p2[sz-2];
        else dp[node][0] = (p1[idd-1]*s1[idd+1])%MOD, dp[node][1] = (p2[idd-1]*s2[idd+1])%MOD;

        dp[x][0] = (dp[x][0]*dp[node][0])%MOD;
        dp[x][1] = (dp[x][1]*(dp[node][0] + dp[node][1])%MOD)%MOD;

        dfs2(x,node);

        f(i,2) dp[node][i] = save[i];

        idd++;
    }
}

