void fill_down(long long u, long long pr = -1) {
    down[u] = 1;
    p[u] = pr;
    vector<long long> a;
    int id = 0;
    for (int i = 0; i < (int)g[u].size(); i++) {
        long long v = g[u][i];
        if (v == pr) continue;
        fill_down(v, u);
        a.push_back(down[v] + 1);
        down[u] *= down[v] + 1;
        down[u] %= MOD;
        ind[u][v] = id++;
    }
    pref[u].resize(a.size() + 1);
    suff[u].resize(a.size() + 1);
    pref[u][0] = 1;
    for (int i = 1; i <= (int)a.size(); i++) {
        pref[u][i] = pref[u][i - 1] * a[i - 1];
        pref[u][i] %= MOD;
    }
    suff[u][a.size()] = 1;
    for (int i = a.size() - 1; i > -1; i--) {
        suff[u][i] = suff[u][i + 1] * a[i];
        suff[u][i] %= MOD;
    }
}

void fill_up(long long u, long long pr = -1) {
    up[u] = 1;
    if (pr != -1) {
        up[u] *= up[pr];
        up[u] %= MOD;
        up[u] *= pref[pr][ind[pr][u]];
        up[u] %= MOD;
        up[u] *= suff[pr][ind[pr][u] + 1];
        up[u] %= MOD;
        up[u]++;
        up[u] %= MOD;
        // cerr << u + 1 << ' ' << suff[pr].size() << ' ' << ind[pr][u] + 1 << endl;
    }
    for (long long v : g[u]) {
        if (v == pr) continue;
        fill_up(v, u);
    }
}

