int MOD;
std::vector<std::vector<int> > hen;
std::vector<std::pair<int, int> > subtree;
std::vector<std::pair<int, int> > res;
void dfs1(int i, int prev) {
	// first : sum(first) + sum(second)
	// second : prod(second + 1)
	subtree[i].first = 0;
	subtree[i].second = 1;
	for (auto j : hen[i]) {
		if (j != prev) {
			dfs1(j, i);
			subtree[i].first += subtree[j].first;
			if (subtree[i].first >= MOD) subtree[i].first -= MOD;
			subtree[i].first += subtree[j].second;
			if (subtree[i].first >= MOD) subtree[i].first -= MOD;
			subtree[i].second = (int64_t) subtree[i].second * (subtree[j].second + 1) % MOD;
		}
	}
}
void dfs2(int i, int prev, std::pair<int, int> parent) {
	res[i].first = 0;
	res[i].second = 1;
	std::vector<std::pair<int, int> > childs;
	for (auto j : hen[i]) {
		std::pair<int, int> cur;
		if (j == prev) cur = parent;
		else cur = subtree[j];
		res[i].first += cur.first;
		if (res[i].first >= MOD) res[i].first -= MOD;
		res[i].first += cur.second;
		if (res[i].first >= MOD) res[i].first -= MOD;
		res[i].second = (int64_t) res[i].second * (cur.second + 1) % MOD;

		if (j != prev) childs.push_back(subtree[j]);
	}

	int m = childs.size();
	std::vector<int> prod_left(m + 1), prod_right(m + 1);
	prod_left[0] = 1;
	for (int i = 0; i < m; i++) prod_left[i + 1] = (int64_t) prod_left[i] * (childs[i].second + 1) % MOD;
	prod_right[m] = 1;
	for (int i = m; i; i--) prod_right[i - 1] = (int64_t) prod_right[i] * (childs[i - 1].second + 1) % MOD;

	int cnt = 0;
	for (auto j : hen[i]) {
		if (j != prev) {
			int first = res[i].first;
			first -= subtree[j].first;
			if (first < 0) first += MOD;
			first -= subtree[j].second;
			if (first < 0) first += MOD;
			int second = (int64_t) prod_left[cnt] * prod_right[cnt + 1] % MOD;
			if (prev != -1) second = (int64_t) second * (parent.second + 1) % MOD;
			dfs2(j, i, {first, second});
			cnt++;
		}
	}

}
