ll calc(int v, int p) {
    ll res = 1;
    for (int u : G[v]) {
        if (u == p) continue;
        res *= (calc(u, v) + 1);
        res %= m;
    }
    return dp[v] = res;
}

void calc2(int v, int p, ll val) {
    dp2[v] = (dp[v] * val) % m;
    int sz = G[v].size();
    ll suf[sz+1], pre[sz+1];
    suf[0] = pre[0] = 1;
    for (int i = 0; i < sz; i++) {
        int u = G[v][i];
        if (u == p) {
            suf[i+1] = suf[i];
        } else {
            suf[i+1] = (suf[i] * (dp[u]+1)) % m;
        }

        int w = G[v][sz-i-1];
        if (w == p) {
            pre[i+1] = pre[i];
        } else {
            pre[i+1] = (pre[i] * (dp[w]+1)) % m;
        }
    }

    for (int i = 0; i < sz; i++) {
        int u = G[v][i];
        if (u == p) continue;

        calc2(u, v, ((val * suf[i] % m) * pre[sz-i-1] + 1) % m);
    }
}

