ll M;

void dfs1(int s, int prev, vector<vector<int>>& graph, vector<ll>& dp) {
    for(auto next: graph[s]) {
        if(next != prev) {
            dfs1(next, s, graph, dp);
            dp[s] *= (dp[next] + 1) % M;
        }
    }
}

void dfs2(int s, int prev, vector<vector<int>>& graph, vector<ll>& dp, vector<ll>& ans, ll prev_comb) {
    vector<ll> values;
    vector<int> edges;
    for(auto next: graph[s]) {
        if(next != prev) {
            values.push_back(dp[next]);
            edges.push_back(next);
        }
    }

    int size = values.size();
    if(size == 0) return;

    vector<ll> prod_forward(size+2, 1), prod_backward(size+2, 1);
    for(int i=1; i<=size; i++) {
        prod_forward[i] = (1+values[i-1]) % M ;
        prod_forward[i] *= prod_forward[i-1] % M;
        prod_backward[size-i+1] = (1+values[size-i]) % M;
        prod_backward[size-i+1] *= prod_backward[size-i+2] % M;
    }

    for(int i=1; i<=size; i++) {
        ll tmp = prev_comb;
        tmp *= prod_forward[i-1] % M;
        tmp = ((tmp*prod_backward[i+1])%M + 1) % M;
        ans[edges[i-1]] =  tmp * values[i-1] % M;
        dfs2(edges[i-1], s, graph, dp, ans, tmp);
    }
}

