    add_undirected(tree, x, y, 1);
  }

  rooting(tree, 0);


  std::vector<mint> dp1(N);
  std::vector<mint> dp2(N, 1);

  {
    auto rec =
      make_fix_point([&](auto &f, int cur) -> mint{
                       dp1[cur] = 1;

                       for(auto &e : tree[cur]){
                         dp1[cur] = dp1[cur] * (f(e.to) + 1); 
                       }

                       return dp1[cur];
                     });
    rec(0);
  }

  {
    auto rec =
      make_fix_point([&](auto &f, int cur, int par, mint left_acc, mint right_acc) -> void{
                       if(par != -1){
                         dp2[cur] = dp2[par] * left_acc * right_acc + 1;
                       }

                       int l = tree[cur].size();

                       std::vector<mint> left(l+1, 1), right(l+1, 1);

                       for(int i = 0; i < l-1; ++i){
                         left[i+1] = left[i] * (dp1[tree[cur][i].to] + 1);
                       }

                       for(int i = l-1; i >= 1; --i){
                         right[i-1] = right[i] * (dp1[tree[cur][i].to] + 1);
                       }

                       for(int i = 0; i < l; ++i){
                         auto &e = tree[cur][i];
                         f(e.to, cur, left[i], right[i]);
                       }
                     });
    rec(0, -1, 1, 1);
  }

  for(int i = 0; i < N; ++i){
    mint ans = dp2[i] * dp1[i];
    std::cout << ans << "\n";
  }

  return 0;
}

