        Edge e{(ll)edges.size(), x, y};
        edges.push_back(e);
        tree[x].push_back(e);
        tree[y].push_back(e);
    }
    for (ll i = 0; i < edges.size(); i++) {
        subtree.push_back(vector<unique_ptr<Mod>>(2));
    }
    for (ll i = 0; i < edges.size(); i++) {
        calc_subtree(i, 0);
        calc_subtree(i, 1);
    }
    for (ll vertex = 0; vertex < N; vertex++) {
        Mod ans = 1;
        for (Edge e : tree[vertex]) {
            ll ori;
            if (e.y == vertex) {
                ori = 0;
            } else {
                ori = 1;
            }
            ans *= *subtree[e.idx][ori];
        }
        cout << ans.value << endl;
    }
}

