pair<int,int>merge(const pair<int,int>&a,const pair<int,int>&b){
    pair<int,int>p;
    p.first=(long long)(a.first)*(b.first)%m;
    p.second=((long long)(a.second)*((b.first+b.second)%m)%m+(long long)(a.first)*(b.second)%m)%m;
    return p;
}

pair<int,int>pro(pair<int,int>p){
    return {p.first,(p.first+p.second)%m};
}

void dfs(int current,int prev){
    pair<int,int>p{1,0};
    for(auto x:edges[current]){
        if(x!=prev){
            child[current].push_back(x);
            dfs(x,current);
            p=merge(p,d[x]);
            downs[current].push_back(d[x]);
        }
    }
    d[current]=pro(p);
}

void dfs2(int current,int prev){
    for(int i=0;i<child[current].size();i+=1){
        pair<int,int>p{1,0};
        if(i){
            p=merge(p,pref[current][i-1]);
        }
        if(i!=(downs[current].size()-1)){
            p=merge(p,suf[current][i+1]);
        }
        if(current!=1){
            p=merge(p,u[current]);
        }
        int b=child[current][i];
        u[b]=pro(p);
        dfs2(b,current);
    }
}

