	    for(int j=0;j<k;j+=1){
	        p=merge(p,downs[i][j]);
	        pref[i].push_back(p);
	    }
	    p={1,0};
	    for(int j=(k-1);j>-1;j-=1){
	        p=merge(p,downs[i][j]);
	        suf[i].push_back(p);
	    }
	    reverse(suf[i].begin(),suf[i].end());
	}
	dfs2(1,-1);
	for(int i=1;i<=n;i+=1){
	    pair<int,int>p{1,0};
	    if(i!=1){
	        p=merge(p,u[i]);
	    }
	    if(!child[i].empty()){
	        p=merge(p,pref[i].back());
	    }
	    p=pro(p);
	    printf("%d\n",p.second);
	}
	return 0;
}

