void dfs1(int v, int p)
{
	if(adj[v].empty()) return; // special case: only one node in the graph
	for(int i = 0; i < adj[v].size(); i++) if(adj[v][i] != p)
	{
		dfs1(adj[v][i], v);
		dp[v] = (dp[v] * ((1 + dp[adj[v][i]]) % m)) % m;
	}
	pre[v].resize(adj[v].size());
	suf[v].resize(adj[v].size());
	pre[v][0] = ((adj[v][0] == p) ? 1 : (1 + dp[adj[v][0]]) % m);
	suf[v][adj[v].size() - 1] = ((adj[v][adj[v].size() - 1] == p) ? 1 : (1 + dp[adj[v][adj[v].size() - 1]]) % m);
	for(int i = 1; i < adj[v].size(); i++)
	{
		if(adj[v][i] == p) pre[v][i] = pre[v][i - 1];
		else pre[v][i] = (pre[v][i - 1] * ((1 + dp[adj[v][i]]) % m)) % m;
	}
	for(int i = adj[v].size() - 2; i > -1; i--)
	{
		if(adj[v][i] == p) suf[v][i] = suf[v][i + 1];
		else suf[v][i] = (suf[v][i + 1] * ((1 + dp[adj[v][i]]) % m)) % m;
	}
}

void dfs2(int v, int p, int i)
{
	if(v) // dp[v] *= (1 + dp[p]/(1 + dp[v]));
	{
		int j = 0;
		ll temp;
		if(adj[p].size() == 1) temp = 1;
		else if(i - 1 == -1) temp = suf[p][i + 1];
		else if(i + 1 == adj[p].size()) temp = pre[p][i - 1];
		else temp = (pre[p][i - 1] * suf[p][i + 1]) % m;
		dp[v] = (dp[v] * ((1 + temp) % m));
		// from here we update pre and suf
		while(adj[v][j] != p) j++;
		pre[v][j] = (!j ? (1 + temp) % m : (pre[v][j - 1] * ((1 + temp) % m)) % m);
		suf[v][j] = (j == adj[v].size() ? (1 + temp) % m : (suf[v][j + 1] * ((1 + temp) % m)) % m);
		int jj = j + 1;
		while(jj < adj[v].size())
		{
			pre[v][jj] = (pre[v][jj - 1] * ((1 + dp[adj[v][jj]]) % m)) % m;
			jj++;
		}
		jj = j - 1;
		while(jj > -1)
		{
			suf[v][jj] = (suf[v][jj + 1] * ((1 + dp[adj[v][jj]]) % m)) % m;
			jj--;
		}
	}
	for(int i = 0; i < adj[v].size(); i++) if(adj[v][i] != p) dfs2(adj[v][i], v, i);
}

