void dp(int p, int q, vector<vector<int>> &V, vector<LL> &s, LL mod){
	for(auto u : V[q]) if(u != p){
		dp(q,u,V,s,mod);
		(s[q] *= (s[u]+1)) %= mod;
	}
}

void solve(int p, int q, LL x, vector<vector<int>> &V, vector<LL> &s, vector<LL> &ans, LL mod){
	ans[q] = s[q]*x%mod;
	vector<LL> b(V[q].size(),1);
	repm(i,V[q].size()-1,0) b[i-1] = b[i]*(V[q][i]==p?1:(s[V[q][i]]+1))%mod;
	LL a = 1;
	repp(i,0,V[q].size()) if(V[q][i] != p){
		solve(q,V[q][i],x*a%mod*b[i]%mod+1,V,s,ans,mod);
		a = a*(s[V[q][i]]+1)%mod;
	}
}

