    }
    if(a!=1)
    {
        soln[a]=1;
        for(auto &k:graph[a])
            soln[a]=(soln[a]*(dp[k]+1))%mo;
        soln[a]=(soln[a]*(dp_parent[a]+1))%mo;
    }
