//rerooting
void dfs2(int x,int p){
    ans[x] = dp[x];

    int sz=to[x].size();
    //子のdpの値の左右の累積積
    vector<ll> l(sz+1), r(sz+1);
    l[0]=1;
    rep(i,sz) l[i+1]=(l[i]*(dp[to[x][i]]+1))%m;
    r[sz]=1;
    for(int i=sz-1;i>=0;i--) r[i]=(r[i+1]*(dp[to[x][i]]+1))%m;

    rep(i,sz){
        int nv=to[x][i]; // 子
        if(nv==p) continue;
        ll tmp_x = dp[x];
        ll tmp_nv = dp[nv];
        dp[x]=(l[i]*r[i+1])%m;
        dp[nv]*=dp[x]+1;
        dp[nv]%=m;
        dfs2(nv, x);
        // 元に戻す
        dp[x] = tmp_x;
        dp[nv] = tmp_nv;
    }
}

