using ll = long long;
const int MAX = 1e5;
ll m;
vector<int> G[MAX], H[MAX];

vector<int> color(MAX, 0);
vector<ll> dp1(MAX); // dp1[i]:頂点iを根とした木で, 頂点iを黒く塗る方法の数(mod m)
void dfs1(int v) {
  color[v] = 1;
  ll keep = 1;
  for (int i = 0; i < G[v].size(); i++) {
    if (color[G[v][i]] == 0) {
      dfs1(G[v][i]);
      H[v].emplace_back(G[v][i]);
    }
    keep *= dp1[G[v][i]] + 1;
    keep %= m;
  }
  color[v] = 2;
  dp1[v] = keep;
  return;
}

vector<ll> dp2(MAX); // dp2[i]:頂点iから親方向に見たsubtreeで, 頂点iを黒く塗る方法の数(mod m)
void dfs2(int v) {
  vector<ll> l(H[v].size()), r(H[v].size()); // 左右からの累積積
  for (int i = 0; i < H[v].size(); i++) {
    l.at(i) = dp1[H[v][i]] + 1;
    if (i > 0) l.at(i) *= l.at(i - 1);
    l.at(i) %= m;
  }
  for (int i = H[v].size() - 1; i >= 0; i--) {
    r.at(i) = dp1[H[v][i]] + 1;
    if (i < H[v].size() - 1) r.at(i) *= r.at(i + 1);
    r.at(i) %= m;
  }

  ll keep = 1;
  if (v != 0) keep *= dp2[v];
  keep %= m;

  for (int i = 0; i < H[v].size(); i++) {
    ll pro = 1;
    if (i > 0) pro *= l.at(i - 1);
    pro %= m;
    if (i < H[v].size() - 1) pro *= r.at(i + 1);
    pro %= m;

    dp2[H[v][i]] = (keep * pro + 1) % m;
    dfs2(H[v][i]);
  }
  return;
}

