long rec(vector<int> adj[], int m, int id, long **mem, int prev=-1)
{
  if(prev!=-1&&mem[id][prev]!=-1)
    return mem[id][prev];
  long ans=1;
  for(int i=0;i<adj[id].size();i++)
  {
    if(adj[id][i]!=prev)
    {
      ans*=rec(adj,m,adj[id][i],mem,id);
      ans%=m;
    }
  }
  if(prev!=-1)
	ans++;
  ans%=m;
  mem[id][prev]=ans;
  return ans;
}

