function<int(int, int)> Div, Mul;

void dfs(int cur, int fa)
{
    dp[cur] = 1;
    for (const auto &v : G[cur])
    {
        if (v == fa)
            continue;
        dfs(v, cur);
        dp[cur] = Mul(dp[cur], dp[v] + 1);
    }
}

void update(int cur, int fa)
{
    for (const auto &v : G[cur])
    {
        if (v == fa)
            continue;

        ans[v] = dp[v];

        ans[v] = Mul(ans[v], Div(ans[cur], dp[v] + 1) + 1);
        update(v, cur);
    }
}

// Pre-Build Function
inline void build()
{
    clr(dp);
    clr(ans);
}

// Actual Solver
inline void solve()
{
    int N, M;
    cin >> N >> M;

    Div = [&M](int a, int b) {
        ll p = M * b;
        ll ans = a % p;
        return static_cast<int>(ans / b);
    };

    Mul = [&M](int a, int b) {
        ll ans = (a % M) * (b % M) % M;
        return static_cast<int>(ans);
    };

    for (int i = 1; i < N; i++)
    {
        int x, y;
        readln(x, y);
        G[x].pb(y);
        G[y].pb(x);
    }

    dfs(1, -1);
    ans[1] = dp[1];
    update(1, -1);

    for (int i = 1; i <= N; i++)
        cout << ans[i] << '\n';
}

