void dfs1(int v, int p) {
	ll now = 1;
	for (int u: eds[v]) {
		if (u == p)
			continue;
		dfs1(u, v);
		now = (now * dp[u]) % MOD;
	}
	now = (now + 1) % MOD;
	dp[v] = now;
}

ll ans[MAXN];

void dfs2(int v, int p, ll up) {
	ll cur = up;
	for (int u: eds[v])
		if (u != p)
			cur = (cur * dp[u]) % MOD;
	ans[v] = cur;
	vector<ll> lb(eds[v].size());
	vector<ll> rb(eds[v].size());
	ll now = 1;
	for (int i = 0; i < eds[v].size(); ++i) {
		lb[i] = now;
		int u = eds[v][i];
		if (u == p)
			continue;
		now = (now * dp[u]) % MOD;
	}
	now = 1;
	for (int i = (int)eds[v].size() - 1; i >= 0; --i) {
		rb[i] = now;
		int u = eds[v][i];
		if (u == p)
			continue;
		now = (now * dp[u]) % MOD;
	}
	for (int i = 0; i < eds[v].size(); ++i) {
		int u = eds[v][i];
		if (u == p)
			continue;
		ll go = (up * lb[i]) % MOD * rb[i] % MOD;
		go = (go + 1) % MOD;
		dfs2(u, v, go);
	}
}

