	for (int child : tree[src])
	{
		if (!vis[child])
		{
			prefix.pb((int)1 + dp1[child]);
			suffix.pb((int)1 + dp1[child]);
		}
	}
	int size1 = prefix.size(), size2 = suffix.size();
	repD(i, size2 - 2, 0)
	{
		suffix[i] = (suffix[i + 1] * suffix[i]) % m;
	}
	repA(i, 1, size1 - 1)
	{
		prefix[i] = (prefix[i - 1] * prefix[i]) % m;
	}
	int cno = 0;
	for (int child : tree[src])
	{
		if (!vis[child])
		{
			int ways = (1 + par_ans) % m;
			ways = (cno > 0) ? (ways * prefix[cno - 1]) % m : ways % m;
			ways = (cno < (size2 - 1)) ? (ways * suffix[cno + 1]) % m : ways % m;
			solve2(child, vis, m, ways);
			cno++;
		}
	}
}
