struct SegmentTree{
    struct node{
        node *l = nullptr;
        node *r = nullptr;
        ll val = 1;
        node(){}
    };
    node *root = new node();

    void update(node *cur,int l,int r,int p,int val){
        if(l==r){
            cur->val = val;
        }
        else{
            int m = (l+r)/2;
            if(p<=m){
                if(!cur->l){
                    cur->l = new node();
                }
                update(cur->l,l,m,p,val);
                cur->val = cur->l->val;
                if(cur->r) cur->val *= cur->r->val;
            }
            else{
                if(!cur->r){
                    cur->r = new node();
                }
                update(cur->r,m+1,r,p,val);
                cur->val = cur->r->val;
                if(cur->l) cur->val *= cur->l->val;
            }
        }
        cur->val %= modulo;
    }
    ll query(node *cur,int l,int r,int a,int b){
        if(!cur or r < a or l > b or a > b) return 1;
        if(l>=a && r<=b){
            return cur->val;
        }
        int m = (l+r)/2;
        return query(cur->l,l,m,a,b) * query(cur->r,m+1,r,a,b) % modulo;
    }   
};
