//! value: variations over the 'to' node
//!         = 2 when 'to' is a leaf, which has only one edge (not to include the edge or to include the edge)
//!         = (1 + vars of the other edge) when 'to' has two edges (not to include the edge or vars from 'to')
//!         = (1 + accumulated product of vars of all the other edges)  <-- this actually includes the two cases above

//! Fill vars on edges that are visited from the dfs that start from node 1 
void dfs(int curr, int from, vector<Edge>& nodes) 
{
	for (auto it: nodes[curr]) {
		if (it.first != from) {
			dfs(it.first, curr, nodes);
		}
	}
	if (0 <= from) {
		LL vars = 1;
		for (auto it: nodes[curr]) {
			if (it.first != from) {
				vars = (vars * it.second) % M;
			}
		}
		nodes[from][curr] = 1LL + vars;
	}
}

//! Fill vars that are are not filled with dfs1
void fillGap(int curr, int from, vector<Edge>& nodes) 
{
	if (nodes[from][curr] == 0) {
		for (auto it: nodes[curr]) {
			if (it.first != from) {
				fillGap(it.first, curr, nodes);
			}
		}
		LL vars = 1;
		for (auto it: nodes[curr]) {
			if (it.first != from) {
				vars = (vars * it.second) % M;
			}
		}
		nodes[from][curr] = 1LL + vars;
	}
}

int main() 
{
	int N;
	cin >> N >> M;
	vector<Edge> nodes(N);
	rep(i, N-1) {
		int x, y;
		cin >> x >> y;
		--x; --y;
		nodes[x][y] = 0;
		nodes[y][x] = 0;
	}

	dfs(0, -1, nodes);
	rep(from, N) {
		for (auto it: nodes[from]) {
			fillGap(it.first, from, nodes);
		}
	}

	rep(from, N) {
		LL vars = 1;
		for (auto it: nodes[from]) {
			vars = (vars * it.second) % M;
		}
		cout << vars << endl;
	}

	return 0;
}

