void calc(int v,int p) {
    sub[v] = 1;
    for (int i : adj[v])
        if (i != p) {
            calc(i,v);
            sub[v] = (ll)sub[v]*(sub[i] + 1)%mod;
        }
}
int pw(int a,int n) {
    int y = 1;
    for (;n;n/=2) {
        if (n&1) y = (ll)y*a%mod;
        a = (ll)a*a%mod;
    }
    return y;
}
int phi(int n) {
    int x = 1;
    for (int lim = sqrt(n), i = 2; i <= lim; i++) {
        if (n % i == 0) {
              while (n%i == 0) {
                n/=i;
                x*=i;
              }
              x/=i;
              x*=(i-1);
        }
    }
    if (n != 1) x*=(n-1);
    return x;
}
void dfs(int v,int p) {
    ll z = (ll)ans[p]*sub[v]%mod;
    ll e  =sub[v] + 1;
    ll g = __gcd(z,e);
    z/=g; e/=g;
    ans[v] = (sub[v] + (ll)z%mod*pw(e,p-1)%mod)%mod;
