	for(auto u: adj[node]){
		if(u == prv) continue;
		sub[node]*=(sub[u]+1);
	}
}

mi nsub[100005];

void dfs2(int node){
	for(auto u: child[node]){
		dfs2(u);
	}
	int n = sz(child[node]);
	vector<mi> pref(n);
	vector<mi> suff(n);
	for(int i = 0; i < n; i++){
		if(i == 0){
			pref[i] = sub[child[node][i]]+1;
		}
		else{
			pref[i] = pref[i-1]*(sub[child[node][i]]+1);
		}
	}

	for(int i = n-1; i >= 0; i--){
		if(i == n-1){
			suff[i] = sub[child[node][i]]+1;
		}
		else{
			suff[i] = suff[i+1]*(sub[child[node][i]]+1);
		}
	}

	for(int i = 0; i < n; i++){
		nsub[child[node][i]] = 1;
		if(i > 0) nsub[child[node][i]]*=pref[i-1];
		if(i < n-1) nsub[child[node][i]]*=suff[i+1];
	}

}
