const int Nmax = 1e5 + 5;

vector <int> adj[Nmax];

int sub[Nmax];
int par[Nmax];
int n,mod;

void mul(int &a, int b)
{
    a *= b;
    if (a >= mod) a %= mod;
}

void add(int &a, int b)
{
    a += b;
    if (a >= mod) a %= mod;
}

void solve_sub(int u, int p)
{
    sub[u] = 1;
    for (int v : adj[u])
    {
        if (v == p) continue;
        solve_sub(v, u);
        mul(sub[u], sub[v] + 1);
    }
}

void solve_par(int u, int p)
{
    vector <int> pre(0), suf(0);
    for (int i = 0; i < adj[u].size(); i++)
    {
        int v = adj[u][i];
        pre.push_back(1);
        suf.push_back(1);
        if (v == p) continue;
        pre.back() += sub[v];
        suf.back() += sub[v];
    }
    for (int i = 1; i < adj[u].size(); i++)
    {
        mul(pre[i], pre[i - 1]);
    }
    for (int i = (int) adj[u].size() - 2; i >= 0; i--)
    {
        mul(suf[i], suf[i + 1]);
    }
    for (int i = 0; i < adj[u].size(); i++)
    {
        int v = adj[u][i];
        if (v == p) continue;
        int a = par[u] + 1;
        int b = (i) ? pre[i - 1] : 1;
        int c = (i + 1 < adj[u].size()) ? suf[i + 1] : 1;
        par[v] = (a * b * c) % mod;
        solve_par(v, u);
    }
}

