ll calc(int tr,int sss)
{
    if(tr==-1)
        return 0;
    if(dp[tr][sss]!=-1)
        return dp[tr][sss];
    dp[tr][sss]=calc(tr-1,sss);
    int ss=sss;
    if(ss==S-1)
        ss=s[tr];
    else
        ss=min(ss-w[tr],s[tr]);
    if(ss>=0)
        dp[tr][sss]=max(dp[tr][sss],v[tr]+calc(tr-1,ss));
    return dp[tr][sss];
}

