ll dfs(int v, int u=-1)
{
  ll res = 1;
  rep(i,tree[v].size())
  {
    int e = tree[v][i];
    if(e == u)continue;
    dp[v][i] = dfs(e,v)%m;
    (res *= (1+dp[v][i])%m) %= m;
  }

  return res%m;
}

void dfs2(int v, int u=-1,ll p = 0)
{
  if(u != -1)
  {
    rep(i,sz(tree[v]))
    {
      int e = tree[v][i];
      if(e == u)
      {
        dp[v][i] = p;
        break;
      }
    }
  }

  vll L(tree[v].size(),1);
  vll R(tree[v].size(),1);
  For(i,1,tree[v].size())
  {
    (L[i] = (L[i-1] *(1 + dp[v][i]))%m) %= m;
  }
  drep(i,tree[v].size()-1)
  {
    if(i != (tree[v].size()-1))(R[i] = (R[i+1] * (1 + dp[v][i+1]))%m)%m;
    ll tot = L[i]%m * R[i]%m;
    tot %= m;
    int e = tree[v][i];
    if(e == u)continue;
    dfs2(e,v,tot);
  }
}

