const int MX = 1e5+7;

vector<int> g[MX];
void eadd(int u, int v)
{
  g[u].push_back(v);
  g[v].push_back(u);
}

ll mod, dp[MX], ans[MX], magic[MX];

void dfsDp(int u=1, int p=-1)
{
  dp[u] = 1;
  for(int v: g[u]) if(v != p)
  {
    dfsDp(v, u);
    dp[u] = dp[u] * (dp[v] + 1) % mod;
  }
}

void dfsAns(int u=1, int p = -1)
{
  ans[u] = dp[u] * magic[u] % mod;
  //~ cerr << "magic[" << u << "] = " << magic[u] << endl;

  ll cur = 1ll;
  for(int v: g[u]) if(v != p) 
  {
    magic[v] = cur;
    cur = cur * (dp[v] + 1) % mod;
  }
  cur = 1ll;
  for(int j=g[u].size()-1;j>=0;--j) if(g[u][j] != p) 
  {
    int v = g[u][j];
    magic[v] = magic[v] * cur % mod;
    cur = cur * (dp[v] + 1) % mod;
  }

  for(int v: g[u]) if(v != p) magic[v] = (magic[v] * magic[u] % mod + 1) % mod;

  //~ cerr << "magic[" << u << "] = " << magic[u] << endl;

  for(int v: g[u]) if(v != p) dfsAns(v, u);
}

