void dfs1(int now, int par) {
	dp1[now] = 1;
	for (int e : G[now]) {
		if (e == par)continue;
		dfs1(e, now);
		dp1[now] *= dp1[e] + 1;
		dp1[now] %= mod;
	}
}
void dfs2(int now, int par,int nowdp=0) {
	int N = G[now].size();
	vector<int>dpl(N), dpr(N);
	rep(i, N) {
		int u = G[now][i];
		if (u == par) {
			dpl[i] = dpr[i] = (nowdp + 1) % mod;
			dp1[now] *= nowdp + 1;
			dp1[now] %= mod;
		}
		else {
			dpl[i] = dpr[i] = (dp1[now] + 1) % mod;
		}
	}
	rep(i, N - 1)dpl[i + 1] = dpl[i + 1] * dpl[i] % mod;
	for (int i = N - 1; i > 0; i--)dpr[i - 1] = dpr[i - 1] * dpr[i] % mod;

	rep(i, N) {
		int u = G[now][i];
		if (u == par)continue;
		int na = 1, nb = 1;
		if (i)na = dpl[i - 1];
		if (i != N - 1)nb = dpr[i + 1];
		dfs2(u, now, na*nb%mod);
	}
}

