vector<ll> DP(MAX), DP2(MAX), ans(MAX);
vector<vector<ll>> G(MAX);


int dfs(ll x, ll p){
    ll res = 1;
    for(auto v : G[x]){
        if(v == p) continue;
        res *= (dfs(v, x)+1);
        //res %= M;
    }
    DP[x] = res;
    return DP[x];
}

void dfs2(ll x, ll p = -1){
    ll res = 1;
    vector<ll> pt;
    for(auto v : G[x]) if(v != p) pt.push_back(v);
    vector<ll> Acc1, Acc2; Acc1.push_back(1); Acc2.push_back(1);
    for(auto v : pt){
        if(v == p) continue;
        Acc1.push_back(DP[v]+1);
        Acc2.push_back(DP[v]+1);
    }Acc1.push_back(1); Acc2.push_back(1);
    for(int i = 0; i < Acc1.size()-1; i++) (Acc1[i+1] *= Acc1[i])%M;
    for(int i = Acc2.size()-1; i > 0; i--) (Acc2[i-1] *= Acc2[i])%M;

    for(int i = 0; i < pt.size(); i++){
        ll idx = i+1;
        ll v = pt[i];
        DP2[v] = ((Acc1[idx-1] * Acc2[idx+1])%M * DP2[x])%M + 1;
    }
    for(auto v : G[x]){
        if(p != v)dfs2(v, x);
    }
}

