void dfs(int cur = 1, int prev = 0)
{
	int size = adj[cur].size();
	pre[cur].resize(size, 1);
	post[cur].resize(size, 1);

	for (int i: adj[cur])
		if (i != prev)
		{
			dfs(i, cur);
			ans[cur] = ans[cur] * (ans[i] + 1) % m;
		}

	for (int i = 0, j = 0; i < size; i++, j++)
	{
		if (adj[cur][i] == prev) {j--; continue;}
		if (j == 0) pre[cur][j] = (ans[adj[cur][i]] + 1) % m;
		else pre[cur][j] = (ans[adj[cur][i]] + 1) * pre[cur][j - 1] % m;
	}

	for (int i = size - 1, j = size - 2; i >= 0; i--, j--)
	{
		if (adj[cur][i] == prev) {j++; continue;}
		post[cur][j] = (ans[adj[cur][i]] + 1) * post[cur][j + 1] % m;
	}
}

void dfsa(int cur = 1, int prev = 0)
{
	int size = adj[cur].size();
	for (int i = 0, j = 0; i < size; i++, j++)
	{
		if (adj[cur][i] == prev) {j--; continue;}

		if (j == 0) f[adj[cur][i]] = (post[cur][j + 1] * f[cur] + 1) % m;
		else f[adj[cur][i]] = ((pre[cur][j - 1] * post[cur][j + 1] % m) * f[cur] + 1) % m;
		dfsa(adj[cur][i], cur);
	}
}

