        dfs(v,u);
        ans[u]*=1+ans[v];
        down[u].push_back({ans[v],v});
        ans[u]%=m;
    }
    ans[u]%=m;
    ll n=down[u].size();
    if(!n)
        return ;
    ll x=1;
    x*=1+down[u][0].fi;
    pre[u].push_back(x);
    for(ll i=1;i<n;i++)
    {
        x*=down[u][i].fi+1;
        x%=m;
        pre[u].push_back(x);
    }
    x=1;
    ll y=1;
    x*=down[u][n-1].fi+1;
    x%=m;
    suf[u].push_back(x);
    for(ll i=n-2;i>=0;i--)
    {
        x*=1+down[u][i].fi;
        y*=1+down[u][i].fi;
        y%=m;
        x%=m;
        suf[u].push_back(x);
        suf2[u].push_back(y);
    }
    suf2[u].push_back(1);
    reverse(suf[u].begin(),suf[u].end());
    reverse(suf2[u].begin(),suf2[u].end());

