                x*=(suf2[u][i+1]%m)*(down[u][n-1].fi%m);
            else
                x*=suf[u][i+1];
        }
        x%=m;
        if(u!=1)
            x*=up[u]+1;
        x%=m;
        up[v]=x;
        ans[v]*=x+1;
        ans[v]%=m;
