#include <bits/stdc++.h>

using namespace std;

typedef long long ll;
#define pb push_back

ll n , m;
vector<ll> gr[100005];
ll dp1[100005], dp2[100005];

void solve1(ll node, bool vis[]) {
	vis[node] = true;
	dp1[node] = 1;
	for (ll child : gr[node]) {
		if (!vis[child]) {
			solve1(child, vis);
			dp1[node] = (dp1[node] * (1 + dp1[child])) % m;
		}
	}
}

void solve2(ll node, bool vis[], ll par_ans ) {
	vis[node] = 1;
	dp2[node] = ((1 + par_ans) * dp1[node]) % m;
	vector<ll> prefix, suffix;
	for (ll child : gr[node]) {
		if (!vis[child]) {
			prefix.pb(1 + dp1[child]);
			suffix.pb(1 + dp1[child]);
		}
	}

	reverse(suffix.begin(), suffix.end());
	for (ll i = suffix.size() - 2; i >= 0; i--) {
		suffix[i] = (suffix[i] + suffix[i + 1]) % m;
	}

	prefix[0] = prefix[0] % m;
	for (ll i = 1; i < prefix.size(); i++) {
		prefix[i] = (prefix[i] + prefix[i - 1]) % m;
	}

	ll cno = 0;
	for (ll child : gr[node]) {
		if (!vis[child]) {
			ll ways = (1 + par_ans);
			ways = (cno > 0) ? (ways * prefix[cno - 1]) : ways;
			ways = (cno < suffix.size() - 1) ? (ways * suffix[cno + 1]) : ways ;
			solve2(child, vis, ways);
			cno++;
		}
	}
}


int main() {


	ll f, s;
	cin >> n >> m;
	for (ll i = 1; i < n; i++) {
		cin >> f >> s;
		gr[f].pb(s);
		gr[s].pb(f);
	}

	bool vis[n + 1];
	memset(vis, 0 , sizeof vis);

	solve1(1, vis);
	memset(vis, 0 , sizeof vis);

	solve2(1, vis, 0);
	for (ll i = 1; i <= n; i++)
		cout << dp2[i] << endl;
	return 0;
}

