void dfs1(int u = rt, int p = 0) {
    f[u] = 1;
    loop (i, g[u].size()) {
        int v = g[u][i];
        if (v == p)  continue;
        dfs1(v, u);
        f[u] *= f[v] + 1;
        f[u] %= mod;
    }
