// Mod int
// cf. https://www.youtube.com/watch?v=1Z6ofKN03_Y
struct mint {
  ll x;
  mint(ll x = 0) : x((x + MOD) % MOD) {}
  mint& operator+= (const mint a) {
    if ((x += a.x) >= MOD) x %= MOD;
    return *this;
  }
  mint operator+ (const mint a) const {
    mint res(*this);
    return res += a;
  }
  mint& operator-= (const mint a) {
    if ((x += MOD - a.x) >= MOD) x %= MOD;
    return *this;
  }
  mint operator- (const mint a) const {
    mint res(*this);
    return res -= a;
  }
  mint& operator*= (const mint a) {
    (x *= a.x) %= MOD;
    return *this;
  }
  mint operator* (const mint a) const {
    mint res(*this);
    return res *= a;
  }
  mint pow(ll t) const {
    if (!t) { return 1; }
    mint a = pow(t >> 1);
    a *= a;
    if (t & 1) a *= *this;
    return a;
  }

  // for prime mod
  mint inv() const {
    return pow(MOD-2);
  }
  mint& operator/= (const mint a) {
    return (*this) *= a.inv();
  }
  mint operator/ (const mint a) const {
    mint res(*this);
    return res /= a;
  }
};
istream& operator>>(istream& is, const mint& a) { return is >> a.x;}
ostream& operator<<(ostream& os, const mint& a) { return os << a.x;}

vector<vector<ll>> g;
vector<mint> dp;
vector<mint> ans;

void dfs1(ll v, ll p=-1) {
  mint res(1);
  for (ll u : g[v]) {
    if (u == p) { continue; }
    dfs1(u, v);
    res *= dp[u]+1;
  }
  dp[v] = res;
}

void dfs2(ll v, ll p=-1) {
  ans[v] = 1;
  for (ll u : g[v]) {
    ans[v] *= dp[u]+1;
  }

  ll m = g[v].size();
  vector<mint> lft(m+1); // lft[i] .. [0,i)
  vector<mint> rht(m+1); // rht[i] .. [i,m)
  lft[0] = 1;
  rht[m] = 1;
  rep(i,m) {
    ll u = g[v][i];
    lft[i+1] = lft[i] * (dp[u]+1);
  }
  for (ll i = m-1; i >= 0; --i) {
    ll u = g[v][i];
    rht[i] = rht[i+1] * (dp[u]+1);
  }

  rep(i,m) {
    ll u = g[v][i];
    if (u == p) { continue; }
    dp[v] = lft[i] * rht[i+1]; // except i.
    dfs2(u, v);
  }
}

