  cin.tie(0);
  cin >> N >> M;
  adj.resize(N);
  sub.resize(N);
  lprod.resize(N);
  rprod.resize(N);
  for (int i = 0; i < N - 1; i++) {
    int x, y;
    cin >> x >> y;
    x--;
    y--;
    adj[x].push_back(y);
    adj[y].push_back(x);
  }
  solve();
}

