void mult(std::vector<int>const& ix, std::vector<uint64_t>const& tmp, int b, int e) {
  if(e-b==3) {
    dpA[ix[b+0]] *= tmp[b+1]*tmp[b+2]%M;
    dpA[ix[b+1]] *= tmp[b+0]*tmp[b+2]%M;
    dpA[ix[b+2]] *= tmp[b+1]*tmp[b+0]%M;
    dpA[ix[b+0]] %= M;
    dpA[ix[b+1]] %= M;
    dpA[ix[b+2]] %= M;
    return;
  } else if(e-b==2) {
    dpA[ix[b+0]] = dpA[ix[b+0]] * tmp[b+1] %M;
    dpA[ix[b+1]] = dpA[ix[b+1]] * tmp[b+0] %M;
    return;
  } else if(e-b==1) {
    return; // nothing to do
  }
  int mid = (b+e)/2;
  mult(ix, tmp, b, mid);
  mult(ix, tmp, mid, e);
  uint64_t p = tmp[b];
  for(int i = b+1; i < mid; ++i) p = p*tmp[i]%M;
  for(int i = mid; i < e; ++i) dpA[ix[i]] = dpA[ix[i]]*p%M;
  p = tmp[mid];
  for(int i = mid+1; i < e; ++i) p = p*tmp[i]%M;
  for(int i = b; i < mid; ++i) dpA[ix[i]] = dpA[ix[i]]*p%M;
}

uint64_t dfs(int v, int p) {
  uint64_t ret = 1;
  for(int i = 0; i < G[v].size(); ++i) {
    int c = G[v][i];
    if(c == p) continue;
    ret = ret*(1 + dfs(c, v))%M;
  }
  return dpS[v] = ret;
}

void bfs() {
  std::queue<std::pair<int, int> > q;
  q.push(std::make_pair(0, -1));
  dpA[0] = 1;
  while(q.size() > 0) {
    int v = q.front().first, p = q.front().second; q.pop();
    std::vector<int> ix;
    std::vector<uint64_t> tmp;
    ix.reserve(G[v].size());
    tmp.reserve(G[v].size());
    for(int i = 0; i < G[v].size(); ++i) {
      int c = G[v][i];
      if(c == p) continue;
      q.push(std::make_pair(c, v));
      ix.push_back(c);
      tmp.push_back(dpS[c]+1);
      dpA[c] = dpA[v];
    }
    if(ix.size() > 0) {
      mult(ix, tmp, 0, ix.size());
      for(int i = 0; i < ix.size(); ++i) ++dpA[ix[i]];
    }
  }
}

