ll n, m;
vvi g;
vi dp;

#define mod(a) (((a % m) + m) % m)

void dfs(ll u = 0, ll p = 0) {
    dp[u] = 1 % m;
    for (auto it : g[u]) {
        if (it == p) {
            continue;
        }

        dfs(it, u);
        dp[u] *= (1 + dp[it]);
        dp[u] %= m;
    }
}

void dfs2(ll u = 0, ll p = 0, ll papa = 0) {
    vi pref, suff;
    for (auto it : g[u]) {
        if (it == p) {
            pref.pb(papa);
            suff.pb(papa);
        } else {
            pref.pb(dp[it]);
            suff.pb(dp[it]);
        }
    }

    ll curr = 1 % m;
    for (auto &it : pref) {
        it = mod(curr * mod(1 + it));
        curr = it;
    }

    curr = 1;
    for (auto it = suff.rbegin(); it != suff.rend(); it++) {
        *it = mod(curr * mod(1 + *it));
        curr = *it;
    }

    curr = 0;
    for (auto it : g[u]) {
        if (it == p) {
            curr++;
            continue;
        }
        ll back = 1 % m, front = 1 % m;
        if (curr != 0) {
            back = pref[curr - 1];
        }

        if (curr != suff.size() - 1) {
            front = suff[curr + 1];
        }

        ll mult = mod(back * front);
        dp[it] *= (1 + mult);
        dp[it] %= m;

        dfs2(it, u, mult);
        curr++;
    }
}

