vector< vector<ll> > tree;
vector<ll> p,up,down;
vector<ll> extra, counter;

ll m = 1000000007 , n;

ll multi(ll a, ll b){

	ll total = ( (a%m)*(b%m) )%m;
	return total;

}

int inverse(ll a) 
{ 
    int m0 = m; 
    int y = 0, x = 1; 

    if (m == 1) 
      return 0; 

    while (a > 1) 
    { 
        // q is quotient 
        int q = a / m; 
        int t = m; 

        // m is remainder now, process same as 
        // Euclid's algo 
        m = a % m, a = t; 
        t = y; 

        // Update y and x 
        y = x - q * y; 
        x = t; 
    } 

    // Make x positive 
    if (x < 0) 
       x += m0; 

    return x; 
} 

ll calc( ll value, ll there ){

	ll a = value%m, b = down[there];

	if(b == 0){

		if( counter[there] >= 2 ){
			return 0;
		}

		if(counter[there] == 1 && a == 0){
			return extra[there];
		}
		else{
			return 0;
		}

	}

	ll c = __gcd(a,b);

	a/= c; 
	b/= c;

	return b*inverse(a); 

}

void dfs(ll here, ll father){

	p[here] = father;

	ll f = tree[here].size();

	for(ll i = 0; i < f; i++){

		if( tree[here][i] != father ){
			dfs(tree[here][i], here);
			down[here] = multi( down[here], down[ tree[here][i]] + 1 );

			if( (down[ tree[here][i]] + 1)%m != 0 ){
				extra[here] = multi( extra[here], down[ tree[here][i]] + 1 );
			}
			else{
				counter[here]++;
			}

		}

	}

}


void dfs2(ll here, ll father, ll tam){

	if( tam >= 2 ){

		ll alfa;

		if(father == 1){
			alfa = 1;
		}
		else{
			alfa = (up[here]+1)%m;

		}

		up[here] = multi( calc( down[here] +1, father ) , alfa );
		up[here] = ( up[here] + 1 )%m;

	}
	else{
		up[here] = ( up[father] + 1 ) %m;
	}


	ll f = tree[here].size();


	for(ll i = 0; i < f ; i++){

		if( tree[here][i] != father ){
			dfs2(tree[here][i], here, f);
		}
	}


}

