	ios::sync_with_stdio(0); cin.tie(0);

	ll m2;

	cin >> n >> m2;

	ll a,b;

	tree.assign(n+1, vector<ll>(0,0));
	up.assign(n+1, 1);
	down.assign(n+1,1);
	p.assign(n+1,0);
	extra.assign(n+1,1);
	counter.assign(n+1, 0);

	up[0] = 0;

	for(ll i = 1; i < n; i++){
		cin >> a >> b;
		tree[a].PB(b);
		tree[b].PB(a);
	}

	tree[0].PB(1);

	dfs(1,0);
	dfs2(1,0,1);


	for(ll i = 1; i <= n; i++){
 		cout  << multi( up[i], down[i] )%m2 << endl;
	}

	return 0;
}

