#define MAXN 550000

ll n,m;
vector<vector<int>> edges(MAXN, vector<int>());
ll dp1[MAXN];
ll dp2[MAXN];

ll dfs1(int n, int p=-1){
  ll r=1;
  for(auto c: edges[n]){
    if(c==p)continue;
    r *= dfs1(c, n);
    r %= m;
  }
  dp1[n] = r+1;
  return dp1[n];
}

void dfs2(int now, int p=-1){
  if(p==-1)dp2[now]=1;

  int ec = edges[now].size();
  ll pr=1;
  vector<ll> lprod;
  rep(i, ec){
    ll c = edges[now][i];
    if(c==p){
      lprod.push_back(pr);
      continue;
    }
    pr *= dp1[c];
    pr %= m;
    lprod.push_back(pr);
  }

  pr=1;
  vector<ll> rprod;
  rrep(i, ec){
    ll c = edges[now][i];

    if(c==p){
      rprod.insert(rprod.begin(), pr);
      continue;
    }
    pr *= dp1[c];
    pr %= m;
    rprod.insert(rprod.begin(), pr);
  }

  rep(i, ec){
    ll c = edges[now][i];
    if(p==c)continue;
    dp2[c] = dp2[now];
    if(i)dp2[c] *= lprod[i-1];
    dp2[c] %= m;
    if(i<ec-1)dp2[c] *= rprod[i+1];
    dp2[c] %= m;
    dp2[c]++;
    dp2[c] %= m;
    dfs2(c, now);

  }
}

vector<ll>ans(MAXN);
void dfs3(int now, int p=-1){
  ans[now] = dp2[now];
  for(auto c:edges[now]){
    if(c==p)continue;

    ans[now] = ans[now]*dp1[c]%m;
    dfs3(c, now);
  }
}

