typedef long long ll;
const ll M = 1e5 + 50;
ll dp[M], dp1[M], mod, n;
vector<ll> graph[M], pre[M], post[M];
void read_graph(){
    for(int i = 0; i < n-1; i++){
        int a, b;
        cin >> a >> b;
        a--, b--;
        graph[a].push_back(b);
        graph[b].push_back(a);
    }
}
void dfs(ll node, ll par){
    dp[node] = 1;
    for(auto child : graph[node]){
        if(child != par){
            dfs(child, node);
            dp[node] *=( dp[child] + 1LL);
            dp[node] %= mod;
        }
    }
    if(par!= -1)pre[par].push_back(dp[node] + 1);   
}
void dfs2(ll node, ll par){
    int c = 0;
    for(auto child : graph[node]){
        if(child != par){
            dp1[child] = (dp1[node]+1)%mod;
            if(c > 0)dp1[child] = (dp1[child]*pre[node][c-1])%mod;
            if(post[node].size() - 1LL  != c)dp1[child] = (dp1[child]*post[node][post[node].size() - 2 - c])%mod;
            dp[child] *= (dp1[child]+1)%mod, dp[child] %= mod;
            dfs2(child, node);
            c++;
        }
    }
}
int main()
{
    cin >> n >> mod;
    read_graph();
    dfs(0LL, -1LL);
    for(ll i = 0; i < n; i++){
        if(pre[i].size() != 0){
            for(ll j = pre[i].size()-1; j >= 0; j--)post[i].push_back(pre[i][j]);
            for(int j = 1; j < pre[i].size(); j++){
                pre[i][j] = (pre[i][j]*pre[i][j-1])%mod;
                post[i][j] = (post[i][j]*post[i][j-1])%mod;
            }
        }
    }
    dfs2(0LL, -1LL);
    for(int i = 0; i < n; i++)cout << dp[i] << endl;
}

