void dfs1(int u, int p) {
    for (int v : tree[u]) {
        if (v == p) {
            continue;
        }
        dfs1(v, u);
        dp[u] = (dp[u] * (dp[v] + 1)) % M;
    }
}

void dfs2(int u, int p, int pval) {
    ans[u] = dp[u];
    if (p != -1) {
        ans[u] = (ans[u] * (pval + 1)) % M;
    }
    for (int v : tree[u]) {
        if (v == p) {
            continue;
        }
        int uval = ans[u] / (dp[v] + 1);
        dfs2(v, u, uval);
    }
}

