#include <bits/stdc++.h>

using namespace std;

using ll = long long;

int N, MOD;
vector<vector<int>> adj;

vector<vector<int>> dp;
vector<int> sz;

void Dfs(const int p, const int v) {
    dp[v] = {0, 1};
    sz[v] = 1;

    for (int u : adj[v]) {
        if (u == p) continue;
        Dfs(v, u);

        vector<int> sub(sz[v] + sz[u] + 1);
        for (int i = 1; i <= sz[v]; ++i)
            for (int j = 0; j <= sz[u]; ++j)
                (sub[i + j] += dp[v][i] * dp[u][j]) %= MOD;

        dp[v] = move(sub);
        sz[v] += sz[u];
    }
    dp[v][0] = 1;
}

int main() {
    cin.tie(0); ios::sync_with_stdio(false);

    cin >> N >> MOD;
    adj.resize(N);
    for (int i = 0, x, y; i + 1 < N; ++i) {
        cin >> x >> y;
        adj[x - 1].push_back(y - 1);
        adj[y - 1].push_back(x - 1);
    }

    if (1e7 <= N * N) return 0;

    dp.resize(N);
    sz.resize(N);
    for (int v = 0; v < N; ++v) {
        for (int u = 0; u < N; ++u) dp[v].clear();
        fill(sz.begin(), sz.end(), 0);
        Dfs(-1, v);

        int res = 0;
        for (int i = 1; i <= N; ++i)
            (res += dp[v][i]) %= MOD;
        cout << res << '\n';
    }

    return 0;
}

