int n, m;
vector<vector<int>> edge;

vector<bool> isVisited;
vector<int64_t> dp1, dp2;
void dfs1(int node)
{
    isVisited[node] = true;
    dp1[node] = 1;

    for (int e : edge[node]) {
        if (!isVisited[e]) {
            dfs1(e);
            dp1[node] *= dp1[e] + 1;
            dp1[node] %= m;
        }
    }
}

void dfs2(int node, int64_t p)
{
    isVisited[node] = true;
    dp2[node] = (p + 1) * dp1[node] % m;

    int n = edge[node].size();
    vector<int64_t> tmp(n + 1), rtmp(n + 1);
    tmp[0] = rtmp[n] = 1;

    rep(i, n)
    {
        int e = edge[node][i];
        if (isVisited[e]) {
            tmp[i + 1] = tmp[i];
        } else {
            tmp[i + 1] = tmp[i] * (dp1[e] + 1);
            tmp[i + 1] %= m;
        }

        int re = edge[node][n - 1 - i];
        if (isVisited[re]) {
            rtmp[n - 1 - i] = rtmp[n - i];
        } else {
            rtmp[n - 1 - i] = rtmp[n - i] * (dp1[re] + 1);
            rtmp[n - 1 - i] %= m;
        }
    }

    rep(i, n)
    {
        int e = edge[node][i];
        if (!isVisited[e]) {
            dfs2(e, tmp[i] * rtmp[i + 1] % m * (p + 1) % m);
        }
    }
}

