ll solve() {
    ll N, M, x, y;
    cin >> N >> M;
    vector<vector<ll>> G(N);
    for ( int i = 0; i < N-1; i++ ) {
        cin >> x >> y;
        x--, y--;
        G[x].push_back(y);
        G[y].push_back(x);
    }
    auto Add = [&](ll& x, ll y) { x = ( x % M + y % M ) % M; };
    auto Mul = [&](ll& x, ll y) { x = ( x % M * y % M ) % M; };
    vector<map<int,ll>> dp(N);

    function<void(int,int)> dfs1 = [&](int v, int p) {
        ll c = 1;
        for ( int u : G[v] ) {
            if ( u == p ) continue;
            dfs1(u, v);
            Mul(c, dp[v][u]);
        }
        Add(c, 1);
        if ( p >= 0 ) {
            dp[p][v] = c;
        }
    };
    dfs1(0,-1);

    function<void(int,int)> dfs2 = [&](int v, int p) {
        int vn = G[v].size();
        vector<ll> pl(vn,1), pr(vn,1);
        int i;
        i = 0;
        for ( auto it = G[v].begin(); it != G[v].end(); it++, i++ ) {
            if ( i > 0 ) Mul(pl[i], pl[i-1]);
            Mul(pl[i], dp[v][*it]);
        }
        i = vn-1;
        for ( auto it = G[v].rbegin(); it != G[v].rend(); it++, i-- ) {
            if ( i < vn-1 ) Mul(pr[i], pr[i+1]);
            Mul(pr[i], dp[v][*it]);
        }
        i = 0;
        for ( auto it = G[v].begin(); it != G[v].end(); it++, i++ ) {
            int u = *it;
            if ( u == p ) continue;
            ll c = 1;
            if ( i > 0 ) Mul(c, pl[i-1]);
            if ( i < G[v].size() - 1 ) Mul(c, pr[i+1]);
            Add(c, 1);
            dp[u][v] = c;
            dfs2(u, v);
        }
    };
    dfs2(0,-1);

    for ( int v = 0; v < N; v++ ) {
        ll c = 1;
        for ( int u : G[v] ) {
            Mul(c, dp[v][u]);
        }
        cout << c << "\n";
    }
    return 0;
}

