vector<long long> memo_l[100005];
vector<long long> memo_r[100005];
long long ans[100005];
int N, M;

long long dfs(int v, int parent) {
    memo_l[v].resize(G[v].size()+2, 1);
    memo_r[v].resize(G[v].size()+2, 1);
    for (int i = 0; i < G[v].size(); i++) {
        int child = G[v][i];
        if (child == parent) continue;

        memo_l[v][i+1] = (dfs(child, v) + 1) % M;
    }
    for (int i = G[v].size(); i > 0; i--) {
        memo_r[v][i] = memo_l[v][i] * memo_r[v][i+1] % M;
    }
    for (int i = 1; i <= G[v].size(); i++) {
        memo_l[v][i] = memo_l[v][i] * memo_l[v][i-1] % M;
    }
    return memo_r[v][1];
}

void calc_ans(int v, int parent, long long parent_res) {
    ans[v] = (parent_res + 1) * memo_r[v][1] % M;
    for (int i = 0; i < G[v].size(); i++) {
        int child = G[v][i];
        if (parent == child) continue;

        calc_ans(child, v, memo_l[v][i] * memo_r[v][i+2] * (parent_res + 1) % M);
    }
}



