void dfs1(int u, int p) {
    int n = tree[u].size();
    for (int i = 0; i < n; i++) {
        int v = tree[u][i];
        if (v == p) {
            continue;
        }
        dfs1(v, u);
        dp[u] = (dp[u] * (dp[v] + 1)) % M;
    }
    for (int i = 0; i < n; i++) {
        int v = tree[u][i];
        if (v == p) {
            if (i == 0) {
                L[u].push_back(1);
            } else {
                L[u].push_back(L[u].back());
            }
        } else {
            if (L[u].size() == 0) {
                L[u].push_back(dp[v] + 1);
            } else {
                L[u].push_back((L[u].back() * (dp[v] + 1)) % M);
            }
        }
    }
    for (int i = n - 1; i >= 0; i--) {
        int v = tree[u][i];
        if (v == p) {
            if (i == n - 1) {
                R[u].push_back(1);
            } else {
                R[u].push_back(R[u].back());
            }
        } else {
            if (R[u].size() == 0) {
                R[u].push_back(dp[v] + 1);
            } else {
                R[u].push_back((R[u].back() * (dp[v] + 1)) % M);
            }
        }
    }
    reverse(R[u].begin(), R[u].end());
}

void dfs2(int u, int p, int pval) {
    // cout << u + 1 << " " << p + 1 << " " << pval << endl;
    ans[u] = (dp[u] * (pval + 1)) % M;

