    for (int i = 0; i < n; i++) {
        int v = tree[u][i];
        if (v == p) {
            continue;
        }
        int uval = (pval + 1) % M;
        if (i > 0) {
            uval = (uval * L[u][i - 1]) % M;
        }
        if (i < n - 1) {
            uval = (uval * R[u][i + 1]) % M;
        }
        dfs2(v, u, uval);
    }
}

