std::vector<int> adj[N+1];
ll cnt[N+1] = {0};
ll dp[N+1];
bool visited[N+1] = {false};

void dfs(int node, int m){
    visited[node] = true;
    cnt[node] =1;

    for(auto child : adj[node]){
        if(!visited[child]){
            dfs(child, m);
            cnt[node] *= cnt[child]+1;
            cnt[node] %= m;
        }
    }
}

void cal_ways(int node, ll parent_cnt, int parent, int m){
    dp[node] = (cnt[node]*(parent_cnt+1))%m;
    // cout<<node<<" ";
    queue<ll> prefix;
    stack<ll> suffix;
    prefix.push(1);
    suffix.push(1);
    ll temp = 1;
    for (int i = 0; i < adj[node].size(); ++i)
    {
        if(adj[node][i]!=parent){
            temp *= cnt[adj[node][i]]+1;
            temp %= m;
            prefix.push(temp);
        }
    }
    temp = 1;
    for (int i = adj[node].size()-1; i >= 0; --i)
    {
        if(adj[node][i]!=parent){
            temp *= cnt[adj[node][i]]+1;
            temp %= m;
            suffix.push(temp);
        }
    }
    suffix.pop();

    for(auto child : adj[node]){
        if(child!= parent){
            ll t = parent_cnt+1;
            t = (t*prefix.front())%m;
            t = (t*suffix.top())%m;
            cal_ways(child, t, node, m);
            prefix.pop();
            suffix.pop();
        }
    }
}


