LL dfs1(int v, int p = -1) {
  LL ret = 1;
  for (int i = 0; i < G[v].size(); ++i) {
    int u = G[v][i];
    if (u == p) continue;
    dp[v][i] = dfs1(u, v);
    ret = (ret * (dp[v][i] + 1)) % M;
  }
  return ret;
}

void dfs2(int v, int p = -1, LL add = 0) {
  int n = G[v].size();
  if (n == 0) return;
  for (int i = 0; i < n; ++i) {
    int u = G[v][i];
    if (u == p) {
      dp[v][i] = add;
      break;
    }
  }

  vector<LL> L(n), R(n);
  L[0] = dp[v][0] + 1LL;
  R[n-1] = dp[v][n-1] + 1LL;

  for (int i = 1; i < n; ++i) {
    L[i] = ((dp[v][i] + 1LL) * L[i-1]) % M;
  }
  for (int i = n - 2; i >= 0; --i) {
    R[i] = ((dp[v][i] + 1LL) * R[i+1]) % M;
  }

  for (int i = 0; i < n; ++i) {
    int u = G[v][i];
    if (u == p) continue;

    LL x = 1;
    if (i != 0) x = (x * L[i-1]) % M;
    if (i != n - 1) x = (x * R[i+1]) % M;
    dfs2(u, v, x);
  }
}

