constexpr int INF = (1<<30);
constexpr ll INFLL = 1LL<<62;
constexpr long double EPS = 1e-12;

ll N;
ll M;
ll MAX=10E+5;
vvll edge(MAX);
vector<vector<bool>> flag(MAX);
vvll black(MAX);
vvll gray(MAX);
vll cnt(MAX, 0);

void search(ll pre, ll index){
  if(flag[pre][index]) return;
  flag[pre][index] = true;
  black[pre][index] = 1;
  gray[pre][index] = 0;
  ll pos = edge[pre][index];
  for(int i=0; i<edge[pos].size(); ++i){
    if(edge[pos][i]==pre) continue;
    if(black[pos][i]<0 && gray[pos][i]<0) search(pos, i);
    black[pre][index] *= (black[pos][i]+1);
    gray[pre][index] += gray[pos][i];
    black[pre][index] %= M;
    gray[pre][index] %= M;
  }
  gray[pre][index] += black[pre][index]-1;
  gray[pre][index] %= M;
  return;
}

