    cin >> x >> y;
    edge[x-1].push_back(y-1);
    edge[y-1].push_back(x-1);
    cnt[x-1]++;
    cnt[y-1]++;
  }

  rep(i, 0, N){
    vll tmp(cnt[i], -1);
    black[i] = tmp;
    gray[i] = tmp;
    vector<bool> tmp_flag(cnt[i], false);
    flag[i] = tmp_flag;
  }

  rep(i, 0, N){
    ll ans = 1;
    for(int j=0; j<edge[i].size(); ++j){
      search(i, j);
      ans *= (black[i][j]+1);
      ans %= M;
    }
    cout << ans << "\n";
  }

  return 0;
}

