		a--; b--;
		G[a].push_back(Edge{ a, b, 1 });
		G[b].push_back(Edge{ b, a, 1 });
	}

	solve1(G, 0, -1, M);
	solve2(G, 0, -1, 1, M);

	rep(i, N) {
		cout << ans[i] << endl;
	}
}

