template <typename Tp>
class mul_monoid {
public:
  using value_type = Tp;

private:
  value_type M_x;

public:
  mul_monoid() = default;  // identity
  mul_monoid(value_type x): M_x(x) {}

  mul_monoid& operator +=(mul_monoid that) { M_x *= that.M_x; return *this; }
  mul_monoid operator +(mul_monoid const& that) const { return mul_monoid(*this) += that; }

  value_type const& get() const { return M_x; }
};

