vector <int> G[N];

int dp[N];
int wynik[N];
vector <int> dzieci[N];
vector <int> iloL[N];
vector <int> iloR[N];

void dfs0(int v, int p) {
    for (int u : G[v]) {
        if (u != p) {
            dfs0(u, v);
        }
    }

    long long pom = 1;
    for (int u : G[v]) {
        if (u != p) {
            pom = (pom * (dp[u] + 1)) % mod;
        }
    }

    dp[v] = pom;
}

void dfs1(int v, int p, int gora) {
    wynik[v] = (1ll * dp[v] * (gora + 1)) % mod;
    for (int u : G[v]) {
        if (u != p) {
            dzieci[v].push_back(u);
        }
    }

    iloL[v].resize(dzieci[v].size());
    iloR[v].resize(dzieci[v].size());
    int ile = dzieci[v].size();
    for (int i = 0; i < ile; ++i) {
        long long rr = dp[dzieci[v][i]] + 1;
        if (i > 0) rr = (rr * iloL[v][i - 1]) % mod;
        iloL[v][i] = rr;
    }
    for (int i = ile - 1; i >= 0; --i) {
        long long rr = dp[dzieci[v][i]] + 1;
        if (i + 1 < ile) rr = (rr * iloR[v][i + 1]) % mod;
        iloR[v][i] = rr;
    }

    for (int i = 0; i < ile; ++i) {
        long long pom = gora + 1;
        if (i > 0) pom = (pom * iloL[v][i - 1]) % mod;
        if (i + 1 < ile) pom = (pom * iloR[v][i + 1]) % mod;
        dfs1(dzieci[v][i], v, pom);
    }
}

