unordered_map<Int, Int> sub;
Int N, M;
std::vector<vector<int>> adj;

Int dfs(int node, int parent) {
  if (parent >= 0) {
    auto it = sub.find(static_cast<Int>(node) * N + parent);
    if (it != sub.end()) {
      return it->second;
    }
  }
  Int r = 1;
  for (int child : adj[node]) {
    if (child == parent) continue;
    r = r * (1 + dfs(child, node)) % M;
  }
  if (parent >= 0) {
    sub[static_cast<Int>(node) * N + parent] = r;
  }
  return r;
};

