vector<int> rht[limit];

//Appropriately Changed
void add_edge(int from, int to) {
	graph[from].push_back(to);
	graph[to].push_back(from);
}

map<int,int> dp[limit];

void dfs(int v,int p){
	if(dp[v].find(p) != end(dp[v])) return;
	int res = 1LL;
	rep(i,graph[v].size()){
		const int to = graph[v][i];
		if(to == p) continue;
		dfs(to, v);
		const int tmp = (dp[to][v] + 1) % m;
		res = 1LL * res * tmp % m;
	}
	dp[v][p] = res;
}

void memo_compute(int v){
	//error(v);
	const int l = graph[v].size();
	lft[v].resize(l);
	rht[v].resize(l);

	int cur = 1;
	rep(i,l){
		const int to = graph[v][i];
		const int tmp = (dp[to][v] + 1) % m;
		cur = 1LL * cur * tmp % m;
		lft[v][i] = cur;
	}

	cur = 1;
	rrep(i,l){
		const int to = graph[v][i];
		const int tmp = (dp[to][v] + 1) % m;
		cur = 1LL * cur * tmp % m;
		rht[v][i] = cur;
	}
}


void dfs2(int v,int p){
	if(p != -1) {
		const int idx = getidx(graph[p],v);
		const int l = graph[p].size();
		ll res = 1LL;
		if(idx - 1 >= 0) res = res * lft[p][idx - 1] % m;
		if(idx + 1 <  l) res = res * rht[p][idx + 1] % m;
		dp[p][v] = res;
	}

	memo_compute(v);

	rep(i,graph[v].size()){
		const int to = graph[v][i];
		if(to == p) continue;
		dfs2(to, v);
	}
}

