const int N = 1e5 + 10;
ll mod, dp[N][2], ans[N];
VI e[N];

void dfs(int now, int past){
    dp[now][0] = dp[now][1] = 1;
    for (int next : e[now]){
        if (next == past) continue;
        dfs(next, now);
        dp[now][0] = (dp[now][0] * dp[next][0]) % mod;
        dp[now][1] = (dp[now][1] * (dp[next][0] + dp[next][1])) % mod;
    }
}

void dfs2(int now, int past, ll s){
    VL tmp;
    for (int next : e[now]){
        if (next == past) continue;
        tmp.push_back((dp[next][0] + dp[next][1]) % mod);
    }
    int m = tmp.size();
    VL pl(m + 1, 1), pr(m + 1, 1);
    REP(i,m){
        pl[i + 1] = (pl[i] * tmp[i]) % mod;
    }
    FORR(i,m-1,0){
        pr[i] = (pr[i+1] * tmp[i]) % mod;
    }
    int i = 0;
    REP(j,e[now].size()){
        int next = e[now][j];
        if (next == past) continue;
        ll ss = s;
        ss = (ss * pl[i]) % mod;
        ss = (ss * pr[i + 1] + 1) % mod;
        ans[next] = (dp[next][1] * ss) % mod;
        dfs2(next, now, ss);
        i++;
    }
}

