void solve(){
  ll n,m; cin>>n>>m;
  vector<vector<ll>> E(n);
  rep(_,n-1){
    ll x,y; cin>>x>>y;
    --x; --y;
    E[x].push_back(y);
    E[y].push_back(x);
  }

  // 木DP (0-rooted)
  vector<ll> dp(n,1);
  function<void(ll,ll)> dfs1=[&](ll v,ll p){
    foreach(nv,E[v]){
      if(nv==p) continue;
      dfs1(nv,v);
      dp[v]*=dp[nv]+1;
      dp[v]%=m;
    }
  };
  dfs1(0,-1);

  // 全方位木DP
  vector<ll> ans(n,1);
  function<void(ll,ll)> dfs2=[&](ll v,ll p){
    foreach(nv,E[v]){
      ans[v]*=dp[nv]+1;
      ans[v]%=m;
    }
    ll k=E[v].size();
    vector<ll> l(k),r(k);
    rep(i,k) l[i]=r[i]=dp[E[v][i]]+1;
    rep(i,1,k){
      l[i]*=l[i-1];
      l[i]%=m;
    }
    rep(i,k-2,-1,-1){
      r[i]*=r[i+1];
      r[i]%=m;
    }
    ll tmp=dp[v];
    rep(i,k){
      ll nv=E[v][i];
      if(nv==p) continue;
      dp[v]=1;
      if(i>0) dp[v]*=l[i-1];
      if(i<k-1) dp[v]*=r[i+1];
      dp[v]%=m;
      dfs2(nv,v);
    }
    dp[v]=tmp;
  };
  dfs2(0,-1);

  rep(i,n) cout<<ans[i]<<"\n";
}

