long long modz(long long x, long long y)
{
	if(x + y >= MOD)
	{
		return x+y-MOD;
	}
	return x+y;
}
long long f(int poz, int p)
{
	if(p != -1)
	{
		if(m[make_pair(poz, p)] != -1)
		{
			return m[make_pair(poz, p)];
		}
    }
	long long u = 1;
	for(int i = 0; i < s[poz].size(); i++)
	{
		if(s[poz][i] != p)
		{
			u *= f(s[poz][i], poz);
			u %= MOD;
		}
	}
	if(p != -1)
	{
		return m[make_pair(poz, p)] = modz(u, 1);
	}
	else
	{
		return u;
	}
}
