void dfs(int node, int parent) {

    long long cur = 1;
    long long ss  = 1;

    for(auto ch: edge[node]) {
        if(ch != parent) {
            dfs(ch, node);
            cur += cur*dp[ch];
            cur %= m;
        }
    }
    dp[node] = cur ;
}

void dfs2(int node, int parent, long long value) {

    // cout << node << " " << parent << " -- ";

    long long cur = 1;

    vector<int> childs;

    long long total = 0;

    for(auto ch: edge[node]) {
        if(ch == parent) continue;
        childs.push_back(ch);
    }

    total = dp[node] + dp[node] * value;

    total %= m;
    if(childs.size() == 0) {
        ans[node] = total;
        return;
    }



    long long curdp[childs.size() + 1];
    long long rightdp[childs.size() ];
    curdp[0] = value + 1;

    for(int j = 0; j < childs.size(); ++j) {
        curdp[j+1] = curdp[j] + curdp[j] * dp[childs[j]];
        curdp[j+1] %= m;
    }
    rightdp[childs.size()-1] = dp[childs[childs.size()-1]] + 1;

    for(int j = childs.size()-2; j >= 0; --j) {
        rightdp[j] = rightdp[j+1] + rightdp[j+1] * dp[childs[j]];
        rightdp[j] %= m;
    }

    for(int i = 0; i < childs.size(); ++i) {
        cur = curdp[i] * dp[childs[i]];
        cur %= m;
        if(i < childs.size()-1) {
            cur = ((rightdp[i+1] * curdp[i])%m) * dp[childs[i]];
            cur %= m;

        }
        cur = total - cur;
        cur %= m;
        // cout << childs[i] << " " << node << " " << cur << "\n";
        dfs2(childs[i], node, cur);
    }


    ans[node] = total;
    ans[node] %= m;

}


