// dp[v] := 頂点 0 を根とした根付き木において、頂点 v を黒く塗ったときの
//          頂点 v 以下の部分木の塗り方
vector<ll> dp;

// Rerooting[v] := 頂点 v を根としたときに、頂点 v を黒に塗る塗り方
vector<ll> Rerooting;

// 頂点 v 以下の部分木の子ノードの dp 値の順方向の累積積
vector<vector<ll>> Prefix_Cumulative_Product;
// 頂点 v 以下の部分木の子ノードの dp 値の逆方向の累積積
vector<vector<ll>> Suffix_Cumulative_Product;

// 頂点 0 を根付き木として、dp テーブルを埋める
ll memo_rec(int from = 0, int p = -1){
    if(dp[from] != -1)  return dp[from];

    ll res = 1;
    for(int i = 0; i < graph[from].size(); ++i){
        int to = graph[from][i];
        if(to == p) continue;
        res *= (memo_rec(to, from) + 1);
        res %= m;
    }

    return dp[from] = res;
}

// Rerooting によって、全頂点における解を求める
void dfs(int from = 0, int p = -1){
    if(p == -1) Rerooting[from] = dp[from];

    // 子のうち何番目の頂点か (累積積を用いるときに必要)
    int now = Prefix_Cumulative_Product[from].size();
    // 累積積の構築 (親があれば、親を 0 番目にしておく)
    for(int to : graph[from]){
        if(to == p) continue;
        Prefix_Cumulative_Product[from].push_back(dp[to] + 1);
    }
    int sz = Prefix_Cumulative_Product[from].size();
    Suffix_Cumulative_Product[from].resize(sz);
    for(int i = 0; i < sz; ++i){
        Suffix_Cumulative_Product[from][i] = Prefix_Cumulative_Product[from][i];
    }
    for(int i = 0; i + 1 < sz; ++i){
        Prefix_Cumulative_Product[from][i + 1] *= Prefix_Cumulative_Product[from][i];
        Prefix_Cumulative_Product[from][i + 1] %= m;
    }
    for(int i = sz - 1; i > 0; --i){
        Suffix_Cumulative_Product[from][i - 1] *= Suffix_Cumulative_Product[from][i];
        Suffix_Cumulative_Product[from][i - 1] %= m;
    }

    for(int i = 0; i < graph[from].size(); ++i){
        int to = graph[from][i];
        if(to == p) continue;

        // to から見た親方向の部分木の塗り方
        ll cnt = 1;
        if(now > 0){
            cnt *= Prefix_Cumulative_Product[from][now - 1];
            cnt %= m;
        }
        if(now + 1 < sz){
            cnt *= Suffix_Cumulative_Product[from][now + 1];
            cnt %= m;
        }

        Rerooting[to] = dp[to] * (cnt + 1) % m;
        Prefix_Cumulative_Product[to].push_back(cnt + 1);
        ++now;

        dfs(to, from);
    }

    return;
}

int main(){
