typedef long long ll;typedef vector<int> vi;typedef pair<int,int> pi;const int inf = (int)1e9;const double INF = 1e12, EPS = 1e-9;

int n, mod, ans[100010];
map<pi, int> dp;
vector<vi> e;

int rec(int c, int p){
	if(dp.count(pi(c, p))) return dp[pi(c, p)];
	int res = 1;
	for(int i : e[c]) if(i != p){
		int x = rec(i, c);
		res = res * (x + 1ll) % mod;
	}
	return dp[pi(c, p)] = res;
}
void rec2(int c, int p){
	if(c == p){
		ans[c] = rec(c, p);
	}
	else{
		int x = rec(c, p);
		int y = rec(p, c);
		ans[c] = x * (y + 1ll) % mod;
	}
	for(int i : e[c]) if(i != p) rec2(i, c);
}

