using PM = pair<LL, LL>;
int N;
LL MOD;
vector<int> G[100000];

map<PP, PM> memo;
PM DP(int from, int prev) {
	if (memo.count(PP(from, prev))) return memo[PP(from, prev)];

	PM ret(1, 1);
	for (int to : G[from]) {
		if (to == prev) continue;
		PM p = DP(to, from);

		ret.first *= p.first;
		ret.second *= p.first + p.second;
		ret.first %= MOD;
		ret.second %= MOD;
	}

	return memo[PP(from, prev)] = ret;
}

