int M;

struct mint {
    int n;
    mint(int n_ = 0) : n(n_) {}
};

mint operator+(mint a, mint b) { a.n += b.n; if (a.n >= M) a.n -= M; return a; }
mint operator-(mint a, mint b) { a.n -= b.n; if (a.n < 0) a.n += M; return a; }
mint operator*(mint a, mint b) { return (long long)a.n * b.n % M; }
mint &operator+=(mint &a, mint b) { return a = a + b; }
mint &operator-=(mint &a, mint b) { return a = a - b; }
mint &operator*=(mint &a, mint b) { return a = a * b; }

int N;
mint dp0[100000];
mint dp1[100000];
vector<int> G[100000];
mint ans[100000];

void dfs(int u, int p) {
    dp0[u] = 1;
    dp1[u] = 1;
    for (int v : G[u]) if (v != p) {
        dfs(v, u);
        dp0[u] *= dp0[v];
        dp1[u] *= dp0[v] + dp1[v];
    }
}

void dfs2(int u, int p) {
    const int m = G[u].size();
    vector<mint> L0(m + 1, 1);
    vector<mint> L1(m + 1, 1);
    vector<mint> R0(m + 1, 1);
    vector<mint> R1(m + 1, 1);
    for (int i = 0; i < m; i++) {
        int v = G[u][i];
        L0[i + 1] = L0[i] * dp0[v];
        L1[i + 1] = L1[i] * (dp0[v] + dp1[v]);
    }
    for (int i = m - 1; i >= 0; i--) {
        int v = G[u][i];
        R0[i] = R0[i + 1] * dp0[v];
        R1[i] = R1[i + 1] * (dp0[v] + dp1[v]);
    }
    ans[u] = L1[m];
    for (int i = 0; i < m; i++) {
        int v = G[u][i];
        if (v == p) continue;
        dp0[u] = L0[i] * R0[i + 1];
        dp1[u] = L1[i] * R1[i + 1];
        dfs2(v, u);
    }
}

