    scanf("%d %d", &N, &M);
    for (int i = 0; i < N - 1; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        u--;
        v--;
        G[u].push_back(v);
        G[v].push_back(u);
    }
    dfs(0, -1);
    dfs2(0, -1);
    for (int i = 0; i < N; i++) {
        printf("%d\n", ans[i].n);
    }
    return 0;
}

