// parent/down[cur_node]
/* 
 * maintain array that stores down of all children and the parent
 * base: if parent is 1 --> array[parent][cur_node] = down[children]/down[cur_node]
 * for other cases array[parent][cur_node] = down[children]/down[cur_node] * array[grand_parent][parent]
 */

const int nax = 1e5+5;
ll down[nax], up[nax];
int n, M;
pii parent[nax];
vvi e(nax);
vector<vl> children(nax);

ll mul(ll a, ll b){return a*b % M;}
ll add(ll a, ll b){return (a+b) % M;}

void black(int cur_node, int last_node)
{
	ll &ans = down[cur_node];
	ans = 1;
	int s = sz(e[cur_node]);
	loop(i, s)
	{
		int it = e[cur_node][i];
		if(it == last_node) continue;
		parent[it] = mkp(cur_node, i);
		black(it, cur_node);
		ans = mul(ans, down[it] +1);
	}
	children[cur_node].resize(s+1);
}

void adjust(int cur_node, int last_node)
{
	// calculate children
	int s = sz(e[cur_node]);
	vl L(s+1), R(s+1);
	loop(i, s)
	{
		L[i] = add(down[e[cur_node][i]],1);
		if(e[cur_node][i] == last_node) L[i] = 1;
		if(i) L[i] = mul(L[i], L[i-1]);
		R[s-i-1] = add(down[e[cur_node][s-i-1]],1);
		if(e[cur_node][s-i-1] == last_node) R[s-i-1] = 1;
		if(i) R[s-i-1] = mul(R[s-i-1], R[s-i]);
	}

	// parent/down[cur_node] ..
	ll adjusted_parent = 1;
	if(cur_node != 1)
	{
		int index = parent[cur_node].ss;
		adjusted_parent = children[last_node][index];
	}

	loop(i, s)
	{
		int it = e[cur_node][i];
		if(it == last_node) continue;

		ll l = i ? L[i-1]:1, r = (i != s-1) ? R[i+1]:1;

		int children_index = parent[it].ss; 
		children[cur_node][children_index] = add(mul(mul(l, r), adjusted_parent), 1);
		up[it] = mul(down[it], children[cur_node][children_index]);
		adjust(it, cur_node);
	}
}
