/**
    we have to re-root the tree, as for every node, we will have to print out the
    numbers of way to paint the tree. As the root is colored black, and every black
    nodes must be connected, we define F[u] : numbers of ways to color the subtree of u
    if node u is black, then the answer for each 'node' is F['node'] after the re-root

    If we only have to output the answer for only a node, the dp works like this
    F[u] = product of (F[v] + 1) for each direct-child v of u
           F[v] : numbers of ways to color the subtree black and
           1    : leave it white

    now, back to the actual problem
    We define G[u] : numbers of ways to colors the nodes out side of u's subtree with
    the direct parent of u is colored black
    So the answer for a 'node' is F['node'] * (G['node'] + 1)
    G[u] can be calculated as folows :
    G[u] = (G[p] + 1) * product of (F[v] + 1) with all v as direct-child of p and v!=u
    this can be done O(n) by using partial product
*/

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

using tpl = tuple<int, int, int>;
typedef pair<int,int> pii;
typedef pair<ll,ll> pll;

void fastStream(){cin.tie(0);std::ios_base::sync_with_stdio(0);}


int N;
int mod;
pii es[100010];
vector<pii> G[100010];
ll dp[100010][2];

ll rec(int edge_idx, int edge_ang){ // edge_ang : 0ならedgeのfirstが現在の場所
    if(dp[edge_idx][edge_ang] >= 0) return dp[edge_idx][edge_ang];
    ll res = 0;
    pii e = es[edge_idx];
    const int pos = edge_ang == 0 ? e.first : e.second;
    const int par = edge_ang == 1 ? e.first : e.second;
    // 現在の頂点を黒で塗る場合
    {
        ll tmp = 1;
        for(pii p : G[pos]){
            int to = p.first;
            int nedge_idx = p.second;
            int nedge_ang = (es[nedge_idx].first == pos);
            if(to == par) continue;
            (tmp *= rec(nedge_idx, nedge_ang)) %= mod;
        }        
        (res += tmp) %= mod;
    }
    // 白で塗る場合
    (res += 1) %= mod;
    return dp[edge_idx][edge_ang] = res;
}


int main() {

    cin >> N >> mod;
    for(int i = 0; i < N - 1; i++){
        int x, y;
        cin >> x >> y;
        x--; y--;
        es[i] = pii(x, y);
        G[x].push_back(pii(y, i));
        G[y].push_back(pii(x, i));
    }

    memset(dp, -1, sizeof(dp));
    for(int i = 0; i < N; i++){
        ll ans = 0;
        // 現在の頂点を黒で塗る場合
        {
            ll tmp = 1;
            // 各方向の値を掛け算する
            for(pii p : G[i]){
                int nedge_idx = p.second;
                int nedge_ang = (es[nedge_idx].first == i);
                (tmp *= rec(nedge_idx, nedge_ang)) %= mod;
            }
            (ans += tmp) %= mod;
        }
        cout << ans << endl;
    }

    return 0;
}

