vector<ll> tree[100010];
ll dp[100010] = {};
ll N,M;
ll ans[100010] = {};
ll power(ll x, ll n){
    if(n == 0) return 1LL;
    ll res = power(x * x % M, n/2);
    if(n % 2 == 1) res = res * x % M;
    return res;
}

void dfs(ll cur, ll par){
    dp[cur] = 1;
    for(auto &e: tree[cur]){
        if(e == par) continue;
        dfs(e, cur);
        dp[cur] *= dp[e];
        dp[cur] %= M;
    }
    dp[cur]++;
}

void dfs2(ll cur, ll par){
    ans[cur] = dp[cur] - 1;
    for(auto &e: tree[cur]){
        if(e == par) continue;

        dp[cur] = (dp[cur]-1) * power(dp[e], M-2) % M + 1;
        dp[e] = (dp[e] - 1) * dp[cur] % M + 1;
        dfs2(e, cur);
        dp[e] = (dp[e]-1) * power(dp[cur], M-2) % M + 1;
        dp[cur] = (dp[cur] - 1) * dp[e] % M + 1;
    }
}
bool isPrime(ll x){
    if(x < 2) return false;
    if(x == 2) return true;
    if(x % 2 == 0) return false;
