ll n,m,dp[N][2],outdp[N],seg[4*N],idx[N];
vector<ll> vec,g[N],lev[N],subx[N];

void Build(ll low,ll high,ll pos)
{
  if(low==high)
  {
    seg[pos]=((dp[vec[low]][0]%m)+(dp[vec[low]][1]%m))%m;
    return;
  }
  ll mid=(low+high)/2;
  Build(low,mid,2*pos+1);
  Build(mid+1,high,2*pos+2);
  seg[pos]=((seg[2*pos+1]%m)*(seg[2*pos+2]%m))%m;
}

ll Query(ll low,ll high,ll qlow,ll qhigh,ll pos)
{
  if(qlow>high||qhigh<low) return 1;
  if(qlow<=low&&qhigh>=high) return seg[pos]%m;
  ll mid=(low+high)/2;
  return ((Query(low,mid,qlow,qhigh,2*pos+1)%m)*(Query(mid+1,high,qlow,qhigh,2*pos+2)%m))%m;
}

void DFS(ll cur,ll par,ll dep)
{
  ll ways=1;
  dp[cur][0]=1;
  lev[dep].pb(cur);
  for(auto i:g[cur])
  {
    if(i==par){continue;}
    DFS(i,cur,dep+1);
    subx[cur].pb(i);
    ways=mul(ways,((dp[i][0]%m)+(dp[i][1]%m))%m,m);
  }
  dp[cur][1]=ways;
}

void xDFS(ll cur,ll par,ll dep)
{
  if(cur==1){outdp[cur]=1;}
  else
  {
    ll p=lev[dep].size();
    if(p==1){outdp[cur]=((outdp[par]%m)+(dp[par][0]%m))%m;}
    else
    {
      ll pro=1,l=idx[subx[par][0]],r=idx[subx[par][subx[par].size()-1]],mid=idx[cur];
      ll lef=Query(0,n-1,l,mid-1,0);
      ll rig=Query(0,n-1,mid+1,r,0);
      pro=mul(pro,lef,m);
      pro=mul(pro,rig,m);
      pro=mul(pro,outdp[par],m);
      outdp[cur]=((pro%m)+(dp[par][0]%m))%m;
    }
  }
  for(auto i:g[cur])
  {
    if(i==par){continue;}
    xDFS(i,cur,dep+1);
  }
}

