void dfs(int v, int p = -1) {
    mint res = 1;
    rep(i, sz(g[v])) {
        auto nv = g[v][i];
        if (p == nv) continue;
        dfs(nv, v);
        suml[v][nv] = sumr[v][nv] = dp[nv] + 1;
        res *= dp[nv] + 1;
    }
    dp[v] = res;
}

void dfs2(int v, int p = -1) {
    mint before = 1;
    suml[v][-1] = 1;
    for (auto& l : suml[v]) {
        before *= l.second;
        l.second = before;
    }
    before = 1;
    sumr[v][n] = 1;
    itrepd(it, sumr[v]) {
        before *= it->second;
        it->second = before;
    }

    rep(i, sz(g[v])) {
        auto nv = g[v][i];
        if (p == nv) continue;
        auto it = suml[v].find(nv); --it;
        auto it2 = sumr[v].find(nv); ++it2;
        suml[nv].emplace(v, it->second * it2->second + 1);
        sumr[nv].emplace(v, it->second * it2->second + 1);
        dp[nv] *= it->second * it2->second + 1;
        dfs2(nv, v);
    }
}

