void fix( int x )
{
	for( auto &y : g[x] ) {
		auto it = find( g[y].begin(), g[y].end(), x );
		if( it != g[y].end() ) {
			g[y].erase( it );
		}
        fix( y );
    }
}

void dfs( int x )
{
    down[x] = 1;
    for( auto &y : g[x] ) {
        dfs( y );
        down[x] = (long long)down[x] * (down[y] + 1) % MOD;
    }
    int sz = g[x].size();
    pref[x].resize( sz + 1 );
    suf[x].resize( sz + 1 );
    pref[x][0] = suf[x][sz] = 1;
    for( int i = 0; i < sz; i++ ) {
        pref[x][i + 1] = (long long)pref[x][i] * (1 + down[ g[x][i] ]) % MOD;
    }
    for( int i = sz-1; i >= 0; i-- ) {
        suf[x][i] = (long long)suf[x][i + 1] * (1 + down[ g[x][i] ]) % MOD;
    }
}

void dfs1( int x )
{
    for( int i = 0; i < g[x].size(); i++ ) {
        int y = g[x][i];
        up[y] = up[x] * (long long)pref[x][i] * suf[x][i+1] % MOD;
        up[y] = (up[y] + 1) % MOD;
        dfs1( y );
    }
}

