vector<int64> dp;
vector<int64> ans;
int64 M;
int64 dfs(int v, int pre){
    for(auto to:edge[v]){
        if(to==pre) continue;
        dp[v]*=dfs(to,v)+1;
        dp[v]%=M;
    }
    return dp[v];
}

void dfs_with_rerooting(int v, int pre, int64 pre_val){
    debug(mp(v, mp(pre,pre_val)))
    for(auto to:edge[v]){
        if(to==pre) ans[v] *= pre_val+1;
        else ans[v] *= dp[to]+1;
        ans[v]%=M;
    }

    //accumulate product
    vector<int64> left(edge[v].size(),1),right(edge[v].size(),1);
    REP(i,edge[v].size()){
        auto to = edge[v][i];
        if(i) left[i] = left[i-1];
        left[i] *= dp[to] + 1;
        left[i] %= M;
    }

    for(int i=edge[v].size()-1; i>=0; i--){
        auto to = edge[v][i];
        if(i<edge[v].size()-1) right[i] = right[i+1];
        right[i] *= dp[to] + 1;
        right[i] %= M;
    }

    //rerooting
    REP(i,edge[v].size()){
        auto to = edge[v][i];
        auto tmp = dp[v];
        if(to!=pre){
            int64 val = 1;
            if(i) val *= left[i-1];
            if(i<edge[v].size()-1) val *= right[i+1];
            val %= M;
            dp[v] = val;
            dfs_with_rerooting(to,v,val);
        }
        dp[v] = tmp;
    }

}

