typedef long long ll;
const int maxn=(1e5)+10;
int n;
ll s[maxn];
ll mod,dp[maxn],ans[maxn];
vector<int> g[maxn];
vector<ll> s1[maxn],s2[maxn];
void update(ll &x,ll y) { x=x*y%mod; }
void dfs(int u,int p) {
	dp[u]=1;
	s1[u].resize(g[u].size()+1);
	s2[u].resize(g[u].size()+1);
	for (int i=0;i<g[u].size();i++) {
		int v=g[u][i];
		if (v==p) {
			if (i) s1[u][i]=s1[u][i-1];
			else s1[u][i]=1;
			continue;
		}
		dfs(v,u);
		if (i) s1[u][i]=s1[u][i-1]*(dp[v]+1)%mod;
		else s1[u][i]=dp[v]+1;
		update(dp[u],dp[v]+1);
	}
	for (int i=g[u].size()-1;i>=0;i--) {
		int v=g[u][i];
		if (v==p) {
			if (i<g[u].size()-1)
				s2[u][i]=s2[u][i+1];
			else s2[u][i]=1;
			continue;
		}
		if (i==g[u].size()-1) s2[u][i]=dp[v]+1;
		else s2[u][i]=s2[u][i+1]*(dp[v]+1)%mod;
		s[v]=1;
		if (i) update(s[v],s1[u][i-1]);
		if (i<g[u].size()-1) update(s[v],s2[u][i+1]);
	}
}
void DFS(int u,int p,ll delta) {
	for (int i=0;i<g[u].size();i++) {
		int v=g[u][i];
		if (v==p) continue;
		ans[v]=(s[v]*delta%mod+1)*dp[v]%mod;
		DFS(v,u,(s[v]+1)*delta%mod);
	}
}
