		read(x); read(y);
		g[x].push_back(y);
		g[y].push_back(x);
	}
	dfs(1,0);
	DFS(1,0,1);
	ans[1]=dp[1];
	for (int i=1;i<=n;i++) printf("%lld\n",ans[i]);
	return 0;
}

