const int MN = 1e5+7;
int MOD, n, dp[MN], dpbig[MN], mark[MN];
vector<int> g[MN];

void dfs(int now, int dis){
    mark[now] = dis;
    int zz = 1;
    for(int i = 0; i < g[now].size(); i++){
        if(mark[g[now][i]] == -1){
            dfs(g[now][i], dis+1);
            zz = (zz * (dp[g[now][i]] + 1)) % MOD;
        }
    }
    dp[now] = zz;
}

void adfs(int now, int last){
    //cout << now << ' ' << last << endl;
    last %= MOD;
    mark[now] = 1;
    dpbig[now] = (last * dp[now]) % MOD;
    if(g[now].size() == 0)return;
    int pef[g[now].size()], suf[g[now].size()];
    int sw = 0;
    for(int i = 0; i < g[now].size(); i++){
        if(mark[g[now][i]] != -1 && sw == 0)pef[i+1] = 1;
        if(mark[g[now][i]] != -1 && sw)pef[i+1] = pef[i];
        if(mark[g[now][i]] == -1 && sw){
            pef[i+1] = (dp[g[now][i]]+1) * pef[i] % MOD;
        }
        if(mark[g[now][i]] == -1 && sw == 0){
            sw = 1;
            pef[i+1] = dp[g[now][i]]+1;
        }
    }
    sw = 0;
    for(int i = g[now].size()-1; i >= 0; i--){
        if(mark[g[now][i]] != -1 && sw == 0)suf[i] = 1;
        if(mark[g[now][i]] != -1 && sw)suf[i] = suf[i+1];
        if(mark[g[now][i]] == -1 && sw){
            suf[i] = (dp[g[now][i]]+1) * suf[i+1] % MOD;
        }
        if(mark[g[now][i]] == -1 && sw == 0){
            sw = 1;
            suf[i] = dp[g[now][i]]+1;
        }
    }
    suf[g[now].size()] = 1;
    pef[0] = 1;
    for(int i = 0; i < g[now].size(); i++){
        if(mark[g[now][i]] == -1){
            adfs(g[now][i], (last * (pef[i] * suf[i+1] % MOD) % MOD)+ 1);
        }
    }
}

