const int N = 1e5 + 10;
int n, m;
vector<int> g[N];
map<pair<int, int>, int> dp;

int mul(int a, int b)
{
    return ((ll)a * b) % m;
}

int solve(int node, int parent)
{
    if(dp.find({node, parent}) != dp.end())
        return dp[{node, parent}];
    int &ret = dp[{node, parent}];
    ret = 1;
    for(auto &x: g[node])
    {
        if(x == parent)
            continue;
        ret = mul(ret, solve(x, node));
    }
    return ret = (ret + 1) % m;
}

