template<class T> class rerooting {
    using F1 = function<T(T, T)>;
    using F2 = function<T(T)>;
    T m_unit, p_unit;
    F1 merge;
    F2 pushup;

    vector<vector<int>>& g;
    int n;
    vector<vector<T>> l, r;
    vector<T> dp, ans;
public:
    rerooting(vector<vector<int>>& _g, T unit1, F1 fun1, T unit2, F2 fun2)
        : g(_g), n(g.size()), l(n), r(n), dp(n), ans(n),
        m_unit(unit1), merge(fun1), p_unit(unit2), pushup(fun2) {
        dfs1(0, -1), dfs2(0, p_unit);
    }
    void dfs1(int now, int par) {
        l[now].reserve(g[now].size());
        r[now].reserve(g[now].size());
        l[now].push_back(m_unit);
        if (par != -1)g[now].erase(find(all(g[now]), par));
        each(to, g[now]) {
            dfs1(to, now);
            l[now].push_back(pushup(dp[to]));
        }
        FOR(i, 2, l[now].size())r[now].push_back(l[now][i]);
        r[now].push_back(m_unit);
        FOR(i, 1, l[now].size())l[now][i] = merge(l[now][i - 1], l[now][i]);
        rFOR(i, 0, r[now].size() - 1)r[now][i] = merge(r[now][i + 1], r[now][i]);
        dp[now] = l[now].back();
        l[now].pop_back();
    }
    void dfs2(int now, const T& pardp) {
        ans[now] = merge(pardp, dp[now]);
        FOR(i, 0, g[now].size()) {
            dfs2(g[now][i], pushup(merge(merge(l[now][i], r[now][i]), pardp)));
        }
    }
    void print(string s) {
        FOR(i, 0, n)cout << ans[i] << (i == n - 1 ? "\n" : s);
    }
};

