void solve1(const Graph &G, int pos, int par, int mod) {
	ll b = 1;
	for (auto e : G[pos]) {
		if (e.to == par)continue;
		solve1(G, e.to, pos, mod);
		b = (b * (subtree[e.to] + 1)) % mod;
	}
	subtree[pos] = b;
}

void solve2(const Graph &G, int pos, int par, ll val, int mod) {
	ans[pos] = (subtree[pos] * val) % MOD;
	vll forward(G[pos].size() + 1, 1), backward(G[pos].size() + 1, 1);

	int j = 0;
	rep(i, G[pos].size()) {
		if (G[pos][i].to == par) {
			j = -1;
			continue;
		}
		forward[i + j + 1] = (forward[i + j] * (subtree[G[pos][i].to] + 1)) % mod;
	}
	j = 0;
	reprev(i, G[pos].size()) {
		if (G[pos][i].to == par) {
			j = 1;
			continue;
		}
		backward[i + j] = (backward[i + j + 1] * (subtree[G[pos][i].to] + 1)) % mod;
	}
	j = 0;
	rep(i, G[pos].size()) {
		if (G[pos][i].to == par) {
			j = -1;
			continue;
		}
		ll val = (forward[i + j] * backward[i + j + 1] + 1) % mod;
		solve2(G, G[pos][i].to, pos, val, mod);
	}
}

