int dame[100001];

int dfs(int v, int prev) {
	if (dame[v]) {
		ll ret = 1;
		if (prev >= 2) {
			int k = K[v] - num[prev];
			if (k >= 2) ret *= S1[v][k - 2];
			if (k < K[v]) ret *= S2[v][k];
			ret %= M;
		}
		else ret = S1[v][K[v] - 1];
		if (dame[v] >= 2 && dame[v] != prev) {
			ll tmp = dfs(to[dame[v]], dame[v] ^ 1);
			int k = K[v] - num[dame[v]];
			for (int i = k - 1; i < K[v]; i++) {
				S1[v][i] = S1[v][i] * tmp % M;
			}
			for (int i = k - 1; i >= 0; i--) {
				S2[v][i] = S2[v][i] * tmp % M;
			}
			ret *= tmp;
			dame[v] = -1;
		}
		return (ret + 1) % M;
	}
	dame[v] = prev;
	ll ret = 1;
	int k = 0;
	for (int i = he[v]; i; i = ne[i]) {
		int tmp = 1;
		if (i != prev) {
			tmp = dfs(to[i], i ^ 1);
			ret = ret * tmp % M;
		}
		S1[v][k] = ret;
		S2[v][k++] = tmp;
	}
	for (int i = k - 2; i >= 0; i--) {
		S2[v][i] = ((ll)S2[v][i] * S2[v][i + 1]) % M;
	}
	return ret + 1;
}

