int MOD = 1000000007;
struct mod_int {
    int val;
    mod_int(long long val_ = 0) : val(val_ % MOD) { if (val < 0) { val += MOD; }}
    bool operator==(const mod_int &rhs) const { return val == rhs.val; }
    bool operator!=(const mod_int &rhs) const { return std::rel_ops::operator!=(*this, rhs); }
    mod_int &operator+=(const mod_int &rhs) {
        if ((val += rhs.val) >= MOD) { val -= MOD; }
        return *this;
    }
    mod_int &operator-=(const mod_int &rhs) {
        if ((val += MOD - rhs.val) >= MOD) { val -= MOD; }
        return *this;
    }
    mod_int &operator*=(const mod_int &rhs) {
        val = (int) ((long long) val * rhs.val % MOD);
        return *this;
    }
    mod_int &operator/=(const mod_int &rhs) { return *this *= rhs.inv(); }
    mod_int operator+() const { return *this; }
    mod_int operator-() const { return -val; }
    mod_int operator++() { return *this += 1; }
    mod_int operator--() { return *this -= 1; }
    mod_int operator++(signed) {
        const mod_int ret(*this);
        ++*this;
        return ret;
    }
    mod_int operator--(signed) {
        const mod_int ret(*this);
        --*this;
        return ret;
    }
    mod_int operator+(const mod_int &rhs) const { return mod_int(*this) += rhs; }
    mod_int operator-(const mod_int &rhs) const { return mod_int(*this) -= rhs; }
    mod_int operator*(const mod_int &rhs) const { return mod_int(*this) *= rhs; }
    mod_int operator/(const mod_int &rhs) const { return mod_int(*this) /= rhs; }
    mod_int inv() const {
        assert(val != 0);
        int a = val, b = MOD, x = 1, u = 0;
        while (b) {
            int t = a / b;
            std::swap(a -= t * b, b);
            std::swap(x -= t * u, u);
        }
        return x;
    }
    mod_int pow(long long n) const {
        if (n < 0) { return pow(-n).inv(); }
        mod_int ret = 1, mul = *this;
        while (n) {
            if (n & 1) { ret *= mul; }
            mul *= mul;
            n >>= 1;
        }
        return ret;
    }
    friend std::istream &operator>>(std::istream &is, mod_int &rhs) {
        long long v;
        is >> v;
        rhs = v;
        return is;
    }
    friend std::ostream &operator<<(std::ostream &os, const mod_int &rhs) { return os << rhs.val; }
    struct combination {
        std::vector<mod_int> fact{1, 1}, f_inv{1, 1}, inv{0, 1};
        void calc(int n) {
            while (fact.size() <= n) {
                int i = fact.size();
                fact.push_back(fact[i - 1] * i);
                inv.push_back(-inv[MOD % i] * (MOD / i));
                f_inv.push_back(f_inv[i - 1] * inv[i]);
            }
        }
        mod_int P(int n, int r) { return r < 0 || n < r ? 0 : (calc(n), fact[n] * f_inv[n - r]); }
        mod_int C(int n, int r) { return r < 0 || n < r ? 0 : (calc(n), fact[n] * f_inv[r] * f_inv[n - r]); }
        mod_int H(int n, int r) { return C(n + r - 1, r); }
    };
};

using mint = mod_int;

template<typename M>
std::vector<typename M::T> re_rooting(const std::vector<std::vector<int>> &adj,
                                      const std::vector<std::vector<typename M::E>> &cost) {
    using T = typename M::T;
    int n = adj.size();
    std::vector<std::vector<T>> dp(n);
    {
        static auto dfs = [&](auto &&self, int cur, int par) -> T {
            dp[cur].resize(adj[cur].size());
            T cum = M::id();
            for (int i = 0; i < adj[cur].size(); i++) {
                if (adj[cur][i] == par) { continue; }
                dp[cur][i] = M::op_TE(self(self, adj[cur][i], cur), cost[cur][i]);
                cum = M::op_TT(cum, dp[cur][i]);
            }
            return cum;
        };
        dfs(dfs, 0, -1);
    }
    std::vector<T> ret(n);
    {
        static auto dfs = [&](auto &&self, int cur, int par, T drop) -> void {
            int m = adj[cur].size();
            std::vector<T> l_cum(m + 1), r_cum(m + 1);
            l_cum[0] = r_cum[m] = M::id();
            for (int i = 0; i < m; i++) {
                if (adj[cur][i] == par) { dp[cur][i] = M::op_TE(drop, cost[cur][i]); }
                l_cum[i + 1] = M::op_TT(l_cum[i], dp[cur][i]);
            }
            for (int i = m - 1; i >= 0; i--) { r_cum[i] = M::op_TT(dp[cur][i], r_cum[i + 1]); }
            for (int i = 0; i < m; i++) {
                if (adj[cur][i] == par) { continue; }
                self(self, adj[cur][i], cur, M::op_TT(l_cum[i], r_cum[i + 1]));
            }
            ret[cur] = l_cum[m];
        };
        dfs(dfs, 0, -1, M::id());
    }
    return ret;
}

struct rr {
    using T = mint;
    using E = int;
    static T id() { return 1; }
    static T op_TT(const T &a, const T &b) { return a * b; }
    static T op_TE(const T &a, const E &b) { return a + b; }
};

