llong search(llong now, llong parent) {
    llong ret = 1;

    FOR(i, edges[now].size()) {
        llong to = edges[now][i];
        if(to == parent) continue;
        if(dp[now][i] == -1) {
            llong cnt = search(to, now);
            dp[now][i] = cnt;
        }
        ret *= dp[now][i];
        ret %= M;
    }

    return (ret + 1) % M;
};

