int M;

long long dfs1(int u) {
  visited[u] = true;
  long long acc = 1;
  for (auto i=0; i< adj[u].size(); i++) {
    auto v = adj[u][i];

    if (!visited[v]) {
      adj_count[u][i] = (dfs1(v) + 1) % M;
      acc = ( acc *  adj_count[u][i] ) % M;
    }
  }

  return acc;
}

void dfs2(int u, long long father) {
  visited[u] = true;

  int le = adj[u].size();

  vector<long long> l( le+1, 1 );
  vector<long long> r( le+1, 1 );
  long long acc = 1;
  for(auto i=0; i<le; i++) {
    auto v = adj[u][i];
    if (visited[v]) adj_count[u][i] = father+1;
    acc = (acc * adj_count[u][i]) % M;
    l[i] = acc;
  }

  acc = 1;
  for(auto i=le-1; i >=0; i--) {
    acc = (acc * adj_count[u][i]) % M;
    r[i]= acc;
  }

  ans[u] = r[0];

  for(auto i=0; i<le; i++) {
    auto v = adj[u][i];
    auto lv = (i > 0)?(l[i-1]):(1);
    auto rv = (i <le-1)?(r[i+1]):(1);
    if (!visited[v])  dfs2(v,  lv*rv);
  }
}

