int n,m;
vector<vector<int> > g; 
vector<int> dn,up;
void dfs1(int cur, int par){
	dn[cur] = 1;
	for(int son : g[cur]){
		if(son==par) continue;
		dfs1(son,cur);
		dn[cur] = (1ll*(dn[cur] * (1+dn[son])))%m;
	}
}

void dfs2(int cur, int par){
	int k = g[cur].size();
	vector<int> pref(k+2,1),suff(n+2,1);
	for(int i = 0; i < k; i++){
		pref[i] = suff[i] = 1;
	}
	for(int i = 0; i < k; i++){
		if(par == g[cur][i]){
			if(i!=0) pref[i] = pref[i-1]%m;
			continue;
		}
		if(i==0) pref[i] = (1+dn[g[cur][i]])%m;
		else     pref[i] = 1ll*(pref[i-1] * (1+dn[g[cur][i]]))%m ;
	}
	for(int i = k-1; i >= 0; i--){
		if(par == g[cur][i]){
			if(i!=k-1) suff[i] = suff[i+1]%m;
			continue;
		}
		if(i==k-1) suff[i] = (1+dn[g[cur][i]])%m;
		else       suff[i] = 1ll*(suff[i+1] * (1+dn[g[cur][i]]) )%m;
	}
	//debug(cur,par,pref);
	//debug(cur,par,suff);
	for(int i = 0; i < k; i++){
		if(par == g[cur][i]) continue;
		int res = 1;
		if(i!=0) res = pref[i-1]%m;
		if(i!=k-1) res = 1ll * res * suff[i+1] % m;
		up[g[cur][i]] = 1ll * (1 + 1ll * up[cur] * res) % m;
		dfs2(g[cur][i],cur);
	}
}


