vector<int> v[100001];

void solve1(int root, int p, int m){
	dp[root] = 1;
	for(int child: v[root]){
		if(child != p){
			solve1(child, root, m);	
			dp[root] = (dp[root] * (dp[child]+1))%m;
		}
	}
}

void solve2(int root, int p, int m){
	dp2[root] = dp[root];
	if(p != 0){
		dp2[root] = (dp2[root] * (dp2[p]/(dp[root] + 1) + 1))%m;
	}

	for(int child : v[root]){
		if(child != p){
			solve2(child, root, m);
		}
	}
}

void solve3(int root, int p, int m, int parent_ans){
	dp2[root] = dp[root]*(1+parent_ans);

	vector<ll> prefix;
	vector<ll> suffix;


	for(int child: v[root]){
		if(child != p){
			prefix.pb(1 + dp[child]);
			suffix.pb(1 + dp[child]);
		}
	}

	for(int i=1; i<prefix.size(); i++){
		prefix[i] = (prefix[i]*prefix[i-1])%m;
	}
	for(int i=suffix.size()-2; i>=0; i--){
		suffix[i] = (suffix[i]*suffix[i+1])%m;
	}

	int cno = 0;
	for(int child : v[root]){
		if(child != p){
			int current_ans = (1 + parent_ans)%m;
			if(cno > 0){
				current_ans = (current_ans * prefix[cno - 1])%m;
			}
			if(cno < suffix.size() - 1){
				current_ans = (current_ans * suffix[cno + 1])%m;
			}

			solve3(child, root, m, current_ans);
			cno++;
		}
	}
}


