void dfs(int x, int pre = -1){
	dp[x] = 1;

	pref[x].resize(sz(G[x]) + 1);
	pref[x][0] = 1;
	suf[x].resize(sz(G[x]) + 1);
	suf[x].back() = 1;

	for(int i = 0; i < sz(G[x]); i++)
		if(G[x][i] != pre){
			dfs(G[x][i], x);
			(dp[x] *= dp[G[x][i]]) %= m;
			pref[x][i + 1] = pref[x][i] * dp[G[x][i]] % m;
		}
		else
			pref[x][i + 1] = pref[x][i];

	for(int i = sz(G[x]) - 1; i >= 0; i--)
		if(G[x][i] != pre)
			suf[x][i] = suf[x][i+1] * dp[G[x][i]] % m;
		else
			suf[x][i] = suf[x][i+1]; 
	(dp[x] += 1) %= m;
}

