void sieve()
{
	int tmp=m;
	phi=1;
	for(int i=2; (ll)i*i<=tmp; i++) {
		if(tmp%i==0) {
			phi*=i-1;
			while(tmp%i==0) {
				tmp/=i;
			}
		}
	}
	if(tmp>1) phi*=tmp-1;
}

int po(int a, int b)
{
	int res=1;
	while(b>0) {
		if(b&1) {
			res=mul(res, a);
		}
		a=mul(a, a);
		b>>=1;
	}
	return res;
}

