int sub[100005] , dp[100005];
vector<vii> gp;
int n,m;
void dfs1(int u,int p)
{
  sub[u] = 1;
  for(auto x:gp[u])
    if(x!=p)
    {
      dfs1(x,u);
      sub[u] = ((sub[x]+1)%m  *  sub[u]%m )%m;
    }
}

void dfs2(int u,int p,int vl)
{
   dp[u] = (sub[u]%m*(vl+1)%m)%m;

   vii ar,suffix,prefix;
   for(int i=0;i<sz(gp[u]);i++)
   {
     if(gp[u][i]!=p)ar.pb(sub[gp[u][i]]+1);
     else ar.pb(1);
   }

   int s = sz(ar);
   suffix.resize(s);
   prefix.resize(s);
   prefix[0]=1;
   suffix[s-1]=1;
   for(int i=1;i<s;i++)
   {
     prefix[i] = (prefix[i-1]%m*ar[i-1]%m)%m;
   }
   for(int i=s-2;i>=0;i--)
   {
    suffix[i] = (suffix[i+1]%m * ar[i+1]%m)%m;
   }

   for(int i=0;i<sz(gp[u]);i++)
    if(gp[u][i]!=p)
    {
      int cvl = (((vl+1)%m*suffix[i]%m)*prefix[i]%m)%m;
      dfs2(gp[u][i],u,cvl);
    }
}
