const int MX = 100 * 1000 + 7;

int f[MX];
vector<int> g[MX];

int ans[MX];

void dfs1(int v, int p) {
    for (int i = 0; i < g[v].size(); i++) {
        if (g[v][i] == p) {
            g[v].erase(g[v].begin() + i);
            break;
        }
    }

    f[v] = 1;
    for (int to : g[v]) {
        dfs1(to, v);
        f[v] = mul(f[v], f[to] + 1);
    }
}

void dfs2(int v, int up) {
    vector<int> pref(g[v].size());
    vector<int> suf(g[v].size());

    int cm = 1;
    for (int i = 0; i < g[v].size(); i++) {
        cm = mul(cm, f[g[v][i]] + 1);
        pref[i] = cm;
    }

    cm = 1;
    for (int i = int(g[v].size()) - 1; i >= 0; i--) {
        cm = mul(cm, f[g[v][i]] + 1);
        suf[i] = cm;
    }

    ans[v] = (up + 1) % M;
    if (g[v].size()) {
        ans[v] = mul(ans[v], pref.back());
    }

    for (int i = 0; i < g[v].size(); i++) {
        int cf = 1;
        if (i) {
            cf = mul(cf, pref[i - 1]);
        }
        if (i + 1 < g[v].size()) {
            cf = mul(cf, suf[i + 1]);
        }
        dfs2(g[v][i], mul(cf, up + 1));
    }
}


