int rec_fun(int a, vector<bool> & been){


	been[a] = true;

	long long res = 1;

	for(int i  = 0; i < graph[a].size(); i++){
		int next = graph[a][i];
		if( !been[next] ){
			long long child = rec_fun(next, been);

			path[a][next] = child;

			res *= 1+child;
			res %= mod;
		}

	}

	return res;	
}


void calc_lasts(int a, vector<bool> & been, int given_by, long long given_point){

	been[a] = true;

	if(given_by != 0){
		path[a][given_by] = given_point % mod;
	}

	long long full = 1;
	for(int i  = 0; i < graph[a].size(); i++){
		int next = graph[a][i];

//		cout<<a<<" ->  "<<next<<"   :"<<path[a][next]<<endl;

		full *= 1+path[a][next];
	}
	ans[a] = full % mod;

	for(int i  = 0; i < graph[a].size(); i++){
		int next = graph[a][i];

		if( !been[next] ){
			calc_lasts(next, been, a, full / (1 + path[a][next]));
		}
	}

}


