vector<ll> in(N), out(N);
vector<int> g[N];

void dfs_in(int src, int par, const int mod){
    ll &cur = in[src];
    cur = 1;
    for(auto i : g[src])
        if(i != par) {
            dfs_in(i, src, mod);
            cur = (cur * (in[i] + 1)) % mod;
        }
}

void dfs_out(int src, int par, const int mod){
    if(par && (int)g[src].size() == 1) return;

    vector<int> child;
    for(auto i : g[src]){
        if(i == par) continue;
        child.pb(i);
    }

    vector<ll> pre((int)child.size() + 2, 1), suf((int)child.size()+2, 1);
    for(int j = 1; j <= (int)child.size(); j++)
        pre[j] = (pre[j-1] * (in[child[j-1]] + 1)) % mod;
    for(int j = (int)child.size(); j > 0; j--)
        suf[j] = (suf[j+1] * (in[child[j-1]] + 1)) % mod;

    for(int j = 1; j <= (int)child.size(); j++){
        int cur = child[j-1];
        ll below = (pre[j-1] * suf[j+1]) % mod;
        out[cur] = (out[src] * below) % mod;
        out[cur] = (out[cur] + 1) % mod;
        dfs_out(cur, src, mod);
    }
}

