void addedge(int u,int v)
{
	tot++;
	nxt[tot]=head[u];
	to[tot]=v;
	head[u]=tot; 
}
int dfs(int index,int parent)
{
	g[index]=1;
	for(int i=head[index];i;i=nxt[i])
	{
		int v=to[i];
		if(parent==v)
			continue;
		g[index]=(int)(((long long)(dfs(v,index)+1)*g[index])%m);
	}
	return g[index];
}
void dfs2(int index,int parent)
{
	if(index==1)
		f[index]=g[index];
	else
		f[index]=(int)(((long long)g[index]*(((f[parent]==0?m:f[parent])/(g[index]+1))%m)+1)%m);
	for(int i=head[index];i;i=nxt[i])
	{
		int v=to[i];
		if(parent==v)
			continue;
		dfs2(v,index);
	}
}
