/////////////////////////////////////////////////////////////////////////////////

// f は子から親に引き継ぐときに変換するための関数
// merge は子から引き継いだ値をマージするための関数
// h はマージされた結果を用いて最終的な値を求めるための関数
template <typename F, typename Monoid, typename H, typename T>
struct Rerooting {
    int N;
    vector<vector<int>> G;
    vector<T> subdp,dpL,dpR,dp;
    F f;
    Monoid merge;
    H h;
    T unity;

    Rerooting(int N, F f, Monoid merge, H h, T unity) : 
        N(N), G(N), subdp(N), dpL(N), dpR(N), dp(N), 
        f(f), merge(merge), h(h), unity(unity) {}

    void add_edge(int u, int v) {
        G[u].emplace_back(v);
        G[v].emplace_back(u);
    }

    void build(int r = 0) {
        dfs_sub(r,-1);
        dfs_all(r, unity);
    }

private:
    void dfs_sub(int v, int pv) {
        for (int &nv : G[v]) {
            if (nv == pv) swap(nv,G[v].back());
        }
        if (~pv) G[v].pop_back();
        subdp[v] = unity;
        for (int nv : G[v]) {
            dfs_sub(nv,v);
            subdp[v] = merge(subdp[v],f(subdp[nv],nv));
        }
        subdp[v] = h(subdp[v],v);
    }

    //valは親を子に見立てたときのf(subdp[pv],pv)の値
    void dfs_all(int v, T val) {
        dp[v] = val;
        T left = unity;
        for (int i = 0; i < (int)G[v].size(); i++) {
            int nv = G[v][i];
            dpL[nv] = left = merge(left,f(subdp[nv],nv));
            dp[v] = merge(dp[v],f(subdp[nv],nv)); 
        }
        dp[v] = h(dp[v],v);
        T right = unity;
        for (int i = (int)G[v].size()-1; i >= 0; i--) {
            int nv = G[v][i];
            dpR[nv] = right = merge(right,f(subdp[nv],nv));
        }
        for (int i = 0; i < (int)G[v].size(); i++) {
            T L = i == 0 ? unity : dpL[G[v][i-1]];
            T R = i == (int)G[v].size()-1 ? unity : dpR[G[v][i+1]];
            dfs_all(G[v][i],f(h(merge(val,merge(L,R)),v),v));
        }
    }
};

