void ABC160F() {
    int N; cin >> N;
    vector<mint> kai(N+1,1);
    rep(i,N) kai[i+1] = kai[i]*(i+1);
    auto f=[&](Node a, int v) {(void)v; return Node(a.dp/kai[a.sub],a.sub);};
    Node unity = Node(1,0);
    auto g=[&](Node a, Node b) {return Node(a.dp*b.dp,a.sub+b.sub);};
    auto h=[&](Node a, int v) {(void)v; return Node(a.dp*kai[a.sub],a.sub+1);};
    Rerooting R(N,f,g,h,unity);
    rep(i,N-1) {
        int u,v; cin >> u >> v;
        --u; --v;
        R.add_edge(u,v);
    }
    R.build();
    rep(i,N) {
