    suff[nod] = vl(k, 1);
    fin(i, k) if (adj[nod][i] != par[nod]) {
        pref[nod][i] = suff[nod][i] = (1 + sub[adj[nod][i]]);
    }
    fin2(i, 1, k) pref[nod][i] = (pref[nod][i] * pref[nod][i-1]) % mod;
    ford(i, k-1) suff[nod][i] = (suff[nod][i] * suff[nod][i+1]) % mod;
}

int sumExcept(int nod, int exceptChild)
{
    int ind = rev[exceptChild];
    int a = (ind > 0 ? pref[nod][ind-1] : 1);
    int b = ((ind < (int)(suff[nod].size()) - 1) ? suff[nod][ind+1] : 1);
    return (a*b) % mod;
}

void constructUp(int nod)
{
    if (upok[nod]) return;
    upok[nod] = true;
    up[nod] = 1;
    if (par[nod] != 0) {
        constructUp(par[nod]);
        up[nod] = (1 + up[par[nod]]*sumExcept(par[nod], nod));
        up[nod] %= mod;
    }
}

void dfs(int nod)
{
    int i = 0;
    for (int enf : adj[nod]) { if (enf != par[nod]) {
        par[enf] = nod;
        rev[enf] = i;
        dfs(enf);
    } ++i; }
}

void solve()
{
    s2(n, mod);
    fin(i, n-1) {
        int x, y;
        s2(x, y);
        adj[x].pb(y);
        adj[y].pb(x);
    }
    dfs(1);
    fin2(i,1,n+1) constructSub(i);
    fin2(i,1,n+1) constructPrefix(i);
    fin2(i,1,n+1) constructUp(i);

    fin2(i,1,n+1) {
        p1((((sub[i]*up[i]) % mod)+mod)%mod);
    }
    return;
}

