          src = dest;
          continue;
        }
        prod = (prod * it->second) % m;
      }
      // ルートで最後に残るのは必ず1or2個。
      // 1個なら、外向きのキャッシュは全てできている
      if (src == -1) { root = node; break; }
      prod = (prod + 1) % m;
      dst[src][node] = prod;
      if (dstn[src] >= 2) {
        --dstn[src];
        if (dstn[src] == 1)
          nextproc.push_back(src);
      }
      if (DBG2) {
