  // ルートからリーフへ向かう

  while (!proc.empty()) {
    forall(pnode, proc) {
      int node = *pnode;
      if (DBG) cout << "leaf<-root node " << node << endl;

      // 今見ているnodeは、外向きキャッシュは既にある前提
      // 周りのノードの値ごとにヒストグラムを作る
      unordered_map<long, bar> h;
      forall(it, dst[node]) {
        h[it->second].num++;
      }
      // 各値ごとに、その個数乗、およびその（個数ー１）乗を作る
      forall(it, h) {
        long p = 1;  // NOTE num==1のときprod1=0
        forr(i, 1, it->second.num-1)
          p = (p * it->first) % m;
        it->second.prod1 = p;
        //h[it->first].prod1 = p;
        it->second.prodall = (p * it->first) % m;
      }
      // 「周りの全部の積、ただし自分除く」を作る（キャッシュに入れる値）
      forall(it, h) {
        long p = 1;
        forall(it2, h)
          if (it->first == it2->first)
            p = (p * it2->second.prod1) % m;
          else
            p = (p * it2->second.prodall) % m;
        it->second.prodme = (p + 1) % m;
      }
      // 各ノードにヒストグラムの値をコピー
      forall(it, dst[node])
        if (dst[it->first][node] == -1) {
          dst[it->first][node] = h[it->second].prodme;
