    proc.clear();
    forall(it, nextproc)
      proc.push_back(*it);
    nextproc.clear();
  }
  if (DBG2) {
    cout << "down from root done" << endl;
    forr(i,0,n-1) {
      cout << "i " << i << " ";
      forall(it, dst[i])
        cout << it->first << ":" << it->second << "  ";
