int m;
void solve1(vector<vector<int> >& tree, vector<bool>& visited, int curr_node) {
	visited[curr_node] = true;
	int ans = 1;
	for (auto child : tree[curr_node]) {
		if (!visited[child]) {
			solve1(tree, visited, child);
			ans *= (1 + dp1[child]);
			ans %= m;
		}
	}
	dp1[curr_node] = ans;
	dp1[curr_node] %= m;
}

void solve2(vector<vector<int> >& tree, vector<bool>& visited, int curr_node, int parent_answer) {

	visited[curr_node] = true;
	dp2[curr_node] = (1 + parent_answer);
  	dp2[curr_node] %=m;
	for (auto child : tree[curr_node]) {
		if (!visited[child]) {
			dp2[curr_node] *= (1 + dp1[child]);
			dp2[curr_node] %= m;
		}
	}
	dp2[curr_node] %= m;

	for (auto child : tree[curr_node]) {
		if (!visited[child]) {
			solve2(tree, visited, child, ((dp2[curr_node] / (1 + dp1[child]))));
		}
	}
}

