void dfs2(int p, int v, int pDp) {
	if (et[v].size() == 0) return;
	//cout << p << " " << v << " " << pDp << endl;
	int i;
	vector<int> ra(et[v].size() + 1);
	vector<int> rb(et[v].size() + 1);

