	rep(i, et[v].size()) {
		int nv = et[v][i];
		if (nv == p) continue;
		leafId[nv] = cor;
		cor++;
	}

	ra[0] = 1;
	rep(i, et[v].size()) {
		int nv = et[v][i];
		if (nv == p) continue;
		ra[leafId[nv] + 1] = ra[leafId[nv]] * (dp1[nv] + 1);
