// 全方位木DP
template<typename T>
class Rerooting {
public:
    const int num_of_nodes;
    vector<T> ans;

private:
    vector<vector<int>> tree;
    vector<vector<T>> dp;           // dp[u][i] = uのi番目の子を根とする部分木のdpの値
    T IDENTITY; // mergeの単位元

    // 問題特有の情報
    int M;

public:
    Rerooting(int num_of_nodes, T identity) : num_of_nodes(num_of_nodes), IDENTITY(identity) {
        ans = vector<T>(num_of_nodes);
        tree = vector<vector<int>>(num_of_nodes, vector<int>());
        dp = vector<vector<T>>(num_of_nodes, vector<T>());
    }

    void set_m(int m) {
        this->M = m;
    }

    void add_undirected_edge(const int u, const int v) {
        tree[u].emplace_back(v);
        tree[v].emplace_back(u);
    }

    void solve() {
        int root = 0;
        for (int i = 0; i < num_of_nodes; ++i) {
            dp[i].resize(tree[i].size());
        }

        dfs1(root, -1);
        dfs2(root, -1, IDENTITY);

        for (int u = 0; u < this->num_of_nodes; ++u) {
            ans[u] = IDENTITY;
            for (int i = 0; i < tree[u].size(); ++i) {
                ans[u] = merge(ans[u], f(dp[u][i], tree[u][i]));
            }
            ans[u] = g(ans[u], u);
        }
    }

    void debug() {
        for (int i = 0; i < num_of_nodes; ++i) {
            dp[i].resize(tree[i].size());
        }

        for (int u = 0; u < this->num_of_nodes; ++u) {
            ans[u] = dfs1(u, -1);
        }
    }

private:
    // dp[u] = g(merge(f(dp_c1, c1), f(dp_c2, c2), ...)) ただしcはuの子供
    T g(T a, int node_no = 0) {
        return a;
    }

    T f(T a, int node_no = 0) {
        return (a + 1) % M;
    };

    // 結合束を満たすこと
    T merge(T a, T b) {
        return a * b % M;
    };

    T dfs1(const int u, const int parent) {
        T res = IDENTITY;
        for (int i = 0; i < tree[u].size(); ++i) {
            const int v = tree[u][i];
            if (v != parent) {
                dp[u][i] = dfs1(v, u);
                res = merge(res, f(dp[u][i], tree[u][i]));
            }
        }
        return g(res, u);
    }

    void dfs2(const int u, const int parent, const T add) {
        for (int i = 0; i < tree[u].size(); ++i) {
            const int v = tree[u][i];
            if (v == parent) {
                dp[u][i] = add;
                break;
            }
        }

        // 左からの累積と右からの累積を計算
        vector<T> left(tree[u].size() + 1), right(tree[u].size() + 1);
        {
            left[0] = IDENTITY;
            for (int i = 0; i < tree[u].size(); ++i) {
                left[i + 1] = merge(left[i], f(dp[u][i], tree[u][i]));
            }
            right[tree[u].size()] = IDENTITY;
            for (int i = tree[u].size(); i > 0; --i) {
                right[i - 1] = merge(right[i], f(dp[u][i - 1], tree[u][i - 1]));
            }
        }

        for (int i = 0; i < tree[u].size(); ++i) {
            const int v = tree[u][i];
            if (v == parent) {
                continue;
            }
            // vを除いたuの子のdpの積
            const auto val = merge(left[i], right[i + 1]);
            dfs2(v, u, g(val, u));
        }
    }
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    LL N, M;
    cin >> N >> M;

    Rerooting<LL> rr(N, 1LL);
    rr.set_m(M);

    FOR(i, 0, N - 1) {
        int A, B;
        cin >> A >> B;
