	int child_num = 0;
	for (auto y : Adj[idx]) {
		if (y == par) { continue; }
		val *= (D[y] + 1);
		val %= M;
		A[idx].push_back(val);
		child_num++;
	}

	B[idx].resize(child_num+2);
	int pos = child_num + 1;
	val = 1;
	B[idx][pos] = val; pos--;

	for (int y = Adj[idx].size() - 1; y >= 0; y--) {
		if (Adj[idx][y] == par) { continue; }
		int m= Adj[idx][y];
		val *= (D[m]+1);
		val %= M;
		B[idx][pos] = val; pos--;
	}

	for (auto y : Adj[idx]) {
		if (y == par) { continue; }
		CALC_A_B(y, idx);
	}
}

