        }
    }
    auto amul = [](vvl aa, vvl bb, int n) {
        vector<vector<ll>> t(n + 1, vector<ll>(n + 1, 0));
        for(int i = 1; i <= n; i++) {
            for(int k = 1; k <= n; k++) {
                for(int j = 1; j <= n; j++) {
                    t[i][j] = (t[i][j] + aa[i][k] * bb[k][j]) % mod;
                }
            }
        }
        return t;
    };
    auto power = [&amul](ll k, vvl cur, int n) {
        vvl res(n + 1, vector<ll> (n + 1, 0));
        for(int i = 1; i <= n; i++)
            res[i][i] = 1;
        while(k > 0) {
            if(k & 1)
                res = amul(res, cur, n);
            k = k >> 1;
            cur = amul(cur, cur, n);
        }
        return res;
    };
    ll ans = 0;
    vvl f = power(K, a, N);
    for(int i = 1; i <= N; i++) {
        for(int j = 1; j <= N; j++) {
            ans += f[i][j];
            ans %= mod;
        }
    }
