ll calc(int v, int p) {
    const P key = make_pair(v, p);
    if (dp.count(key) == 0) {
        ll res = 1;
        for (int i = 0; i < (int)G[v].size(); i++) {
            int u = G[v][i];
            if (u == p) continue;
            res *= (calc(u, v) + 1);
            res %= m;
        }
        dp[key] = res;
    }
    return dp[key];
}

