void dfs1(int u, SegmentTree& st) {
	// cout<<n<<endl;
	seen[u]=1;
	int lo=-1;
	for(int i = 0; i < sz(g[u]); i++) {
		int v=g[u][i];
		if(!seen[v]) {
			if(lo==-1) lo=id[v];
			int hi=lo+sz(g[u])-1;
			if(u!=0) hi--;
			int mid=id[v];
			int oldu=dp[u],oldv=dp[v];
			dp[u]=1;
			// cout<<u<<" "<<v<<" "<<dp[u]<<" "<<dp[v]<<endl;
			// for(int i = 0; i < 4; i++)
			// 	cout<<st.RMQ(i,i).ss<<" gdf ";
			// cout<<endl;
			// cout<<u<<" "<<v<<" "<<lo<<" dsf "<<mid<<" "<<hi<<endl;
			if(parent[u]!=u) dp[u] *= (dp[parent[u]]+1);
			if(lo<=mid-1) dp[u] *= st.RMQ(lo,mid-1).ss;
			dp[u]%=MOD;
			if(hi>=mid+1) dp[u] *= st.RMQ(mid+1,hi).ss;
			dp[u] %=MOD;
			dp[u]+=MOD;
			dp[u]%=MOD;
			dp[v]=(dp[u]+1)*dp[v];
			dp[v]%=MOD;
			dp[v]+=MOD;
			dp[v]%=MOD;
			// cout<<u<<" "<<v<<" "<<dp[u]<<" "<<dp[v]<<endl;
			st.Update(id[u],id[u],((dp[u]-oldu)%MOD+MOD)%MOD);
			st.Update(id[v],id[v],((dp[v]-oldv)%MOD+MOD)%MOD);
			ans[v]=dp[v];
			dfs1(v,st);
			st.Update(id[u],id[u],((oldu-dp[u])%MOD+MOD)%MOD);
			st.Update(id[v],id[v],((oldv-dp[v])%MOD+MOD)%MOD);
			dp[u]=oldu,dp[v]=oldv;
		}
	}
}
