ll n, mod;
vec<ll> res_bottom, res_top;
vec<vec<ll>> graf;

ll MD(ll x) { return (x + mod) % mod; }

void dfs_1(ll parent, ll node)
{
    for (auto nd : graf[node])
    {
        if (nd != parent)
        {
            dfs_1(node, nd);
            res_bottom[node] = MD(res_bottom[node] * (res_bottom[nd] + 1));
        }
    }
}

void dfs_2(ll parent, ll node)
{
    ll prod_left = 1, prod_right = 1;
    for (auto nd : graf[node])
    {
        if (nd != parent)
        {
            res_top[nd] = MD(res_top[nd] * prod_left);
            prod_left = MD(prod_left * (res_bottom[nd] + 1));
        }
    }
    for (auto nd = graf[node].rbegin(); nd != graf[node].rend(); nd++)
    {
        if (*nd != parent)
        {
            res_top[*nd] = MD(res_top[*nd] *  prod_right);
            if (node != 1)
                res_top[*nd] = MD(res_top[*nd] * res_top[node] + 1);
