long long bp(long long x)
{
	long long pr = 1, lr = x;
	for(int i = 0; (1<<i) <= MOD-2; i++)
	{
		if((int)((1<<i)&(MOD-2)) > 0)
		{
			pr *= lr;
			pr %= MOD;
		}
		lr *= lr;
		lr %= MOD;
	}
	return pr;
}
long long modd(long long x, long long y)
{
	return ((x % MOD) * ((bp(y)) % MOD)) % MOD;
}
long long modz(long long x, long long y)
{
	if(x + y >= MOD)
	{
		return x+y-MOD;
	}
	return x+y;
}
long long f(int poz, int p)
{
	v.push_back(make_pair(poz, p));
	long long u = 1;
	for(int i = 0; i < s[poz].size(); i++)
	{
		if(s[poz][i] != p)
		{
			u *= f(s[poz][i], poz);
			u %= MOD;
		}
	}
	if(p != -1)
	{
		return biok[poz] = modz(u, 1);
	}
	else
	{
		return biog[poz] = u;
	}
}
long long r(int poz, int p)
{
	long long u = 1;
	for(int i = 0; i < s[poz].size(); i++)
	{
		if(s[poz][i] != p)
		{
			u *= biok[s[poz][i]];
			u %= MOD;
		}
		else
		{
			u *= modz(1, modd(biog[p], biok[poz]));
			u %= MOD;
		}
	}
	return biog[poz] = u;
}
