long long dfs(long long num,long long fpar)
{
	std::vector<long long> vec;
	ways[num]=1;
	for(auto it:g[num])
	{
		if(it==fpar){continue;}
		else
		{
			par[it]=num;
			dfs(it,num);
			ways[num]=((ways[num]*(1+ways[it]))%mod);
			vec.pb(((1+ways[it])%mod));
		}
	}
	vector<long long> pre,suff;
	long long pro=1;
	for(auto it:vec)
	{
		pro=((pro*it)%mod);
		pre.pb(pro);
	}
	pro=1;
	long long sz=vec.size();
	for(long long i=sz-1;i>=0;--i)
	{
		pro=((pro*vec[i])%mod);
		suff.pb(pro);
	}
	long long ct=0;
	reverse(suff.begin(),suff.end());
	for(auto it:g[num])
	{
		if(it==fpar){
			continue;
		}
		else
		{
			long long ans=1;
			if(ct!=0){ans=((ans*pre[ct-1])%mod);}
			if(ct!=sz-1){ans=((ans*suff[ct+1])%mod);}
			parval[it]=ans;
			++ct;
		}
	}
	topo.pb(num);
	return ways[num];
}
