			r[x].resize(K + 1, 1);
			rep(i, K) l[x][i + 1] = l[x][i] * ress[i] % M;
			rep(i, K) r[x][K - 1 - i] = r[x][i + 1] * ress[K - 1 - i] % M;
		}
	} else {
		dfs(G, dp, l, r, x, -1, f);
		int k = lower_bound(G[x].begin(), G[x].end(), p) - G[x].begin();
		tmp = l[x][k] * r[x][k + 1] % M;
	}
	return dp[x][p] = tmp + 1;
}
