const int N = 1e5 + 10;
struct E
{
    int v, next;
} edge[N << 1];
int head[N], e;
void addedge(int u, int v)
{
    edge[e].v = v;
    edge[e].next = head[u];
    head[u] = e++;
}

int n;
int mod;

LL dp1[N], dpf[N], dp2[N];

LL dfs1(int u, int f)
{
    LL ret = 1;
    for (int i = head[u]; ~i; i = edge[i].next)
    {
        int v = edge[i].v;
        if (v == f) continue;
        LL val = dfs1(v, u);
        ret = ret * (1 + val) % mod;
    }
    return dp1[u] = ret;
}

LL pre[N], suf[N], val[N];
int idx[N];

void dfs2(int u, int f)
{
    int cnt = 0;
    for (int i = head[u]; ~i; i = edge[i].next)
    {
        int v = edge[i].v;
        if (v == f) continue;
        ++cnt;
        idx[cnt] = v;
        val[cnt] = dp1[v];
    }

    // if (cnt == 0) return;

    // assert(cnt >= 0);
    // assert(cnt <= n - 1);

    pre[0] = 1;
    for (int i = 1; i <= cnt; i++) pre[i] = pre[i - 1] * (1 + val[i]) % mod;
    suf[cnt + 1] = 1;
    for (int i = cnt; i >= 1; i--) suf[i] = suf[i + 1] * (1 + val[i]) % mod;

    for (int i = 1; i <= cnt; i++)
    {
        int p = idx[i];
        // assert(p >= 1);
        // assert(p <= n);

        LL v1 = pre[i - 1];
        LL v2 = suf[i + 1];
        LL v = v1 * v2 % mod;  // 同级

        dpf[p] = (dpf[u] * v + 1) % mod;
        dp2[p] = dpf[p] * dp1[p] % mod;
    }

    for (int i = head[u]; ~i; i = edge[i].next)
    {
        int v = edge[i].v;
        if (v == f) continue;
        dfs2(v, u);
    }
}

