void dfs(int u, int p) {
  down[u] = 1;
  for (int v : adj[u]) {
    if (v == p) continue;
    dfs(v, u);
    id[u][v] = pre[u].size();
    down[u] = (1ll * down[u] * (down[v] + 1)) % mod;
    pre[u].push_back(down[u]);
  }
  int cur = 1;
  for (int i = adj[u].size() - 1; i >= 0; i--) {
    int v = adj[u][i];
    if (v == p) continue;
    cur = (1ll * cur * (down[v] + 1)) % mod;
    suf[u].push_back(cur);
  }
  reverse(suf[u].begin(), suf[u].end());
}

void dfs1(int u, int p) {
  up[u] = 1;
  if (p != -1) {
    up[u] = up[p];
    int pos = id[p][u];
    if (pos > 0) {
      up[u] = (1ll * up[u] * pre[p][pos - 1]) % mod;
    }
    if (pos + 1 < suf[p].size()) {
      up[u] = (1ll * up[u] * suf[p][pos + 1]) % mod;
    }
    up[u] = (up[u] + 1) % mod;
  }
  for (int v : adj[u]) {
    if (v == p) continue;
    dfs1(v, u);
  }
}

