const int N = 1e5 + 100;
int n, m;
vector<int> adjList[N];
vector<long long> wout[N];
long long dp[N], ans[N];

void dfs1(int v, int p) {
	dp[v] = 1;

	for (int u : adjList[v]) {
		if (u == p) continue;
		dfs1(u, v);
		dp[v] = (dp[v] * dp[u]) % m;
	}
	dp[v] = (dp[v] + 1) % m;

	int s = adjList[v].size() - (p ? 1 : 0);
	int idx;

	long long pref[s + 2];
	pref[0] = 1;
	idx = 1;
	for (int i = 1; i <= s; i++) {
		int u = adjList[v][i - 1];
		if(u == p) continue;
		pref[idx] = (pref[idx - 1] * dp[u]) % m;
		idx++;
	}

	long long suf[s + 2];
	suf[s + 1] = 1;
	idx = s;
	for (int i = s; i > 0; i--) {
		int u = adjList[v][i - 1];
		if(u == p) continue;
		suf[idx] = (suf[idx + 1] * dp[u]) % m;
		idx--;
	}

	wout[v].resize(s);

	for (int i = 1; i <= s; i++) {
		wout[v][i - 1] = (pref[i - 1] * suf[i + 1]) % m;
	}
}

void dfs2(int v, int p) {
	ans[v] = dp[v];
	int s = adjList[v].size();

	int idx = 0;
	for (int u : adjList[v]) {
		if (u == p) continue;
		dp[u] = (m - 1 + dp[u]) % m;
		dp[u] = (dp[u] * wout[v][idx]) % m;
		for (long long &x : wout[u]) {
			x = (x * wout[v][idx] + 1) % m;
		}
		dfs2(u, v);
		idx ++;
	}
}

