ll dfs1(int x, int y) {
    ll r = 1;
    for(auto v : g[x]) {
        if(v != y) r *= (dfs1(v, x) + 1);
        r %= m;
    }
    fore(i, 0, g[x].size()) if(g[x][i] == y) {
        swap(g[x][i], g[x].back());
        g[x].pop_back();
        break;
    }
    dp[x] = r;
    return r;
}
void dfs2(int x, int ant) {
    if(x != 0) dp[x] *= ant; dp[x] %= m;
    vector<ll> val = {1};
    vector<ll> rval;
    for(auto v : g[x]) {
            val.pb(dp[v] + 1);
            rval.pb(dp[v] + 1);
    }
    rval.pb(1);

    fore(i, 1, val.size()) val[i] *= val[i - 1], val[i] %= m;
    for(int i = rval.size() - 2; i >= 0; i--) rval[i] *= rval[i + 1], rval[i] %= m;
    // fore(i, 0, val.size()) cout << val[i] << " "; cout << endl;
    // fore(i, 0, rval.size()) cout << rval[i] << " "; cout << endl;
    fore(i, 0, g[x].size()) {
        dfs2(g[x][i], (1 + val[i] * rval[i + 1] * ant) % m);
    }
}

