void dfs2(int v, int p = -1, ll d_par = 0) {
    (dp[v] *= (d_par + 1)) %= M;

    vector<ll> rmul;
    rmul.push_back(1);
    for (int i = G[v].size() - 1; i >= 0; --i) {
        int nv = G[v][i];
        if (nv == p)
            continue;
        rmul.push_back(rmul.back() * (dp[nv] + 1) % M);
    }
    reverse(rmul.begin(), rmul.end());

    int cnt = 0;
    ll lmul = 1;
    for (auto nv : G[v]) {
        if (nv == p)
            continue;
        ll tmp = lmul * (rmul[cnt + 1] * (d_par + 1) % M) % M;
        (lmul *= (dp[nv] + 1)) %= M;
        dfs2(nv, v, tmp);
        cnt++;
    }
}

