int mod;

void dfs(int in, int pi, vector<int> adj[], long long dp[]) {
	dp[in] = 1;
	for(auto node: adj[in]) {
		if(node == pi)
			continue;
		dfs(node, in, adj, dp);
		dp[in] = dp[in] * (1+dp[node]) % mod;
	}
}



void dfs2(int in, int pi, vector<int> adj[], long long dp[], long long dp2[]) {
	{
		vector<long long> pref(adj[in].size());
		vector<long long> suff(adj[in].size());
		long long running_prod = 1;
		for(int j=0; j<adj[in].size(); j++) {
			int node = adj[in][j];
			if(node == pi) {
				pref[j] = running_prod;
				continue;
			}
			running_prod = running_prod * (1+dp[node]) % mod;
			pref[j] = running_prod;
		}
		running_prod = 1;
		for(int j=(int)adj[in].size()-1; j>=0; j--) {
			int node = adj[in][j];
			if(node == pi) {
				suff[j] = running_prod;
				continue;
			}
			running_prod = running_prod * (1+dp[node]) % mod;
			suff[j] = running_prod;
		}
		for(int j=0; j<adj[in].size(); j++) {
			int node = adj[in][j];
			if(node == pi)
				continue;
			dp2[node] = dp2[in];
			dp2[node] = dp2[node] * (j-1>=0 ? pref[j-1] : 1) % mod;
			dp2[node] = dp2[node] * (j+1<adj[in].size() ? suff[j+1] : 1) % mod;
			dp2[node] = 1+dp2[node];
		}
	}
	for(auto node: adj[in]) {
		if(node != pi)
			dfs2(node, in, adj, dp, dp2);
	}
}

