const int MAXN = 1e5 + 10;
vector<vector<int>> g(MAXN);
ll dp[MAXN], ans[MAXN];

int N, M;

void exgcd(ll a, ll b, ll &d, ll &x, ll &y) {
  if (!b) {
    d = a;
    x = 1;
    y = 0;
    return;
  }
  exgcd(b, a % b, d, y, x);
  y -= x * (a / b);
}

ll inv(ll a, ll n) {
  ll d, x, y;
  exgcd(a, n, d, x, y);
  x = (x + n) % n;
  return d == 1 ? x : -1;
}

ll blackRoot(int x, int par) {
  ll rb = 1;
  for (int child : g[x]) {
    if (child != par) {
      rb = (rb * (1 + blackRoot(child, x))) % M;
    }
  }
  return dp[x] = rb;
}

void calcAns(int x, int par) {
  if (x == 1) {
    ans[x] = dp[x];
  } else {
    ll inver = inv(1 + dp[x], M);
    if (inver == -1) {
      ans[x] = ((dp[x] + ans[par] - ans[par] / (1 + dp[x])) % M + M) % M;
    } else {
      ans[x] = ((dp[x] + ans[par] - ans[par] * inv(1 + dp[x], M)) % M + M) % M;
    }
  }
  for (int child : g[x]) {
    if (child != par) {
      calcAns(child, x);
    }
  }
}

