  for (int i = 1; i < N; i++) {
    int x, y;
    scanf("%d %d", &x, &y);
    g[x].push_back(y);
    g[y].push_back(x);
  }

  blackRoot(1, 0);
  calcAns(1, 0);
  for (int i = 1; i <= N; i++) {
    printf("%lld\n", ans[i]);
  }
}

