int GM;

void DFS1(int V,int P,vector<vector<int> > & GRAPH, vector<int> & DP)
{
  DP[V] = 1;
  for (auto &i : GRAPH[V])
  {
    if(i == P)continue;
    DFS1(i,V,GRAPH,DP);
    DP[V] *= DP[i]+1;
    DP[V] %= GM;
  }


}
void DFS2(int V,int P,int DP_P,vector<vector<int> > & GRAPH, vector<int> & DP)
{
  int N = GRAPH[V].size();
  vector<int> mul1 (N,0);
  vector<int> mul2 (N,0);
  for (int i = 0; i < N; i++)
  {
    int U = GRAPH[V][i];
    if(U == P)
    {
      mul1[i] = mul2[i] = (DP_P + 1)%GM;
      DP[V] *= DP_P + 1;
      DP[V] %= GM;
    }
    else
    {
      mul1[i] = mul2[i] = (DP[U]+1)%GM;
    }

  }
  for (int i = 0; i < N-1; i++)
  {
    mul1[i+1] *= mul1[i];
    mul1[i+1] %=GM;
  }
  for (int i = N-1; i > 0; i--)
  {
    mul2[i-1] *= mul2[i];
    mul2[i-1] %= GM;
  }
  for (int i = 0; i < N; i++)
  {
    int U = GRAPH[V][i];
    if(U == P)continue;
    int A =(i? mul1[i-1]:1);
    int B = (i+1<N ? mul2[i+1]:1);
    DFS2(U,V,A*B%GM,GRAPH,DP);
  }




}
void solve(void)
{
  int N,M;
   cin>>N>>M;
    vector<vector<int> > GRAPH (N);
   for (int i = 0; i < N-1; i++)
   {
     int A,B;
