long long dfs(vector< vector<int> > &G, vector<long long> &C, int v, int p, int M){
  long long ret = 1;
  for(size_t i = 0; i < G[v].size(); ++i){
    int v_ = G[v][i];
    if(v_ == p) continue;
    ret *= dfs(G,C,v_,v,M) + 1;
    //ret %= M;
  }
  C[v] = ret;
  return ret;
}

void dfs2(vector< vector<int> > &G, vector<long long> &A, vector<long long> &C, int v, int p, int M){
  if(p < 0) A[v] = C[v];
  else{
    long long t = A[p]/(C[v]+1);
    A[v] = (t+1)*C[v];
  }
  for(size_t i = 0; i < G[v].size(); ++i){
    int v_ = G[v][i];
    if(v_ == p) continue;
    dfs2(G,A,C,v_,v,M);
  }
}

