const int MAXN = 100010;
typedef long long ll;

int n, m;

inline int add(int x, int y){return (x+=y)>=m?x-m:x;}
inline int mul(int x, int y){return 1ll*x*y%m;}

struct edge{
	int next, to;
	edge(int N=0,int T=0):next(N),to(T){}
}e[MAXN<<1];
int fir[MAXN], num = 0;
inline void join(int a, int b)
{
	e[++num].next = fir[a];
	fir[a] = num;
	e[num].to = b;
}

int f[MAXN], g[MAXN], ans[MAXN], pre[MAXN], suf[MAXN], t[MAXN], in[MAXN]; 

void dfs1(int u, int fa)
{
	int cnt = 0;
	f[u]    = 1;
	for(int i=fir[u]; i; i=e[i].next)
	{
		int v = e[i].to;
		if(v == fa) continue;
		dfs1(v, u);
		f[u] = mul(f[u], add(f[v], 1));
	}
	for(int i=fir[u];i;i=e[i].next)
		if(e[i].to!=fa)in[++cnt] = e[i].to;
	pre[0] = suf[cnt+1] = 1;
	for(int i=1; i<=cnt; i++)
		pre[i] = mul(pre[i-1], add(f[in[i]], 1));
	for(int i=cnt; i>=1; i--)
		suf[i] = mul(suf[i+1], add(f[in[i]], 1));
	for(int i=1; i<=cnt; i++)
		t[in[i]] = mul(pre[i-1], suf[i+1]);
}
void dfs2(int u, int fa)
{
	int cnt = 0;
	for(int i=fir[u]; i; i=e[i].next)
	{
		int v = e[i].to;
		if(v == fa)continue;
		++cnt;
		g[v] = add(mul(g[u], t[v]), 1);
		ans[v] = mul(g[v], f[v]);
		dfs2(v, u);
	}
}
