Int ans[110000];

void dfs1(int x, int last = -1)
{
	Int prod = 1;
	for (auto to : edge[x]) {
		if (to == last) continue;
		dfs1(to, x);
		prod = prod * dp1[to] % m;
	}
	dp1[x] = prod + 1;
}

void dfs2(int x, int last = -1)
{
	if (last == -1) dp2[x] = 1;
	vector<Int> lprod = vector<Int>(edge[x].size(), 1);
	vector<Int> rprod = vector<Int>(edge[x].size(), 1);

	for (int i = 0; i < edge[x].size(); i++) {
		int to = edge[x][i];
		if (i - 1 >= 0) lprod[i] = lprod[i - 1];
		if (to == last) continue;
		lprod[i] *= dp1[to];
		lprod[i] %= m;
	}

	for (int i = (int)edge[x].size() - 1; i >= 0; i--) {
		int to = edge[x][i];
		if (i + 1 < rprod.size()) rprod[i] = rprod[i + 1];
		if (to == last) continue;
		rprod[i] *= dp1[to];
		rprod[i] %= m;
	}

	for (int i = 0; i < edge[x].size(); i++) {
		int to = edge[x][i];
		if (to == last) continue;
		Int rest_prod = 1;
		if (i - 1 >= 0) rest_prod = rest_prod * lprod[i - 1] % m;
		if (i + 1 < rprod.size()) rest_prod = rest_prod * rprod[i + 1] % m;
		dp2[to] = (dp2[x] * rest_prod + 1) % m;
		dfs2(to, x);
	}
}

void dfs3(int x, int last = -1) 
{
	ans[x] = dp2[x];
	for (auto to : edge[x]) {
		if (to == last) continue;
		ans[x] *= dp1[to];
		ans[x] %= m;
		dfs3(to, x);
	}
}

