		if(!u&&q.size()){
			q.push(u);continue;
		}else if(!u)break;
		int v=*in[u].begin();
		ll res=1;
		for(auto val:pref[u])res=res*val%m;
		res=(res+1)%m;
		out[v].push_back(u);
		pref[v].push_back(res);
		suf[v].push_back(res);
		in[v].erase(u);
		if((v&&in[v].size()==1)||(!v&&in[v].empty()))q.push(v);
