		for(int i=1;i<n;++i){
			pref[u][i]=(ll)pref[u][i]*pref[u][i-1]%m;
			suf[u][n-i-1]=(ll)suf[u][n-i-1]*suf[u][n-i]%m;
		}
		res[u]=suf[u][0];
		for(int i=0;i<n-!!u;++i){
			ll last=1;
			if(i)last*=pref[u][i-1];
			if(i!=n-1)last=last*suf[u][i+1]%m;
			last=(last+1)%m;
			int v=out[u][i];
			out[v].push_back(u);
			pref[v].push_back(last);
			suf[v].push_back(last);
			q.push(v);
		}
	}
	for(int i=0;i<n;++i)cout<<res[i]<<" ";cout<<endl;	
}

