const ll N = 100006;
ll n, Mod;
vector<ll> g[N];
ll ans[N];
vector<ll> L[N], R[N];

void dfs(ll a, ll par) {
  L[a].resize(g[a].size() + 2);
  R[a].resize(g[a].size() + 2);
  L[a].front() = 1;
  R[a].back() = 1;
  for (ll b : g[a]) {
    if (b != par)dfs(b, a);
  }

  for (ll i = 0; i < (ll)g[a].size(); i++) {
    ll b = g[a][i];
    L[a][i + 1] = L[a][i];
    if (b == par)continue;
    L[a][i + 1] *= (L[b].back() + 1);
    L[a][i + 1] %= Mod;
  }
  for (ll i = 0; i < (ll)g[a].size(); i++) {
    ll id = (ll)g[a].size() - i - 1;
    ll b = g[a][id];
    R[a][id + 1] = R[a][id + 2];
    if (b == par)continue;
    R[a][id + 1] *= (L[b].back() + 1);
    R[a][id + 1] %= Mod;
  }
  L[a].back() = R[a].front() = R[a][1];
}

void solve(ll a, ll par, ll K) {
  ans[a] = K * L[a].back() % Mod;
  for (ll i = 0; i < (ll)g[a].size(); i++) {
    ll b = g[a][i];
    if (b == par)continue;
    ll x = L[a][i] * R[a][i + 2] % Mod;
    solve(b, a, (K * x + 1) % Mod);
  }
}

