template <typename X>
struct Edge{
  int from;
  int to;
  X cost;
  int idx;

  Edge() = default;

  Edge(int from, int to, X cost, int idx) : from(from), to(to), cost(cost), idx(idx) {}
};

template <typename X>
struct Node{
  int idx;
  int par;
  X depth;
  vector<Edge<X>> edge;
  map<int,int> to_index;
  vector<X> dp;
  vector<X> lsum, rsum;
  int cnt;

  Node() = default;

  explicit Node(int idx) : idx(idx) {
    cnt = 0;
  }

  void Make_to_index() {
    rep(i,edge.size()) {
      to_index[edge[i].idx] = i;
    }
    to_index[idx] = -1;
    dp.resize(edge.size(), -1);
  }

  void Make_Sum(X id) {
    int n = dp.size();
    lsum.resize(n+1, id);
    rsum.resize(n+1, id);
    rep(i,n) {
      lsum[i+1] = (lsum[i] * (dp[i] + 1)) % M;
    }
    for (int i = n; i > 0; --i) {
      rsum[i-1] = (rsum[i] * (dp[i-1] + 1)) % M;
    }
  }

};

