long long int MOD;

vector<int > adj[100002];
long long down[100002];
long long up[100002];
int par[100002];

long long powMod(long long a, long long b) {
	if(b==-1)
		return 0;
	if( b==0)
		return 1;
	long long c= powMod(a, b/2);
	c*=c;
	c%=MOD;
	if(b%2==1)
		c*=a;
	return c%MOD;
}
long long dfsDown(int s,int p){
	par[s] = p;
	long long ans = 1;
	for(int node: adj[s]) {
		if(node == p)
			continue;
		ans*=(1 + dfsDown(node, s));
		ans%=MOD;
	}

	return down[s] = ans;
}


long long solveUp(int s){

	if(up[s]!=-1)
		return up[s];
	if(s == 0 || s==1)
		return up[s]=0;

	int p= par[s];
	vector<long long> a, pref, suff;
	for(int node : adj[p]) {
		if(node == par[p])
			continue;
		a.push_back(1 + down[node]);
	}

	pref.push_back(a[0]);
	for(int i =1; i<a.size(); i++ )
		pref.push_back( (pref.back() + a[i])%MOD );
	suff.push_back(a.back());
	for(int i= (int)a.size()-2; i>=0;i--)
		suff.push_back( (suff.back() + a[i])%MOD );
	reverse(suff.begin(), suff.end());

	// cout << "a: "<<a<<"\n";
	// cout << "pref: "<<pref<<"\n";
	// cout << "suf: "<<suff<<"\n";

	int in = 0;
	for(int node : adj[p]) {
		if(node == par[p])
			continue;
		long long ans = 1 + solveUp(p);
		long long l = 1;
		long long r= 1;
		if(in-1>=0)
			l = pref[in-1];
		if(in +1 <=(int)suff.size() - 1)
			r =suff[in +1];
		long long m = (l*r)%MOD;
		ans*=m;
		ans%=MOD;
		up[node] = ans;
		in++;
	}
	return up[s];

}
int main() {
    ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n;
	cin >> n >> MOD;
	for(int i=1 ;i <=n-1;i++) {
		int a, b;
		cin >> a >> b;
		adj[a].push_back(b);
		adj[b].push_back(a);
	}

	dfsDown(1, 0);

	memset(up, -1, sizeof up);

	for(int i = 1;i<=n;i++)
		cout << (down[i]*(1 + solveUp(i)) )%MOD<<"\n";





	return 0;
}

