ll DP[MAXN], D[MAXN];
int p[MAXN];
vector<ll> pre[MAXN], suf[MAXN];
ll idxpre[MAXN], idxsuf[MAXN];
vi v[MAXN];

void dfs(int x) {
	//cout << x << '\n';
	REP(i, v[x].size()) {
		int now = v[x][i];
		//cout << x << ' ' << now << "eAAAAA\n";
		if (p[x] == now) continue;
		idxpre[now] = i;
		idxsuf[now] = v[x].size() - 1 - i;
		p[now] = x;
		dfs(now);
	}
}

ll rek(int pos) {
	ll &ret = DP[pos];
	ret = 1;
	REP(i, v[pos].size()) {
		ll now = v[pos][i];
		if (p[pos] == now) {
			pre[pos].pb(ret);
			continue;
		}
		ret = (ret * (1 + rek(now))) % MOD;
		pre[pos].pb(ret);
	}	
	ret = 1;
	for(int i = v[pos].size() - 1; i >= 0; i--) {
		ll now = v[pos][i];
		if (p[pos] == now) {
			suf[pos].pb(ret);
			continue;
		}
		ret = (ret * (1 + rek(now))) % MOD;
		suf[pos].pb(ret);
	}
	return ret;
}

ll rekk(int pos) {
	if (pos == 0) return 1;
	ll &ret = D[pos];
	ll nyok = 1;
	if (idxpre[pos] > 0) nyok = (nyok * pre[p[pos]][idxpre[pos] - 1]) % MOD;
	if (idxsuf[pos] > 0) nyok = (nyok * suf[p[pos]][idxsuf[pos] - 1]) % MOD;
	ret = nyok * rekk(p[pos]) + 1;
	ret %= MOD;
	return ret;
}

