        return first;
    }

    ReverseNumberIterator end() {
        return second;
    }
};


class VSubtree {
public:
    void solve() {
        int N = in.readInt(), M = in.readInt();
        mod = M;
        arri u, v;
        in.readArrays(N - 1, u, v);
        decreaseByOne(u, v);
        Graph<BiEdge> graph(N);
        for (int i : range(N - 1)) {
            graph.addEdge(u[i], v[i]);
        }
        arr<modint> dp(N), ans(N);
        RecursiveFunction dfs1 = [&](auto const &self, int u, int p) -> void {
            dp[u] = modint(1);
            for (auto &e : graph[u]) {
                int v = e.to;
                if (v == p) {
                    continue;
                }
                self(v, u);
                dp[u] *= dp[v];
            }
            dp[u] += modint(1);
        };
        RecursiveFunction dfs2 = [&](auto const &self, int u, int p, modint ways) -> void {
            vector<modint> P, S;
            P.emplace_back(modint(1));
            for (auto &e : graph[u]) {
                int v = e.to;
                if (v == p) {
                    continue;
                }
                P.emplace_back(dp[v]);
                S.emplace_back(dp[v]);
            }
            S.emplace_back(modint(1));
            for (int i : range(1, (int) P.size())) {
                P[i] *= P[i - 1];
            }
            for (int i : RevRange((int) S.size() - 1, 0)) {
                S[i] *= S[i + 1];
            }
            ans[u] = P.back() * ways;
            int i = 0;
            for (auto &e : graph[u]) {
                int v = e.to;
                if (v == p) {
                    continue;
                }
                self(v, u, P[i] * S[i + 1] * ways + modint(1));
                ++i;
            }
        };
        dfs1(0, -1);
        dfs2(0, -1, modint(1));
        for (int i : range(N)) {
            out.printLine(ans[i]);
        }
    }
};

