using namespace std;
typedef long long ll;
const int N = 3e5;
int n, mod;
ll up[N], down[N], ans[N];
vector<int> G[N];
void dfs(int x, int f) {
	down[x] = 1;
	for (int u: G[x]) {
		if (u == f) continue;
		dfs(u, x);
		(down[x] *= down[u] + 1) %= mod;
	}
}
void dfs1(int x, int f) { //cout << x << ",";
	if (x != 1)
		G[x].erase(find(G[x].begin(), G[x].end(), f));
	vector<ll> pre, suf;
	pre.resize(G[x].size() + 1);
	suf.resize(G[x].size() + 1);
	for (int i = 0; i < G[x].size(); ++i) {
		int u = G[x][i];
		pre[i] = down[u] + 1;
	}
	suf[G[x].size() - 1] = pre[G[x].size() - 1];
	for (int i = G[x].size() - 2; i >= 0; --i)
		suf[i] = suf[i + 1] * pre[i] % mod;
	for (int i = 1; i < G[x].size(); ++i)
		pre[i] = pre[i - 1] * pre[i] % mod;
	for (int i = 0; i < G[x].size(); ++i) {
		int u = G[x][i];
		ll tmp = up[x];
		if (i) tmp = tmp * pre[i - 1] % mod;
		if (i < G[x].size() - 1) tmp = tmp * suf[i + 1] % mod;
		(tmp += 1) %= mod;
		up[u] = tmp;
	}
	for (int u: G[x]) dfs1(u, x);
}
