		G[x].push_back(y);
		G[y].push_back(x);
	}
	up[1] = 1;
	dfs(1, 0); 
	dfs1(1, 0);
	for (int i = 1; i <= n; ++i) {
		ll ans = up[i] * down[i] % mod;
		printf("%lld\n", ans);
	}
}

