#include <bits/stdc++.h>

using namespace std;

long long n, mod;
typedef pair<int,int> ii;
static vector<ii> adj[100005];
static vector<long long> dp[100005];

long long dfs(int u, int p){
	if(p != -1 && dp[u][p] != -1) return dp[u][p];
	long long ans = 1;
	for(int i = 0;i < (int)(adj[u].size());i++){
		int v = adj[u][i].first;
		int in = adj[u][i].second;
		if(i != p){
			ans *= (dfs(v,in) + 1);
			ans %= mod; 
		}
	}
	if(p != -1) dp[u][p] = ans;
	return ans;
}

int main(){
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cin >> n >> mod;

	for(int i = 0;i < n - 1;i++){
		int a, b;
		cin >> a >> b;
		a--;
		b--;
		adj[a].push_back(ii(b,adj[b].size()));
		adj[b].push_back(ii(a,adj[a].size()-1));
		dp[a].push_back(-1);
		dp[b].push_back(-1);
	}

	for(int i = 0;i < n;i++) cout << dfs(i,-1) << "\n";
}

