pii eu(long long a,long long b)//extended eucledian to find inverse modulo coprime numbers needn't be prime
{
	if(a==0){return {0,1};}
	if(b==0){return {1,0};}
	long long q=(a/b),r=(a%b);
	pii t=eu(b,r);
	return {t.y,((t.x)-(q*(t.y)))};

}
long long inv(long long num)
{
	if(__gcd(num,mod)!=1){return 0;}
	pii ans=eu(num,mod);
	ans.x=((((ans.x)%mod)+mod)%mod);
	return ans.x;
}
