}

void dfs1(int u = rt, int p = 0) {
    f[u] = 1;
    loop (i, g[u].size()) {
        int v = g[u][i];
        if (v == p)  continue;
        dfs1(v, u);
        f[u] *= f[v] + 1;
        f[u] %= mod;
    }
}

void dfs2(int u = rt, int p = 0) {
    int m = (int) g[u].size();
    num f_u = f[u];
    vector<num> &pre = ::pre[u], &suf = ::suf[u];
    pre.resize(m), suf.resize(m);
    loop (i, m) {
        int v = g[u][i];
        pre[i] = (i - 1 >= 0 ? pre[i - 1] : 1) * (f[g[u][i]] + 1) % mod;
    }
    for (int i = m - 1; i >= 0; --i) {
        suf[i] = (i + 1 < m ? suf[i + 1] : 1) * (f[g[u][i]] + 1) % mod;
    }
    dp[u] = modulo(dp[p] - f[p] + f[u]);
