ll dfs(ll pos, ll par, ll col) {
	if(dp[pos][col] != -1) return dp[pos][col];
	ll ret = 0;
	if(!col) {
		REP(i, g[pos].size()) {
			if(g[pos][i] == par) continue;
			ret += (dfs(g[pos][i], pos, 0) + dfs(g[pos][i], pos, 1) - 1);
		}
