			if(g[pos][i] == par) continue;
			ret *= (1 + dfs(g[pos][i], pos, 1));
			ret %= m;
		}
	}
	return dp[pos][col] = ret % m;
}

void dfs2(ll pos, ll par) {
	ll tmp = info[pos];
	if(pos == 0) tmp = 0;
