ll range(int, int, int, int, int, int);
ll paint(int, int);

void put(int v, int i, int L, int R, int pos, ll x) {
    if (L == R)
        seg[v][i] = x;
    else {
        int M = (L + R) / 2;
        if (pos <= M)
            put(v, 2 * i + 1, L, M, pos, x);
        else
            put(v, 2 * i + 2, M + 1, R, pos, x);
        if (seg[v][2 * i + 1] != -1 && seg[v][2 * i + 2] != -1)
            seg[v][i] = seg[v][2 * i + 1] * seg[v][2 * i + 2] % MOD;
    }
}

ll range(int v, int i, int L, int R, int l, int r) {
    if (l > r)
        return 1;
    else if (l <= L && R <= r && seg[v][i] != -1)
        return seg[v][i];
    else if (L == R) {
        int n = adj[v].size();
        ll x = (1 + paint(adj[v][L], v)) % MOD;
        put(v, 0, 0, n - 1, L, x);
        return seg[v][i];
    } else {
        int M = (L + R) / 2;
        ll result = 1;
        if (l <= M)
            result = result * range(v, 2 * i + 1, L, M, l, r) % MOD;
        if (r > M)
            result = result * range(v, 2 * i + 2, M + 1, R, l, r) % MOD;
        return result;
    }
}

ll paint(int v, int u) {
    pair<int, int> key = {v, u};
    int n = adj[v].size();
    if (!dp.count(key)) {
        if (v == u)
            dp[key] = range(v, 0, 0, n - 1, 0, n - 1);
        else {
            ll result = 1;
            int i = lower_bound(adj[v].begin(), adj[v].end(), u) - adj[v].begin();
            if (i > 0)
                result = result * range(v, 0, 0, n - 1, 0, i - 1) % MOD;
            if (i < n - 1)
                result = result * range(v, 0, 0, n - 1, i + 1, n - 1) % MOD;
            dp[key] = result;
        }
    }
    return dp[key];
}

