void solve(int u, int p) {
    answ[u] = dp[1][u];
    std::reverse(all(adj[u]));
    vi stack0 = {1};
    vi stack1 = {1};
    for (int v : adj[u]) {
        stack1.push_back(int(stack1.back() * 1LL * (dp[0][v] + dp[1][v]) % mod));
        stack0.push_back(int(stack0.back() * 1LL * (dp[0][v]) % mod));
    }
    std::reverse(all(adj[u]));
    int pref0 = 1, pref1 = 1;
    for (int v : adj[u]) {
        stack1.pop_back();
        stack0.pop_back();
