const LL MOD = 1000000007;

LL M = MOD;

vector<vector<int>> edges;
vector<vector<LL>> dp;

//! Fill vars on edges that are visited from the dfs that start from node 0 
LL dfs(int from, int curr) 
{
	LL vars = 1;
	for (int i = 0; i < edges[curr].size(); ++i) {
		if (edges[curr][i] != from) {
			dp[curr][i] = dfs(curr, edges[curr][i]);
			vars = (vars * (dp[curr][i] + 1)) % M;
		}
	}
	return vars;
}

//! Fill vars that are are not filled with dfs
void rev(int from, int curr, LL add) 
{
	for (int i = 0; i < edges[curr].size(); ++i) {
		if (edges[curr][i] == from) {
			dp[curr][i] = add;
			break;
		}
	}

    const int deg = edges[curr].size();
    vector<LL> l(deg), r(deg);
    for (int i = 0; i < deg; ++i) r[i] = ((l[i] = (dp[curr][i] + 1)) %= M);
    for (int i = 1; i < deg; ++i) (l[i] *= l[i - 1]) %= M;
    for (int i = deg - 2; 0 <= i; --i) (r[i] *= r[i + 1]) %= M;

    for (int i = 0; i < deg; ++i) {
        if (edges[curr][i] == from) continue;

        LL add_c = 1;
        if (i != 0) (add_c *= l[i - 1]) %= M;
        if (i != deg - 1) (add_c *= r[i + 1]) %= M;
        rev(curr, edges[curr][i], add_c);
    }
}


