vector<ll> tree[100010];
ll dp[100010] = {};
ll N,M;
ll ans[100010] = {};

void dfs(ll cur, ll par){
    dp[cur] = 1;
    for(auto &e: tree[cur]){
        if(e == par) continue;
        dfs(e, cur);
        dp[cur] *= dp[e];
        dp[cur] %= M;
    }
    dp[cur]++;
}

vector<ll> mul_left[100010], mul_right[100010];
vector<ll> mul[100010];

void dfs2(ll cur, ll par){
    ans[cur] = (dp[cur] - 1 + M) % M;
    ll cc = 1;
    mul_left[cur].push_back(cc);
    for(auto &e: mul[cur]){
        (cc *= dp[e]) %= M;
        mul_left[cur].push_back(cc);
    }
    cc = 1;
    mul_right[cur].push_back(cc);
    reverse(mul[cur].begin(), mul[cur].end());
    for(auto &e: mul[cur]){
        (cc *= dp[e]) %= M;
        mul_right[cur].push_back(cc);
    }
    reverse(mul[cur].begin(), mul[cur].end());

    for(auto &e: tree[cur]){
        if(e == par) continue;
        ll ps = lower_bound(mul[cur].begin(), mul[cur].end(), e) - mul[cur].begin();
        ll sz = mul[cur].size();
        ll val = mul_left[cur][ps] * mul_right[cur][sz - ps - 1] % M;
        // print(cur, val, ps, e, mul_left[cur][ps]);
        ll prev_cur = dp[cur];
        ll prev_e = dp[e];
        dp[cur] = val + 1;
        dp[cur] %= M;
        dp[e] = (dp[e] - 1 + M) * dp[cur] % M + 1;
        dp[e] %= M;
        // dp[cur] = val + 1;
        // dp[cur] %= M;
        dfs2(e, cur);
        dp[cur] = prev_cur;
        dp[e] = prev_e;
    }
}


