ll N;
vector<ll> E[100010];
ll dp[100010];

ll dfs(ll now, ll from){
  ll res = 1;
  for(ll to: E[now])if(to != from){
    res *= dfs(to, now) + 1;
    res %= MOD;
  }
  return dp[now] = res;
}

ll Dar[100010];
void dfs2(ll now, ll from){
  vector<ll> xs;
  vector<ll> TO;
  for(ll to: E[now])if(to != from){
    xs.pb(dp[to] + 1);
    TO.pb(to);
  }
  ll M = xs.size();
  vector<ll> left(M+1), right(M+1);
  left[0] = 1;
  right[M] = 1;
  rep(i, M) left[i+1] = left[i] * xs[i] % MOD;
  revrep(i, M) right[i] = right[i+1] * xs[i] % MOD;
  rep(i, M){
    Dar[TO[i]] = Dar[now] * left[i] % MOD * right[i+1] % MOD + 1;
  }
  rep(i, M) dfs2(TO[i], now);
}

