ll M;
vector<vector<ll>> adjusts;
vector<map<ll, ll>> dp;

ll evaluate(ll F, ll B) {
	if (dp[F].find(B) != dp[F].end())return dp[F][B];

	ll res = 1;
	for (ll node : adjusts[B]) {
		if (node == F)continue;
		(res *= evaluate(B, node)) %= M;
	}
	return dp[F][B] = (res + 1) % M;
}

