#define ll long long
using namespace std;
ll dp1[1000001];
ll dp2[1000001];
vector<ll> tree[100001];
ll m;
void solve2(ll source,bool vis[],ll parent_ans)
{
	vis[source]=1;
	dp2[source]=((1+parent_ans)*dp1[source])%m;
	vector<ll> prefix;
	vector<ll> suffix;
	for(ll child:tree[source])
	{
		if(!vis[child])
		{
			prefix.push_back(1+dp1[child]);
			suffix.push_back(1+dp1[child]);
		}
	}
	for(ll z=suffix.size()-2;z>=0;z--)
	{
		suffix[z]=(suffix[z]*suffix[z+1])%m;
	}
	for(ll z=1;z<prefix.size();z++)
	{
		prefix[z]=(prefix[z]*prefix[z-1])%m;
	}
	ll child_number=0;
	for(ll child:tree[source])
	{
		if(!vis[child])
		{
			ll ways=(1+parent_ans);
			ways= (child_number>0) ? (ways * (prefix[child_number-1]))%m : ways;
			ways= (child_number<(suffix.size()-1)) ? (ways*(suffix[child_number+1]))%m :ways;
			solve2(child,vis,ways);
			child_number++;
		}
	}
}
void solve1(ll source,bool vis[])
{
	vis[source]=1;
	dp1[source]=1;
	for(ll child:tree[source])
	{
		if(!vis[child])
		{
			solve1(child,vis);
			dp1[source] = (dp1[source]*(1+dp1[child]))%m;
		}
	}
}
int main()
{
	ll n;
	cin>>n>>m;
	ll edge=n-1;
	while(edge--)
	{
		ll u,v;
		cin>>u>>v;
		tree[u].push_back(v);
		tree[v].push_back(u);
	}
	bool vis[n+1];
	memset(vis,0,sizeof(vis));
	solve1(1,vis);
	memset(vis,0,sizeof(vis));
	solve2(1,vis,0);
	for(ll p=1;p<=n;p++)
		cout<<dp2[p];
	cout<<endl;
}

