void dfsDown(int v) {
	used[v] = 1;
    down[v] = 1;

	for (auto it : e[v]) {
		if (!used[it]) {
			dfsDown(it);
            down[v] = down[v] * (down[it] + 1) % m;
		}
	}
}

void dfsUp(int v) {
    vector <int> pref(e[v].size() + 2), suff(e[v].size() + 2);
    pref[0] = up[v];
    suff[suff.size() - 1] = 1;
    used[v] = 1;

    for (int i = 0; i < e[v].size(); i++)
        pref[i + 1] = pref[i] * 1LL * (used[e[v][i]] ? 1 : (down[e[v][i]] + 1)) % m;

    for (int i = e[v].size() - 1; i > -1; i--)
        suff[i + 1] = suff[i + 2] * 1LL * (used[e[v][i]] ? 1 : (down[e[v][i]] + 1)) % m;

    for (int i = 0; i < e[v].size(); i++) {
        if (!used[e[v][i]]) {
            up[e[v][i]] = (1 + pref[i] * 1LL * suff[i + 2]) % m;
            dfsUp(e[v][i]);
        }
    }
}

