      fBlack[v] *= (fBlack[to] + 1) % mod;
      fBlack[v] %= mod;
    }
    if (p != -1) {
      g[v].erase(find(all(g[v]), p));
    }
  };
  dfs1(0, -1);
  dbg(fBlack);

  function<void(int, int, int64_t)> dfs = [&](int v, int p, int64_t upMul) {
    if (p != -1) {
      fUp[v] = (1 + upMul) % mod;
    } else {
      fUp[v] = 1 % mod;
    }

    if (g[v].empty()) return;
    vec<int64_t> suffix(g[v].size());
    suffix[g[v].size() - 1] = (fBlack[ g[v].back() ] + 1) % mod;
    for (int i = (int) g[v].size() - 2; i >= 0; --i) {
      int64_t c = (fBlack[g[v][i]] + 1) % mod;
      suffix[i] = (suffix[i + 1] * c) % mod;
    }

    int64_t u = 1;
    if (p != -1) u = (upMul + 1) % mod;
    int64_t pr = 1, su;
    FOR(i, g[v].size()) {
      int to = g[v][i];

      if (i + 1 >= g[v].size()) {
        su = 1;
      } else {
        su = suffix[i + 1];
      }

      int64_t d = (pr * su) % mod;
      d *= u;
      d %= mod;
//      ++d;
//      d %= mod;

      dfs(to, v, d);
      pr = (pr * (fBlack[to] + 1) % mod) % mod;
    }
  };
  dfs(0, -1, 1);
  dbg(fUp);
  FOR(i, n) {
    out << (fBlack[i] * fUp[i]) % mod << "\n";
  }
}

