struct Tree {
	struct Node {
		int stdl, stdr;
		ll mul;
		Node() : mul(1) {}
	};
	int n, p;
	vector<Node> tree;
	Tree() : n(0), p(0) {}
	Tree(int x, int y) {
		n = x + 1;
		p = y;
		tree.resize(n << 2);
		buildtree(1, 1, n);
	}
	inline void buildtree(int root, int l, int r) {
		tree[root].stdl = l;
		tree[root].stdr = r;
		if (l == r) return;
		int mid = (l + r) >> 1;
		buildtree(root << 1, l, mid);
		buildtree(root << 1 | 1, mid + 1, r);
	}
	inline void pushdown(int root) {
		tree[root << 1].mul = (tree[root << 1].mul * tree[root].mul) % p;
		tree[root << 1 | 1].mul = (tree[root << 1 | 1].mul * tree[root].mul) % p;
		tree[root].mul = 1;
	}
	inline void ride(int root, int l, int r, ll k) {
		if (r < tree[root].stdl || l > tree[root].stdr) return;
		if (l <= tree[root].stdl && tree[root].stdr <= r) {
			tree[root].mul = (tree[root].mul * k) % p;
			return;
		}
		pushdown(root);
		ride(root << 1, l, r, k);
		ride(root << 1 | 1, l, r, k);
	}
	inline ll query(int root, int l, int r) {
		if (r < tree[root].stdl || l > tree[root].stdr) return 0;
		if (l <= tree[root].stdl && tree[root].stdr <= r) return tree[root].mul;
		pushdown(root);
		return (query(root << 1, l, r) + query(root << 1 | 1, l, r)) % p;
	}
};
const int MAXN = 1e5 + 7;
int n, m, dp[MAXN], res[MAXN];
