inline void dfs(int w, int pre) {
	dp[w] = 1;
	fval[w] = Tree(edge[w].size(), m);
	rep (j, 0, (int)edge[w].size()-1) {
		int i = edge[w][j];
		if (i == pre) continue;
		dfs(i, w);
		dp[w] = (dp[i] + 1ll) * dp[w] % m;
		if (j) fval[w].ride(1, 1, j, dp[i]+1);
		if (j + 1 != (int)edge[w].size() ) fval[w].ride(1, j + 2, edge[w].size(), dp[i]+1);
	}
	rep (j, 0, (int)edge[w].size()-1) {
		int i = edge[w][j];
		if (i == pre) continue;
		res[i] = fval[w].query(1, j+1, j+1);
	}
}
inline void solve(int w, int pre) {
	if (w != 1) {
		dp[w] = (res[w] + 1) * 1ll * dp[w] % m;
		for (auto i : edge[w]) {
			res[i] = (res[w] + 1) * 1ll * res[i] % m;
		}
	}
	for (auto i : edge[w]) {
		if (i == pre) continue;
		solve(i, w);
	}
}
