int add(int a, int b) { if ((a += b) >= MOD) a -= MOD; return a; }
int mul(int a, int b) { return 1LL * a * b % MOD; }

void dfs(int u, int par) {
  REP(i, SZ(g[u])) if (g[u][i] == par) {
    swap(g[u][i], g[u].back());
    g[u].pop_back();
    break;
  }
  pref[u].resize(SZ(g[u]));
  suff[u].resize(SZ(g[u]));
  REP(i, SZ(g[u])) {
    int v = g[u][i];
    dfs(v, u);
    pref[u][i] = add(dp[v], 1);
    suff[u][i] = add(dp[v], 1);
  }
  FOR(i, 1, SZ(g[u]) - 1) pref[u][i] = mul(pref[u][i], pref[u][i - 1]);
  FORD(i, SZ(g[u]) - 2, 0) suff[u][i] = mul(suff[u][i], suff[u][i + 1]);
  dp[u] = SZ(g[u]) ? pref[u].back() : 1;
}

void solve(int u, int parDp) {
  ans[u] = mul(dp[u], add(parDp, 1));
  REP(i, SZ(g[u])) {
    int rem = mul(i > 0 ? pref[u][i - 1] : 1, i + 1 < SZ(g[u]) ? suff[u][i + 1] : 1);
    int v = g[u][i];
    solve(v, mul(rem, add(parDp, 1)));
  }
}

