void dfs(int u, int p)
{
	for (int v : edge[u])
	{
		if (v == p) continue;
		dfs(v, u);
	}
	dp[u] = 1;
	for (int v : edge[u])
	{
		if (v == p) continue;
		dp[u] *= (dp[v] + 1); dp[u] %= MOD;
	}
	// cerr << u << ' ' << dp[u][0] << ' '  << dp[u][1] << endl;
}
void dfs1(int u, int p)
{
	vl pref(SZ(edge[u]) + 1), suf(SZ(edge[u]) + 1);
	pref[0] = 1;
	FOR(i, 0, SZ(edge[u]))
	{
		int v = edge[u][i];
		if (v == p)
		{
			pref[i + 1] = pref[i];
			continue;
		}
		pref[i + 1] = pref[i] * (dp[v] + 1); pref[i + 1] %= MOD;
	}
	suf[SZ(edge[u])] = 1;
	FORD(i, SZ(edge[u]), 0)
	{
		int v = edge[u][i];
		if (v == p)
		{
			suf[i] = suf[i + 1];
			continue;
		}
		suf[i] = suf[i + 1] * (dp[v] + 1); suf[i] %= MOD:
	}
	FOR(i, 0, SZ(edge[u]))
	{
		int v = edge[u][i];
		if (v == p) continue;
		dp1[v] = pref[i] * suf[i + 1] % MOD * (dp1[u] + 1) % MOD;
	}
	for (int v : edge[u])
	{
		if (v == p) continue;
		dfs1(v, u);
	}
}

