ll n, mod, dp[N], ans[N], seg[4*N];
vector < ll > g[N];

void up(ll k, ll bas, ll son, ll x, ll y){
	if(bas == son){
		seg[k] = y;
		return;
	}
	if(x <= orta)
		up(sol, bas, orta, x, y);
	else
		up(sag, orta + 1, son, x, y);
	seg[k] = seg[sol]*seg[sag]%mod;
}

ll qu(ll k, ll bas, ll son, ll x, ll y){
	if(bas >= x and son <= y)
		return seg[k];
	if(bas > y or son < x)
		return 1;
	return qu(sol, bas, orta,x , y)*qu(sag, orta + 1, son, x, y)%mod;
}

void dfs(ll node, ll par, ll ust){
	// cout << node << " -> " << dp[node] << " " << ust << endl;
	ans[node] = dp[node]*( (ust + 1)%mod )%mod;

	for(ll i = 0; i < g[node].size(); i++){
		if(g[node][i] == par){
			up(1, 1, n, i + 1, 1);
			continue;
		}
		up(1, 1, n, i + 1, (dp[g[node][i]] + 1)%mod );
		// cout << "AMK" << node << " -> " << i  << " " << g[node][i]<<  " = " << (dp[g[node][i]] + 1)%mod << endl;
	}
	// cout << qu(1, 1, n, 1, 1) << endl;
	vector < ll > git;
	git.resize((int)g[node].size());
	for(ll i = 0; i < g[node].size(); i++){
		if(g[node][i] == par)
			continue;
		ll sl = qu(1, 1, n, 1, i);
		ll sg = qu(1, 1, n, i + 2, (int)g[node].size());
		// cout << node << " tooo " << g[node][i] << " " << sl << " " << sg << endl;
		git[i] = ((sl*sg%mod)*( (ust + 1)%mod )%mod)%mod;
		// dfs(g[node][i], node, ((sl*sg%mod)*(ust + 1)%mod) );
	}
	for(ll i = 0; i < g[node].size(); i++){
		if(g[node][i] == par)
			continue;
		dfs(g[node][i], node, git[i] );

	}
}

void bul(ll node, ll par){
	dp[node] = 1;
	for(ll i = 0; i < g[node].size(); i++)
		if(g[node][i] != par){
			bul(g[node][i], node);
			dp[node] = dp[node]*( (dp[g[node][i]] + 1)%mod )%mod;
		}
}

