#include <bits/stdc++.h>
#define REP(i, n) for (decltype(n) i = 0; i < (n); ++i)
using namespace std;
using Int = long long;
Int N, M;
vector<vector<int>> adj;
vector<unordered_map<int, Int>> sub;
vector<vector<Int>> lprod, rprod;

Int dfs(int node, int parent) {
  if (parent >= 0) {
    auto it = sub[parent].find(node);
    if (it != sub[parent].end()) return it->second;
  }
  Int r = 1;
  vector<Int> cs(adj[node].size(), 1);
  REP(i, adj[node].size()) {
    int child = adj[node][i];
    if (child == parent) {
      cs[i] = 1;
      continue;
    }
    Int c = 1 + dfs(child, node);
    cs[i] = c;
    r = r * c % M;
  }
  lprod[node].resize(cs.size() + 1, 1);
  rprod[node].resize(cs.size() + 1, 1);
  REP(i, cs.size()) {
    lprod[node][i + 1] = lprod[node][i] * cs[i] % M;
    rprod[node][cs.size() - 1 - i] =
        rprod[node][cs.size() - i] * cs[cs.size() - 1 - i] % M;
  }
  if (parent >= 0) {
    sub[parent][node] = r;
  }
  return r;
};

void solve() {
  vector<Int> ans(N);
  ans[0] = dfs(0, -1);
  auto dfs2 = [&](auto rec, int node, int parent, Int acc) -> void {
    REP(i, adj[node].size()) {
      int child = adj[node][i];
      if (child == parent) continue;
      ans[child] = sub[node][child];
      Int q = lprod[node][i] * rprod[node][i + 1] % M;
      ans[child] += sub[node][child] * q % M * (1 + acc) % M;
      ans[child] %= M;
      rec(rec, child, node, q);
    }
  };
  dfs2(dfs2, 0, -1, 0);
  for (int i = 0; i < N; ++i) {
    cout << ans[i] << "\n";
  }
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  cin >> N >> M;
  adj.resize(N);
  sub.resize(N);
  lprod.resize(N);
  rprod.resize(N);
  for (int i = 0; i < N - 1; i++) {
    int x, y;
    cin >> x >> y;
    x--;
    y--;
    adj[x].push_back(y);
    adj[y].push_back(x);
  }
  solve();
}

#include <bits/stdc++.h>
using namespace std;
vector<vector<int>> graph,vals2,dp2,dp3;
int n,m,dp[100001],updp[100001];

int getans(int curr , int tag){
	if(curr == dp2[tag].size()){
		return 1;
	}
	if(dp2[tag][curr] != -1){
		return dp2[tag][curr];
	}
	long long ret = getans(curr+1,tag) + (vals2[tag][curr]*getans(curr+1,tag));
	ret %= m;
	return dp2[tag][curr] = ret;
}

int getans2(int curr , int tag){
	if(curr == -1){
		return 1;
	}
	if(dp3[tag][curr] != -1){
		return dp3[tag][curr];
	}
	long long ret = getans2(curr-1,tag) + vals2[tag][curr]*getans2(curr-1,tag);
	ret %= m;
	return dp3[tag][curr] = ret;
}

void dfs(int curr , int par){
	vector<int> vals;
	for(int i : graph[curr]){
		if(i != par){
			dfs(i,curr);
			vals.push_back(dp[i]);
		}
	}
	vals2[curr] = vals;
	dp2[curr].assign(vals.size(),-1);
	dp3[curr].assign(vals.size(),-1);
	dp[curr] = getans(0,curr);
}

void dfs2(int curr , int par){
	int cnt = 0;
	for(int i : graph[curr]){
		if(i == par){
			continue;
		}
		updp[i] = updp[curr]*getans(cnt+1,curr)*getans2(cnt-1,curr)+1;
		cnt += 1;
		dfs2(i,curr);
	}
}

