template <typename T>
class Rerooting{
public:
	vector<vector<int>> edge;
	vector<map<int,T>> memo;
	vector<map<int,T>> sumL;
	vector<map<int,T>> sumR;

	struct Solver {
		virtual T init() const = 0;
		virtual T merge(T, T) const = 0;
		virtual T add_me(T) const = 0;
	};
	const Solver *solver;

	const T init_value;

	Rerooting(
			int N,
			const Solver *solver
	) :
		edge(N),
		memo(N),
		sumL(N),
		sumR(N),
		solver(solver),
		init_value(solver->init())
	{ }

	void add_edge(int u, int v){
		edge[u].push_back(v);
		edge[v].push_back(u);
	}

	T dfs(int n, int b = -1) {
		T ret = init_value;
		for(auto t: edge[n]) if(t != b){
			ret = solver->merge(ret, dfs(t, n));
		}
		return memo[n][b] = solver->add_me(ret);
	}

	void dfs2(int n, int b = -1) {
		// 累積を計算しておく
		T sum = init_value;
		rep(i, edge[n].size()){
			int t = edge[n][i];
			sumL[n][t] = sum;
			sum = solver->merge(sum, memo[t][n]);
		}
		sum = init_value;
		rrep(i, edge[n].size()){
			int t = edge[n][i];
			sumR[n][t] = sum;
			sum = solver->merge(sum, memo[t][n]);
		}

		// 累積から逆方向の辺を計算
		for(auto t: edge[n]) if(t != b) {
			auto ret = solver->merge(sumL[n][t], sumR[n][t]);
			memo[n][t] = solver->add_me(ret);
			dfs2(t, n);
		}
		memo[n][-1] = solver->add_me(sum);
	}

	T solve(int n){
		const int b = -1;
		if(memo[n].count(b)) return memo[n][b];

		dfs(n);
		dfs2(n);

		return memo[n][b];
	}
};

struct Solver: Rerooting<ll>::Solver {
	ll init() const override {
		return 1;
	}

	ll merge(ll a, ll b) const override {
		return a * b % MOD;
	}

	ll add_me(ll a) const override {
		return a + 1;
	}
};

int main(){
	ios_base::sync_with_stdio(false);

	int N;
	cin >> N >> MOD;
	Rerooting<ll> rr(N, new Solver());
	rep(i,N-1){
		int a, b;
		cin >> a >> b;
		a--; b--;
		rr.add_edge(a, b);
	}

	rep(i,N) cout << rr.solve(i) - 1 << "\n";

	return 0;
}

