    auto f=[&](ll a, int v) {(void)v; return (a+1)%M;};
    ll unity = 1;
    auto g=[&](ll a, ll b) {return a*b%M;};
    auto h=[](ll a, int v) {(void)v; return a;};
    Rerooting R(N,f,g,h,unity);
    rep(i,N-1) {
        int u,v; cin >> u >> v;
        --u; --v;
        R.add_edge(u,v);
    }
    R.build();
