typedef long long LL;

LL ec = 0,hed[100005] = {0},nxt[200005],to[200005];
void add_edge(LL f,LL t){
	++ ec; to[ec] = t; nxt[ec] = hed[f]; hed[f] = ec;
}

LL n,N,a,b;
LL dp[100005] = {0},ans[100005] = {0};
LL p[100005];
LL pre[100005],suf[100005],sum[100005];

void dfs1(LL u,LL f){
	LL tot = 0;
	dp[u] = 1 % N;
	for(LL i = hed[u];i;i = nxt[i]){
		LL v = to[i];
		if(v == f) continue;
		dfs1(v,u);
		dp[u] = dp[u] * dp[v];
		dp[u] %= N;
	}
	for(LL i = hed[u];i;i = nxt[i]) p[++ tot] = to[i];
	dp[u] ++; dp[u] %= N;
	pre[0] = 1LL; suf[tot + 1] = 1LL;
	for(LL i = 1;i <= tot;i ++) pre[i] = (pre[i - 1] * dp[p[i]]) % N;
	for(LL i = tot;i >= 1;i --) suf[i] = (suf[i + 1] * dp[p[i]]) % N;
	for(LL i = 1;i <= tot;i ++) sum[p[i]] = (pre[i - 1] * suf[i + 1]) % N;
}

void dfs2(LL u,LL f){
	if(u == 1) ans[u] = 1LL;
	else ans[u] = (ans[f] * sum[u] + 1) % N;
	for(LL i = hed[u];i;i = nxt[i]){
		LL v = to[i];
		if(v == f) continue;
		dfs2(v,u);
	}
}

