    int cnt = 0;
    vector<ll> v;
    for(auto x:g[k]){
        if(x!=pre){
            tmp *= (dfs(x,k)+1)%m;
            tmp %= m;
            mp[k][x] = cnt;
            cnt++;
            v.PB(p[x]+1);
        }
    }
    segtree<ll> sgt(v);
    sg[k] = sgt;
    return p[k] = tmp;
}
void dfs2(int k,int pre){
    if(k==0){
        q[k] = 1;
    }else{
        ll tmp = 1;
        tmp *= sg[pre].query(0,mp[pre][k]);
        tmp %= m;
        tmp *= sg[pre].query(mp[pre][k]+1,mp[pre].size());
        tmp %= m;
        q[k] = (tmp*q[pre]+1)%m;
    }
    for(auto x:g[k]){
        if(x!=pre){
            dfs2(x,k);
        }   
    }
}
