void dfs2(int v,int pa) {
  //cout<<"view "<<v<<" "<<pa<<" "<<d[v]<<endl;
  STree st(ch[v].size());
  fore(i,0,ch[v].size())st.upd(i,s[ch[v][i]]+1);
  fore(i,0,ch[v].size()) {
    ll a=st.query(0,i);
    ll b=st.query(i+1,ch[v].size());
    d[ch[v][i]]=((((d[v]+1)*a)%MOD)*b)%MOD;
    //cout<<v<<" : "<<ch[v][i]<<" "<<a<<" "<<b<<" "<<d[ch[v][i]]<<endl;
    dfs2(ch[v][i],v);
  }
  if(v) {
    //cout<<"r["<<v<<"]="<<d[v]<<" "<<st.query(0,ch[v].size())<<endl;
    r[v]=((d[v]+1)*st.query(0,ch[v].size()))%MOD;
  }
  else r[v]=s[v];
}

