void dochild(int at,int par) {
	LL ans = 1;
	for (int i=0; i<e[at].size(); i++) {
		int c = e[at][i];
		if (c == par) continue;
		dochild(c,at);
		ans *= dpc[c]+1; ans %= mod;
	}
	//printf("At %d = %d\n",at,ans);
	dpc[at] = ans;
}

void doparent(int at,int par) {
	LL ans = 1;
	for (int i=0; i<e[at].size(); i++) {
		int c = e[at][i];
		if (c == par) continue;
		ans *= dpc[c]+1; ans %= mod;
		pre[i] = ans;
	}
	ans = 1;
	for (int i=((int)e[at].size())-1; i>=0; i--) {
		int c = e[at][i];
		if (c == par) continue;
		ans *= dpc[c]+1; ans %= mod;
		suf[i] = ans;
	}
	for (int i=0; i<e[at].size(); i++) {
		int c = e[at][i];
		if (c == par) continue;
		int prev = 1,next = 1;
		int pid = i-1,nid = i+1;
		if (pid >= 0 && e[at][pid] == par) pid--;
		if (nid < e[at].size() && e[at][nid] == par) nid++;

		if (pid >= 0) prev = pre[pid];
		if (nid < e[at].size()) next = suf[nid];
		//printf("  c = %d: d %d p %d n %d\n",c,dpp[at],prev,next);
		dpp[c] = (((prev*1LL*next)%mod)*dpp[at]+1)%mod;
	}

	for (int i=0; i<e[at].size(); i++) {
		int c = e[at][i];
		if (c == par) continue;
		doparent(c,at);
	}
}

