ll dpin[maxn],dpout[maxn],mod;
int n,father[maxn];
vector <int> g[maxn];

void dfs1(int x,int fa){
	father[x]=fa;
	ll ret=1ll;
	for(int i=0;i<g[x].size();i++){
		int to=g[x][i];
		if(to==fa) continue;
		dfs1(to,x);
		ret=(ret*dpin[to])%mod;
	}
	dpin[x]=(ret+1)%mod;
}

void dfs2(int x,int fa){
	vector <ll> v1,v2;
	for(int i=0;i<g[x].size();i++){
		int to=g[x][i];
		if(to==fa) v1.pb(1ll),v2.pb(1ll);
		else v1.pb(dpin[to]),v2.pb(dpin[to]);
	}
	for(int i=1;i<v1.size();i++) v1[i]=(v1[i-1]*v1[i])%mod;
	for(int i=v2.size()-2;i>=0;i--) v2[i]=(v2[i+1]*v2[i])%mod;
	for(int i=0;i<g[x].size();i++){
		int to=g[x][i];
		if(to==fa) continue;
		ll ret=1;
		if(i>0) ret=(ret*v1[i-1])%mod;
		if(i<v2.size()-1) ret=(ret*v2[i+1])%mod;
		ret=(ret*dpout[x])%mod;
		ret=(ret+1)%mod;
		dpout[to]=ret;
		dfs2(to,x);
	}
}

