		ll ans=dpout[i];
		for(int j=0;j<g[i].size();j++){
			int to=g[i][j];
			if(to==father[i]) continue;
			ans=(ans*dpin[to])%mod;
		}
		printf("%d\n",ans);
	}
	return 0;
}

