#include <bits/stdc++.h>
using namespace std;
const int N = 1e5 + 100;
int n;
long long m;
vector<int> adjList[N];
vector<long long> wout[N];
long long dp[N], ans[N];

void dfs1(int v, int p) {
	dp[v] = 1;

	for (int u : adjList[v]) {
		if (u == p) continue;
		dfs1(u, v);
		dp[v] = (dp[v] * dp[u]) % m;
	}
	dp[v] = (dp[v] + 1) % m;

	int s = adjList[v].size() - (p ? 1 : 0);
	int idx;

	long long pref[s + 2];
	pref[0] = 1;
	idx = 1;
	for (int i = 1; i <= s; i++) {
		int u = adjList[v][i - 1];
		if(u == p) continue;
		pref[idx] = (pref[idx - 1] * dp[u]) % m;
		idx++;
	}

	long long suf[s + 2];
	suf[s + 1] = 1;
	idx = s;
	for (int i = s; i > 0; i--) {
		int u = adjList[v][i - 1];
		if(u == p) continue;
		suf[idx] = (suf[idx + 1] * dp[u]) % m;
		idx--;
	}

	wout[v].resize(s);

	for (int i = 1; i <= s; i++) {
		wout[v][i - 1] = (pref[i - 1] * suf[i + 1]) % m;
	}
}

void dfs2(int v, int p) {
	ans[v] = dp[v];
	int s = adjList[v].size();

	int idx = 0;
	for (int u : adjList[v]) {
		if (u == p) continue;
		dp[u] = (m - 1LL + dp[u]) % m;
		dp[u] = (dp[u] * wout[v][idx]) % m;
		for (long long &x : wout[u]) {
			x = (x * wout[v][idx] + 1LL) % m;
		}
		dfs2(u, v);
		idx++;
	}
}

int main() {
	ios_base::sync_with_stdio(0);
	cin.tie(0);

	cin >> n >> m;

	int a, b;
	for (int i = 1; i < n; i++) {
		cin >> a >> b;
		adjList[a].emplace_back(b);
		adjList[b].emplace_back(a);
	}

	dfs1(1, 0);
	dp[1] = (dp[1] + m - 1) % m;
	for (long long &x : wout[1]) {
		x = (x + 1LL) % m;
	}
	dfs2(1, 0);

	for (int i = 1; i <= n; i++) {
		cout << ans[i] << '\n';
	}

	return 0;
}

#include <bits/stdc++.h>

#define N_MAX 100002
#define ll long long

using namespace std;

int n;

ll m;

vector <int> edges[N_MAX];

int parent[N_MAX];

vector <int> sons[N_MAX];

bool visited[N_MAX];

void dfs (int node)
{
    visited[node] = true;
    for(int u : edges[node])
        if(visited[u] == false)
        {
            parent[u] = node;
            sons[node].push_back(u);
            dfs(u);
        }
}

ll up[N_MAX], down[N_MAX];

void computeDown (int node)
{
    down[node] = 1;
    for(int u : sons[node])
    {
        computeDown(u);
        down[node] = down[node] * (down[u] + 1) % m;
    }
}

ll dw[N_MAX];

void computeUp (int node)
{
    up[node] += 1;
    if(up[node] >= m)
        up[node] -= m;
    dw[sons[node].size()] = 1;
    for(int i = sons[node].size() - 1; i >= 0; i--)
        dw[i] = dw[i + 1] * (down[sons[node][i]] + 1) % m;
    ll dw1 = 1;
    for(int i = 0; i < sons[node].size(); i++)
    {
        int u = sons[node][i];
        up[u] = dw1 * dw[i + 1] % m * up[node] % m;
        dw1 = dw1 * (down[u] + 1) % m;
        computeUp(u);
    }
}

int main()
{
    cin >> n >> m;
    for(int i = 1; i < n; i++)
    {
        int u, v;
        cin >> u >> v;
        edges[u].push_back(v);
        edges[v].push_back(u);
    }
    dfs(1);
    computeDown(1);
    computeUp(1);
    for(int i = 1; i <= n; i++)
        cout << down[i] * up[i] % m << "\n";
    return 0;
}

