	}

	bool vis[n + 1];
	memset(vis, 0 , sizeof vis);

	solve1(1, vis);
	memset(vis, 0 , sizeof vis);

	solve2(1, vis, 0);
	for (ll i = 1; i <= n; i++)
		cout << dp2[i] % m << endl;
	return 0;
}

