long long int MOD;

vector<int > adj[100002];
long long down[100002];
long long up[100002];
int par[100002];

long long dfsDown(int s,int p){
	par[s] = p;
	long long ans = 1;
	for(int node: adj[s]) {
		if(node == p)
			continue;
		ans*=(1 + dfsDown(node, s));
		ans%=MOD;
	}

	return down[s] = ans;
}


long long solveUp(int s){

	if(up[s]!=-1)
		return up[s];
	if(s == 0 || s==1)
		return up[s]=0;

	int p= par[s];
	vector<long long> a, pref, suff;
	for(int node : adj[p]) {
		if(node == par[p])
			continue;
		a.push_back(1 + down[node]);
	}

	pref.push_back(a[0]%MOD);
	for(int i =1; i<a.size(); i++ )
		pref.push_back( (pref.back() * a[i])%MOD );
	suff.push_back(a.back()%MOD);
