LL mod, n, dp[N], ans[N], fav[N];
VI g[N], L[N], R[N], son[N], ind[N];

void dfs1(int u, int fa) {
    dp[u] = 1;
    for(auto v : g[u]) if(v != fa) ind[u].pb(v);
    sort(all(ind[u]));
    for(auto v : ind[u]) {
        dfs1(v, u);
        son[u].pb((1+dp[v])%mod);
        dp[u] = 1LL * dp[u] * (1+dp[v]) % mod;
    }
    int sz = SZ(son[u]);
    if(sz) L[u].pb(son[u][0]), R[u].pb(son[u][sz-1]);
    rep(i, 1, sz-1) L[u].pb(1LL * L[u][i-1] * son[u][i] % mod);
    per(i, sz-2, 0) R[u].pb(1LL * R[u][sz-i-2] * son[u][i] % mod);
    assert(SZ(L[u]) == SZ(R[u]));
}

void dfs2(int u, int fa) {
    for(auto v : g[u]) if(v != fa) {
        int p = lower_bound(all(ind[u]), v)-ind[u].begin();
        int tmp = 1;
        if(p) tmp = 1LL * tmp * L[u][p-1] % mod;
        if(p < SZ(L[u])-1) tmp = 1LL * tmp * R[u][SZ(R[u])-2-p] % mod;
        fav[v] = 1LL * (1+fav[u]) * tmp % mod;
        dfs2(v, u);
    }
}

