    for (int i=0; i<D; ++i) {
        assert(IN(i, 0, dp[u].size()));
        acc_left[i+1] = (acc_left[i] * (dp[u][i] + 1)) % MOD;
    }
    for (int i=D-1; i>=0; --i) {
