// [0, pi]
ll leftProduct(int u, int pi) {
  if (pi == -1) return 1;
  if (lpMemo[u][pi] != -1) return lpMemo[u][pi];

  return lpMemo[u][pi] =
             (subtreeCount(G[u][pi], u) + 1) * leftProduct(u, pi - 1) % M;
}

// [pi, G[u].siize())
ll rightProduct(int u, int pi) {
  if (pi == G[u].size()) return 1;
  if (rpMemo[u][pi] != -1) return rpMemo[u][pi];

  return rpMemo[u][pi] =
             (subtreeCount(G[u][pi], u) + 1) * rightProduct(u, pi + 1) % M;
}

int subtreeCount(int u, int p) {
  if (p == -1) return leftProduct(u, G[u].size() - 1);

  return leftProduct(u, id[u][p] - 1) * rightProduct(u, id[u][p] + 1) % M;
}

