void dfs1(int u, int p) {
	for (int uu : e[u])
		if (uu != p) dfs1(uu, u);
	for (int i = 0; i < e[u].size(); i++) {
		int uu = e[u][i];
		pre[u][i] = i ? pre[u][i-1] : 1;
		if(uu != p)
			pre[u][i] = pre[u][i] * (1 + down[uu]) % mod;
	}
	for (int i = e[u].size() - 1; i >= 0; i--) {
		int uu = e[u][i];
		suf[u][i] = (i < e[u].size() - 1) ? suf[u][i+1] : 1;
		if(uu != p)
			suf[u][i] = suf[u][i] * (1 + down[uu]) % mod;
	}
	down[u] = suf[u][0];
}
void dfs2(int u, int p) {
	for (int i = 0; i < e[u].size(); i++) {
		int uu = e[u][i];
		if (uu == p) continue;
		ll cnt = up[u];
		if(i) cnt = cnt * pre[u][i-1] % mod;
		if(i+1 < e[u].size()) cnt = cnt * suf[u][i+1] % mod;
		up[uu] = cnt + 1; // 1是不取par
		dfs2(uu, u);
	}
}
int main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    int n; cin >> n >> mod;
    for (int i = 1; i < n; i++) {
    	int a, b; cin >> a >> b;
    	e[a].pb(b), e[b].pb(a);
    }
    e[1].pb(0), up[1] = 1;
    for (int i = 1; i <= n; i++) {
    	pre[i].resize(e[i].size());
    	suf[i].resize(e[i].size());
    }
    dfs1(1, 0), dfs2(1, 0);
    for (int i = 1; i <= n; i++)
    	cout << down[i] * up[i] % mod << "\n";
    return 0;
}

