template <typename T>
struct ReRooting {
  private:
    using F = function<T(T,int)>;
    using H = function<T(T,T)>;
    int n;
    const vector<vector<int> > G;
    vector<vector<T> > dp;
    vector<T> ans;
    //dp_v = g(combine(f(dp_u1,u1), f(dp_u2,u2), ..., f(dp_uk,uk)) , v)
    const F f;
    const H combine;
    const T NE; //neutral of combine
    const F g;

    T dfs1(int v, int p = -1) {
      T res = NE;
      dp[v].assign(G[v].size(), NE);
      for (int i = 0; i < (int)G[v].size(); ++i) {
        int to = G[v][i];
        if (to == p) continue;
        dp[v][i] = dfs1(to, v);
        res = combine(res, f(dp[v][i], to));
      }
      return g(res,v);
    }
    void dfs2(int v, const T& add, int p = -1) {
      int m = G[v].size();
      for (int i = 0; i < m; ++i){
        if (G[v][i] == p) dp[v][i] = add;
      }
      vector<T> dp_l(G[v].size()+1,NE), dp_r(G[v].size()+1,NE); //累積combine
      for (int i = 0; i < m; ++i) {
        dp_l[i+1] = combine(dp_l[i], f(dp[v][i], G[v][i]));
      }
      for (int i = G[v].size(); i > 0; --i) {
        dp_r[i-1] = combine(dp_r[i], f(dp[v][i-1], G[v][i-1]));
      }
      ans[v] = g(dp_l[m], v);
      for (int i = 0; i < m; ++i) {
        int to = G[v][i];
        if (to == p) continue;
        dfs2(to, g(combine(dp_l[i], dp_r[i+1]), v), v);
      }
    }
  public:
    ReRooting(const vector<vector<int> >& G, const F &f, const H &combine, T ne, F g=[](T a, int b){ return a;}):
    G(G),f(f),combine(combine),NE(ne),g(g) {
      n = G.size();
      dp.resize(n);
      ans.assign(n,NE);
    }
    void build(int root = 0) {
      dfs1(root);
      dfs2(root, NE);
    }
    T operator[](const int &v) const{
      assert(v < n);
      return ans[v];
    }
};

int main() {
  std::cin.tie(nullptr);
  std::ios_base::sync_with_stdio(false);
  std::cout << std::fixed << std::setprecision(15);
  ll n,m;
  cin >> n >> m;
  auto f = [](int a, int v){ return a+1;};
  auto combine = [](ll a, ll b){ return a*b;};
  vector<vector<int> > G(n);
  rep(i,n-1) {
    int x,y;
    cin >> x >> y;
    x--; y--;
    G[x].emplace_back(y);
    G[y].emplace_back(x);
  }
  ReRooting<ll> dp(G, f, combine, 1);
  dp.build();
  rep(i,n) cout << dp[i] % m << "\n";
  return 0;
}

