int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);

  int n, MOD;
  cin >> n >> MOD;

  vector<vector<int>> graph(n);
  for (int i = 1; i < n; ++i) {
    int u, v;
    cin >> u >> v;
    --u, --v;
    graph[u].push_back(v);
    graph[v].push_back(u);
  }
  vector<i64> up(n, 1), down(n, 1);
  function<void(int, int)> dfs_down = [&](int v, int p) {
    for (auto it = graph[v].begin(); it != graph[v].end(); ) {
      auto ch = *it;
      if (ch == p) {
        it = graph[v].erase(it);
        continue;
      }
      dfs_down(ch, v);
      down[v] *= (down[ch] + 1);
      down[v] %= MOD;
      ++it;
    }
  };
  dfs_down(0, -1);
  function<void(int, int, i64)> dfs_up = [&](int v, int p, i64 prod) {
    if (~p) {
      up[v] = (up[p] * prod + 1) % MOD;
    }
    int k = (int) graph[v].size();
    vector<i64> pref(k + 1), suff(k + 1);
    pref[0] = suff[0] = 1;
    for (int i = 0; i < k; ++i) {
      pref[i + 1] = pref[i] * (down[graph[v][i]] + 1) % MOD;
      suff[i + 1] = suff[i] * (down[graph[v][k - i - 1]] + 1) % MOD;
    }
    for (int i = 0; i < k; ++i) {
      dfs_up(graph[v][i], v, pref[i] * suff[k - i - 1] % MOD);
    }
  };
  dfs_up(0, -1, 1);
  for (int i = 0; i < n; ++i) {
    cout << (down[i] * up[i] % MOD) << '\n';
  }
  return 0;
}

