vi suf[MAX + 1];
long long down[MAX + 1];
long long up[MAX + 1];

int add( int x, int y ) { return ((long long)x + y) % MOD; }
int mul( int x, int y ){ return (long long)x * y % MOD; }

void fix( int x )
{
	for( int i = 0; i < g[x].size(); i++ ) {
		int y = g[x][i];
		g[y].erase( find( g[y].begin(), g[y].end(), x ) );
        fix( y );
    }
}

void dfs( int x )
{
    down[x] = 1;
    for( auto &y : g[x] ) {
        dfs( y );
        down[x] = mul( down[x], add(down[y], 1) );
    }
    int sz = g[x].size();
    pref[x].resize( sz + 1 );
    suf[x].resize( sz + 1 );
    pref[x][0] = suf[x][sz] = 1;
    for( int i = 0; i < sz; i++ ) {
        pref[x][i + 1] = mul( pref[x][i], add(1, down[ g[x][i] ] ) );
    }
    for( int i = sz-1; i >= 0; i-- ) {
        suf[x][i] = mul( suf[x][i + 1], add(1, down[ g[x][i] ] ) );
    }
}

void dfs1( int x )
{
    for( int i = 0; i < g[x].size(); i++ ) {
        int y = g[x][i];
        up[y] = mul(up[x], mul( pref[x][i], suf[x][i+1] ) );
        up[y] = add(up[y], 1 );
        dfs1( y );
    }
}

