    for(int i=1; i<n; i++)
      L[i] = L[i-1] * (dp[v[nd][i-1]]+1) %mod;
    for(int i=n-2; i>=0; i--)
      R[i] = R[i+1] * (dp[v[nd][i+1]]+1) % mod;

    for(int i=0; i<n; i++)
    {
      int y = v[nd][i];
      dp1[y] = (dp1[nd] +1) * L[i]%mod*R[i]%mod;
      dfs(y, nd);
    }
  }
}

