#define rrep(i, n) for (int i = (n)-1; i >= 0; i--)

using ll = long long;
using namespace std;

ll n, m;
vector<ll> G[100100];
ll dp[100100];

void dfs1(ll v, ll p = -1){
    dp[v] = 1; // v:black固定
    for(auto nv : G[v]) {
        if(nv != p) {
            dfs1(nv, v);
            dp[v] *= dp[nv]+1; // nv:whiteの分+1する
            dp[v] %= m;
        }
    }
} // 通常の木DP

void dfs2(ll v, ll p = -1, ll dpp = 0){
    ll nn = G[v].size();
    // 積を累積しておく配列（前から、後ろから）
    vector<ll> mul1(nn), mul2(nn);
    // vの子nvについて問題を解く準備
    rep(i,nn){
        ll nv = G[v][i];
        if(nv == p) {
            mul1[i] = mul2[i] = (dpp+1) % m; // p:whiteno分だけ+1する
            dp[v] *= dpp+1; // p:whiteの分だけ+1する v:black固定
            dp[v] %= m;
        } // nv=pの時、dvの更新をする
        else mul1[i] = mul2[i] = (dp[nv]+1) % m; // nv:whiteの分+1する
    }
    // 前からの累積
    rep(i,nn-1){
        mul1[i+1] *= mul1[i];
        mul1[i+1] %= m;
    }
    // 後ろからの累積
    rrep(i,nn-1){
        mul2[i] *= mul2[i+1];
        mul2[i] %= m;
    }
    rep(i,nn){
        ll nv = G[v][i];
        if(nv != p) {
            ll a = (i ? mul1[i-1] : 1); // 前からの累積
            ll b = (i+1 < nn ? mul2[i+1] : 1); // 後ろからの累積
            dfs2(nv, v, a*b%m); // nvのdp更新は再帰先でされる
        } // 子nvについて再帰的にDPを更新していく
    }
}

