void dfs(int x, int p) {

    dp[x] = 1;
    for (auto y: adj[x]) {
        if (y == p)
            continue;
        dfs(y, x);
        dp[x] *= dp[y] + 1;
        dp[x] %= M;
    }

    int sz = adj[x].size();
    if (sz > 1) {
        pre[x].resize(sz);
        if (adj[x][0] != p)
            pre[x][0] = (dp[ adj[x][0] ] + 1) % M;
        else
            pre[x][0] = 1;
        for (int i=1; i<sz; i++) {
            if (adj[x][i] != p)
                pre[x][i] = pre[x][i-1] * (dp[ adj[x][i] ]+1) % M;
            else
                pre[x][i] = pre[x][i-1];
        }
        suf[x].resize(sz);
        if (adj[x][sz-1] != p)
            suf[x][sz-1] = (dp[ adj[x][sz-1] ] + 1) % M;
        else
            suf[x][sz-1] = 1;
        for (int i=sz-2; i>=0; i--) {
            if (adj[x][i] != p)
                suf[x][i] = suf[x][i+1] * (dp[ adj[x][i] ]+1) % M;
            else
                suf[x][i] = suf[x][i+1];
        }
    }
}

void dfs2(int x, int p) {
    ans[x] = dp[x];
