    for (int i=0; i<sz; i++) {
        int y = adj[x][i];
        if (y == p)
            continue;
        dp[x] = 1;
        dp[x] *= (i>0 ? pre[x][i-1] : 1);
        dp[x] %= M;
        dp[x] *= (i<sz-1 ? suf[x][i+1] : 1);
        dp[x] %= M;
        dp[x] *= (x==p ? 1 : dp[p]+1);
        dp[x] %= M;
        // printf("dp[%lld] = %lld\n", x, dp[x]);
        int tmp = dp[y];
        dp[y] *= dp[x] + 1;
        dp[y] %= M;
        dfs2(y, x);
        dp[y] = tmp;
    }
    dp[x] = ans[x];
}

