    dp1[v][0] = dp1[v][1] = 1;
    for (int i = 0; i < int(g[v].size()); i++) {
        int u = g[v][i];
        if (u == p) continue;
        dfs1(u, v);
        dp1[v][0] *= dp1[u][0];
        dp1[v][1] *= (dp1[u][0] + dp1[u][1]);
    }
}

using T = array<Mint, 2>;
void dfs2(int v, int p) {
    if (p == -1) {
        dp2[v][0] = dp2[v][1] = 1;
    }

    vector<int> c;
    for (auto u : g[v]) {
        if (u == p) continue;
        c.push_back(u);
    }
    int cc = int(c.size());
    vector<T> pf(cc + 2), sf(cc + 2);

    pf[0] = {1, 1};
    for (int i = 0; i < cc; i++) {
        int u = c[i];
        pf[i+1] = pf[i];
        pf[i+1][0] *= dp1[u][0];
        pf[i+1][1] *= (dp1[u][0] + dp1[u][1]);
    }

    sf[cc+1] = {1, 1};
    for (int i = cc-1; i >= 0; i--) {
        int u = c[i];
        sf[i+1] = sf[i+2];
        sf[i+1][0] *= dp1[u][0];
        sf[i+1][1] *= (dp1[u][0] + dp1[u][1]);
    }

    for (int i = 0; i < cc; i++) {
        int u = c[i];
        dp2[u][0] = pf[i][0] * sf[i+2][0] * dp2[v][0];
        dp2[u][1] = dp2[u][0] + dp2[v][1] * pf[i][1] * sf[i+2][1];
        dfs2(u, v);
    }
}

