                if(head.nodesu==0) continue;
                (ans*=head.kuro)%=M;
            } 
            cout<< ans <<"\n";
        }
    }

    void calcedge(){
        rep(v,N){
            if(v==root) continue;
            Hono head1=toparhead[v], head2=fromparhead[v];

        }
    }

    void build(ll _root=0){
        root=_root;
        dfs1(root);
        dfs2(root);
        calcnode(); // refer to nodepara and edge-partial trees attached to it (for node query)
        calcedge(); // refer to edgepara and node-partial trees attached to it (for path)
    }

    void debug(){
       if(isdebug) debugmode=true;
    }
    void debugout(Hono &head){
        de(head.kuro);
    }
};

struct HONO{
    ll kuro=0;
    ll edgesu=0;
    ll nodesu=0;
};
struct NONO{
    ll val=0;
};
HONO mergehead(HONO head1, HONO head2) { // 下にある(siro+kuro)をかける
    if(head1.nodesu==0) return head2;
    if(head2.nodesu==0) return head1;
    HONO head;
    head.edgesu=head1.edgesu+head2.edgesu;
    head.nodesu=head1.nodesu+head2.nodesu;
    head.kuro=head1.kuro*head2.kuro%M;
    return head;
}
HONO throughnode(HONO head1, NONO node1){
    HONO head=head1;
    if(head1.nodesu==0){ //葉の初期化
        head.kuro=2;
    }
    else{
        head.kuro+=1;
    }
    head.edgesu=1;
    head.nodesu=head1.nodesu+1;
    return head;
}
