void dfs1(int cur, int par, vector<vector<int>> &g, vector<lint> &dp) {
  lint ret = 1;
  for (auto nxt : g[cur]) {
    if (nxt == par) continue;
    dfs1(nxt, cur, g, dp);
    ret *= (dp[nxt] + 1);
    ret %= MOD;
  }
  dp[cur] = ret;
}

void dfs2(int cur, int par, vector<vector<int>> &g, vector<lint> &dp, vector<lint> &ans, lint Dpar) {
  lint ret = Dpar + 1;
  if (Dpar == -1) ret = 1;
  vector<int> chs;
  for (auto nxt : g[cur]) {
    if (nxt == par) continue;
    ret *= (dp[nxt] + 1);
    ret %= MOD;
    chs.push_back(nxt);
  }
  ans[cur] = ret;

  // 左右から累積
  size_t sz = chs.size();
  vector<lint> accLeft(sz + 2, 1);
  vector<lint> accRight(sz + 2, 1);
  for (int i = 1; i <= sz; i++) {
    accLeft[i] = (dp[chs[i - 1]] + 1);
    accRight[i] = (dp[chs[i - 1]] + 1);
  }

  for (int i = 1; i <= sz; i++) {
    accLeft[i] *= accLeft[i - 1];
    accLeft[i] %= MOD;
  }

  for (int i = sz; i >= 1; i--) {
    accRight[i] *= accRight[i + 1];
    accRight[i] %= MOD;
  }

  for (int i = 1; i <= sz; i++) {
    lint nxtDpar = accLeft[i - 1] % MOD * accRight[i + 1] % MOD;
    int nxt = chs[i - 1];
    if (Dpar != -1) {
      nxtDpar *= (Dpar + 1);
      nxtDpar %= MOD;
    }
    if (nxt == par) continue;
    dfs2(nxt, cur, g, dp, ans, nxtDpar);
  }
}

