void update(int u){
    up[u] = 1;
    int sz = g[u].size();
    for(int i=1;i<sz;i++) pref[u][i] = (pref[u][i]*pref[u][i-1])%m;
    for(int i=sz-2;i>=0;i--) suff[u][i] = (suff[u][i]*suff[u][i+1])%m;
