void dfs_down(int u, int p){
    par[u] = p;
    pref[u].resize(g[u].size());
    suff[u].resize(g[u].size());

    dp[u][p] = 1;
    for(int i=0;i<g[u].size();i++){
        int v = g[u][i];
        idx[u][v] = i;
        if(v == p) continue;
        dfs_down(v, u);

        pref[u][i] = (dp[v][u]+1)%m;
        suff[u][i] = (dp[v][u]+1)%m;
        dp[u][p] = (dp[u][p]*(dp[v][u]+1))%m;
    }
    if(u == 1) update(1);
}

void dfs_up(int u, int p){
    if(!up[u]){
        int v = par[u];
        dfs_up(v, u);
        pref[u][idx[u][v]] = (dp[v][u]+1)%m;
        suff[u][idx[u][v]] = (dp[v][u]+1)%m;
        par[u] = 0;
        update(u);
