long long down[NNODES];
long long up[NNODES];

int dfsDown(int root, int m) {
    int temp = 1;
    for(int node: v[root]) {
        if (fatherOf[root] == node) {
            continue;
        }
        fatherOf[node] = root;
        temp = ((temp % m) * (1 + dfsDown(node, m)) % m ) % m;
    }
    down[root] = temp%m;
    return down[root];
}

int dfsUp(int root, int m) {
    if (up[root] > 1) {
        return up[root];
    } 
    if (fatherOf[root] == -1) {
        up[root] = 1%m;
        return up[root];
    }
    int upV = dfsUp(fatherOf[root], m);
    up[root] = ((((down[fatherOf[root]]/(down[root]+1))%m) * (upV%m)) + 1) %m;
    return up[root];
}
void solve(int n, int m) {
    int root = 1;
    fatherOf[root] = -1;
    dfsDown(root, m);
    for (int i = 1; i <= n; i++) {
        dfsUp(i, m);
    }
}

