void dfs_vis2(int s, int p, int m)
{
	res[0][s] = ((in[0][s]%m) * (((out[0][s]%m) + (1%m))%m))%m;
	res[1][s] = ((in[1][s]%m) + (((out[0][s]%m) + (out[1][s]%m))%m))%m;
