        suf[i] = cnt[adj[node][i]] +1 ;        
    }

    for (int i = 1; i < n; ++i) pre[i] = (pre[i] * pre[i-1])%MOD;

    for (int i = n-2; i >= 0; --i) suf[i] = (suf[i] * suf[i+1])%MOD;

