typedef long long int ll;
const int INF = 1e9 + 7;
int mod;

int nxt() {
    int x;
    scanf("%d", &x);
    return x;
}

const int nax = 1e5 + 5;
VI edges[nax], children[nax];
vector<PII> downs[nax], pref[nax], suf[nax];
PII down[nax], up[nax];

int add(int a, int b) {
    return (a + b) % mod;
}

int mul(int a, int b) {
    return (ll) a * b % mod;
}

#define black second
#define white first
PII merge(const PII& a, const PII& b) {
    PII p;
    p.white = mul(a.white, b.white);
    p.black = add(mul(a.black, add(b.white, b.black)), mul(a.white, b.black));
    return p;
}
PII process(PII p) {
    return {p.white, add(p.black, p.white)};
}
// black, white pair
void dfs_one(int a, int parent) {
    PII p{1, 0};
    for (int b : edges[a]) {
        if (b != parent) {
            children[a].push_back(b);
            dfs_one(b, a);
            // down[a].black = mul(down[a].black, add(down[b].black, down[b].white));
            // down[a].white = mul(down[a].white, down[b].white);
            p = merge(p, down[b]);
            downs[a].push_back(down[b]);
        }
    }
    down[a] = process(p);
}

void dfs_two(int a, int parent) {
    for (int i = 0; i < (int)children[a].size(); i++) {
        PII p{1, 0};
        if (i) {
            p = merge(p, pref[a][i - 1]);
        }
        if (i != (int)downs[a].size() - 1) {
            p = merge(p, suf[a][i + 1]);
        }
        if (a != 1) {
            p = merge(p, up[a]);
        }
        int b = children[a][i];
        up[b] = process(p);
        dfs_two(b, a);
    }
}

int main() {
    int n = nxt();
    mod = nxt();
    for (int i = 0; i < n - 1; i++) {
        int a = nxt(), b = nxt();
        edges[a].push_back(b);
        edges[b].push_back(a);
    }
    dfs_one(1, -1);
    for (int a = 1; a <= n; a++) {
        int k = downs[a].size();
        assert(k == (int)children[a].size());
        PII p{1, 0};
        for (int i = 0; i < k; i++) {
            p = merge(p, downs[a][i]);
            pref[a].push_back(p);
        }
        p = {1, 0};
        for (int i = k - 1; i >= 0; i--) {
            p = merge(p, downs[a][i]);
            suf[a].push_back(p);
        }
        reverse(all(suf[a]));
    }
    dfs_two(1, -1);
    for (int a = 1; a <= n; a++) {
        PII p{1, 0};
        if (a != 1) {
            p = merge(p, up[a]);
        }
        if (!children[a].empty()) {
            p = merge(p, pref[a].back());
        }
        p = process(p);
        printf("%d\n", p.black);
        // printf("%d\n", mod);
        // printf("%d %d\>n", up[a].second, down[a].second);
    }
    return 0;
}

