void dfs(int src,vector<int> adj[],int p,bool isleaf[])
{
	int count=0;
	for(int x:adj[src])
	{
		if(x!=p)
		{
			dfs(x,adj,src,isleaf);
			count++;
		}
	}
	if(count==0)
	{
		isleaf[src]=true;
	}
}
void dfs(int src,vector<int> adj[],int p,int in[],bool isleaf[],int m)
{
	if(isleaf[src])
	{
		in[src]=1;
		return ;
	}
	else
	{
		for(int x:adj[src])
		{
			if(x!=p)
			{
				dfs(x,adj,src,in,isleaf,m);
			}
		}
		for(int x:adj[src])
		{
			if(x!=p)
			{
				in[src]*=(in[x]+1);
				in[src]%=m;
			}
		}
	}
}
void dfs(int src,vector<int> adj[],int p,int prev,int in[],int out[],bool isleaf[],int m)
{
	out[src]*=(prev+1);
	out[src]%=m;
	int next=prev+1;  // prev is for black only
	next%=m;
	if(isleaf[src])
	  return ;
	vector<int> vec;
	for(int x:adj[src])
	{
		if(x!=p)
		{
			vec.push_back(x);
		}

	}
	int n=vec.size();
	int prefix[n],suffix[n];
	prefix[0]=in[vec[0]]+1;
	int j;
	for(j=1;j<n;j++)
	{
		prefix[j]=prefix[j-1]*(in[vec[j]]+1);
		prefix[j]%=m;
	}
	suffix[n-1]=(in[vec[n-1]]+1);
	for(j=n-2;j>=0;j--)
	{
		suffix[j]=suffix[j+1]*(in[vec[j]]+1);
		suffix[j]%=m;
	}
	for(j=0;j<n;j++)
	{
		int here=1;
		if(j>=1)
		{
			here*=prefix[j-1];
		}
		if(j+1<n)
		{
			here*=suffix[j+1];
		}
		here%=m;
		int final=here*next;
		int x=vec[j];
		dfs(x,adj,src,final,in,out,isleaf,m);
	}
}
