int dfsUp(int root, int m) {
    if (up[root] > 1) {
        return up[root];
    } 
    if (fatherOf[root] == -1) {
        up[root] = 1%m;
        return up[root];
    }
    int upV = dfsUp(fatherOf[root], m);
    // pair<int, int> a(fatherOf[root], root);
    up[root] = ((( (prefix[root]%m) * (suffix[root]%m) * (upV%m)) % m) + 1) %m;
