void solve(int n, int m) {
    int root = 2;
    fatherOf[root] = -1;
    dfsDown(root, m);
    for (int i = 1; i <= n; i++) {
        dfsUp(i, m);
    }
    queue<int> q;
    q.push(root);
    while (q.size() > 0) {
        int it = q.front();
        q.pop();
        dfsUp(it, m);
        for (int node: v[it]) {
            if (node == fatherOf[it]) {
                continue;
            }
            q.push(node);
        }
    }
}

