        if (v == p) continue;
        dfsdown(v,u);
        down[u] = (down[u]*(down[v]+1))%m;
        children[u].PB(v);
    }
}

void dfsup(int u,int p)
{
    if (p == -1) up[u] = 1;
    else
    {
        up[u] = up[p];
        for(auto v:children[p])
        {
            if (v == u) continue;
            up[u] = (up[u]*(down[v]+1))%m;
        }
        up[u]++;
    }

    for(auto v:G[u])
    {
        if (v == p) continue;
        dfsup(v,u);
    }
}

