void dfs1(int v, int pr = -1){
    dp1[v] = 1;
    for(int to : g[v]){
        if(to == pr){
            continue;
        }
        dfs1(to, v);
        dp1[v] = 1LL * dp1[v] * (dp1[to] + 1) % MOD;
    }
}

void dfs2(int v, int pr = -1){
    if(pr != -1){
        g[v].erase(find(g[v].begin(), g[v].end(), pr));
    }
    if(g[v].empty()){
        return;
    }
    vector < int > pref((int)g[v].size() + 1),
                   suf((int)g[v].size() + 1);
    pref[1] = (dp1[g[v][0]] + 1) % MOD;
    for(int i = 2; i <= (int)g[v].size(); i++){
        pref[i] = 1LL * pref[i - 1] * (dp1[g[v][i - 1]] + 1) % MOD;
    }
    suf[(int)g[v].size()] = (dp1[g[v].back()] + 1) % MOD;
    for(int i = (int)g[v].size() - 1; i >= 1; i--){
        suf[i] = 1LL * suf[i + 1] * (dp1[g[v][i - 1]] + 1) % MOD;
    }
    for(int i = 1; i <= (int)g[v].size(); i++){
        int to = g[v][i - 1];
        int cur = (dp2[v]) % MOD;
        if(i - 1 >= 1){
            cur = 1LL * cur * pref[i - 1] % MOD;
        }
        if(i + 1 <= (int)g[v].size()){
            cur = 1LL * cur * suf[i + 1] % MOD;
        }
        cur = (cur + 1) % MOD;
        dp2[to] = cur;
        dfs2(to, v);
    }
}
