#include <bits/stdc++.h>
using namespace std;

const int N = 1e5 + 5;

int dp[N][2];
int dw[N][2];
int asd[N];
int parent[N];
vector<int> adj[N];
int n, MOD;

void read() {
  scanf("%d %d", &n, &MOD);
  for (int i = 1; i < n; i++) {
    int u, v;
    scanf("%d %d", &u, &v);
    adj[u].push_back(v);
    adj[v].push_back(u);
  }
}

int solve(int pos, int color, int prv) {
  int &ret = dp[pos][color];
  if (ret != -1) return ret;

  parent[pos] = prv;
  ret = 1 % MOD;
  for (int nex : adj[pos]) {
    if (nex == prv) continue;

    int ways = solve(nex, 0, pos);
    if (color == 1) {
      ways = (ways + solve(nex, 1, pos)) % MOD;
    }

    ret = 1ll * ret * ways % MOD;
  }

  return ret;
}

void dfs(int now, int prv) {
  // printf("sekarang %d\n", now);
  asd[now] = (asd[now] + 1) % MOD;

  vector<int> prefBoth, sufBoth;
  vector<int> prefZero, sufZero;

  prefBoth = prefZero = {1 % MOD};
  for (int nex : adj[now]) {
    if (nex == prv) continue;

    prefBoth.push_back((solve(nex, 0, now) + solve(nex, 1, now)) % MOD);
    prefZero.push_back(solve(nex, 0, now));
  }
  prefZero.push_back(1 % MOD);
  prefBoth.push_back(1 % MOD);

  sufZero = prefZero;
  sufBoth = prefBoth;

  for (int i = 1; i < prefZero.size(); i++) {
    prefBoth[i] = 1ll * prefBoth[i] * prefBoth[i - 1] % MOD;
    prefZero[i] = 1ll * prefZero[i] * prefZero[i - 1] % MOD;
  }

  for (int i = sufZero.size() - 2; i >= 0; i--) {
    sufBoth[i] = 1ll * sufBoth[i] * sufBoth[i + 1] % MOD;
    sufZero[i] = 1ll * sufZero[i] * sufZero[i + 1] % MOD;
  }

  int cnt = 0;

  for (int nex : adj[now]) {
    if (nex == prv) continue;
    cnt++;

    asd[nex] = asd[now];
    asd[nex] = 1ll * asd[nex] * prefBoth[cnt-1] % MOD;
    asd[nex] = 1ll * asd[nex] * sufBoth[cnt+1] % MOD;
    // asd[nex] = (asd[nex] + 1ll * prefBoth[cnt-1] * sufBoth[cnt+1]) % MOD;

    dfs(nex, now);
  }
}

void work() {
  memset(dp, -1, sizeof dp);
  asd[1] = 0;
  solve(1, 0, -1);
  dfs(1, -1);

  for (int i = 1; i <= n; i++) {
    int ways = asd[i];

    ways = 1ll * ways * solve(i, 1, parent[i]) % MOD;

    // printf("i %d parent %d ways %d\n", i, parent[i], ways);

    printf("%d\n", (ways) % MOD);
  }
}

int main() {
  read();
  work();
  return 0;
}

