    if(c==0){
      tmp += dfs(nv,0,v);
    }
    tmp %= MOD;
    res = (res*tmp)%MOD;
  }
  return dp[v][c] = res;
}
void solve(ll v,ll pre){
  ll m = G[v].size();
  SegmentTree<ll> seg0(m,[&](ll x,ll y){return (x*y)%MOD;},1);
  SegmentTree<ll> seg1(m,[&](ll x,ll y){return (x*y)%MOD;},1);
  ll now_0 = dp[v][0],now_1 = dp[v][1];
  dp[v][0] = dp[v][1] = 1;
  for(int i=0;i<m;i++){
    seg0.set(i,1);
