  }
  for(ll i=0;i<m;i++){
    dp[v][0] = (dp[v][0] * (dp[G[v][i]][0] + dp[G[v][i]][1])) % MOD;
    dp[v][1] = (dp[v][1] * dp[G[v][i]][1]) % MOD;
    seg0.update(i,(dp[G[v][i]][0] + dp[G[v][i]][1]) % MOD);
