        adj[y - 1].push_back(x - 1);
    }

    dp.resize(N);
    for (int v = 0; v < N; ++v) dp[v].resize(adj[v].size());
    Dfs(-1, 0);
    Rev(-1, 0, 0);

    for (int v = 0; v < N; ++v) {
        ll ans = 1;
        for (ll add : dp[v]) (ans *= (add + 1)) %= MOD;
        cout << ans << '\n';
    }

    return 0;
}

