ll M;

ll dfs1(const vector<vector<int>>& graph, vector<bool>& visited, vector<ll>& dp, int node) {
    visited[node] = true;
    ll res = 1;
    rep(i, 0, graph[node].size()) {
        if (visited[graph[node][i]]) {
            continue;
        }
        ll child_val = dfs1(graph, visited, dp, graph[node][i]) + 1;
        res = (res * child_val) % M;
    }
    return dp[node] = res;
}

void dfs2(const vector<vector<int>>& graph, vector<bool>& visited, vector<ll>& dp, vector<ll>& ans, int node, int parent) {
    visited[node] = true;
    ans[node] = 1;
    rep(i, 0, graph[node].size()) {
        ans[node] = (ans[node] * (dp[graph[node][i]] + 1)) % M;
    }
    int n = (int)graph[node].size();
    vector<ll> lcum(n, 0), rcum(n, 0);
    rep(i, 0, n) {
        lcum[i] = rcum[i] = (dp[graph[node][i]] + 1) % M;
    }
    rep(i, 1, n) {
        lcum[i] = (lcum[i] + lcum[i - 1]) % M;
    }
    rrep(i, n - 1, 0) {
        rcum[i] = (rcum[i] + rcum[i + 1]) % M;
    }
    rep(i, 0, n) {
        if (graph[node][i] == parent) {
            continue;
        }
        dp[node] = (parent >= 0 ? dp[parent] : 1);
        if (i > 0) dp[node] = (dp[node] * lcum[i - 1]) % M;
        if (i < n - 1) dp[node] = (dp[node] * rcum[i + 1]) % M;
        dfs2(graph, visited, dp, ans, graph[node][i], node);
    }
}

