typedef long long ll;

vector<int> edge[100005];
vector<ll> dp[100005];
ll M;

ll dfs(int cur, int pre)
{
	ll ret = 1;
	for (int i = 0; i < edge[cur].size(); i++) {
		int e = edge[cur][i];
		if (e != pre) {
			dp[cur][i] = dfs(e, cur);
			ret *= (1 + dp[cur][i]);
			ret %=M;
		}
	}
	return ret;
}

void dfs2(int cur, int pre, ll p)
{
	for (int i = 0; i < edge[cur].size(); i++) {
		int e = edge[cur][i];
		if(e == pre) {
			dp[cur][i] = p;
		}
	}
	vector<ll> l(edge[cur].size()), r(edge[cur].size());
	for (int i = 0; i < edge[cur].size(); i++) {
		l[i]= (i ? l[i - 1] : 1) * (1 + dp[cur][i]) % M;
	}
	for (int i = edge[cur].size() - 1; i >= 0; i--) {
		r[i] = ((i < edge[cur].size() - 1) ? (r[i + 1]) : 1) * (1 + dp[cur][i]) % M;
		if (edge[cur][i] != pre) {
			ll total = (i ? l[i - 1] : 1) * ((i < edge[cur].size() - 1) ? r[i + 1] : 1) % M;
			dfs2(edge[cur][i], cur, total);
		}
	}
}
