#include <bits/stdc++.h>
using namespace std;
int MOD;

void dfs(int node, auto& g, auto& dp, auto& preff, auto& suff, auto& f) {
    dp[node] = 1;

    vector<int> sons;

    for (int v : g[node]) {
        if (v == f[node])
            continue;
        f[v] = node;
        dfs(v, g, dp, preff, suff, f);
        sons.push_back(v);
    }

    int k = sons.size();

    for (int i = 0; i < k; i += 1) {
        dp[node] = 1LL * dp[node] * (dp[sons[i]] + 1) % MOD;
        preff[node].push_back(dp[node]);
    }

    dp[node] = 1;

    for (int i = k - 1; i >= 0; i -= 1) {
        dp[node] = 1LL * dp[node] * (dp[sons[i]] + 1) % MOD;
        suff[node].push_back(dp[node]);
    }

    reverse(suff[node].begin(), suff[node].end());
}

void dfs2(int node, auto& g, auto& dp, auto& preff, auto& suff, auto& f, auto& sol, int up) {
    sol[node] = dp[node];
    vector<int> sons;

    for (int v : g[node]) {
        if (v == f[node])
            continue;
        sons.push_back(v);
    }

    int k = sons.size();
    for (int i = 0; i < k; i += 1) {
        int left_coef = (i - 1 >= 0 ? preff[node][i - 1] : 1);
        int right_coef = (i + 1 < k ? suff[node][i + 1] : 1);

        dp[node] = 1LL * left_coef * right_coef % MOD;
        dp[node] = 1LL * dp[node] * up % MOD;
        dp[sons[i]] = 1LL * dp[sons[i]] * (dp[node] + 1) % MOD;
        dfs2(sons[i], g, dp, preff, suff, f, sol, dp[node] + 1);
    }   

    dp[node] = 1;
    for (int i = 0; i < k; i += 1)
        dp[node] = 1LL * dp[node] * (dp[sons[i]] + 1) % MOD;

    if (f[node] >= 0)
        dp[f[node]] = 1LL * dp[f[node]] * (dp[node] + 1) % MOD;
}

int main() {
    int n, m; cin >> n >> m;
    MOD = m;
    vector<vector<int>> g(n);

    for (int i = 0; i < n - 1; i += 1) {
        int x, y; cin >> x >> y;
        x -= 1, y -= 1;
        g[x].push_back(y);
        g[y].push_back(x);
    }

    vector<int> dp(n, 0);
    vector<vector<int>> preff(n), suff(n);
    vector<int> f(n, -1);

    dfs(0, g, dp, preff, suff, f);

    vector<int> sol(n, 0);

    dfs2(0, g, dp, preff, suff, f, sol, 1);

    for (int i = 0; i < n; i += 1)
        cout << sol[i] << "\n";
}

