    for(int i=0; i<G[v].size(); i++){
        if(G[v][i] == p) continue;
        dp[v][i] = dfs(G[v][i],v);
        res *= (dp[v][i]+1);
        res %= M;
    }
    return res;
}

void rev(int v,int p=-1,ll add=-1){
    for(int i=0; i<G[v].size(); i++){
        if(G[v][i] == p){
            dp[v][i] = add;
            break;
        }
    }
    vector<ll> l(G[v].size()),r(G[v].size());
    for(int i=0; i<G[v].size(); i++){
        l[i] = r[i] = (dp[v][i]+1)%M;
    }
    for(int i=1; i<G[v].size(); i++){
        l[i] *= l[i-1];
        l[i] %= M;
    }
    for(int i=G[v].size()-2; i>=0; i--){
        r[i] *= r[i+1];
        r[i] %= M;
    }
    for(int i=0; i<G[v].size(); i++){
        if(G[v][i] == p) continue;
        ll add_c = 1;
        if(i != 0){
            add_c *= l[i-1];
            add_c %= M;
        }
        if(i != G[v].size()-1){
            add_c *= r[i+1];
            add_c %= M;
        }
        rev(G[v][i],v,add_c);
    }
}


