vector<long long> Num[maxm],Left[maxm],Right[maxm];

struct edge{
	int To;
	int Next;
	# define To(x) Edge[x].To
	# define Next(x) Edge[x].Next
}Edge[maxm<<1];

inline void Add_Edge(int From,int To){Edge[++tot]=(edge){To,head[From]};head[From]=tot;return;}
inline void Insert_Edge(int x,int y){Add_Edge(x,y),Add_Edge(y,x);return;}

void Dfs(int now){
	DP[now]=1;
	for(int i=head[now];i;i=Next(i)){
		if(To(i)==Father[now]) continue;
		long long Number;
		Father[To(i)]=now;
		Dfs(To(i));
		Number=(1+DP[To(i)])%Mod;
		Number=(Number+Mod)%Mod;
		DP[now]=DP[now]*Number%Mod;
		Num[now].push_back(Number);
	}
	return;
}

inline void Work(int now){
	register int i;
	register long long Result;
	sort(Num[now].begin(),Num[now].end());
	Result=1;
	Left[now].push_back(1);
	for(i=0;i<Num[now].size();i++){
		Result=(Result*Num[now][i])%Mod;
		Left[now].push_back(Result);
	}
	Result=1;
	Right[now].push_back(1);
	for(i=Num[now].size()-1;i>=0;i--){
		Result=(Result*Num[now][i])%Mod;
		Right[now].push_back(Result);
	}
	return;
}

void Dfs2(int now){
	if(now==1){
		DP2[now]=DP[now];
		Work(now);
	}else{
		long long Now,Number;
		Number=(DP[now]+1)%Mod;
		Number=(Number+Mod)%Mod;
		Step=(lower_bound(Num[Father[now]].begin(),Num[Father[now]].end(),Number)-Num[Father[now]].begin());
		Now=(Left[Father[now]][Step]*Right[Father[now]][Num[Father[now]].size()-Step-1])%Mod;
		Number=(Now+1)%Mod;
		Number=(Number+Mod)%Mod;
		Num[now].push_back(Number);
		DP2[now]=Number*DP[now]%Mod;
		Work(now);
	}
	for(int i=head[now];i;i=Next(i)){
		if(To(i)==Father[now]) continue;
		Dfs2(To(i));
	}
	return;
}

