class SegmentTree {
private:
	int num;
	vector<ll> dat;

	// TODO: Change the operator and the identity element.
	static const ll INI = 1;
	ll op(ll a, ll b) {
		return a*b % M;
	}

public:
	SegmentTree(int n_) {
		num = 1;
		while (num < n_) num *= 2;
		dat = vector<ll>(2 * num, INI);
	}

	// Update the k-th value (0-indexed) to a.
	void update(int k, ll a) {
		k += num - 1;
		dat[k] = a;
		while (k > 0) {
			k = (k - 1) / 2;
			dat[k] = op(dat[2 * k + 1], dat[2 * k + 2]);
		}
	}

	// Get the value of the range [a, b).
	// k: The index of the node.
	// [left, right): The range corresponds to the k-th node.
	// Call like getval(a, b).
	ll getval(int a, int b, int k = 0, int left = 0, int right = -1) {
		if (right < 0) right = num;
		if (right <= a || b <= left) return INI;
		if (a <= left && right <= b) return dat[k];
		ll vleft = getval(a, b, 2 * k + 1, left, left + (right - left) / 2);
		ll vright = getval(a, b, 2 * k + 2, left + (right - left) / 2, right);
		return op(vleft, vright);
	}
};


ll func(int pos) {
	ll ret = 1;
	dp[pos] = 0;
	for (int to : edg[pos]) {
		if (dp[to] != -1) continue;
		ret *= (func(to) + 1)%M;
		ret %= M;
	}
	return dp[pos] = ret;
}

void func2(int pos) {
	int cnt = 0;
	for (int to : edg[pos]) {
		if (dp2[to] != -1) continue;
		cnt++;
	}
	SegmentTree seg(cnt + 1);
	cnt = 0;
	for (int to : edg[pos]) {
		if (dp2[to] != -1) continue;
		seg.update(cnt++, dp[to] + 1);
	}
	seg.update(cnt++, dp2[pos] + 1);
	int c = 0;
	for (int to : edg[pos]) {
		if (dp2[to] != -1) continue;
		seg.update(c, 1);
		dp2[to] = seg.getval(0, cnt);
		seg.update(c++, dp[to] + 1);
		func2(to);
	}
}

