const ll MAXN = 1e5 + 10;
vector<ll> graph[MAXN];
ll MOD;
vector<ll> going_toward[MAXN];
ll down[MAXN];
ll ans[MAXN];

void dfs(ll u,ll p){
    down[u] = 1;

    for(ll v:graph[u]){
        if(v == p) continue;
        dfs(v,u);
        down[u] = (down[u]*(1+down[v]))%MOD;
    }

    vector<ll> pref,suff;

    for(ll v:graph[u]){
        if(v == p) pref.push_back(1);
        else pref.push_back(down[v] + 1);
    }

    suff = pref;
    FOR(i,1,(ll)pref.size()-1) pref[i] = (pref[i-1]*pref[i])%MOD;
    RFOR(i,0,(ll)suff.size()-2) suff[i] = (suff[i+1]*suff[i])%MOD;

    FOR(i,0,(ll)graph[u].size()-1){
        if(graph[u][i] == p) going_toward[u].push_back(-1);
        else {
            ll mul1 = 1; if(i-1 >= 0) mul1 = pref[i-1];
            ll mul2 = 1; if(i+1 <= suff.size()-1) mul2 = suff[i+1];
            going_toward[u].push_back((mul1*mul2)%MOD);
        }
    }
}

void root_change_dfs(ll u,ll p){
    ans[u] = down[u];

    FOR(i,0,(ll)graph[u].size()-1){
        ll v = graph[u][i];
        if(v == p) continue;

        ll oldu = down[u],oldv = down[v];
        down[u] = (going_toward[u][i]*(1+down[p]))%MOD;
        down[v] = (down[v]*(1+down[u]))%MOD;
        root_change_dfs(v,u);
        down[u] = oldu,down[v] = oldv;
    }
}

