    (dp[u] *= cur) %= MOD;
    vector<ll> suf;
    for (const int v : adj[u]) {
        if (v == p) continue;
        suf.push_back(1 + dp0[v]);
    }
    suf.push_back(1);
    for (int i = suf.size() - 2; i >= 0; i--) {
        (suf[i] *= suf[i + 1]) %= MOD;
    }
    ll left = 1;
    int i = 0;
    for (const int v : adj[u]) {
        if (v == p) continue;
        const ll val = (left * suf[i + 1]) % MOD;
        dfs(v, u, (1 + cur * val) % MOD);
        (left *= 1 + dp0[v]) %= MOD;
        i++;
    }
}

