void DPSub(int curr, int par)
{
    dpSub[curr] = 1;
    for(auto& neighbor : graph[curr])
    {
        if(neighbor == par) continue;
        DPSub(neighbor, curr);
        dpSub[curr] *= (dpSub[neighbor] + 1);
        dpSub[curr] %= MOD;
    }
}

void DPAll(int curr, int par)
{
    int k = graph[curr].size();
    vector<int> pref(k+2), suff(k+2);
    pref[0] = 1, suff[k+1] = 1;
    for(int i = 1; i <= k; ++i)
    {
        int neighbor = graph[curr][i-1];
        pref[i] = (dpSub[neighbor] + 1);
        (pref[i] *= pref[i-1]) %= MOD;
    }
    for(int i = k; i > 0; --i)
    {
        int neighbor = graph[curr][i-1];
        suff[i] = (dpSub[neighbor] + 1);
        (suff[i] *= suff[i+1]) %= MOD;
    }

    for(int i = 1; i <= k; ++i)
    {
        int neighbor = graph[curr][i-1];
        if(neighbor == par) continue;

        dpAll[neighbor] = dpSub[neighbor];
        // Num ways to paint this black without considering child, plus paint this white
        ll fromThis = (pref[i-1] * suff[i+1] + 1) % MOD;
        (dpAll[neighbor] *= fromThis) %= MOD;
        DPAll(neighbor, curr);
    }
}

