template<class T>
vector<T> rerooting(vector<vector<ll>> G, function<T(T,T)> merge, T id){
    ll N = G.size();
    vector<T> V(N); // 各頂点の値
    vector<map<ll, T>> dp(N);

    auto dfs = [&](auto&& dfs, ll now, ll par, bool flag) {
        if (dp[now].count(par)) return dp[now][par];

        ll gn = G[now].size();
        if(par == -1 or flag){
            vector<T> A;
            for (ll i = 0; i < gn; i++){
                ll to = G[now][i];
                if (to == par) continue;

// 
                A.emplace_back(dfs(dfs, to, now, flag) + 1);
            }

            ll an = A.size();
            vector<T> R(an + 1, id);  //右からの累積和
            for (ll i = an; i > 0; i--) R[i - 1] = merge(R[i], A[i - 1]);

            if(par == -1){
                T L = id;
                for (ll i = 0; i < gn; i++){
                    ll to = G[now][i];

                    dp[now][to] = merge(L, R[i + 1]);  //now->toを除いた値
                    L = merge(L, A[i]);  //左から累積していく
                }
            }

            return dp[now][par] = R[0];

        }
        else{
            dfs(dfs, now, -1, flag);
            return dfs(dfs, now, par, flag);
        }
    };

    dfs(dfs, 0, -1, true);

    for (ll i = 0; i < N; i++) dfs(dfs, i, -1, false), V[i] = dp[i][-1];

    return V;
}

