int dp2[MAX_N];

int solve(int pos, int par)
{
  int ret = 1;

  for(int next : Edge[pos]) {
    if(next == par) continue;
    ret *= (solve(next, pos)+1);
    ret %= M;   
  }

  return dp[pos] = ret;
}

void solve2(int pos, int par, int parInfo)
{
  dp2[pos] = (dp[pos] * (parInfo+1)) % M;
  vector<int> blackSize;
  deque<int> front,end;
  for(int next : Edge[pos]) {
    if(next == par) blackSize.emplace_back(parInfo);
    else blackSize.emplace_back(dp[next]);
  }

  int f = 1, e = 1;
  for(int i = 0; i < blackSize.size(); i++) {
    f *= (blackSize[i]+1); f %= M;
    e *= (blackSize[blackSize.size()-i-1]+1); e %= M;
    front.push_back(f); end.push_front(e);
  }

  for(int i = 0; i < Edge[pos].size(); i++) {
    int next = Edge[pos][i];
    if(next == par) continue;
    int nextParInfo = 1;
    if(i>0) {
      nextParInfo *= front[i-1]; nextParInfo %= M;
    }
    if(i<Edge[pos].size()-1) {
      nextParInfo *= end[i+1]; nextParInfo %= M;
    }
    solve2(next, pos, nextParInfo);
  }
}

