    if (c == par) continue;
    dfs2(c, cur);
    x *= dp[c] + 1;
    x %= M;
  }
  dp2[cur] = x;
}

void dfs3(int par, int ppar) {
  ll x = 1;
  if (ppar != -1) {
    x *= dp3[ppar][par] + 1;
    x %= M;
  }
  for (auto cur : edge[par]) {
    if (cur == ppar) continue;
    ll y = x;
    for (auto d: edge[par]) {
      if (d == ppar) continue;
      if (d == cur) continue;
      y *= (dp[d]+1);
      y %= M;
    }
    dp3[par][cur] = y;
    dfs3(cur, par);
  }
