    --x, --y;
    tree[x].push_back(y);
    tree[y].push_back(x);
  }

  prod.resize(N);

  rec(tree, 0, -1);
  fill(ALL(visit),false);
  rec2(tree, 0, -1, 0);

  REP(i,N){
    mint ans = (dp2[i]+1) * dp[i];
    cout << ans << endl;
  }

  return 0;
}

