int dfs(int u, int p, int c){
	if(dp[u][c]  != -1) return dp[u][c]%m;
	dp[u][c] = 1;
	pref[u].resize(adj[u].size());
	suf[u].resize(adj[u].size());
	for(int i =0; i < adj[u].size(); i++){
		int v = adj[u][i];
		if(v == p){
			pref[u][i] = 1ll;
			suf[u][i] = 1ll;
			continue;
		}
		lli res = 0;

		if(c == 0){//negro
			res = (dfs(v,u,0) + dfs(v,u,1)) % m;
			dp[u][c] = (dp[u][c] * res) % m;
		}
		else{
			res = dfs(v,u,1) % m;
			dp[u][c] = (dp[u][c] * res)%m;
		}
		pref[u][i] = res;
		suf[u][i] = res;
	}
	//pref
	for(int i =1; i < pref[u].size(); i++){
		pref[u][i] = (pref[u][i] * pref[u][i-1])%m;
	}
	for(int i = suf[u].size()-2; i >=0; i--){
		suf[u][i] = (suf[u][i] * suf[u][i+1])%m;
	}
	return dp[u][c] % m;
}

