int get(vector <int> &v, int p) {
	if(p < 0 || p >= (int) v.size())
		return 1;

	return v[p];
}

void dfs1(int u, int p = -1) {
	dp[u] = 1;

	for(int v : g[u]) {
		if(v != p) {
			dfs1(v, u);
			dp[u] = 1LL * dp[u] * (dp[v] + 1) % M;
		}
	}
}

void dfs2(int u, int p = -1, int up = 0) {
	ans[u] = 1LL * dp[u] * (up + 1) % M;

	vector <int> pre, suf;

	for(int v : g[u]) {
		if(v != p) {
			if(pre.empty())
				pre.push_back(dp[v] + 1);

			else pre.push_back(1LL * pre.back() * (dp[v] + 1) % M);
		}
	}

	for(int i = (int) g[u].size() - 1; i >= 0; i--) {
		int v = g[u][i];

		if(v != p) {
			if(suf.empty())
				suf.push_back(dp[v] + 1);

			else suf.push_back(1LL * suf.back() * (dp[v] + 1) % M);
		}
	}

	reverse(suf.begin(), suf.end());

	int it = 0;
	for(int v : g[u]) {
		if(v != p) {
			int nup = 1LL * get(pre, it - 1) * get(suf, it + 1) % M;
			nup = 1LL * nup * (up + 1) % M;
