void dfs1(int v, int p) {
//	cout << "DFS1 " << v << " " << p << "\n";
	dp[v] = 1;
	for (int to : G[v]) {
		if (to == p) continue;
		dfs1(to, v);
		dp[v] = (LL)dp[v] * (dp[to] + 1) % MOD;
	}

	pref[v].resize(G[v].size() + 1);
	pref[v][0] = 1;
	for (int i = 0; i < G[v].size(); i++) {
		int to = G[v][i];
		LL mul = to == p ? 1 : dp[to] + 1;
		pref[v][i + 1] = pref[v][i] * mul % MOD;
	}

	suff[v].resize(G[v].size() + 1);
	suff[v][G[v].size()] = 1;
	for (int i = G[v].size() - 1; i >= 0; i--) {
		int to = G[v][i];
		LL mul = to == p ? 1 : dp[to] + 1;
		suff[v][i] = suff[v][i + 1] * mul % MOD;
	}
