ll mod;
vector<vector<int>> graph;
vector<ll> dp1;
vector<ll> dp2;

ll dfs1(int v,int pa){
  ll ans=1;
  for(int i=0;i<sz(graph.at(v));i++){
    int nv=graph.at(v).at(i);
    if(nv==pa)  continue;
    ans*=(dfs1(nv,v)+1);
    ans%=mod;
  }
  return dp1.at(v)=ans;
}

void dfs2(int v,int pa){
  if(pa==-1)  dp2.at(v)=1;
  int vsize=sz(graph.at(v));
  vector<ll> mul1(vsize+1,1);
  vector<ll> mul2(vsize+1,1);
  for(int i=0;i<vsize;i++){
    int nv=graph.at(v).at(i);
    if(nv==pa)  mul1.at(i+1)=mul1.at(i);
    else  mul1.at(i+1)=mul1.at(i)*(dp1.at(nv)+1)%mod;
  }
  for(int i=vsize-1;i>=0;i--){
    int nv=graph.at(v).at(i);
    if(nv==pa)  mul2.at(i)=mul2.at(i+1);
    else  mul2.at(i)=mul2.at(i+1)*(dp1.at(nv)+1)%mod;
  }
  for(int i=0;i<vsize;i++){
    int nv=graph.at(v).at(i);
    if(nv==pa)  continue;
    dp2.at(nv)=(dp2.at(v)*(mul1.at(i)*mul2.at(i+1)%mod)+1)%mod;
    dfs2(nv,v);
  }
}

