         ll v_res=dp[v];
         ll s_res=dp[s];
         ll mm=left[v].size();
         if(mm==1)
         dp[v]=1;
        else if(cnt==0)
         {
            ll z=right[v].size();

            dp[v]=right[v].at(z-2);
         }
         else if(cnt==right[v].size()-1)
         {
            dp[v]=left[v].at(left[v].size()-2);
         }
         else 
         {
            dp[v]=((left[v].at(cnt-1))*(right[v].at(right[v].size()-2-cnt)))%m;
