void yo(int u,int pr)
{
    vi pre(sz(g[u]),1),suf(sz(g[u]),1);
    for(int i=0;i<sz(g[u]);i++){
        int v=g[u][i];
        if(v==pr) continue;
        pre[i]=dp1[v]+1;
        if(i) pre[i]=1LL*pre[i]*pre[i-1]%mod;
    }
