void dfs_pre(int v, int p) {
    for (int u : tree[v]) {
        if (u != p) dfs_pre(u, v);
    }

    prol[v].resize(tree[v].size() + 1);
    prol[v][0] = 1;
    for (int i = 0; i < (int)tree[v].size(); ++i) {
        if (tree[v][i] != p) prol[v][i + 1] = (prol[v][i] * (prol[tree[v][i]].back() + 1)) % MOD;
        else prol[v][i + 1] = prol[v][i];
    }
    pror[v].resize(tree[v].size() + 1);
    pror[v][tree[v].size()] = 1;
    for (int i = tree[v].size() - 1; i >= 0; --i) {
        if (tree[v][i] != p) pror[v][i] = (pror[v][i + 1] * (prol[tree[v][i]].back() + 1)) % MOD;
        else pror[v][i] = pror[v][i + 1];
    }
}

void dfs(int v, int p, ll subp) {
    ans[v] = prol[v].back() * (subp + 1) % M;

    for (int i = 0; i < (int)tree[v].size(); ++i) {
        if (tree[v][i] != p) dfs(tree[v][i], v, (subp + 1) * prol[v][i] % M * pror[v][i + 1] % M);
    }
}

