long long dp[111111];
long long ep[111111];

void dfs(int s, int p){
    long long res = 1;
    for(int t : adj[s]){
        if(t == p) continue;
        dfs(t, s);
        res *= (dp[t]+1);
        res %= M;
    }
    dp[s] = res;
}

void efs(int s, long long x, int p){
    int sz = 0;
    map<int, int> mp;
    for(int t : adj[s]){
        sz++;
        mp[mp.size()] = t;
    }

    for(int i=0; i<sz; i++)
        cerr << "MP " << i << " " << mp[i] << endl;

    if(mp.find(p) != mp.end())
        dp[p] = x;

    vector<long long> left(sz+2, 1), righ(sz+2, 1);
    for(int i=0; i<sz; i++){
        int t = mp[i];
        left[i+1] = (left[i] * (dp[t]+1))%M;
    }
    for(int i=sz-1; i>=0; i--){
        int t = mp[i];
        righ[i+1] = (righ[i+2] * (dp[t]+1))%M;
    }

    for(int i=0; i<sz+2; i++)
        cerr << left[i] << " ";
    cerr << endl;
    for(int i=0; i<sz+2; i++)
        cerr << righ[i] << " ";
    cerr << endl;

    for(int i=0; i<sz; i++){
        int t = mp[i];
        if(t == p) continue;
        ep[t] = (dp[t] * (left[i] * righ[i+2] + 1)%M)%M;
        efs(t, (left[i]*righ[i+2])%M, s);
    }
}


