#include <bits/stdc++.h>

using namespace std;

#define fi first
#define se second
#define pb push_back
#define mp make_pair

#define int long long

typedef pair<int, int> ii;

const int N = 1e5 + 5;

const int inf = 1e15;

int n, mod, dp[N][2], up[N][2], pref[N][2], suff[N][2];

vector<int> graph[N];

void dfs(int u, int p) {
    dp[u][0] = dp[u][1] = 1;
    for(int i = 0; i < graph[u].size(); i++) {
        int v = graph[u][i];
        if(v == p) continue;
        dfs(v, u);
    }
    for(int i = 0; i < graph[u].size(); i++) {
        int v = graph[u][i];
        if(v == p) continue;
        dp[u][0] = (dp[u][0] * dp[v][0]) % mod;
        dp[u][1] = (dp[u][1] * (dp[v][1] + dp[v][0])) % mod;
    }
}

void redfs(int u, int p) {
    for(int j = 0; j < 2; j++) {
        for(int i = 0; i < graph[u].size(); i++)
            pref[i][j] = suff[i][j] = 1;
    }
    for(int i = 0; i < graph[u].size(); i++) {
        int v = graph[u][i];
        if(i >= 1) {
            pref[i][0] = pref[i - 1][0];
            pref[i][1] = pref[i - 1][1];
        }
        if(v == p) continue;
        pref[i][0] = (pref[i][0] * dp[v][0]) % mod;
        pref[i][1] = (pref[i][1] * (dp[v][0] + dp[v][1])) % mod;
    }
    for(int i = (int)(graph[u].size()) - 1; i >= 0; i--) {
        int v = graph[u][i];
        if(i < graph[u].size() - 1) {
            suff[i][0] = suff[i + 1][0];
            suff[i][1] = suff[i + 1][1];
        }
        if(v == p) continue;
        suff[i][0] = (suff[i][0] * dp[v][0]) % mod;
        suff[i][1] = (suff[i][1] * (dp[v][0] + dp[v][1])) % mod;
    }
    for(int i = 0; i < graph[u].size(); i++) {
        int v = graph[u][i];
        if(v == p) continue;
        for(int j = 0; j <= 1; j++) {
            up[v][j] = up[u][j];
            //cout << v << " " << i << "\n";
            if(i == 0 && i + 1 < graph[u].size())
                up[v][j] = (up[v][j] * suff[i + 1][j]) % mod;
            else if(i > 0 && i == graph[u].size() - 1)
                up[v][j] = (up[v][j] * pref[i - 1][j]) % mod;
            else if(i > 0 && i < graph[u].size() - 1) {
                //cout << pref[i - 1][j] << " " << suff[i + 1][j] << " " << j << " " << i << "\n";
                up[v][j] = (up[v][j] * ((pref[i - 1][j] * suff[i + 1][j]) % mod)) % mod;
            }
            if(j == 1)
                up[v][j] = (up[v][j] + up[v][0]) % mod;
        }
    }
    for(int i = 0; i < graph[u].size(); i++) {
        int v = graph[u][i];
        if(v == p) continue;
        redfs(v, u);
    }
}

