ll recur(ll cur,ll pre, ll n)
{
    if(cur>n) return 0;
    ll len=cur-pre;
    if(dp[cur][len]!=-1) return dp[cur][len];
    ll temp=0;
    temp+=m[cur];
    if(len==1)
         temp+=max(recur(cur+len-1,cur,n),recur(cur+len+1,cur,n));
    else temp+=max(recur(cur+len-1,cur,n), max(recur(cur+len,cur,n),recur(cur+len+1,cur,n)));
    dp[cur][len]=temp;
    return temp;
}
