ll N,M;

//普通に木dp
vector<ll> dp;
void dfs1(vector<vector<ll>> &g, ll v, ll p) {
	//葉の場合はすぐ返す
	if(g[v].size()==1 && p!=-1){
		dp[v]=1;
		return;
	}

	for(ll nextv : g[v]){
		if(nextv==p) continue;
		dfs1(g, nextv, v);
	}

	//各子供の計算結果dp[nextv]を集計してdp[v]を作る
	ll ans=1;
	for(ll nextv : g[v]){
		if(nextv==p) continue;
		ans*=(dp[nextv]+1);
		ans%=M;
	}
	dp[v]=ans;
}

//vが根になったときの気持ちになってみる
//pval=vが根になったときのdp[p]相当の値
vector<ll> dpans;
void dfs2(vector<vector<ll>> &g, ll v, ll p, ll pval) {
	ll gvsize=g[v].size();
	//dpt[i]=vが根になったときのdp[i]
	//dpleft,dpright=左右からの累積mergeした値
	//必要なら初期値変えること！
	vector<ll> dpt(gvsize,0),dpleft(gvsize+1,1),dpright(gvsize+1,1);
	for (ll i = 0; i < gvsize; i++) {
		ll nextv=g[v][i];
		if(nextv==p) dpt[i]=pval;
		else dpt[i]=dp[nextv];
	}

	//根vの子x,yが返してきた値dp[x],dp[y]をマージする
	//kosux,kosuyはこの問題専用に追加したので、問題に応じて変えてね
	auto merge = [&](ll dpx, ll dpy){
		return dpx*(dpy+1);
	};
	for (ll i = 0; i < gvsize; i++) {
		dpleft[i + 1] = merge(dpleft[i], dpt[i])%M;
		dpleft[i + 1] %= M;
	}
	for (ll i = gvsize - 1; i >= 0; i--) {
		dpright[i] = merge(dpright[i + 1], dpt[i]);
		dpright[i] %= M;
	}

	dpans[v]=dpright[0];

	for (ll i = 0; i < gvsize; i++) {
		ll nextv=g[v][i];
		if(nextv==p) continue;
		//vval=次の根とする頂点nextv以外をマージした計算結果 dp[v]相当の値
		ll vval=dpleft[i] * dpright[i + 1];//merge(dpleft[i], dpright[i + 1]);
		vval%=M;
		dfs2(g, nextv, v, vval);
	}
}

