const int MAXN=1e5+5;
map<int,int> dp[MAXN][2];
vi dp_blk[MAXN][2];
vvi adj(MAXN);
int N,MOD;
int BLK = 500;


int dfs(int u, int p, int col) {
    if(dp[u][col].count(p))
        return dp[u][col][p];

    int blks = ((int)adj[u].size() + BLK-1) / BLK;
    ll res=1;

    FOR(i,blks) {
        int idx_from = i*BLK;
        int idx_to = min( (i+1)*BLK-1, (int)adj[u].size()-1 );
        int u_from = adj[u][idx_from];
        int u_to = adj[u][idx_to];

        if(u_from<=p && p<=u_to) {
            RNG(j, idx_from, idx_to) {
                int to = adj[u][j];
                if(to!=p)
                    res = res * dfs(to, u, col) % MOD;
            }
            continue;
        }

        if(dp_blk[u][col][i]<0) {
            int rez=1;
            RNG(j, idx_from, idx_to) {
                int to = adj[u][j];
                rez = rez * dfs(to, u, col) % MOD;
            }
            dp_blk[u][col][i] = rez;
        }

        res = res*dp_blk[u][col][i] % MOD;
    }

    if(p>=1 && col==0)
        res += dfs(u, p, 1);

    return dp[u][col][p]=res%MOD;
}

