        adj[a].push_back(b);
        adj[b].push_back(a);
    }

    RNG(u,1,N) {
        int blks = ((int)adj[u].size() + BLK-1) / BLK;
        FOR(i,2)
            dp_blk[u][i].resize(blks, -1);
        sort(ALL(adj[u]));
    }

    RNG(i,1,N)
        cout<<dfs(i, -1, 0)<<endl;

    return 0;
}

