void dfs2(int u = 0 , int p = -1, int up = 0)
{
    ans[u] = int(1LL * dp[u] * (up + 1) % m) ;
    vector<int > _prefix ;
    vector<int > _suffix (adjList[u].size());
    int prev = 1 ;
    for(int v : adjList[u])
        if(v != p)
        {
            _prefix.push_back(prev) ;
            prev = int(1LL * prev * (1 + dp[v]) % m) ;
        }
        else
            _prefix.push_back(1);
    prev = 1 ;
    for(int i = adjList[u].size() - 1 ; i >= 0 ; i--)
    {
        int v = adjList[u][i] ;
        if(v != p)
        {
            _suffix[i] = prev ;
            prev = int(1LL * prev * (1 + dp[v]) % m) ;
        }
        else
            _suffix[i] = 1 ;
    }
    for(int i = 0 ; i < adjList[u].size() ; i++)
    {
        int v = adjList[u][i];
        if(v != p)
            dfs2(v , u, int(1LL * (1LL * (up + 1) * _prefix[i] % m) * _suffix[i] % m) ) ;
    }
}

