using u32 = uint32_t;
template<class MM, class U, class CM, class MA>
struct Rerooting {
	MM merge_monoid;
	U unity;
	CM child_to_monoid;
	MA merge_all;
	vector<U> dp, dp_reroot;
	Rerooting(MM mm, U u, CM cm, MA ma) : merge_monoid(mm), unity(u), child_to_monoid(cm) ,merge_all(ma) {}
	template<class graph>
	void build(const graph& g, u32 root = 0) {
		dp.resize(g.size(), unity);
		dp_reroot.resize(g.size(), unity);

		auto dfs = [&](auto&& f, u32 v, u32 parent = -1) -> U {
			for (auto& e : g.e[v]) {
				if (e.to == parent) continue;
				dp[v] = merge_monoid(dp[v], child_to_monoid(f(f, e.to, v)));
			}
			return dp[v] = merge_all(dp[v], v);
		};
		dfs(dfs, root);
		auto dfs_reroot = [&](auto&& f, u32 v, U parent_data, u32 parent = -1) -> void {
			vector<U> left_accum(g.e[v].size()+1, unity);
			vector<U> right_accum(g.e[v].size()+1, unity);
			{
				u32 i = 0;
				for (auto& e : g.e[v]) {
					i++;
					left_accum[i] = right_accum[i-1] = child_to_monoid(e.to == parent ? parent_data : dp[e.to]);
				}
			}
			for (u32 i = 1; i < left_accum.size(); i++) left_accum[i] = merge_monoid(left_accum[i-1], left_accum[i]);
			for (u32 i = right_accum.size() - 1; 0 < i; i--) right_accum[i-1] = merge_monoid(right_accum[i-1], right_accum[i]);
			dp_reroot[v] = merge_all(left_accum.back(), v);
			{
				u32 i = 0;
				for (auto& e : g.e[v]) {
					i++;
					if (e.to == parent) continue;
					f(f, e.to, merge_all(merge_monoid(left_accum[i-1], right_accum[i]), v), v);
				}
			}
		};
		dfs_reroot(dfs_reroot, root, unity);
	}
};

template<class MM, class U, class CM, class MA>
Rerooting<MM, U, CM, MA> make_rerooting(MM mc, U cu, CM cm, MA ma) {
	return Rerooting<MM, U, CM, MA>(mc, cu, cm, ma);
}

