LL POW(LL x, LL y)
{
    LL ans = 1;
    LL base = x;
    while (y)
    {
        if (y & 1)
        {
            ans *= base;
            ans %= MOD;
        }
        base = base * base;
        base %= MOD;
        y = y >> 1;
    }
    return ans;
}
LL phi(LL n)
{
    LL result = n;
    for (LL i = 2; i * i <= n; i++)
    {
        if (n % i == 0)
        {
            while (n % i == 0)
                n /= i;
            result -= result / i;
        }
    }
    if (n > 1)
        result -= result / n;
    return result;
}

LL dfs(LL s)
{
    if (!visited[s])
    {
        visited[s] = true;
        dp[s] = 1;
        for (auto x : adj[s])
        {
            dp[s] *= (dfs(x) + 1);
            dp[s] %= MOD;
        }
        return dp[s] % MOD;
    }
    else
    {
        return 0;
    }
}

LL inverse(LL a, LL m)
{
    return POW(a, phi(m) - 1);
}

void dfs2(LL s, LL par)
{
    if (!visited[s])
    {
        visited[s] = true;
        LL mult = dp[s] + 1;
        LL ans = dp[par];
       // dp[s] = (dp[s] * (dp[par])) % MOD;
        LL inv = inverse(mult, MOD);
        ans = (ans * inv) % MOD;
        dp[s] = (dp[s] * (ans + 1)) % MOD;
        dp_final[s] = dp[s];
        for (auto &x : adj[s])
        {
            dfs2(x, s);
        }
    }
}
