    int D = nxt[u].size();
    rep(i,D){
        int v = nxt[u][i];
        if (v == p) {
            continue;
        }
        if (dp[u][i] == -1) {
            dp[u][i] = f(v,u);
        }
        (ans *= (dp[u][i] + 1)) %= MOD;
    }

    return ans;
}

void solve(int N,int M,vi& x,vi& y) {
    MOD = M;

    nxt.resize(N); nxtR.resize(N);
    dp.resize(N);
    degr.resize(N);

    rep(i,N-1){
        int u=x[i]-1, v=y[i]-1;
        nxt[u].pb(v);
        nxt[v].pb(u);
    }
    rep(u,N) {
        int D = nxt[u].size();
        degr[u] = D;
        dp[u].assign(D, -1);
        rep(i,D) {
            int v = nxt[u][i];
            nxtR[u][v] = i;
        }
    }

    vii order(N);
    rep(i,N) order[i] = ii(degr[i], i);
    sort(ALL(order), greater<ii>());

    vll ans(N);

    for (ii x: order) {
        int u = x.second, D = x.first;
        assert(IN(u, 0, N-1));
        ans[u] = f(u);

        vll acc_left(D+1), acc_right(D+1);
        acc_left[0] = acc_right[D] = 1;
        for (int i=0; i<D; ++i) {
            assert(IN(i, 0, dp[u].size()));
            acc_left[i+1] = (acc_left[i] * (dp[u][i] + 1)) % MOD;
        }
        for (int i=D-1; i>=0; --i) {
            assert(IN(i, 0, dp[u].size()));
            acc_right[i] = (acc_right[i+1] * (dp[u][i] + 1)) % MOD;
        }
        rep(i,D) {
            int v = nxt[u][i];
            assert(IN(v, 0, dp.size()-1));
            assert(IN(u, 0, pi.size()-1));
            int j = nxtR[v][u];
            assert(IN(j, 0, dp[v].size()-1));
            dp[v][j] = (acc_left[i] * acc_right[i+1]) % MOD;
        }
    }

    rep(u,N) {
        printf("%lld\n", ans[u]);
    }
}

int main() {
    int N, M; scanf("%d%d", &N, &M);
    vi x(N-1), y(N-1);
    rep(i, N-1) {
        scanf("%d%d", &x[i], &y[i]);
    }
    solve(N,M,x,y);
    return 0;
}

