			u *= f(s[poz][i], poz);
			u %= MOD;
		}
	}
	if(p != -1)
	{
		return biok[poz] = modz(u, 1);
	}
	else
	{
		return biog[poz] = u;
	}
}
long long r(int poz, int p)
{
	long long u = 1;
