vector<int> dp1,dp2;

void dfs1(auto &E,int now,int parent){
	dp1[now] = 1;
	for(int i=0;i<E[now].size();i++){
		int to = E[now][i];
		if(to==parent)continue;
		dfs1(E,to,now);
		dp1[now] = mod(dp1[now] * (dp1[to] + 1));
	}
}

void dfs2(auto &E,int now,int parent,int X){
	vector<int> temp(E[now].size(),1);
	dp2[now] = 1;
	for(int i=0;i<E[now].size();i++){
		int to = E[now][i];
		if(to==parent)continue;
		temp[i] = mod(dp1[to]+1);
		dp2[now] = mod(dp2[now] * temp[i]);
	}

	dp2[now] = mod(dp2[now] * (X+1));

	vector<int> t1(E[now].size()+1,1),t2(E[now].size()+1,1);
	for(int i=0;i<E[now].size();i++){
		t1[i+1] = mod(t1[i] * temp[i]);
	}
	for(int i=E[now].size()-1;i>=0;i--){
		t2[i] = mod(t2[i+1] * temp[i]);
	}

	for(int i=0;i<E[now].size();i++){
		int to = E[now][i];
		if(to==parent)continue;
		int A = mod(t1[i] * t2[i+1]);
		dfs2(E,to,now,mod(A*(X+1)));
	}
}

