void solve(istream& in, ostream& out) {
  auto n = next<int>(in);
  auto mod = next<int64_t>(in);
  vec2d<int> g(n);
  FOR(i, n - 1) {
    auto x = next<int>(in) - 1;
    auto y = next<int>(in) - 1;
    g[x].push_back(y);
    g[y].push_back(x);
  }
  vec<int64_t> fBlack(n, 0), fUp(n, 0);

  function<void(int, int)> dfs1 = [&](int v, int p) {
    fBlack[v] = 1;
    for (auto to : g[v]) {
      if (to == p) continue;
      dfs1(to, v);
      fBlack[v] *= (fBlack[to] + 1) % mod;
      fBlack[v] %= mod;
    }
    if (p != -1) {
      g[v].erase(find(all(g[v]), p));
    }
  };
  dfs1(0, -1);
  dbg(fBlack);

  function<void(int, int, int64_t)> dfs = [&](int v, int p, int64_t upMul) {
    fUp[v] = upMul;
    if (g[v].empty()) return;
    vec<int64_t> prefix(g[v].size()), suffix(g[v].size());
    prefix[0] = (fBlack[g[v][0]] + 1) % mod;
    FOR(i, g[v].size()) if (i) {
        int64_t c = (fBlack[g[v][i]] + 1) % mod;
        prefix[i] = (prefix[i - 1] * c) % mod;
      }
    suffix[g[v].size() - 1] = (fBlack[g[v][g[v].size() - 1]] + 1) % mod;
    for (int i = (int) g[v].size() - 2; i >= 0; --i) {
      int64_t c = (fBlack[g[v][i]] + 1) % mod;
      suffix[i] = (suffix[i + 1] * c) % mod;
    }

    int64_t u = 1;
    if (p != -1) u = (fUp[p] + 1) % mod;
    int64_t pr = 1, su;
    FOR(i, g[v].size()) {
      int to = g[v][i];

      if (i + 1 >= g[v].size()) {
        su = 1;
      } else {
        su = suffix[i + 1];
      }

      int64_t d = (pr * su) % mod;
      d *= u;
      d %= mod;
      ++d;
      d %= mod;

      dfs(to, v, d);
      pr = prefix[i];
    }
  };
  dfs(0, -1, 1);
  FOR(i, n) {
    out << (fBlack[i] * fUp[i]) % mod << "\n";
  }
}

