                for (int i = 0; i < g[u].size(); i ++) {
                        long long nxt = (i > 0 ? left[u][i - 1] : 1) * (i < (int) g[u].size() - 1 ? right[u][i + 1] : 1) % m;
                        dfs2(g[u][i], nxt * (r + 1) % m);
                }
        };
        dfs2(0, 0);
        rep(i, n) {
                printf("%lld\n", ans[i]);
        }
        return 0;
}

