void solve() {
    ll n, m;
    cin >> n >> m;
    vc<int> x(n - 1), y(n - 1);
    REP(i, 0, n - 1) {
        cin >> x[i] >> y[i];
        --x[i], --y[i];
    }

    vvc<int> edges(n - 1);
    REP(i, 0, n - 1) edges[i] = {x[i], y[i]};

    auto merge = [](mint s, mint t) -> mint { return s * t; }; // 部分木のマージ
#pragma GCC diagnostic ignored "-Wunused-parameter"
    auto addNode = [](mint val, int id) -> mint { return val + 1; }; // 頂点の追加
#pragma GCC diagnostic warning "-Wunused-parameter"
    // dump(m, edges);
    ReRooting<mint> rr(n, edges, mint(m, 1LL), merge, addNode);
    // dump(1);

    REP(i, 0, n) cout << (rr.query(i) - 1) << endl;
}

// entry point
int main() {
    solve();
    return 0;
}

