int MOD;

int modExp(int base, int power) {
    if (power == 0) {
        return 1;
    } else {
        int cur = modExp(base, power / 2); cur = cur * cur; cur = cur % MOD;
        if (power % 2 == 1) cur = cur * base;
        cur = cur % MOD;
        return cur;
    }
}

int inv(int base) {
    int g = MOD, r = base, x = 0, y = 1;
    while (r != 0) {
        int q = g / r;
        g %= r; swap(g, r);
        x -= q * y; swap(x, y);
    }
    return x < 0 ? x+MOD : x;
}

int mul(int A, int B) {
	return (A*B)%MOD;
}

int add(int A, int B) {
	return (A+B)%MOD;
}

int dvd(int A, int B) {
    return mul(A, inv(B));
}

int sub(int A, int B) {
    return (A-B+MOD)%MOD;
}

void dfs1(int node, int parent = -1) {
	long long tot = 1;
	for(int it : v[node]) {
		if(it == parent)continue;
		dfs1(it, node);
		tot *= (1 + dp[it]);
	}
	dp[node] = tot;
}

void dfs2(int node, int parent = -1) {
	ans[node] = dp[node];
	for(auto it : v[node]) {
		if(it == parent)continue;
		dp[node] /= (1 + dp[it]);
		dp[it] *= 1 + dp[node];
	//	dp[it] = mul(dp[it], 1 + dp[node]);
		dfs2(it, node);
		dp[it] = dp[it] / (1 + dp[node]);
		//dp[it] = mul(dp[it], inv(1 + dp[node]));	
		//dp[node] = mul(dp[node], 1 + dp[it]);
		dp[node] *= 1 + dp[it];
	}	
}


