  for (auto v: g[u]) if (v != p) {
    pans[v] = ways;
    ways *= dp[v]+1;
    ways %= mod;
  }
  reverse(all(g[u]));

  ways = 1;
  for (auto v: g[u]) if (v != p) {
    sans[v] = ways;
    ways *= dp[v]+1;
    ways %= mod;
  }
  reverse(all(g[u]));

  ans[u] *= dp[u];
  ans[u] %= mod;

  for (auto v: g[u]) if (v != p) {
    dfs2(v, u);
  }
}

