void dfs(ll u, ll p = -1) {
    blackdown[u] = blackdown1[u] = 1;
    for (int i = 0; i < g[u].size(); i++) {
        if (g[u][i] == p)
            continue;
        ll to = g[u][i];
        dfs(to, u);
        blackdown[u] = (blackdown[u] * (blackdown[to] + 1)) % m;
        pmult[u].pb(blackdown[u]);
        tto[to] = pmult[u].size() - 1;
        // blackdown1[u] = (blackdown1[u] * (blackdown1[to] + 1));
    }
    blackdown[u] = blackdown1[u] = 1;
    for (int i = g[u].size() - 1; i >= 0; i--) {
        if (g[u][i] == p)
            continue;
        ll to = g[u][i];
        blackdown[u] = (blackdown[u] * (blackdown[to] + 1)) % m;
        smult[u].pb(blackdown[u]);
        // blackdown1[u] = (blackdown1[u] * (blackdown1[to] + 1));
    }
    reverse(smult[u].begin(), smult[u].end());
}


ll get(ll u, ll to) {
    if (pmult[u].size() == 1)
        return 1;
    if (tto[to] == 0)
        return smult[u][1];
    if (tto[to] == pmult[u].size() - 1)
        return pmult[u][pmult[u].size() - 2];
    return (pmult[u][tto[to] - 1] * smult[u][tto[to] + 1]) % m;
}


void dfss(ll u, ll p=-1) {
    if (p != -1) {
        // blackup1[u] = (1 + blackup1[p] * ((blackdown1[p] / (blackdown1[u] + 1)) % m)) % m;
        // ans1[u] = (blackup1[u] * blackdown[u]) % m;
        blackup[u] = (1 + blackup[p] * get(p, u));
        ans[u] = (blackdown[u] * blackup[u]) % m;
        // cout << u << " " << blackdown[u] << " " << blackdown1[u] << " " << blackup[u] << " " << blackup1[u] << " " << m << endl;
    } else {
        // cout << blackdown[u] << endl;
        blackup1[u] = blackup[u] = 1;
        ans1[u] = ans[u] = blackdown[u];
    }
    for (int i = 0; i < g[u].size(); i++)
        if (g[u][i] != p)
            dfss(g[u][i], u);
}


