inline int mul(ll a, ll b){return (a*b)%mod;}
inline int add(ll a, ll b){return (a+b)%mod;}

int getin(int v, int idx){
	int ret = 1;
	if (idx > 0) ret = mul(ret, pre[v][idx-1]);
	if (idx < int(sons[v].size())-1) ret = mul(ret, suf[v][idx+1]);
	return ret;
}

void dfsin(int v, int p = -1){
	for(int &e: vs[v]) if (e == p) {swap(e, vs[v].back()); break;}
	int ways = 1, aux;
	for(int &e: vs[v]) if (e != p){
		dfsin(e, v);
		aux = add(in[e], 1);
		ways = mul(ways, aux);
		sons[v].push_back(aux);
	}
	in[v] = ways;
}

void dfsout(int v, int p = -1){
	if (sons[v].size() == 0) return;
	for(int i = 0; i<vs[v].size(); i++)
		if (vs[v][i] != p) out[vs[v][i]] = add(1, mul(getin(v, i), out[v]));

	for(int &e: vs[v]) if (e != p) dfsout(e, v);
}

