int gcd(int a,int b){
	if(b==0) return (a!=0)?a:1;
	else return gcd(b,a%b);
}
int d, x, y;
void extendedEuclid(int A, int B) {
    if(B == 0) {
        d = A;
        x = 1;
        y = 0;
    }
    else {
        extendedEuclid(B, A%B);
        int temp = x;
        x = y;
        y = temp - (A/B)*y;
    }
}
int modInverse(int A,int m){
    extendedEuclid(A,m);
    return (x%m+m)%m;
}
int mul(int a,int b){
	return ((a%mod)*(b%mod))%mod;
}
void mul_self(int& a,int b){
	a = ((a%mod)*(b%mod))%mod;
	return ;
}
void add_self(int& a,int b){
	a = (a+b)%mod;
	return ;
}
int dfs(int u,int fp,int color){
	if(dp[u][color]!=-1){
		return dp[u][color];
	}
	int p = 1;
	for(auto child: v[u]){
		int tmp = 0;
		if(child!=fp){
			add_self(tmp,dfs(child,u,color));
			if(color==1){
				add_self(tmp,dfs(child,u,1-color));
			}
			mul_self(p,tmp);
		}
	}
	return dp[u][color] = p;
}
void dfs2(int u,int fp,int par_white,int par_black){
	ans[u] = dp[u][1];
	if(fp!=-1){
		mul_self(ans[u],(par_white+par_black)%mod);
	}
	int tmp_white,tmp_black;
	for(auto child: v[u]){
		if(child!=fp){

			int g = gcd(dp[child][0],mod);
			int tmpdpchild = dp[child][0]/g;
			int m = mod/g;
			int tmpdpu = dp[u][0]/g;
			int tmp2 = modInverse(tmpdpchild,m);
			tmp_white = ((tmpdpu%mod)*(tmp2%mod))%mod;
			if(fp!=-1){
				mul_self(tmp_white,par_white);
			}

			g = gcd((dp[child][0]+dp[child][1])%mod,mod);
			tmpdpchild = (dp[child][0]+dp[child][1])%mod/g;
			tmpdpu = dp[u][1]/g;
			m = mod/g;
			tmp2 = modInverse(tmpdpchild,m);
			tmp_black = ((tmpdpu%mod)*(tmp2%mod))%mod;
			if(fp!=-1){
				mul_self(tmp_black,(par_white + par_black)%mod);
			}

			dfs2(child,u,tmp_white,tmp_black);
		}
	}
}
