int N,M;
LLI dp[101000];
LLI dp2[101000];
vector<bool> visit(101000);
vector<vector<LLI>> prod1, prod2;

LLI rec(vector<vector<int>> &tree, int cur, int par){
  if(visit[cur]) return dp[cur];
  visit[cur] = true;

  dp[cur] = 1;

  for(auto next : tree[cur]){
    if(next == par) continue;
    (dp[cur] *= (rec(tree,next,cur)+1)%M) %= M;
  }

  int c = tree[cur].size();
  if(par != -1) --c;

  prod1[cur].resize(c+1);
  prod2[cur].resize(c+1);

  prod1[cur][0] = 1;
  prod2[cur][c] = 1;

  REP(i,c){
    prod1[cur][i+1] = (prod1[cur][i] * (dp[tree[cur][i]]+1)%M) % M;
    prod2[cur][c-1-i] = (prod2[cur][c-i] * (dp[tree[cur][c-1-i]]+1)%M) % M;
  }

  return dp[cur];
}

LLI rec2(vector<vector<int>> &tree, int cur, int par, int index){
  if(visit[cur]) return dp2[cur];
  visit[cur] = true;

  if(par == -1) dp2[cur] = 0;
  else{
    dp2[cur] = ((prod1[par][index]*prod2[par][index+1])%M * (dp2[par]+1)%M) % M;
  }

  int i = 0;
  for(auto next : tree[cur]){
    if(next == par) continue;
    rec2(tree, next, cur, i);
    ++i;
  }

  return dp2[cur];
}

int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);

  cin >> N >> M;
  vector<vector<int>> tree(N);
  REP(i,N-1){
    int x,y; cin >> x >> y;
    --x, --y;
    tree[x].push_back(y);
    tree[y].push_back(x);
  }

  prod1.resize(N);
  prod2.resize(N);

  rec(tree, 0, -1);
  fill(ALL(visit),false);
  rec2(tree, 0, -1, 0);

  REP(i,N){
    LLI ans = ((dp2[i]+1)%M * dp[i]) % M;
    cout << ans << endl;
  }

  return 0;
}

