    for(auto x : v[node]){
        if(x != parent){
            DFS(x, node);
            moduri *= (dp[x] + 1);
        }
    }
    dp[node] = moduri;
}

void Rerooting(int node, int parent){
    sol[node] = dp[node] % MOD;
    for(auto x : v[node]){
        if(parent != x){
            int old = dp[node], _old = dp[x];
            dp[node] /= (dp[x] + 1);
            dp[x] *= (dp[node] + 1);
            Rerooting(x, node);
            dp[node] = old;
            dp[x] = _old;
        }
    }
}

