void dfs(int p,int pre){
    dp[p] = 1;
    for(auto i:v[p]){
        if(i!=pre){
            dfs(i,p);
            suf[p].push_back(dp[p]);
            dp[p] = (dp[p] * (dp[i]+1)) % mod;
        }
    }
    ll now = 1;
    int m = v[p].size();
    for(int i=0;i<v[p].size();i++){
        prf[p].push_back(now);
        now *= dp[v[p][m - i - 1]]+1;
        now %= mod;
    }
}

ll ans[100010];

void solve(int p,int pre,ll d){
    ans[p] = (d+1)%mod;
    ans[p] *= dp[p];
    ans[p] %= mod;
    int now = 0;
    int m = v[p].size();
    for(auto i:v[p]){
        if(i != pre){
            ll ret = suf[p][now] * prf[p][m - 1 - now];
            //db4(p,i,suf[p][now],prf[p][m-1-now]);
            ret %= mod;
            //ret *= (d+1);
            solve(i,p,ret);
            now++;
        }
    }
}

