using namespace std;

int main() {
    int N, M; cin >> N >> M;
    vector<vector<int>> G(N);
    for(int i = 0; i < N - 1; ++i) {
        int a, b; cin >> a >> b;
        a--, b--;
        G[a].emplace_back(b);
        G[b].emplace_back(a);
    }
    vector<int64_t> dp(N), ans(N);
    auto dfs = [&](auto &&dfs, int cur, int pre) -> int64_t {
        dp[cur] = 1;
        for(auto &to : G[cur]) {
            if(to == pre) continue;
            dp[cur] *= (dfs(dfs, to, cur) + 1);
            dp[cur] %= M;
        }
        return dp[cur];
    };
    auto efs = [&](auto &&efs, int cur, int pre, int64_t ret) -> void {
        vector<int> V;
        for(auto &e : G[cur]) {
            if(e != pre) V.push_back(e);
        }
        int n = V.size();
        vector<int64_t> L(n), R(n);
        for(int i = 0; i < n; ++i) {
            L[i] = dp[V[i]] + 1;
            if(i) L[i] *= L[i - 1];
            L[i] %= M;
        }
        for(int i = n - 1; i >= 0; --i) {
            R[i] = dp[V[i]] + 1;
            if(i != n - 1) R[i] *= R[i + 1];
            R[i] %= M;
        }
        for(int i = 0; i < n; ++i) {
            int64_t l = i ? L[i - 1] : 1;
            int64_t r = i + 1 < n ? R[i + 1] : 1;
            ans[V[i]] = ((l * r) % M) * ret + 1;
            ans[V[i]] %= M;
            efs(efs, V[i], cur, ans[V[i]]);
        }
    };
    ans[0] = 1;
    dfs(dfs, 0, 0);
    efs(efs, 0, 0, 1);
    for(int i = 0; i < N; ++i) {
        dp[i] *= ans[i];
        cout << dp[i] % M << '\n';
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
using ll = long long int;

const int N = 1e5+9;
struct vertex { vector<int> edge; };
ll n, m;
vertex g[N];
map<int, ll> dp[N]; // node=黒 to以降の塗り方

// ALL to. dp[node][to]
// return 1 + PROD(dp[node][to])
ll out(int node, int from) {
    ll res = 1;
    for(auto to : g[node].edge) {
        if(to == from)  continue;
        if(!dp[node].count(to))  dp[node][to] = out(to, node);
        res = res * dp[node][to] % m;
    }
    return (1 + res) % m;
}

// ALL from. dp[from][node]
void in(int node, int exc) {
    vector<ll> vals;
    for(auto to : g[node].edge)  vals.push_back(dp[node][to]);

    vector<ll> left{1}, right{1};
    int sz = vals.size();
    for(int i = 0; i < sz; i++) {
        left.push_back( left.back() * vals[i] % m );
        right.push_back( right.back() * vals[sz-1-i] % m );
    }
    right.pop_back();  reverse(begin(right), end(right));

    int i = 0;
    for(auto from : g[node].edge) {
        if(from == exc)  continue;
        dp[from][node] = (left[i] * right[i] + 1) % m;
        i++;
        in(from, node);
    }
}

int main() {
    cin >> n >> m;
    for(int i = 0; i < n-1; i++) {
        int x, y;  cin >> x >> y;
        x--;  y--;
        g[x].edge.push_back(y);
        g[y].edge.push_back(x);
    }

    out(0, -1);
    in(0, -1);

    for(int node = 0; node < n; node++) {
        ll ans = 1;
        for(auto to : g[node].edge)  ans = ans * dp[node][to] % m;
        cout << ans << endl;
    }
}

