bool ok(node &r) {
    long long int ad = 1;
    r.pre.PB(1);
    for(int i = 0 ; i < r.ar.size() ; i++ ) {
        ad*=r.ar[i];
        ad%=m;
        r.pre.PB(ad);
    }
    reverse(r.ar.begin(),r.ar.end());
    ad = 1;
    r.suf.PB(1);
    for(int i = 0 ; i < r.ar.size() ; i++ ) {
        ad*=r.ar[i];
        ad%=m;
        r.suf.PB(ad);
    }
    reverse(r.ar.begin(),r.ar.end());
}

long long int del(node &r, long long int x) {
    return (r.pre[x]*r.suf[r.ar.size()-x-1])%m;
}

