    du[x]=1;
    if(px!=-1) {
        du[x]+=du[px]*((nd[px].ar.size()!=1)?del(nd[px],tu):1);
        du[x]%=m;
    }
    int tt = 0;
    for(int u: v[x]) {
        if(u!=px) dfs2(u,x,tt++);
    }
}

