int n, m;
vector<vector<int>> adj;
vector<int> par;
vector<mint> dp, ans;
mint dfs(int u = 0) {
    if (par[u] != -1) 
        adj[u].erase(find(adj[u].begin(), adj[u].end(), par[u]));
    mint s = 1;
    for (int v : adj[u]) {
        par[v] = u;
        s *= dfs(v);
    }
    return dp[u] = s + 1;
}
void dfs2(int u = 0, mint pa = 1) {
    int ch = adj[u].size();
    vector<mint> pre(ch, 1), suf(ch, 1);
    for (int i = 0; i < ch - 1; i++)
        pre[i + 1] = pre[i] * dp[adj[u][i]];
    for (int i = ch - 1; i > 0; i--)
        suf[i - 1] = suf[i] * dp[adj[u][i]];
    for (int i = 0; i < ch; i++) {
        dfs2(adj[u][i], (pa * pre[i] * suf[i]) + 1);
    }
    ans[u] = pa * (dp[u] - 1);
}

