ll extGCD(ll a, ll b, ll &x, ll &y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    ll d = extGCD(b, a%b, y, x); // 再帰的に解く
    y -= a / b * x;
    return d;
}

inline ll mod(ll a, ll m) {
    return (a % m + m) % m;
}

ll modinv(ll a, ll m) {
    ll x, y;
    extGCD(a, m, x, y);
    return mod(x, m); // 気持ち的には x % m だが、x が負かもしれないので
}


void dfs(int cur, int par) {
    dp[cur] = 1LL;
    for (int child : edge[cur]) {
        if (child == par) continue;
        dfs(child, cur);
        dp[cur] *= (dp[child] + 1LL) % m;
    }
}

void dfs2(int cur, int par, ll par_value) {
    dp[cur] = 1LL;
    for (int child : edge[cur]) {
        if (child == par) dp[cur] *= (par_value + 1LL) % m;
        else dp[cur] *= (dp[child] + 1LL) % m;
    }
    for (int child : edge[cur]) {
        if (child == par) continue;
        dfs2(child, cur, dp[cur] / (dp[child] + 1LL));
    }
}

