// 0 - white , 1 - black 

void dfs(int node, int par =-1 ) {
	dp[0][node] = dp[1][node] = 1 ; 

	for(auto i : g[node]) {
		if( i!= par) {
			dfs(i,node) ;
			dp[0][node] = (dp[0][node] * dp[0][i]) % m ;
			dp[1][node] = (dp[1][node] * (dp[0][i] + dp[1][i])) % m ;
		}
	}
}

void calc(int node, int par =-1 ) {
	int a = dp[0][node] ; 
	int b = dp[1][node] ; 
	dp[0][node] = dp[1][node] = 1 ; 

	vii pf[2], sf[2] ; 

	for(auto i : g[node]) {
		pf[0].eb(dp[0][i]) ;
		pf[1].eb((dp[0][i] + dp[1][i])%m) ; 
		sf[0].eb(dp[0][i]) ;
		sf[1].eb((dp[0][i] + dp[1][i])%m) ;
	}

	int s = sz(g[node]) ;

	rep(i,1,s) {
		pf[0][i] = (pf[0][i-1] * pf[0][i]) % m ; 
		pf[1][i] = (pf[1][i-1] * pf[1][i]) % m ;
	}

	rep(i,s-1,0) {
		sf[0][i] = (sf[0][i] * sf[0][i+1]) % m ;
		sf[1][i] = (sf[1][i] * sf[1][i+1]) % m ; 
	}

	ans[node] = sf[1][0] ; 

	int c = 0 ;

	for(auto i : g[node]) {
		if(i != par) {
			dp[0][node] = (c>0 ? pf[0][c-1] : 1) * (c < s-1 ? sf[0][c+1] : 1) % m;
			dp[1][node] = (c>0 ? pf[1][c-1] : 1) * (c < s-1 ? sf[1][c+1] : 1) % m;
			calc(i,node) ; 
		}
		++c ; 
	}

	dp[0][node] = a ;
	dp[1][node] = b ; 
} 

void solve() {
	cin >> n >> m ;
	rep(i,0,n-1) {
		int u,v; cin >> u >> v ;
		g[u].eb(v) ;
		g[v].eb(u) ;
	}

	dfs(1) ; 

	calc(1) ; 

	rep(i,1,n+1) cout << ans[i] << nl ;
}

