ll mod = 1000000007;
ll N;
vector<ll> pathes[105000];
ll parent[105000];
vector<ll> children[105000];
ll dp[105000];
ll dp2[105000];

void dfs(int now) {
    dp[now] = 1;
    for(int i = 0; i < pathes[now].size(); i++) {
        int to = pathes[now][i];
        if(to == parent[now]) continue;
        parent[to] = now;
        children[now].push_back(to);
        dfs(to);
        dp[now] *= (1 + dp[to]);
        dp[now] %= mod;
    }
}

void dfs2(int now, ll factor) {
    dp2[now] = dp[now] * factor % mod;
    vector<ll> R(children[now].size() + 1, 1);
    vector<ll> L(children[now].size() + 1, 1);
    for(int i = 1; i < R.size(); i++) {
        int to = children[now][i-1];
        L[i] = L[i-1] * (dp[to] + 1) % mod;
    }
    for(int i = (int)children[now].size() - 1; i >= 0; i--) {
        int to = children[now][i];
        R[i] = R[i+1] * (dp[to] + 1) % mod;
    }
    for(int i = 0; i < children[now].size(); i++) {
        int to = children[now][i];
        ll nowfactor = factor;
        nowfactor *= L[i];
        nowfactor %= mod;
        nowfactor *= R[i+1];
        nowfactor %= mod;
        nowfactor++;
        nowfactor %= mod;
        dfs2(to, nowfactor);
    }
}

