//            }
            if(x>1)
                x*=(suf2[u][i+1]%m)*(down[u][n-1].fi+1%m)%m;
            else
                x*=suf[u][i+1];
        }
//        cout<<v<<' '<<x<<endl;
        x%=m;
        if(u!=1)
