long dp1[1<<17],dp2[1<<17],mod;
int n;
vector<int>G[1<<17];
long gcd(long a,long b,long&x,long&y)
{
	if(!b)
	{
		x=1;
		y=0;
		return a;
	}
	long q=a/b;
	long g=gcd(b,a-q*b,x,y);
	long z=x-q*y;
	x=y;y=z;
	return g;
}
long mydiv(long a,long b)
{
	long x,y,z;
	z=gcd(b,mod,x,y);
	x%=mod;
	if(x<0)x+=mod;
	return a*x%mod/z;
}
long dfs1(int u,int p)
{
	dp1[u]=1;
	for(int i=0;i<G[u].size();i++)
	{
		if(G[u][i]!=p)
		{
			dp1[u]=dp1[u]*(dfs1(G[u][i],u)+1)%mod;
		}
	}
	return dp1[u];
}
void dfs2(int u,int p,long x)
{
	dp2[u]=dp1[u]*(x+1)%mod;
	for(int i=0;i<G[u].size();i++)
	{
		if(G[u][i]!=p)
		{
			dfs2(G[u][i],u,mydiv(dp2[u],dp1[G[u][i]]+1));
		}
	}
}
