	if(fs[x]!=-1)
		return fs[x];
	par[x]=p;
	ll sum=1;
	for(int i=0;i<ad[x].size();i++){
		if(ad[x][i]==p)
			continue;
		sum=(sum*(f(x,ad[x][i])+1))%m;
	}
	fs[x]=sum;
