struct Mod {
    static ll BASE;
    ll value = 0;
    static ll residue(ll value) { return (value % BASE + BASE) % BASE; }
    Mod(ll value)
    : value(residue(value)) {}
    Mod operator+(const Mod& rhs) const { return Mod(value + rhs.value); }
    void operator+=(const Mod& rhs) { *this = *this + rhs; }
    Mod operator-(const Mod& rhs) const { return Mod(value - rhs.value); }
    void operator-=(const Mod& rhs) { *this = *this - rhs; }
    Mod operator*(const Mod& rhs) const { return Mod(value * rhs.value); }
    void operator*=(const Mod& rhs) { *this = *this * rhs; }
};
ll Mod::BASE = 1000000007;

struct Edge {
    ll idx;
    ll x;
    ll y;
    Edge(ll idx, ll ax, ll ay) : idx(idx) {
        x = min(ax, ay);
        y = max(ax, ay);
    }
};

vector<Edge> edges;
vector<vector<Edge>> tree;
ll N, M;
vector<vector<unique_ptr<Mod>>> subtree; // 0=エッジの両端のうちidxの小さい側のsubtreeの数、1=大きい側のsubtreeの数

void calc_subtree(ll idx, ll ori) {
    if (subtree[idx][ori]) {
        return;
    }
    ll root = 0;
    if (ori == 0) {
        root = edges[idx].x;
    } else {
        root = edges[idx].y;
    }
    Mod res = 1;
    for (Edge e : tree[root]) {
        if (e.idx == idx) {
            continue;
        }
        ll next_ori;
        if (e.y == root) {
            next_ori = 0;
        } else {
            next_ori = 1;
        }
        calc_subtree(e.idx, next_ori);
        res *= *subtree[e.idx][next_ori];
    }
    res += 1;
    subtree[idx][ori] = make_unique<Mod>(res);
}

