        parr[i] = parr[i-1] * (dp[adjList[start][i-1]][0]+1);
        parr[i] %= modd;
    }
    suff[adjList[start].size()+1] = 1;
    for(int i=adjList[start].size();i>=1;--i){
        if(adjList[start][i-1] == par){
            suff[i] = 1;
