	pre[index][i]=pre[index][i-1]*(tmp[index][i-1]+1)%mod;
    }
    bac[index][len-1]=1;
    for(i=len-2;i>=0;i--)
    {
	bac[index][i]=bac[index][i+1]*(tmp[index][i+1]+1)%mod;
    }
}

