}

void dfsup(int u, int par){
	pref[0] = 1;
	for(int i = 0; i < (int)edge[u].size(); i++){
		int v = edge[u][i];
		pref[i + 1] = pref[i];
		if(v == par) continue;
		pref[i + 1] = (pref[i + 1] * (down[v] + 1)) % mod;
	}
	suf[(int)edge[u].size() + 1] = 1;
	for(int i = (int)edge[u].size() - 1; i >= 0; i--){
		int v = edge[u][i];
		suf[i + 1] = suf[i + 2];
		if(v == par) continue;
		suf[i + 1] = (suf[i + 1] * (down[v] + 1)) % mod;
	}
	for(int i = 0; i < (int)edge[u].size(); i++){
		int v = edge[u][i];
		if(v == par) continue;
		up[v] = pref[i] * suf[i + 2] % mod * (up[u] + 1) % mod;
		down[v] = down[v] * (up[v] + 1) % mod;
	}
	for(int v : edge[u]){
		if(v == par) continue;
		dfsup(v, u);
	}
}

