const int mxn = 100010;
ll dp[mxn], tmp[mxn], ans[mxn], mod;
int N;

vector<int> adj[mxn];

void dfs_dp(int node, int parent)
{
	for(auto x:adj[node])
		if(x!=parent) dfs_dp(x, node);

	dp[node] = 1ll; 
	for(auto x:adj[node])
		if(x!=parent) dp[node]*=(dp[x]+1), dp[node]%=mod;
}

void dfs_ans(int node, int parent)
{
	ans[node] = 1ll;
	for(auto x:adj[node])
		ans[node]*=(tmp[x]+1), ans[node]%=mod;

	vector<int> pre((int) adj[node].size()+2, 1ll);
	vector<int> suff((int) adj[node].size()+2, 1ll);

	for(int i=1; i<=(int) adj[node].size(); i++)
		pre[i] = pre[i-1]*(tmp[adj[node][i-1]]+1), pre[i]%=mod;

	for(int i=(int) adj[node].size(); i>=1; i--)
		suff[i] = suff[i+1]*(tmp[adj[node][i-1]]+1), suff[i]%=mod;

	for(int i=1; i<=(int) adj[node].size(); i++) {
		if(adj[node][i-1]!=parent) {
			tmp[node] = pre[i-1]*suff[i+1];
			tmp[node]%=mod;
			dfs_ans(adj[node][i-1], node);
		}
	}

	tmp[node] = dp[node];
}

void process(int root)
{
	dfs_dp(root, -1);
	for(int i=1; i<=N; i++) tmp[i] = dp[i];
	dfs_ans(root, -1);
}

