ll n, M, down[N], up[N], dpl[N], dpr[N];
vector<ll> f[N], g[N];
void Tamiz(int v, int par){
	for(int i = 0 ; i < f[v].size() ; i ++){
		if(f[v][i] == par) continue ;
		Tamiz(f[v][i], v) ; g[v].push_back(f[v][i]) ;
	}
}
void dfs1(int v){
	down[v] = 1 ;
	for(int i = 0 ; i < g[v].size() ; i ++){
		int u = g[v][i] ; dfs1(u) ; 
		down[v] = (down[v] * (1+down[u])) % M ; 
	}
	if(!g[v].size()) return ;
	dpl[g[v][0]] = dpr[g[v].back()] = 1 ;
	for(int i = 1 ; i < g[v].size() ; i ++) dpl[g[v][i]] = (dpl[g[v][i-1]] * (down[g[v][i-1]]+1)) % M ; 
	for(int i = g[v].size()-2 ; i >= 0 ; i --) dpr[g[v][i]] = (dpr[g[v][i+1]] * (down[g[v][i+1]]+1)) % M ; 
} 
void dfs(int v, int par){
	up[v] = (1 + (up[par]*(dpl[v]*dpr[v])%M))%M ;
	for(int i = 0 ; i < g[v].size() ; i ++) dfs(g[v][i], v) ;
}
