  vll lefm(nc, 1), rigm(nc, 1);
  repLRE(i, 1, nc - 1) lefm[i] =
      (lefm[i - 1] * ((1 + ans[chl[i - 1]]) % m)) % m;
  rrepLRE(i, nc - 2, 0) rigm[i] =
      (rigm[i + 1] * ((1 + ans[chl[i + 1]]) % m)) % m;
  map<ll, ll> uv;
  rep(i, nc) { uv[chl[i]] = (((lefm[i] * rigm[i]) % m) * (1 + pav)) % m; }

  for (ll v : to[u]) {
    if (v == pa) continue;
    dfs2(v, u, uv[v]);
    add = (add * (1 + ans[v])) % m;
  }
  ans2[u] = add;
