vector< vector<int> > presum, sufsum;

void dfs_down(int u, int pa) {
  dp_down[u] = 1;
  for (auto v : g[u]) {
    if (v != pa) {
      dfs_down(v, u);
      dp_down[u] = mul(dp_down[u], dp_down[v]);
    }
  }
  add(dp_down[u], 1); // white
}

void dfs_up(int u, int pa, int id) {
  int child = g[u].size();
  presum[u] = vector<int>(child + 1, 1);
  sufsum[u] = vector<int>(child + 1, 1);
  for (int i = 0; i < child; i++) {
    presum[u][i + 1] = mul(presum[u][i], (g[u][i] == pa) ? 1 : dp_down[g[u][i]]);
    sufsum[u][i + 1] = mul(sufsum[u][i], (g[u][child - i - 1] == pa) ? 1 : dp_down[g[u][child - i - 1]]);
  }

  if (pa == -1) {
    dp_up[u] = 1;
  } else {
    dp_up[u] = dp_up[pa];
    dp_up[u] = mul(dp_up[u], presum[pa][id]);
    dp_up[u] = mul(dp_up[u], sufsum[pa][g[pa].size() - id - 1]);
    add(dp_up[u], 1);
  }

  for (int i = 0; i < child; i++) {
    int v = g[u][i];
    if (v != pa) {
      dfs_up(v, u, i);
    }
  }
}

