        {
            DFS(v, u);
            mul(dp_down[u], dp_down[v] + 1);
            pre[u].eb(dp_down[u]);
        }
    }
    ll tmp = 1;
    ford(k, adj[u].size())
    {
        int v = adj[u][k];
        if (v != p)
        {
            mul(tmp, dp_down[v] + 1);
            suf[u].eb(tmp);
        }
    }
    reverse(all(suf[u]));
}

void recal(int u, int p)
{
    for0(k, adj[u].size())
    {
        int v = adj[u][k];
        if (v != p)
        {
            dp_up[v] = dp_up[u];
            if (k > 0)
            {
                mul(dp_up[v], pre[u][k - 1]);
            }
            if (k < (int)adj[u].size() - 1)
            {
                mul(dp_up[v], suf[u][k + 1]);
            }
            dp_up[v] = (dp_up[v] + 1) % mod;
            recal(v, u);
        }
    }
}

int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> mod;
    for1(i, n - 1)
    {
        int u, v;
        cin >> u >> v;
        adj[u].eb(v);
        adj[v].eb(u);
    }
    DFS(1, 0);
    dp_up[1] = 1;
    recal(1, 0);
    for1(i, n)
    {
        cout << (dp_down[i] * dp_up[i]) % mod << '\n';
    }
    return 0;
}

