void go(ll x,ll par){
    dp[x] = 1;
    for(int i=0; i<v[x].size(); i++){
        if(v[x][i] != par){
            go(v[x][i] , x);
            dp[x] *= dp[v[x][i]] + 1;
            dp[x] %= m;
        }
    }
    ll namr = 1;
    for(int i=0; i<v[x].size(); i++){
        if(v[x][i] != par){
            namr *= dp[v[x][i]] + 1;
            namr %= m;
            pre[x].pb(namr);
        }
    }
    namr = 1;
    for(int i=(int)v[x].size() - 1; i>=0; i--){
        if(v[x][i] != par){
            namr *= dp[v[x][i]] + 1;
            namr %= m;
            suf[x].pb(namr);
        }
    }
    reverse(suf[x].begin(),suf[x].end());
}

void solve(ll x,ll par,ll cur){
    ans[x] = (cur + 1) * dp[x];
    ans[x] %= m;
    int t = 0;
    for(int i=0; i<v[x].size(); i++){
        if(v[x][i] == par)t++;
         if(v[x][i] != par){
            ll gas = 1;
            if(i - t)gas *= pre[x][i - 1 - t];
            if(i < (int)v[x].size() - 1 - 1 + (x == 1))gas *= suf[x][i + 1 - !t];
            gas %= m;
            solve(v[x][i],x,((gas * cur) % m + gas) % m);
         }
    }
}
