	vector<vector<int>> g(n);
	inc(i, n - 1) {
		IN(int, a, b);
		a--; b--;
		g[a].PB(b);
		g[b].PB(a);
	}
	vector<DMI> C(n), P(n + 1, 1), ans(n);
	function<void(int, int, int)> dfs = [&](int v, int p, int f) {
		if(f == 0) {
			DMI x = 1;
			RF(e, g[v]) {
				if(e == p) { continue; }
				dfs(e, v, f);
				x *= C[e];
			}
			C[v] = x + 1;
		} else {
			int d = SI(g[v]);
			vector<DMI> L(d + 1, 1), R(d + 1, 1);
			inc(i, d) {
				int e = g[v][i];
				L[i + 1] = R[i] = (e == p ? P[v] : C[e]);
			}
			inc(i, d) { L[i + 1] *= L[i]; }
			dec(i, d) { R[i] *= R[i + 1]; }
			inc(i, d) {
