				if(e == p) { continue; }
				P[e] = L[i] * R[i + 1] + 1;
			}
			assert(L.BA == R.FR);
			ans[v] = L.BA;

			RF(e, g[v]) {
				if(e == p) { continue; }
				dfs(e, v, f);
			}
		}
	};
