void solve() {
    //const i64 mod = 1'000'000'007;
    i64 N,M;
    cin >> N >> M;

    vector<vector<i64>> tree(N);
    rep(i,0,N-1){
        i64 x,y;
        cin >> x >> y;
        --x;
        --y;
        tree[x].emplace_back(y);
        tree[y].emplace_back(x);
    }

    const i64 maxn=100000;

    static i64 memo1[maxn];
    fill_n((i64*)memo1,maxn,0);

    function<i64(i64,i64)> rec1=[&](i64 u,i64 p){
        auto& res=memo1[u];
        res=1;
        for(auto v:tree[u]){
            if(v==p) continue;
            res*=(rec1(v,u)+1)%M;
            res%=M;
        }
        return res;
    };

    rec1(0,-1);

    static i64 memo2[maxn];
    fill_n((i64*)memo2,maxn,0);

    function<void(i64,i64,i64)> rec2=[&](i64 u,i64 p,i64 up){
        memo2[u]=(1+up)%M*memo1[u]%M;

        vector<i64> l(tree[u].size()),r(tree[u].size());
        rep(i,0,tree[u].size()){
            i64 v=tree[u][i];
            if(i==0) l[0]=(v==p)?(up+1)%M:((1+memo1[v])%M);
            else l[i]=((v==p)?(up+1)%M:((1+memo1[v])%M))*l[i-1]%M;
        }
        for(i64 i=int(tree[u].size())-1; i>=0; --i){
            i64 v=tree[u][i];
            if(i==int(tree[u].size())-1) r[int(tree[u].size())-1]=(v==p)?(up+1)%M:((1+memo1[v])%M);
            else r[i]=((v==p)?(up+1)%M:((1+memo1[v])%M))*r[i+1]%M;
        }

        rep(i,0,tree[u].size()){
            i64 v=tree[u][i];
            if(v==p) continue;

            i64 tmp=1;
            if(i-1>=0){
                tmp*=l[i-1];
                tmp%=M;
            }
            if(i+1<tree[u].size()){
                tmp*=r[i+1];
                tmp%=M;
            }

            rec2(v,u,tmp);
        }
    };

    rec2(0,-1,0);

    rep(i,0,N) cout << memo2[i] << endl;
}

