	const Mint ZERO = Mint(0, m);
	const Mint ONE = Mint(1, m);

	vector<vector<int>> g(n + 1);
	for (int i = 0; i < n - 1; i++) {
		int u,v; R(u,v);
		g[u].pb(v);
		g[v].pb(u);
	}

