	function<void(int, int)> dfs1 = [&](int u, int p) {
		dp[u] = 1;
		for (auto& v : g[u]) {
			if (v != p) {
				dfs1(v, u);
				dp[u] *= (dp[v] + 1);
			}
		}
	};

	dfs1(1, -1);

	vector<Mint> ans(n + 1, ZERO);
	function<void(int, int, Mint)> dfs2 = [&](int u, int p, Mint val) {
		ans[u] = dp[u];

		vector<int> child = { -1 };
		for (auto& v : g[u]) {
			if (v == p) continue;
			child.pb(v);
		}
		int l = child.size() - 1;

		vector<Mint> ps, ss;
		ps.pb(ONE);
		ss.pb(ONE);
		for (int i = 1; i <= l; i++) {
			ps.pb(dp[child[i]] + 1);
			ss.pb(dp[child[i]] + 1);
		}
		ps.pb(ONE);
		ss.pb(ONE);

		for (int i = 1; i <= l + 1; i++)
			ps[i] *= ps[i - 1];
		for (int i = l; i >= 0; i--)
			ss[i] *= ss[i + 1];

		for (int i = 1; i <= l; i++) {
			int v = child[i];
			Mint newDpu = ps[i - 1] * ss[i + 1] * val;
			Mint newDpv = dp[v] * (newDpu + 1);

			swap(dp[u], newDpu);
			swap(dp[v], newDpv);

			dfs2(v, u, dp[u] + 1);

			swap(dp[u], newDpu);
			swap(dp[v], newDpv);
		}
	};

	dfs2(1, -1, ONE);
	for (int i = 1; i <= n; i++)
		W(ans[i]);

	return 0;
}

