void mul(ll &x,ll y){x=x*y%MOD;}
void dfs(int x,int fa){
    if(sz(g[x])==1&&g[x][0]==fa){
        pro[x]=1;
        return ;
    }
    ll res=1;
    for(auto it:g[x]){
        if(it==fa)continue;
        dfs(it,x);
        mul(res,pro[it]+1);
    }
    int rk=1,Pre=1,Last=1;
    pre[x].pb(1);
    last[x].pb(1);
    for(auto it:g[x]){
        if(it==fa)continue;
        Pre=1LL*Pre*(pro[it]+1)%MOD;
        pre[x].pb(Pre);
        mp[it]=rk++;
    }
    for(int i=0;i<sz(g[x]);i++){
        int to=g[x][i];
        if(to==fa)continue;
        Last=1LL*Last*(pro[to]+1)%MOD;
        last[x].pb(Last);
    }
    pro[x]=res;
}

void dfs2(int x,int fa){
    if(x==1){
        dp[x]=pro[x];
    }else{
        ll res=1LL*pre[fa][mp[x]-1]*last[fa][sz(g[fa])-mp[x]]%MOD;
        dp[x]=(pro[x]+res*pro[x]%MOD)%MOD;
    }
    for(auto it:g[x]){
        if(it==fa)continue;
        dfs2(it,x);
    }
}

