int M ;
int solve(int v,int p=-1){
	if(dp[v]!=-1)return dp[v];

	if(adj[v].size()==1 && p!=-1)return dp[v] = 2;

	int op1 = 1;
	int op2 = 1;
	for(int i=0;i<adj[v].size();i++){
		int to = adj[v][i];
		if(to==p)continue;
		pai[to] = v; 
		op2 = (op2*solve(to,v))%M;
	}
	return dp[v] = (op1 + op2)%M;
}

