void crivo(){
	for(int i=2;i<MAXN;i++){
		if(!mark[i]){
			for(int j=i;j<MAXN;j+=i){
				if(!mn[j])mn[j] = i;
				mark[j] = true; 
			}
		}
	}
}


int sla(int m){
	int x = m;
	phi = m;
	while(x>1){
			int p = -1;
		if(x>=MAXN){
			for(int i=2;i*i<=x;i++){
				if(x%i==0){
					p = i;
					break;
				}
			}
			if(p==-1) p =x;

		}else{
			p = mn[x];
		}
			phi/=p;
			phi*=(p-1);
			while(x%p==0)x/=p;
		}
	return phi;
}

