void dfs1(int u, int p)
{
	par->at(u) = p;
	es->at(u)->erase(find(es->at(u)->begin(), es->at(u)->end(), p));
	for (auto v : *(es->at(u))) dfs1(v, u);
}
ll dfs2(int u)
{
	dp0->at(u) = 1L;
	for (auto v : *(es->at(u))) dp0->at(u) = dp0->at(u) * (dfs2(v) + 1) % Mod;
	return dp0->at(u);
}
void dfs3(int u)
{
	auto W = es->at(u)->size();
	auto x = new vector<ll>(W + 1, 1); // x[i] = t[0]*...*t[i-1], x[i+1]=x[i]*t[i]
	auto y = new vector<ll>(W + 1, 1); // y[i] = t[i]*...*t[W-1], y[i]=y[i+1]*t[i]
	for (int i = 0; i < W; i++) x->at(i + 1) = x->at(i) * (dp0->at(es->at(u)->at(i)) + 1) % Mod;
	for (int i = W - 1; i >= 0; i--) y->at(i) = y->at(i + 1) * (dp0->at(es->at(u)->at(i)) + 1) % Mod;
	for (int i = 0; i < W; i++) dp1->at(es->at(u)->at(i)) = (dp1->at(u) + 1) * x->at(i) % Mod * y->at(i + 1) % Mod;
	for (int v : *(es->at(u))) dfs3(v);
}

