#include <bits/stdc++.h>
using namespace std;
using ll = long long int;

const int N = 1e5+9;
const ll INF = 1LL<<60;
struct vertex { vector<int> edge; };
ll n, m;
vertex g[N];
map<int, ll> dp[N];

ll mod(ll a) {
    a %= m;
    return (a < 0) ? a + m : a;
}

void modmul(ll &a, ll b) {
    a = mod( mod(a) * mod(b) );
}

ll out(int node, int from) {
    ll res = 1;
    for(auto to : g[node].edge) {
        if(to == from)  continue;
        if(dp[node][to] == INF)  dp[node][to] = out(to, node);
        modmul(res, dp[node][to] + 1);
    }
    return res;
}

void in(int node) {
    vector<ll> parents;
    for(auto from : g[node].edge)  parents.push_back(dp[node][from] + 1);

    vector<ll> left{1}, right{1};

    for(int i = 0, sz = parents.size(); i < sz; i++) {
        left.push_back( left.back() * parents[i] % m );
        right.push_back( right.back() * parents[sz-1-i] % m );
    }
    right.pop_back();  reverse(begin(right), end(right));

    int i = 0;
    for(auto from : g[node].edge) {
        if(dp[from][node] != INF)  continue;
        dp[from][node] = left[i] * right[i] % m;
        i++;
        in(from);
    }
}


int main() {
    cin >> n >> m;
    for(int i = 0; i < n-1; i++) {
        int x, y;  cin >> x >> y;
        x--; y--;
        g[x].edge.push_back(y);
        g[y].edge.push_back(x);
        dp[x][y] = dp[y][x] = INF;
    }

    out(0, -1);
    in(0);
    for(int i = 0; i < n; i++) {
        ll ans = 1;
        for(auto e : dp[i])  modmul(ans, e.second + 1);
        cout << ans << endl;
    }
}

