long long mod;

template<typename T>
struct rerooting {
	struct rr_edge {
		long long from;
		long long to;
		long long weight;
		T dp;
		long long reverse_idx;
	};

	long long n;
	std::vector<std::vector<rr_edge>> adj_list;
	std::vector<std::vector<T>> left_sum;
	std::vector<std::vector<T>> right_sum;
	std::vector<T> dp;
	T id_e = 1;

	rerooting(long long n) : n(n) {
		adj_list.resize(n);
		left_sum.resize(n);
		right_sum.resize(n);
		dp.resize(n, id_e);
	}

	void make_egde(long long s, long long t, long long w) {
		adj_list[s].push_back({s, t, w, id_e, (long long)adj_list[t].size()});
		adj_list[t].push_back({t, s, w, id_e, (long long)adj_list[s].size() - 1});
	}

	void calculate() {
		dfs1(-1, 0, -1);
		dfs2(-1, 0, -1);
	}

	T f(T t, long long prev, long long idx) {
		if (prev == -1) return t;
		else return (t + 1) % mod;
	}

	T merge(T a, T b) {
		return a * b % mod;
	}

	void make_sum(long long now) {
		long long m = adj_list[now].size();
		left_sum[now].resize(m + 1, id_e);
		right_sum[now].resize(m + 1, id_e);
		for (long long i = 0; i < m; i++) {
			left_sum[now][i + 1] = merge(left_sum[now][i], adj_list[now][i].dp);
		}
		for (long long i = m - 1; i >= 0; i--) {
			right_sum[now][i] = merge(right_sum[now][i + 1], adj_list[now][i].dp);
		}
	}

	void dfs1(long long prev, long long now, long long idx) {
		long long ans = id_e;
		for (long long i = 0; i < adj_list[now].size(); i++) {
			if (adj_list[now][i].to == prev) continue;
			dfs1(now, adj_list[now][i].to, i);
			ans = merge(ans, adj_list[now][i].dp);
		}
		if (now == 0) {
			make_sum(0);
			dp[0] = f(ans, prev, idx);
		} else adj_list[prev][idx].dp = f(ans, prev, idx);
	}

	void dfs2(long long prev, long long now, long long idx) {
		if (now > 0) {
			adj_list[now][adj_list[prev][idx].reverse_idx].dp = f(
				merge(
					left_sum[prev][idx],
					right_sum[prev][idx + 1]
				),
				now,
				adj_list[prev][idx].reverse_idx
			);
			make_sum(now);
			dp[now] = f(left_sum[now].back(), -1, -1);
		}
		for (long long i = 0; i < adj_list[now].size(); i++) {
			if (adj_list[now][i].to == prev) continue;
			dfs2(now, adj_list[now][i].to, i);
		}
	}
};

int main() {
	long long n;
	std::cin >> n >> mod;
	rerooting<long long> rr(n);
	for (long long i = 0; i < n - 1; i++) {
		long long s, t;
		std::cin >> s >> t;
		s--; t--;
		rr.make_egde(s, t, 1);
	}

	rr.calculate();
	for (auto i : rr.dp) std::cout << i << std::endl;
}

