vvll in_Graph(ll nodeNum, ll edgeNum, bool isDirected){
	vvll to(nodeNum);
	REP(i, edgeNum){
		ll v, u;
		cin >> v >> u;
		v--; u--;
		to[v].push_back(u);
		if (!isDirected) to[u].push_back(v);
	}
	return std::move(to);
}

ll N, M;
vvll to;
vmll dp;
vmll ans;

mll dfs(ll v, ll p){
	EACH(u, to[v]){
		if (u == p) continue;

		dp[v] *= dfs(u, v) + 1;
	}
	return dp[v];
}

void dfsR(ll v, ll p, mll dpp){
	ll n = (ll)to[v].size();

	if (n == 0){
		ans[v] = dpp+1;
		return;
	}

	vmll  leftCum(n+1);
	vmll rightCum(n);

	leftCum[0] = 1;
	REPS(i, 0, n-1){
		ll u = to[v][i];
		mll val = (u==p) ? dpp : dp[u];
		leftCum[i+1] = leftCum[i] * (val+1);
	}
	rightCum[n-1] = 1;
	DEPS(i, 1, n-1){
		ll u = to[v][i];
		mll val = (u==p) ? dpp : dp[u];
		rightCum[i-1] = rightCum[i] * (val+1);
	}

	ans[v] = leftCum[n];

	REP(i, n){
		ll u = to[v][i];
		if (u == p) continue;
		mll dpc = leftCum[i]*rightCum[i];
		dfsR(u, v, dpc);
	}
}

void solve()
{
	cin >> N >> M;
	to = in_Graph(N, N-1, false);
	mll::MOD = M;

	if (N == 1) bye(1);

	dp.resize(N, 1);
	dfs(0, -1);

	ans.resize(N);
	dfsR(0, -1, 1);

	coutv(ans, '\n');
}


int main(){
	solve();
	return 0;
}

