template<class T>
class Rerooting{
    int n;
    T def;
    function<T(T,T)> merge;
    function<T(T)> addroot;
    vector<vector<Edge>> g;
    vector<vector<T>> dp;
    public:
    vector<T> ans;
    Rerooting(int _n,T _def,function<T(T,T)> _merge,function<T(T)> _addroot)
    :n(_n),def(_def),merge(_merge),addroot(_addroot)
    {
        g=vector<vector<Edge>>(n);
        dp=vector<vector<T>>(n);
        ans=vector<T>(n,def);
    }
    void add_edge(int a,Edge e){
        g[a].pb(e);
    }

    T dfs(int v,int par=-1){
        T ret=def;
        dp[v].resize(g[v].size());
        rep(i,g[v].size()){
            if(g[v][i].to==par){
              continue;
            }
            dp[v][i]=dfs(g[v][i].to,v);
            ret=merge(ret,dp[v][i])%mod;
        }
        return addroot(ret);
    }

    void bfs(int v,T val,int par=-1){
        int deg=g[v].size();
        rep(i,deg){
            if(g[v][i].to==par)dp[v][i]=val;
        }
        vector<T> dpl(deg+1,def),dpr(deg+1,def);
        rep(i,deg)dpl[i+1]=merge(dpl[i],dp[v][i])%mod;
        per(i,deg)dpr[i]=merge(dpr[i+1],dp[v][i])%mod;
        ans[v]=dpl[deg];
        rep(i,deg){
            int nv=g[v][i].to;
            if(nv==par)continue;
            bfs(nv,addroot(dpl[i]*dpr[i+1]%mod),v);
        }
    }
};


