				valor += (dfs(pos, 1, viz, true) % mod);
			}
			else if(cor == 0 && preto == true)
			{
				valor += (dfs(pos, 0, viz, true) % mod);
			}
			else if(cor == 1) // put color = black
			{
				valor += (dfs(pos, 0, viz, true) % mod);
				valor += (dfs(pos, 1, viz, true) % mod);
			}

			//tem q multiplicar os resultados
			if(dp[pos][cor] == 0)	
				dp[pos][cor] = valor;
			else
				dp[pos][cor] = (dp[pos][cor] * valor) % mod;
		}

	}


	//se é folha
	if(dp[pos][cor] == 0)
		return dp[pos][cor] = 1;

	return dp[pos][cor];

}





