void update(int x, int y, int A) {
	D[x][y][A] = (D[x][y][A * 2] * D[x][y][A * 2 + 1]) % M;
	if (A != 1) update(x, y, A / 2);
}

void add(int x, int y, int A, int B) {
	int C = A + KM[x];
	D[x][y][C] = B;
	update(x, y, C / 2);
}

ll check(int x, int y, int L, int R, int A, int l, int r) {
	if (L <= l && r <= R) return D[x][y][A];
	if (r <= L || R <= l) return 1;
	return (check(x, y, L, R, A * 2, l, (l + r) / 2) * check(x, y, L, R, A * 2 + 1, (l + r) / 2, r)) % M;
}

ll query(int x, int y, int L, int R) {
	return check(x, y, L, R, 1, 0, KM[x]);
}

pair<ll, ll> dfs(int A, int B) {
	if (dp[A][B] != mp(0ll, 0ll)) return dp[A][B];

	if (B == 0) {
		for (int i = 0; i < V[A].size(); i++) {
			auto P = dfs(V[A][i], A);
			add(A, 0, i, (P.first + P.second) % M);
			add(A, 1, i, P.second % M);
		}
		C[A] = 1;
		return mp(query(A, 0, 0, V[A].size() + 1), query(A, 1, 0, V[A].size() + 1));
	}
	//else if (C[A]) {
	//	int kari = BB[A][B];
	//	ll kuro = query(A, 0, 0, kari) * query(A, 0, kari + 1, V[A].size() + 1) % M;
	//	ll siro = query(A, 1, 0, kari) * query(A, 1, kari + 1, V[A].size() + 1) % M;
	//	dp[A][B] = mp(kuro, siro);
	//	return mp(kuro, siro);
	//}
	else {
		ll kuro = 1;
		ll siro = 1;
		for (int i = 0; i < V[A].size(); i++) {
			if (V[A][i] == B) continue;
			auto P = dfs(V[A][i], A);
			kuro = kuro * (P.first + P.second) % M;
			siro = siro * P.second % M;
		}
		dp[A][B] = mp(kuro, siro);
		return mp(kuro, siro);
	}
}


