void dfs1(ll hd, ll pr, ll m){
	mult[hd].pb(1);
	fw[hd].pb(1);
	for(auto hr : g[hd]){
		if(hr == pr)
			continue;
		dfs1(hr, hd, m);
		ll ans = fw[hr][fw[hr].size()-1] + 1;
		ans = ans % m;
		mult[hd].pb(ans);
		fw[hd].pb(fw[hd][fw[hd].size()-1] * ans % m);
	}
}

void dfs2(ll hd, ll pr, ll m){
	mult[hd].pb(1);
	fw[hd].pb(fw[hd][fw[hd].size()-1]);
	{
		ll n = fw[hd].size();	
		bc[hd].resize(n);
		bc[hd][n-1] = 1;
		for(ll i = n-2; i>-1; i--)
			bc[hd][i] = bc[hd][i+1] * mult[hd][i] % m;
	}
	fori(g[hd].size()){
		auto hr = g[hd][i];
		if(hr == pr)
			continue;
		ll index = i+1;
		ll some_add_1 = fw[hd][index-1] * bc[hd][index+1] % m ;
		some_add_1 = (some_add_1 + 1) % m;
		mult[hr].pb(some_add_1);
		fw[hr].pb(fw[hr][fw[hr].size()-1] * some_add_1 % m);
		dfs2(hr, hd, m);
	}
}

