using namespace std;

const int mN = 1e5+5;
int n, mod;
vector<int> graph[mN];

typedef long long LL;
LL cnt[mN];
LL ans[mN];

int parent[mN];
void dfs(int u) {
    cnt[u] = 1;
    for (int v : graph[u]) if (parent[u] != v) {
        parent[v] = u;
        dfs(v);
        cnt[u] *= cnt[v] + 1;
        cnt[u] %= mod;
    }
    ans[u] = cnt[u];
}

LL gcd(LL a, LL b, LL &x, LL &y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    LL g, x1, y1;
    g = gcd(b, a%b, x1, y1);
    x = y1;
    y = x1 - y1*(a/b);
    return g;
}

LL modular_inverse(LL a, LL mod) {
    LL g,x,y;
    g = gcd(a,mod, x,y);
    if (g != 1) return 0;
    x %= mod;
    if (x<0) x += mod;
    return x;
}

void reconsider(int u) {
    for (int v : graph[u]) if (parent[u] != v) {
        parent[v] = u;
        LL u_as_child = ans[u];
        LL x,y, g = gcd(u_as_child, cnt[v]+1, x, y);
        u_as_child /= g;
        u_as_child *= modular_inverse((cnt[v]+1)/g, mod);
        u_as_child %= mod;
        cnt[v] *= u_as_child + 1;
        cnt[v] %= mod;
        ans[v] = cnt[v];
//        if (u == 1 and v == 2) cerr << ans[v] << "\n";
//        if (u == 2 and v == 3) cerr << ans[v] << "\n";
        reconsider(v);
    }
//    cerr << u << " : " << ans[u] << "\n";
}

