using namespace utils;
vector<map<int, ll>> dpf, dpb;

vector<set<int>> edge;
ll N, M;

ll dfs(ll v, ll p = -1){
    ll ans = 1;
    map<int, ll> s;
    for (auto &&u : edge[v]) {
        if(u == p) continue;
        auto t =  (dfs(u, v) + 1);
        s[u] = t;
        ans *= t;
        ans %= M;
    } // end u
    ll f = 1;
    for (auto &&u : s) {
        dpf[v][u.first] = f;
        f *= u.second;
        f %= M;
    } // end u
    ll b = 1;
    for(auto u = s.rbegin(); u != s.rend(); u++){
        dpb[v][u->first] =  b;
        b *= u->second;
        b %= M;
    }
    dpb[v][-1] = ans;

    return ans;
}

void sub_main(istream &is) {
    is >> N >> M;
    if(!is) return;
    edge.clear();
    edge.resize(N);
    for (int i = 0; i < N - 1; ++i) {
        int x, y;
        is >> x >> y;
        x--; y--;
        edge[x].insert(y);
        edge[y].insert(x);
    } // end i
    dpf.clear(); dpb.clear();
    dpf.resize(N); dpb.resize(N);
    vector<ll> ans(N);
    vector<ll> check(N, 1);
    ans[0] = dfs(0);

    queue<int> bfq;
    for (auto &&u : edge[0]) { bfq.push(u); } // end u
    while(!bfq.empty()){
        int v = bfq.front(); bfq.pop();
        ll a = 1;
        for (auto &&u : edge[v]) {
            if(dpf[v].count(u) == 0){
                ll b =  (dpf[u][v] * dpb[u][v]);
                b %= M;
                b *= check[u]; b += 1;
                b%=M;
                check[v] = b;
                a *= b;
            }
            else{
                a *= dpb[u][-1] + 1;
                bfq.push(u);
            }
            a %= M;
        } // end u
        ans[v] = a;
    }

    for (int j = 0; j < N; ++j) {
        cout << ans[j] << endl;
    } // end j

}

