		if (adj[cur][i]==par)continue;
		suf[0][adj[cur][i]] = prv[0];
		suf[1][adj[cur][i]] = prv[1];
		prv[0] = mul(prv[0],down[0][adj[cur][i]]);
		prv[1] = mul(prv[1],add(down[0][adj[cur][i]],down[1][adj[cur][i]]));
	}
}
void dfs2(int cur ,int par) {
	for (int i : adj[cur]) {
		if (i==par)continue;
		up[0][i] = mul(up[0][cur],mul(pre[0][i],suf[0][i]));
		up[1][i] = add(mul(up[0][cur],mul(pre[0][i],suf[0][i])),mul(up[1][cur],mul(pre[1][i],suf[1][i])));
		dfs2(i,cur);
	}
}
void solve() {
