map<pair<int, int>, int> pat;
int recur(int a, int b)
{
    auto p = make_pair(a, b);
    auto it = pat.lower_bound(p);
    if (it != end(pat) && it->first == p) {
        return it->second;
    }
    long long value = 1;
    for (int next : graph[b]) {
        if (next == a) continue;
        value = value * recur(b, next) % M;
    }
    value = (value + 1) % M;
    pat.insert(it, make_pair(p, value));
    return value;
}
