#include "bits/stdc++.h"
using namespace std;
typedef long long ll;

int mod;

struct mint {
private:
    long long x;
public:
    mint(long long x = 0) :x(x%mod) {}
    mint(std::string s) {
        long long z = 0;
        for (int i = 0; i < s.size(); i++) {
            z *= 10;
            z += s[i] - '0';
            z %= mod;
        }
        this->x = z;
    }
    mint& operator+=(const mint a) {
        if ((x += a.x) >= mod) x -= mod;
        return *this;
    }
    mint& operator-=(const mint a) {
        if ((x += mod - a.x) >= mod) x -= mod;
        return *this;
    }
    mint& operator*=(const mint a) {
        (x *= a.x) %= mod;
        return *this;
    }
    mint operator+(const mint a) const {
        mint res(*this);
        return res += a;
    }
    mint operator-(const mint a) const {
        mint res(*this);
        return res -= a;
    }
    mint operator*(const mint a) const {
        mint res(*this);
        return res *= a;
    }
    friend std::ostream& operator<<(std::ostream& os, const mint& n) {
        return os << n.x;
    }
    bool operator==(const mint a) const {
        return this->x == a.x;
    }
};

int n;
vector<vector<int>> tree;
vector<mint> node; // iを根とする部分木でiが黒に塗られる組数
vector<mint> ans;

void dfs1(int v, int p = -1) {
    mint res = 1;
    for (int &u : tree[v]) {
        if (u == p) continue;
        dfs1(u, v);
        res *= (node[u] + 1);
    }
    node[v] = res;
}

void dfs2(int v, mint d_par, int p = -1) {
    // v における答えの計算
    ans[v] = 1;
    for (int &u : tree[v]) {
        if (u == p) {
            ans[v] *= (d_par + 1);
        }
        else {
            ans[v] *= (node[u] + 1);
        }
    }
    // 左右からの累積演算を用いて子に送る d_par の計算
    // lf[i] : [:i-1]の演算結果
    // ri[i] : [i+1:]の演算結果
    int e = 1; // 演算の単位元 ( maxの場合 -INF )
    vector<mint> lf(tree[v].size(), e), ri(tree[v].size(), e);
    for (int i = 1; i < tree[v].size(); i++) {
        if (tree[v][i - 1] == p) {
            lf[i] = lf[i - 1];
        }
        else {
            lf[i] = (node[tree[v][i - 1]] + 1) * lf[i - 1];
        }
    }
    for (int i = tree[v].size() - 2; i >= 0; i--) {
        if (tree[v][i + 1] == p) {
            ri[i] = ri[i + 1];
        }
        else {
            ri[i] = (node[tree[v][i + 1]] + 1) * ri[i + 1];
        }
    }
    for (int i = 0; i < tree[v].size(); i++) {
        if (tree[v][i] == p) continue;
        dfs2(tree[v][i], lf[i] * ri[i] * (p >= 0 ? d_par + 1 : e), v);
    }
}

int main() {
    cin >> n >> mod;
    tree.resize(n);
    node.resize(n);
    ans.resize(n);
    for (int i = 0; i < n - 1; i++) {
        int u, v; cin >> u >> v;
        u--; v--;
        tree[u].push_back(v);
        tree[v].push_back(u);
    }
    dfs1(0);
    dfs2(0, 0);
    for (int i = 0; i < n; i++) {
        cout << ans[i] << endl;
    }
    return 0;
}

