using namespace std;
const int maxn = 100100;
vector<int>g[maxn];
ll n, mod;

vector<ll>pr[maxn][2], sf[maxn][2];
ll dp[maxn][2];

vector<ll>dps[maxn][2];

ll dpresult[maxn][2];

int ind[maxn];

void dfs_zero(int node, int p) {
	dp[node][0] = dp[node][1] = 1LL;

	int x = 1;
	dps[node][0].pb(1);
	dps[node][1].pb(1);
	for(int i:g[node]) {
		if(i == p) continue;

		dfs_zero(i, node);
		ind[i] = x;

		dps[node][0].pb(dp[i][0] + dp[i][1]);
		dps[node][1].pb(dp[i][1]);

		dp[node][0] *= (dp[i][0] + dp[i][1])%mod;
		dp[node][0] %= mod;

		dp[node][1] *= dp[i][1];
		dp[node][1] %= mod;

		x++;
	}

	dps[node][0].pb(1);
	dps[node][1].pb(1);

	pr[node][0].resize(dps[node][0].size(), 1);
	sf[node][0].resize(dps[node][0].size(), 1);

	pr[node][1].resize(dps[node][1].size(), 1);
	sf[node][1].resize(dps[node][1].size(), 1);

	pr[node][0][0] = dps[node][0][0];
	pr[node][1][0] = dps[node][1][0];
	for(int i=1;i<dps[node][0].size();i++) {
		pr[node][0][i] = (pr[node][0][i-1] * dps[node][0][i])%mod;
		pr[node][1][i] = (pr[node][1][i-1] * dps[node][1][i])%mod;
	}

	sf[node][0][dps[node][0].size()-1] = dps[node][0][dps[node][0].size()-1];
	sf[node][1][dps[node][1].size()-1] = dps[node][1][dps[node][1].size()-1];
	for(int i=dps[node][0].size()-2;i>=0;i--) {
		sf[node][0][i] = (sf[node][0][i+1] * dps[node][0][i])%mod;
		sf[node][1][i] = (sf[node][1][i+1] * dps[node][1][i])%mod;
	}
}

void dfs_one(int node, int p, ll carry0=1LL, ll carry1=1LL) {
	dpresult[node][0] = dp[node][0] * carry0;
	dpresult[node][1] = dp[node][1] * carry1;

	for(int i:g[node]) {
		if(i == p) continue;

		int cr = ind[i];

		//cout<<"At index "<<cr<<" calling "<<i<<"\n";

		ll tmp0 = carry0 * (pr[node][0][cr-1] * sf[node][0][cr+1])%mod;
		ll tmp1 = carry1 * (pr[node][1][cr-1] * sf[node][1][cr+1])%mod;
		tmp0 = (tmp0+1)%mod;
		tmp1 %= mod;

		dfs_one(i, node, tmp0, tmp1);
	}
}

