	ll a, b;
	for(int i=0;i<n-1;i++) {
		cin>>a>>b;
		g[a].pb(b);
		g[b].pb(a);
	}

	dfs_zero(1, -1);
	dfs_one(1, -1);

	for(int i=1;i<=n;i++) {
		cout<<dpresult[i][0]<<"\n";
	}
}

