int dp[NMAX];
vector <int> adia[NMAX];
int ans[NMAX];

void dfs(int nod, int tata)
{
    dp[nod] = 1;
    for (auto i : adia[nod]) {
        if (i == tata)
            continue;
        dfs(i, nod);
        dp[nod] = 1LL * dp[nod] * (dp[i] + 1) % m;
    }
}

void dfsup(int nod, int tata, int modstata)
{
    if (tata)
        adia[nod].erase(find(adia[nod].begin(), adia[nod].end(), tata));

    ans[nod] = 1LL * dp[nod] * modstata % m;

    vector <int> vl(adia[nod].size()), vr(adia[nod].size());

    for (int i = 0; i < vl.size(); i++) {
        vl[i] = dp[adia[nod][i]] + 1;
        vr[i] = dp[adia[nod][i]] + 1;

        if (i)
            vl[i] = 1LL * vl[i] * vl[i - 1] % m;
    }

    for (int i = (int)vr.size() - 2; i >= 0; i--)
        vr[i] = 1LL * vr[i] * vr[i + 1] % m;

    for (int i = 0; i < adia[nod].size(); i++) {
        int oth = 1;
        if (i)
            oth = 1LL * oth * vl[i - 1] % m;
        if (i + 1 < vr.size())
            oth = 1LL * oth * vr[i + 1] % m;

        oth = 1LL * oth * modstata % m;

        dfsup(adia[nod][i], nod, (oth + 1) % m);
    }
}

