#include <bits/stdc++.h>

typedef long long ll;
const ll MOD = 1000000007;
ll mod;

using namespace std;

vector<vector<int> > t(100005);
vector<int> a(100005, -1), dp(100005, -1);

// C function for extended Euclidean Algorithm
int gcdExtended(ll a, int b, int *x, int *y) {
    // Base Case
    if (a == 0) {
        *x = 0, *y = 1;
        return b;
    }

    int x1, y1;  // To store results of recursive call
    int gcd = gcdExtended(b % a, a, &x1, &y1);

    // Update x and y using results of recursive
    // call
    *x = y1 - (b / a) * x1;
    *y = x1;

    return gcd;
}

// Function to find modulo inverse of a
int modInverse(ll a, int m) {
    int x, y;
    int g = gcdExtended(a, m, &x, &y);
    if (g != 1)
        return -1;
    else {
        // m is added to handle negative x
        int res = (x % m + m) % m;
        return res;
    }
}

int dfs(int node, int p = -1) {
    if (dp[node] != -1) return dp[node];
    ll ans = 1;
    for (auto c : t[node]) {
        if (c == p) continue;
        ans = (ans * (1LL + dfs(c, node))) % mod;
    }
    dp[node] = ans;
    return (int)ans;
}

void reroot(int node, int p = -1) {
    if (p != -1) {
        // calculate the new answer for p
        int mi = modInverse(dp[node] + 1LL, mod);
        dp[p] = (dp[p] * (ll)mi) % mod;
    }
    // find the answer assuming node is root
    ll ans = 1;
    for (auto c : t[node]) {
        ans = (ans * (1LL + dp[c])) % mod;
    }
    dp[node] = a[node] = ans;
    // make every child except p the new root
    for (auto c : t[node]) {
        if (c == p) continue;
        ll tmp1 = dp[node];
        ll tmp2 = dp[c];
        reroot(c, node);
        dp[node] = tmp1;
        dp[c] = tmp2;
    }
    return;
}

