        cin >> u >> v;
        u--, v--;
        t[u].push_back(v);
        t[v].push_back(u);
    }

    a[0] = dfs(0);

    reroot(0);

    for (int i = 0; i < n; i++) {
        cout << a[i] << endl;
    }

    return 0;
}

