using namespace std;
const int maxn = 200100;
vector<int>g[maxn];
ll n, mod, dp[maxn];

void firstdfs(int node, int p) {
    dp[node] = 1LL;
    for(int i:g[node]) {
        if(i != p) {
            firstdfs(i, node);
            dp[node] *= (dp[i] + 1) % mod;
            dp[node] %= mod;
        }
    }
}

void seconddfs(int node, int p, ll carry = 0LL) {
    vector<ll>pref(g[node].size()+3), suff(g[node].size()+3);
    vector<ll>dps;
    vector<int>v;
    for(int i:g[node]) {
        if(i != p) {
            dps.pb(dp[i]);
            v.pb(i);
        }
    }

    dp[node] *= (carry + 1LL)%mod;
    dp[node] %= mod;


    if(v.size() == 0) return;

    pref[0] = 1LL;
    for(int i=0;i<dps.size();i++) {
        if(i > 0) pref[i] = pref[i-1];
        pref[i] *= (dps[i] + 1)%mod;
        pref[i] %= mod;
    }
    suff[dps.size()-1] = 1LL;
    suff[dps.size()] = 1LL;
    for(int i=dps.size()-1;i>=0;i--) {
        if(i < dps.size()-1) suff[i] = suff[i+1];
        suff[i] *= (dps[i] + 1)%mod;
        suff[i] %= mod;
    }

    if(node == 1) carry = 1LL;

    for(int i=0;i<dps.size();i++) {
        ll ncarry = carry;
        if(i == 0) {
            ncarry *= suff[i+1];
            ncarry %= mod;
        }
        else {
            ncarry *= pref[i-1];
            ncarry %= mod;
            ncarry *= suff[i+1];
            ncarry %= mod;
        }
        seconddfs(v[i], node, ncarry);
    }
}

