int N, M;

ll mul(ll a, ll b) { return a * b % M; }

ll add(ll a, ll b) { return (a + b) % M; }

ll blackRoot(int x, int par) {
  ll rb = 1;
  for (int child : g[x]) {
    if (child != par) {
      rb = mul(rb, 1 + blackRoot(child, x));
    }
  }
  return down[x] = rb;
}

void calcUp(int x, int par) {
  int size = g[x].size();
  if (size == 0) return;
  vector<ll> suffix(size);
  suffix[size - 1] = 1;
  for (int i = size - 1; i > 0; i--) {
    int child = g[x][i];
    if (child != par) {
      suffix[i - 1] = mul(suffix[i], 1 + down[child]);
    } else {
      suffix[i - 1] = suffix[i];
    }
  }

  ll prefix = 1;
  for (int i = 0; i < size; i++) {
    int child = g[x][i];
    if (child != par) {
      up[child] = mul(mul(prefix, suffix[i]), 1 + up[x]);
      prefix = mul(prefix, 1 + down[child]);
    }
  }
  for (int child : g[x]) {
    if (child != par) {
      calcUp(child, x);
    }
  }
}

