const int cap = 1e5 + 1;
int N, x, y;
int64_t M;
vector<int> G[cap], pre[cap], suf[cap];
int P[cap];
int64_t cnt[cap], dp[cap];

void prepro(int i) {
    pre[i] = vector<int>(G[i].size() + 1, 1);
    suf[i] = vector<int>(G[i].size() + 1, 1);
    for (int k = 0; k < int(G[i].size()); ++k) {
        int j = G[i][k];
        P[j] = i;
        auto it = find(G[j].begin(), G[j].end(), i);
        G[j].erase(it);
        prepro(j);
        cnt[i] = (cnt[i] * cnt[j]) % M;
        pre[i][k + 1] = (pre[i][k] * cnt[j]) % M;
    }
    for (int k = int(G[i].size()) - 1; k >= 0; --k)
        suf[i][k] = (suf[i][k + 1] * cnt[G[i][k]]) % M;
    ++cnt[i];
}

void calc(int i, int64_t res) {
    dp[i] = ((cnt[i] - 1) * res) % M;
    for (int k = 0; k < int(G[i].size()); ++k) {
        int nxt = (((pre[i][k] * suf[i][k + 1]) % M) * res + 1) % M;
        calc(G[i][k], nxt);
    }
}

int main() {
    scanf("%d %" PRId64, &N, &M);
    for (int i = 1; i < N; ++i) {
        scanf(" %d %d", &x, &y);
        G[x].push_back(y);
        G[y].push_back(x);
    }

    fill(cnt, cnt + N + 1, 1);
    P[1] = 0;
    prepro(1);
    calc(1, 1);

    for (int i = 1; i <= N; ++i)
        printf("%" PRId64 "\n", dp[i]);
}

