int rec(int p, int i) {
    int &res = dp[p][i];
    if (res >= 0) return res;
    res = 1;
    int x = g[p][i];
    rep (j,g[x].size()) {
        int y = g[x][j];
        if (y == p) continue;
        res *= rec(x,j)+1;
        res = mod(res,m);
    }
    return res;
}

