using namespace std;

int n;

ll m;

ll phi;

ll pwr (ll a, ll b)
{
    if(b == 0)
        return 1;
    if(b & 1)
        return pwr(a, (b ^ 1)) * a % m;
    ll pw = pwr(a, (b >> 1));
    return pw * pw % m;
}

ll divm (ll a, ll b)
{
    return a * pwr(b, phi - 1) % m;
}

vector <int> edges[N_MAX];

int parent[N_MAX];

vector <int> sons[N_MAX];

bool visited[N_MAX];

void dfs (int node)
{
    visited[node] = true;
    for(int u : edges[node])
        if(visited[u] == false)
        {
            parent[u] = node;
            sons[node].push_back(u);
            dfs(u);
        }
}

ll up[N_MAX], down[N_MAX];

void computeDown (int node)
{
    down[node] = 1;
    for(int u : sons[node])
    {
        computeDown(u);
        down[node] = (down[node] * (down[u] + 1)) % m;
    }
}

void computeUp (int node)
{
    up[node] += 1;
    if(up[node] >= m)
        up[node] -= m;
    for(int u : sons[node])
    {
        up[u] = divm(down[node], down[u] + 1) * up[node] % m;
        computeUp(u);
    }
}

