    while(m1 > 1)
    {
        if(pf * pf > m1)
            pf = m1;
        if(m1 % pf == 0)
        {
            ll pfe = 1;
            while(m1 % pf == 0)
            {
                pfe *= pf;
                m1 /= pf;
            }
            pfe /= pf;
            phi *= pfe * (pf - 1);
        }
        pf++;
    }
    for(int i = 1; i < n; i++)
    {
