    for (long j : css[i]) {
      if (dp1s[j] >= 0) {
        dp = (dp * (dp1s[j] + 1)) % M;
      } else {
        stack.push_back(j);
        ok = 0;
      }
    }
    if (ok) {
      dp1s[i] = dp;
      stack.pop_back();
    }
  }
  //   for (long i = 0; i < N; i++) {
