void update(int u){
    up[u] = 1;
    int sz = g[u].size();
    for(int i=1;i<sz;i++) pref[u][i] = (pref[u][i]*pref[u][i-1])%m;
    for(int i=sz-2;i>=0;i--) suff[u][i] = (suff[u][i]*suff[u][i+1])%m;
}

void dfs_down(int u, int p){
    par[u] = p;
    pref[u].resize(g[u].size());
    suff[u].resize(g[u].size());

    dp[u][p] = 1;
    for(int i=0;i<g[u].size();i++){
        int v = g[u][i];
        idx[u][v] = i;
        if(v == p) continue;
        dfs_down(v, u);

        pref[u][i] = (dp[v][u]+1)%m;
        suff[u][i] = (dp[v][u]+1)%m;
        dp[u][p] = (dp[u][p]*(dp[v][u]+1))%m;
    }
    if(u == 1) update(1);
}

void dfs_up(int u, int p){
    if(dp[u].count(p)) return;
    if(!up[u]){
        int v = par[u];
        dfs_up(v, u);
        pref[u][idx[u][v]] = (dp[v][u]+1)%m;
        suff[u][idx[u][v]] = (dp[v][u]+1)%m;
        par[u] = 0;
        update(u);
    }

    if(p == 0) dp[u][p] = pref[u][g[u].size()-1];
    else{
        dp[u][p] = 1;
        if(idx[u][p]-1 >= 0) dp[u][p] = (dp[u][p]*pref[u][idx[u][p]-1])%m;
        if(idx[u][p]+1 < g[u].size()) dp[u][p] = (dp[u][p]*suff[u][idx[u][p]+1])%m;
    }
}

