const int N = 1e5 + 5;
int n, mod, dp[N], f[N];
vector<int> gr[N], pref[N], suff[N];

int add (int _a, int _b) {
    _a += _b;
    if (_a >= mod) _a -= mod;
    return _a;
}

int mult (int _a, int _b) { return 1LL * _a * _b % mod; }

void dfs (int u, int prv) {
    dp[u] = 1;
    for (int v : gr[u]) if (v != prv) {
        dfs(v, u);
        dp[u] = mult(dp[u], add(dp[v], 1) );
        pref[u].pb(1); suff[u].pb(1);
    }
    int i = 0;
    for (int v : gr[u]) if (v != prv) {
        if (i) pref[u][i - 1] = mult(pref[u][i - 1], add(dp[v], 1) );
        if (i + 1 < suff[u].size() ) suff[u][i + 1] = mult(suff[u][i + 1], add(dp[v], 1) );
        ++i;
    }
    for (i = 1; i < suff[u].size(); ++i) suff[u][i] = mult(suff[u][i], suff[u][i - 1]);
    for (i = (int)pref[u].size() - 2; i >= 0; --i) pref[u][i] = mult(pref[u][i], pref[u][i + 1]);
}

void dfs2 (int u, int prv) {
    int i = 0;
    for (int v : gr[u]) if (v != prv) {
        f[v] = add(1, mult(f[u], mult(pref[u][i], suff[u][i]) ) );
        ++i;
        dfs2(v, u);
    }
}

