void dfs(int i){
  dp[i] = 1;
  rep(j, edge[i].size()){
    if(par[edge[i][j]] >= 0)continue;
    par[edge[i][j]] = i;
    child[i].pb(edge[i][j]);
    dfs(edge[i][j]);
    dp[i] = (dp[i] * ((dp[edge[i][j]] + 1) % m)) % m;
  }
}

void dfs2(int i, ll p){
  dp2[i] = dp[i] * (p + 1) % m;
  vector<ll> fr(child[i].size()), ba(child[i].size());
  ll ptmp = p + 1;
  rep(j, child[i].size()){
    if(j == 0)fr[j] = (dp[child[i][j]] + 1) % m;
    else fr[j] = fr[j-1] * ((dp[child[i][j]] + 1) % m) % m;
  }
  for(int j = sz(child[i]) - 1; j >= 0; j--){
    if(j + 1 == sz(child[i]))ba[j] = (dp[child[i][j]] + 1 ) % m;
    else ba[j] = ba[j+1] * ((dp[child[i][j]] + 1) % m) % m;
  }
  rep(j, sz(child[i])){
    ll tmp = ptmp;
    if(j + 1 < sz(child[i]))tmp = tmp * ba[j+1] % m;
    if(j-1 >= 0)tmp = tmp * fr[j-1] % m;
    dfs2(child[i][j], tmp);
  }
}

