int qpow(int a, int b, int MOD) {
    return qpow(static_cast<long long>(a), static_cast<long long>(b), MOD);
}
long long qpow(long long a, long long b, int MOD) {
    assert(b >= 0);
    if (b == 0) return 1;
    long long res = 1;
    while (b) {
        if (b & 1) res = (res * a) % MOD;
        a = (a * a) % MOD;
        b >>= 1;
    }
    return res;
}
LL inv(LL a, int MOD) {
    return qpow(a, (MOD - 2) * 1LL, MOD);
}
