int mod;
const int N = 1e5 + 10;
int dp[N], ex[N];
vector<int> a[N];

void DFS(int u, int parent) {
  vector<int> child;
  dp[u] = 1;
  for (auto& v : a[u]) {
    if (v == parent) continue;
    DFS(v, u);
    child.push_back(v);
    dp[u] = (int64)dp[u] * (1 + dp[v]) % mod;
  }
  int m = child.size();
  if (m) {
    vector<int> L(m), R(m);
    L[0] = dp[child[0]] + 1;
    for (int i = 1; i < m; ++i) {
      L[i] = (int64)L[i - 1] * (dp[child[i]] + 1) % mod;
    }
    R[m - 1] = dp[child[m - 1]] + 1;
    for (int i = m - 2; i >= 0; --i) {
      R[i] = (int64)R[i + 1] * (dp[child[i]] + 1) % mod;
    }
    for (int i = 0; i < m; ++i) {
      int64 cur = 1;
      if (i - 1 >= 0) cur = cur * L[i - 1] % mod;
      if (i + 1 < m) cur = cur * R[i + 1] % mod;
      ex[child[i]] = cur;
    }
  }
}

int ret[N];
void DFS2(int u, int parent, int prod) {
  ret[u] = (int64)dp[u] * prod % mod;
  for (auto& v : a[u]) {
    if (v == parent) continue;
    DFS2(v, u, ((int64)prod * ex[v] + 1) % mod);
  }
}

