#include <bits/stdc++.h>

using namespace std;

typedef long long ll;

int N, M;
vector<int> parent, down, up;
vector<vector<int>> adj;
vector<vector<ll>> prefix, suffix;

void dfs_parent(int v, int u) {
    parent[v] = u;
    for (int w : adj[v])
        if (w != u)
            dfs_parent(w, v);
}

ll dfs_down(int v) {
    down[v] = 1;
    for (int w : adj[v])
        down[v] = down[v] * (1 + dfs_down(w)) % M;
    return down[v];
}

void bfs_up() {
    queue<int> q;
    q.push(0);
    while (!q.empty()) {
        int v = q.front();
        q.pop();
        up[v] = (up[v] + 1) % M;
        int n = adj[v].size();
        for (int i = 0; i < n; i++) {
            int w = adj[v][i];
            up[w] = up[v];
            up[w] = up[w] * prefix[v][i] % M;
            up[w] = up[w] * suffix[v][i + 1] % M;
            q.push(w);
        }
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> N >> M;

    adj.resize(N);
    for (int i = 0; i < N - 1; i++) {
        int v, w;
        cin >> v >> w;
        v--, w--;
        adj[v].push_back(w);
        adj[w].push_back(v);
    }

    parent.resize(N);
    dfs_parent(0, 0);

    adj.assign(N, vector<int>());
    for (int v = 1; v < N; v++)
        adj[parent[v]].push_back(v);

    down.resize(N);
    dfs_down(0);

    prefix.resize(N);
    suffix.resize(N);
    for (int v = 0; v < N; v++) {
        int n = adj[v].size();
        prefix[v].assign(n + 1, 1);
        suffix[v].assign(n + 1, 1);
        for (int i = 0; i < n; i++)
            prefix[v][i + 1] = prefix[v][i] * (1 + down[adj[v][i]]) % M;
        for (int i = n; i > 0; i--)
            suffix[v][i - 1] = suffix[v][i] * (1 + down[adj[v][i - 1]]) % M;
    }

    up.resize(N);
    bfs_up();
    for (int v = 0; v < N; v++)
        cout << up[v] * down[v] % M << endl;
}

