typedef long long ll;
typedef pair<int,int> P;
#define MOD 1000000007 
#define INF 987654321 

int n;
ll m;
vector<int> adj[100001];
map<P,ll> val;

ll solve(P edge){
	ll ret=val[edge];
	if(ret!=0) return ret;
	ret=1;
	int u=edge.first;
	int pu=edge.second;
	for(int next:adj[u]){
		if(next!=pu){
			ret=(ret*(1+solve(P(next,u))))%m;
		}
	}
	val[edge]=ret;
	return ret;
}

