int dfs0(const int u, const int p)
{
    size[u] = 1;
    FOR_ALL(v,G1[u]) if (p != *v) {
        size[u] += dfs0(*v,u);
        G2[u].push_back(*v);
        parent[*v] = u;
    }
    return size[u];
