int dfs2(const int u, const int i);

int dfs1(const int u)
{
    if (size[u] == 1)
        return 1;
    int& ans = dp1[u];
    if (-1 == ans)
        ans = dfs2(u,0);
    return ans;
}

int dfs2(const int u, const int i)
{
    const int n = G2[u].size();
    if (i == n)
        return 1;
    const int v = G2[u][i];
    VI& A = dp2[u];
    if (A.empty())
        A = VI(n,-1);
    int& ans = A[i];
    if (-1 == ans) {
        ans = 0;
        ans += 1LL * dfs1(v) * dfs2(u,i+1) % mod;
        ans %= mod;
        ans += dfs2(u,i+1);
        ans %= mod;
    }
    return ans;
}

int dfs4(const int u, const int c, int i);

int dfs3(const int u)
{
    int ans = dfs1(u);
    if (u != 1) {
        ans += 1LL * ans * dfs4(parent[u],u,0) % mod;
        ans %= mod;
    }
    return ans;
}

int dfs4(const int u, const int c, int i)
{
    const int n = G2[u].size();
    if (i == n)
        return 1;
    const int v = G2[u][i];
    const PII k(u,c);
    VI& A = dp3[k];
    if (A.empty())
        A = VI(n,-1);
    int& ans = A[i];
    if (-1 == ans) {
        ans = 0;
        if (v != c) {
            ans += 1LL * dfs1(v) * dfs4(u,c,i+1) % mod;
            ans %= mod;
        }
        ans += dfs4(u,c,i+1);
        ans %= mod;
        if (u != 1) {
            ans += 1LL * ans * dfs4(parent[u],u,0) % mod;
            ans %= mod;
        }
    }
    return ans;
}

