				}
			}
			dp[a][x]++;
		}
		else {
			solve(ne, mp[make_pair(ne, X[ne])]);

			for (int i = 0; i < g[ne].size(); i++) {
				sum1[ne][i + 1] = (sum1[ne][i] * dp[ne][i]) % M;
			}
			for (int i = (int)g[ne].size() - 1; i >= 0; i--) {
				sum2[ne][i] = (sum2[ne][i + 1] * dp[ne][i]) % M;
			}

			X[ne] = -2;
