{ return S.find(s) != string::npos; }

/* For each vetex v, count # of subtrees can be rooted at v. */
/*
 *         r        Suppose the tree is rooted at r, we use dfs1 to get
 *        / \       value of subtree rooted at v. But when we reroot
 *       u   ..     the tree at v, we need to consider the value at u
 *      /|\         and all the other upper part of the tree. When
 *    /| | |\       consider u, we need to a merge of node 1,2 and 4,5.
 *   1 2[v]4 5      We can use a prefix and suffix value to calculate
 *   prx/ \sfx      the combination of node 1,2,4,5, where 3 is current
 *     /   \        node v.
 */

const int maxn = 1e5+5;
int parent[maxn], child[maxn], dp1[maxn], mod;
VI prx[maxn], sfx[maxn], dp2[maxn], G[maxn];

int getprx(const int u, const int i)
{ return i >= 0 ? prx[u][i] : 1; }
int getsfx(const int u, const int i)
{ return sfx[u][i]; }

int dfs1(const int u, const int p)
{
    parent[u] = p;
    int& ans = dp1[u];
    if (-1 == ans) {
        int n = 0;
        FOR_ALL(v,G[u]) if (*v != p)
            dfs1(*v,u), child[*v] = n++;
        prx[u] = sfx[u] = VI(n+1,1); /* +1 for sentinel */
        int i = 0;
        FOR_ALL(v,G[u]) if (*v != p) {
            /* use v */
            prx[u][i] = 1LL * getprx(u,i-1) * dp1[*v] % mod;
            /* not use v */
            prx[u][i] += getprx(u,i-1);
            prx[u][i] %= mod;
            i++;
        }
        i = n-1;
        FOR_ALLR(v,G[u]) if (*v != p) {
            sfx[u][i] = 1LL * getsfx(u,i+1) * dp1[*v] % mod;
            sfx[u][i] += getsfx(u,i+1);
            sfx[u][i] %= mod;
            i--;
        }
        ans = getprx(u,n-1);
    }
    return ans;
}

int dfs2(const int u, const int c)
{
    if (u == 0)
        return 0;
    if (dp2[u].empty())
        dp2[u] = VI(G[u].size(),-1);
    int& ans = dp2[u][c];
    if (-1 == ans) {
        ans  = 1LL * getprx(u,c-1) * getsfx(u,c+1) % mod;
        ans += 1LL * ans * dfs2(parent[u],child[u]) % mod;
        ans %= mod;
    }
    return ans;
}

