// For modular arithmetic when a modular is specified per input case.
// Verified: ABC129F
struct ModInt {
 private:
  static int64 M;
  int64 x;
 public:
  static void SetMod(int64 mod) {
    M = mod;
  }
  ModInt(int64 input_x) : x(input_x % M) {}
  ModInt() : x(0) {}
  int64 Value() { return x; }
  inline ModInt operator+(ModInt o) {
    ModInt r(*this); r += o; return r;
  }
  inline ModInt operator-(ModInt o) {
    ModInt r(*this); r -= o; return r;
  }
  inline ModInt operator* (ModInt o) {
    ModInt r(*this); r *= o; return r;
  }
  inline void operator+= (ModInt o) { x = (x + o.x) % M; }
  inline void operator-= (ModInt o) { x = (x + M - o.x) % M; }
  inline void operator*= (ModInt o) { x = (x * o.x) % M; }
};
int64 ModInt::M = 1;  // Do not forget to add this line.

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  int n;
  int64 mod;
  cin >> n >> mod;
  ModInt::SetMod(mod);

  vector<vector<Edge>> graph = ReadUndirectedGraph(n, n - 1, true);

  vector<ModInt> dp1(n);
  vector<vector<ModInt>> v_to_cpl(n);  // Cumulative product left
  vector<vector<ModInt>> v_to_cpr(n);  // Cumulative product right

  function<void(int, int)> dfs1 = [&](int v, int parent) {
    vector<ModInt> ps;
    for (auto e : graph[v]) {
      if (e.to == parent) continue;
      dfs1(e.to, v);
      ps.push_back(dp1[e.to] + 1);
    }

    if (ps.size() == 0) {
      dp1[v] = 1;
      return;
    }

    int d = ps.size();
    auto& cpl = v_to_cpl[v];
    auto& cpr = v_to_cpr[v];
    cpl.resize(d);
    cpr.resize(d);
    cpl[0] = ps[0];
    for (int i = 1; i < d; i++) {
      cpl[i] = cpl[i - 1] * ps[i];
    }
    cpr[d - 1] = ps[d - 1];
    for (int i = d - 2; i >= 0; i--) {
      cpr[i] = cpr[i + 1] * ps[i];
    }
    dp1[v] = cpl[d - 1];
  };
  dfs1(0, -1);

  vector<ModInt> dp2(n);
  function<void(int, int, ModInt)> dfs2 =
      [&](int v, int parent, ModInt factor) {
    // cout << "v: " << v << " factor: " << factor.Value() << endl;

    dp2[v] = dp1[v] * factor;

    auto& cpl = v_to_cpl[v];
    auto& cpr = v_to_cpr[v];

    int edge_id = 0;
    for (auto e : graph[v]) {
      if (e.to == parent) continue;
      ModInt new_factor = factor;
      if (edge_id - 1 >= 0) new_factor *= cpl[edge_id - 1];
      if (edge_id + 1 < cpr.size()) new_factor *= cpr[edge_id + 1];
      new_factor += 1;
      dfs2(e.to, v, new_factor);
      edge_id++;
    }
  };
  dfs2(0, -1, 1);

  for (int i = 0; i < n; i++) {
    cout << dp2[i].Value() << endl;
  }
}

