        if (h == p)
            continue;
        pp[i] = (pp[i] * 1LL * (d[h] + 1)) % M;
    }
    for (int i = a[x].size() - 1; i >= 0; --i)
    {
        int h = a[x][i];
        if (i < a[x].size() - 1)
            ss[i] = ss[i + 1];
        else
            ss[i] = 1;
        if (h == p)
            continue;
        ss[i] = (ss[i] * 1LL * (d[h] + 1)) % M;
    }
    for (int i = 0; i < a[x].size(); ++i)
    {
        int h = a[x][i];
        if (h == p)
            continue;
        int u = 1;
        if (i)
            u = (u * 1LL * pp[i - 1]) % M;
        if (i < a[x].size() - 1)
            u = (u * 1LL * ss[i + 1]) % M;
        dfs1(h, x, ((dp + 1) * 1LL * u) % M);
    }
}

