		int x;
		int y;
		std::cin >> x;
		std::cin >> y;
		vec[x - 1].connected_to.push_back(y - 1);
		vec[y - 1].connected_to.push_back(x - 1);
	}
	for (int i = 0; i < N; ++i) {
		std::cout << (traverse(i, -1, vec) - 1)%M << "\n";
	}

}

