long dfs1(const vector<long> &ps, const vector<vector<long>> &css, long M,
          vector<long> &dp1s, long i) {
  const long N = ps.size();
  if (dp1s[i] < 0) {
    long dp = 1;
    for (long j : css[i]) {
      dp = (dp * (dfs1(ps, css, M, dp1s, j) + 1)) % M;
    }
    dp1s[i] = dp;
  }
  return dp1s[i];
}

long dfs3(const vector<long> &ps, const vector<vector<long>> &css, long M,
          const vector<long> &dp2s, vector<long> &dp3s, long i) {
  const long N = ps.size();
  if (dp3s[i] < 0) {
    long dp;
    if (ps[i] >= 0) {
      dp = (dp2s[i] * dfs3(ps, css, M, dp2s, dp3s, ps[i]) + 1) % M;
    } else {
      dp = 1;
    }
    dp3s[i] = dp;
    for (long j : css[i]) {
      dfs3(ps, css, M, dp2s, dp3s, j);
    }
  }
  return dp3s[i];
}

