LLI N,M;

LLI dp[101000];
LLI dp2[101000];

LLI rec(vector<vector<int>> &tree, int cur, int par){
  dp[cur] = 1;

  for(auto next : tree[cur]){
    if(next == par) continue;
    (dp[cur] *= (rec(tree,next,cur)+1)%M) %= M;
  }

  return dp[cur];
}

LLI rec2(vector<vector<int>> &tree, int cur, int par, LLI val){
  int c = tree[cur].size();
  if(par != -1) --c;

  vector<LLI> left(c+1,1);
  REP(i,c) (left[i+1] = left[i] * (dp[tree[cur][i]]+1)%M) %= M;

  LLI right = 1;
  int i = c-1;

  REV(j,tree[cur].size()-1,0){
    int next = tree[cur][j];
    if(next == par) continue;
    dp2[next] = (val*left[i]%M*right%M+1)%M;

    (right *= (dp[tree[cur][j]]+1)%M) %= M;
    rec2(tree, next, cur, dp[next]);
    --i;
  }

  return dp2[cur];
}

