    --x, --y;
    tree[x].push_back(y);
    tree[y].push_back(x);
  }

  rec(tree, 0, -1);
  rec2(tree, 0, -1, dp2[0]=1);

  REP(i,N){
    LLI ans = (dp2[i]*dp[i])%M;
    cout << ans << endl;
  }

  return 0;
}

