vector<vector<int>> v(100010);
ll mod;

vector<ll> dp(100010);
vector<vector<ll>> prf(100010);

void dfs(int p,int pre){
    dp[p] = 1;
    for(auto i:v[p]){
        if(i!=pre){
            dfs(i,p);
            dp[p] = (dp[p] * (dp[i]+1)) % mod;
        }
    }
    ll now = 1;
    int m = v[p].size();
    for(int i=0;i<v[p].size();i++){
        if(v[p][i] == pre) continue;
        prf[p].push_back(now);
        now *= dp[v[p][m - i - 1]]+1;
        now %= mod;
    }
    reverse(prf[p].begin(),prf[p].end());
}

ll ans[100010];

void solve(int p,int pre,ll d){
    ans[p] = (d+1)%mod;
    ans[p] *= dp[p];
    ans[p] %= mod;
    db3(p,d+1,dp[p]);
    int now = 0;
    ll suf = d+1;
    for(auto i:v[p]){
        if(i != pre){
            ll ret = suf * prf[p][now];
            ret %= mod;
            solve(i,p,ret);
            now++;
            suf *= (dp[i]+1);
            suf %= mod;
        }
    }
}

