using ll = long long;
using vi = vector<int>;
using vvi = vector<vi>;
using vll = vector<ll>;
using vvll = vector<vll>;
using vb = vector<bool>;
using vd = vector<double>;
using vs = vector<string>;

int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N;
    ll M;
    cin >> N >> M;

    vvi adj(N);
    for(int i=0;i<N-1;i++) {
        int x, y;
        cin >> x >> y;
        x--; y--;
        adj[x].push_back(y);
        adj[y].push_back(x);
    }

    queue<int> bfs;
    vi parent(N, -1);
    vvi children(N);
    vi cindex(N, -1);
    vi order;

    bfs.push(0);
    parent[0] = 0;

    while (!bfs.empty()) {
        int cur = bfs.front();
        bfs.pop();

        order.push_back(cur);

        for(int nbr : adj[cur]) {
            if (parent[nbr] == -1) {
                parent[nbr] = cur;
                cindex[nbr] = children[cur].size();
                children[cur].push_back(nbr);
                bfs.push(nbr);
            }
        }

    }

    reverse(order.begin(), order.end());

    vll dp(N, 0);

    vvll prefs(N);
    vvll suffs(N);
    for (int v : order) {
        int S = children[v].size();

        ll cur = 1;
        prefs[v].push_back(cur);
        for (int i=0;i<S;i++) {
            int w = children[v][i];
            cur *= dp[w];
            cur %= M;
            prefs[v].push_back(cur);
        }

        cur = 1;
        suffs[v].push_back(cur);
        for(int i=0;i<S;i++) {
            int w = children[v][S-1-i];
            cur *= dp[w];
            cur %= M;
            suffs[v].push_back(cur);
        }

        dp[v] = 1 + prefs[v][S];
        dp[v] %= M;
    }

    vvll dpe(N);
    reverse(order.begin(), order.end());
    for (int v : order) {
        ll base = 1;
        if (v != 0) {
            // contribution from parent
            int par = parent[v];
            base = dpe[par][cindex[v]];
        }

        int S = children[v].size();
        for(int i=0;i<S;i++) {

            ll cur = (base * prefs[v][i]) % M;
            cur = (cur * suffs[v][S-i-1]) % M;
            cur++;
            dpe[v].push_back(cur);
        }
    }

    vll dpf(N);
    for (int v : order) {
        dpf[v] = 1;
        if (v != 0) {
            int par = parent[v];
            dpf[v] = dpe[par][cindex[v]];
        }
        dpf[v] = (dpf[v]*(dp[v]+M-1)) % M;
    }

    for (int i=0;i<N;i++) {
        cout << dpf[i] << endl;
    }


    return 0;
}

