    vector<mint> fmul(m + 1, 1), bmul(m + 1, 1);
    rep(i, m) {
        if(g[s][i] == par[s]) fmul[i + 1] *= fmul[i] * (rdp[s] + 1);
        else fmul[i + 1] *= fmul[i] * (dp[g[s][i]] + 1);
    }
    for(int i = m - 1; i >= 0; i--) {
        if(g[s][i] == par[s]) bmul[i] *= bmul[i + 1] * (rdp[s] + 1);
        else bmul[i] *= bmul[i + 1] * (dp[g[s][i]] + 1);
    }
    rep(i, m) {
        int j = g[s][i];
        if(j == par[s]) continue;
        rdp[j] = fmul[i] * bmul[i + 1];
        rdfs(j);
    }
}

