    cin >> N >> M;
    Rerooting reroot(N);
    rep(i, N - 1) {
        ll x, y;
        cin >> x >> y;
        x--;
        y--;
        reroot.add_edge(x, y);
        reroot.add_edge(y, x);
    }
    reroot.build();

    rep(i, N) {
        cout << (reroot.ans[i].dp - 1) % M << endl;
    }
}

