void maketree(int u,int p){
    tree[u].push_back(u);
    for(int to:G[u]){
        if(to==p) continue;
        tree[u].push_back(to);
        maketree(to,u);
    }
    tree[u].push_back(u);
}

void DFS(int u){

    dp[u][0]=1;
    dp[u][1]=1;

    int M=si(tree[u]);

    l[u][0].push_back(1);
    l[u][1].push_back(1);

    for(int i=1;i<M-1;i++){

        int to=tree[u][i];

        DFS(to);

        l[u][0].push_back(dp[to][0]);
        l[u][1].push_back((dp[to][0]+dp[to][1])%mod);
    }

    l[u][0].push_back(1);
    l[u][1].push_back(1);

    r[u][0]=l[u][0];
    r[u][1]=l[u][1];

    for(int i=1;i<M;i++){
        for(int j=0;j<2;j++){
            l[u][j][i]*=l[u][j][i-1];
            l[u][j][i]%=mod;
        }
    }

    for(int i=M-2;i>=0;i--){
        for(int j=0;j<2;j++){
            r[u][j][i]*=r[u][j][i+1];
            r[u][j][i]%=mod;
        }
    }

    dp[u][0]*=l[u][0].back();
    dp[u][0]%=mod;

    dp[u][1]*=l[u][1].back();
    dp[u][1]%=mod;
}

void zenn(int u,int p){

    int M=si(tree[u]);

    ans[u]=dp[u][1];

    for(int i=1;i<M-1;i++){
        int to=tree[u][i];

        ll a=dp[u][0],b=dp[u][1],c=dp[to][0],d=dp[to][1];

        dp[u][0]=l[u][0][i-1]*r[u][0][i+1]%mod;
        dp[u][1]=l[u][1][i-1]*r[u][1][i+1]%mod;

        if(p!=-1){
            dp[u][0]*=dp[p][0];
            dp[u][0]%=mod;

            dp[u][1]*=(dp[p][0]+dp[p][1]);
            dp[u][1]%=mod;
        }

        dp[to][0]*=dp[u][0];
        dp[to][0]%=mod;

        dp[to][1]*=(dp[u][0]+dp[u][1]);
        dp[to][1]%=mod;

        zenn(to,u);

        dp[u][0]=a;
        dp[u][1]=b;
        dp[to][0]=c;
        dp[to][1]=d;

    }
}


