typedef long long ll;

const int MAXN = 1e5 + 5;
int n, parent[MAXN];
ll M, g[MAXN], prod[MAXN], f[MAXN], pleft[MAXN], pright[MAXN];
vector<int> adj[MAXN];

void dfs(int s, int p = 0) {
    parent[s] = p;
    int m = adj[s].size();
    if(s != 1)
        m--;
    pleft[0] = pright[m + 1] = 1;
    g[s] = 1;
    for(auto v : adj[s]) {
        if(v == p)
            continue;
        dfs(v, s);
        g[s] = (g[s] * (g[v] + 1)) % M;
    }
    int ctl = 1, ctr = m;
    for(int i = 0; i < adj[s].size(); i++) {
        int v = adj[s][i];
        if(v == p)
            continue;
        pleft[ctl] = (pleft[ctl - 1] * (g[v] + 1)) % M;
        ctl++;
    }
    for(int i = adj[s].size() - 1; i >= 0; i--) {
        int v = adj[s][i];
        if(v == p)
            continue;
        pright[ctr] = (pright[ctr + 1] * (g[v] + 1)) % M;
        ctr--;
    }
    ctl = 1;
    for(auto v : adj[s]) {
        if(v == p)
            continue;
        prod[v] = (pleft[ctl - 1] * pright[ctl + 1]) % M;
        ctl++;
    }
}

void calcf(int s, int p = 0) {
    if(s != 1)
        f[s] = (prod[s] * (f[p] + 1)) % M;
    //cout << s << " " << prod[s] << " " << f[p] << " " << f[s] << endl;
    for(auto v : adj[s]) {
        if(v != p)
            calcf(v, s);
    }
}

