template <class Handler>
struct UnrootedTreeDP {
    typedef typename Handler::val_t val_t;
    int n;
    vector<vi> g;
    vector<vector<val_t>> memo;
    vector<val_t> dp;
    UnrootedTreeDP(const vector<vi> &g) :g(g), n(g.size()), dp(n), memo(n) {
        REP(i, n) {
            memo[i].resize(g[i].size());
        }
        dfs1(0, -1);
        dfs2(0, -1, 0);
    }

    val_t get(int u) {
        return dp[u];
    }
    val_t dfs1(int u, int p) {
        val_t res = Handler::def_val();
        REP(i, g[u].size()) {
            if (g[u][i] != p) {
                res = Handler::merge(res, dfs1(g[u][i], u) + 1);
            }
        }
        return dp[u] = res;
    }

    val_t dfs2(int u, int p, val_t pv) {
        vector<val_t> sum(g[u].size() + 1, Handler::def_val());
        RREP(i, g[u].size()) {
            sum[i] = Handler::merge((g[u][i] == p ? pv : dp[g[u][i]]) + 1, sum[i + 1]);
        }
        val_t res = Handler::def_val();
        REP(i, g[u].size()) {
            val_t ret = (g[u][i] == p ? pv : dp[g[u][i]]);
            if (g[u][i] != p) {
                dfs2(g[u][i], u, Handler::merge(res, sum[i + 1]));
            }
            res = Handler::merge(res, ret + 1);
        }
        return dp[u] = res;
    }
};

