template <typename T, typename U>
struct ZenhouiTreeDP{
  int N;
  Tree<T> tree;
  vector<int> parent;

  vector<U> sub_dp, bottom_up_dp;
  U id;

  ZenhouiTreeDP(const Tree<T> &tree, U id):
    N(tree.size()), tree(tree), parent(N), sub_dp(N), bottom_up_dp(N, id), id(id)
  {
    rooting(0);
  }

  void rooting(int cur, int par = -1){
    auto it = tree[cur].begin();
    while(it != tree[cur].end()){
      if(it->to == par) break;
      ++it;
    }
    if(it != tree[cur].end()) tree[cur].erase(it);

    for(auto &e : tree[cur]){
      rooting(e.to, e.from);
    }
  }

  virtual void subtree_func(int cur, int to){}

  void sub_dfs(int cur){
    sub_dp[cur] = id;

    for(auto &e : tree[cur]){
      sub_dfs(e.to);
      subtree_func(cur, e.to);
    }
  }

  virtual void bottom_up_func(int cur, int par, U left, U right){}
  virtual U sum_func(U prev, int cur){return 0;}

  void accum_dfs(int cur){
    int size = tree[cur].size();

    vector<U> left_sum(size+1, id);
    U right_sum = id;

    for(int i = 0; i < size; ++i){
      left_sum[i+1] = sum_func(left_sum[i], tree[cur][i].to);
    }

    for(int i = size-1; i >= 0; --i){
      int nxt = tree[cur][i].to;

      bottom_up_func(nxt, cur, left_sum[i], right_sum);

      right_sum = sum_func(right_sum, nxt);
      accum_dfs(nxt);
    }
  }

};


struct DP : public ZenhouiTreeDP<int, LLI>{
  int M;
  DP(const Tree<int> &tree, int M): ZenhouiTreeDP(tree, 1), M(M){}

  void subtree_func(int cur, int to){
    (sub_dp[cur] *= (sub_dp[to]+1) % M) %= M;
  }

  void bottom_up_func(int cur, int par, LLI left, LLI right){
    (bottom_up_dp[cur] = (bottom_up_dp[par] * left % M * right % M + 1) % M) %= M;
  }

  LLI sum_func(LLI prev, int cur){
    return prev * (sub_dp[cur] + 1) % M;
  }

  void run(){
    sub_dfs(0);
    accum_dfs(0);
  }
};


