		if(*it!=fa[x]) fa[*it]=x,Fdfs(*it),Fdp[x]=Fdp[x]*(Fdp[*it]+1)%m;
	return;
}

void Sdfs(int x){
	int len=ver[x].size();
	long long suf[len+10],pre[len+10];
	pre[0]=1,suf[len+1]=1;
	for(int i=1;i!=len;++i)
		pre[i]=pre[i-1]*(Fdp[ver[x][i-1]]+1)%m,
		suf[len-i+1]=suf[len-i+2]*(Fdp[ver[x][len-i]]+1)%m;
	for(int i=0;i!=len;++i){
		if(Sdp[ver[x][i]]!=-1) continue;
		int tmp1=Fdp[x],tmp2=Fdp[ver[x][i]];
		fa[ver[x][i]]=-1,fa[x]=ver[x][i];
		Fdp[x]=pre[i]*suf[i+2]%m,Fdp[ver[x][i]]=(Fdp[x]+1)*tmp2%m;
		Sdp[ver[x][i]]=Fdp[ver[x][i]],Sdfs(ver[x][i]);
		fa[x]=-1,fa[ver[x][i]]=x;
		Fdp[x]=tmp1,Fdp[ver[x][i]]=tmp2;
	}
	return;
}

