using namespace std;

using ll = long long;

int const maxn = 101010;

int mod;

vector<int> v[maxn];
int dp[maxn], up[maxn];

int pref[maxn], suf[maxn];

void mul(int& a, int b) {
    a = (ll)a*b%mod;
}

int solve(int x, int p) {
    int& d = dp[x];

    if (d != -1) return d;

    d = 1;
    for (int u : v[x]) {
        if (u == p) continue;

        mul(d, solve(u, x) + 1);
    }

    int k = 1;
    for (int u : v[x]) {
        if (u == p) continue;
        pref[u] = k;
        mul(k, solve(u, x) + 1);
    }

    k = 1;
    for (int i = (int)v[x].size()-1; i >= 0; i--) {
        int u = v[x][i];

        if (u == p) continue;
        suf[u] = k;
        mul(k, solve(u, x) + 1);
    }

    return d;
}

void solve2(int x, int p) {
    for (int u : v[x]) {
        if (u == p) continue;

        up[u] = 1;
        mul(up[u], pref[u]);
        mul(up[u], suf[u]);
        mul(up[u], up[x] + 1);

        mul(dp[u], up[u] + 1);

        solve2(u, x);
    }
}

