        cin >> a >> b;

        v[a].push_back(b);
        v[b].push_back(a);
    }

    memset(dp, -1, sizeof(dp));

    solve(1, 1);
    solve2(1, 1);

    for (int i = 1; i <= n; i++) {
        cout << dp[i] << "\n";
    }
}

