	ReRooting(int N, vector<vector<int>>edges, T identity, function<T(T, T)>ope, function<T(T, int)>opeNode) :N(N), identity(identity), ope(ope), opeNode(opeNode),adj(N),idxForAdj(N),dp(N),res(N){
		for (int i = 0; i < edges.size(); i++) {
			auto &edge = edges[i];
			idxForAdj[edge[0]].push_back(adj[edge[1]].size());
			idxForAdj[edge[1]].push_back(adj[edge[0]].size());
			adj[edge[0]].push_back(edge[1]);
			adj[edge[1]].push_back(edge[0]);
		}
		for (int i = 0; i < adj.size(); i++)dp[i] = vector<T>(adj[i].size());
		if (N > 1)initialize();
		else if (N == 1)res[0] = opeNode(identity, 0);
	}
	void initialize() {
		vector<int>par(N);
		vector<int>ord(N);
#pragma region InitOrderedTree
		int idx = 0;
		stack<int>stk;
		stk.push(0);
		par[0] = -1;
		while (!stk.empty()) {
			auto node = stk.top();
			stk.pop();
			ord[idx++] = node;
			for (auto nxt : adj[node]) {
				if (nxt == par[node])continue;
				stk.push(nxt);
				par[nxt] = node;
			}
		}
#pragma endregion

#pragma region fromLeaf
		for (int i = ord.size() - 1; i >= 1; i--) {
			auto node = ord[i];
			auto parent = par[node];
			T accum = identity;
			int parIdx = -1;
			for (int j = 0; j < adj[node].size(); j++) {
				if (adj[node][j] == parent) {
					parIdx = j;
					continue;
				}
				accum = ope(accum, dp[node][j]);
			}

			dp[parent][idxForAdj[node][parIdx]] = opeNode(accum, node);
		}
#pragma endregion

#pragma region toLeaf
		for (int i = 0; i < ord.size(); i++) {
			auto node = ord[i];
			T accum = identity;
			vector<T>accumsFromTail(adj[node].size());
			accumsFromTail[accumsFromTail.size() - 1] = identity;
			for (int j = accumsFromTail.size() - 1; j >= 1; j--)accumsFromTail[j - 1] = ope(dp[node][j], accumsFromTail[j]);
			for (int j = 0; j < accumsFromTail.size(); j++) {
				dp[adj[node][j]][idxForAdj[node][j]] = opeNode(ope(accum, accumsFromTail[j]), node);
				accum = ope(accum, dp[node][j]);
			}
			res[node] = opeNode(accum, node);
		}
#pragma endregion
	}
};

