#include <bits/stdc++.h>

using namespace std;

const int N = 100010;

vector <int> g[N];
vector <int> pref[N];
vector <int> suff[N];
int n, m, down[N], up[N];

void fix (int u = 1) {
  for (int v : g[u]) {
    g[v].erase(find(g[v].begin(), g[v].end(), u));
    fix(v);
  }
}

void go (int u = 1) {
  down[u] = 1;
  for (int v : g[u]) {
    go(v);
    down[u] = down[u] * 1LL * (1 + down[v]) % m;
  }
  int sz = g[u].size();
  pref[u].resize(sz + 1);
  suff[u].resize(sz + 1);
  pref[u][0] = suff[u][sz] = 1;
  for (int i = 0; i < sz; ++i) {
    pref[u][i + 1] = pref[u][i] * 1LL * (1 + down[g[u][i]]) % m;
  }
  for (int i = sz - 1; i >= 0; --i) {
    suff[u][i] = suff[u][i + 1] * 1LL * (1 + down[g[u][i]]) % m;
  }
}

void dfs (int u = 1) {
  for (int i = 0; i < g[u].size(); ++i) {
    int v = g[u][i];
    up[v] = pref[u][i] * 1LL * suff[u][i + 1] % m;
    up[v] = up[v] * 1LL * up[u] % m;
    ++up[v]; if (up[v] >= m) up[v] -= m;
    dfs(v);
  }
}

