void dfs2(int u){
    pref[u][0] = 1;
    for (int j = 1; j < adj[u].size(); j++){
        ii v = adj[u][j];
        pref[u][j] = mul(pref[u][j-1], dp[v.fi][v.se]);
    }

    suf[u][adj[u].size()] = 1;
    for (int j = adj[u].size()-1; j >= 1; j--){
        ii v = adj[u][j];
        suf[u][j] = mul(suf[u][j+1], dp[v.fi][v.se]);
    }

