#ifndef H_dp_on_tree
#define H_dp_on_tree

#include <cstddef>
#include <queue>
#include <vector>

template <typename Monoid, typename AdjacencyList, typename Fn>
std::vector<Monoid> dp_on_tree(AdjacencyList const& g, Fn f, Monoid e = Monoid{}) {
  size_t n = g.size();
  std::vector<size_t> ord, par(n, n);
  std::vector<bool> vis(n, false);
  ord.reserve(n);
  vis[0] = true;
  std::queue<size_t> q;
  q.push(0);
  while (!q.empty()) {
    size_t v = q.front();
    q.pop();
    ord.push_back(v);
    for (auto const& e: g[v]) {
      size_t u = e.target();
      if (!vis[u]) {
        vis[u] = true;
        par[u] = v;
        q.push(u);
      }
    }
  }

  std::vector<Monoid> dpl(n, e), dpr(n, e), dpp(n, e);
  for (size_t i = n; i--;) {
    size_t v = ord[i];
    bool bef = true;
    for (size_t j = 0; j < g[v].size(); ++j) {
      auto const& e = g[v][j];
      size_t u = e.target();
      auto w = e.weight();
      if (u == par[v]) {
        bef = true;
      } else if (bef) {
        dpl[v] += f(dpl[u] + dpr[u], w);
      } else {
        dpr[v] = f(dpl[u] + dpr[u], w) + std::move(dpr[v]);
      }
    }
  }

  std::vector<Monoid> dp(n);
  for (size_t i = 0; i < n; ++i) {
    size_t v = ord[i];
    std::vector<Monoid> al(g[v].size());
    for (size_t j = 0; j < g[v].size(); ++j) {
      auto const& e = g[v][j];
      size_t u = e.target();
      auto w = e.weight();
      al[j] = ((u == par[v])? dpp[v]: f(dpl[u] + dpr[u], w));
    }
    auto ar = al;
    al.insert(al.begin(), e);
    ar.push_back(e);
    for (size_t j = 1; j <= g[v].size(); ++j) al[j] = al[j-1] + std::move(al[j]);
    for (size_t j = g[v].size(); j--;) ar[j] += ar[j+1];
    for (size_t j = 0; j < g[v].size(); ++j) {
      auto const& e = g[v][j];
      size_t u = e.target();
      if (u == par[v]) continue;
      auto w = e.weight();
      dpp[u] = f(al[j] + ar[j+1], w);
    }
    dp[v] = ar[0];
  }
  return dp;
}

#endif  /* !defined(H_dp_on_tree) */

