void dfs1(int v, int parent){
    dp[v] = 1;
    for(auto c : graf[v]){
        if(c == parent) continue;
        dfs1(c, v);
    }
    int k = graf[v].size();
    for(int i=0; i<k; i++){
        if(graf[v][i] == parent){
            graf[v].erase(graf[v].begin()+i);
            break;
        }
    }
    k = graf[v].size();
    for(int i=0; i<k; i++){
        pref[v].push_back(1+dole[graf[v][i]]);
        if(i) pref[v][i] = mul(pref[v][i], pref[v][i-1]);
    }
    for(int i=k-1; i>=0; i--){
        suf[v].push_back(1+dole[graf[v][i]]);
        if(i < k-1) suf[v][k-1-i] = mul(suf[v][k-1-i], suf[v][k-2-i]);
    }
    reverse(suf[v].begin(), suf[v].end());
