    if(k) dole[v] = pref[v][k-1];
    else dole[v] = 1;
}

void dfs2(int v, int parent){
    dp[v] = add(1, dpn[parent]);
    dp[v] = mul(dp[v], dole[v]);
    dpn[v] = dp[v];
    int k = graf[v].size();
    for(int i=0; i<k; i++){
        dpn[v] = add(1, dpn[parent]);
        if(i) dpn[v] = mul(dpn[v], pref[v][i-1]);
        if(i < k-1) dpn[v] = mul(dpn[v], suf[v][i+1]);
        dfs2(graf[v][i], v);
    }
}

