using namespace std;
vector<int> parent(vector<vector<int>> &E, int r){
	int N = E.size();
	vector<int> p(N, -1);
	queue<int> Q;
	Q.push(r);
	while (!Q.empty()){
		int v = Q.front();
		Q.pop();
		for (int w : E[v]){
			if (p[w] == -1){
				p[w] = v;
				Q.push(w);
			}
		}
	}
	return p;
}
vector<vector<int>> child(vector<int> &p, int r){
	int N = p.size();
	vector<vector<int>> c(N);
	for (int i = 0; i < N; i++){
		if (i != r){
			c[p[i]].push_back(i);
		}
	}
	return c;
}
long long add(long long A, long long B, long long MOD){
  return A * B % MOD;
}
long long root(long long A, long long MOD){
  return (A + 1) % MOD;
}
long long dfs1(vector<long long> &dp, vector<vector<int>> &c, int v, long long MOD){
  dp[v] = 1;
  for (int w : c[v]){
    dp[v] = add(dp[v], root(dfs1(dp, c, w, MOD), MOD), MOD);
  }
  return dp[v];
}
void dfs2(vector<long long> &dp1, vector<long long> &dp2, vector<vector<int>> &c, int v, long long MOD){
  int deg = c[v].size();
  vector<long long> L(deg + 1, 1);
  for (int i = 0; i < deg; i++){
    L[i + 1] = add(L[i], root(dp1[c[v][i]], MOD), MOD);
  }
  vector<long long> R(deg + 1, 1);
  for (int i = deg - 1; i >= 0; i--){
    R[i] = add(R[i + 1], root(dp1[c[v][i]], MOD), MOD);
  }
  for (int i = 0; i < deg; i++){
    //cout << "v=" << v << ", w=" << c[v][i] << endl;
    long long sum = add(L[i], R[i + 1], MOD);
    //cout << "sum=" << sum << endl;
    dp2[c[v][i]] = root(add(dp2[v], sum, MOD), MOD);
    dfs2(dp1, dp2, c, c[v][i], MOD);
  }
}
