template<typename T> vector<T> rerooting(vector<vector<int>> const & g, T const id, function<T(T, T)> f, function<T(T)> u) {
	int n = SI(g);
	vector<T> C(n, id), P(n, id), ans(n);
	function<void(int, int)> dfs1 = [&](int v, int p) {
		RF(e, g[v]) {
			if(e == p) { continue; }
			dfs1(e, v);
			C[v] = f(C[v], u(C[e]));
		}
	};
	function<void(int, int)> dfs2 = [&](int v, int p) {
		int d = SI(g[v]);
		vector<T> L(d + 1, id), R(d + 1, id);
		inc(i, d) {
			int e = g[v][i];
			L[i + 1] = R[i] = u(e == p ? P[v] : C[e]);
		}
		inc(i, d) { L[i + 1] = f(L[i], L[i + 1]); }
		dec(i, d) { R[i]     = f(R[i], R[i + 1]); }
		assert(L.BA == R.FR);
		ans[v] = u(L.BA);
		inc(i, d) {
			int e = g[v][i];
			if(e == p) { continue; }
			P[e] = f(L[i], R[i + 1]);
		}
		RF(e, g[v]) {
			if(e == p) { continue; }
			dfs2(e, v);
		}
	};
	dfs1(0, -1);
	dfs2(0, -1);
	return ans;
}
