int n, m;
vector<vector<int> > adj(100001);
vector<int> dp, ans;

void dfs1(int x, int p) {
	for (int c : adj[x]) {
		if (c == p) continue;
		dfs1(c, x);
		dp[x] *= dp[c] + 1; dp[x] %= m;
	}
	return;
}

void dfs2(int x, int p) {
	int l = adj[x].size();
	vector<int> cuml(l+2, 1);
	vector<int> cumr(l+2, 1);
	for (int i = 0; i < l; ++i) cuml[i+1] = (cuml[i] * (dp[adj[x][i]] + 1)) % m;
	for (int i = l-1; i >= 0; --i) cumr[i+1] = (cumr[i+2] * (dp[adj[x][i]] + 1)) % m;
	int pres_x = dp[x];
	for (int i = 0; i < l; ++i)
	{
		int c = adj[x][i];
		if (c == p) continue;
		int pres_c = dp[c];
		dp[x] = (cuml[i] * cumr[i+2]) % m;
		dp[c] *= dp[x] + 1;
		dp[c] %= m;
		ans[c] = dp[c];
		dfs2(c, x);
		dp[x] = pres_x;
		dp[c] = pres_c;
	}
	return;
}

