vector<int> g[N];
ll dp[N] , dp2[N] , P[N];

void dfs(int v , int p){
    dp[v] = 1;
    P[v] = p;
    for(int i = 0; i < g[v].size(); i++){
        int x = g[v][i];
        if (x!=p) dfs(x,v);
    }
    for(int i = 0; i < g[v].size(); i++){
        int x = g[v][i];
        if (x == p) continue;
        dp[v] *= dp[x] + 1;
        dp[v] %= MOD;
    }
} 

void dfs2(int v , int p){
    ll res;
    if(p == 0){
        res = 1;
    }else{
        res = dp2[p];
        for(int i = 0; i < g[p].size(); i++){
            int x = g[p][i];
            if ( x != v && x != P[p]) res = (res * (1 + dp[x] )) % MOD;    
        }
        res++;
        res %= MOD;
    }
    dp2[v] = res;
    for(int i = 0; i < g[v].size(); i++){
        int x = g[v][i];
        if (x!=p) dfs2(x,v);
    }
} 


