//int N, M, K, H, W, L, R;
long long int N, M, K, H, W, L, R;

void Calculate_Depth(vector<vector<int>>&edge, vector<int>&depth, int stnode) {
	depth[stnode] = 0;
	queue<int>Q;
	Q.push(stnode);
	while (!Q.empty()) {
		int cn = Q.front();
		Q.pop();
		for (auto i : edge[cn]) {
			if (depth[i] > depth[cn] + 1) {
				depth[i] = depth[cn] + 1;
				Q.push(i);
			}
		}
	}
	return;
}

void Search(vector<vector<int>>&edge, vector<long long int>&dp, vector<int>&depth, int node, vector<vector<long long int>>&l, vector<vector<long long int>>&r) {
	l[node].resize(edge[node].size(), 1);
	r[node].resize(edge[node].size(), 1);
	for (int i = 0; i < edge[node].size(); i++) {
		if (depth[edge[node][i]] > depth[node]) {
			Search(edge, dp, depth, edge[node][i], l, r);
			dp[node] *= dp[edge[node][i]] + 1;
			dp[node] %= M;
			l[node][i] = dp[edge[node][i]] + 1;
			r[node][i] = dp[edge[node][i]] + 1;
		}
	}
	for (int i = 1; i < edge[node].size(); i++) {
		l[node][i] *= l[node][i - 1];
		l[node][i] %= M;
	}
	for (int i = ((int)edge[node].size()) - 2; i >= 0; i--) {
		r[node][i] *= r[node][i + 1];
		r[node][i] %= M;
	}
	return;
}

void Search(vector<vector<int>>&edge, vector<long long int>&dpa, vector<long long int>&dpb, vector<int>&depth, int node, vector<vector<long long int>>&l, vector<vector<long long int>>&r, long long int box = 1) {
	for (int i = 0; i < edge[node].size(); i++) {
		if (depth[edge[node][i]] > depth[node]) {
			if (i)dpb[edge[node][i]] *= l[node][i - 1];
			if (i + 1 < edge[node].size())dpb[edge[node][i]] *= r[node][i + 1];
			dpb[edge[node][i]] %= M;
			dpb[edge[node][i]] *= box;
			dpb[edge[node][i]]++;
			dpb[edge[node][i]] %= M;
			long long int nx = dpb[edge[node][i]];
			dpb[edge[node][i]] *= dpa[edge[node][i]];
			dpb[edge[node][i]] %= M;
			Search(edge, dpa, dpb, depth, edge[node][i], l, r,nx);
		}
	}
	return;
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);

	cin >> N >> M;
	vector<vector<int>>edge(N);
	for (int i = 1; i < N; i++) {
		cin >> L >> R;
		L--;
		R--;
		edge[L].push_back(R);
		edge[R].push_back(L);
	}
	vector<vector<long long int>>l(N);
	vector<vector<long long int>>r(N);
	vector<int>depth(N, MOD);
	Calculate_Depth(edge, depth, 0);
	vector<long long int>dpa(N, 1);
	vector<long long int>dpb(N, 1);
	Search(edge, dpa, depth, 0, l, r);
	dpb[0] = dpa[0];
	Search(edge, dpa, dpb, depth, 0, l, r);
	for (int i = 0; i < N; i++)cout << dpb[i] << endl;
}

