ll n,m,x,y;
vl g[110000];
ll dp1[110000],dp2[110000];
ll ans[110000];
void dfs1(ll x,ll last=-1){
    ll res=1;
    for(auto next:g[x]){
        if(next==last)continue;
        dfs1(next,x);
        res*=dp1[next];
        res%=m;
    }
    dp1[x]=res+1;
    dp1[x]%=m;
}
void dfs2(ll x,ll last=-1){
    if(last==-1)dp2[x]=1;
    vl lcnt(sz(g[x]),1);
    vl rcnt(sz(g[x]),1);
    for(int i=0;i<sz(g[x]);i++){
        ll next=g[x][i];
        if(i>=1)lcnt[i]=lcnt[i-1];
        if(next==last)continue;
        else{
            lcnt[i]*=dp1[next];
            lcnt[i]%=m;
        }
    }
    for(int i=sz(g[x])-1;i>=0;i--){
        ll next=g[x][i];
        if(i<sz(g[x])-1)rcnt[i]=rcnt[i+1];
        if(next==last)continue;
        else{
            rcnt[i]*=dp1[next];
            rcnt[i]%=m;
        }
    }
    for(int i=0;i<sz(g[x]);i++){
        ll next=g[x][i];
        if(next==last)continue;
        ll res=1;
        if(i!=0)res*=lcnt[i-1],res%=m;
        if(i!=sz(g[x])-1)res*=rcnt[i+1],res%=m;
        dp2[next]=(res*dp2[x]+1)%m;
        dfs2(next,x);
    }
}
void dfs3(ll x,ll last=-1){
    ans[x]=dp2[x];
    for(auto next:g[x]){
        if(last==next)continue;
        ans[x]*=dp1[next];
        ans[x]%=m;
        dfs3(next,x);
    }
}
