    if(i != (tree[v].size()-1))(R[i] = (R[i+1] * (1 + dp[v][i+1]))%m)%m;
    ll tot = L[i]%m * R[i]%m;
    tot %= m;
    int e = tree[v][i];
    if(e == u)continue;
    dfs2(e,v,tot);
  }
}

