struct SegTree{
	int size;
	vector<llint> seg;

	SegTree(){}
	SegTree(int size){
		this->size = size;
		seg.resize(1<<(size+1));
	}

	void init()
	{
		for(int i = 0; i < (1<<(size+1)); i++) seg[i] = 0;
	}

	void update(int i, llint val)
	{
		i += (1 << size);
		seg[i] = val;
		while(i > 1){
			i /= 2;
			seg[i] = (seg[i*2] * seg[i*2+1]) % mod;
		}
	}

	llint query(int a, int b, int k, int l, int r)
	{
		if(b < l || r < a) return 1;
		if(a <= l && r <= b) return seg[k];
		llint lval = query(a, b, k*2, l, (l+r)/2);
		llint rval = query(a, b, k*2+1, (l+r)/2+1, r);
		return (lval * rval) % mod;
	}
	llint query(int a, int b)
	{
		if(a > b) return 1;
		return query(a, b, 1, 0, (1<<size)-1);
	}
};


vector<int> G[100005];
int edge[100005][2];
llint dp[100005][2];
SegTree seg(17);

llint modpow(llint a, llint n)
{
	if(n == 0) return 1;
	if(n % 2){
		return ((a%mod) * (modpow(a, n-1)%mod)) % mod;
	}
	else{
		return modpow((a*a)%mod, n/2) % mod;
	}
}

int getid(int i, int u)
{
	if(edge[i][0] == u) return 0;
	else return 1;
}

void dfs(llint e, llint id)
{
	llint v = edge[e][id];
	for(int i = 0; i < G[v].size(); i++){
		if(G[v][i] == e) continue;
		dfs(G[v][i], 1-getid(G[v][i], v));
	}
	llint ret = 1;
	for(int i = 0; i < G[v].size(); i++){
		if(G[v][i] == e) continue;
		ret *= dp[G[v][i]][1-getid(G[v][i], v)]+1, ret %= mod;
	}
	dp[e][id] = ret;
}


void dfs2(llint e, llint id)
{
	llint v = edge[e][id];

	for(int i = 0; i < G[v].size(); i++){
		seg.update(i, dp[G[v][i]][1-getid(G[v][i], v)]+1);
	}
	for(int i = 0; i < G[v].size(); i++){
		if(G[v][i] == e) continue;
		llint tmp = seg.query(0, i-1) * seg.query(i+1, (int)G[v].size()-1) % mod;
		dp[G[v][i]][getid(G[v][i], v)] = tmp;
	}
	for(int i = 0; i < G[v].size(); i++){
		if(G[v][i] == e) continue;
		dfs2(G[v][i], 1-getid(G[v][i], v));
	}
}

