void dfs1(int node){
  dp[node]=1;
  for(int child:edges[node]){
    edges[child].erase(std::find(edges[child].begin(),edges[child].end(),node));
    dfs1(child);
    dp[node]=1LL*dp[node]*dp[child]%MOD;
  }
  dp[node]=(dp[node]+1)%MOD;
  //printf("dp[%d]=%d\n",node,dp[node]);
}

void dfs2(int node,int up){
  //printf("dfs2(%d,%d)\n",node,up);
  std::vector<int> prefix(edges[node].size());
  std::vector<int> suffix(edges[node].size());
  for(int i=0;i<edges[node].size();i++){
    prefix[i]=suffix[i]=dp[edges[node][i]];
  }
  for(int i=1;i<edges[node].size();i++){
    prefix[i]=1LL*prefix[i-1]*prefix[i]%MOD;
  }
  for(int i=(int)edges[node].size()-2;i>=0;i--){
    suffix[i]=1LL*suffix[i+1]*suffix[i]%MOD;
  }
  for(int i=0;i<edges[node].size();i++){
    //printf("prefix[%d][%d]=%d\n",node,i,prefix[i]);
    //printf("suffix[%d][%d]=%d\n",node,i,suffix[i]);
    int child=edges[node][i];
    int curr=up;
    if(i+1<edges[node].size()) curr=1LL*curr*suffix[i+1]%MOD;
    if(i-1>=0) curr=1LL*curr*prefix[i-1]%MOD;
    dfs2(child,(curr+1)%MOD);
  }
  ans[node]=1LL*up*(dp[node]+MOD-1)%MOD;
}

