		{
			pref[u][0] = (down[pref[u][0]]+1) % mod;
			for (int i = 1; i < pref[u].size(); ++i)
				pref[u][i] = pref[u][i-1] * (down[pref[u][i]]+1) % mod;

			suf[u].back() = (down[suf[u].back()]+1) % mod;
			for (int i = suf[u].size()-2; i >= 0; --i)
				suf[u][i] = suf[u][i+1] * (down[suf[u][i]]+1) % mod;
