#include<bits/stdc++.h>
using namespace std;

const int mN = 100100;
int n, mod;
vector<int> graph[mN];

typedef long long LL;
LL cnt[mN], coef[mN];

int parent[mN];
void dfs(int u) {
    cnt[u] = coef[u] = 1;
    for (int v : graph[u]) if (parent[u] != v) {
        parent[v] = u;
        dfs(v);
        cnt[u] *= cnt[v] + 1;
        cnt[u] %= mod;
    }
}

LL prefix[mN], suffix[mN];
void reconsider(int u) {
    int id = 0;
    prefix[0] = 1;
    for (int j=0; j<graph[u].size(); j++) {
        int v = graph[u][j];
        if (parent[u] == v) continue;
        prefix[++id] = (prefix[id-1] * (cnt[v]+1)) % mod;
    }
//    cerr << "total = " << id << ".";
    suffix[id+1] = 1;
    for (int j=graph[u].size()-1; j>=0; j--) {
        int v = graph[u][j];
        if (parent[u] == v) continue;
        suffix[id] = (suffix[id+1] * (cnt[v]+1)) % mod;
        --id;
    }
//    cerr << "prepare for node " << u << " completed: ";
//    for (int i=0; i<=graph[u].size()+1; i++) cerr << "(" << prefix[i] << "," << suffix[i] << ") ";
//    cerr << "\n";
    for (int j=0; j<graph[u].size(); j++) {
        int v = graph[u][j];
        if (parent[u] == v) continue;
        LL u_as_child = (prefix[id++] * suffix[id+1]) % mod;
        u_as_child *= coef[u], u_as_child %= mod;
        cnt[v] *= u_as_child + 1;
        cnt[v] %= mod;
        coef[v] = u_as_child + 1;
        if (u == 2 and v == 3) cerr << cnt[v] << "\n";
        parent[v] = u;
        reconsider(v);
    }
    //cerr << u << " : " << cnt[u] << "\n";
}

int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(nullptr);
    cin >> n >> mod;
    for (int i=1,x,y; i<n; i++) {
        cin >> x >> y;
        graph[x].push_back(y);
        graph[y].push_back(x);
    }
    fill(parent, parent+mN, 0);
    dfs(1);
    fill(parent, parent+mN, 0);
    fill(suffix, suffix+mN, 1);
    fill(prefix, prefix+mN, 1);
    reconsider(1);
    for (int i=1; i<=n; i++) cout << cnt[i] << "\n";
	return 0;
}

