	ll res=1;

	for (auto it :edge[s]){
		if (it!=par){
			DFS1(it,s);

			res=res*(down[it]+1)%M;

			luu[s].push_back(down[it]+1);
		}
	}

	down[s]=res;
	up[s]=1;
}

void DFS2(int s,int par = -1){
	for (ll i=0;i<edge[s].size();++i){
		auto it=edge[s][i];
		if (it!=par){
			up[it]=up[s]*((i>0)? pr[s][i-1] : 1)%M * ((i<edge[s].size()-1)? sf[s][i+1] : 1)%M;

			dp2[it]=down[it]*(up[it]+1)%M;

			DFS2(it,s);

		}

	}
}

