const int MAXN=1e5+5;
int ans[MAXN];
int parent[MAXN];
int dp[MAXN][2];
vi dp_blk[MAXN][2];
vvi adj(MAXN);
int N,MOD;
int BLK = 500;
vi order;

void dfs1(int u, int p) {
    order.push_back(u);
    for(auto to : adj[u]) {
        if(to==p) continue;
        dfs1(to, u);
    }
}

int dfs(int u, int p, int col) {
    if(parent[u]!=p)
        parent[u]=p, dp[u][0]=dp[u][1]=-1;
    if(dp[u][col]>=0)
        return dp[u][col];

    int blks = ((int)adj[u].size() + BLK-1) / BLK;
    ll res=1;

    FOR(i,blks) {
        int idx_from = i*BLK;
        int idx_to = min( (i+1)*BLK-1, (int)adj[u].size()-1 );
        int u_from = adj[u][idx_from];
        int u_to = adj[u][idx_to];

        if(u_from<=p && p<=u_to) {
            RNG(j, idx_from, idx_to) {
                int to = adj[u][j];
                if(to!=p)
                    res = res * dfs(to, u, col) % MOD;
            }
            continue;
        }

        if(dp_blk[u][col][i]<0) {
            ll rez=1;
            RNG(j, idx_from, idx_to) {
                int to = adj[u][j];
                rez = rez * dfs(to, u, col) % MOD;
            }
            dp_blk[u][col][i] = rez;
        }

        res = res*dp_blk[u][col][i] % MOD;
    }

    if(p>=1 && col==0)
        res += dfs(u, p, 1);

    return dp[u][col]=res%MOD;
}

int main() {
    ios_base::sync_with_stdio(false); cin.tie(nullptr); cout.tie(nullptr);
    cin>>N>>MOD;
    FOR(i,N-1)
    {
        int a,b; cin>>a>>b;
        adj[a].push_back(b);
        adj[b].push_back(a);
    }

    RNG(u,1,N) {
        int blks = ((int)adj[u].size() + BLK-1) / BLK;
        FOR(i,2)
            dp_blk[u][i].resize(blks, -1);
        sort(ALL(adj[u]));
    }

    dfs1(1, -1);

    for(auto u : order) {
        ans[u] = dfs(u, -1, 0);
    }

    FOR(i,N) cout<<ans[i+1]<<endl;

    return 0;
}

