long long N, M;
vector<vector<int>> G;
vector<long long> dp;

long long dfs(int cur, int prv){
    if(dp[cur] != 0) return dp[cur];
    long long ans = 1;
    for(int nxt : G[cur]){
        if(nxt == prv) continue;
        ans *= (1 + dfs(nxt, cur)) % M;
        ans %= M;
    }
    dp[cur] = ans;
    return ans;
}

void efs(int cur, int prv, int mul){
    vector<int> chs;
    for(int nxt : G[cur]){
        if(nxt == prv) continue;
        chs.push_back(nxt);
    }
    int K = chs.size();
    vector<long long> cm0(K+2, 1), cm1(K+2, 1);
    for(int i=0; i<K; i++) cm0[i+1] = (cm0[i] * (dp[chs[i]] + 1) % M) % M;
    for(int i=K-1; i>=0; i--) cm1[i+1] = (cm1[i+2] * (dp[chs[i]] + 1) % M) % M;
    REP(i, K){
        long long tmp = ((mul * (cm0[i] * cm1[i+2]) % M) % M + 1) % M;
        dp[chs[i]] *= tmp;
        dp[chs[i]] %= M;
        efs(chs[i], cur, tmp);
    }
}

