    G.resize(N);
    dp.resize(N);
    REP(i, N-1){
        int x, y;
        cin >> x >> y;
        x--; y--;
        G[x].push_back(y);
        G[y].push_back(x);
    }
    dfs(0, -1);
    efs(0, -1, 1);
    for(auto x : dp)
        cout << x << endl;
    return 0;
}

