//辺edge->e : 逆辺edge->path[e.to][e.rev]
void add_edge(ll from,ll to){
    path[from].push_back((edge){to,path[to].size(),0});
    path[to].push_back((edge){from,path[from].size()-1,0});
}

void dfs(ll x,ll per,ll idx){
    rep(i,path[x].size()){
        edge &e=path[x][i];
        if(e.to!=per) dfs(e.to,x,i);
    }
    edge &E=path[per][idx];
    E.dp=1; //変更点
    for(edge &e:path[x]){
        if(e.to==per) continue; 
        E.dp=E.dp*e.dp%mod_; //変更点
    }
    E.dp++;
}

void bfs(ll x){
    queue<pair<ll,ll>> que;
    que.push(mk(x,-1));
    while(!(que.empty())){
        ll cx,par;
        tie(cx,par)=que.front();
        que.pop();
        vector<ll> mul1(path[cx].size(),1); //変更点
        vector<ll> mul2(path[cx].size(),1);
        rep(i,path[cx].size()-1){
            mul1[i+1]=(mul1[i]*path[cx][i].dp)%mod_; //変更点
            mul2[path[cx].size()-i-2]=(mul2[path[cx].size()-i-1]*path[cx][path[cx].size()-i].dp)%mod_;
        }
        rep(i,path[cx].size()){
            edge &e=path[cx][i];
            if(e.to==par) continue;
            path[e.to][e.rev].dp=(mul1[i]*mul2[i]+1)%mod_;
            que.push(mk(e.to,cx));
        }
    }
}

