int dfs2(const int u, const int p, const int i)
{
    const int n = G[u].size();
    if (i == n)
        return 1;
    int ans = 0;
    const int v = G[u][i];
    if (v != p) {
        ans += 1LL * dfs1(v,u) * dfs2(u,p,i+1) % mod;
        ans %= mod;
    }
    ans += dfs2(u,p,i+1);
    ans %= mod;
    return ans;
}

