vector<int> es[100000];

int get(int i){
    if(dp[i] > 0) return dp[i];
    if(es[e[i].to].size() == 1){
        dp[i] = 2 % m;
        return dp[i];
    }
    int64_t r = 1;
    for(int idx: es[e[i].to]){
        if(e[idx].to == e[i].from) continue;
        r = r * get(idx) % m;
    }
    dp[i] = (r + 1) % m;
    return dp[i];
}
