const ll INFL = numeric_limits<ll>::max() / 2;
const ll INF = numeric_limits<int>::max() / 2;
ll MOD;

const int N = 1e5 + 5;
ll cnt[N], ans[N];
vector<int> edge[N];
ll dp(int v, int p = -1)
{
    ll &ret = cnt[v];
    ret = 1;
    for (int u: edge[v]) {
        if (u == p) continue;
        ret = (ret * (1 + dp(u, v))) % MOD;
    }
    return ret;
}

void dfs(int v, ll pc = 0, int p = -1)
{
    /* cerr << "S: " << v << " " << pc << " " << cnt[v] << endl; */
    ans[v] = cnt[v] * (1 + pc) % MOD;

    vector<int> ch;
    for (int u: edge[v]) {
        if (u == p) continue;
        ch.push_back(u);
    }
    int n = sz(ch);
    vector<ll> pre(n), suf(n);
    for (int i = 0; i < n; i++) {
        int u = ch[i];
        pre[i] = 1 + cnt[u];
        if (i) pre[i] = (pre[i] * pre[i-1]) % MOD;
    }
    for (int i = n-1; i >= 0; i--) {
        int u = ch[i];
        suf[i] = 1 + cnt[u];
        if (i+1 < n) suf[i] = (suf[i] * suf[i+1]) % MOD;
    }
    for (int i = 0; i < n; i++) {
        int u = ch[i];
        ll left = (i) ? pre[i-1] : 1, right = (i+1 < n) ? suf[i+1] : 1;
        /* cerr << v << " " << left << " " << right << endl; */
        dfs(u, (1 + pc) * (left * right % MOD) % MOD, v);
    }
}

void solve()
{
    int n; cin >> n >> MOD;
    for (int i = 0; i < n-1; i++) {
        int x, y; cin >> x >> y;
        --x; --y;
        edge[x].push_back(y);
        edge[y].push_back(x);
    }
    dp(0);
    dfs(0);
    for (int i = 0; i < n; i++) {
        cout << ans[i] << endl;
    }
}

