lli indp[100010], outdp[100010], m, mul[100010];

void dfs1(int v, int p, vvi &adj)
{
    lli val=1;
    forr(x,adj[v])
    {
        if(x==p) continue;
        dfs1(x,v,adj);
        val*=indp[x];
    }
    indp[v]=(1+val)%m;
}

void dfs2(int v, int p, vvi &adj)
{
    lli pref[sz(adj[v])], suff[sz(adj[v])];
    pref[0]=1; suff[sz(adj[v])-1]=1;

    fol(i,1,sz(adj[v]))
    {
        if(adj[v][i-1]==p) pref[i]=pref[i-1];
        else pref[i]=(pref[i-1]*indp[adj[v][i-1]])%m;
    }
    loop(i,sz(adj[v])-2,0)
    {
        if(adj[v][i]==p) suff[i]=suff[i+1];
        else suff[i]=(suff[i+1]*indp[adj[v][i+1]])%m;
    }

    fol(i,0,sz(adj[v]))
    {
        int &x=adj[v][i];
        if(x==p) continue;
        outdp[x]=(pref[i]*suff[i])%m;
        outdp[x]=(outdp[x]*outdp[v])%m;
        outdp[x]=(outdp[x]+1)%m;
        dfs2(x,v,adj);
    }
}

