    T acc_unit, ope_unit;
    F1 acc_fun;
    F2 ope_fun;

    vector<vector<int>>& g;
    int n;
    vector<vector<T>> l, r;
    vector<T> dp, ans;
public:
    rerooting(vector<vector<int>>& _g, T unit1, F1 fun1, T unit2, F2 fun2, int start = 0)
        : g(_g), n(g.size()), l(n), r(n), dp(n), ans(n),
        acc_unit(unit1), acc_fun(fun1), ope_unit(unit2), ope_fun(fun2) {
        dfs1(start, -1), dfs2(start, ope_unit);
    }
    void dfs1(int now, int par) {
        l[now].reserve(g[now].size());
        r[now].reserve(g[now].size());
        l[now].push_back(acc_unit);
        if (par != -1)g[now].erase(find(all(g[now]), par));
        each(to, g[now]) {
            dfs1(to, now);
            l[now].push_back(ope_fun(dp[to]));
        }
        FOR(i, 2, l[now].size())r[now].push_back(l[now][i]);
        r[now].push_back(acc_unit);
        FOR(i, 1, l[now].size())l[now][i] = acc_fun(l[now][i - 1], l[now][i]);
        rFOR(i, 0, r[now].size() - 1)r[now][i] = acc_fun(r[now][i + 1], r[now][i]);
        dp[now] = l[now].back();
        l[now].pop_back();
    }
    void dfs2(int now, const T& pardp) {
        ans[now] = acc_fun(pardp, dp[now]);
        FOR(i, 0, g[now].size()) {
            dfs2(g[now][i], ope_fun(acc_fun(acc_fun(l[now][i], r[now][i]), pardp)));
        }
    }
    void print(string s) {
        FOR(i, 0, n)cout << ans[i] << (i == n - 1 ? "\n" : s);
    }
};

