ll Dfs(const int p, const int v){
    ll res = 1;
    for(int i=0; i<adj[v].size(); i++){
        if(adj[v][i] != p){
            dp[v][i] = Dfs(v,adj[v][i]);
            res *= dp[v][i]+1;
            res %= MOD;
        }
    }
    return res;
}

void Rev(const int p, const int v, const ll add){
    for(int i=0; i<adj[v].size(); i++){
        if(adj[v][i] == p){
            dp[v][i] = add;
            break;
        }
    }
    const int deg = adj[v].size();
    vector<ll> l(deg), r(deg);
    for(int i=0; i<deg; i++){
        r[i] = l[i] = (dp[v][i] + 1)%MOD;
    }
    for(int i=1; i<deg; i++){
        l[i] *= l[i-1];
        l[i] %= MOD;
    }
    for(int i=deg-2; i>=0; i--){
        r[i] *= r[i+1];
        r[i] %= MOD;
    }
    for(int i=0; i<deg; i++){
        if(adj[v][i] != p){
            ll add_c = 1;
            if(i != 0){
                add_c *= l[i-1];
                add_c %= MOD;
            }
            if(i != deg-1){
                add_c *= r[i+1];
                add_c %= MOD;
            }
            Rev(v, adj[v][i],add_c);
        }
    }
}

