			for(int j = 0; j < graph[a].size(); j++){
				if(i == j) continue;
				int next_j = graph[a][j];

				step *= 1 + path[a][next_j];
				step %= mod;
			}

			calc_lasts(next, been, a, step);

		}
	}

}


