ll query(const vl &seg, int l, int r, int a, int b, int k){
  if(r<=a || b<=l)return 1ll;
  if(l<=a && b<=r)return seg[k];
  int z = (a+b)/2;
  return query(seg,l,r,a,z,2*k+1) * query(seg,l,r,z,b,2*k+2) % m;
}

void dfs2(int p, int bef){
  ans[p] = dp[p];
