    while(N < z)N*=2;
    seg[p].assign(2*N-1,1);
    REP(i,z)seg[p][i+N-1] = chs[i];
    FORR(i,0,N-1)seg[p][i] = seg[p][2*i+1] * seg[p][2*i+2] % m;
  }
  REP(i,g[p].size()){
    int to = g[p][i];
    if(to == bef)continue;
    ll v = query(seg[p],0,i,0,N,0) * query(seg[p],i+1,z,0,N,0) % m;
