ll down[N];

void dfs(int u, int f) {
  down[u] = 1;
  for(int v : g[u]) if(v != f) {
    dfs(v, u);
    down[u] *= (down[v] + 1);
    down[u] %= M;
  }
}

int par[N];
ll pre[N], suf[N], up[N];

void dfs1(int u, int f) {
  par[u] = f;
  ll res = 1;
  for(int i = 0; i < sz(g[u]); i++) {
    if(g[u][i] == f) continue;
    pre[g[u][i]] = res;

    res *= (down[g[u][i]] + 1);
    res %= M;
  }
  res = 1;
  for(int i = sz(g[u]) - 1; i >= 0; i--) {
    if(g[u][i] == f) continue;
    suf[g[u][i]] = res;

    res *= (down[g[u][i]] + 1);
    res %= M;
  }
  for(int v : g[u]) if(v != f) dfs1(v, u);
}

void dfs2(int u, int f) {
  if(f == 0) up[u] = 1;
  else up[u] = (up[f] * (pre[u] * suf[u] % M) + 1) % M;
  for(int v : g[u]) if(v != f) dfs2(v, u);
}

