    while(ca)
      ans++,ca/=10;
    return ans;
  }

  Int operator ^(const Int &v){
    Int ans=1,a=*this,b=v;
    while(!b.isZero()){
      if(b%2)
        ans*=a;
      a*=a,b/=2;
    }
    return ans;
