ll poww(ll a, ll b, ll md) {
    return (!b ? 1 : (b & 1 ? a * poww(a * a % md, b / 2, md) % md : poww(a * a % md, b / 2, md) % md));
}

ll modd;

ll MOD(ll a){
    return ((a%modd)+modd)%modd;
}

ll inv(ll a){
    return poww(a,INF-2,INF);
}

ll dp[MAXN][2],n;
vector<int> adjList[MAXN];

void dfs(int start,int par){
    dp[start][0] = 1;
    for(auto u : adjList[start]){
        if(u != par){
            dfs(u,start);
            dp[start][0] *= (dp[u][0] + 1);
            dp[start][0] = MOD(dp[start][0]);
        }
    }
}

void dfs1(int start,int par){
    vector<ll> parr(adjList[start].size()+4),suff(adjList[start].size()+4);
    parr[0] = 1;
    for(int i=1;i<=adjList[start].size();++i){
        if(adjList[start][i-1] == par){
            parr[i] = parr[i-1];
            continue;
        }
        parr[i] = MOD(parr[i-1] * (dp[adjList[start][i-1]][0]+1)) ;
    }
    suff[adjList[start].size()+1] = 1;
    for(int i=adjList[start].size();i>=1;--i){
        if(adjList[start][i-1] == par){
            suff[i] = suff[i+1];
            continue;
        }
        suff[i] = MOD(suff[i+1] * (dp[adjList[start][i-1]][0]+1));
    }
    for(int i=1;i<=adjList[start].size();++i){
        if(adjList[start][i-1] != par){
            dp[adjList[start][i-1]][1] = MOD(1 + (MOD(MOD(parr[i-1] * suff[i+1])) * dp[start][1]));
            dfs1(adjList[start][i-1],start);
        }
    }
}

