int N;
LL MOD;
vector<int> G[100000];

map<PP, LL> memo;

LL DP(int from, int prev) {
	if (memo.count(PP(from, prev))) return memo[PP(from, prev)];
	LL ret = 1;
	for (int to : G[from]) {
		if (to == prev) continue;

		ret *= DP(to, from) + 1;
		ret %= MOD;
	}

	return memo[PP(from, prev)] = ret;
}

struct Mul {
	using Type = LL;
	static Type Identity() {
		return 1;
	}
	static Type Operate(const Type& left, const Type& right) {
		return left * right % MOD;
	}
};

void Pre(int from) {
	SegmentTree<Mul> seg(log2(4 * G[from].size() + 2));

	const int n = G[from].size();
	REP(i, 0, n) {
		int to = G[from][i];
		int ans = DP(to, from) + 1;
		seg.Update(i, ans);
		seg.Update(i + n, ans);
	}

	REP(i, 0, n) {
		int prev = G[from][i];

		memo[PP(from, prev)] = seg.Query(i + 1, i + n);
	}
}

