int n;
vector<vi> edges;
vector<ll> down, up;
vi parents;
vi leaves;

int whichp(int a, int parent) {
    return *(lower_bound(edges[a].begin(), edges[a].end(), parent));
}

ll mult(ll a, ll b) {    
    ll x = a * b;
    x %= mod;
    return x;
}

ll add(ll a, ll b) { 
    ll x = a + b;
    x %= mod;
    return x;
}

ll dfs_down(int a, int p) {

    if(down[a] != -1) return down[a];

    parents[a] = p;
    ll ans = 1;

    for(int& b : edges[a]) if(b != p) {
        ans = mult(ans, dfs_down(b, a)+1);
    }

    if(ans == 1) leaves.push_back(a);

    down[a] = ans;
    return ans;
}

void dfs_up(int a) {

    if(up[a] != -1) return;

    dfs_up(parents[a]);

    up[a] = (down[parents[a]]/(1+down[a])) * up[parents[a]] +1;
}

