void dfs(int u=0) {
	dp[u]=1;
  	for(int v : adj[u]) {
		adj[v].erase(find(adj[v].begin(), adj[v].end(), u));
    	dfs(v);
    	dp[u]=dp[u]*(dp[v]+1)%M;
  	}
  	ll curp=1, curs=1;
  	for(int i=0; i<adj[u].size(); ++i) {
    	int to=adj[u][i], rto=adj[u][adj[u].size()-i-1];
    	pre[u].push_back(curp);
