    	curp=curp*(dp[to]+1)%M;
    	curs=curs*(dp[rto]+1)%M;
  	}
  	reverse(suf[u].begin(), suf[u].end());
}

void dfs2(int u=0, int par=-1) {
  	ans[u]=dp[u];
  	for(int i=0; i<adj[u].size(); ++i) {
    	int to=adj[u][i], olds=dp[u], oldto=dp[to];
    	dp[u]=pre[u][i]*suf[u][i]%M;
    	if (par!=-1) dp[u]=dp[u]*(dp[par]+1)%M;
    	dp[to]=dp[to]*(dp[u]+1)%M;
    	dfs2(to, u);
    	dp[u]=olds;
    	dp[to]=oldto;
  	}
}

