template <class Handler>
struct ReRooting : Handler {
    using edge = typename Handler::edge; // edge data
    using dp_t = typename Handler::dp_t; // internal dp data
    using res_t = typename Handler::res_t; // res after all calc
    using Handler::unit; // () -> dp_t
    using Handler::join; // (dp_t,res_t,edge) -> dp_t
    using Handler::merge; // (dp_t,dp_t) -> res_t

    vector<vector<edge> > const* g;
    vector<res_t> dp1,dp2;
    ReRooting(vector<vector<edge> > const& g)
        : g(&g), dp1(g.size()), dp2(g.size()) {}
    vector<res_t> run() {
        dfs1(0,-1);
        dp2[0] = merge(unit(),unit()); dfs2(0,-1); // (?)
        return dp1;
    }
    void dfs1(int x, int p) {
        dp_t t = unit();
        for (auto const& e : (*g)[x]) {
            const int y = dst(e);
            if (y == p) continue;
            dfs1(y,x);
            t = join(t,dp1[y],e);
        }
        dp1[x] = merge(t,unit());
    }
    void dfs2(int x, int p) {
        auto const& es = (*g)[x];
        auto d = [&](int i) { return dst(es[i]); };
        const int m = es.size();
        {
            vector<dp_t> ldp(m+1, unit()), rdp(m+1, unit());
            for (int i = 0; i < m; i++) {
                res_t val = (d(i) == p ? dp2[x] : dp1[d(i)]);
                ldp[i+1] = join(ldp[i],val,es[i]);
            }
            for (int i = m-1; i >= 0; i--) {
                res_t val = (d(i) == p ? dp2[x] : dp1[d(i)]);
                rdp[i] = join(rdp[i+1],val,es[i]);
            }
            dp1[x] = merge(unit(), rdp[0]);
            for (int i = 0; i < m; i++) {
                if (d(i) != p) dp2[d(i)] = merge(ldp[i],rdp[i+1]);
            }
        }
        for (int i = 0; i < m; i++) if (d(i) != p) dfs2(d(i),x);
    }
};

struct Handler {
    using edge = int;
    using dp_t = mint;
    using res_t = mint;
    static dp_t unit() { return 1; }
    static dp_t join(dp_t const& x, res_t const& y, edge const&) {
        return x*(y+1);
    }
    static res_t merge(dp_t const& x, dp_t const& y) {
        return x*y;
    }
};

