void dfs(vvl &graph, ll pos, ll par = -1){
    ll ans = 1;
    for(auto &to : graph[pos]){
        if(to == par)continue;
        dfs(graph, to, pos);
        ans = ans * (sub[to] + 1) % m;
    }
    sub[pos] = ans;
}

void dfs2(vvl &graph, ll pos, ll par = -1){
    ll n = graph[pos].size();
    if(n == 0)return ;
    vector<ll> cum(n+1), cum2(n+1), num(n);
    cum[0] = 1;
    cum2[n] = 1;
    num[n-1] = 1;
    ll ans = 1;

    rep(i, n){
        ll to = graph[pos][i];
        if(to == par){
            num[i] = dp[pos];
            continue;
        }
        num[i] = sub[to] + 1;
        ans = (ans * (sub[to] + 1)) % m;
    }
    rep(i,n)cum[i+1] = (cum[i] * num[i]) % m;
    rreps(i,n)cum2[i-1] = (cum2[i] * num[i-1]) % m;
    // debug(pos);print(num);print(cum);print(cum2);
    sub[pos] = ans;
    rep(i,n){
        ll to = graph[pos][i];
        if(to == par)continue;
        dp[to] = (cum[i] * cum2[i+1] + 1) % m;
    }
    if(par == -1)dp[pos] = ans;
    else{
        for(auto &to : graph[pos]){
            if(to == par)continue;
            dp[pos] = dp[pos] * (sub[to] + 1) % m;
        }
    }
    for(auto &to : graph[pos]){
        if(to != par)dfs2(graph, to, pos);
    }
}


