{
	scanf("%d %d", &N, &mod);
	for (int i=1;i<N;i++){
		int x, y; scanf("%d %d", &x, &y);
		G[x].push_back(y);
		G[y].push_back(x);
	}

	go(1, 0);
	go2(1);

	for (int i=1;i<=N;i++) printf("%lld\n", A[i]);

	return 0;
}

