    q.push(1);
    visited[1] = true;
    while(!q.empty())
    {
        int f = q.front();
        q.pop();
        for(int u : edges[f])
            if(visited[u] == false)
            {
                parent[u] = f;
                sons[f].push_back(u);
                visited[u] = true;
                q.push(u);
            }
    }
}

ll up[N_MAX], down[N_MAX];

void computeDown ()
{
    for(int i = 1; i <= n; i++)
    {
        down[i] = 1;
        if(sons[i].empty())
        {
            q.push(i);
            visited[i] = true;
        }
    }
    while(!q.empty())
    {
        int f = q.front();
        q.pop();
        if(parent[f] == 0)
            continue;
        down[parent[f]] = down[parent[f]] * (down[f] + 1) % m;
        q.push(parent[f]);
    }
}

ll dw[N_MAX];

void computeUp ()
{
    q.push(1);
    while(!q.empty())
    {
        int f = q.front();
        q.pop();
        up[f] += 1;
        if(up[f] >= m)
            up[f] -= m;
        dw[sons[f].size()] = 1;
        for(int i = sons[f].size() - 1; i >= 0; i--)
            dw[i] = dw[i + 1] * (down[sons[f][i]] + 1) % m;
        ll dw1 = 1;
        for(int i = 0; i < sons[f].size(); i++)
        {
            int u = sons[f][i];
            up[u] = dw1 * dw[i + 1] % m * up[f] % m;
            dw1 = dw1 * (down[u] + 1) % m;
            q.push(u);
        }
    }
}

int main()
{
    cin >> n >> m;
    for(int i = 1; i < n; i++)
    {
        int u, v;
        cin >> u >> v;
        edges[u].push_back(v);
        edges[v].push_back(u);
    }
    dfs();
    computeDown();
    computeUp();
    for(int i = 1; i <= n; i++)
        cout << down[i] * up[i] % m << "\n";
    return 0;
}

