vl adj[N];

ll rec1(ll i, ll p) {
	dp[i] = 1;
	for (ll j: adj[i]) if (j != p) {
		dp[i] = dp[i] * (1 + rec1(j,i)) % MOD;
	}
	return dp[i];
}

void rec2(ll i, ll p, ll above) {
	dp[i] = dp[i] * (1 + above) % MOD;

	vl below;
	for (ll j: adj[i]) if (j != p) below.pb(1 + dp[j]);

	ll n = sz(below);
	vl pre(n+1,1), suf(n+1,1);
	FOR(i,0,n) pre[i+1] = pre[i] * below[i] % MOD;
	FORD(i,0,n) suf[i] = suf[i+1] * below[i] % MOD;

	ll k = 0;
	for (ll j: adj[i]) if (j != p) {
		ll nabove = 1 + above;
		nabove = nabove * pre[k] % MOD;
		nabove = nabove * suf[k+1] % MOD;
		rec2(j,i,nabove);
		k++;
	}
}

