long long int N, M;

struct edge{
	int to;
	long long int S;
	int rev;
};

vector<edge> E[110000];
unordered_map<long long int, long long int> m;
long long int MUL = 1e10;

long long int func(int pos, int pre, int rev){

	long long int ret = 1;
	if(pre != -1 && E[pos][rev].S != -1 && m.find(pos * MUL + E[pos][rev].S) != m.end()){
		return m[pos * MUL + E[pos][rev].S];
	}

	bool flag = true;
	for(int i = 0; i < E[pos].size(); i++){
		if(E[pos][i].S == -1){
			flag = false;
		}
		if(pre == E[pos][i].to){
			continue;
		}
		if(E[pos][i].S == -1){
			E[pos][i].S = func(E[pos][i].to, pos, E[pos][i].rev);
		}
		ret *= (E[pos][i].S + 1);
		ret %= M;
	}

	if(flag){
		m[pos * MUL + E[pos][rev].S] = ret;
	}

	return ret;
}

