	for(int i = 1; i <= N; i++){
		for(int j = 0; j < E[i].size(); j++){
			hoge[i * MUL + E[i][j].to] = j;
		}
	}

	for(int i = 1; i <= N; i++){
		for(int j = 0; j < E[i].size(); j++){
			E[i][j].rev = hoge[E[i][j].to * MUL + i];
		}
	}

	for(int i = 1; i <= N; i++){
		long long int ans = 1;
		for(int j = 0; j < E[i].size(); j++){
			if(E[i][j].S == -1){
				E[i][j].S = func(E[i][j].to, i, E[i][j].rev);
			}
			ans *= (E[i][j].S + 1);
			ans %= M;
		}
		cout << ans << endl;
	}

	return 0;
}

