vi AdjL[nax];
int vis1[nax], vis2[nax];
ll ways[nax];
ll M;

ll dfs(int u) {
    vis1[u] = 1;
    ll ans = 1;

    trav(v, AdjL[u]) {
	if (!vis1[v]) {
	    ans *= (dfs(v) + 1);
	    ans %= M;
	}
    }
    return ways[u] = ans;
}

void dfs2(int u, ll pro) {
    pro %= M;
    ways[u] *= (pro + 1);
    ways[u] %= M;

    vis2[u] = 1;
    vl pre, suff, child;
    trav(v, AdjL[u]) {
	if (!vis2[v]) 
	    child.pb(v);
    }
    ll x = 1;
    pre.pb(1);
    for (int i = 0; i < (int)child.size(); ++i) {
	x *= ways[child[i]] + 1;
	pre.pb(x);
    }
    x = 1;
    suff.pb(1);
    for (int i = (int)child.size() - 1; ~i; --i) {
	x *= ways[child[i]] + 1;
	suff.pb(x);
    }
    //~ debug(pre, suff);
    for (int i = 0; i < (int)child.size(); ++i) {
	dfs2(child[i], (pro + 1) * pre[i] * suff[child.size() - i - 1]);
    }
}

