        else {
            long long cnt = 1;
            for (long long child : tree[start])
                if (!visited[child])
                    cnt = (cnt * (dfs(child) + 1)) % m;

            dp[start] = cnt;
        }
    }

    return dp[start];
}

void solve(long long node, long long parent) {
    if (parent == -1)
        res[node] = dp[node];
    else {
        long long factor = __gcd(res[parent], dp[node] + 1);
        long long num = res[parent] / factor;
        long long den = (dp[node] + 1) / factor;

        res[node] = (((num * modinv(den, m) + 1) % m) * dp[node]) % m;
    }

    for (long long child : tree[node])
        if (child != parent)
            solve(child, node);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> m;

    tree.resize(n);
    for (i = 0; i < n - 1; ++i) {
        cin >> x >> y;
        tree[x - 1].push_back(y - 1);
        tree[y - 1].push_back(x - 1);
    }

    dp.resize(n);
    visited.resize(n);
    dfs(0);

    res.resize(n);
    solve(0, -1);

    for (i = 0; i < n; ++i) {
        if (res[i] < 0)
            cout << res[i] + m << '\n';
        else
            cout << res[i] << '\n';
    }
}

