void dfs2(int v, int p = -1)
{
    children.clear();
    for (auto u:g[v])
        if (u!=p)
            children.push_back(u);

    vector <ll> st(4*children.size());
    if (children.size())
        build(0, children.size()-1, 1, st);

    for (int i=0; i<children.size(); ++i)
    {
        int u = children[i];
        ll a = (i == 0) ? 1 : quest(0, children.size()-1, 1, 0, i-1, st);
        ll b = (i == children.size()-1) ? 1 : quest(0, children.size()-1, 1, i+1, children.size()-1, st);
        int x = up[v];
        up[u] = ((up[v] + (v!=0)) * a % mod) * b % mod;
    }
    for (auto u:g[v])
        if (u != p)
            dfs2(u, v);
}

void dfs1(int v, int p = -1)
{
    dp[v] = 1;
    for (int u:g[v])
        if (u != p)
        {
            dfs1(u, v);
            dp[v] *= dp[u]+1;
            dp[v] %= mod;
        }
}

void build(int l, int r, int idx, vector <ll>& st)
{
    if (l == r)
    {
        st[idx] = dp[children[l]] + 1;
        st[idx] %= mod;
        return;
    }

    int m = (l + r) / 2;
    build(l, m, 2*idx, st);
    build(m+1, r, 2*idx+1, st);
    st[idx] = st[2*idx] * st[2*idx + 1];
    st[idx] %= mod;
}

ll quest(int l, int r, int idx, int left, int right, vector <ll>& st)
{
    if (right < l || left > r)
        return 1;
    if (r <= right && l >= left)
        return st[idx];
    int m = (l + r) / 2;
    ll a = quest(l, m, 2*idx, left, right, st);
    ll b = quest(m+1, r, 2*idx+1, left, right, st);
    return a*b%mod;
}

