using namespace std;

void bottom_up(int node, int parent, vector<vector<long long>>& dp_left, vector<vector<long long>>& dp_right, vector<long long>& dp, int M, vector<vector<int>>& graph){
  dp[node] = 1;

  for(int next : graph[node]){
    if(next != parent){
      bottom_up(next, node, dp_left, dp_right, dp, M, graph);

      dp_left[node].push_back(dp[next] + 1);
      dp_right[node].push_back(dp[next] + 1);

      dp[node] *= dp[next] + 1;
      dp[node] %= M;
    }else{
      dp_left[node].push_back(1);
      dp_right[node].push_back(1);
    }
  }

  for(int j = 1; j < (int)dp_left[node].size(); j++){
    dp_left[node][j] *= dp_left[node][j - 1];
    dp_left[node][j] %= M;
  }

  for(int j = (int)dp_right[node].size() - 2; j >= 0; j--){
    dp_right[node][j] *= dp_right[node][j + 1];
    dp_right[node][j] %= M;
  }
}

void top_down(int node, int parent, long long pro, vector<vector<long long>>& dp_left, vector<vector<long long>>& dp_right, vector<long long>& dp, int M, vector<vector<int>>& graph){
  dp[node] *= pro;
  dp[node] %= M;

  for(int j = 0; j < (int)graph[node].size(); j++){
    int next = graph[node][j];
    if(next == parent) continue;

    long long c = 1;
    if(j - 1 >= 0) c *= dp_left[node][j - 1];
    if(j + 1 < (int)graph[node].size()) c *= dp_right[node][j + 1];

    top_down(next, node, (c % M * pro % M + 1) % M, dp_left, dp_right, dp, M, graph);
  }
}

int main(){
  int N, M;
  cin >> N >> M;

  vector<vector<int>> graph(N);
  for(int i = 0; i < N - 1; i++){
    int u, v;
    cin >> u >> v;
    --u; --v;

    graph[u].push_back(v);
    graph[v].push_back(u);
  }

  vector<vector<long long>> dp_left(N), dp_right(N);
  vector<long long> dp(N);

  bottom_up(0, -1, dp_left, dp_right, dp, M, graph);
  top_down(0, -1, 1, dp_left, dp_right, dp, M, graph);

  for(int i = 0; i < N; i++){
    cout << (dp[i] + M) % M << endl;
  }

  return 0;
}

