        G[s].push_back(t);
    }

    ll dfs(int v, int pa){
        ll res = 1;
        for(int i = 0; i < (int)G[v].size(); i++){
            if(G[v][i] == pa) continue;
            Gd[v].push_back(G[v][i]);
            res *= dfs(G[v][i], v) + 1;
            res %= MOD;
        }
        dp[v] = res;
        return res;
    }

    void dfs2(int v, int d_pa){
        ans[v] = d_pa + 1;
        int sz = Gd[v].size();
        ll lft[sz + 1], rht[sz + 1];
        lft[0] = 1;
        rht[sz] = 1;
        for(int i = 0; i < sz; i++){
            ans[v] *= dp[Gd[v][i]] + 1;
            ans[v] %= MOD;
            lft[i + 1] = (lft[i] * (dp[Gd[v][i]] + 1)) % MOD;
            rht[sz - 1 - i] = (rht[sz - i] * (dp[Gd[v][sz - 1 - i]] + 1)) % MOD;
        }

        //debug
