        for(int i = 0; i <= sz; i++){
            cout << "rht" << i << " = " << rht[i] << endl;
        }
        */

        for(int i = 0; i < sz; i++){
            dfs2(Gd[v][i], ((lft[i] * rht[i + 1] * (d_pa + 1)) % MOD));
        }
    }
};

