    for(int i=0;i<n-1;i++) {
        cin>>u>>v;
        g[u].pb(v);
        g[v].pb(u);
    }
    firstdfs(1, -1);

    seconddfs(1, -1);

    for(int i=1;i<=n;i++) {
        cout<<dp[i]<<"\n";
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

const int mxN = 1e5 + 5;
vector<int> adj[mxN], tree[mxN];
vector<ll> pref[mxN], suf[mxN];
ll up[mxN], down[mxN];
int parent[mxN], N, M;

void dfs(int node, int par) {
	parent[node] = par;
	for (auto it : adj[node]) {
		int next = it;
		if (next != par) {
			tree[node].push_back(next);
			dfs(next, node);
		}
	}
	return;
}

void solve_down(int node) {
	int size = tree[node].size();
	pref[node].resize(size);
	suf[node].resize(size);
	down[node] = 1;
	for (auto it : tree[node]) {
		int next = it;
		solve_down(it);
		down[node] = (down[node] * (1 + down[next])) % M;
	}
	for (int i = 0; i < size; i++) {
		int child = tree[node][i];
		pref[node][i] = 1 + down[child];
		if (i >= 1) {
			pref[node][i] = (pref[node][i] * pref[node][i - 1]) % M;
		}
	}
	for (int i = size - 1; i >= 0; i--) {
		int child = tree[node][i];
		suf[node][i] = 1 + down[child];
		if (i < size - 1) {
			suf[node][i] = (suf[node][i] * suf[node][i + 1]) % M;
		}
	}
	return;
}

void solve_up(int node) {
	if (node == 1) {
		up[node] = 1;
	}
	int size = tree[node].size();
	for (int i = 0; i < size; i++) {
		int par = tree[node][i];
		up[par] = up[node];
		if (i > 0) {
			up[par] = (up[par] * pref[node][i - 1]) % M;
		}
		if (i < size - 1) {
			up[par] = (up[par] * suf[node][i + 1]) % M;
		}
		up[par]++;
		up[par] = up[par] % M;
		solve_up(par);
	}
	return;
}

int main() {
	ios_base::sync_with_stdio(false);

	cin >> N >> M;
	int x, y;
	for (int i = 0; i < N - 1; i++) {
		cin >> x >> y;
		adj[x].push_back(y);
		adj[y].push_back(x);
	}
	dfs(1, 0);
	solve_down(1);
	solve_up(1);
	for (int i = 1; i <= N; i++) {
		ll answer = (up[i] * down[i]) % M;
		cout << answer << '\n';
	}

	return 0;
}

