const int N = 100005;
int MOD;
vi adj[N];
ll ways[N];
ll realways[N];
vl prefix[N];
vl sufix[N];
void reroot(int u, int parent) {
	realways[u] = ways[u];
	int nn = adj[u].size();
	for(int i = 0; i < adj[u].size(); i++) {
		int v = adj[u][i];
		if(v == parent)continue;
		ll waysu = ways[u];
		ll waysv = ways[v];
		ways[u] = (prefix[u][i] * sufix[u][nn - 1 - i]) % MOD;
		if(parent != -1)ways[u] = (ways[u] * (ways[parent] + 1)) % MOD;
	//	cout << i << " " << ways[u] << " " << waysu << " " << ways[v] << "uwu \n";
		ways[v] = (ways[v] * (ways[u] + 1)) % MOD;
		reroot(v, u);
		ways[u] = waysu;
		ways[v] = waysv;
	}
}
void dfs(int u, int parent) {
	ways[u] = 1;
	for(auto v : adj[u]) {
		if(v == parent)continue;
		dfs(v, u);
		ways[u] = (ways[u] * (1 + ways[v])) % MOD;
	}
	ll act = 1;
	for(int i = 0; i < adj[u].size(); i++) {
		int v = adj[u][i];
		prefix[u].pb(act);
		if(adj[u][i] == parent)continue;
		act = (act * (ways[v] + 1)) % MOD;
	}
	prefix[u].pb(act);
	act = 1;
	for(int i = adj[u].size() - 1; i >= 0; i--) {
		int v = adj[u][i];
		sufix[u].pb(act);
		if(adj[u][i] == parent)continue;
		act = (act * (ways[v] + 1)) % MOD;
	}
	sufix[u].pb(act);
}
