int N;
ll M;
vec<int, 2> G;

vec<ll, 3> dp;

ll func(int v, int p, int c) {
  int k = 0;
  for (int i = 0; i < G[v].size(); i++)
    if (G[v][i] == p) k = i + 1;
  ll& res = dp[v][k][c];
  if (res != -1) return res;
  res = 1;
  for (int u : G[v]) {
    if (u == p) continue;
    ll sum = 0;
    for (int nc = 0; nc <= (c ? 1 : 0); nc++) {
      sum += func(u, v, nc);
      sum %= M;
    }
    res = res * sum % M;
  }
  return res;
}

ll solve(int v) {
  return func(v, -1, 1);
}

