#define pb push_back
using namespace std;

const int MAXN = (int)1e5 + 5;

int mod;
vector<int> g[MAXN];
vector<int> tree[MAXN];
int p[MAXN];

vector<long long> pref[MAXN];
vector<long long> suf[MAXN];
long long down[MAXN];
long long up[MAXN];

void DFS(int node, int par = 0) {
    p[node] = par;

    for (int i = 0; i < (int)g[node].size(); i++) {
        int viz = g[node][i];
        if (viz != par) {
            tree[node].pb(viz);
            DFS(viz, node);
        }
    }
    return;
}

void solve_down(int node) {
    int sz = tree[node].size();
    pref[node].resize(sz);
    suf[node].resize(sz);

    down[node] = 1;
    for (int i = 0; i < sz; i++) {
        int viz = tree[node][i];
        solve_down(viz);
        down[node] = (down[node] * (1 + down[viz])) % mod;
    }

    for (int i = 0; i < sz; i++) {
        int viz = tree[node][i];
        pref[node][i] = 1 + down[viz];
        if (i != 0) {
            pref[node][i] *= pref[node][i - 1];
            pref[node][i] %= mod;
        }
    }
    for (int i = sz - 1; i >= 0; i--) {
        int viz = tree[node][i];
        suf[node][i] = 1 + down[viz];
        if (i != sz - 1) {
            suf[node][i] *= suf[node][i + 1];
            suf[node][i] %= mod;
        }
    }
    return;
}

void solve_up(int node) {
    if (node == 1) up[node] = 1;

    int sz = tree[node].size();
    for (int i = 0; i < sz; i++) {
        int viz = tree[node][i];
        up[viz] = up[node];
        if (i != 0) up[viz] = (up[viz] * pref[node][i - 1]) % mod;
        if (i != sz - 1) up[viz] = (up[viz] * suf[node][i + 1]) % mod;

        up[viz] = (up[viz] + 1) % mod;
        solve_up(viz);
    }
    return;
}

int main(void) {
    int n;
    int x, y;

    scanf(" %d %d", &n, &mod);
    for (int i = 1; i < n; i++) {
        scanf(" %d %d", &x, &y);
        g[x].pb(y);
        g[y].pb(x);
    }

    DFS(1);
    solve_down(1);
    solve_up(1);

    for (int i = 1; i <= n; i++) {
        printf("%lld\n", (down[i] * up[i]) % mod);
    }

    return 0;
}

