ll phi (ll k)
{
    ll cur = k;
    vector < ll > primes;
    if (k%2 == 0)
    {
        primes.pb(2);
        while (k%2 == 0)
        {
            k /= 2;
        }
    }
    for (ll i = 3; i < k; i+=2)
    {
        if (k%i == 0)
        {
            primes.pb(i);
            while (k%i == 0)
            {
                 k /= i;
            }
        }
    }
    if (primes.sz == 0)
        return (cur-1);
    else
    {
        ll ans = cur;
        for (ll i:primes)
        {
            ans *= ((i-1)/i);
        }
        return ans;
    }
}
