ll N, dp2[100010], par[100010];
pair<ll, ll> dp[100010];
vector<ll> adj[100010];

void f(ll u, ll p) {
    dp[u] = {1,1};
    for (ll v:adj[u]) {
        if (v != p) {
            f(v, u);
            dp[u].first = (dp[u].first*add(dp[v].first, dp[v].second))%MOD;
            dp[u].second = (dp[u].second*dp[v].second)%MOD;
        }
    }
}

void process(ll u, ll p, ll curr) {
    dp[u].first = (dp[u].first*curr)%MOD;
    ll currprod = 1;
    vector<ll> pprod, sprod(adj[u].size());
    for (ll v: adj[u]) {
        if (v == p) {
            currprod=(currprod*curr)%MOD;
            pprod.push_back(currprod);
            continue;
        }
        currprod=currprod*add(1, dp[v].first)%MOD;
        pprod.push_back(currprod);
    }
    currprod = 1;
    for (ll i = adj[u].size()-1; i>=0; i--) {
        if (adj[u][i] == p) {
            currprod = (currprod*curr)%MOD;
            sprod[i] = currprod;
            continue;
        }
        currprod=currprod*add(1, dp[adj[u][i]].first)%MOD;
        sprod[i] = currprod;
    }
    for (int i = 0; i<adj[u].size(); i++) {
        if (adj[u][i] == p) {
            continue;
        }
        ll v = adj[u][i];
        ll L, R;
        if (i == 0) {
            L = 1;
        } else {
            L = pprod[i-1];
        }
        if (i == adj[u].size()-1) {
            R = 1;
        } else {
            R = sprod[i+1];
        }
        process(v, u, add(1, (L*R)%MOD));
    }
}

