int ans[100001];
int calc(int u, int p, int subs){
//  cout << u << ' ' << subs << endl;
  bool cc = 0;
  vector<int> chres;
  for(auto el : adj[u]){
    if(el != p){

      chres.push_back(dp[el] + 1);
      cc = 1;
    }
  }
  ans[u] = 1ll * (1 + subs) * dp[u] % m;
  if(!cc)
    return 0;
  vector<int> lsum(chres);
  vector<int> rsum(chres);
  for(int i = 1;i < lsum.size();i++){
    lsum[i] = (1ll * lsum[i] * lsum[i - 1]) % m;
  }
  for(int i = (int)rsum.size() - 2;i >= 0;i--){
    rsum[i] = (1ll * rsum[i] * rsum[i + 1]) % m;
  }
  int pp = 0;
  for(int i = 0;i < adj[u].size();i++){
    if(adj[u][i] == p){
      pp = 1;
      continue;
    }
    calc(adj[u][i], u, 1ll * (subs + 1) * (i - pp - 1 >= 0 ? lsum[i - pp - 1] : 1) % m * (i - pp + 1 < rsum.size() ? rsum[i - pp + 1] : 1) % m);
  }

}
void dfs(int u, int p = -1){
  dp[u] = 1;
  for(auto el : adj[u]){
    if(el == p)continue;
    dfs(el, u);
    dp[u] = 1ll * (1 + dp[el]) * dp[u] % m;
  }
}
