	cin >> n >> m;
	for (int i = 0; i < n - 1; i++) {
		int a, b;
		cin >> a >> b;
		a--;
		b--;
		t[b].push_back(a);
		t[a].push_back(b);
	}
	rec(0, -1);
	solve(0, -1, 1);
	for (int i = 0; i < n; i++) {
		printf("%lld\n", ans[i]);
	}
	return 0;
}

#include <bits/stdc++.h>
using namespace std;
#define ll long long
#define ld long double

int N;
ll M;
vector<vector<int>> edge;
vector<ll> dp, dp_rev;
vector<vector<ll>> dp_l, dp_r;

void dfs(int now, int par) {
    for (int nxt : edge[now]) {
        if (nxt == par) continue;
        dfs(nxt, now);
        dp[now] *= (dp[nxt]+1);
        dp[now] %= M;
    }
    int K = edge[now].size();
    if (K == 0) return;

    dp_l[now].resize(K, 1);
    if (edge[now][0] != par) dp_l[now][0] = dp[edge[now][0]]+1;
    for (int i = 1; i < K; i++) {
        dp_l[now][i] = dp_l[now][i-1];
        if (edge[now][i] != par) dp_l[now][i] = dp_l[now][i] * (dp[edge[now][i]]+1) % M;
    }

    dp_r[now].resize(K, 1);
    if (edge[now][K-1] != par) dp_r[now][K-1] = dp[edge[now][K-1]]+1;
    for (int i = K-2; i >= 0; i--) {
        dp_r[now][i] = dp_r[now][i+1];
        if (edge[now][i] != par) dp_r[now][i] = dp_r[now][i] * (dp[edge[now][i]]+1) % M;
    }
    return;
}

void dfs_rev(int now, int par) {
    int K = edge[now].size();
    for (int i = 0; i < K; i++) {
        int nxt = edge[now][i];
        if (nxt == par) continue;
        dp_rev[nxt] = dp_rev[now];
        if (i >= 1) {
            dp_rev[nxt] *= dp_l[now][i-1];
            dp_rev[nxt] %= M;
        }

        if (i <= K-2) {
            dp_rev[nxt] *= dp_r[now][i+1];
            dp_rev[nxt] %= M;
        }
        dp_rev[nxt]++;
        dfs_rev(nxt, now);
    }
    return;
}

int main() {
    scanf("%d %lld", &N, &M);
    edge.resize(N);
    dp.resize(N, 1);
    dp_rev.resize(N, 1);
    dp_l.resize(N);
    dp_r.resize(N);
    for (int i = 0; i < N-1; i++) {
        int x, y;
        scanf("%d %d", &x, &y);
        x--;y--;
        edge[x].push_back(y);
        edge[y].push_back(x);
    }

    dfs(0, -1);
    dfs_rev(0, -1);
    for (int i = 0; i < N; i++) {
        printf("%lld\n", dp[i]*dp_rev[i]%M);
    }
    return 0;
}

