vector<int> G[100005];
int dp[100005], MOD, ans[100005], father[100005];

void f(int v, int p) {
	dp[v] = 1;

	for(int u : G[v]) {
		if(u == p) continue;
		f(u, v);
		dp[v] = 1LL*dp[v]*(1+dp[u])%MOD;
	}
}

void g(int v, int p) {
	vector<int> pre, suf;
	int cur = 1;
	for(int u : G[v]) {
		if(u == p) {
			pre.push_back(cur);
			continue;
		}
		cur = 1LL*cur*(1+dp[u])%MOD;
		pre.push_back(cur);
	}

	cur = 1;
	for(int i = (int)G[v].size()-1; i >= 0; i--) {
		int u = G[v][i];
		if(u == p) {
			suf.push_back(cur);
			continue;
		}
		cur = 1LL*cur*(1+dp[u])%MOD;
		suf.push_back(cur);
	}
	reverse(suf.begin(), suf.end());

	for(int i = 0; i < G[v].size(); i++) {
		int u = G[v][i];
		if(u == p) continue;
		father[v] = v == 1 ? 1 : 1+father[p];

		if(i) father[v] = 1LL*father[v]*pre[i-1]%MOD;
		if(i < (int)G[v].size()-1) father[v] = 1LL*father[v]*suf[i+1]%MOD;

		ans[u] = 1LL*dp[u]*(1+father[v])%MOD;
		g(u, v);
	}
}

