ll dfs1(const vector<vector<int>>& graph, vector<bool>& visited, vector<ll>& dp, ll mod, int node) {
    visited[node] = true;
    ll res = 1;
    rep(i, 0, graph[node].size()) {
        if (visited[graph[node][i]]) {
            continue;
        }
        ll child_val = dfs1(graph, visited, dp, mod, graph[node][i]) + 1;
        res *= child_val % mod ? child_val % mod : mod;
    }
    return dp[node] = res;
}

void dfs2(const vector<vector<int>>& graph, vector<bool>& visited, const vector<ll>& dp1, vector<ll>& dp2,  ll mod, int parent, ll ans) {
    visited[parent] = true;
    dp2[parent] = ans;
    rep(i, 0, graph[parent].size()) {
        int node = graph[parent][i];
        if (visited[node]) {
            continue;
        }
        ll parent_val = (dp2[parent] / ((dp1[node] + 1) % mod ? (dp1[node] + 1) % mod : mod) + 1) % mod;
        dfs2(graph, visited, dp1, dp2, mod, node, dp1[node] * parent_val);
    }
}

