			p = merge(p, downs[u][i]);
			pre[u].push_back(p);
		}
		p = {1, 0};
		for (int i = children[u].size() - 1; i >= 0; --i) {
			p = merge(p, downs[u][i]);
			su[u].push_back(p);
		}
		reverse(su[u].begin(), su[u].end());
	}

	dfs2(1, -1);

	for (int u = 1; u <= N; ++u) {
