#define REP(i,n)   for(int i=0; i<(int)(n); i++)
#define FOR(i,b,e) for(int i=(b); i<=(int)(e); i++)
#define DUMP(a, n) REP(i, n) printf("%lld%c", a[i], i + 1 == n ? '\n' : ' ')
#define DUMP2D(a, n, m) REP(i, n) REP(j, m) printf("%d%c", a[i][j], j + 1 == m ? '\n' : ' '); puts("")

const int N_MAX = 1e5;
const int M_MAX = 1e9;

int N, M;

//------------------------------------------------------------------------------
const int V_MAX = N_MAX;

int V;
vector<int> G[V_MAX];

void add_edge(int from, int to) {
  G[from].push_back(to);
  G[to].push_back(from);
}

//------------------------------------------------------------------------------
#define LF(i)   (n - 1 + i)
#define PA(k)   ((k - 1) / 2)
#define LC(k)   (k * 2 + 1)
#define RC(k)   (k * 2 + 2)
#define M(l,r)  ((l + r) / 2)

template<typename T> class SegTree {
public:
  int n;
  int sz;
  T def;
  vector<T> dat;

  void init(int _n, T _def) {
    n = 1; while (n < _n) n <<= 1;
    sz = n * 2 - 1;
    def = _def;
    dat.resize(sz, def);
  }

  void update(int i, T x) {
    int k = LF(i);
    dat[k] = x;
    while (k > 0) {
      k = PA(k);
      dat[k] = dat[LC(k)] * dat[RC(k)] % M;
    }
  }

  T query(int a, int b, int k, int l, int r) {
    if (r <= a || b <= l) return def;
    if (a <= l && r <= b) return dat[k];
    T vl = query(a, b, LC(k), l, M(l, r));
    T vr = query(a, b, RC(k), M(l, r), r);
    return vl * vr % M;
  }

  T query(int a, int b) {
    if (a >= b) return def;
    return query(a, b, 0, 0, n);
  }

  T except(int i) {
    return query(0, i) * query(i + 1, n) % M;
  }

  void dump() {
    REP(i, sz) printf("%d%c", dat[i], i + 1 == sz ? '\n' : ' ');
  }
};

//------------------------------------------------------------------------------
SegTree<ll> dp[V_MAX];
int pi[V_MAX];

void dfs(int p, int v) {
  dp[v].init(G[v].size(), 1);
  REP(i, G[v].size()) {
    int u = G[v][i];
    if (u == p) {
      pi[v] = i;
      continue;
    }
    dfs(v, u);
    dp[v].update(i, (dp[u].dat[0] + 1) % M);
  }
}

void dfs2(int p, int v, int vi) {
  if (p >= 0) dp[v].update(pi[v], (dp[p].except(vi) + 1) % M);
  REP(i, G[v].size()) {
    int u = G[v][i];
    if (u == p) continue;
    dfs2(v, u, i);
  }
}

void solve() {
  dfs(-1, 0);
  dfs2(-1, 0, -1);
  REP(v, V) printf("%lld\n", dp[v].dat[0]);
}

void input() {
  scanf("%d%d", &N, &M);
  V = N;
  REP(i, N - 1) {
    int x, y;
    scanf("%d%d", &x, &y);
    add_edge(x - 1, y - 1);
  }
}

int main() {
  input();
  solve();
  return 0;
}

