void build(int a, int idx,int l,int r) {
	if(l == r){
		ST[idx] = (dp[vec[a][l]] + 1) % MOD;
		return ;
	}
	int mid = (l + r) / 2;
	build(a,2 * idx, l, mid), build(a,2 * idx + 1,mid + 1,r);
	ST[idx] = ST[2 * idx] * ST[2 * idx + 1] % MOD;
}

LL query(int idx,int l,int r,int tar) {
	if(r < tar || l > tar) return ST[idx];
	if(l == tar && r == tar) return 1;
	int mid = (l + r) / 2;
	return query(2 * idx,l,mid,tar) * query(2 * idx + 1,mid + 1,r,tar) % MOD;
}

