using namespace std;
using ll = long long;

ll dfs1(const vector<vector<int>>& graph, vector<bool>& visited, vector<ll>& dp, ll m, int node) {
    visited[node] = true;
    ll res = 1;
    rep(i, 0, graph[node].size()) {
        if (visited[graph[node][i]]) {
            continue;
        }
        ll child_val = dfs1(graph, visited, dp, m, graph[node][i]) + 1;
        res *= (child_val % m ? child_val % m : m);
    }
    return dp[node] = res;
}

void dfs2(const vector<vector<int>>& graph, vector<bool>& visited, const vector<ll>& dp1, vector<ll>& dp2,  ll m, int parent, ll ans) {
    visited[parent] = true;
    dp2[parent] = ans;
    rep(i, 0, graph[parent].size()) {
        int node = graph[parent][i];
        if (visited[node]) {
            continue;
        }
        ll child_val = dp1[node] + 1;
        ll parent_val = dp2[parent] / (child_val % m ? child_val % m : m) + 1;
        dfs2(graph, visited, dp1, dp2, m, node, dp1[node] * (parent_val % m));
    }
}

