using u32 = uint32_t;
template<class MC, class CU, class MA>
struct Rerooting {
	MC merge_child;
	CU child_unity;
	MA merge_all;
	vector<CU> dp, dp_reroot;
	Rerooting(MC mc, CU cu, MA ma) : merge_child(mc), child_unity(cu), merge_all(ma) {}
	template<class graph>
	void build(const graph& g, u32 root = 0) {
		dp.resize(g.size(), child_unity);
		dp_reroot.resize(g.size(), child_unity);

		auto dfs = [&](auto&& f, u32 v, u32 parent = -1) -> CU {
			for (auto& e : g.e[v]) {
				if (e.to == parent) continue;
				dp[v] = merge_child(dp[v], f(f, e.to, v));
			}
			return dp[v] = merge_all(dp[v], v);
		};
		dfs(dfs, root);
		auto dfs_reroot = [&](auto&& f, u32 v, CU parent_data, u32 parent = -1) -> void {
			vector<CU> left_accum(g.e[v].size()+1, child_unity);
			vector<CU> right_accum(g.e[v].size()+1, child_unity);
			{
				u32 i = 0;
				for (auto& e : g.e[v]) {
					i++;
					left_accum[i] = right_accum[i-1] = (e.to == parent ? parent_data : dp[e.to]);
				}
			}
			for (u32 i = 1; i < left_accum.size(); i++) left_accum[i] = merge_child(left_accum[i-1], left_accum[i]);
			for (u32 i = right_accum.size() - 1; 0 < i; i--) right_accum[i-1] = merge_child(right_accum[i-1], right_accum[i]);
			dp_reroot[v] = merge_all(left_accum.back(), v);
			{
				u32 i = 0;
				for (auto& e : g.e[v]) {
					i++;
					if (e.to == parent) continue;
					f(f, e.to, merge_all(merge_child(left_accum[i-1], right_accum[i]), v), v);
				}
			}
		};
		dfs_reroot(dfs_reroot, root, child_unity);
	}
};

template<class MC, class CU, class MA>
Rerooting<MC, CU, MA> make_rerooting(MC mc, CU cu, MA ma) {
	return Rerooting<MC, CU, MA>(mc, cu, ma);
}

