ll m, d[MAXN], u[MAXN];
vector<ll> g[MAXN], pre[MAXN], suf[MAXN];

void dfs1(int x, int p){
	d[x] = 1;
	//cout << x;
	if(p != -1)
		g[x].erase(lower_bound(g[x].begin(), g[x].end(), p));
	for(auto i : g[x]){
		if(i == p) continue;
		dfs1(i, x);
		d[x] *= d[i] + 1;
		d[x] %= m;
	}
	int t = g[x].size();
	pre[x].resize(t + 5, 1);
	suf[x].resize(t + 5, 1);
	pre[x][0] = suf[x][t + 1] = 1;
	for(int i = 0; i < t; i++){
		pre[x][i + 1] = pre[x][i] * (d[g[x][i]] + 1);
		pre[x][i + 1] %= m;
	}
	for(int i = t - 1; i >= 0; i--){
		suf[x][i] = suf[x][i + 1];
		if(i < t - 1) suf[x][i] *= (d[g[x][i + 1]] + 1);
		suf[x][i] %= m;
	}
}
void dfs2(int x, int p){
	u[x] = 1;
	if(p != -1){
		u[x] *= u[p];
		u[x] %= m;
		int t = lower_bound(g[p].begin(), g[p].end(), x) - g[p].begin();
		u[x] *= pre[p][t];
		u[x] %= m;
		u[x] *= suf[p][t];
		u[x]++;
		u[x] %= m;
		//cout << x << " " << pre[p][t] << " " << suf[p][t] << endl;
	}
	for(auto i : g[x]){
		if(i == p) continue;
		dfs2(i, x);
	}
}

