ll evaluate(int F, int B) {
	if (dp[F][B] != -1)return dp[F][B];

	ll res = 1;
	for (int node : adjusts[B]) {
		if (node == F)continue;
		(res *= evaluate(B, node)) %= M;
	}
	return dp[F][B] = (res + 1) % M;
}

