const int MAXN = 1E5 + 100;
int MOD, N, dp[MAXN], dp2[MAXN], up[MAXN];
vvi adj(MAXN);

void DFS(int u = 0, int p = -1) {
	dp[u] = 1;
	for(int v : adj[u]) {
		if(v == p)
			continue;
		DFS(v, u);
		dp[u] = (dp[u]*(dp[v] + 1))%MOD;
	}
}

ll pow(ll x, ll y) {
	if(y == 0)
	return 1;
	ll temp = pow(x, y/2);
	temp = (temp*temp)%MOD;
	if(y%2 == 1)
		temp *= x;
	return temp%MOD;
}

int egcd(int a, int b, int &x, int &y) {
	if(b == 0) {
		x = 1, y = 0;
		return a;
	}
	int g = egcd(b, a%b, x, y);
	int tmp = x;
	x = y;
	y = tmp - y*(a/b);
	return g;
}

void reroot(int u = 0, int p = -1) {
	vi children;
	for(int i = 0; i < sz(adj[u]); i++) {
		if(adj[u][i] == p)
			continue;
		children.pb(adj[u][i]); 
	}
	int pref[sz(children) + 1], suff[sz(children) + 1];
	pref[0] = suff[sz(children)] = 1;
	for(int i = 0; i < sz(children); i++) {
		pref[i + 1] = (pref[i]*(dp[children[i]] + 1))%MOD;
		//error(i, pref[i + 1]);
	}
	for(int i = sz(children) - 1; i >= 0; i--) {
		suff[i] = ((dp[children[i]] + 1)*suff[i + 1])%MOD;
		//error(i, suff[i]);
	}
	for(int i = 0; i < sz(children); i++)
		up[children[i]] = (1 + ((up[u]*pref[i])%MOD)*suff[i + 1])%MOD;
	for(int i = 0; i < sz(children); i++) {
		int v = children[i];
		int tmp = (pref[i]*suff[i + 1])%MOD;
		if(v == p)
			continue;
		dp2[v] = (tmp*dp[v])%MOD;
		dp2[v] = (dp2[v]*up[u])%MOD;
		dp2[v] = (dp2[v] + dp[v])%MOD;
		//error(u, up[u], up[v]);
		reroot(v, u);
	}
}

