int add(int a, int b)
{
	a = (a + mod) % mod;
	b = (b + mod) % mod;
	return (a + b) % mod;
}

int mul(int a, int b)
{
	a = (a + mod) % mod;
	b = (b + mod) % mod;
	return (1ll * a * b) % mod;
}

void dfs(int node, int parent)
{
	pre[node].resize(g[node].size());
	suf[node].resize(g[node].size());
	int cur = 1;
	for(int i = 0; i < g[node].size(); i++)
	{
		int child = g[node][i];
		if(child != parent)
		{
			dfs(child, node);
			cur = mul(cur, dp[child]);
		}
		pre[node][i] = cur;
	}
	cur = 1;
	for(int i = g[node].size() - 1; i >= 0; i--)
	{
		int child = g[node][i];
		if(child != parent)
		{
			cur = mul(cur, dp[child]);
		}
		suf[node][i] = cur;
	}
	dp[node] = add(cur, 1);
}

//dp[child] = (dp[child] - 1) * val_parent + 1

void dfs2(int node, int parent, int val_parent)
{
	dp[node] = add(mul(add(dp[node], -1), val_parent), 1);
	sol[node] = dp[node];
	for(int i = 0; i < g[node].size(); i++)
	{
		int child = g[node][i];
		if(child != parent)
		{
			int p = 1, s = 1;
			if(i)
				p = pre[node][i - 1];
			if(i + 1 < g[node].size())
				s = suf[node][i + 1];
			dfs2(child, node, add(mul(mul(p, s), val_parent), 1));
		}
	}
}

