template <typename X, typename M>
struct SegTreeLazyProportional {
    using FX = function<X(X, X)>;
    using FA = function<X(X, M)>;
    using FM = function<M(M, M)>;
    using FP = function<M(M, int)>;
private:
    int n;
    FX query_Value_;
    FA merge_data_and_lazy_;
    //遅延評価するときに子に伝番させる方法
    FM updateLazy_;
    //遅延評価値と長さから何をするか決める
    FP evaluateLazyLength_;
    //無効値
    const X defaultData_;
    vector<X> data_;
    //無効値
    const M defaultLazy_;
    vector<M> lazy_;
public:
    SegTreeLazyProportional(int n_, FX query_value, FA merge_data_and_lazy, FM updateLazy, FP evaluateLazyLength, X defaultData, M defaultLazy)
        : n(), query_Value_(query_value), merge_data_and_lazy_(merge_data_and_lazy),
        updateLazy_(updateLazy),
        evaluateLazyLength_(evaluateLazyLength),
        defaultData_(defaultData),
        defaultLazy_(defaultLazy),
        data_(n_ * 4, defaultData_), lazy_(n_ * 4, defaultLazy_) {
        int x = 1;
        while (n_ > x) x *= 2;
        n = x;
    }

    void set(int i, X x) { data_[i + n - 1] = x; }
    void build() {
        for (int k = n - 2; k >= 0; k--) data_[k] = query_Value_(data_[2 * k + 1], data_[2 * k + 2]);
    }
    //[a,b)
    void update(int a, int b, M x) { update(a, b, x, 0, 0, n); }
    //[a,b)
    X query(int a, int b) { return query_sub(a, b, 0, 0, n); }

private:
    void eval(int k, int len) {
        if (lazy_[k] == defaultLazy_) return;  // 更新するものが無ければ終了
        if (k < n - 1) {            // 葉でなければ子に伝搬
            lazy_[k * 2 + 1] = updateLazy_(lazy_[k * 2 + 1], lazy_[k]);
            lazy_[k * 2 + 2] = updateLazy_(lazy_[k * 2 + 2], lazy_[k]);
        }
        // 自身を更新
        data_[k] = merge_data_and_lazy_(data_[k], evaluateLazyLength_(lazy_[k], len));
        lazy_[k] = defaultLazy_;
    }

    void update(int a, int b, M x, int k, int l, int r) {
        eval(k, r - l);
        if (a <= l && r <= b) {  // 完全に内側の時
            lazy_[k] = updateLazy_(lazy_[k], x);
            eval(k, r - l);
        }
        else if (a < r && l < b) {                     // 一部区間が被る時
            update(a, b, x, k * 2 + 1, l, (l + r) / 2);  // 左の子
            update(a, b, x, k * 2 + 2, (l + r) / 2, r);  // 右の子
            data_[k] = query_Value_(data_[k * 2 + 1], data_[k * 2 + 2]);
        }
    }

    X query_sub(int a, int b, int k, int l, int r) {
        eval(k, r - l);
        if (r <= a || b <= l) {  // 完全に外側の時
            return defaultData_;
        }
        else if (a <= l && r <= b) {  // 完全に内側の時
            return data_[k];
        }
        else {  // 一部区間が被る時
            X vl = query_sub(a, b, k * 2 + 1, l, (l + r) / 2);
            X vr = query_sub(a, b, k * 2 + 2, (l + r) / 2, r);
            return query_Value_(vl, vr);
        }
    }
};

SegTreeLazyProportional<ll, ll> RangeMul(int n, ll m) {
    auto queryValue = [=](ll left, ll right) -> ll { return left * right % m; };
    auto updateValue = [=](ll old, ll next) -> ll { return next % m; };
    auto merge = [=](ll source, ll lazyValue) -> ll { return source * lazyValue; };
    auto evaluate_lazy_length = [=](ll lazyValue, ll length) -> ll { return lazyValue * length; };
    ll defaultValue_ = 1;
    SegTreeLazyProportional<ll, ll> rmq(n, queryValue, merge, updateValue, evaluate_lazy_length, defaultValue_, defaultValue_);
    return rmq;
}


void publish_core(int current, int from, ll fromCount) {
    roots[current][from] = fromCount;

    auto tree = RangeMul(g[current].size(), m);
    for (int i = 0; i < g[current].size(); i++) {
        int to = g[current][i];
        tree.set(i, roots[current][to]);
    }
    tree.build();
    for (int i = 0; i < g[current].size(); i++) {
        if (g[current][i] == from) continue;
        ll v = 1;
        if (i > 0) {
            v *= tree.query(0, i);
            v %= m;
        }
        if (i < n - 1) {
            v *= tree.query(i + 1, n - 1);
            v %= m;
        }
        publish_core(g[current][i], current, v + 1);
    }
}


void publish(int current) {
	//子要素に計算結果を伝達する
	//各子要素に自身以外の結果を使った時の組み合わせ数を伝える
    auto tree = RangeMul(g[current].size(), m);
    for (int i = 0; i < g[current].size(); i++) {
        int to = g[current][i];
        tree.set(i, roots[current][to]);
    }
    tree.build();
    for (int i = 0; i < g[current].size(); i++) {
        ll v = 1;
        if (i > 0) {
            v *= tree.query(0, i);
            v %= m;
        }
        if (i < n-1) {
            v *= tree.query(i+1, n-1);
            v %= m;
        }
        publish_core(g[current][i], current, v + 1);
    }

}

ll dfs(int current, int from) {
	if (dp[current].count(from)) {
		return dp[current][from];
	}
	ll v = 1;
	for (auto to : g[current]) {
		if (to == from) continue;
		ll d = dfs(to, current);
		roots[current][to] = d;
		v *= d;
		v %= m;
	}
	if (from != -1) {
		v++;
	}
	dp[current][from] = v % m;
	return dp[current][from];
}

ll dfs2(int current) {
    ll v = 1;
    for (auto to : g[current]) {
        ll d = dfs(to, current);
        roots[current][to] = d;
        v *= d;
        v %= m;
    }
    return v % m;
}

