void dfs1(int i, int p) {
    dp[i] = 1;
    for(int e : G[i]) {
        if(e != p) {
            dfs1(e, i);
            x[i].push_back((dp[e] + 1) % m);
            dp[i] *= dp[e] + 1;
            dp[i] %= m;
        } else {
            pp[i] = x[i].size();
            x[i].push_back(-1);
        }
    }
