void dfs2(int i, int p, ll d_p = -1) {
    if(p != -1) {
        x[i][pp[i]] = d_p;
        (dp[i] *= d_p) %= m;
    }
    V<ll> s1, s2;
    s1 = s2 = x[i];
    rep(j, s1.size() - 1)(s1[j + 1] *= s1[j]) %= m;
    FORR(j, s2.size() - 1)(s2[j] *= s2[j + 1]) %= m;
