int mod;
struct mint {
  long long x;
  mint(long long x=0) : x((x%mod+mod)%mod) {}
  mint operator-() const { return mint(-x); }
  mint& operator+=(const mint& a) {
    if ((x += a.x) >= mod) x -= mod;
    return *this;
  }
  mint& operator-=(const mint& a) {
    if ((x += mod-a.x) >= mod) x -= mod;
    return *this;
  }
  mint& operator*=(const mint& a) {
    (x *= a.x) %= mod;
    return *this;
  }
  mint operator+(const mint& a) const {
    return mint(*this) += a;
  }
  mint operator-(const mint& a) const {
    return mint(*this) -= a;
  }
  mint operator*(const mint& a) const {
    return mint(*this) *= a;
  }
  mint pow(long long t) const {
    if (!t) return 1;
    mint a = pow(t>>1);
    a *= a;
    if (t&1) a *= *this;
    return a;
  }
  // for prime mod
  mint inv() const { return pow(mod-2); }
  mint& operator/=(const mint& a) { return *this *= a.inv(); }
  mint operator/(const mint& a) const {
    return mint(*this) /= a;
  }
};
istream& operator>>(istream& is, const mint& a) {
  return is >> a.x;
}
ostream& operator<<(ostream& os, const mint& a) {
  return os << a.x;
}

struct Rerooting {
  struct DP {
    mint dp;
    DP(int dp=1) : dp(dp) {}
    DP operator+(const DP& a) const {
      DP res(*this);
      res.dp *= a.dp;
      return res;
    }
    DP add_root() const {
      DP res(*this);
      res.dp+=1;
      return res;
    }
  };

  int n;
  vector<vector<int>> to;
  vector<vector<DP>> dp;
  vector<DP> ans;
  Rerooting(int n) : n(n), to(n), dp(n), ans(n) {}
  void add_edge(int s, int t) {
    to[s].push_back(t);
  }
  void init() {
    dfs(0);
    bfs(0);
  }

  DP dfs(int v, int p=-1) {
    DP dp_sum;
    dp[v] = vector<DP>(to[v].size());
    for (int i = 0; i < to[v].size(); i++) {
      int u = to[v][i];
      if (u == p) continue;
      dp[v][i] = dfs(u, v);
      dp_sum = dp_sum + dp[v][i];
    }
    return dp_sum.add_root();
  }
  void bfs(int v, const DP& dp_p=DP(), int p=-1) {
    int deg = to[v].size();
    for (int i = 0; i < deg; i++) {
      if (to[v][i] == p) dp[v][i] = dp_p;
    }

    vector<DP> dp_l(deg+1), dp_r(deg+1);
    for (int i = 0; i < deg; i++) {
      dp_l[i+1] = dp_l[i] + dp[v][i];
    }
    for (int i = deg-1; i >= 0; i--) {
      dp_r[i] = dp_r[i+1] + dp[v][i];
    }
    ans[v] = dp_l[deg];

    for (int i = 0; i < deg; i++) {
      int u = to[v][i];
      if (u == p) continue;
      DP d = dp_l[i] + dp_r[i+1];
      bfs(u, d.add_root(), v);
    }
  }
};

