      dfs2(i, node);
      dp[i].second = (dp[i].second / dp[node].second) % mod;
      dp[i].first = (dp[i].first / (dp[node].first + dp[node].second) % mod) % mod;
      dp[node].first = (dp[node].first * (dp[i].first + dp[i].second) % mod) % mod;
      dp[node].second = (dp[node].second * dp[i].second) % mod;
    }
  return;
}



