class Lowest_Common_Ancestor {
public:
	int N, MAX_bit;
	vector<vector<int>> edge;
	vector<int> depth;
	vector<int> order;
	vector<vector<int>> parent;
	vector<vector<int>> child;
	vector<vector<int>> descendant;


	Lowest_Common_Ancestor(int N, int MAX_bit = 20) :N(N), MAX_bit(MAX_bit), edge(N), depth(N, -1), order(N, -1), parent(N, vector<int>(MAX_bit)), child(N), descendant(N){
		//do nothing
	}

	//O(1)
	void make_edge(int from, int to) {
		edge[from].push_back(to);
	}

	//O(N)
	void make_depth(int root) {
		queue<int> q;
		depth[root] = 0;
		q.push(root);
		while (q.size()) {
			int from = q.front();
			q.pop();
			for (auto to : edge[from]) {
				if (depth[to] != -1) continue;
				depth[to] = depth[from] + 1;
				q.push(to);
			}
		}
	}

	//O(NlogN)
	void make_order(){
		vector<pair<int,int>> tmp(N);
		for (int i = 0; i < N; ++i) tmp[i] = {depth[i],i};
		sort(tmp.begin(),tmp.end(),greater<>());
		for (int i = 0; i < N; ++i) order[i] = tmp[i].second;
	}

	//O(MAX_bit*N)
	void make_parent() {
		for (int i = 0; i < N; ++i) parent[i][0] = i;
		for (int i = 0; i < N; ++i) for (auto j : edge[i]) if (depth[i] > depth[j]) parent[i][0] = j;
		for (int bit = 1; bit < MAX_bit; ++bit) for (int i = 0; i < N; ++i) parent[i][bit] = parent[parent[i][bit - 1]][bit - 1];
	}

	//O(N)
	void make_child() {
		for (int i = 0; i < N; ++i) for (auto j : edge[i]) if (depth[i] < depth[j]) child[i].push_back(j);
	}

	//O(N^2)
	void make_descendant() {
		for (int i = 0; i < N; ++i) descendant[i].push_back(i);
		for (int i = 0; i < N; ++i) for (auto j : edge[order[i]]) if (depth[order[i]] < depth[j]) for(auto k: descendant[j]) descendant[order[i]].push_back(k);
	}

	//O(MAX_bit*logN)
	int lca(int l, int r) {
		if (depth[l] < depth[r]) swap(l, r);
		int diff = depth[l] - depth[r];
		for (int bit = 0; bit < MAX_bit; ++bit) if (diff & (1 << bit)) l = parent[l][bit];
		int ok = (1 << MAX_bit), ng = -1, md;
		while (ok - ng>1) {
			md = (ok + ng) / 2;
			int x = l, y = r;
			for (int bit = 0; bit < MAX_bit; ++bit) if (md & (1 << bit)) x = parent[x][bit];
			for (int bit = 0; bit < MAX_bit; ++bit) if (md & (1 << bit)) y = parent[y][bit];
			(x == y ? ok : ng) = md;
		}
		for (int bit = 0; bit < MAX_bit; ++bit) if (ok & (1 << bit)) l = parent[l][bit];
		return l;
	}

	void print() {
		cout << " depth { " << depth[0];
		for (int i = 1; i < N; ++i) cout << ", " << depth[i];
		cout << " }" << endl;

		cout << "parent { " << parent[0][0];
		for (int i = 1; i < N; ++i) cout << ", " << parent[i][0];
		cout << " }" << endl;

		cout << " child { " << child[0];
		for (int i = 1; i < N; ++i) cout << ", " << child[i];
		cout << " }" << endl;

		cout << "descen { " << descendant[0];
		for (int i = 1; i < N; ++i) cout << ", " << descendant[i];
		cout << " }" << endl;
	}

};

int main() {
	ll N,M; cin >> N >> M;
	corner(N==1,1);
	Lowest_Common_Ancestor tree(N);
	REP(i,N-1){
		int x,y; cin >> x >> y;
		x--,y--;
		tree.make_edge(x,y);
		tree.make_edge(y,x);
	}
	tree.make_depth(0);
	tree.make_child();
	tree.make_order();
	tree.make_parent();
	V<ll> dp1(N,1),dp2(N,0);
	for(int i = 0; i < N; ++i){
		int j = tree.order[i];
		for(auto k:tree.child[j]) (dp1[j] *= (dp1[k] + 1) ) %= M;
	}
	for(int i = N-1; 0 <= i; --i){
		int j = tree.order[i];
		V<ll> a;
		for(int k = 0; k < tree.child[j].size(); ++k) a.push_back(dp1[tree.child[j][k]]);
		a.push_back(dp2[j]);
		int K = a.size();
		if(K == 1) continue;
		V<ll> L(K),R(K);
		L[0] = a[0] + 1;
		for(int i = 1; i < K; ++i) L[i] = (L[i-1]*(a[i] + 1)) % M;
		R[K-1] = a[K-1] + 1;
		for(int i = K-2; 0 <= i; --i) R[i] = (R[i+1]*(a[i] + 1)) % M;

		for(int k = 0; k < tree.child[j].size(); ++k) {
			int l = tree.child[j][k];
			dp2[l] = 1;
			if(0<=k-1) dp2[l] *= L[k-1];
			if(k+1<K) dp2[l] *= R[k+1];
		}
	}

	V<ll> dp(N,1);
	for(int i = 0; i < N; ++i){
		(dp[i] *= (dp2[i] + 1) ) %= M;
		for(auto k:tree.child[i]) (dp[i] *= (dp1[k] + 1) ) %= M;
		cout << dp[i] << endl;
	}


	return 0;
}

