	}

	vector<ll>L(sz), R(sz);
	L[0] = (dp[v][0]+1);
	R[sz - 1] = (dp[v][sz - 1]+1);
	rep(i, 1, sz)(L[i] = L[i-1] * (dp[v][i]+1))%=M;
	rrep(i,sz-2,0)(R[i] = R[i + 1] * (dp[v][i]+1))%=M;
