void dfs2(ll node, ll from, ll up){
  ll s = connected[node].size();
  ll pl[s], pr[s];
  pl[0] = 1, pr[s-1] = 1;
  REP(i,s-1){
    if(connected[node][i]==from) pl[i+1] = pl[i];
    else pl[i+1] = pl[i] * (dp[connected[node][i]]+1) % m;
  }
  REP(i,s-1){
    if(connected[node][s-1-i]==from) pr[s-2-i] = pr[s-1-i];
    else pr[s-2-i] = pr[s-1-i] * (dp[connected[node][s-1-i]]+1) % m;
