        R[i] = ((R[i + 1]*(down[v[nod][i + 1]] + 1))%mod + mod)%mod;
    }

    for(int i = 0; i < len; i++){

        int it = v[nod][i];

        up[it] = (((up[nod] + 1)*(L[i]%mod)*(R[i]%mod))%mod + mod)%mod;

        dfs2(it,nod);
    }


}

void dfs(int nd, int parent)
{
  auto I = find(v[nd].begin(), v[nd].end(), parent);
  if (I != v[nd].end()) v[nd].erase(I);

  if((int)v[nd].size() >= 1)
  {
    int n= v[nd].size();
    vector<ll> L(n, 0) , R(n, 0);
    L[0] = 1;
    R[n-1] = 1;
    for(int i=1; i<n; i++)
      L[i] = L[i-1] * (dp[v[nd][i-1]]+1) %mod;
    for(int i=n-2; i>=0; i--)
      R[i] = R[i+1] * (dp[v[nd][i+1]]+1) % mod;

    for(int i=0; i<n; i++)
    {
      int y = v[nd][i];
      dp1[y] = (dp1[nd] +1) * L[i]%mod*R[i]%mod;
      dfs(y, nd);
    }
  }
}

