ll search1(ll a[], ll f,ll n)
{
	ll left=1;
	ll right=n+1;
	while(right-left>1)
	{
		ll mid = left + (right-left)/2;
		if(a[mid]<f)
		{
			left=mid;
		}
		else right=mid;
	}
	return a[left];
}
ll n,m;
vl v[100003];
vector<ll> downdp;
vector<ll> updp;
vector<ll> grey;

ll down(ll vertex,ll parent,ll gp)
{
	//if(downdp[vertex]!=-1)return downdp[vertex];
	downdp[vertex]=1;
	vl g;
	for(ll x : v[vertex])
	{
		if(x==parent)continue;
		downdp[vertex]*=(1+down(x,vertex,parent))%m;
		g.pb(x);
	}
	if(!g.empty())
	{
		ll pre[g.size()];
		ll aft[g.size()];
		pre[0]=aft[g.size()-1]=1;
		for(ll i = 1;i<g.size();i++)
		{
			pre[i]=(pre[i-1]*(1+downdp[g[i-1]]))%m;
			aft[g.size()-i-1]=(aft[g.size()-i]*(1+downdp[g[g.size()-i]]))%m;
		}
		for(ll i=0;i<g.size();i++)
		{
			grey[g[i]]=(pre[i]*aft[i])%m;
		}
	}
	return downdp[vertex]%=m;
}
void up(ll vertex,ll parent,ll gp)
{
	//if(updp[vertex]!=-1)return;
	if(parent==0){updp[vertex]=1;}
	else
	{
		updp[vertex]=1;
		ll prod=updp[parent];
		prod*=grey[vertex]%m;
		updp[vertex]+=prod%m;
		updp[vertex]%=m;
	}
	for(ll x : v[vertex])
	{
		if(x==parent)continue;
		up(x,vertex,parent);
	}
}

