void dfs_sub(int u, int p) {
    sub[u] = 1;
    for (int v : g[u]) {
        if (v == p) continue;
        dfs_sub(v, u);
        (sub[u] *= sub[v] + 1) %= m;
    }
}
void dfs_par(int u, int p) {
    i64 x = 1;
    for (int i = 0; i < g[u].size(); ++i) {
        int v = g[u][i];
        if (v == p) continue;
        par[v] = par[u] * x % m;
        (x *= sub[v] + 1) %= m;
    }
    x = 1;
    for (int i = g[u].size() - 1; i >= 0; --i) {
        int v = g[u][i];
        if (v == p) continue;
        par[v] = (par[v] * x + 1) % m;
        (x *= sub[v] + 1) %= m;
    }
    for (int v : g[u]) {
        if (v == p) continue;
        dfs_par(v, u);
    }
}
