const int lim = 100000 + 100;

int N;
vec<int, 2> G;

ll MOD;
ll dp[lim], ans[lim];

void dfs(int v, int p = -1) {
  dp[v] = 1;
  for (int i = 0; i < G[v].size(); i++) {
    int u = G[v][i];
    if (u == p) continue;
    dfs(u, v);
    dp[v] = dp[v] * (1 + dp[u]) % MOD;
  }
}

void dfs2(int v, int p = -1, ll pv = 0) {
  vector<ll> f(G[v].size(), 1);
  for (int i = 0; i < G[v].size(); i++) {
    int u = G[v][i];
    if (u == p) {
      f[i] = (1 + pv) % MOD;
    } else {
      f[i] = (1 + dp[u]) % MOD;
    }
  }
  vector<ll> L(G[v].size() + 1, 1), R(G[v].size() + 1, 1);
  for (int i = 0; i < G[v].size(); i++) L[i + 1] = L[i] * f[i] % MOD;
  for (int i = G[v].size() - 1; i >= 0; i--) R[i] = R[i + 1] * f[i] % MOD;
  for (int i = 0; i < G[v].size(); i++) {
    int u = G[v][i];
    if (u == p) continue;
    ll cv = L[i] % MOD * R[i + 1] % MOD;
    dfs2(u, v, cv);
  }
  ans[v] = (1 + pv) * dp[v] % MOD;
}

