int dfs(int v)
{
    vis[v] = 1;
    int cn = 1;
    for(auto x : adj[v])
    {
        if(!vis[x])
        {
            par[x] = v;
            cn = (cn * (1+dfs(x)))%m;
        }
    }
    return dp[v] = cn;
}

void calc(int v, int p)
{
    dp2[v] = dp2[p];
    int prod = 1;
    for(auto x : adj[p])
    {
        if(x != v && x != par[p])
        {
            prod = (prod * (1 + dp[x]))%m;
        }
    }
    dp2[v] = (dp2[v] * prod +(v!=1))%m;
    for(auto x : adj[v])
    {
        if(x != p)
        {
            calc(x,v);
        }
    }
}

