//To compute dp[]
void dfs0(int i, int p) {
    dp[i] = 1;
    for(int j : adj[i]) {
        if(j != p) {
            dfs0(j, i);
            dp[i] = mul(dp[i], add(1, dp[j], m), m);
        }
    }
}

//To compute ans[]
void dfs(int i, int p) {
    ans[i] = dp[i];

    int k = adj[i].size();
    vi pre(k), suf(k);

    int cur = 1;
    for(int j = 0; j < k; j++) {
        pre[j] = cur;
        cur = mul(cur, add(1, dp[adj[i][j]], m), m);
    }

    cur = 1;
    for(int j = k-1; j >= 0; j--) {
        suf[j] = cur;
        cur = mul(cur, add(1, dp[adj[i][j]], m), m);
    }

    for(int c = 0; c < k; c++) {
        int j = adj[i][c];
        if(j == p) continue;

        int dpi, dpj;
        dpi = dp[j], dpj = dp[j];

        dp[i] = mul(pre[c], suf[c], m);
        dp[j] = mul(dp[j], add(1, dp[i], m), m);
        dfs(j, i);

        dp[i] = dpi;
        dp[j] = dpj;
    }
}

