void gao(int x){
	for(int i=0;i!=v[x].size();++i){
		if(fa[x]==v[x][i]) continue;
		fa[v[x][i]]=x;
		gao(v[x][i]);
	}
}

long long suan(int x){
	if(dp[x]!=0)	return dp[x];
	dp[x]=1;
	for(int i=0;i!=v[x].size();++i){
		if(v[x][i]==fa[x]) continue;
		dp[x]*=suan(v[x][i])+1;
		dp[x]%=m;
	}
	return dp[x];
}

void nong(int x){
	for(int i=0;i<v[x].size();++i){
		if(ans[v[x][i]]!=0) continue;
		fa[x]=v[x][i];
		fa[v[x][i]]=0;
		long long tmp1=dp[x],tmp2=dp[v[x][i]];
		dp[x]=1;
		for(int j=0;j<v[x].size();++j) {
			if(v[x][j]==fa[x]) continue;
			dp[x]*=dp[v[x][j]]+1;
			dp[x]%=m;
		}
		dp[v[x][i]]*=dp[x]+1;
		dp[v[x][i]]%=m;
		//for(int j=1;j<=n;++j) cout<<dp[j]<<" ";
		//puts("");
		ans[v[x][i]]=dp[v[x][i]];
		nong(v[x][i]);
		fa[v[x][i]]=x;
		fa[x]=0;
		dp[x]=tmp1;
		dp[v[x][i]]=tmp2;
	}

}

