inline int multiply(int a, int b) {
    // return a * b;
    return (a * b) % m;
}

inline int binpow(int n, int k) {
    int res = 1;
    while(k) {
        if(k & 1)
            res = multiply(res, n);
        k >>= 1;
        n = multiply(n, n);
    }
    return res;
}

inline int divide(int a, int b) {
    return multiply(a / __gcd(a, b), binpow(b / __gcd(a, b), phi - 1));
}

inline void add(int &a, int b) {
    // a += b;
    a = (a + b) % m;
}

void dfs(int v, int p = -1) {
    dp[v] = 1;
    for(int to : g[v])
        if(to != p) {
            dfs(to, v);
            add(dp[v], multiply(dp[v], dp[to]));
        }
    dp2[v] = dp[v];
}

void recalc(int v, int p = -1) {
    for(int to : g[v])
        if(to != p) {
            add(dp2[to], divide(multiply(dp2[v], dp[to]), 1 + dp[to]));
            recalc(to, v);
        }
}

