struct Node {
    //Educational DP Contest V - Subtree
    Mint sm = Mint(1);
    template <class E> Node to_subs(int, const E&) const {
        //tree -> subtrees
        return {sm + 1};
    }
    Node operator+(const Node& r) const {
        //subtrees + subtrees
        return {sm * r.sm};
    }
    Node join(int) const {
        //subtrees -> tree
        return *this;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n >> MD;
    struct E { int to; };
    VV<E> g(n);
    for (int i = 0; i < n-1; i++) {
        int a, b;
        cin >> a >> b; a--; b--;
        g[a].push_back(E{b});
        g[b].push_back(E{a});
    }

    auto all_tree = get_all_tree<Node>(g);

    for (int i = 0; i < n; i++) {
        cout << all_tree[i].back().sm << "\n";
    }
    return 0;
}

