llint dfs(int v, int pre)
{
	if(memo.count(make_pair(v, pre))) return memo[make_pair(v, pre)];

	llint ret = 1;
	for(int i = 0; i < G[v].size(); i++){
		if(G[v][i] == pre) continue;
		ret *= dfs(G[v][i], v)+1, ret %= mod;
	}
	return memo[make_pair(v, pre)] = ret;
}

