vector<int> sp[N][2];
int f(int x, int p){
	int &r=dp[x];
	if(r!=-1)return r;
	r=1;
	for(int y:g[x])if(y!=p)r=mul(r,1+f(y,x));
	sp[x][0].resize(SZ(g[x]),1);
	sp[x][1].resize(SZ(g[x]),1);
	fore(i,0,SZ(g[x])){
		int y=g[x][i];
		fa[y]=i;
		if(i==SZ(g[x])-1)continue;
		sp[x][0][i+1]=mul(sp[x][0][i],(y==p?1:dp[y]+1));
	}
	for(int i=SZ(g[x])-1;i>0;i--){
		int y=g[x][i];
		sp[x][1][i-1]=mul(sp[x][1][i],(y==p?1:dp[y]+1));
	}
	return r;
}
