	int r=vpp;
	r=mul(r,mul(sp[p][0][fa[x]],sp[p][1][fa[x]]));
	r++;
	ans[x]=mul(dp[x],r);
	if(r>=m)r-=m;
	for(int y:g[x])if(y!=p)doit(y,x,r);
}
