ll n,m,dp[N][2],outdp[N];
deque<ll> g[N],lev[N],pre[N],suf[N];

void DFS(ll cur,ll par,ll dep)
{
  ll ways=1;
  dp[cur][0]=1;
  lev[dep].pb(cur);
  for(auto i:g[cur])
  {
    if(i==par){continue;}
    DFS(i,cur,dep+1);
    ways=mul(ways,((dp[i][0]%m)+(dp[i][1]%m))%m,m);
  }
  dp[cur][1]=ways;
}

void xDFS(ll cur,ll par,ll dep)
{
  if(cur==1){outdp[cur]=1;}
  else
  {
    ll p=lev[dep].size();
    ll lb=lower_bound(all(lev[dep]),cur)-lev[dep].begin();
    if(p==1){outdp[cur]=((outdp[par]%m)+(dp[par][0]%m))%m;}
    else
    {
      ll pro=1;
      if(lb==0){pro=mul(pro,suf[dep][lb+1],m);}
      else if(lb==p-1){pro=mul(pro,pre[dep][lb-1],m);}
      else
      {
        pro=mul(pro,pre[dep][lb-1],m);
        pro=mul(pro,suf[dep][lb+1],m);
      }
      //  trace5(cur,lb,p,dep,pro);
      pro=mul(pro,outdp[par],m);
      //trace5(cur,lb,p,dep,pro);
      outdp[cur]=((pro%m)+(dp[par][0]%m))%m;
    }
  }
  for(auto i:g[cur])
  {
    if(i==par){continue;}
    xDFS(i,cur,dep+1);
  }
}

