void dfs_one(int u, int p) {
	dp[u] = 1;
	for (int v : adj[u]) {
		if (v == p) {
			continue;
		}
		dfs_one(v, u);
		dp[u] = dp[u] * dp[v] % mod;
	}
	dp[u] = (dp[u] + 1) % mod;
}

void dfs_two(int u, int p, ll ways_now) {
	vector<ll> pref, suf;
	pref.push_back(1);
	for (int v : adj[u]) {
		if (v == p) {
			continue;
		}
		pref.push_back(dp[v]);
		suf.push_back(dp[v]);
	}
	suf.push_back(1);
	for (int i = 1; i < (int) pref.size(); i++) {
		pref[i] = (pref[i] * pref[i - 1]) % mod;
	}
	for (int i = (int) suf.size() - 2; i >= 0; i--) {
		suf[i] = (suf[i] * suf[i + 1]) % mod;
	}
	ans[u] = pref.back() * ways_now % mod;
	int i = 0;
	for (int v : adj[u]) {
		if (v == p) {
			continue;
		}
		ll next_ways = pref[i] * suf[i + 1] % mod;
		next_ways = next_ways * ways_now % mod;
		next_ways = (next_ways + 1) % mod;
		dfs_two(v, u, next_ways);
		i++;
	}
}

