		int p = (i - 1 >= 0 ? pre[a][i - 1] : 1);
		int s = (i + 1 < (int)adj[a].size() ? suf[a][i + 1] : 1);
		up[b] = mul(up[a], mul(p, s));
		up[b]++;
	}
	for(int b : adj[a]) if(b != p) {
		dfs2(b, a);
	}
