struct Edge {
  int from;
  int to;
  int id;
};

int N;
ll M;
vec<Edge, 2> G;

vector<Edge> edges;

ll dp[400000][2];

ll func(int ei, int c) {
  ll& res = dp[ei][c];
  if (res != -1) return res;
  int p = edges[ei].from;
  int v = edges[ei].to;
  res = 1;
  for (auto e : G[v]) {
    if (e.to == p) continue;
    ll sum = 0;
    for (int nc = 0; nc <= (c ? 1 : 0); nc++) {
      sum += func(e.id, nc);
      sum %= M;
    }
    res = res * sum % M;
  }
  return res;
}

ll solve(int v) {
  return func(2 * (N - 1) + v, 1);
}

