ll extEuclides(ll a,ll b,ll &x, ll &y,ll mod = 0){
        if(!b){
                x = 1, y = 0;
                return a;
        }
        ll gcd = extEuclides(b,a%b,x,y,mod);
        x = !mod ? x-y*(a/b) : (mod+x-(y*(a/b))%mod)%mod;
        swap(x,y);
        return gcd;
}
ll modInverse(ll a,ll m){
	ll x,y;
	ll g = extEuclides(a,m,x,y,m);
	if(g != 1)return -1;
	return (x%m+m)%m;
}
ll modDivide(ll a,ll b,ll m){
	a %= m;
	ll inv = modInverse(b,m);
	if(inv == -1)return -1;
	return (inv*a)%m;
}
