typedef long long ll;typedef vector<int> vi;typedef pair<int,int> pi;const int inf = (int)1e9;const double INF = 1e12, EPS = 1e-9;

int n, mod, cnt[200010];
map<pi, int> dp, eid;
vi lsum[200010], rsum[200010], memo[200010];
vector<vi> e;

int rec(int c, int p){
	if(dp.count(pi(c, p))) return dp[pi(c, p)];

	int m = e[c].size();
	vi &ls = lsum[c], &rs = rsum[c];

	if(cnt[c]++ >= 2){
		int i = eid[pi(c, p)];
		assert(ls.size() == m + 1 && rs.size() == m + 1);
		return dp[pi(c, p)] = ls[i] * (ll)rs[i + 1] % mod;
	}
	if(cnt[c] == 1) memo[c].resize(m);

	int res = 1;
	rep(i, m) if(e[c][i] != p){
		int x = rec(e[c][i], c) + 1;
		memo[c][i] = x;
		res = res * (ll)x % mod;
	}

	if(cnt[c] == 2){
		ls.resize(m + 1);
		rs.resize(m + 1);
		ls[0] = rs[m] = 1;
		rep(i, m) ls[i + 1] = (ll)ls[i] * memo[c][i] % mod;
		for(int i = m - 1; i >= 0; i--) rs[i] = (ll)rs[i + 1] * memo[c][i] % mod;
	}

	return dp[pi(c, p)] = res;
}
int main(){
	scanf("%d%d", &n, &mod);
	e.resize(n);
	rep(i, n - 1){
		int a, b; scanf("%d%d", &a, &b); a--; b--;
		e[a].pb(b); eid[pi(a, b)] = e[a].size() - 1;
		e[b].pb(a); eid[pi(b, a)] = e[b].size() - 1;
	}
	if(n == 1){
		cout << 1 << endl;
		return 0;
	}

	rep(i, n){
		int o = -1;
		for(int j : e[i]){
			o = j;
			break;
		}
		assert(o >= 0 && o != i);

		int x = rec(i, o);
		int y = rec(o, i);
		printf("%d\n", x * (y + 1ll) % mod);
	}
	return 0;
}

