int read()
{
	int x = 0, f = 1; char c = getchar();
	while(!isdigit(c)) { if(c == '-') f = 0; c = getchar(); }
	while(isdigit(c)) { x = (x << 3) + (x << 1) + (c ^ 48); c = getchar(); }
	return f ? x : -x;
}

typedef long long LL;
const int maxn = 1e5 + 10, maxm = maxn << 1;
int mod, to[maxm], nxt[maxm], head[maxn], e, f[maxn], g[maxn], ans[maxn], p[maxn];
vector<int> vec[maxn];

void add(int x, int y) 
{
	to[++e] = y; nxt[e] = head[x]; head[x] = e;
	to[++e] = x; nxt[e] = head[y]; head[y] = e;
}

void dfs(int u, int fa)
{
	f[u] = 1;
	int tot = 0;
	for(int i = head[u]; i; i = nxt[i])
	{
		int v = to[i];
		if(v == fa) continue;
		dfs(v, u);
		f[u] = (LL)f[u] * (f[v] + 1) % mod;
		p[v] = tot++; vec[u].push_back(f[v]);
	}
}

void dp(int u, int fa)
{
	//cout << u << ' ' << g[u] << ' ' << f[u] << endl;
	vec[u].push_back(g[u] + 1);
	for(int i = (int)vec[u].size() - 2; i >= 0; --i)
		vec[u][i] = (LL)(vec[u][i] + 1) * vec[u][i + 1] % mod;
	int now = 1; ans[u] = vec[u][0];
	for(int i = head[u]; i; i = nxt[i])
	{
		int v = to[i];
		if(v == fa) continue;
		g[v] = (LL)now * vec[u][p[v] + 1] % mod;
		dp(v, u);
		now = (LL)now * (f[v] + 1);
	}
}

int main()
{

	int n = read(); mod = read();
	for(int i = 2; i <= n; ++i) add(read(), read());
	dfs(1, 0);
	dp(1, 0);
	for(int i = 1; i <= n; ++i) printf("%d\n", ans[i]);

	return 0;
}

