void solve1(int node,int par){
    int sz = adjlist[node].size();
    ll w=1;
    for(int i=0;i<sz;i++){
        int u = adjlist[node][i];
        if(u!=par){
            solve1(u,node);
            w *= (dp1nonroot[u]+1)%m;
            w %=m;
        }
    }
    dp1nonroot[node] = w;
}
void solve2(int node,int par_val,int par){
    int sz = adjlist[node].size();
    ll w=1;
    w = (dp1nonroot[node]*((1+par_val)%m))%m;
    dp2asroot[node] = w;
    vector<int>chld;
    for(int i=0;i<sz;i++){
        if(adjlist[node][i]==par){
            continue;
        }
        chld.push_back(adjlist[node][i]);
    }
    sz = chld.size();
    vector<int>prefix(sz,1),suffix(sz,1);
    for(int i=1;i<sz;i++){
        prefix[i] = (prefix[i-1]*((dp1nonroot[chld[i-1]]+1)%m))%m;
    }
    for(int i=sz-2;i>=0;i--){
        suffix[i] = (suffix[i+1]*((dp1nonroot[chld[i+1]]+1)%m))%m;
    }

    for(int i=0;i<sz;i++){
        int u = chld[i];
        int pv = (((prefix[i]*suffix[i])%m)*((par_val +1)%m))%m;
        solve2(u,pv,node);
    }
    return;
}

