{
    cin>>n>>m;
    FOR(i,0,N) dp[i]=dp2[i]=1;
    FOR(i,1,n)
    {
        cin>>x>>y;
        g[x].push_back(y);
        g[y].push_back(x);
    }
    dfs(1,-1);
    dpf(1,-1);
    FOR(i,1,n+1) cout<<(dp[i]*dp2[i])%m<<'\n';

    return 0;
}

