template <class Handler>
struct ReRooting : Handler {
    using data = typename Handler::data; // edge data
    using dp_t = typename Handler::dp_t; // internal dp data
    using res_t = typename Handler::res_t; // res of dfs
    using Handler::unit; // () -> dp_t
    using Handler::join; // (dp_t,res_t,edge) -> dp_t
    using Handler::merge; // (dp_t,dp_t) -> res_t
    struct edge {
        int32_t to,rev; data d;
        edge(int32_t to, int32_t rev, data const& d) : to(to),rev(rev),d(d) {}
    };
    int n;
    vector<vector<edge> > g;
    vector<vector<dp_t> > ldp,rdp;
    vector<int32_t> l,r;
    ReRooting(int n = 0) : n(n), g(n), ldp(n), rdp(n), l(n), r(n) {}
    void resize(int n) {
        this->n = n; g.resize(n);
        ldp.resize(n); rdp.resize(n); l.resize(n), r.resize(n);
    }
    void add_edge(int x, int y, data const& d) {
        g[x].emplace_back(y, g[y].size(), d);
        g[y].emplace_back(x, g[x].size()-1, d);
        // g[x].emplace_back(edge { y, (int)g[y].size(), d });
        // g[y].emplace_back(edge { x, (int)g[x].size()-1, d });
    }
    void add_edge(int x, int y, data const& d, data const& e) {
        g[x].emplace_back(y, g[y].size(), d);
        g[y].emplace_back(x, g[x].size()-1, e);
    }
    vector<res_t> run() {
        rep (i,n) {
            ldp[i].resize(g[i].size()+1, unit());
            rdp[i].resize(g[i].size()+1, unit());
            l[i] = 0; r[i] = g[i].size()-1;
        }
        vector<res_t> ret; ret.reserve(n);
        rep (i,n) ret.emplace_back(dfs(i,-1));
        return ret;
    }
    res_t dfs(int x, int p) {
        auto const& e = g[x];
        for (int32_t &i = l[x]; i != p && i < (int32_t)e.size(); ++i) {
            ldp[x][i+1] = join(ldp[x][i], dfs(e[i].to, e[i].rev), e[i].d);
        }
        for (int32_t &j = r[x]; j != p && j >= 0; --j) {
            rdp[x][j] = join(rdp[x][j+1], dfs(e[j].to, e[j].rev), e[j].d);
        }
        if (p < 0) return rdp[x][0];
        return merge(ldp[x][p], rdp[x][p+1]);
    }
};

struct Handler {
    using data = void*;
    using dp_t = mint;
    using res_t = mint;
    static dp_t unit() { return 1; }
    static dp_t join(dp_t const& x, res_t const& y, data const&) {
        return x*(y+1);
    }
    static res_t merge(dp_t const& x, dp_t const& y) {
        return x*y;
    }
};

int32_t main() {
    int n,m; cin >> n >> m;
    mint::mod() = m;
    ReRooting<Handler> rr(n);
    rep (i,n-1) {
        int x,y; cin >> x >> y; x--,y--;
        rr.add_edge(x,y,0);
    }
    for (auto x : rr.run()) {
        cout << x << "\n";
    }
}

