    for (const int next : G[curr])
    {
        if (next == prev) continue;
        dfs1(next, curr);
        dp[curr] *= dp[next] + 1;
    }
}

mint ans[100010];

void dfs2(int curr, int prev = -1)
{
    ans[curr] = 1;
    for (const int next : G[curr]) ans[curr] *= dp[next] + 1;

    const int n = G[curr].size();
    vector<mint> l(n), r(n);
    rep(i, 0, n) l[i] = r[i] = dp[G[curr][i]] + 1;
    rep(i, 0, n - 1) l[i + 1] *= l[i];
    rrep(i, n - 1, 1) r[i - 1] *= r[i];

    rep(i, 0, n)
    {
        const int next = G[curr][i];
        if (next == prev) continue;
        dp[curr] = 1;
        if (i - 1 >= 0) dp[curr] *= l[i - 1];
        if (i + 1 < n) dp[curr] *= r[i + 1];
        dfs2(next, curr);
    }
}

