{
    cin >> n >> m;
    ll x, y;
    for (int i = 1; i < n; ++i)
    {
        cin >> x >> y;
        adj[x].push_back(y);
        adj[y].push_back(x);
    }
    dfs1(1, -1);
    dfs2(1, -1, 0);
    for (int i = 1; i <= n; ++i)
        cout << dp2[i] << "\n";
    return 0;
}

