int dp[MAX_N] ,dp2[MAX_N];
void pre(int u){
    dp[u] = 1;
    for(int&v : adj[u]){
        adj[v].erase(find(adj[v].begin() ,adj[v].end() ,u));
        pre(v);
        dp[u] = 1LL*dp[u]*(dp[v]+1)%m;
    }
}
void dfs(int u ,int up=1){
    dp2[u] = 1LL*dp[u]*up%m;
    if(adj[u].empty())
        return;
    vector <int> pref(adj[u].size() ,1) ,suff(adj[u].size() ,1);
    for(int i=1; i<adj[u].size(); i++)
        pref[i] = 1LL*pref[i-1]*(dp[adj[u][i-1]]+1)%m;
    for(int i=adj[u].size()-2; ~i; i--)
        suff[i] = 1LL*suff[i+1]*(dp[adj[u][i+1]]+1)%m;
    for(int i=0; i<adj[u].size(); i++)
        dfs(adj[u][i] ,(1LL*up*pref[i]%m*suff[i]+1)%m);
}

