void dfs1(int u, int p = -1){
  vector<int> children;
  for(int v : g[u]){
    if(v == p) continue;
    children.push_back(v);
  }
  int tot = children.size();
  if(!tot) return;
  vector<int> pref(tot), suf(tot);
  pref[0] = (1 + dp_down[children[0]]) % M;
  for(int i = 1; i < tot; ++i){
    pref[i] = (pref[i - 1] * (1 + dp_down[children[i]]) % M) % M;
  }
  suf[tot - 1] = (1 + dp_down[children[tot - 1]]) % M;
  for(int i = tot - 2; i >= 0; --i){
    suf[i] = (suf[i + 1] * (1 + dp_down[children[i]]) % M) % M;
  }
  for(int i = 0; i < tot; ++i){
    int tempAns = 1;
    if(i > 0) mul(tempAns, pref[i - 1]);
    if(i < tot - 1) mul(tempAns, suf[i + 1]);
    dp_up[children[i]] = (1 + (dp_up[u] * tempAns) % M) % M;
  }
  for(int v : g[u]){
    if(v != p)
