ll M, dp[C], kk, cafu[C];

int s[C], is=0, ip=1, par[C], ji[C];
void proc_tree(int a, int n, vector <vector <int> > &tab, int ij[]){
	s[0]=a, is=1, dp[a]=1;
	int b, i, j;

	for(int z=1;z<=n;z++)	ji[z]=ij[z], par[z]=0;

	while (is>0){
		a=s[is-1];
		if (ji[a]>0&&tab[a][ji[a]-1]==par[a])	ji[a]--;
		if (ji[a]>0)	b=s[is]=tab[a][ji[a]-1], dp[b]=1, par[b]=a, is++, ji[a]--;
		else {
			if (is>1)	b=s[is-2];
			else b=0;
			mom[a]=all[b], all[b]++;
			dp[b]=dp[b]*(dp[a]+1);
			il[b].push_back(dp[a]+1);
			is--;
		}
	}

	for(int z=1;z<=n;z++)	ji[z]=ij[z];

	for (i=1;i<=n;i++){
		for (j=0;j<all[i];j++){
			if (j>0)	il1[i].push_back((il1[i][j-1]*il[i][j])%M), il2[i].push_back((il2[i][j-1]*il[i][all[i]-j-1])%M);
			else 		il1[i].push_back(il[i][0]), il2[i].push_back(il[i][all[i]-1]);
		}
	}

	s[0]=1, is=1, cafu[1]=1;
	while (is>0){
		a=s[is-1];
		if (ji[a]>0&&tab[a][ji[a]-1]==par[a])	ji[a]--;
		if (ji[a]>0)	{
			b=s[is]=tab[a][ji[a]-1];

			kk=1;
			if (mom[b]>0)	kk=(il1[a][mom[b]-1])%M;
			if (all[a]-mom[b]-1>0)	kk=(kk*il2[a][all[a]-mom[b]-2])%M;
			kk=(kk*cafu[a])%M;
			cafu[b]=(kk+1)%M;
			dp[b]=(dp[b]*cafu[b])%M;
			is++, ji[a]--;
		}
		else is--;
	}

}

