int dp1[100001], dp2[100001];
vi tree[100001];
void solve1(int src, bool vis[], int m)
{
	vis[src] = 1;
	dp1[src] = 1;
	for (int child : tree[src])
	{
		if (!vis[child])
		{
			solve1(child, vis, m);
			dp1[src] = (dp1[src] * (1 + dp1[child])) % m;
		}
	}
}
void solve2(int src, bool vis[], int m, int par_ans)
{
	vis[src] = 1;
	dp2[src] = ((1 + par_ans) * dp1[src]) % m;
	vi prefix, suffix;
	for (int child : tree[src])
	{
		if (!vis[child])
		{
			prefix.pb((int)1 + dp1[child]);
			suffix.pb((int)1 + dp1[child]);
		}
	}
	repD(i, suffix.size() - (int)2, 0)
	{
		suffix[i] = (suffix[i + 1] * suffix[i]) % m;
	}
	repA(i, 1, prefix.size() - (int)1)
	{
		prefix[i] = (prefix[i - 1] * prefix[i]) % m;
	}
	int cno = 0;
	for (int child : tree[src])
	{
		if (!vis[child])
		{
			int ways = (1 + par_ans);
			ways = (cno > 0) ? (ways * prefix[cno - 1]) % m : ways;
			ways = (cno < (suffix.size() - 1)) ? (ways * suffix[cno - 1]) % m : ways;
			solve2(child, vis, m, ways);
			cno++;
		}
	}
}
