void add_self(ll &a, ll b){a+=b;if(a>=mod)a-=mod;}
void sub_self(ll &a, ll b){a-=b;if(a<0)a+=mod;}
void mul_self(ll &a, ll b){a*=b;a%=mod;}


void dfs(ll v, ll p)
{
	for( ll i:G[v])if(i!=p){dfs(i,v);mul_self(down[v],down[i]+1);}

	ll x=1;
	for(ll i:G[v]){if(i!=p)mul_self(x,down[i]+1);pref[v].pb(x);}
	x=1;
	forr(i,sz(G[v])){if(G[v][i]!=p)mul_self(x,down[G[v][i]]+1);suff[v].pb(x);}
	reverse(all(suff[v]));
}

void dfs2(ll v, ll p)
{
	forn(i,sz(G[v]))
	{
		if(G[v][i]==p)continue;
		ll x=1;
		if(i!=0)mul_self(x,pref[v][i-1]);
		if(i!=sz(G[v])-1)mul_self(x,suff[v][i+1]);
		mul_self(x,up[v]);
		up[G[v][i]]=x+1;
		dfs2(G[v][i],v);
	}
}

