		g[a].pb(b);
		g[b].pb(a);
	}
	rep(i,n) sort(all(g[i]));
	sepDec sd_(g);
	vector<int> sd(n); iota(all(sd),0);
	sort(rall(sd),[&](int i,int j){return g[i].size()<g[j].size();});
	vector<int> usd(n);
	function<ll(int,int)> dfs=
		[&](int v,int p){
			if(memo[v].count(p)) return memo[v][p];
			ll re=1;
			for(int w:g[v])if(w!=p) (re*=(1+dfs(w,v)))%=m;
			return memo[v][p]=re;
		};
	vector<ll> re(n);
	for(int rt:sd){
		vector<ll> vs;
		for(int v:g[rt]){
			vs.pb(1+dfs(v,rt));
		}
