		r.pb(1);
		rrep(i,vs.size()) (r[i]*=r[i+1])%=m;
		ll p=1;
		rep(i,g[rt].size()){
			memo[rt][g[rt][i]]=p*r[i+1]%m;
			(p*=vs[i])%=m;
		}
		usd[rt]=1;
		re[rt]=r[0];
	}
	out(re,1);
	for(int x:re) cout<<x<<"\n";
  return 0;
}

