		}
	}
	for(int i=0;i<t1[p].size();i++)
	{
		l[p][i]=(i==0)?1:l[p][i-1];
		(l[p][i]*=(f[t1[p][i]]+1))%=mod;
	}
	for(int i=t1[p].size()-1;i>=0;i--)
	{
		r[p][i]=(i==t1[p].size()-1)?1:r[p][i+1];
