#include<bits/stdc++.h>
#define maxn 120000 
using namespace std;
typedef long long LL;
LL M; 
vector<int> G[maxn];
LL up[maxn], down[maxn];
void DFS_down(int u, int fa = 0){
	down[u] = 1;
	for(int v : G[u]) if(v != fa){
		DFS_down(v, u);
		down[u] = down[u] * (1 + down[v]) % M;
	}
}
void DFS_up(int u, int fa = 0){
	for(int v : G[u]) if(v != fa) up[v] = up[u];
	LL pre = 1;
	for(int v : G[u]) if(v != fa){
		up[v] = up[v] * pre % M;
		pre = pre * (down[v] + 1) % M;
	}
	LL suf = 1;
	reverse(G[u].begin(), G[u].end());
	for(int v : G[u]) if(v != fa){
		up[v] = up[v] * suf % M;
		suf = suf * (down[v] + 1) % M;
	}
	for(int v : G[u]) if(v != fa){
		up[v] = (up[v] + 1) % M;
		DFS_up(v, u);
	}
}
int main(){
	ios::sync_with_stdio(false);
	int N;
	cin >> N >> M;
	for(int i = 1; i < N; i += 1){
		int x, y;
		cin >> x >> y;
		G[x].push_back(y);
		G[y].push_back(x);
	}
	DFS_down(1);
	DFS_up(up[1] = 1);
	for(int i = 1; i <= N; i += 1) cout << down[i] * up[i] % M << endl;
}

