#define REP(i,n) for(ll i = 0; i < (ll)n; i++)
#define INF 1000000000000000
using namespace std;
typedef long long ll;
typedef double db;
typedef string str;
typedef pair<ll,ll> p;

map<p,ll> mp;
vector<vector<ll> > connected;
ll m;

ll dfs(ll node, ll from){
  auto itr = mp.find(p(node,from));
  if(itr!=mp.end()) return mp[p(node,from)];
  if(connected[node].size()==1) return mp[p(node,from)] = 2;
  ll res = 1;
  for(ll k: connected[node]){
    if(k==from) continue;
    res *= dfs(k,node), res %= m;
  }
  res++, res %= m;
  return mp[p(node,from)] = res;
}

int main(){
  ll n;
  cin >> n >> m;
  connected.resize(n);
  REP(i,n-1){
    ll x,y;
    cin >> x >> y;
    x--, y--;
    connected[x].push_back(y);
    connected[y].push_back(x);
  }
  REP(i,n){
    ll res = 1;
    for(ll k : connected[i]){
      res *= dfs(k,i), res %= m;
    }
    cout << res << endl;
  }
  return 0;
}

#include "bits/stdc++.h"
using namespace std;
typedef long long ll;
const int MM = 2e5 + 4;
ll mod;
ll dp[MM], ans[MM];
vector <ll> T[MM], suf[MM], pref[MM];
ll dfs(int u, int p) {
	ll ans = 1;
	for(int i = 0; i < T[u].size(); i++) {
		int v = T[u][i];
		if(v != p) {
			ans = (ans * (1 + dfs(v, u))) % mod;
		}
	}
	ll k = 1;
	pref[u].push_back(1);
	for(int i = 0; i < T[u].size(); i++) {
		int v = T[u][i];
		if(v != p) {
			k = (k * (1 + dp[v])) % mod;
		}
		pref[u].push_back(k);
	}
	k = 1;
	for(int i = (int)T[u].size() - 1; i >= 0; i--) {
		int v = T[u][i];
		if(v != p) {
			k = (k * (1 + dp[v])) % mod;
		}
		suf[u].push_back(k);
	}
	reverse(suf[u].begin(), suf[u].end());
	suf[u].push_back(1);
	return dp[u] = ans;
}
void dfs2(int u, int p, int ind, ll tp) {
	ans[u] = 1;
	if(p != -1) {
		ans[u] = (pref[p][ind] * suf[p][ind + 1]) % mod;
		ans[u] = (ans[u] * tp) % mod;
		ans[u]++;
	}
	for(int i = 0; i < T[u].size(); i++) {
		int v = T[u][i];
		if(v != p) {
			dfs2(v, u, i, ans[u]);
		}
	}
	for(int v : T[u]) {
		if(v != p) {
			ans[u] = (ans[u] * (1 + dp[v])) % mod;
		}
	}
}
int main() {
	int n;
	cin >> n >> mod;
	for(int i = 0; i < n - 1; i++) {
		int x, y;
		cin >> x >> y;
		x--; y--;
		T[x].push_back(y);
		T[y].push_back(x);
	}
	dfs(0, -1);
	dfs2(0, -1, 0, 1);
	for(int i = 0; i < n; i++) {
		cout << ans[i] % mod << endl;
	}
	return 0;
}

