int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    int n, m;
    cin, n, m;
    vector<vector<int>> g(n);
    REP(i, 0, n - 1) {
        int a, b;
        cin, a, b;
        a--;
        b--;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    vector<ll> dp(n, 1);
    vector<vector<ll>> sumL(n, vector<ll>(1, 1)), sumR(n, vector<ll>(1, 1));
    function<void(int, int)> dfs = [&](int v, int p) {
        vector<ll> res;
        for (int i = 0; i < g[v].size(); i++) {
            int vv = g[v][i];
            if (vv == p) continue;
            dfs(vv, v);
            res.emplace_back((dp[vv] + 1) % m);
        }
        REP(i, 0, res.size()) {
            sumL[v].emplace_back((sumL[v].back() * res[i]) % m);
        }
        REP(i, 0, res.size()) {
            sumR[v].emplace_back((sumR[v].back() * res[res.size() - i - 1]) % m);
        }
        reverse(sumR[v].begin(), sumR[v].end());
        dp[v] = sumL[v].back();
    };

    vector<ll> prop(n, 1);
    function<void(int, int)> bfs = [&](int v, int p) {
        int cnt = 0;
        for (auto vv : g[v]) {
            if (vv == p) continue;
            prop[vv] = (sumL[v][cnt] * sumR[v][cnt + 1]) % m;
            prop[vv] = (prop[vv] * prop[v] + 1) % m;
            dp[vv] = (prop[vv] * sumL[vv].back()) % m;
            bfs(vv, v);
            cnt++;
        }
    };
    dfs(0, -1);
    bfs(0, -1);

    REP(i, 0, n) {
        print(dp[i]);
    }

    return 0;
}

