ll mod, down[100005], up[100005];

ll solve(ll u, ll p = 0){
    pai[u] = p;
    ll res = 1;
    for(ll v : adj[u])
        if(v != p)
            res *= (1 + solve(v, u));
    return down[u] = res;
}

void go(ll u, ll p = 0){
    vector<ll> vec;
    for(ll v : adj[u])
        if(v != p)
            vec.push_back(1 + down[v]);

    vector<ll> pref(vec), suff(vec);
    for(ll i = 1; i < pref.size(); i++)
        pref[i] = (pref[i]*pref[i-1])%mod;
    for(ll i = ll(suff.size()) - 2; i >= 0; i--)
        suff[i] = (suff[i]*suff[i+1])%mod;

    for(ll i = 0; i < adj[u].size(); i++){
        ll v = adj[u][i];
        ll esq = (i-1 >= 0 ? pref[i-1] : 1);
        ll dir = (i+1 < vec.size() ? suff[i+1] : 1);
        up[v] = (1 + esq*dir)%mod;
    }
}

