		v_rev[y].push_back(v[x].size()-1);
		dp[x].push_back(-1);
		dp[y].push_back(-1);
		ru[x].push_back(-1);
		ru[y].push_back(-1);
		ru2[x].push_back(-1);
		ru2[y].push_back(-1);
	}
	//
	reg(i,1,n){
		// cout<<"current: "<<i<<endl;
		cout<<f(i,1e9,true)<<endl;
	}
	return 0;
}

