int N, M;
vector<int> adj[110000];
ll dp1[110000];
ll dp2[110000];

void dfs(int nd, int prv = -1) {
	ll res = 1;
	for (int child : adj[nd]) {
		if (child == prv) continue;
		dfs(child, nd);
		res *= dp1[child];
	}
	dp1[nd] = res + 1;
}

void dfs2(int nd, int prv = -1) {
	if (prv == -1) dp2[nd] = 1;
	vector<ll> lprod = vector<ll>(adj[nd].size(), 1);
	vector<ll> rprod = vector<ll>(adj[nd].size(), 1);
	for (int i = 0; i < adj[nd].size(); i++) {
		int child = adj[nd][i];
		if (i - 1 >= 0) lprod[i] = lprod[i - 1];
		if (child == prv) continue;
		lprod[i] *= dp1[child]; lprod[i] %= M;
	}
	for (int i = (int)adj[nd].size() - 1; i >= 0; i--) {
		int child = adj[nd][i];
		if (i + 1 < adj[nd].size()) rprod[i] = rprod[i + 1];
		if (child == prv) continue;
		rprod[i] *= dp1[child]; rprod[i] %= M;
	}
	for (int i = 0; i < adj[nd].size(); i++) {
		int child = adj[nd][i];
		if (prv == child) continue;
		ll rest_prod = 1;
		if (i - 1 >= 0) rest_prod = rest_prod * lprod[i - 1] % M;
		if (i + 1 < adj[nd].size()) rest_prod = rest_prod * rprod[i + 1] % M;
		dp2[child] = (rest_prod * dp2[nd] + 1) % M;
		dfs2(child, nd);
	}
}

ll ans[110000];
void dfs3(int nd, int prv = -1) {
	ans[nd] = dp2[nd];
	for (int child : adj[nd]) {
		if (child == prv) continue;
		ans[nd] *= dp1[child];
		ans[nd] %= M;
		dfs3(child, nd);
	}
}

