int mod;
const int N = 1e5+5;
vector<int> G[N], child[N];
vector<pll> prv[N], suf[N];
pll down[N], up[N];
// (all_white, sth_is_black)
// omnidirectional dp( O(n) )


int add(int a, int b){
	return (a + b) % mod;
}
int mul(int a, int b){
	return (ll)a * b % mod;
}

pll merge(const pll& a,const pll& b){
	// calculate subtrees, not considering the root
	pll p;
	p.F = mul(a.F, b.F);
	p.S = add(mul(a.S, add(b.F, b.S)), mul(a.F, b.S));
	return p;
}

pll ans(const pll& a){
	pll p;
	p.F = a.F;
	p.S = add(a.F, a.S);
	return p;
}
void dfs1(int a, int parent) {
	pll p = {1, 0};
	for(int b : G[a]){
		if(b != parent){
			child[a].pb(b);
			dfs1(b, a);
			p = merge(p, down[b]);
		}
	}

	down[a] = ans(p);
}

void dfs2(int a, int parent){
	rep(i, SZ(child[a])){
		pll p{1, 0};
		if(i != 0)	p = merge(p, prv[a][i-1]);
		if(i != SZ(child[a]) - 1)	p = merge(p, suf[a][i+1]);
		if(a != 1)	p = merge(p, up[a]);
		up[child[a][i]] = ans(p);
		dfs2(child[a][i], a);
	}
}

