	// calculate prefix sums and suffix sums
	for(int a = 1; a <= n; a++){
		pll p{1, 0};
		for(int b = 0; b < SZ(child[a]); b++){
			p = merge(p, down[child[a][b]]);
			prv[a].pb(p);
		}
		p = {1, 0};
		for(int b = SZ(child[a]) - 1; b >= 0; b--){
			p = merge(p, down[child[a][b]]);
			suf[a].pb(p);
		}
		reverse(suf[a].begin(), suf[a].end());
	}
	dfs2(1, -1);
	for(int a = 1; a <= n; a++){
		pll p{1, 0};
		if(a != 1)	p = merge(p, up[a]);
		if(!child[a].empty())	p = merge(p, prv[a].back());
		p = ans(p);
