}

int x, y;
void extendedEuclid(int a, int b){
	if(b == 0){
		y = 0;
		x = 1;
		return;
	}

	extendedEuclid(b, a%b);
	int cx = y;
	int cy = x - (a/b)*y;

	x = cx;
	y = cy;
}

int modInverse(int a, int m){
	extendedEuclid(a, m);
	return (x%m + m)%m;
}

void solve1(int root, int p, int m){
	dp[root] = 1;
	for(int child: v[root]){
		if(child != p){
			solve1(child, root, m);	
			dp[root] = (dp[root] * (dp[child]+1))%m;
		}
	}
}

void solve2(int root, int p, int m){
	dp2[root] = dp[root];
	if(p != 0){
		dp2[root] = (dp2[root] * (dp2[p]/(dp[root] + 1) + 1))%m;
	}

	for(int child : v[root]){
		if(child != p){
			solve2(child, root, m);
		}
	}
}



