ll us(ll a, ll b){
	ll ans = 1;
	while (b){
		if (b & 1){
			ans *= a;
			ans %= mod;
		}
		a *= a;
		a %= mod;
		b >>= 1;
	}
	return ans;
}

ll bol(ll a, ll b){
	a %= mod;
	b %= mod;
	if (a == 0 && b == 0) return 0;
	ll gcd = __gcd(a, b);
	a /= gcd;
	b /= gcd;
	assert(__gcd(b, mod) == 1);
	ll ans = a*us(b, phi-1);
	ans %= mod;
	return ans;
}

ll calphi(ll a){
	ll ans = a;
	for (int i = 2; i <= sqrt(a); i++){
		if (a % i == 0){
			ans /= i;
			ans *= (i-1);
			while (a % i == 0) a /= i;
		}
	}
	if (a > 1){
		ans /= a;
		ans *= a-1;
	}
	return ans;
}

void dfs1(int node, int ata){
	par[node] = ata;
	for (int ch: adj[node]){
		if (ch == ata) continue;
		dfs1(ch, node);
	}

	ll ans = 1;
	vector<int> grp;
	vector<int> grpi;
	for (int ch: adj[node]){
		if (ch == ata) continue;
		grp.pb((1+dpalt[ch])%mod);
		grpi.pb(ch);
		ans *= 1 + dpalt[ch];
		ans %= mod;
	}

	vector<int> pr(grp.size());
	vector<int> sf(grp.size());
	if (grp.size() > 0) pr[0] = grp[0];
	for (int i = 1; i < grp.size(); i++) pr[i] = (pr[i-1]*grp[i])%mod;
	if (grp.size() > 0) sf[grp.size()-1] = grp[grp.size()-1];
	for (int i = grp.size()-1; i >= 0; i--) sf[i] = (sf[i+1]*grp[i])%mod;
	for (int i = 1; i < (int)grp.size()-1; i++){
		dp3[grpi[i]] = (sf[i-1]*pr[i+1])%mod;
	}
	if (grp.size() > 0) dp3[grpi[0]] = pr[1];
	if (grp.size() > 0) dp3[grpi[grp.size()-1]] = sf[grp.size()-2];
	dpalt[node] = ans; 
}

