map<int, map<int, int>> memo;  // key = from, to
map<int, map<int, bool>> used; // key = from, to

int mod;
int dfs(int u, int p = -1) {
    if (used[p][u]) return memo[p][u];

    used[p][u] = true;
    int ret = 1;
    for (auto v : to[u]) {
        if (v != p) ret = (ret * (dfs(v, u) + 1)) % mod;
    }
    return memo[p][u] = ret;
}

int dfs2(int u, int p = -1) {
    if (used[p][u]) return memo[p][u];

    used[p][u] = true;
    int ret = 1;
    vector<int> l = {1}, r = {1};
    rep(i, to[u].size()) {
        int lv = to[u][i];
        int rv = to[u][to[u].size() - i - 1];
        l.push_back(l.back() * (dfs2(lv, u) + 1) % mod);
        r.push_back(r.back() * (dfs2(rv, u) + 1) % mod);
        if (lv != p) ret = (ret * (dfs2(lv, u) + 1)) % mod;
    }
    reverse(all(r));

    rep(i, to[u].size()) {
        int v = to[u][i];
        used[v][u] = true;
        memo[v][u] = (l[i] * r[i + 1]) % mod;
    }
    // if (p != -1 and memo[p][u] != ret) {
    //     cout << "ERROR :" << p << " " << u << " " << memo[p][u] << " " << ret << endl;
    // }
    return memo[p][u] = ret;
}

