ll MOD;

vvi nxt;
vector<unordered_set<int>> send, receive;
unordered_map<int,unordered_map<int,ll>> memo;

int cnt = 0;

int main() {
    int N; scanf("%d%lld", &N, &MOD);
    nxt.resize(N);
    send.resize(N);
    receive.resize(N);

    rep(i, N-1) {
        int x, y;
        scanf("%d%d", &x, &y);
        --x; --y;
        nxt[x].pb(y);
        send[x].insert(y); receive[x].insert(y);
        nxt[y].pb(x);
        send[y].insert(x); receive[y].insert(x);
    }

    queue<ii> q;
    rep(u, N) {
        if (send[u].size() == 1) {
            int v = *send[u].begin();
            q.push(ii(v,u));
            send[u].erase(v);
        }
    }

    while (!q.empty()) {
        ii t = q.front(); q.pop();
        int u = t.first, v = t.second;
        if (found(memo,u) && found(memo[u],v)) continue;

        receive[u].erase(v);

        ll ans = 1;
        for (int w: nxt[v]) {
            if (w == u) continue;
            (ans *= (1 + memo[v][w])) %= MOD;
        }
        memo[u][v] = ans;

        if (receive[u].size() == 1) {
            int w = *receive[u].begin();
            if (found(receive[w],u))
                q.push(ii(w,u));
            send[u].erase(w);
        }
        if (receive[u].size() == 0) {
            if (send[u].size() > 0) {
                for (int w : send[u]) {
                    if (found(receive[w],u))
                        q.push(ii(w,u));
                }
                send[u].clear();
            }
        }
    }

    rep(u, N) {
        ll ans = 1;
        for (int v: nxt[u]) {
            if (!(found(memo,u) && found(memo[u],v))) assert(false);
            (ans *= (1 + memo[u][v])) %= MOD;
        }
        printf("%lld\n", ans);
    }
    cout << std::flush;

    return 0;
}

