	father[x]=fa;
	ll ret=1ll;
	for(int i=0;i<g[x].size();i++){
		int to=g[x][i];
		if(to==fa) continue;
		dfs1(to,x);
		ret=ll(ret*ll(dp[to][0]+1ll)%mod)%mod;
	}
	dp[x][0]=ret;
