void dfs2(int x,int fa){
	vector <ll> v1,v2; 
	for(int i=0;i<g[x].size();i++){
		int to=g[x][i];
		if(to==fa){
			v1.pb(1ll);
			continue;
		}
		v1.pb(ll(dp[to][0]+1ll)%mod);
	}
	for(int i=1;i<g[x].size();i++) v1[i]=ll(v1[i-1]*v1[i])%mod;
	for(int i=0;i<g[x].size();i++){
		int to=g[x][i];
		if(to==fa){
			v2.pb(1ll);
			continue;
		}
		v2.pb(ll(dp[to][0]+1ll)%mod); 
	}
	for(int i=g[x].size()-2;i>=0;i--) v2[i]=ll(v2[i+1]*v2[i])%mod;
	for(int i=0;i<g[x].size();i++){
		int to=g[x][i];
