const int maxn = 1e5 + 10;
int dp_up[maxn], dp_down[maxn], P[maxn], n, mod;
vector<int> adj[maxn];

int dfs_up(int u = 1, int par = 0)
{
    dp_up[u] = u == 1 ? 1 : (dp_up[par] * P[par] / (1 + dp_down[u]) + 1) % mod;
    P[u] = 1;
    for (int v : adj[u])
        if (v != par)
            P[u] *= 1 + dp_down[v];
    for (int v : adj[u])
        if (v != par)
            dfs_up(v, u);
}

int dfs_down(int u = 1, int par = 0)
{
    dp_down[u] = 1;
    for (int v : adj[u])
        if (v != par)
            (dp_down[u] *= dfs_down(v, u) + 1) %= mod;
    return dp_down[u];
}

