		}
		for (int i = (int) suff.size() - 2; i >= 0; i--) {
			mul(suff[i], suff[i + 1], mod);
		}
		ans[u] = pref.back() * ways % mod;
		int i = 0;
		for (int v : adj[u]) {
			if (v == p) continue;
			ll new_ways = 1;
			mul(new_ways, pref[i], mod);
			mul(new_ways, suff[i + 1], mod);
			mul(new_ways, ways, mod);
			add(new_ways, 1ll, mod);
			dfs_two(v, u, new_ways);
			i++;
		}
	}
};

