const int N = 100000 + 10;
struct E
{
    int v, next;
} edge[N << 1];
int head[N], e;
void addedge(int u, int v)
{
    edge[e].v = v;
    edge[e].next = head[u];
    head[u] = e++;
}

int n;
LL mod;

LL fa[N], idx[N], dp1[N], dpf[N], dp2[N];

LL dfs1(int u, int f)
{
    fa[u] = f;
    LL ret = 1;
    int cnt = 0;
    for (int i = head[u]; ~i; i = edge[i].next)
    {
        int v = edge[i].v;
        if (v == f) continue;
        cnt++;
        // idx[u] = cnt;
        LL val = dfs1(v, u);
        ret = ret * (1 + val) % mod;
    }
    return dp1[u] = ret;
}

LL pre[N], suf[N];
LL pref[N], suff[N];
LL val[N];

LL dfs2(int u, int f)
{
    int cnt = 0;
    for (int i = head[u]; ~i; i = edge[i].next)
    {
        int v = edge[i].v;
        if (v == f) continue;
        ++cnt;
        idx[cnt] = v;
        val[cnt] = dp1[v];
    }

    pre[0] = 1;
    for (int i = 1; i <= cnt; i++) pre[i] = pre[i - 1] * (1 + val[i]) % mod;
    suf[cnt + 1] = 1;
    for (int i = cnt; i >= 1; i--) suf[i] = suf[i + 1] * (1 + val[i]) % mod;

    for (int i = 1; i <= cnt; i++)
    {
        int p = idx[i];

        LL v1 = pre[i - 1];
        LL v2 = suf[i + 1];
        LL v = v1 * v2 % mod;  // 同级

        dp2[p] = (v * dpf[u] + 1) % mod * dp1[p] % mod;
        dpf[p] = (dpf[u] * v + 1) % mod;
    }

    for (int i = head[u]; ~i; i = edge[i].next)
    {
        int v = edge[i].v;
        if (v == f) continue;
        dfs2(v, u);
    }
}

