ll ADD(ll x, ll y) { return (x+y) % MOD; }
ll MUL(ll x, ll y) { return x*y % MOD; }

vvi nxt;
unordered_map<ll,ll> memo;

ll f(int u, int v) {
    ll k = 131072LL * u + v;
    if (found(memo,k)) return memo[k];

    ll ans = 1;
    for (int w: nxt[v]) {
        if (w == u) continue;
        ans = MUL(ans, f(v, w));
    }
    return memo[k] = ADD(ans, 1);
}

