const int mxn = 100010;
ll dp[mxn], tmp[mxn], ans[mxn], mod;
int N;

vector<int> adj[mxn], pre[mxn], suff[mxn], children[mxn];

void dfs_dp(int node, int parent) {
	for(auto x:adj[node])
		if(x!=parent) dfs_dp(x, node);

	dp[node] = 1ll; 
	for(auto x:adj[node])
		if(x!=parent) {
			dp[node]*=(dp[x]+1);
			dp[node]%=mod;
			children[node].push_back(x);
		}
}

void calc_pre_suff() {
	for(int node=1; node<=N; node++) {
		int sz = (int) children[node].size();
		if(!sz or sz==1) continue;
		pre[node].resize(sz);
		suff[node].resize(sz);
		pre[node][0] = dp[children[node][0]]+1;
		for(int i=1; i<sz; i++)
			pre[node][i] = pre[node][i-1]*(dp[children[node][i]]+1)%mod;
		suff[node][sz-1] = dp[children[node][sz-1]]+1;
		for(int i=sz-2; i>=0; i--)
			suff[node][i] = suff[node][i+1]*(dp[children[node][i]]+1)%mod;
	}
}

ll get_range(int node, int idx) {
	int sz = (int) children[node].size();
	if(sz==1) return 1ll;
	if(idx==0) return suff[node][1];
	if(idx==sz-1) return pre[node][sz-2];
	return suff[node][idx+1]*pre[node][idx-1]%mod;
}


void dfs_ans(int node, int parent, ll val_of_parent=0ll) { 
	ans[node] = val_of_parent+1;
	for(auto x:adj[node])
		if(x!=parent) ans[node]*=(dp[x]+1), ans[node]%=mod;

	for(int i=0; i<(int) children[node].size(); i++) {
		int next = children[node][i];
		ll new_val = (val_of_parent+1)*get_range(node, i)%mod;
		dfs_ans(next, node, new_val);
	}
}

void process(int root) {
	dfs_dp(root, -1);
	calc_pre_suff();
	dfs_ans(root, -1);
}

int main() {
	ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);

	cin>>N>>mod;
	for(int i=0; i<N-1; i++) {
		int x, y; cin>>x>>y;
		adj[x].push_back(y);
		adj[y].push_back(x);
	}

	process(N);

	for(int i=1; i<=N; i++)
		cout << ans[i] << '\n';

	return 0;
}

