using Graph = adjacency_list<nullptr_t>;
int constexpr Io97 = 1'000'000'007;
using MIo97 = modulo<Io97>;

void solve(int N, int M, Graph const &G) {
  auto const tree = make_rooted_tree(G, 0);
  vector<lli> dr(N); vector<MIo97> mr(N);
  RREP(i, tree.size) {
    size_t u = tree.topo[i];
    lli val = 1; MIo97 mval = 1;
    for (auto &&v : tree.children[u]) {
      val *= (dr[v] + 1); val %= M;
      mval *= (mr[v] + MIo97(1));
    }
    dr[u] = val; mr[u] = mval;
  }

  vector<lli> dpar(N); vector<MIo97> mpar(N);
  dpar[0] = 0, mpar[0] = 0;
  stack<size_t> stk; stk.push(0);
  while (!stk.empty()) {
    size_t u = stk.top(); stk.pop();
    for (auto &&v : tree.children[u]) {
      dpar[v] = dr[u]; mpar[v] = mr[u];
      stk.push(v);
    }
  }

  REP(u, N) {
    // dpar[u] / (dr[u]+1)
    lli p, q;
    extgcd<lli>(M, Io97, p, q);
    lli xd = (Io97 * q * dpar[u] + M * p * mpar[u].data());
    assert(xd % (dr[u] + 1) == 0);
    lli x = xd / (dr[u] + 1);
    lli y = (dr[u] * (x + 1)) % M;
    while (y < 0) { y += M; }
    for (auto &&c : tree.children[u]) {
      dpar[c] = y;
    }
    cout << y << endl;
  }
}

