inline void add_edge (int x, int y) { To[++e] = y; Next[e] = Begin[x]; Begin[x] = e; }

vector <int> Id[Maxn], Pre[Maxn], Suf[Maxn];

inline void dfs_pre (int x)
{
	f[x] = 1;
	for (int i = Begin[x]; i; i = Next[i])
	{
		int y = To[i]; 
		if (y == fa[x]) continue;
		fa[y] = x, Id[x].pb(y);
		dfs_pre (y);
		f[x] = (LL)f[x] * (f[y] + 1) % Mod;
	}
}

inline void dfs (int x)
{
	if (!Id[x].empty()) Pre[x].pb(f[Id[x][0]] + 1);
	for (int i = 1; i < Id[x].size(); ++i)
		Pre[x].pb((LL)(f[Id[x][i]] + 1) * Pre[x].back() % Mod);

	if (!Id[x].empty()) Suf[x].pb(f[Id[x][(int)Id[x].size() - 1]] + 1);
	for (int i = (int)Id[x].size() - 2; i >= 0; --i)
		Suf[x].pb((LL)(f[Id[x][i]] + 1) * Suf[x].back() % Mod);
	reverse (Suf[x].begin(), Suf[x].end());

	for (int i = 0; i < Id[x].size(); ++i)
	{
		int y = Id[x][i], pre = 1, suf = 1;
		if (i) pre = Pre[x][i - 1];
		if (i != (int)Id[x].size() - 1) suf = Suf[x][i + 1];
		g[y] = ((LL)pre * suf % Mod * g[x] % Mod) + 1;
		dfs (y);
	}
}

