struct Rerooting {
  struct DP {
    mint d;
    DP():d(1) {}
    DP& operator+=(const DP& a) {
      d *= a.d;
      return *this;
    }
    DP& addRoot() {
      d += 1;
      return *this;
    }
    DP operator+(const DP& a) const { return DP(*this) += a;}
  };

  int n;
  vvi to;
  vv(DP) dp;
  v(DP) ans;
  Rerooting(int n=0):n(n),to(n),dp(n),ans(n) {}
  void add(int a, int b) {
    to[a].pb(b);
    to[b].pb(a);
  }
  void init() {
    dfs(0);
    bfs(0);
  }

  DP dfs(int v, int p=-1) {
    DP dpSum;
    dp[v] = v(DP)(sz(to[v]));
    rep(i,sz(to[v])) {
      int u = to[v][i];
      if (u == p) continue;
      dp[v][i] = dfs(u,v);
      dpSum += dp[v][i];
    }
    return dpSum.addRoot();
  }
  void bfs(int v, const DP& dpP=DP(), int p=-1) {
    int deg = sz(to[v]);
    rep(i,deg) if (to[v][i] == p) dp[v][i] = dpP;

    v(DP) dpSumL(deg+1);
    rep(i,deg) dpSumL[i+1] = dpSumL[i] + dp[v][i];
    v(DP) dpSumR(deg+1);
    for (int i = deg-1; i >= 0; --i) dpSumR[i] = dpSumR[i+1] + dp[v][i];
    ans[v] = DP(dpSumL[deg]).addRoot();

    rep(i,deg) {
      int u = to[v][i];
      if (u == p) continue;
      bfs(u, (dpSumL[i] + dpSumR[i+1]).addRoot(), v);
    }
  }
};


