void dfsBottomUp(int v, int p = -1) {
  countDownwards[v] = 1;
  for (int c : neighbours[v]) {
    if (c != p) {
      dfsBottomUp(c, v);
      children[v].push_back(c);
      mulSelf(countDownwards[v], add(countDownwards[c], 1));
    }
  }
}

void dfsTopDown(int v, int p = -1) {
  for (int i = 0; i < (int)children[v].size(); i++) {
    int c = children[v][i];
    countUpwards[c] = countUpwards[v];
    if (i - 1 >= 0)
      mulSelf(countUpwards[c], prefProd[v][i - 1]);
    if (i + 1 < (int)children[v].size())
      mulSelf(countUpwards[c], suffProd[v][i + 1]);
    addSelf(countUpwards[c], 1);
    dfsTopDown(c, v);
  }
}

