#define MAXN 110000
ll n,m;
vector<vector<int>>edges(MAXN, vector<int>());

ll dp1[MAXN];
void dfs1(int x, int p=-1){
  dp1[x]=1;
  for(auto c:edges[x]){
    if(c==p)continue;
    dfs1(c,x);
    dp1[x] *= dp1[c];
    dp1[x] %= m;
  }
  dp1[x]++;
  dp1[x] %= m;
}

ll dp2[MAXN];
void dfs2(int x, int p=-1){
  if(p==-1)dp2[x]=1;
  int ec=edges[x].size();

  vector<ll> lprod;
  rep(i, ec){
    int c = edges[x][i];

    if(c==p){
      if(lprod.size())lprod.push_back(lprod.back());
      else lprod.push_back(1);
      continue;
    }


    if(lprod.size()){
      lprod.push_back(lprod.back());
    }else{
      lprod.push_back(dp1[c]);
    }

    if(i)lprod.back() *= dp1[c];
    lprod.back() %= m;
  }

  vector<ll> rprod;
  rrep(i, ec){
    int c = edges[x][i];

    if(c==p){
      if(rprod.size())rprod.push_back(rprod.back());
      else rprod.push_back(1);
      continue;
    }

    if(rprod.size()){
      rprod.push_back(rprod.back());
    }else{
      rprod.push_back(dp1[c]);
    }

    if(i<ec-1)rprod.back() *= dp1[c];
    rprod.back() %= m;
  }
  reverse(rprod.begin(), rprod.end());

//for(auto c: lprod)cout<<c<<' ';cout<<endl;
//for(auto c: rprod)cout<<c<<' ';cout<<endl;


  rep(i, ec){
    int c = edges[x][i];
    if(c==p)continue;
    dp2[c] = dp2[x];
    if(i)dp2[c] *= lprod[i-1];
    if(i<ec-1)dp2[c] *= rprod[i+1];
    dp2[c]++;
    dp2[c]%=m;
    dfs2(c, x);
  }
}

ll ans[MAXN];
void dfs3(int now, int p=-1){
  ans[now] = dp2[now];
  for(auto c:edges[now]){
    if(c==p)continue;
    ans[now] *= dp1[c];
    ans[now] %= m;
    dfs3(c, now);
  }
}

