void O() {
    int n;
    cin >> n;
    vector<vector<int>> cnt(n + 1, vector<int>(n + 1, 0));
    for(int i = 1; i <= n; i++) {
        for(int j = 1; j <= n; j++) {
            cin >> cnt[i][j];
        }
    }
    vector<int> dp((1 << n), 0);
    dp[0] = 1;
    for(int mask = 1; mask < (1 << n); mask++) {
        bitset<32> bt(mask);
        int i = bt.count();
        //cout<<i<<endl;
        for(int j = 0; j < n; j++) {
            if(cnt[i][j + 1] == 1 && ((mask & (1 << j)) != 0)) {
                dp[mask] = (dp[mask] + dp[mask - (1 << j)]) % mod;
            }
        }
    }
    cout << dp[(1 << n) - 1] << endl;
}
ll PHelper(vector<vector<ll>>& dp, vector<vector<int>>& child, int cur, int flag) {
    if(dp[cur][flag] != -1)
        return dp[cur][flag];
    ll ans = 1;
    for(auto c : child[cur]) {
        if(flag == 1)
            ans = (ans * PHelper(dp, child, c, 0)) % mod;
        else
            ans = (ans * (PHelper(dp, child, c, 0) + PHelper(dp, child, c, 1))) % mod;
    }
    dp[cur][flag] = ans;
    return ans;
}
