void U() {
    int n;
    cin >> n;
    vector<vector<ll>> a(n + 1, vector<ll>(n + 1));
    for(int i = 0; i < n; i++) {
        for(int j = 0; j < n; j++) {
            cin >> a[i][j];
        }
    }
    int maxn = (1 << n);
    vector<ll> cost(maxn, 0);
    vector<ll> dp(maxn, 0);
    for(int mask = 0; mask < maxn; mask++) {
        for(int i = 0; i < n; i++) {
            for(int j = i + 1; j < n; j++) {
                if(((1 << i)&mask) && ((1 << j)&mask)) {
                    cost[mask] += a[i][j];
                }
            }
        }
    }
    for(int mask = 0; mask < maxn; mask++) {
        for(int submask = mask; submask > 0; submask = (submask - 1)&mask) {
            dp[mask] = max(dp[mask], dp[mask - submask] + cost[submask]);
        }
    }
    cout << dp[maxn - 1] << endl;
}
void Vdfs1(vector<ll>& dp, vvl& child, ll cur, ll mod) {
    dp[cur] = 1;
    for(auto s : child[cur]) {
        Vdfs1(dp, child, s, mod);
        (dp[cur] *= (dp[s] + 1)) %= mod;
    }
}
void Vdfs2(vector<ll>& ans, vector<ll> &dp,vvl& child, ll cur, ll fac, ll mod) {
    ans[cur] = dp[cur] * fac % mod;
    vector<ll> prefix, suffix;
    for(auto s : child[cur]) {
        prefix.push_back(dp[s] + 1);
    }
    suffix = prefix;
    for(int i = 1; i < prefix.size(); i++) {
        (prefix[i] *= prefix[i - 1]) %= mod;
    }
    for(int i = suffix.size() - 2; i >= 0; i--) {
        (suffix[i] *= suffix[i + 1]) %= mod;
    }
    int cnt = 0;
    for(auto s : child[cur]) {
        //计算当前的cur对其孩子的贡献度
        ll curcontribution = fac;
        if(cnt > 0) {
            curcontribution *= prefix[cnt - 1];
            curcontribution %= mod;
        }
        if(cnt < suffix.size() - 1) {
            curcontribution *= suffix[cnt + 1];
            curcontribution %= mod;
        }
        //这里curcontribution+1是指有可能父节点不对该子节点做出贡献
        Vdfs2(ans, dp, child, s, curcontribution + 1, mod);
    }
}
