// ALL to. dp[node][to]
// return 1 + PROD(dp[node][to])
ll out(int node, int from) {
    ll res = 1;
    for(auto to : g[node].edge) {
        if(to == from)  continue;
        if(!dp[node].count(to))  dp[node][to] = out(to, node);
        res = res * dp[node][to] % m;
    }
    return (1 + res) % m;
}

// ALL from. dp[from][node]
void in(int node) {
    vector<ll> vals;
    for(auto to : g[node].edge)  vals.push_back(dp[node][to]);

    vector<ll> left{1}, right{1};
    int sz = vals.size();
    for(int i = 0; i < sz; i++) {
        left.push_back( left.back() * vals[i] % m );
        right.push_back( right.back() * vals[sz-1-i] % m );
    }
    right.pop_back();  reverse(begin(right), end(right));

    for(int i = 0; i < sz; i++) {
        int from = g[node].edge[i];
        if(dp[from].count(node))  continue;
        dp[from][node] = (left[i] * right[i] + 1) % m;
        in(from);
    }
}

