vi es[100010];
vl dp[100010];
ll dfs(int x,int pre) {

	ll res = 1;
	int i = -1;
	dp[x] = vl(es[x].size());
	for (auto v : es[x]) {
		i++;
		if (v == pre) continue;
		dp[x][i] = dfs(v, x) + 1;
		res *= dp[x][i];
		res %= m;
	}

