const int MM = 2e5 + 4;
ll mod;
ll dp[MM], ans[MM];
vector <int> T[MM], suf[MM], pref[MM];
ll dfs(int u, int p) {
	ll ans = 1;
	for(int i = 0; i < T[u].size(); i++) {
		int v = T[u][i];
		if(v != p) {
			ans = (ans * (1 + dfs(v, u))) % mod;
		}
	}
	ll k = 1;
	pref[u].push_back(1);
	for(int i = 0; i < T[u].size(); i++) {
		int v = T[u][i];
		if(v != p) {
			k = (k * (1 + dp[v])) % mod;
		}
		pref[u].push_back(k);
	}
	k = 1;
	for(int i = (int)T[u].size() - 1; i >= 0; i--) {
		int v = T[u][i];
		if(v != p) {
			k = (k * (1 + dp[v])) % mod;
		}
		suf[u].push_back(k);
	}
	reverse(suf[u].begin(), suf[u].end());
	suf[u].push_back(1);
	return dp[u] = ans;
}
void dfs2(int u, int p, int ind, ll tp) {
	ans[u] = 1;
	if(p != -1) {
		ans[u] = (pref[p][ind] * suf[p][ind + 1]) % mod;
		ans[u] = (ans[u] * tp) % mod;
		ans[u]++;
	}
	for(int i = 0; i < T[u].size(); i++) {
		int v = T[u][i];
		if(v != p) {
			dfs2(v, u, i, ans[u]);
		}
	}
	for(int v : T[u]) {
		if(v != p) {
			ans[u] = (ans[u] * (1 + dp[v])) % mod;
		}
	}
}
