#include <bits/stdc++.h>

using namespace std;

using ll = long long;

struct Edge {
    int src, dst, w;
    Edge(int _s, int _d, int _w = -1) : src(_s), dst(_d), w(_w) {}
    Edge() : w(-1) {}
};

int N, MOD;
vector<vector<Edge>> adj;

int Dfs(const int p, const int v) {
    int res = 1;
    for (auto &&e : adj[v]) {
        if (e.dst == p) continue;
        if (e.w == -1) e.w = Dfs(v, e.dst);
        (res *= (e.w + 1)) %= MOD;
    }
    return res % MOD;
}

int main() {
    cin.tie(0); ios::sync_with_stdio(false);

    cin >> N >> MOD;

    adj.resize(N);
    for (int i = 0, x, y; i + 1 < N; ++i) {
        cin >> x >> y;
        --x; --y;
        adj[x].emplace_back(Edge(x, y));
        adj[y].emplace_back(Edge(y, x));
    }

    for (int v = 0; v < N; ++v) {
        for (auto &&e : adj[v])
            if (e.w == -1) e.w = Dfs(e.src, e.dst);
    }

    for (int v = 0; v < N; ++v) {
        int ans = 1;
        for (const auto &e : adj[v])
            (ans *= (e.w + 1)) %= MOD;
        cout << ans << '\n';
    }

    return 0;
}

#include <algorithm>
#include <cstdio>
#include <cstring>
