const int MaxN = 100000 + 5;

struct Graph {
  int cnte;
  int Head[MaxN], Next[MaxN * 2], To[MaxN * 2];

  inline void addEdge(int from, int to) {
    cnte++; To[cnte] = to;
    Next[cnte] = Head[from]; Head[from] = cnte;
  }
};

int N, Mod;
Graph G;
std::vector<int> A[MaxN], Pre[MaxN], Suf[MaxN];
int Dp[MaxN];
int Ans[MaxN];

inline int add(int x, int y) { return (x += y) >= Mod ? x - Mod : x; }
inline int sub(int x, int y) { return (x -= y) < 0 ? x + Mod : x; }
inline int mul(int x, int y) { return 1LL * x * y % Mod; }

void init() {
  scanf("%d %d", &N, &Mod);
  for (int i = 1; i < N; ++i) {
    int u, v;
    scanf("%d %d", &u, &v);
    G.addEdge(u, v);
    G.addEdge(v, u);
  }
}

void dfs1(int u, int fa) {
  int s = 0;
  A[u].push_back(1);
  Dp[u] = 1;
  for (int i = G.Head[u]; i; i = G.Next[i]) {
    int v = G.To[i];
    if (v == fa) continue;
    s++;
    dfs1(v, u);
    Dp[u] = mul(Dp[u], add(Dp[v], 1));
    A[u].push_back(add(Dp[v], 1));
  }
  A[u].push_back(1);
  Pre[u].resize(s + 2), Suf[u].resize(s + 2);
  Pre[u][0] = 1; Suf[u][s + 1] = 1;
  for (int i = 1; i <= s; ++i) Pre[u][i] = Pre[u][i - 1] * A[u][i];
  for (int i = s; i >= 1; --i) Suf[u][i] = Suf[u][i + 1] * A[u][i];
}

void dfs2(int u, int fa, int f) {
  Ans[u] = mul(Dp[u], f);
  for (int i = G.Head[u], c = 0; i; i = G.Next[i]) {
    int v = G.To[i];
    if (v == fa) continue;
    c++;
    int fu = mul(mul(Pre[u][c - 1], Suf[u][c + 1]), f);
    dfs2(v, u, add(fu, 1));
  }
}

