template <typename T, typename D>
struct ReRooting {
  using L = function<T(T, D)>;
  using M = function<T(T, T)>;
  struct Edge {
    int to;
    D data;
    Edge(int to, D data) : to(to), data(data) {}
  };
  int n;
  vector<vector<Edge>> edges;
  L lift;
  M merge;
  T e;
  vector<vector<T>> dp;
  vector<int> par;
  vector<T> ans;
  ReRooting(int n, L lift, M merge, T e) : n(n), lift(lift), merge(merge), e(e) {
    edges = vector<vector<Edge>>(n);
  }
  void add_edge(int v, int u, D d) {
    edges[v].emplace_back(u, d);
  }
  T dfs(int v, int p = -1) {
    int l = edges[v].size();
    dp[v] = vector<T>(l);
    T ret = e;
    for (int i = 0; i < l; i++) {
      auto e = edges[v][i];
      if (e.to == p) {
        par[v] = i;
        continue;
      }
      dp[v][i] = lift(dfs(e.to, v), e.data);
      ret = merge(ret, dp[v][i]);
    }
    return ret;
  }
  void bfs(int v, T t) {
    if (par[v] != -1) {
      dp[v][par[v]] = lift(t, edges[v][par[v]].data);
    }
    int l = edges[v].size();
    vector<T> dpl(l + 1, e);
    vector<T> dpr(l + 1, e);
    for (int i = 0; i < l; i++) {
      dpl[i + 1] = merge(dpl[i], dp[v][i]);
    }
    for (int i = l - 1; i >= 0; i--) {
      dpr[i] = merge(dpr[i + 1], dp[v][i]);
    }
    ans[v] = dpr[0];
    for (int i = 0; i < l; i++) {
      if (i == par[v]) continue;
      int u = edges[v][i].to;
      bfs(u, merge(dpl[i], dpr[i + 1]));
    }
  }
  vector<T> solve() {
    dp = vector<vector<T>>(n);
    par = vector<int>(n, -1);
    ans = vector<T>(n);
    dfs(0);
    bfs(0, e);
    return ans;
  }
};

void solve() {
  int N, M;
  cin >> N >> M;
  ReRooting<int, int> root(N,
    [&](int a, int b) { return (a + 1) % M; },
    [&](int a, int b) { return (i64) a * b % M; },
    1);
  rep(i, N - 1) {
    int x, y;
    cin >> x >> y;
    x--, y--;
    root.add_edge(x, y, 0);
    root.add_edge(y, x, 0);
  }
  auto ans = root.solve();
  each(v, ans) cout << v << endl;
}

