using namespace std;

int n,m,in[100001],out[100001],excludent[100001];
vec(int) adj[100001],v[100001];

void dfs_in(int node,int par)
{
	in[node] = 1;
	for(auto it:adj[node])
		if(it!=par)
		{
			dfs_in(it,node);
			in[node] = (in[node] * (in[it] + 1))%m;
			v[node].pb(it);
		}
	if(size(v[node])==0) return;
	vec(int) pre(size(v[node]),1),suf(size(v[node]),1);
	pre[0] = in[v[node][0]]+1;
	suf[size(suf)-1] = in[v[node][size(v[node])-1]]+1;
	loop(i,1,size(pre)) pre[i] = (pre[i-1] * (in[v[node][i]]+1))%m;
	for(int i=size(suf)-2;i>=0;i--) suf[i] = (suf[i+1] * (in[v[node][i]]+1))%m;
	loop(i,0,size(v[node]))
	{
		excludent[v[node][i]] = 1;
		if(i>0) excludent[v[node][i]] = (excludent[v[node][i]] * pre[i-1])%m;
		if(i<size(v[node])-1) excludent[v[node][i]] = (excludent[v[node][i]] * suf[i+1])%m;
	}	
}

void dfs_out(int node,int par)
{
	out[node] = (excludent[node] * (out[par]+1))%m;
	for(auto it:adj[node])
		if(it!=par)
			dfs_out(it,node);
}

signed main()
{
	fastio(0);
	cin>>n>>m;
	loop(i,1,n)
	{
		int x,y;
		cin>>x>>y;
		adj[x].pb(y);
		adj[y].pb(x);
	}
	dfs_in(1,0);
	for(auto it:adj[1]) dfs_out(it,1);
	loop(i,1,n+1) cout<< (in[i] * (out[i]+1))%m <<endl;	
	return 0;		
}

