const int nax=1000*1007;
ll mod=1000*1000*1000+7;
const ll inf=1e18;

int n;

vi graf[nax];

ll dol[nax];
ll gor[nax];

ll wyn[nax];

void dfs1(int v, int oj)
{
	for (int &i : graf[v])
	{
		if (i==oj)
		{
			swap(i, graf[v].back());
			graf[v].pop_back();
			break;
		}
	}
	dol[v]=1;
	for (int i : graf[v])
	{
		dfs1(i, v);
		dol[v]=(dol[v]*dol[i])%mod;
	}
	dol[v]=(dol[v]+1)%mod;
}

ll pre[nax];
ll suf[nax];

void dfs2(int v, int oj)
{
	int r=graf[v].size();
	pre[0]=suf[r+1]=1;
	for (int i=1; i<=r; i++)
		pre[i]=(pre[i-1]*dol[graf[v][i-1]])%mod;
	for (int i=r; i; i--)
		suf[i]=(suf[i+1]*dol[graf[v][i-1]])%mod;
	ll mno=gor[v];
	//~ debug() << v;
	//~ debug() << range(pre+1, pre+1+r);
	//~ debug() << range(suf+1, suf+1+r);
	for (int i=1; i<=r; i++)
	{
		ll x=(pre[i-1]*suf[i+1])%mod;
		x=(x*mno+1)%mod;
		gor[graf[v][i-1]]=x;
	}
	wyn[v]=gor[v]%mod;
	for (int i : graf[v])
		wyn[v]=(wyn[v]*dol[i])%mod;
	for (int i : graf[v])
	{
		dfs2(i, v);
	}
}

