	{
		int a, b;
		scanf("%d%d", &a, &b);
		graf[a].push_back(b);
		graf[b].push_back(a);
	}
	dfs1(1, 0);
	gor[1]=1;
	dfs2(1, 0);

	for (int i=1; i<=n; i++)
		printf("%lld\n", wyn[i]);
	return 0;
}

