const int N=100100;
int n,m;
int dp[2*N];
int l[2*N],r[2*N];
vector<int>g[N];

int go(int id){
	if(~dp[id])return dp[id];
	dp[id]=1;
	for(auto v:g[r[id]])if(r[v]!=l[id])dp[id]=(ll)dp[id]*go(v)%m;
	return dp[id]=(dp[id]+1)%m;
}

main(){
	cin.tie(0);cin.sync_with_stdio(0);
	int id=0;
	cin>>n>>m;
	for(int i=0;i<n-1;++i){
		int u,v;cin>>u>>v;--u;--v;
		g[u].push_back(id);
		l[id]=u;r[id]=v;
		++id;
		g[v].push_back(id);
		l[id]=v;r[id]=u;
		++id;
	}
	memset(dp,-1,sizeof(dp));
	for(int i=0;i<n;++i){
		ll res=1;
		for(int j:g[i])res=res*go(j)%m;
		cout<<res<<" ";
	}
	cout<<endl;
}

