long long mod(const long long &a) {
	if (a >= 0)return a % m;
	return m - (-a) % m;
}
int mod(const int &a) {
	if (a >= 0)return a % m;
	return m - (-a) % m;
}


long long root(int i, int j) {//i,jはiからjへ行く辺でi黒の組み合わせ
	if (mem[i][j] != -1) {
		return mem[i][j];
	}
	long long temp = 1;
	auto iter = mem[i].begin();
	int size = mem[i].size();
	if (size == 1 && iter->first == j)return 1;
	for (int k = 0; k < size; k++)
	{
		if (iter->first == j) { iter++;continue; }
		temp = mod(temp *= (root(iter->first, i) +1));
		iter++;
	}
	return mem[i][j] = temp;
}

long long ans(int i) {
	auto iter = mem[i].begin();
	long long temp = 1;
	int size = mem[i].size();
	for (int k = 0; k < size; k++)
	{
		temp = mod(temp *= (root(iter->first,i)+1));
		iter++;
	}
	return temp;
}



