vector<long long> parents;
typedef pair<ll,ll> pll;
vector<ll> DP0;
vector<ll> DP1;

//0を根として木を張ってみる
void treeconstruct() {
	queue<pll> q;
	q.push(pll(0, 0));
	while (!q.empty()) {
		pll next = q.front();
		q.pop();
		parents[next.first] = next.second;
		for (ll child : childs[next.first]) {
			if (child == next.second)continue;
			q.push(pll(child, next.first));
		}
	}
}

ll dp0(ll node) {
	if (DP0[node] != -1)return DP0[node];
	ll ans = 1;
	for (ll child : childs[node]) {
		if (child == parents[node])continue;
		ans = (ans * (dp0(child) + 1)) % M;
	}
	DP0[node] = ans;
	return ans;
}

ll dp1(long long node) {
	if (DP1[node] != -1)return DP1[node];
	if (node == 0)return 0;
	ll ans = (dp1(parents[node])+1)%M;
	for (ll child : childs[parents[node]]) {
		if (child == node || child == parents[parents[node]])continue;
		ans = (ans * (dp0(child) + 1)) % M;
	}
	DP1[node] = ans;
	return ans;
}

