int n, m;
vector <int> edge[100005];
long long ways[100005], ans[100005];

void pre(int id, int p) {
	ways[id] = 1LL;
	for (int i = 0; i < edge[id].size(); i++) {
		int to = edge[id][i];
		if (to == p) continue;
		pre(to, id);
		ways[id] = (ways[id] * ways[to]) % m;
	}
	ways[id] = (ways[id] + 1) % m;
}

void solve(int id, int p, int cool) {
	ans[id] = cool;
	vector <long long> l, r;

	for (int i = 0; i < edge[id].size(); i++) {
		int to = edge[id][i];
		if (to == p) continue;
		ans[id] = (ans[id] * ways[to]) % m;
		l.push_back(ways[to]);
	}
	r = l;

	for (int i = 1; i < l.size(); i++) l[i] = (l[i - 1] * l[i]) % m;
	for (int i = r.size() - 2; i >= 0; i--) r[i] = (r[i + 1] * r[i]) % m;

	int child = 0;

	for (int i = 0; i < edge[id].size(); i++) {
		int to = edge[id][i];
		if (to == p) continue;
		long long tmp = cool;
		if (child - 1 >= 0) tmp = (tmp * l[child - 1]) % m;
		if (child + 1 < r.size()) tmp = (tmp * r[child + 1]) % m;
		tmp = (tmp + 1) % m;
		solve(to, id, tmp);
		child++;
	}
}

