	scanf("%d%d", &n, &m);

	for (int i = 0; i < n - 1; i++) {
		int x, y;
		scanf("%d%d", &x, &y);
		edge[x].push_back(y);
		edge[y].push_back(x);
	}

	pre(1, -1);
	solve(1, -1, 1);

	for (int i = 1; i <= n; i++) printf("%lld\n", ans[i]);
}

