ll calc_X(int v, pair<int,ll> key) {
  int pos = lower_bound(ALL(childs[v]), key) - childs[v].begin();
  ll X = prod_l[v][pos] * prod_r[v][pos+1] % MOD;
  // cout << "MOD=" << MOD << endl;
  // pv(ALL(childs[v]));
  // pv(ALL(prod_l[v]));
  // pv(ALL(prod_r[v]));
  // cout << "calc X=" << X << endl;
  return X;
}

void ready_X(int v, int prev) {
  vector< pair<int, ll> > c;
  for (int u : g[v])  {
    if (u != prev) {
      c.push_back({u, 1+dp1[u]});
    } else {
      c.push_back({u, calc_X(u, make_pair(v, 1+dp1[v]))});
    }
  }
  sort(ALL(c));
  int M = (int)c.size();
  vector<ll> l(M+1);
  vector<ll> r(M+1);
  l[0] = 1;
  for (int i = 0; i < M; i++) { l[i+1] = l[i] * c[i].second % MOD; }
  r[M] = 1;
  for (int i = M-1; i >= 0; i--) { r[i] = r[i+1] * c[i].second % MOD; }
  childs[v] = c;
  prod_l[v] = l;
  prod_r[v] = r;
}

void dfs1(int v, int prev) {
  parent[v] = prev;
  ll res = 1;
  for (int u : g[v]) if (u != prev) {
    dfs1(u, v);
    res *= (1 + dp1[u]);
    res %= MOD;
  }
  dp1[v] = res;
}

void dfs2(int v) {
  if (dp2[v] != -1) return;
  if (parent[v] == -1) {
    dp2[v] = dp1[v] % MOD;
    ready_X(v, -1);
    return;
  }
  dfs2(parent[v]);
  ll X = calc_X(parent[v], make_pair(v, 1+dp1[v]));
  // ll X2 = dp2[parent[v]] / (1+dp1[v]);
  // cout << "actual   X=" << X << endl;
  // cout << "expected X=" << X2 % MOD << endl;
  ll res = 1;
  for (int u : g[v]) {
    if (u != parent[v]) {
      res *= (1+dp1[u]);
    } else {
      res *= (1+X);
    }
    res %= MOD;
  }
  dp2[v] = res;
  ready_X(v, parent[v]);
}

