void dfs1(int curr = 0, int prev = -1) {
    if (prev != -1) {
        (res1[curr] *= res1[prev]) %= MOD;
        (++res1[curr]) %= MOD;
    }
    stack<ll> s;
    ll prod = 1;
    for (int i = adj[curr].size() - 1; i >= 0; i--) {
        if (adj[curr][i] == prev) continue;
        s.push(prod);
        (prod *= 1 + res0[adj[curr][i]]) %= MOD;
