void Build(int nod=1, int l=1, int r=f.sz){
    if(l>r) return;
    if(l==r){
        sg[nod]=f[l-1]%mod;
        return;
    }
    int mid=(l+r)/2;
    Build(2*nod,l,mid);
    Build(2*nod+1,mid+1,r);
    sg[nod]=(sg[2*nod]*sg[2*nod+1])%mod;
}

ll Qry(int lt, int rt, int nod=1, int l=1, int r=f.sz){
    if(lt>rt) return 1;
    if(l>rt || r<lt) return 1;
    if(l>=lt && r<=rt) return sg[nod];
    int mid=(l+r)/2;
    return (Qry(lt,rt,2*nod,l,mid)*Qry(lt,rt,2*nod+1,mid+1,r))%mod;
}

void DFS1(int nod){
    v[nod]=1; dp[nod]=1;
    for(int i : g[nod]){
        if(!v[i]){
            DFS1(i);
            dp[nod]*=(1+dp[i]);
            dp[nod]%=mod;
        }
    }
}

void DFS2(int nod){
    v[nod]=1; f.clear();
    for(int i : g[nod]){
        if(!v[i]){
            f.pb(1+dp[i]);
        }
    }
    Build(); int k=1;
    for(int i : g[nod]){
        if(!v[i]){
            q[i]=(1+Qry(1,k-1)*Qry(k+1,f.sz)%mod*q[nod])%mod;
            s[i]=dp[i]*q[i]%mod;
            k++;
        }
    }
    for(int i : g[nod]){
        if(!v[i]){
            DFS2(i);
        }
    }
}

