int dfs1(VVI &dp, VVI &adj, int M, int u, int p) {
    int res = 1;
    for (auto v: adj[u]) {
        if (v == p) continue;
        dp[u][v] = dfs1(dp, adj, M, v, u) + 1;
        res *= dp[u][v];
        res %= M;
    }
    return res;
}

void dfs2(VVI &dp, VVI &adj, VI &res, int M, int u, int p) {
    int n = adj[u].size();
    VI back(n, 1);
    for (int i = n - 1; i >= 0; i--) {
        int v = adj[u][i];
        back[i-1] = back[i] * dp[u][v];
        back[i-1] %= M;
    }
    int acc = 1;
    for (int i = 0; i < n; i++) {
        int v = adj[u][i];
        dp[v][u] = acc * back[i] + 1;
        dp[v][u] %= M;
        if (v != p)
            dfs2(dp, adj, res, M, v, u);
        acc *= dp[u][v];
        acc %= M;
    }

    res[u] = acc;
}

