ll up[maxn], down[maxn], L[maxn], R[maxn];

vector<int> adj[maxn];
int n, mod;

void dfsDown(int u, int p){
    down[u] = 1;
    for (auto v : adj[u]){
        if (v != p){
            dfsDown(v, u);
            down[u] = down[u] * (1 + down[v]) % mod;
        }
    }
}

void dfsUp(int u, int p){
    if (p != -1)
        adj[u].erase(remove(adj[u].begin(), adj[u].end(), p), adj[u].end());
    int sz = adj[u].size();
    for (int i = 0; i < sz; i++){
        L[i] = R[i] = 1;
    }
    if (sz){
        L[0] = down[adj[u][0]] + 1;
        R[sz - 1] =  down[adj[u][sz - 1]] + 1;
        for (int i = 1; i < sz; i++){
            L[i] = L[i - 1] * (1 + down[adj[u][i]]) % mod;
        }
        for (int i = sz - 2; i >= 0; i--){
            R[i] = R[i + 1] * (1 + down[adj[u][i]]) % mod;
        }
        for (int i = 0; i < sz; i++){
            up[adj[u][i]] = 1 + up[u] * (i - 1 >= 0 ? L[i - 1] : 1) % mod * (i + 1 < sz ? R[i + 1] : 1) % mod;
        }
    }
    for (auto v : adj[u]){
        dfsUp(v, u);
    }
}

