  if (DP[s] != 0)
    return DP[s];
  ll ans = 1;
  AUTO(g, G[s]) {
    if (g == p)
      continue;
    ans *= (func(G, DP, g, s) + 1); // % MOD;
    // ans %= MOD;
  }
  return DP[s] = ans;
}

void func2(vvl &G, vl &DP, vl &DP2, ll s, ll p) {
