          (DP2[p] / (DP[s] + 1)) + 1; //(MODDIV(DP2[p], DP[s] + 1) + 1) % MOD;
      // ans %= MOD;
      continue;
    }
    ans *= DP[g] + 1;
    // ans %= MOD;
