// https://codeforces.com/blog/entry/64250?#comment-483299
void fast_down(int u) {
    if (down[u]) return;
    int ret = 1;
    fora (v, kids[u]) {
        fast_down(v);
        ret = mul(ret, 1 + down[v]);
    }
    down[u] = ret;

    int k = sz(kids[u]);
    pref[u] = vi(k + 1, 1);
    fori (i, 1, k + 1) {
        int v = kids[u][i - 1];
        pref[u][i] = mul(pref[u][i - 1], 1 + down[v]);
    }

    suff[u] = vi(k + 1, 1);
    ford (i, k - 1, -1) {
        int v = kids[u][i];
        suff[u][i] = mul(suff[u][i + 1], 1 + down[v]);
    }
}

void fast_up(int u) {
    if (u == 1) up[u] = 1;
    fori (i, 0, sz(kids[u])) {
        int v = kids[u][i];
        up[v] = up[u];
        up[v] = mul(up[v], pref[u][i]);
        up[v] = mul(up[v], suff[u][i + 1]);
        up[v] = add(up[v], 1);
        fast_up(v);
    }
}

