const int borne = (int)(1e5) + 5;
vl adj[borne];
int par[borne];
int sub[borne];
int up[borne];
vl pref[borne];
vl suff[borne];
int rev[borne];

bool subok[borne];
bool upok[borne];

void constructSub(int nod)
{
    if (subok[nod]) return;
    subok[nod] = true;
    sub[nod] = 1;
    for (int enf : adj[nod]) if (enf != par[nod]) {
        constructSub(enf);
        sub[nod] *= (1 + sub[enf]);
        sub[nod] %= mod;
    }
}

void constructPrefix(int nod)
{
    int k = adj[nod].size();
    pref[nod] = vl(k,1);
    suff[nod] = vl(k, 1);
    fin(i, k) if (adj[nod][i] != par[nod]) {
        pref[nod][i] = suff[nod][i] = (1 + sub[adj[nod][i]]);
    }
    fin2(i, 1, k) pref[nod][i] = (pref[nod][i] * pref[nod][i-1]) % mod;
    ford(i, k-1) suff[nod][i] = (suff[nod][i] * suff[nod][i+1]) % mod;
}

int sumExcept(int nod, int exceptChild)
{
    int ind = rev[exceptChild];
    int a = (ind ? pref[nod][ind-1] : 1);
    int b = ((ind < (int)(suff[nod].size()) - 1) ? suff[nod][ind+1] : 1);
    return (a*b) % mod;
}

void constructUp(int nod)
{
    if (upok[nod]) return;
    upok[nod] = true;
    up[nod] = 1;
    if (par[nod] != 0) {
        constructUp(par[nod]);
        up[nod] *= up[par[nod]];
        up[nod] *= sumExcept(par[nod], nod);
        up[nod] += 1;
        up[nod] %= mod;
    }
}

void dfs(int nod)
{
    for (int enf : adj[nod]) if (enf != par[nod]) {
        par[enf] = nod;
        dfs(enf);
    }
}

void solve()
{
    s2(n, mod);
    fin(i, n-1) {
        int x, y;
        s2(x, y);
        rev[y] = adj[x].size();
        adj[x].pb(y);
        rev[x] = adj[y].size();
        adj[y].pb(x);
    }
    dfs(1);
    fin2(i,1,n+1) constructSub(i);
    fin2(i,1,n+1) constructPrefix(i);
    fin2(i,1,n+1) constructUp(i);

    fin2(i,1,n+1) {
        p1((((sub[i]*up[i]) % mod)+mod)%mod);
    }
    return;
}

