            if(u_==par_) continue;
            dp[v_][i_]=dfs(u_,v_);
            dp_cum_=merge(dp_cum_,dp[v_][i_]);
        }
        return add_root(dp_cum_);
    }
    void bfs(int v_,const DP &dp_par,int par_=-1){
        int deg_=(int)G[v_].size();
        for(int i_=0;i_<deg_;i_++){
            if(G[v_][i_].to==par_) dp[v_][i_]=dp_par;
        }
        vector<DP> dp_l(deg_+1,identity),dp_r(deg_+1,identity);
        for(int i_=0;i_<deg_;i_++){
            dp_l[i_+1] = merge(dp_l[i_],dp[v_][i_]);
        }
        for(int i_=deg_-1;i_>=0;i_--){
            dp_r[i_] = merge(dp_r[i_+1],dp[v_][i_]);
        }
        ans[v_]=add_root(dp_l[deg_]);
        for(int i_=0;i_<deg_;i_++){
            int u_=G[v_][i_].to;
            if(u_==par_) continue;
            bfs(u_,add_root(merge(dp_l[i_], dp_r[i_+1])),v_);
        }
    }
};

