struct SegMent_Tree {
	int seg[maxn * 4], tag[maxn * 4], val[maxn];
	void init(int node,int l,int r) {
		if (l == r) {
			seg[node] = 1;
			tag[node] = 1;
		}
		else {
			int m = (l + r) >> 1;
			init(ls, l, m);
			init(rs, m + 1, r);
			seg[node] = tag[node] = 1;
		}
	}
	void upd(int node,int l,int r,int ql,int qr,int val) {
		if (ql <= l && r <= qr) {
			tag[node] *= val;
			tag[node] %= mod;
		}
		else {
			int m = (l + r) >> 1;
			if (ql <= m) upd(ls, l, m, ql, qr, val);
			if (qr > m) upd(rs, m+1, r, ql, qr, val);
		}
	}
	void push(int node) {
		tag[ls] = (tag[node] * tag[ls]) % mod;
		tag[rs] = (tag[node] * tag[rs]) % mod;
	}
	void get_val(int node,int l,int r) {
		if (l == r) {
			val[l] = seg[node] * tag[node];
		}
		else {
			push(node);
			int m = (l + r) >> 1;
			get_val(ls, l, m);
			get_val(rs, m+1, r);
		}
	} 
} Seg;

void dfs2(int now,int fa,int val) {
	vector<int> Val;
	ans[now] = val;
	Seg.init(1, 0, SZ(G[now]));
	for (int i = 0; i < SZ(G[now]); i++) {
		if (G[now][i] == fa) continue;
		ans[now] = (ans[now] * (dp[G[now][i]] + 1)) % mod;
		if (i - 1 >= 0) {
			Seg.upd(1, 0, SZ(G[now]), 0, i - 1, dp[G[now][i]] + 1);
		}
		Seg.upd(1, 0, SZ(G[now]), i + 1, SZ(G[now]), dp[G[now][i]] + 1);
	}
	Seg.get_val(1, 0, SZ(G[now]));

	for (int i = 0; i < SZ(G[now]); i++) Val.pb(Seg.val[i]);
	for (int i = 0; i < SZ(G[now]); i++) {
		int k = G[now][i];
