const int maxN = 1e5 + 10, maxK = 1e5 + 10, inf = 1e15 + 10, base = 223;

int mod;

struct segment_tree {
    vector < int > t;



    void set(int n) {
        for (int i = 0; i < 4 * n; i++) t.push_back(1);
    }

    void update(int v, int l, int r, int pos, int val) {
        if (l == r) {
            t[v] = val % mod;
        } else {
            int m = (r + l) / 2;
            if (pos <= m) update(v * 2, l, m, pos, val);
            else update(v * 2 + 1, m + 1, r, pos, val);
            t[v] = (t[v * 2] * t[v * 2 + 1]) % mod;
        }
    }

    int get(int v, int l, int r, int tl, int tr) {
        if (l >= tl && r <= tr) {
            return t[v];
        }
        if (l > tr || r < tl) return 1;
        int m = (r + l) / 2;
        return (get(v * 2, l, m, tl, tr) * get(v * 2 + 1, m + 1, r, tl, tr)) % mod;
    }

};

int n, dp[maxN], updp[maxN];
vector < int > a[maxN];
segment_tree tree[maxN];

void dfs(int v, int p) {
    dp[v] = 1;
    for (int i = 0; i < a[v].size(); i++) {
        int to = a[v][i];
        if (to == p) continue;
        dfs(to, v);
        dp[v] = (dp[v] * (dp[to] + 1)) % mod;
        tree[v].update(1, 0, a[v].size() - 1, i, dp[to] + 1);
    }
}

void dfs1(int v, int p) {
    for (int i = 0; i < a[v].size(); i++) {
        int to = a[v][i];
        if (to == p) continue;
        int e = 1;
        if (i) e = e * tree[v].get(1, 0, a[v].size() - 1, 0, i - 1) % mod;
        if (i + 1 < a[v].size()) e = e * tree[v].get(1, 0, a[v].size() - 1, i + 1, a[v].size() - 1) % mod;
        updp[to] = ((updp[v] + 1) * e) % mod;
        dfs1(to, v);
    }
}

