int up[100500];
int down[100500];
vector<int> gr[100500];

void calc_down(int v, int par = -1) {
    down[v] = 1;

    for (int x : gr[v])
        if (x != par) {
            calc_down(x, v);
            down[v] = mult(down[v], (1 + down[x]));
        }
}

void calc_up(int v, int par = -1) {
    if (par == -1)
        up[v] = 1;

    vector<int> children;
    for (int x : gr[v])
        if (x != par)
            children.push_back(x);

    vector<int> pref(children.size() + 1, 1);
    vector<int> suf(children.size() + 1, 1);

    for (int i = 0; i < children.size(); i++)
        pref[i + 1] = mult(pref[i], down[children[i]] + 1);

    for (int i = int(children.size()) - 1; i >= 0; i--)
        suf[i] = mult(suf[i + 1], down[children[i]] + 1);

    for (int i = 0; i < children.size(); i++)
        up[children[i]] = add(1, mult(up[v], mult(pref[i], suf[i + 1])));

    for (int x : children)
        calc_up(x, v);
}

