void dfs(int node, int last){
    int p = 1;

    for(int a : Graph[node]){

        if(a == last) continue;

        dfs(a,node);
        children[node].push_back(a);

        p*=(down[a]+1);
        p%=mod;

    }
    down[node] = p;
}


void dfs_2(int node){
    for(int i = 0; i < children[node].size(); i++){

        int a = children[node][i];

        int p = 1;

        if(node != 1){
            p*=(up[node]+1);
            p%=mod;
        }

        if(i) p*=(pref[node][i-1]);
        p%=mod;

        if(i+1 < suff[node].size()) p*=(suff[node][i+1]);
        p%=mod;

        up[a] = p;

        dfs_2(a);

    }
}


