const int N = 1e5 + 5;
int n, mod;
int dp[N], sol[N];
deque<int> g[N], pre[N], suf[N];

int add(int a, int b)
{
	a = (a + mod) % mod;
	b = (b + mod) % mod;
	return (a + b) % mod;
}

int mul(int a, int b)
{
	return (1ll * a * b) % mod;
}

void dfs(int node, int parent)
{
	int cur = 1;
	for(int i = 0; i < g[node].size(); i++)
	{
		int child = g[node][i];
		if(child != parent){
			dfs(child, node);
			cur = mul(cur, dp[child]);
		}
		pre[node].push_back(cur);
	}
	cur = 1;
	for(int i = (int)g[node].size() - 1; i >= 0; i--)
	{
		int child = g[node][i];
		if(child != parent){
			dfs(child, node);
			cur = mul(cur, dp[child]);
		}
		suf[node].push_front(cur);
	}
	dp[node] = add(1, cur);
}

void dfs2(int node, int parent, int val_parent)
{
	dp[node] = (dp[node] - 1 + mod) % mod;
	dp[node] = (1ll * dp[node] * val_parent) % mod;
	dp[node] = (dp[node] + 1) % mod;
	sol[node] = dp[node];
	for(int i = 0; i < g[node].size(); i++)
	{
		int child = g[node][i];
		if(child != parent){
			int p = 1, s = 1;
			if(i)
				p = pre[node][i - 1];
			if(i + 1 < g[node].size())
				s = suf[node][i + 1];
			int v = (1ll * p * s) % mod;
			v = (1ll * v * val_parent) % mod;
			v = (v + 1) % mod;
			dfs2(child, node, v);
		}
	}
}

