  vl sum1(n + 1, 1), sum2(n + 1, 1);
  rep (i, n) {
    int v = G[now][i];
    sum1[i + 1] = sum1[i] * (dp[edge2idx[pii(now, v)]] + 1) % MOD;
  }
  rrep (i, n) {
    int v = G[now][i];
    sum2[i] = sum2[i + 1] * (dp[edge2idx[pii(now, v)]] + 1) % MOD;
  }
  rep (i, n) {
    int v = G[now][i];
    int idx = edge2idx[pii(v, now)];
    if (dp[idx] >= 0) continue;
    dp[idx] = sum1[i] * sum2[i + 1] % MOD;
  }
  rep (i, n) {
    if (G[now][i] == par) continue;
    dfs2(G[now][i], now);
  }
}

