const int MAX_N = 1e5 + 2;

int n;
int MOD;
vector<int> g[MAX_N];
vector<int> subtree[MAX_N];
int p[MAX_N];

vector<ll> prf[MAX_N];
vector<ll> suf[MAX_N];
ll dp_down[MAX_N], dp_up[MAX_N];

void add_edge(int from, int to)
{
    g[from].push_back(to);
    g[to].push_back(from);
}

void dfs(int x, int par) {
    p[x] = par;
    for (int i=0; i<g[x].size(); i++) {
        int y = g[x][i];
        if (y != par) {
            subtree[x].push_back(y);
            dfs(y, x);
        }
    }
}

void solve_down(int x) {
    const int sz = subtree[x].size();
    prf[x].resize(sz);
    suf[x].resize(sz);

    dp_down[x] = 1;
    for (int i = 0; i < sz; i++) {
        int y = subtree[x][i];
        solve_down(y);
        dp_down[x] = (dp_down[x] * (1 + dp_down[y]))%MOD;
    }
    for (int i = 0; i < sz; i++) {
        int y = subtree[x][i];
        prf[x][i] = 1 + dp_down[y];
        if (i != 0) {
            (prf[x][i] *= prf[x][i - 1])%=MOD;
        }
    }
    for (int i = sz - 1; i >= 0; i--) {
        int y = subtree[x][i];
        suf[x][i] = 1 + dp_down[y];
        if (i != sz - 1) {
            (suf[x][i] *= suf[x][i + 1])%=MOD;
        }
    }
}

void solve_up(int x) {
    if (x == 1) dp_up[x] = 1;
    const int sz = subtree[x].size();
    for (int i = 0; i < sz; i++) {
        int y = subtree[x][i];
        dp_up[y] = dp_up[x];
        if (i != 0) (dp_up[y] *= prf[x][i - 1])%=MOD;
        if (i != sz - 1) (dp_up[y] *=suf[x][i + 1])%=MOD;
        (dp_up[y] += 1)%=MOD;
        solve_up(y);
    }
}

void solve()
{
    dfs(1,-1);
    solve_down(1);
    solve_up(1);
    for (int i = 1; i <= n; i++)
		printf("%lld\n", (dp_down[i] * dp_up[i]) % MOD);
}

