void rerooting(int idx, int par, mint val) {
  for (auto to : g[idx]) {
    if (to == par)
      continue;

    mint v = 1;
    for (auto e : g[idx]) {
      if (e == to || e == par)
        continue;

      v *= dp[e] + 1;
    }

    rerooting(to, idx, val * v + 1);
  }
  ans[idx] *= val;
}
