int fact(int x,int y){
    if(y==0)return 1;
    else if(y==1)return x;
    else if(y%2==0)return fact(x*x%m,y/2)%m;
    else return fact(x*x%m,y/2)%m*x%m;
}
int dfs(int i,int par){
    int &res=dp[i];
    if(~res)return res;
    res=1;
    for(auto e:v[i]){
        if(e==par) continue;
        (res*=dfs(e,i)+1)%=m;
    }
    return res;
}
vector<int>front[114514],back[114114];
void dfs2(int i,int par,int carry){
    dp2[i]=carry*dp[i]%m;
    int h=v[i].size();
    front[i].resize(h+2);
    back[i].resize(h+2);
    front[i][0]=1;
