ll n, mod;
ll explore(int i, vector<vector<ll>>& graph, vector<vector<pair<ll, ll>>>& dp, vector<ll>& vis)
{
	vis[i] = 1;
	if (graph[i].size() == 1 && vis[graph[i][0]] == 1)
	{
		//dp[i].push_back(make_pair(graph[i][0], 2));
		return 2;
	}
	ll ans = 1;
	for (int j = 0;j < graph[i].size();j++)
	{
		if (vis[graph[i][j]] == 0)
		{
			int test = 0;
			for (int k = 0;k < dp[i].size();k++)
			{
				if (dp[i][k].first == graph[i][j])
				{
					test = 1;
					ans *= dp[i][k].second;
					ans %= mod;
					break;
				}
			}
			if (test == 0)
			{
				ll temp = explore(graph[i][j], graph, dp, vis) % mod;
				dp[i].push_back(make_pair(graph[i][j], temp));
				ans *= temp;
				ans %= mod;

			}
		}
	}

		ans += 1;
	return ans;
}

