using namespace std;

ll P;
vvl G = vv(100001, 0, 0, ll);
vll num(100001, 1);
vll rev(100001, 1);
vvl t = vv(100001, 0, 0, ll);

ll f_bottom(ll now, ll from){
  ll ret = 1;
  for(int i=0;i<G[now].size();i++){
    if(G[now][i] == from) continue;
    ll tmp = (f_bottom(G[now][i], now) + 1)%P;
    t[now].push_back(tmp);
    ret = (ret * tmp)%P;
  }
  return num[now] = ret;
}

void f_down(ll now, ll from){
  vll l(t[now].size(), 1), r(t[now].size(), 1);
  for(int i=0;i<t[now].size();i++) l[i] = ((i==0?1:l[i-1]) * t[now][i])%P;
  for(int i=0;i<t[now].size();i++) r[i] = ((i==0?1:r[i-1]) * t[now][t[now].size()-1-i])%P;

  ll c = 0;
  for(int i=0;i<G[now].size();i++){
    if(G[now][i]==from) continue;
    ll tmp = ((c==0?1:l[c-1])*(c==t[now].size()-1?1:r[t[now].size()-2-c]))%P;
    c++;
    tmp = (rev[now] * tmp)%P;
    rev[G[now][i]] = (tmp + 1)%P;
  }
  for(int i=0;i<G[now].size();i++){
    if(G[now][i]==from) continue;
    f_down(G[now][i], now);
  }
}

