const int N = 1e6 + 69;

int n, x, y, m;
int ANS[N];
vector <int> gr[N];

ll binpow(ll a,int b){
        ll res = 1;
        while(b){
                if(b&1){
                        res *= a;
                        res %= m;
                }
                a *= a;
                a %= m;
                b >>= 1;
        }

        return res;
}

void dfs(int x,int p){

        ANS[x] = 1;
        for(int i = 0; i < gr[x].size(); i++){
                int to = gr[x][i];
                if(to == p) continue;
                dfs(to,x);
                ANS[x] *= ANS[to] + 1;
                ANS[x] %= m;
        }
}

void dfs1(int x,int p){

        ANS[x] = (ANS[p]*binpow((ANS[x]+1),m-2)+1)*ANS[x];
        ANS[x] %= m;

        for(int i = 0; i < gr[x].size(); i++){
                int to = gr[x][i];
                if(to == p) continue;
                dfs1(to,x);
        }
}

