	mint sm = mint(1);
	template <class E> Node to_subs(int, const E&) const {
		//tree -> subtrees
		return { sm + 1 };
	}
	Node operator+(const Node& r) const {
		//subtrees + subtrees
		return { sm * r.sm };
	}
	Node join(int) const {
		//subtrees -> tree
		return *this;
	}
};

