const int N = 1 << 17;

vi vertices[N];
int par[N], dp1[N][2], dp2[N][2], cnt[N], n, M;
unordered_map<int, int> tries[N];
unordered_map<int, int> r_tries[N];


inline int MOD(int v)
{
    return (v % M + M) % M;
}


void add(unordered_map<int, int> &t, int ind, int v)
{
    for (int i = ind; i < N; i += i&-i)
        if (!t.count(i))
            t[i] = v;
        else
            t[i] = MOD(t[i] * v);
}


int get(unordered_map<int, int> &t, int ind)
{
    int cnt = 1;
    for (int i = ind; i; i -= i&-i)
        if (t.count(i))
            cnt = MOD(cnt * t[i]);

    return cnt;
}


void dfs(int v, int p = -1) {

    par[v] = p;
    for (int u : vertices[v]) {
        if (u == p)
            continue;

        dfs(u, v);
    }

    dp1[v][0] = 1;
    dp1[v][1] = 1;

    for (int u : vertices[v]) {
        if (u == p)
            continue;

        dp1[v][1] = MOD(dp1[v][1] * (dp1[u][1] + 1));
        dp1[v][0] = MOD(dp1[v][0] + dp1[u][1] + dp1[u][0] - 1);
    }

    for (int u : vertices[v])
        if (u != par[u])
        {
            cnt[v] = MOD(cnt[v] + dp1[u][0] + dp1[u][0] - 1);
            add(tries[v], u, MOD(dp1[u][1] + 1));
            add(r_tries[v], N - u, MOD(dp1[u][1] + 1));
        }
}

void dfs2(int v, int p = -1)
{

    dp2[v][0] = dp2[v][1] = 1;


    if (p != -1) {

        dp2[v][0] = MOD(dp2[v][0] + dp2[p][0] - 1);
        dp2[v][0] = MOD(dp2[v][0] + cnt[p] - (dp1[v][0] + dp1[v][1] - 1));

        int cnt = MOD(MOD(dp2[p][1] * get(tries[p], v - 1)) * get(r_tries[p], N - v - 1));

        dp2[v][0] = MOD(dp2[v][0] + cnt);
        dp2[v][1] = MOD(dp2[v][1] + cnt);
    }

    for (int u : vertices[v]) {
        if (u == p)
            continue;

        dfs2(u, v);
    }

}


