using namespace std;

typedef long long ll;
typedef long double ld;

const int N = 1e5 + 10;
int n, m;
vector<int> g[N];
vector<int> dp[N];

int mul(int a, int b)
{
    return ((ll)a * b) % m;
}

int solve(int node, int parent)
{
    int idx;
    if(parent == -1)
        idx = dp[node].size() - 1;
    else
    {
        int st = 0, en = g[node].size() - 1;
        while(st <= en)
        {
            int mid = (st + en) / 2;
            if(g[node][mid] <= parent)
                idx = mid, st = mid + 1;
            else
                en = mid - 1;
        }
    }
    int &ret = dp[node][idx];
    if(ret != -1)
        return ret;
    ret = 1;
    for(auto &x: g[node])
    {
        if(x == parent)
            continue;
        ret = mul(ret, solve(x, node));
    }
    return ret = (ret + 1) % m;
}

int main()
{
    //ios_base::sync_with_stdio(0), cin.tie(0), cout.tie(0);
    cin >> n >> m;
    for(int i = 0; i < n - 1; i++)
    {
        int x, y;
        cin >> x >> y;
        g[x].push_back(y);
        g[y].push_back(x);
    }
    for(int i = 0; i <= n; i++){
        sort(g[i].begin(), g[i].end());
        for(int j = 0; j < g[i].size() + 1; j++)
            dp[i].push_back(-1);
    }
    for(int i = 1; i <= n; i++)
    {
        cout << (solve(i, -1) - 1 + m) % m << '\n';
    }
}

