int m;
vector <int> v[100000];
vector <int> w[100000];
vector <int> z[100000];
vector <int> l[100000];
vector <int> r[100000];
map <int, int> mp[100000];

long long dfs(int x, int y) {
    int i;

    if (mp[x].count(y)) return mp[x][y];

    if (z[x].size() == 0) {
        long long ans = 1;

        for (i = 0; i < v[x].size(); i++) {
            if (v[x][i] == y) {
                z[x].push_back(w[x].size());
                w[x].push_back(0);
            } else {
                w[x].push_back(dfs(v[x][i], x) + 1);
                ans = ans * w[x].back() % m;
            }
        }

        if (y == -1) {
            long long left = 1, right = 1;

            for (i = 0; i < v[x].size(); i++) {
                l[x].push_back(left);
                left = left * w[x][i] % m;
            }
            l[x].push_back(left);

            for (i = v[x].size() - 1; i >= 0; i--) {
                r[x].push_back(right);
                right = right * w[x][i] % m;
            }
            reverse(r[x].begin(), r[x].end());

            z[x].push_back(0);
        }

        return mp[x][y] = ans;
    } else if (w[x][z[x][0]] == 0) {
        int p = z[x][0];
        long long left = 1, right = 1;

        w[x][p] = dfs(v[x][p], x) + 1;

        for (i = 0; i < v[x].size(); i++) {
            l[x].push_back(left);
            left = left * w[x][i] % m;
        }
        l[x].push_back(left);

        for (i = v[x].size() - 1; i >= 0; i--) {
            r[x].push_back(right);
            right = right * w[x][i] % m;
        }
        reverse(r[x].begin(), r[x].end());
    }

    if (y == -1) {
        return mp[x][y] = l[x].back();
    } else {
        int p = lower_bound(v[x].begin(), v[x].end(), y) - v[x].begin();

        return mp[x][y] = (long long)l[x][p] * r[x][p] % m;
    }
}

