ll MODDIV(ll a, ll b) {
  a %= MOD;
  b %= MOD;
  if (b == 0)
    b = MOD;
  while (a % b != 0) {
    a += MOD;
  }
  // cout << a << "," << b << endl;
  return (a / b) % MOD;
}

