ll func(vvl &G, vl &DP, ll s, ll p) {
  if (DP[s] != 0)
    return DP[s];
  ll ans = 1;
  AUTO(g, G[s]) {
    if (g == p)
      continue;
    ans *= (func(G, DP, g, s) + 1) % MOD;
    ans %= MOD;
  }
  return DP[s] = ans;
}

void func2(vvl &G, vl &DP, vl &DP2, ll s, ll p) {
  ll ans = 1;
  AUTO(g, G[s]) {
    if (g == p) {
      ans *= (MODDIV(DP2[p], DP[s] + 1) + 1) % MOD;
      ans %= MOD;
      continue;
    }
    ans *= DP[g] + 1;
    ans %= MOD;
  }
  DP2[s] = ans;
  // cout << s << "," << ans << endl;
  AUTO(g, G[s]) {
    if (g == p) {
      continue;
    }
    func2(G, DP, DP2, g, s);
  }
}
