const int nmax = 100100;
ll N, M;
VL G[nmax], dp[nmax];

ll dfs1(ll now, ll par) {
    ll ret = 1;
    REP(i, G[now].size()) {
        ll to = G[now][i];
        if(to == par) continue;
        dp[now][i] = dfs1(to, now);
        (ret *= 1 + dp[now][i]) %= M;
    }
    return ret;
}

void dfs2(ll now, ll par, ll d_par) {
    ll n = G[now].size();
    REP(i, n) {
        ll to = G[now][i];
        if(to == par) dp[now][i] = d_par;
    }
    VL L(n), R(n);
    REP(i, n) {
        L[i] = (i ? L[i - 1] : 1) * (1 + dp[now][i]) % M;
        R[n - 1 - i] = (i ? L[n - i] : 1) * (1 + dp[now][n - 1 - i]) % M;
    }
    REP(i, n) {
        ll to = G[now][i];
        if(to == par) continue;
        dfs2(to, now, (i ? L[i - 1] : 1) * (i != n - 1 ? R[i + 1] : 1));
    }
}

signed main() {
