    }
    REP(i, N) dp[i].resize(G[i].size());
    dfs1(0, -1);
    dfs2(0, -1, 0);
    REP(i, N) {
        ll tmp = 1;
        REP(j, G[i].size())(tmp *= (1 + dp[i][j])) %= M;
        cout << tmp << "\n";
    }
}

