using namespace std;
typedef pair<int,int> ii;
int n,m;
vector<int> al[100005];
class custom_hash{
    public:
        size_t operator()(const pair<int,int> &i)const{
            return hash<long long>()(((long long)i.first)|(((long long)i.second)<<32));
        }
};
unordered_map<ii,int,custom_hash> memo;
int dfs(int i,int p,int j){ ///j=0 not coloured, j=1 is coloured
    int ji=(j?1:-1)*i;
    if (memo.count(ii(ji,p))) return memo[ii(ji,p)];
    if (al[i].size()==1 && al[i][0]==p){
        return memo[ii(ji,p)]=1;
    }
    long long ans=1;
    for (vector<int>::iterator it=al[i].begin();it!=al[i].end();it++){
        if (*it==p) continue;
        if (j==0){
            ans=(ans+dfs(*it,i,1)+dfs(*it,i,0)-1)%m;
        }
        else{
            ans=(ans*(dfs(*it,i,1)+1))%m;
        }
    }
