    auto ReRooting = [&](auto&& self, int from = 0, int par = -1) -> void {
        int cur = prefix[from].size();
        for(int to : graph[from]){
            if(to == par)   continue;
            prefix[from].emplace_back(dp[to] + 1);
        }
        int sz = prefix[from].size();
        suffix[from] = prefix[from];
        for(int i = 0; i < sz; ++i){
