                res = (ll)res * suffix[from][cur + 1] % m;
            }
            dp2[to] = (ll)dp[to] * (res + 1) % m;
            prefix[to].emplace_back(res + 1);
            ++cur;
            self(self, to, from);
        }

        return;
    };
    ReRooting(ReRooting);
