}

#include <algorithm>
#include <cassert>
#include <iostream>
#include <vector>
using namespace std;

int N, MOD;
vector<vector<int>> adj;

// up[node] = number of ways to color the subtree of node that its parent is responsible for, empty coloring included.
// down[node] = number of ways to paint node's subtree where node must be painted black.
vector<int> up, down;

long long solve_down(int node, int parent) {
    down[node] = 1;

    // Erase parent from adj[node].
    for (int &neighbor : adj[node])
        if (neighbor == parent) {
            swap(neighbor, adj[node].back());
            adj[node].pop_back();
            break;
        }

    for (int child : adj[node])
        down[node] = down[node] * (solve_down(child, node) + 1) % MOD;

    return down[node];
}

void solve_up(int node) {
    int n = adj[node].size();
    vector<int> prefix(n, 1), suffix(n, 1);

    for (int i = 0; i + 1 < n; i++)
        prefix[i + 1] = (long long) prefix[i] * (down[adj[node][i]] + 1) % MOD;

    for (int i = n - 1; i > 0; i--)
        suffix[i - 1] = (long long) suffix[i] * (down[adj[node][i]] + 1) % MOD;

    for (int i = 0; i < n; i++)
        up[adj[node][i]] = (1 + (long long) prefix[i] * suffix[i] % MOD * up[node]) % MOD;

    for (int child : adj[node])
        solve_up(child);
}

int main() {
    scanf("%d %d", &N, &MOD);
    adj.assign(N, {});

    for (int i = 0; i < N - 1; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        a--; b--;
        adj[a].push_back(b);
        adj[b].push_back(a);
    }

    up.assign(N, 1);
    down.assign(N, 1);
    solve_down(0, -1);
    solve_up(0);

    for (int i = 0; i < N; i++)
        printf("%lld\n", (long long) up[i] * down[i] % MOD);
}

#include<bits/stdc++.h>
using namespace std;
#define ll long long

vector<ll>adj[100005];
ll down[100005],up[100005],visited[100005],m;

ll power(ll a,ll b,ll mod)
{
    ll re=1;
    while(b)
    {
        if(b&1)
        {
            re=(re*a)%mod;
        }
        a=(a*a)%mod;
        b=b>>1;
    }
    return re;
}

void dfs(ll pa)
{
    visited[pa]=1;
    down[pa]=1;
    for(ll i=0;i<adj[pa].size();i++)
    {
        if(!visited[adj[pa][i]])
        {
            dfs(adj[pa][i]);
            down[pa]=(down[pa]*(1+down[adj[pa][i]]))%m;
        }
    }
}

void dfs2(ll pa)
{
    visited[pa]=1;
   // cout<<pa<<endl;
    ll c=1;
    for(ll i=0;i<adj[pa].size();i++)
    {
        if(!visited[adj[pa][i]])
            c=(c*(1+down[adj[pa][i]]))%m;
    }
    for(ll i=0;i<adj[pa].size();i++)
    {
        if(!visited[adj[pa][i]])
        {
     //       cout<<adj[pa][i]<<endl;
            up[adj[pa][i]]=(1+(up[pa]*((c*power((1+down[adj[pa][i]]),m-2,m))%m))%m)%m;
            dfs2(adj[pa][i]);
        }
    }
}

