    {
        cin>>x>>y;
        adj[x].push_back(y);
        adj[y].push_back(x);
    }
    dfs(1);
    memset(visited,0,sizeof(visited));
    up[1]=1;
    dfs2(1);
    for(i=1;i<=n;i++)
    {
//        cout<<down[i]<<" "<<up[i]<<endl;
        cout<<(down[i]*up[i])%m<<endl;
    }
}

