inline int MOD(int v)
{
    return (v % M + M) % M;
}


void dfs(int v, int p = -1)
{

    par[v] = p;
    for (int u : vertices[v])
    {
        if (u == p)
            continue;

        dfs(u, v);
    }

    dp1[v][0] = 1;
    dp1[v][1] = 1;

    for (int u : vertices[v])
    {
        if (u == p)
            continue;

        dp1[v][1] = MOD(dp1[v][1] * (dp1[u][1] + 1));
        dp1[v][0] = MOD(dp1[v][0] + dp1[u][1] + dp1[u][0] - 1);
    }
}

void dfs2(int v, int p = -1)
{

    dp2[v][0] = dp2[v][1] = 1;


    if (p != -1) {

        dp2[v][0] = MOD(dp2[v][0] + dp2[p][0] - 1);

        for (int u : vertices[p])
            if (u != v && u != par[p])
                dp2[v][0] = MOD(dp2[v][0] + dp1[u][0] + dp1[u][1] - 1);

        int cnt = dp2[p][1];
        for (int u : vertices[p])
            if (u != v && u != par[p])
                cnt = MOD(cnt * (dp1[u][1] + 1));

        dp2[v][0] = MOD(dp2[v][0] + cnt);


        cnt = dp2[p][1];
        for (int u : vertices[p])
            if (u != v && u != par[p])
                cnt = MOD(cnt * (dp1[u][1] + 1));

        dp2[v][1] = MOD(dp2[v][1] + cnt);
    }

    for (int u : vertices[v]) {
        if (u == p)
            continue;

        dfs2(u, v);
    }

}


