void Dfs(const int p, const int v) {
    dp[v] = {0, 1};
    sz[v] = 1;

    for (int u : adj[v]) {
        if (u == p) continue;
        Dfs(v, u);

        vector<int> sub(sz[v] + sz[u] + 1);
        for (int i = 1; i <= sz[v]; ++i)
            for (int j = 0; j <= sz[u]; ++j)
                (sub[i + j] += dp[v][i] * dp[u][j]) %= MOD;

        dp[v] = move(sub);
        sz[v] += sz[u];
    }
    dp[v][0] = 1;
}

