	}

	ll gn=g[v].size();
	Array suml(gn+1,1),sumr(gn+1,1);
	REP(i,gn){
		if(g[v][i].to==p) suml[i+1] = suml[i]*pval%m;
		else suml[i+1] = suml[i]*dp[g[v][i].to]%m;
