  cin >> n >> mod;
  for (int i = 1; i < n; i++) {
    int x, y;
    cin >> x >> y;
    adj[x].push_back(y);
    adj[y].push_back(x);
  }
  dfs(1, -1);
  dfs1(1, -1);
  for (int i = 1; i <= n; i++) {
    cout << (1ll * ((up[i]) * (down[i]))) % mod << endl;
  }
  return 0;
}

