void dfs1(int x, int p = -1){
  dp1[x] = 1;
  for(auto to:edges[x]){
    if(to==p)continue;
    dfs1(to, x);
    dp1[x] *= dp1[to];
  }
  dp1[x]++;
}

void dfs2(int x, int p=-1){
  if(p==-1)dp2[x]=1;
  vector<ll> lprod(edges[x].size(), 1);
  rep(i, (int)edges[x].size()){
    int to = edges[x][i];
    if(i)lprod[i] *= lprod[i-1];
    if(to==p)continue;// 着目中のノードのパターン数はかけない

    lprod[i] *= dp1[to]; lprod[i] %= m;
  }

  vector<ll> rprod(edges[x].size(), 1);
  rrep(i, (int)edges[x].size()){
    int to = edges[x][i];
    if(i<edges[x].size()-1)rprod[i] *= rprod[i+1];
    if(to==p)continue;// 着目中のノードのパターン数はかけない

    rprod[i] *= dp1[to]; rprod[i] %= m;
  }

  rep(i, (int)edges[x].size()){
    int to = edges[x][i];
    if(to==p)continue;
    ll pr = 1;
    if(i)pr = pr * lprod[i-1] % m;
    if(i<edges[x].size()-1)pr = pr * rprod[i+1] % m;
    dp2[to] = (dp2[x] * pr+1)%m;
    dfs2(to, x);
  }
}

ll ans[MAXN];
void dfs3(int x, int p = -1){
  ans[x] = dp2[x];
  for(auto to:edges[x]){
    if(to==p)continue;
    ans[x] *= dp1[to];
    ans[x] %= m;
    dfs3(to, x);
  }
}

