        int k = downs[a].size(); // children[a].size
        assert(k == (int) children[a].size());
        pair<int,int> p{1, 0};
        for(int i = 0; i < k; ++i) {
            p = merge(p, downs[a][i]);
            pref[a].push_back(p);
        }
        p = {1, 0};
        for(int i = k - 1; i >= 0; --i) {
            p = merge(p, downs[a][i]);
            suf[a].push_back(p);
        }
        reverse(suf[a].begin(), suf[a].end());
    }
    dfs_two(1, -1);
    for(int a = 1; a <= n; ++a) {
        pair<int,int> p{1, 0};
        if(a != 1) {
            debug() << imie(a) imie(up[a]);
            p = merge(p, up[a]);
        }
        if(!children[a].empty()) {
            debug() << imie(a) imie(pref[a].back());
            p = merge(p, pref[a].back());
        }
        p = process(p);
        printf("%d\n", p.sth_is_black);
    }
}

