			if (all[a]-mom[b]-1>0)	kk=(kk*il2[a][all[a]-mom[b]-2])%M;
			kk=(kk*cafu[a])%M;
			cafu[b]=(kk+1)%M;
			dp[b]=(dp[b]*cafu[b])%M;
			is++, ji[a]--;
		}
		else is--;
	}

}

