int dp[100001];

int dfs(int x, int p = -1)
{
    if (dp[x] != -1) return dp[x];
    int sol = 1;
    for (int y : adj[x])
        if (y != p)
            muls(sol, add(1, dfs(y, x)));
    return dp[x] = sol;
}

int dp2[100001];

void dfs2(int x, int p = -1, int f = 1)
{
    int sz = adj[x].size() - int(p != -1), i = 0;
    vi pref(sz), suff(sz);
    for (int y : adj[x])
        if (y != p)
            pref[i] = suff[i] = add(1, dp[y]), ++i;
    for (int i = 1; i < sz; ++i)
        muls(pref[i], pref[i - 1]);
    for (int i = sz - 2; i >= 0; --i)
        muls(suff[i], suff[i + 1]);

    i = 0;
    for (int y : adj[x])
    {
        if (y == p) continue;
        int g = f;
        if (i != 0) muls(g, pref[i - 1]);
        if (i != sz - 1) muls(g, suff[i + 1]);
        dfs2(y, x, add(g, 1));
    }
    dp2[x] = mul(f, dp[x]);
}

