int m;
int mult(int a, int b) {
	return a * (long long)(b) % m;
}

vector<vector<int>> graph;
vector<int> subtreeDP; // dp[v] = number of ways to color subtree of v such that v is black

void DFS(int v = 0, int p = -1) {
	subtreeDP[v] = 1;

	for(int u : graph[v])
		if(u != p) {
			DFS(u, v);
			subtreeDP[v] = mult(subtreeDP[v], subtreeDP[u] + 1);
		}
}

vector<int> upDP; // number of ways to color v & "up" of v (subgraph when going to parent)

void upDFS(int v = 0, int p = -1) {
	vector<int> sons;
	for(int u : graph[v])
		if(u != p)
			sons.emplace_back(u);
	int n = int(sons.size());

	vector<int> prefix(n), suffix(n);

	for(int i = 0; i < n; ++i) {
		prefix[i] = subtreeDP[sons[i]] + 1;
		if(i != 0)
			prefix[i] = mult(prefix[i], prefix[i - 1]);
	}
	for(int i = n - 1; i >= 0; --i) {
		suffix[i] = subtreeDP[sons[i]] + 1;
		if(i != n - 1)
			suffix[i] = mult(suffix[i], suffix[i + 1]);
	}
	for(int i = 0; i < n; ++i) {
		int u = sons[i];
		upDP[u] = upDP[v];
		if(i != 0)
			upDP[u] = mult(upDP[u], prefix[i - 1]);
		if(i != n - 1)
			upDP[u] = mult(upDP[u], suffix[i + 1]);
		upDP[u] = (upDP[u] + 1) % m;
		upDFS(u, v);
	}
}

