    parentAns /= (1 + dp1[node]);
    ans *= (1 + parentAns);
    dp2[node] = ans%M;
    for(int child : adj[node])
    {
        if(!vis[child])
        {
            finalSolve(child, vis, dp2[node]);
        }
    }
}

