ll n, mod;
vector<ll> dp1(n + 1), dp2(n + 1);

void recurdp1(ll i, ll p, vector<vector<ll>>& adj)
{
	ll ans = 1;
	for (ll j = 0;j < adj[i].size();j++)
	{
		ll v = adj[i][j];
		if (v != p)
		{
			recurdp1(v, i, adj);
			ans *= dp1[v] % mod;
			ans %= mod;
		}
	}
	ans += 1;
	ans %= mod;
	dp1[i] = ans;
}
void recurdp2(ll i, ll p, vector<vector<ll>>& adj)
{
	ll si = adj[i].size();
	if(si==0)
		return;
	vector<ll> prefix(si);
	vector<ll> suffix(si);
	prefix[0] = 1;
	suffix[si - 1] = 1;
	if (adj[i][0] != p)
		prefix[0] = dp1[adj[i][0]];
	if (adj[i][si - 1] != p)
		suffix[si - 1] = dp1[adj[i][si - 1]];
	for (ll j = 1;j < si;j++)
	{
		if (adj[i][j] != p)
			prefix[j] = (prefix[j - 1] * dp1[adj[i][j]]) % mod;
		else {
			prefix[j] = prefix[j - 1];
		}
	}
	for (ll j = si - 2;j >= 0;j--)
	{
		if (adj[i][j] != p)
			suffix[j] = (suffix[j + 1] * dp1[adj[i][j]]) % mod;
		else
			suffix[j] = suffix[j + 1];
	}
	for (ll j = 0;j < si;j++)
	{
		if (adj[i][j] != p)
		{
			ll ans = 1;
			ans *= dp2[i] % mod;
			ans %= mod;
			if (j > 0)
				ans *= prefix[j - 1] % mod;
			ans %= mod;
			if (j < si - 1)
				ans *= suffix[j + 1] % mod;
			ans %= mod;
			ans++;
			ans %= mod;
			dp2[adj[i][j]] = ans;
			recurdp2(adj[i][j], i, adj);
		}
	}

}

