ll dfs(ll w,ll p){
    dp[w].resize(edge[w].size(),1);
    ll sum=1;
    for(int i=0;i<edge[w].size();i++){
        if(edge[w][i]==p){continue;}
        dp[w][i]=dfs(edge[w][i],w);
        sum*=dp[w][i];
        sum%=m;
    }
    return dp2[w]=sum+1;
}

void dfs2(ll w,ll p,ll num){
    dp2[w]--;
    (dp2[w]*=num)%=m;
    vector<ll> A(edge[w].size(),1);
    for(int i=0;i<edge[w].size();i++){
        A[i]=dp[w][i];
        if(edge[w][i]==p){dp[w][i]=A[i]=num;}
    }
    for(int i=1;i<edge[w].size();i++){
        A[i]*=A[i-1];
        A[i]%=m;
    }
    for(int i=(int)edge[w].size()-2;i>=0;i--){
        dp[w][i]*=dp[w][i+1];
        dp[w][i]%=m;
    }
    for(int i=0;i<edge[w].size();i++){
        if(edge[w][i]==p){continue;}
        ll D=1;
        if(i!=0){D*=A[i-1];}
        if(i+1!=edge[w].size()){D*=dp[w][i+1];}
        D++;
        D%=m;
        dfs2(edge[w][i],w,D);
    }
}



