template <typename T = int> T minimum_power_2(T n){
  T i = 1;
  while(i<n) i = (i<<1);
  return i;
}

template <typename T> class SegmentTree{
private:
  int size;
  vector<T> vec;
  T e;
  function<T(T,T)> f, upd;

  T aux(int x, int y, int i, int l, int r){
    if(r<=x || y<=l) return e;
    else if(x<=l && r<=y) return vec[i];
    else return f(aux(x,y,i*2+1,l,(l+r)/2), aux(x,y,i*2+2,(l+r)/2,r));
  };

public:
  SegmentTree(){}
  SegmentTree(int n, T e, function<T(T,T)> f, function<T(T,T)> upd):
    size(minimum_power_2(n)*2-1), vec(size, e), f(f), e(e), upd(upd){}
  void update(int i, T x){
    int j = i+(size+1)/2-1;
    vec[j] = upd(vec[j], x);
    --j;
    while(j>=0){
      vec[j/2] = f(vec[(j/2)*2+1], vec[(j/2)*2+2]);
      (j /= 2) -= 1;
    }
  }

  T query(int x, int y){return aux(x,y,0,0,(size+1)/2);}
};

LLI N,M;
LLI dp[101000];
LLI dp2[101000];
vector<bool> visit(101000);
vector<vector<LLI>> prod1, prod2;
vector<SegmentTree<LLI>> prod;

LLI rec(vector<vector<int>> &tree, int cur, int par){
  if(visit[cur]) return dp[cur];
  visit[cur] = true;

  dp[cur] = 1;

  for(auto next : tree[cur]){
    if(next == par) continue;
    (dp[cur] *= (rec(tree,next,cur)+1)%M) %= M;
  }

  int c = tree[cur].size();
  if(par != -1) --c;

  prod[cur] = SegmentTree<LLI>(c,1,[&](LLI a, LLI b){return (a*b)%M;}, [&](LLI a, LLI b){return b;});

  REP(i,c){
    prod[cur].update(i,dp[tree[cur][i]]+1);
  }

  return dp[cur];
}

LLI rec2(vector<vector<int>> &tree, int cur, int par, int index){
  if(visit[cur]) return dp2[cur];
  visit[cur] = true;

  if(par == -1) dp2[cur] = 0;
  else{
    dp2[cur] = ((dp2[par]+1)%M * (prod[par].query(0,index) * prod[par].query(index+1,tree[par].size()))%M)%M;
  }

  int i = 0;
  for(auto next : tree[cur]){
    if(next == par) continue;
    rec2(tree, next, cur, i);
    ++i;
  }

  return dp2[cur];
}

int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);

  cin >> N >> M;
  vector<vector<int>> tree(N);
  REP(i,N-1){
    int x,y; cin >> x >> y;
    --x, --y;
    tree[x].push_back(y);
    tree[y].push_back(x);
  }

  prod.resize(N);

  rec(tree, 0, -1);
  fill(ALL(visit),false);
  rec2(tree, 0, -1, 0);

  REP(i,N){
    LLI ans = ((dp2[i]+1)%M * dp[i]) % M;
    cout << ans << endl;
  }

  return 0;
}

