int n, m;
vector<vector<int>> edges;

vector<int> sub, ans;


void init(int V) {
	edges.assign(V, vector<int>());
	sub.resize(V);
	ans.resize(V);
}

int dfs1(int u, int par = -1) {
	int ret = 1;
	for (int v : edges[u])if (v != par) {
		ret = ret * (dfs1(v, u) + 1LL) % m;
	}
	return sub[u] = ret;
}

void dfs2(int u, int par = -1, int parv = 0) {
	int e = edges[u].size();
	vector<int> left, right;
	vector<int> dest;
	left.reserve(e);
	right.reserve(e);
	dest.reserve(e);

	for (int v : edges[u])if (v != par) {
		dest.push_back(v);
		int subtree = (sub[v] + 1) % m;
		left.push_back(subtree);
		right.push_back(subtree);
	}
	for (int i = 1; i < left.size(); i++) {
		left[i] = (int64_t)left[i] * left[i - 1] % m;
	}
	for (int i = right.size() - 2; i >= 0; i--) {
		right[i] = (int64_t)right[i] * right[i + 1] % m;
	}

	ans[u] = 1;
	ans[u] = ans[u] * (parv + 1LL) % m;
	if (!right.empty())ans[u] = (int64_t)ans[u] * right[0] % m;

	for (int i = 0; i < left.size(); i++)if (dest[i] != par) {
		int ret = 1;
		ret = ret * (parv + 1LL) % m;
		if (0 < i)ret = (int64_t)ret * left[i - 1]  % m;
		if (i + 1 < left.size())ret = (int64_t)ret * right[i + 1] % m;
		dfs2(dest[i], u, ret);
	}
}


int main() {
	ios::sync_with_stdio(0);
	cin.tie(0);

	cin >> n >> m;
	init(n);
	rep(i,n-1) {
		int x, y;
		cin >> x >> y;
		x--; y--;
		edges[x].push_back(y);
		edges[y].push_back(x);
	}

	dfs1(0);
	dfs2(0);
	rep(i,n) {
		cout << ans[i] << endl;
	}

	return 0;
}

