void dfs(int x, int p = -1)
{
        d[x] = 1;
        for(int y: v[x]){
                if(y == p){
                        continue;
                }
                dfs(y, x);
                d[x] = d[x] * d[y] % m;
        }
        d[x] = (d[x] + 1) % m;
}

void solve(int x, long long u, int p = -1)
{
        vector < long long > g = {1};
        for(int y: v[x]){
                if(y == p){
                        continue;
                }
                g.push_back(g.back() * d[y] % m);
        }
        res[x] = (d[x] - 1) * u % m;
        if(res[x] < 0){
                res[x] += m;
        }
        long long l = 1;
        for(int y: v[x]){
                if(y == p){
                        continue;
                }
                g.pop_back();
                long long nu = u * l % m;
                nu = nu * g.back() % m;
                nu = (nu + 1) % m;
                l = l * d[y] % m;
                solve(y, nu, x);
        }

}

