    int add(int a, int b, int mod = M) {return (a + b) % mod; /*int r = a + b; if (r >= mod) r -= mod; return r;*/}
    void ADD(int& a, int b, int mod = M) {a = (a + b) % mod; /*a += b; if (a >= mod) a -= mod;*/}
    int sub(int a, int b, int mod = M) {return (a - b + mod) % mod; /*int r = a - b; if (r < 0) r += mod; return r;*/}
    void SUB(int& a, int b, int mod = M) {a = (a - b + mod) % mod; /*a -= b; if (a < 0) a += mod;*/}
