{
	if(!b)
	{
		x=1;
		y=0;
		return a;
	}
	long q=a/b;
	long g=gcd(b,a-q*b,x,y);
	long z=x-q*y;
	x=y;y=z;
	return g;
}
long mydiv(long a,long b)
{
	long x,y,z;

