int N;
lint M;
vector<vector<int>> roads;
vector<lint> down, up;

void dfs_down(int now, int back){
    lint ret = 1;
    for(int i: roads[now]){
        if(i != back){
            dfs_down(i, now);
            ret = ret * (down[i] + 1) % M;
        }
    }
    down[now] = ret;
}

void dfs_up(int now, int back){
    lint mul = 1;
    for(int i = 0; i < roads[now].size(); i++){
        int x = roads[now][i];
        if(x != back){
            up[x] = up[x] * up[now] % M * mul % M;
            mul = (mul * (down[x] + 1)) % M;
        }
    }
    mul = 1;
    for(int i = int(roads[now].size()) - 1; i >= 0; i--){
        int x = roads[now][i];
        if(x != back){
            up[x] = (up[x] * mul + 1) % M;
            mul = (mul * (down[x] + 1)) % M;
            dfs_up(x, now);
        }
    }
}

int main(){
    cin >> N >> M;
    roads.resize(N);
    for(int i = 0; i < N - 1; i++){
        int x, y;
        cin >> x >> y;
        x--, y--;
        roads[x].push_back(y);
        roads[y].push_back(x);
    }
    down.resize(N);
    up.resize(N, 1);
    dfs_down(0, -1);
    dfs_up(0, -1);
    for(int i = 0; i < N; i++){
        cout << down[i] * up[i] % M << endl;
    }
}

