std::vector<bool> vis;std::vector<long long> ways;std::vector<long long> par;
std::vector<long long> topo;
long long dfs(long long num)
{
	vis[num]=1;
	for(auto it:g[num])
	{
		if(!vis[it])
		{
			par[it]=num;
			ways[num]=((ways[num]*(1+dfs(it)))%mod);
		}
	}
	topo.pb(num);
	return ways[num];
}
long long pro(long long a,long long b){return ((((a*b)%mod)+mod)%mod);}
pii eu(long long a,long long b)
{
	if(a==0){return {0,1};}
	if(b==0){return {1,0};}
	long long q=(a/b),r=(a%b);
	pii t=eu(b,r);
	return {t.y,((t.x)-(q*(t.y)))};

}
long long inv(long long num)
{
	if(__gcd(num,mod)!=1){return 0;}
	pii ans=eu(num,mod);
	ans.x=((((ans.x)%mod)+mod)%mod);
	return ans.x;
}
std::vector<long long> dp;
long long solve()
{
	long long n;cin>>n>>mod;
	g.resize(n);vis.resize(n,0);ways.resize(n,1);par.resize(n);
	REP(i,0,n-2)
	{
		long long a,b;cin>>a>>b;--a;--b;
		g[a].pb(b);g[b].pb(a);
	}
	dfs(0);//gives topo, ways
	dp.resize(n,-1);
	reverse(topo.begin(),topo.end());
	dp[0]=ways[0];
	for(auto it:topo)
	{
		if(dp[it]==0){continue;}
		long long p=par[it];
		if(dp[p]==-1){while(1){;}}
		long long den=((1+ways[it])%mod),num=dp[p];long long g=__gcd(mod,den);
		if(g!=1){
			den/=g;
			num/=g;
		}
		dp[it]=pro(ways[it],(pro(num,inv(den))+1));
	}
	for(auto it:dp){cout<<it<<"\n";}
}
signed main(){
	long long tt=1;
	//cin>>tt;
