struct LazySegmentTree{
private:
   int n;
   vector<ll> node,lazy;
public:
   LazySegmentTree(int sz,ll init=1){
      n=1;
      while(n<sz)n*=2;
      node.resize(2*n-1,init);
      lazy.resize(2*n-1,1);
   }

   void eval(int k,int l,int r){
      if(lazy[k]!=1)node[k]=node[k]*lazy[k]%mod;
      if(r-l>1){
          (lazy[2*k+1]*=lazy[k])%=mod;
          (lazy[2*k+2]*=lazy[k])%=mod;
      }
      lazy[k]=1;
   }
      //[a,b)にxを加算
   void add(int a,int b,ll x,int k=0,int l=0,int r=-1){
       if(r<0)r=n;
       eval(k,l,r);
       if(r<=a||b<=l)return;
       if(a<=l&&r<=b){
          (lazy[k]*=x)%=mod;
          eval(k,l,r);
       }
       else {
          add(a,b,x,2*k+1,l,(l+r)/2);
          add(a,b,x,2*k+2,(l+r)/2,r);
          node[k]=node[2*k+1]*node[2*k+2]%mod;
        }
   }
   //[a,b)での和を返す
   ll get(int a,int b,int k=0,int l=0,int r=-1){
      if(r<0)r=n;
      eval(k,l,r);
      if(r<=a||b<=l)return 1;
      if(a<=l&&r<=b)return node[k];
      ll xl=get(a,b,2*k+1,l,(l+r)/2);
      ll xr=get(a,b,2*k+2,(l+r)/2,r);
      return xl*xr%mod;
   }
};


ll dfs1(int x,int p){
    ll ret=1;
    int n=v[x].size();
    rep(i,n){
        int to=v[x][i];
        if(to==p)continue;
        ll res=dfs1(to,x);
        (ret*=(res+1))%=mod;
    }
    dp[x]=ret;
    return ret;
}


void dfs2(int x,int p){
    ll ret=ans[x]+1;
    int n=v[x].size();
    LazySegmentTree sg(n);
    rep(i,n){
        int to=v[x][i];
        if(to==p)continue;
        (ret*=(dp[to]+1))%=mod;
        sg.add(0,i,dp[to]+1);
        sg.add(i+1,n,dp[to]+1);
    }
    sg.add(0,n,ans[x]+1);
    rep(i,n){
        int to=v[x][i];
        if(to==p)continue;
        else ans[to]=sg.get(i,i+1);
    }
    for(auto to:v[x]){
        if(to==p)continue;
        dfs2(to,x);
    }
    ans[x]=ret%mod;
}
int main(){
    int n;
    cin>>n>>mod;
