int n, mod;
vector<vector<int>> g;
vector<int> dp;
vector<int> ans;

void dfs1(int v, int p) {
    dp[v] = 1;
    for (int to: g[v]) {
        if (to == p) {
            continue;
        }
        dfs1(to, v);
        dp[v] *= dp[to] + 1;
        dp[v] %= mod;
    }
}

void dfs2(int v, int p, int cur) {
    ans[v] = dp[v] * cur % mod;
    //cerr <<v + 1 << " " <<  dp[v] << " " << cur << endl;
    vector<int> sons;
    for (int to: g[v]) {
        if (to != p) {
            sons.push_back(to);
        }
    }
    vector<int> pref(sons.size() + 1, 1), suf(sons.size() + 1, 1);
    for (int i = 0; i < sons.size(); i++) {
        pref[i + 1] = pref[i] * (dp[sons[i]] + 1) % mod;
    }
    for (int i = sons.size() - 1; i >= 0; i--) {
        suf[i] = suf[i + 1] * (dp[sons[i]] + 1) % mod;
    }
    for (int i = 0; i < sons.size(); i++) {
        dfs2(sons[i], v, (cur * pref[i] % mod * suf[i + 1] % mod + 1) % mod);
    }
}

