ll n, m;
vector<vector<ll>> g;
vector<map<int, ll>> dp;

ll dfs(int current, int from) {
	if (dp[current].count(from)) {
		return dp[current][from];
	}
	ll v = 1;
	for (auto to : g[current]) {
		if (to == from) continue;
		ll d = dfs(to, current);
		v *= d;
		v %= m;
	}
	if (from != -1) {
		v++;
	}
	dp[current][from] = v % m;
	return dp[current][from];
}

