template<class T, int L=0, int R=2000000000>//[0,2e9]
class SegmentTree{
private:
  struct node{
    node *l = nullptr;
    node *r = nullptr;
    T val = 0;
    node(){}
  };
  node *root = new node();
  void update(int p,int val,node *cur,int l,int r){
    if(l==r){
        cur->val = val;
    }
    else{
      int m = (l+r)/2;
      if(p<=m){
        if(!cur->l){
          cur->l = new node();
        }
        update(p,val,cur->l,l,m);
        cur->val = cur->l->val;
        if(cur->r) cur->val *= cur->r->val;
      }
      else{
        if(!cur->r){
          cur->r = new node();
        }
        update(p,val,cur->r,m+1,r);
        cur->val = cur->r->val;
        if(cur->l) cur->val *= cur->l->val;
      }
    }
    cur->val %= modulo;
  }
  T query(int a,int b, node *cur,int l,int r){
    if(!cur or r < a or l > b) return 1;
    if(l>=a && r<=b){
      return cur->val;
    }
    int m = (l+r)/2;
    return query(a,b,cur->l,l,m) * query(a,b,cur->r,m+1,r) % modulo;
  }
public:   
  void update(int p,int val){
  	update(p, val, this->root, L, R);
  }
  T query(int l,int r){
  	return query(l, r, this->root, L, R);
  }
};
vector<int> adj[200200];
vector<ll> ways(200200), dp(200200);
SegmentTree<long long, 0, 200200> tree[200200];
void dfs(int u,int p){
	ways[u] = 1;
	for(int i=0;i<adj[u].size();i++){
		int v = adj[u][i];
		if(v!=p){
			dfs(v, u);
			tree[u].update(i, ways[v] + 1);
			ways[u] *= (ways[v] + 1);
			ways[u] %= modulo;
		}
	}
}
void go(int u,int p){
	//dp[u] = (dp[p] / (ways[u]+1) + 1) * ways[u];
	for(int i=0;i<adj[u].size();i++){
		int v = adj[u][i];
		if(v!=p){
			//dp[v] = dp[u] / (ways[u] + 1) + 1
			dp[v] = (tree[u].query(0, i-1) * tree[u].query(i+1, adj[u].size()) + 1) % modulo;
			tree[v].update(adj[v].size(), dp[v]);
			dp[v] = dp[v] * ways[v] % modulo;
			go(v, u);
		}
	}
}
void solve(){
	cin >> n >> modulo;
	for(int i=0;i<n-1;i++){
		int a,b;
		cin >> a >> b;
		adj[a].pb(b); adj[b].pb(a);
	}
	dfs(1,1);
	dp[1] = ways[1];
	go(1,1);
	for(int i=1;i<=n;i++){
		cout << dp[i] << endl;
	}
}
