        tree[x].emplace_back(y);
        tree[y].emplace_back(x);
        dp[x].emplace_back(1);
        pre[x].emplace_back(1);
        suf[x].emplace_back(1);
        dp[y].emplace_back(1);
        pre[y].emplace_back(1);
        suf[y].emplace_back(1);
    }
}

void mul_self(ll &lhs, ll rhs)
{
    lhs = lhs * rhs % m;
}

// let v be the root, count ways
ll dfs1(int v, int p)
{
    ll cnt = 1;
    for(size_t i = 0; i < tree[v].size(); i++)
    {
        int c = tree[v][i];
        if(c == p) continue;
        dp[v][i] = dfs1(c, v);
        mul_self(cnt, 1+dp[v][i]);
    }
    if(!tree[v].empty())
    {
        pre[v][0] = 1+dp[v][0];
        for(size_t i = 1; i < tree[v].size(); i++) mul_self(pre[v][i], pre[v][i-1] * (1+dp[v][i]));
        suf[v][tree[v].size()-1] = 1+dp[v][tree[v].size()-1];
        for(int i = tree[v].size()-2; i >= 0; i--) mul_self(suf[v][i], suf[v][i+1] * (1+dp[v][i]));
    }

    return cnt;
}

// change root from v to its childrens
void dfs2(int v, int p)
{
    for(size_t i = 0; i < tree[v].size(); i++)
    {
        int c = tree[v][i];
        if(c == p) continue;
        ll tmp = 1;
        if(i > 0) mul_self(tmp, pre[v][i-1]);
        if(i+1 < tree[v].size()) mul_self(tmp, suf[v][i+1]);
        ans[c] = dp[v][i];
        mul_self(ans[c], 1+tmp);
        dfs2(c, v);
    }
}

void process()
{
    ans[1] = dfs1(1, 1);
    dfs2(1, 1);
    for(int i = 1; i <= n; i++) cout << ans[i] << endl;
}

