struct Graph {
  vector<vector<int>> edge;
  Graph(int n = 0) { resize(n); }
  void resize(int n) { edge.resize(n, vector<int>()); }
  void addEdge(int from, int to) {
    edge[from].push_back(to); edge[to].push_back(from);
  }
  vector<int>& operator[](int from) { return edge[from]; }
};
int N, M;
vector<int> dp;
vector<ll> ans;
vector<vector<ll>> mul, mul2;

ll dfs(Graph& G, int cur, int prev) {
  if (dp[cur] != -1) return dp[cur];
  dp[cur] = 1;
  for (int to : G[cur]) {
    if (to == prev) continue;
    (dp[cur] *= (dfs(G, to, cur) + 1) % M) %= M;
  }
  return dp[cur];
}
void dfs2(Graph& G, int cur, int prev) {
  vector<ll> v;
  for (int to : G[cur]) {
    if (to != prev) {
      v.push_back((dp[to] + 1) % M);
      continue;
    }
    int i = all(lower_bound, G[to], i) - G[to].begin();
    v.push_back((mul[to][i] * mul2[to][i+1] + 1) % M);
  }
  ll m1 = 1, m2 = 1;
  int n = v.size();
  rep(i, n) {
    mul[cur].push_back((m1 *= v[i]) %= M);
    mul2[cur].push_back((m2 *= v[n-1-i]) %= M);
  }
  all(reverse, mul2[cur]);
  ans[cur] = (mul[cur][0] * mul2[cur][0]) % M;
  for (int to : G[cur]) {
    if (to == prev) continue;
    dfs2(G, to, cur);
  }
}

