void dfs (int u, int p) {
    auto it = find(gr[u].begin(), gr[u].end(), p);
    if (it != gr[u].end()) gr[u].erase(it);
    f[u] = 1;
    for (auto v: gr[u]) {
        dfs(v, u);
        f[u] = 1LL * f[u] * (f[v] + 1) % mod;
    }
}

void redfs (int u, int coef) {
    g[u] = coef + 1;
    vector <int> pre((int)gr[u].size()), suf((int)gr[u].size());
    int cur = 1;
    for (int i = 0; i < gr[u].size(); i++) {
        int v = gr[u][i];
        cur = 1LL * cur * (f[v] + 1) % mod;
        pre[i] = cur;
    }

    cur = 1;
    for (int i = (int)gr[u].size() - 1; i >= 0; i--) {
        int v = gr[u][i];
        cur = 1LL * cur * (f[v] + 1) % mod;
        suf[i] = cur;
    }

    for (int i = 0; i < gr[u].size(); i++) {
        int v = gr[u][i], ncoef = coef + 1;
        if (i) ncoef = 1LL * ncoef * pre[i - 1] % mod;
        if (i + 1 < gr[u].size()) ncoef = 1LL * ncoef * suf[i + 1] % mod;
        redfs(v, ncoef);
    }
}

