using namespace std;

template<typename T,typename Y>
struct Rerooting{

	using F =function<T(T,T)>;
	using G =function<T(T,Y)>;

	vector<vector<int>>g;
	vector<vector<T>>dp;//dp[v][i]:頂点vを根とする部分木のi番目の有向辺に対応する値
	vector<T>ans;//答え
	const F merge;//子を根とする部分木に対して二項演算を適用する
	const G add_root;//マージしたものに根を追加するときに子に対してする計算
	const G to_root;//マージしたものに根を追加するときに根に対してする計算
	const T identity;//単位元a・e=e・a=aが成り立つe

	Rerooting(int n,const F &merge,const G &add_root,const T &identity,const G &to_root):merge(merge),add_root(add_root),identity(identity),to_root(to_root){
		g.resize(n);
		dp.resize(n);
		ans.resize(n,identity);
	}

	void add_edge(int u,int v){
		g[u].emplace_back(v);
	}

	void build(int root=0){
		dfs1(root);
		dfs2(root,identity);
	}

	T dfs1(int v,int par=-1){//木dp
		T cul = identity;
		dp[v].resize(g[v].size(),identity);
		for(int i=0;i<g[v].size();++i){
			int u =g[v][i];
			if(u==par)continue;
			dp[v][i]=dfs1(u,v);
			cul=merge(cul,add_root(dp[v][i],g[v][i]));
		}
		return to_root(cul,v);
	}

	void dfs2(int v,const T &val ,int par=-1){
		for(int i=0;i<g[v].size();++i){
			if(g[v][i]==par){//値を再利用
				dp[v][i]=val;
				break;
			}
		}
		vector<T>dp_l(g[v].size()+1,identity),dp_r(g[v].size()+1,identity);
		for(int i=0;i<g[v].size();++i){//左から累積
			dp_l[i+1]=merge(dp_l[i],add_root(dp[v][i],g[v][i]));
		}
		for(int i=g[v].size()-1;i>=0;--i){//右から累積
			dp_r[i]=merge(dp_r[i+1],add_root(dp[v][i],g[v][i]));
		}

		ans[v]=to_root(dp_l[g[v].size()],v);

		for(int i=0;i<g[v].size();++i){//隣接する頂点に対して計算
			int u=g[v][i];
			if(u==par)continue;
			dfs2(u,to_root(merge(dp_l[i],dp_r[i+1]),v),v);
		}
	}
};

void solve()
{
	int n,m;
	cin>>n>>m;
	Rerooting<ll,ll>tree(n,[&](ll a,ll b){return a*b%m;},[&](ll a,ll b){return a+1;},1,[](ll a,ll b){return a;});
	rep(i,n-1){
		int x,y;
