lli rec(int curr, int prev)
{
  pair<int, int> key = make_pair(curr, prev);
  if (memo.count(key)) return memo[key];
  lli x = 1;
  each (next, g[curr]) {
    if (next == prev) continue;
    (x *= rec(next, curr) + 1) %= mod;
  }
  return memo[key] = x;
}

