ll M;

vvl adj;
vvl tree;

void create_tree(ll cur, ll parent) {
	for(const auto it : adj[cur]) {
		if(it != parent) {
			tree[cur].pb(it);
			create_tree(it, cur);
		}
	}
}

vl dp;
vl res;

ll first_run(ll cur) {
	ll foo = 1;

	for(const auto it : tree[cur]) {
		foo = (foo * (first_run(it) + 1)) % M;
	}

	dp[cur] = foo;
	return foo;
}


void res_run(ll cur, ll parent) {
	// dp tells me how many possibilities are below
	// parent tells me how many are up

	if(parent > 0) {
		res[cur] = (parent * dp[cur] + dp[cur] * (dp[cur] + 1)) / (dp[cur] + 1);
		res[cur] %= M;
	} else
		res[cur] = dp[cur];

	for(const auto it : tree[cur]) {
		res_run(it, res[cur]);
	}
}

int main(void){
	ios::sync_with_stdio(false);
	cin.tie(0);

	ll N;
	cin >> N >> M;

	adj.assign(N, vl());
	tree.assign(N, vl());
	dp.assign(N, 0);
	res.assign(N, 0);

	FOR(i,0,N-1) {
		ll x, y;
		cin >> x >> y;

		x--;
		y--;

		adj[x].pb(y);
		adj[y].pb(x);
	}

	create_tree(0, -1);

	first_run(0);

	res_run(0, -1);

	FOR(i,0,N) {
		cout << res[i] << endl;
	}
}

