vvi adj;

ll calc(vi &a)
{
    ll ret = 0;
    for (auto bl : a)
        ret += ret * bl + bl, ret %= mod;
    return ret;
}

ll dfs1(int v, int p = -1)
{
    vi vtemp;
    for (auto u : adj[v])
        if (u != p)
            vtemp.pb(dfs1(u, v));
    return val[v] = (calc(vtemp) + 1) % mod;
}

void dfs2(int v, int p = -1)
{
    ll oldval = 0;
    vll vtemp;
    for (auto u : adj[v])
        vtemp.pb(u);
    int n = vtemp.size();
    vll pref(n), suf(n);
    pref[0] = val[vtemp[0]];
    suf[n - 1] = val[vtemp[n - 1]];
    for (int i = 1; i < n; i++)
        pref[i] = val[vtemp[i]] + pref[i - 1] + val[vtemp[i]] * pref[i - 1], pref[i] %= mod;
    for (int i = n - 2; i >= 0; i--)
        suf[i] = val[vtemp[i]] + suf[i + 1] + val[vtemp[i]] * suf[i + 1], suf[i] %= mod;
    for (int i = 0; i < n; i++)
    {
        assert(n == vtemp.size());
        if (vtemp[i] == p)
            continue;
        ll pr = i ? pref[i - 1] : 0;

        ll s = i < n - 1 ? suf[i + 1] : 0;
        val[v] = pr + s + pr * s + 1, val[v] %= mod;
        // dbgm(v, p, i, vtemp[i], pr, s, val[s]);
        dfs2(vtemp[i], v);
    }
    ans[v] = suf[0] + 1, ans[v] %= mod;
    val[v] = oldval;
}

