// 次に任意の頂点について求める
void dfs2(int v, int p) {
    int sz = g[v].size();
    ans[v] = dp[v];
    vector<ll> lsum(sz + 1, 1), rsum(sz + 1, 1);
    for(int i = 0; i < sz; i++) {
        (lsum[i + 1] *= (lsum[i] * (dp[g[v][i]] + 1) % m)) %= m;
    }
    for(int i = sz - 1; i >= 0; i--) {
        (rsum[i] *= (rsum[i + 1] * (dp[g[v][i]] + 1) % m)) %= m;
    }
    for(int i = 0; i < sz; i++) {
        int u = g[v][i];
        if(u != p) {
            ll pre = lsum[i] * rsum[i + 1] % m;
            ll tmp1 = dp[v], tmp2 = dp[u];
            dp[v] = pre;
            (dp[u] *= (dp[v] + 1)) %= m;
            dfs2(u, v);
            dp[v] = tmp1;
            dp[u] = tmp2;
        }
    }
