int cnt,head[100010],to[200010],nxt[200010];
void add(int x,int y)
{
	cnt++;
	to[cnt]=y;
	nxt[cnt]=head[x];
	head[x]=cnt;
}
void dfs(int x,int fa)
{
	f[x]=1;
	for (int i=head[x];i;i=nxt[i])
	{
		int y=to[i];
		if (y==fa)
		{
			continue;
		}
		dfs(y,x);
		f[x]=f[x]*(f[y]+1)%Mod;
	}
}
void work(int x,int fa,ll g)
{
	ans[x]=f[x]*(g+1)%Mod;
	int k=0;
	p[k++]=ans[x];
	for (int i=head[x];i;i=nxt[i])
	{
		int y=to[i];
		if (y==fa)
		{
			continue;
		}
		p[k++]=(f[y]+1)%Mod;
	}
	q[k]=1;
	for (int i=k-1;i>=0;i--)
	{
		q[i]=q[i+1]*p[i]%Mod;
	}
	for (int i=1;i<k;i++)
	{
		p[i]=p[i]*p[i-1]%Mod;
	}
	k=0;
	for (int i=head[x];i;i=nxt[i])
	{
		int y=to[i];
		if (y==fa)
		{
			continue;
		}
		k++;
		work(y,x,p[k-1]*q[k+1]%Mod);
	}
}
