    ll n; cin >> n >> mod;
    for(ll i = 0; i < n-1; i++){
        ll u, v; cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    ll root = 1;
    for(ll i = 1; i <= n; i++)
        if(!pai[i]){
            solve(i);
            root = i;
        }
    for(ll i = 1; i <= n; i++)
        up[i] = 1;

    go(root);
    // for(ll i = 1; i <= n; i++)
