    // for(ll i = 1; i <= n; i++)
    //     cout << "up[" << i << "] = " << up[i] << endl;
    for(ll i = 1; i <= n; i++){
        ll res = (down[i] * up[i])%mod;
        cout << res << endl;
    }
    return 0;
}

