	int suf = 1;
	for (int i = (int)g[u].size()-1; i >= 0; i--)
	{
		int v = g[u][i];
		if (v == last) continue;

		solve2(v, u, mul(mul(up+1, pref[i]), suf));
		suf = mul(suf,  pd[v] + 1);
	}
}

