void down_dfs(ll u, ll par){
    down[u] = 1;
    for(int i=0;i<tree[u].size();++i){
        int to = tree[u][i];
        if(to!=par){
            down_dfs(to,u);
            down[u] = (down[u]*((down[to]+1)%m))%m;
        }
    }
}

void up_dfs(ll u, ll par){
    pref[0] = 1;
    ll x = 1;
    for(int i=0;i<tree[u].size()-1;++i){
        int child = tree[u][i];
        if(child!=par){
            x = (x*(down[child]+1))%m;
            pref[i+1] = x;
        }else{
            pref[i+1] = x;
        }
    }
    suff[tree[u].size()-1] = 1;
    x = 1;
    for(int i=tree[u].size()-1;i>0;--i){
        int child = tree[u][i];
        if(child!=par){
            x = (x*(down[child]+1))%m;
            suff[i-1] = x;
        }else{
            suff[i-1] = x;
        }
    }
    for(int i=0;i<tree[u].size();++i){
        int child = tree[u][i];
        if(child!=par){
            up[child] = (pref[i]*suff[i])%m;
            up[child] = (up[child]*(up[u]+1))%m;
        }
    }
    for(int i=0;i<tree[u].size();++i){
        int child = tree[u][i];
        if(child!=par){
            up_dfs(child,u);
        }
    }
}

