ll dpust[100005];
ll dpalt[100005];

ll phi;

ll par[100005];

ll us(ll a, ll b){
	ll ans = 1;
	while (b){
		if (b & 1){
			ans *= a;
			ans %= mod;
		}
		a *= a;
		a %= mod;
		b >>= 1;
	}
	return ans;
}

ll bol(ll a, ll b){
	a %= mod;
	b %= mod;
	if (a == 0 && b == 0) return 0;
	ll gcd = __gcd(a, b);
	a /= gcd;
	b /= gcd;
	assert(__gcd(b, mod) == 1);
	ll ans = a*us(b, phi-1);
	ans %= mod;
	return ans;
}

ll calphi(ll a){
	ll ans = a;
	for (int i = 2; i <= sqrt(a); i++){
		if (a % i == 0){
			ans /= i;
			ans *= (i-1);
			while (a % i == 0) a /= i;
		}
	}
	if (a > 1){
		ans /= a;
		ans *= a-1;
	}
	return ans;
}

void dfs1(int node, int ata){
	par[node] = ata;
	for (int ch: adj[node]){
		if (ch == ata) continue;
		dfs1(ch, node);
	}

	ll ans = 1;
	for (int ch: adj[node]){
		if (ch == ata) continue;
		ans *= 1 + dpalt[ch];
		ans %= mod;
	}
	dpalt[node] = ans; 
}

