ll mod(ll a, ll m) {
    return (a % m + m) % m;
}

void dfs(int x) {
    vis[x] = true;
    dp[x] = 1;
    prod[x][0].push_back(1);
    prod[x][1].push_back(1);
    vector<int> c;
    for(int y : adj[x]) {
        if(!vis[y]) {
            c.push_back(y);
            dfs(y);
            dp[x] = mod(dp[x] * (1 + dp[y]), m);
            prod[x][0].push_back(dp[x]);
        }
    }
    reverse(c.begin(), c.end());
    ll val = 1;
    for(int y : c) {
        val = mod(val * (1 + dp[y]), m);
        prod[x][1].push_back(val);
    }
    reverse(prod[x][1].begin(), prod[x][1].end());
}
void dfs2(int x) {
    vis[x] = true;
    int cnt = 0;
    dp[x] = mod(dp[x] * dp2[x], m);
    for(int y : adj[x]) {
        if(!vis[y]) {
            cnt++;
            dp2[y] = mod(1 + mod(dp2[x] * prod[x][0][cnt - 1], m) * prod[x][1][cnt], m);
            dfs2(y);
        }
    }
}

