void calcdfs(ll v,ll prev)
{
    dp[v]=1;
    for (auto u: adj[v])
    {
        if (u==prev) continue;
        calcdfs(u,v);
        dp[v]=mul(dp[v],dp[u]+1);
    }
    return;
}
void move(ll u,ll v)
{
    dp[v]=1;
    for (auto k:adj[v])
    {
        if (u==k) continue;
        dp[v]=mul(dp[v],dp[k]+1);
    }
    dp[u]=1;
    for (auto k:adj[u])
    {
        dp[u]=mul(dp[u],dp[k]+1);
    }
}
void answerdfs(ll v,ll prev)
{
    answer[v]=dp[v];
    for (auto u: adj[v])
    {
        if (u==prev) continue;
        ll pv=dp[u];
        move(u,v);
        answerdfs(u,v);
        dp[u]=pv;
        dp[v]=answer[v];
    }
    return;
}
