#include <bits/stdc++.h>
using namespace std;
using LL = long long;

int MOD;
vector<int> adj[111111];
int F[111111];
int G[111111];
int sub[111111];
int H[111111];
int pow2[111111];

int add(int a, int b){
    a += b;
    a %= MOD;
    if(a < 0) a += MOD;
    return a;
}

int mult(int a, int b){
    return (a * 1LL * b) % MOD;
}

void prep(int u, int p = -1){
    sub[u] = 1;
    for(int v : adj[u]){
        if(v == p) continue;
        prep(v, u);
        sub[u] += sub[v];
    }
}

void dfs(int u, int p){
    F[u]=1;
    vector<LL> pre;
    for(int v : adj[u]){
        if(v == p) continue;
        dfs(v, u);
        F[u] = mult(F[u], add(F[v], 1));
        pre.push_back(add(F[v], 1));
    }
    vector<LL> suf = pre;
    for(int i = int(suf.size()) - 1; i >= 0; i--){
        if(i + 1 < suf.size()) suf[i] = mult(suf[i], suf[i+1]);
    }
    for(int i = 1; i < pre.size(); i++) pre[i] = mult(pre[i], pre[i - 1]);
    int c = 0;
    for(int v : adj[u]){
        if(v == p) continue;
        H[v] = 1;
        if(c > 0)              H[v] = pre[c - 1];
        if(c + 1 < suf.size()) H[v] = mult(H[v], suf[c + 1]);
        c++;
    }
}

void dfs2(int u, int p){
    for(int v : adj[u]){
        if(v == p) continue;
        G[v] = 1;
        G[v] = add(G[v], mult(G[u], H[v]));
        dfs2(v, u);
    }
}

int main(){

    // 1. 入力情報取得.
    int N;
    scanf("%d %d", &N, &MOD);
    pow2[0] = 1;
    for(int i = 1; i <= N; i++) pow2[i] = add(pow2[i - 1], pow2[i - 1]);
    for(int i = 0; i < N - 1; i++){
        int u, v;
        scanf("%d %d", &u, &v);
        u--;
        v--;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    // 2. dp更新.
    prep(0, -1);
    dfs(0, -1);
    G[0] = 1;
    dfs2(0, -1);

    // 3. 出力.
    for(int i = 0; i < N; i++) printf("%d\n", mult(G[i], F[i]));
    return 0;
}

