ll N, M;
vvpl adj;
vvll dp, as1, as2;
vll chk;

ll dfs(ll x) {
	chk[x] = 0;
	ll tmp = 1;
	REP(i, adj[x].sz) {
		if (!chk[adj[x][i].fi]) continue;
		tmp = (tmp * (dp[x][i] = dfs(adj[x][i].fi))) % M;
	}
	return tmp + 1;
}

ll rec(ll x, ll n) {
	if (dp[x][n] + 1) return dp[x][n];
	ll y, nn;
	tie(y, nn) = adj[x][n];
	if (!chk[y]) {
		chk[y] = 1;
		ll adjs = adj[y].sz;
		as1[y].res(adjs);
		as2[y].res(adjs);
		as1[y][0] = 1;
		as2[y][adjs - 1] = 1;
		FOR(i, 1, adjs - 1) as1[y][i] = (as1[y][i - 1] * rec(y, i - 1)) % M;
		rFOR(i, 0, adjs - 2) as2[y][i] = (as2[y][i + 1] * rec(y, i + 1)) % M;
	}
	return dp[x][n] = (as1[y][nn] * as2[y][nn] + 1) % M;
}

void Solve() {

	cin >> N >> M;
	adj.asn(N, vpl());
	dp.asn(N, vll());
	as1.asn(N, vll());
	as2.asn(N, vll());
	chk.asn(N, 1);
	ll x, y;
	REP(i, N - 1) {
		cin >> x >> y;
		x--; y--;
		adj[x].pb(mp(y, adj[y].sz));
		adj[y].pb(mp(x, adj[x].sz - 1));
		dp[x].pb(-1);
		dp[y].pb(-1);
	}
	dfs(0);
	REP(i, N) {
		ll tmp = 1;
		REP(j, adj[i].sz) tmp = (tmp * rec(i, j)) % M;
		sal(tmp);
	}

}

