    rep(i,e[v].size()) {
        if (e[v][i] == par[v]) continue;
        add = add * dp[e[v][i]] % m;
    }
    dp[v] = (1 + add) % m;
    rep(i,e[v].size()) {
        if (i != 0) {
            l[v][i] = l[v][i-1];
        }
        if (e[v][i] == par[v]) continue;
        l[v][i] = l[v][i] * dp[e[v][i]] % m;
    }
    for (int i = (int)e[v].size()-1; i >= 0; i--) {
        if (i != (int)e[v].size()-1) {
            r[v][i] = r[v][i+1];
        }
        if (e[v][i] == par[v]) continue;
        r[v][i] = r[v][i] * dp[e[v][i]] % m;
    }
}

void dfr(int v, ll pre) {
    dp[v] = (dp[v] - 1 + m) % m;
    dp[v] = dp[v] * pre % m;

    rep(i,e[v].size()) {
        if (e[v][i] == par[v]) continue;
        ll nxt = 1;
        if (i != 0) nxt = nxt * l[v][i-1] % m;
        if (i != e[v].size()-1) nxt = nxt * r[v][i+1] % m;
        nxt = nxt * pre % m;
        nxt = (nxt + 1) % m;
        dfr(e[v][i], nxt);
    }
}

