int kMod;

vector<int> down, up;
vector<vector<int>> graph;

void DFSDown(int node, int par) {
    down[node] = 1;
    if (par != -1)
        graph[node].erase(find(graph[node].begin(), graph[node].end(), par));
    for (auto vec : graph[node]) {
        DFSDown(vec, node);
        down[node] = 1LL * down[node] * (1 + down[vec]) % kMod;
    }    
}

void DFSUp(int node, int par, int buff) {
    up[node] = 1LL * buff * down[node];

    vector<int> pref(graph[node].size()), suff(pref);
    for (int i = 0; i < (int)pref.size(); ++i) {
        pref[i] = (down[graph[node][i]] + 1) % kMod;
        if (i > 0) pref[i] = 1LL * pref[i] * pref[i - 1] % kMod;
    }
    for (int i = (int)pref.size() - 1; i >= 0; --i) {
        suff[i] = (down[graph[node][i]] + 1) % kMod;
        if (i < (int)pref.size() - 1) 
            suff[i] = 1LL * suff[i] * suff[i + 1] % kMod;
    }

    for (int i = 0; i < (int)graph[node].size(); ++i) {
        int left = (i == 0) ? 1 : pref[i - 1];
        int right = (i == (int)graph[node].size() - 1) ? 1 : suff[i + 1];    
        int coef = (1LL * left * right % kMod * buff % kMod + 1) % kMod;
        DFSUp(graph[node][i], node, coef);
    }
}

