        graph[a].push_back(b);
        graph[b].push_back(a);    
    }

    DFSDown(0, -1);
    DFSUp(0, -1, 1);

    for (int i = 0; i < n; ++i) {
        cout << up[i] % kMod << '\n';
    } 

    return 0;
}

