using namespace std;

long n, MOD;
vector<vector<long>> g;
long dp[100010], ans[100010];

void dfs1(int v, int p) {
  dp[v] = 1;
  for(int nv : g[v]) {
    if(nv == p) continue;
    dfs1(nv, v);
    dp[v] = dp[v] * -~dp[nv]%MOD;
  }
}

// 各頂点が根となるように遷移する。
void dfs2(int v, int p) {
  ans[v] = 1;
  // この時、nvがpだったらnvはvの子としての値を持ってる。
  // ここでans[v]が確定する。
  for(int nv : g[v]) ans[v] = ans[v] * -~dp[nv]%MOD;

  int N = g[v].size();
  vector<long> L(N,1), R(N,1);
  for(int i = 0; i < N; ++i) L[i+1] = L[i] * -~dp[g[v][i]]%MOD;
  for(int i =N-1;i > 0; --i) R[i-1] = R[i] * -~dp[g[v][i]]%MOD;

  for(int i = 0; i < N; ++i) {
    if(g[v][i] == p) continue;
    // ここでvをnvの子としての値に変換、遷移先で適切にansを計算
    // i番目の子の子としての値に変換したいなら、
    // i番目の子以外の子の情報を掛け合わせたのになる。
    // それは左からの累積積と右からの累積積を掛け合わせることで
    // O(1)で計算できる。
    dp[v] = 1;
    dp[v] = dp[v] * L[i]%MOD * R[i]%MOD;
    dfs2(g[v][i], v);
  }
}

