#include <bits/stdc++.h>

using namespace std;

typedef long long int ll;

const int N = (int) 1e5 + 10;

int n, mod;
int par[N];
int memo[N];
vector<int> vs[N];
vector<int> down[N];
vector<int> left_mult[N], right_mult[N];
vector<int> memo2[N];

int mult(ll a, ll b) {
    return (a * b) % mod;
}

void dfs(int node, int p) {
    par[node] = p;
    if(p != -1) down[p].push_back(node);
    for(int v : vs[node]) if(v != p) dfs(v, node);
    left_mult[node].resize(down[node].size());
    right_mult[node].resize(down[node].size());
}

int dp(int node) {
    int &ans = memo[node];
    if(ans != -1) return ans;
    ans = 1;
    for(int v : down[node]) ans = mult(ans, 1 + dp(v));
    for(int i = 0, j = down[node].size() - 1; i < down[node].size(); ++i, --j) {
        {
            int v = down[node][i];
            int v_ans = (1 + dp(v)) % mod;
            left_mult[node][i] = v_ans;
            if(i > 0) left_mult[node][i] = mult(left_mult[node][i - 1], left_mult[node][i]);
        }
        {
            int v = down[node][j];
            int v_ans = (1 + dp(v)) % mod;
            right_mult[node][j] = v_ans;
            if(j + 1 < down[node].size()) right_mult[node][j] = mult(right_mult[node][j + 1], right_mult[node][j]);
        }
    }
    return ans;
}

int get_index(int node, int target) {
    if(target == -1) return down[node].size();
    int lo = 0, hi = down[node].size() - 1;
    while(lo <= hi) {
        int m = lo + hi >> 1;
        if(down[node][m] >= target) hi = m - 1;
        else lo = m + 1;
    }
    return lo;
}

int get_below(int node, int ind) {
    if(ind == down[node].size()) {
        if(down[node].empty()) return 1;
        return right_mult[node][0];
    }
    int l = ind == 0 ? 1 : left_mult[node][ind - 1];
    int r = ind + 1 == down[node].size() ? 1 : right_mult[node][ind + 1];
    return mult(l, r);
}

int go(int node, int prev) {
    if(node == -1) return 0;
    int ind = get_index(node, prev);
    int &ans = memo2[node][ind];
    if(ans != -1) return ans;
    ans = 1;
    int below = get_below(node, ind);
    ans = mult(ans, below);
    ans = mult(ans, 1 + go(par[node], node));
    return ans;
}

void solve() {
    cin >> n >> mod;
    for(int i = 0; i < n - 1; ++i) {
        int u, v;
        cin >> u >> v;
        --u, --v;
        vs[u].push_back(v);
        vs[v].push_back(u);
    }
    for(int i = 0; i < n; ++i) {
        sort(vs[i].begin(), vs[i].end());
        memo2[i].resize(vs[i].size() + 1, -1);
    }
    dfs(0, -1);
    memset(memo, -1, sizeof(memo));
    dp(0);
    for(int i = 0; i < n; ++i) {
        cout << go(i, -1) << '\n';
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout.precision(20);
    cout << fixed;
    solve();
    return 0;
}

