		{
			dfs1(v,u);
			temp.push_back(cnt[v]+1);
			chil.push_back(v);
		}
	}


	if( temp.size() )
	{
		vector<int>fdp=temp;
		vector<int>bdp=temp;
		int p;
		p=1;

		for(size_t i=0;i<temp.size();i++)
		{
			p*=temp[i];
			p%=M;
			fdp[i]=p;
		}
		p=1;
		for(int i=temp.size()-1;i>=0;i--)
		{
			p*=temp[i];
			p%=M;
			bdp[i]=p;
		}

		for(size_t i=0;i<temp.size();i++)
		{
			int p1 = ( i ? fdp[i-1] : 1);
			int p2 = ( i+1!=temp.size() ? bdp[i+1] : 1 );
			dp[u][ chil[i] ]=(p1*p2)%M;
		}
		cnt[u]*=bdp[0];
		cnt[u]%=M;
	}

}

void dfs2(int u=1,int p=0)
{
	unordered_map<int,int>udp;
	unordered_map<int,int>pdp;
	int ucnt;
	int pcnt;
	if( p )
	{
		// make yourself root

		udp = dp[u];
		pdp = dp[p];

		ucnt = cnt[u];
		pcnt = cnt[p];

		cnt[u] *= ( dp[p][u] + 1);
		cnt[u] %= M;
		for(auto &it:dp[u])
		{
			it.second *=  (dp[p][u]+1);
			it.second %=  M;
		}
		dp[u][p]=ucnt;


	}
	// update yourself as root
	ans[u]=cnt[u];
	for(auto v:g[u])
	{
		if(v!=p)
		{
			dfs2(v,u);
		}
	}
	if( p )
	{
		// reform yourself
		dp[u]=udp;
		dp[p]=pdp;
		cnt[u]=ucnt;
		cnt[p]=pcnt;
	}
}



