using namespace std;

class Tree {
  public:
    Tree(int size):
        m_edges(size),
        m_down(size, 1),
        m_up(size, 1) {}

    void add_edge(int x, int y) {
        m_edges[x].push_back(y);
        m_edges[y].push_back(x);
    }

    void count_independent_sets(int modulo) {
        dfs_down(0, modulo);
        m_up[0] = 1;
        dfs_up(0, modulo);
    }

    int independent_sets_with(int node, int modulo) const {
        return 1LL * m_down[node] * m_up[node] % modulo;
    }

  private:
    void dfs_down(int node, int modulo, int father = -1) {
        m_down[node] = 1;
        for (auto &x : m_edges[node]) {
            if (x == father)
                continue;
            dfs_down(x, modulo, node);
            m_down[node] = 1LL * m_down[node] * (1 + m_down[x]) % modulo;
        }
    }

    void dfs_up(int node, int modulo, int father = -1) {
        int ways = 1;
        auto add = [&](int x) {
            if (x == father)
                return;
            m_up[x] = 1LL * m_up[x] * ways % modulo;
            ways = 1LL * ways * (m_down[x] + 1) % modulo;
        };

        for_each(m_edges[node].begin(), m_edges[node].end(), add);
        ways = m_up[node];
        for_each(m_edges[node].rbegin(), m_edges[node].rend(), add);

        for (auto &x: m_edges[node])
            if (x != father) {
                m_up[x] = (m_up[x] + 1) % modulo;
                dfs_up(x, modulo, node);
            }
    }

    vector< vector<int> > m_edges;
    vector<int> m_down, m_up;
};

int main() {
    ios::sync_with_stdio(false);

    int N, M; cin >> N >> M;
    Tree T(N);
    for (int i = 1; i < N; ++i) {
        int x, y; cin >> x >> y;
        T.add_edge(x - 1, y - 1);
    }

    T.count_independent_sets(M);

    for (int i = 0; i < N; ++i)
        cout << T.independent_sets_with(i, M) << "\n";
}

