const int lim = 100000 + 100;

int N;
vec<int, 2> G;

ll MOD;

ll dp[lim], ans[lim];
vector<ll> dp2[lim];

void dfs(int v, int p = -1) {
  dp[v] = 1;
  for (int i = 0; i < G[v].size(); i++) {
    int u = G[v][i];
    if (u == p) {
      continue;
    }
    dfs(u, v);
    dp[v] = dp[v] * (1 + dp[u]) % MOD;
  }
}

void dfs2(int v, int p = -1, int vi = -1) {
  dp2[v].clear();
  dp2[v].resize(G[v].size(), 0);
  ll pre = 1;
  if (p != -1) {
    pre = (dp2[p][vi] + 1) % MOD;
  }
  vector<ll> f(G[v].size(), 1);
  for (int i = 0; i < G[v].size(); i++) {
    int u = G[v][i];
    if (u == p) {
      continue;
    }
    f[i] = (1 + dp[u]) % MOD;
  }
  vector<ll> L(G[v].size() + 1, 1), R(G[v].size() + 1, 1);
  for (int i = 0; i < G[v].size(); i++) L[i + 1] = L[i] * f[i] % MOD;
  for (int i = G[v].size() - 1; i >= 0; i--) R[i] = R[i + 1] * f[i] % MOD;
  for (int i = 0; i < G[v].size(); i++) {
    int u = G[v][i];
    if (u == p) {
      continue;
    }
    dp2[v][i] = pre * L[i] % MOD * R[i + 1] % MOD;
    dfs2(u, v, i);
  }
  ans[v] = dp[v] * pre % MOD;
}

int main() {
  while (cin >> N >> MOD) {
    G.clear();
    G.resize(N);
    for (int i = 0; i < N - 1; i++) {
      int x, y;
      cin >> x >> y;
      --x;
      --y;
      G[x].push_back(y);
      G[y].push_back(x);
    }
    dfs(0);
    dfs2(0);
    for (int v = 0; v < N; v++) cout << ans[v] << endl;
  }
  return 0;
}

