ll down[N];
ll up[N];

void dfsdown(int u,int p)
{
    down[u] = 1;

    for(auto v:G[u])
    {
        if (v == p) continue;
        dfsdown(v,u);
        down[u] = (down[u]*(down[v]+1))%m;
        children[u].PB(v);
    }
    int n = children[u].size();
    if (n > 0)
    {
        pref[u].PB(down[children[u][0]]+1);
        REP(i,1,n-1)
        {
            pref[u].PB((pref[u][i-1]*(down[children[u][i]]+1))%m);
        }
        suff[u].PB(down[children[u][n-1]]+1);
        REPI(i,n-2,0)
        {
            suff[u].PB((suff[u].back()*(down[children[u][i]]+1))%m);
        }
        reverse(suff[u].begin(),suff[u].end());
    }
}

void dfsup(int u,int p,int idx)
{
    if (p == -1) up[u] = 1;
    else
    {
        up[u] = up[p];
        if (idx > 0) up[u] = (up[u]*pref[p][idx-1])%m;
        //cout << u << ' ' << pref[p][idx-1] << endl;
        if (idx < suff[p].size()-1) up[u] = (up[u]*suff[p][idx+1])%m;
        up[u]++;
    }
    int i = -1;
    for(auto v:children[u])
    {
        i++;
        dfsup(v,u,i);
    }
}

