void dfs1(int s, vector<int > adj[], int vis[],long long int st[], long long int x){
	vis[s] = 1;
	int v;
	long long int ans=1;
	for (int i=0;i<adj[s].size();i++){
		v = adj[s][i];
		if (!vis[v]){
			dfs1(v, adj, vis, st, x);
			ans = ((ans%x)*((st[v]+1)%x)%x);
		}
	}
	st[s] = ans;
}

void dfs2(int s,vector<int > adj[], int vis[], long long int st[],long long int rt[], long long int x){
	vis[s] = 1;
	int v;
	for (int i=0;i<adj[s].size();i++){
		v = adj[s][i];
		if(!vis[v]){
			rt[v] = ((st[v]%x)*((1 + (rt[s]/(1+st[v])))%x)%x);
			dfs2(v, adj, vis, st, rt, x);
		}
	}
}
