llongVV edges;
llongVV dp;
llongVV memo;
llong M;

llong search(llong now, llong parent) {
    FOR(i, edges[now].size()) {
        if(edges[now][i] == parent) {
            if(memo[now][i] >= 0) return memo[now][i];
            else break;
        }
    }
    llong ret = 1;

    FOR(i, edges[now].size()) {
        llong to = edges[now][i];
        if(to == parent) continue;
        if(dp[now][i] == -1) {
            llong cnt = search(to, now);
            dp[now][i] = cnt;
        }
        ret *= dp[now][i];
        ret %= M;
    }

    FOR(i, edges[now].size()) {
        if(edges[now][i] == parent) {
            memo[now][i] = (ret + 1) % M;
            break;
        }
    }
    return (ret + 1) % M;
};

