// DP
template<typename T>
struct rerooting_dp {
  struct edge {
    int v; T dp_sub;
    edge(int v) : v(v) {}
  };

  using Edges = vector<edge>;
  using Graph = vector<Edges>;
  Graph G;
  const T ident;
  vector<T> dp;

  using Fm = function<T(T, T)>;
  using Ft = function<T(T)>;
  const Fm f_merge;
  const Ft f_trans;

  rerooting_dp(int N, const T &ident, const Fm fm, const Ft ft)
    : G(N), ident(ident), dp(N, ident), f_merge(fm), f_trans(ft) {}

  void add_edge(int u, int v) {
    G[u].push_back(edge(v));
    G[v].push_back(edge(u));
  }

  T dfs(int u, int p=-1) {
    T res = ident;
    int d = G[u].size();
    for (auto &e : G[u]) {
      if (e.v == p) continue;
      e.dp_sub = dfs(e.v, u);
      res = f_merge(res, e.dp_sub);
    }
    return f_trans(res);
  }

  void dfs2(int u, T par, int p=-1) {
    int d = G[u].size();
    rep(i, d) if (G[u][i].v == p) G[u][i].dp_sub = par;

    for (auto &e : G[u]) dp[u] = f_merge(dp[u], e.dp_sub);

    vector<T> res_l(d+1, ident), res_r(d+1, ident);
    rep(i, d)  res_l[i+1] = f_merge(res_l[i], G[u][i].dp_sub);
    drep(i, d) res_r[i] = f_merge(res_r[i+1], G[u][i].dp_sub);

    rep(i, d) {
      auto e = G[u][i];
      if (e.v == p) continue;
      dfs2(e.v, f_trans(f_merge(res_l[i], res_r[i+1])), u);
    }
  }

  vector<T> build() {
    dfs(0);
    dfs2(0, ident);
    return dp;
  }
};


int main() {
  int N; cin >> N >> MOD;

  auto f_merge = [&] (mint a, mint b) {
    return a*b;
  };
  auto f_trans = [&] (mint a) {
    return a+1;
  };

  rerooting_dp<mint> G(N, mint(1), f_merge, f_trans);

  for (int i = 0; i < N-1; ++i) {
    int a, b;
    cin >> a >> b;
    a--; b--;
    G.add_edge(a, b);
  }

  auto dp = G.build();
  rep(i, N) cout << dp[i] << endl;
  return 0;
}

