LL dfs1(int u, int p = -1) {
    LL ret = 1;
    for (auto v: adj[u]) {
        if (v == p) continue;
        dp[u][v] = dfs1(v, u);
        ret = ret * ((1 + dp[u][v]) % M) % M;
    }
    return ret;
}

void dfs2(int u, int p = -1) {
    ans[u] = 1;
    for (auto v: adj[u])
        ans[u] = ans[u] * ((dp[u][v] + 1) % M) % M;

    int n = adj[u].size();
    VLL left(n), right(n);
    forn(i, 0, n) left[i] = right[i] = (dp[u][adj[u][i]] + 1) % M;
    forn(i, 1, n) left[i] = left[i] * left[i-1] % M;
    for (int i = n - 2; i >= 0; i--)
        right[i] = right[i] * right[i + 1] % M;

    forn(i, 0, n) {
        int v = adj[u][i];
        if (v != p) {
            dp[v][u] = 1;
            if (i) dp[v][u] = dp[v][u] * left[i-1] % M;
            if (i < n - 1) dp[v][u] = dp[v][u] * right[i+1] % M;
            dfs2(v, u);
        }
    }
}

