vi graph[maxn];

void dfs(int u,int p){
	dp1[u] = 1;
	vi nodes;
	for(auto &v : graph[u]){
		if(v == p)continue;
		nodes.pb(v);
		dfs(v,u);
	}
	if(nodes.empty())return;
	dp2[0] = dp1[nodes[0]]+1;
	for(int i = 1; i < nodes.size(); i++){
		dp2[i] = dp2[i-1];
		dp2[i] += ((dp2[i-1]%M)*(dp1[nodes[i]]%M))%M;
		dp2[i] %= M;
	}
	dp1[u] = dp2[nodes.size()-1];
}
void dfs2(int u,int p, ll arriba){
	ll sum = 1;
	for(auto &v : graph[u]){
		if(v == p)continue;
		sum *= ll(dp1[v]+1);
	}
	for(auto &v : graph[u]){
		if(v == p)continue;
		sum /= ll(dp1[v]+1);
		dp3[v] = ((sum%M)*(arriba%M))%M; dp3[v]++;
		dp3[v] %= M;
		sum *= ll(dp1[v]+1);
		dfs2(v,u,dp3[v]);
	}
}
