	int N,M;
	cin >> N >> M;
	vector<int> x(N-1),y(N-1);
	FOR(i,0,N-1) cin >> x[i] >> y[i];
	FOR(i,0,N-1) x[i]--,y[i]--;

	if(N==1){
		cout << 1 << endl;
		return 0;
	}


	vector< vector<int> > G(N);
	for(int i=0;i<N-1;i++){
		G[x[i]].push_back(y[i]);
		G[y[i]].push_back(x[i]);
	}
	vector< map<int,int> > ma(N);
	for(int i=0;i<N;i++){
		for(int j=0;j<G[i].size();j++){
			ma[ i ][ G[i][j] ] = j;
		}
	}
	vector<ll> val(N,1);

	vector< func<ll> > dp(N);
	for(int i=0;i<N;i++){
		dp[i].init(G[i].size(),1,M);
	}

	auto route = leaf_to_root(x,y,0);
	for(auto a:route){
		int p = a.first;
		int c = a.second;
		( val[p] *= val[c]+1LL ) %= M;
		dp[p].update(ma[p][c],(val[c]+1LL)%M );
	}

	for(int i=0;i<N;i++) dp[i].calc();

	reverse(route.begin(),route.end());
	for(auto a:route){
		int c = a.second;
		int p = a.first;
		ll v = dp[p].get_except(ma[p][c]);
		dp[c].final_updete(ma[c][p],(v+1LL)%M);
	}

	for(int i=0;i<N;i++){
		cout << dp[i].get_all() << endl;
	}


}

