ll mult(ll a, ll b){
	//~ ll mod = mod;
	return (a%mod*b%mod+mod)%mod;
}
ll add(ll a, ll b){
	//~ ll mod = modd;
	return (a%mod+b%mod+mod)%mod;
}
pi merge(pi a, pi b){
	pi p;
	p.all_white = mult(a.all_white, b.all_white);
	p.sth_is_black = add(mult(a.all_white, b.sth_is_black), mult(a.sth_is_black, add(b.all_white, b.sth_is_black)));
	return p;
}
pi process(pi p){
	return mp(p.all_white, add(p.sth_is_black, p.all_white));
}
void dfs_one(ll x, ll par){
	pi p = mp(1,0);
		for (auto i:adjlist[x]){
		if (i == par)continue;
		children[x].pb(i);
		dfs_one(i, x);
		//~ cout << "hi";
		p = merge(p, down[i]);
		downs[x].pb(down[i]);
	}
	down[x] = process(p);
}
void dfs_two(ll x, ll par){
	for (ll i = 0; i < children[x].size(); i++){
		pi p = mp(1, 0);
		if (i != 0){
			p = merge(p, pre[x][i-1]);
		}
		if (i != (ll)children[x].size()-1){
			p = merge(p, suf[x][i+1]);
		}
		if (x != 1)p = merge(p, up[x]);
		ll b = children[x][i];
		up[b] = process(p);
		dfs_two(b, x);
	}
}
