#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll max_n = 1e5 + 50, inf = 1e15;
ll dp1[max_n], dp2[max_n]; // dp1 is the no. of ways to paint the subtree at i if i is black
// dp2 is final answer for node i
vector<ll> adj[max_n];
ll n, m;

void dfs1(ll curr, ll par)
{
    dp1[curr] = 1;
    for (ll &neigh : adj[curr])
    {
        if (neigh == par)
            continue;
        dfs1(neigh, curr);
        dp1[curr] *= dp1[neigh] + 1;
        dp1[curr] %= m;
    }
}

void dfs2(ll curr, ll par, ll par_contrib)
{
    dp2[curr] = (1 + par_contrib) * dp1[curr];
    dp2[curr] %= m;
    vector<ll> pref, suff;
    for (ll &neigh : adj[curr])
    {
        if (neigh == par)
            continue;
        pref.push_back(1 + dp1[neigh]);
        suff.push_back(1 + dp1[neigh]);
    }
    for (int i = 1; i < pref.size(); ++i)
    {
        pref[i] = pref[i - 1] * pref[i];
        pref[i] %= m;
    }
    for (int i = int(suff.size()) - 2; i >=0; --i)
    {
        suff[i] = suff[i+1] * suff[i];
        suff[i] %= m;
    }
    ll cnt = 0;
    for (ll &neigh : adj[curr])
    {
        if (neigh == par)
            continue;
        ll ways = (1 + par_contrib);
        if (cnt > 0)
            ways *= pref[cnt - 1];
        ways %= m;
        if (cnt < (int(suff.size()) - 1))
            ways *= suff[cnt + 1];
        ways %= m;
        dfs2(neigh, curr, ways);
        ++cnt;
    }
}

