ll down[maxn], up[maxn];

int idx[maxn];

void get_down(int u, int p){
	down[u] = 1;

	for(int i = 0; i < (int)g[u].size(); i++){
		int v = g[u][i];
		if(v != p){
			get_down(v, u);
			ll x = (down[v] + 1) % m;
			down[u] = (down[u] * x) % m;
			idx[v] = i;
		}
	}

	for(int i = 0; i < (int)g[u].size(); i++){
		int v = g[u][i];
		if(v == p)
			pref[u][i] = 1;
		else
			pref[u][i] = (down[v] + 1) % m;
		if(i)
			pref[u][i] = (pref[u][i] * pref[u][i - 1]) % m;
	}

	for(int i = (int)g[u].size() - 1; i >= 0; i--){
		int v = g[u][i];
		if(v == p)
			suff[u][i] = 1;
		else
			suff[u][i] = (down[v] + 1) % m;
		if(i + 1 != (int)g[u].size())
			suff[u][i] = (suff[u][i] * suff[u][i + 1]) % m;
	}
}

void get_up(int u, int p){

	if(u == 1)
		up[u] = 1;
	else{
		up[u] = up[p];
		int l = idx[u] - 1;
		int r = idx[u] + 1;
		if(l >= 0)
			up[u] = (up[u] * pref[p][l]) % m;
		if(r < (int)g[p].size())
			up[u] = (up[u] * suff[p][r]) % m;
		up[u] = (up[u] + 1) % m;
	}

	for(int i = 0; i < (int)g[u].size(); i++){
		int v = g[u][i];
		if(v != p)
			get_up(v, u);
	}
}

