ll m;
class rerooting {
    vector<vector<int>>& g;
    int n;
    vector<VL> l, r;
    VL dp;
public:
    rerooting(vector<vector<int>>& g, int start = 0) : g(g), n(g.size()), l(n), r(n), dp(n) {
        dfs1(start, -1), dfs2(start, 1);
    }
    void dfs1(int now, int par) {
        l[now].reserve(g[now].size());
        r[now].reserve(g[now].size());
        l[now].push_back(1);
        each(to, g[now]) {
            if (to == par)continue;
            dfs1(to, now);
            l[now].push_back(dp[to] + 1);
        }
        if (par != -1)g[now].erase(find(all(g[now]), par));
        FOR(i, 2, l[now].size())r[now].push_back(l[now][i]);
        r[now].push_back(1);
        FOR(i, 1, l[now].size())l[now][i] *= l[now][i - 1];
        rFOR(i, 0, r[now].size() - 1)r[now][i] *= r[now][i + 1];
        dp[now] = l[now].back();
        l[now].pop_back();
    }
    void dfs2(int now, const ll& pardp) {
        (dp[now] *= pardp) %= m;
        FOR(i, 0, g[now].size()) {
            dfs2(g[now][i], (pardp * l[now][i] % m * r[now][i] % m + 1) % m);
        }
    }
    void print(string s) {
        FOR(i, 0, n)cout << dp[i] << (i == n - 1 ? "\n" : s);
    }
};

