void dfs1(ll v, ll p = -1) {
    // 行きの処理はこのへんに書く
    ll x = 1;
    for(ll to : G[v]) {
        if(to == p) {
            continue;
        }
        dfs1(to, v);
        // 帰りの処理はこのへんに書く
        x = x * dp1[to] % mod;
    }
    dp1[v] = x + 1;
}

void dfs2(ll v, ll p = -1) {
    // 行きの処理はこのへんに書く
    if(p == -1) {
        dp2[v] = 1;
    }
    vl ruiL(G[v].size(), 1);
    rep(i, G[v].size()) {
        ll to = G[v][i];
        if(i-1 >= 0) {
            ruiL[i] = ruiL[i-1];
        }
        if(to == p) {
            continue;
        }
        ruiL[i] = dp1[to] * ruiL[i] % mod;
    }
    vl ruiR(G[v].size(), 1);
    for(ll i = G[v].size()-1; i >= 0; i--) {
        ll to = G[v][i];
        if(i+1 < G[v].size()) {
            ruiR[i] = ruiR[i+1];
        }
        if(to == p) {
            continue;
        }
        ruiR[i] = dp1[to] * ruiR[i] % mod;
    }
    rep(i, G[v].size()) {
        ll to = G[v][i];
        if(to == p) {
            continue;
        }
        ll x = 1;
        if(i-1 >= 0) {
            x = x * ruiL[i-1] % mod;
        }
        if(i+1 < G[v].size()) {
            x = x * ruiR[i+1] % mod;
        }
        dp2[to] = (x * dp2[v] + 1) % mod;
        dfs2(to, v);
    }
}

void dfs3(ll v, ll p = -1) {
    // 行きの処理はこのへんに書く
    ans[v] = dp2[v];
    for(ll to : G[v]) {
        if(to == p) {
            continue;
        }
        ans[v] = ans[v] * dp1[to] % mod;
        dfs3(to, v);
        // 帰りの処理はこのへんに書く
    }
}

