void dfs(int u) {
    if(p[u] != -1) {
        int v = p[u];
        int j = lower_bound(g[v].begin(), g[v].end(), u) - g[v].begin();
        ans[u] = (f[u] + 1ll * f[u] * answ[v][j] % M) % M;
        for(int i = 0; i < g[u].size(); ++i) {
            int k = i - 1;
            int l = i + 1;
            int val = 1;
            if(k >= 0) val = 1ll * val * fw[u][k] % M;
            if(l < g[u].size()) val = 1ll * val * bw[u][l] % M;
            answ[u][i] = (val + 1ll * val * answ[v][j] % M) % M;
        }
    } else {
        ans[u] = f[u];
        for(int i = 0; i < g[u].size(); ++i) {
            int k = i - 1;
            int l = i + 1;
            int val = 1;
            if(k >= 0) val = 1ll * val * fw[u][k] % M;
            if(l < g[u].size()) val = 1ll * val * bw[u][l] % M;
            answ[u][i] = val;
        }
    }
    for(int v : g[u]) {
        dfs(v);
    }
}

