ll calc(ll here, ll father){

	return total[father]/ (down[here]+1  );

}

void dfs(ll here, ll father){

	p[here] = father;
	ll f = tree[here].size();

	for(ll i = 0; i < f; i++){

		if( tree[here][i] != father ){

			dfs(tree[here][i], here);			
			total[here]*= (down[ tree[here][i]] + 1 );

		}

	}

	down[here] = multi(down[here], total[here]);

}


void dfs2(ll here, ll father){

	if(here != 1){
		up[here] = multi( up[ p[father] ] +1 , calc(here, father) );
		up[here] =  (up[here]+1)%m;
	}


	ll f = tree[here].size();

	for(ll i = 0; i < f ; i++){

		if( tree[here][i] != father ){
			dfs2(tree[here][i], here);
		}
	}


}

