vi adj[111111];

int add(int a, int b)
{
	a+=b;
	a%=MOD;
	if(a<0) a+=MOD;
	return a;
}

int mult(int a, int b)
{
	return (a*1LL*b)%MOD;
}

int F[111111];
int G[111111];
int sub[111111];

void prep(int u, int p=-1)
{
	sub[u]=1;
	for(int v:adj[u])
	{
		if(v==p) continue;
		prep(v,u);
		sub[u]+=sub[v];
	}
}
int H[111111];
int pow2[111111];
void dfs(int u, int p)
{
	F[u]=1;
	vector<ll> pre;
	for(int v:adj[u])
	{
		if(v==p) continue;
		dfs(v,u);
		F[u]=mult(F[u],add(F[v],1));
		pre.pb(add(F[v],1));
	}
	vector<ll> suf=pre;
	for(int i=int(suf.size())-1;i>=0;i--)
	{
		if(i+1<suf.size()) suf[i]=mult(suf[i],suf[i+1]);
	}
	for(int i=1;i<pre.size();i++) pre[i]=mult(pre[i],pre[i-1]);
	int c=0;
	for(int v:adj[u])
	{
		if(v==p) continue;
		H[v]=1;
		if(c>0) H[v]=pre[c-1];
		if(c+1<suf.size()) H[v]=mult(H[v],suf[c+1]);
		c++;
	}
}
void dfs2(int u, int p)
{
	for(int v:adj[u])
	{
		if(v==p) continue;
		//G[v]
		G[v]=1;
		G[v]=add(G[v],mult(G[u],H[v]));
		//cerr<<v<<' '<<F[v]<<' '<<G[v]<<'\n';
		dfs2(v,u);
	}
}
