unordered_map<pair<int,pair<int,int>>,bool, HASH2> vis;
int n,m;
int dfs(int i, int j, int req){
	if(vis[{i,{j,req}}]){
		if(req==i) return dp[{i,j}].fr;
		else return dp[{i,j}].sc;
	}
	vis[{i,{j,req}}]=1;
	ll ans1 = 1, ans2 = 1;
	if(req==i){
		for(auto v:g[i]){
			if(v==j) continue;
			ans1 = (ans1*dfs(min(i,v),max(v,i),v))%m;
		}
		dp[{i,j}].fr = 1+ans1;
		// trace(i,j,req,1+ans1);
		return 1+ans1;
	}
	else{
		for(auto v:g[j]){
			if(v==i) continue;
			ans2 = (ans2*dfs(min(v,j),max(v,j),v))%m;
		}
		dp[{i,j}].sc = 1+ans2;
		// trace(i,j,req,1+ans2);
		return 1+ans2;
	}
}
