    for (int v : graph[u]) {
      if (v == p) {
        continue;
      }
      self(v, u);
      dp[u] *= dp[v];
    }
    ++dp[u];
  })(0, -1);
  vector<mod_int<>> ans(n);
  y_combinator([&](auto self, int u, int p, mod_int<> p_val) -> void {
    vector<mod_int<>> pref, suff;
    pref.push_back(1);
    for (int v : graph[u]) {
      if (v == p) {
