using namespace std;
using ll = long long;

ll MOD;
vector<int> path[100010];
ll dp[100010], ans[100010];

ll dfs(int v, int r) {
    dp[v] = 1;
    for (int sv : path[v]) {
        if (sv == r) continue;
        dp[v] *= dfs(sv, v) + 1;
        dp[v] %= MOD;
    }
    return dp[v];
}

void edfs(int v, int r, ll par) {
    ans[v] = dp[v] * (par + 1) % MOD;

    vector<int> chv = {-1};
    for (int sv : path[v]) {
        if (sv == r) continue;
        chv.push_back(sv);
    }
    int L = chv.size() - 1;

    ll fore[L + 2], back[L + 2];
    fore[0] = back[L + 1] = 1;
    for (int i = 1; i <= L; ++i) fore[i] = fore[i - 1] * (dp[chv[i]] + 1) % MOD;
    for (int i = L; i >= 1; --i) back[i] = back[i + 1] * (dp[chv[i]] + 1) % MOD;

    for (int i = 1; i <= L; ++i) {
        edfs(chv[i], v, fore[i - 1] * back[i + 1] % MOD * (par + 1) % MOD);
    }
}

int main() {
    int N;
    cin >> N >> MOD;
    for (int i = 0; i < N - 1; ++i) {
        int u, v;
        cin >> u >> v;
        --u, --v;
        path[u].push_back(v);
        path[v].push_back(u);
    }

    dfs(0, -1);
    edfs(0, -1, 0);
    for (int v = 0; v < N; ++v) cout << ans[v] << endl;
    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

typedef long long ll;

const int MAX_N = 10000;

int n; 
ll m;
vector<int> graph[MAX_N];
ll dp[MAX_N][MAX_N];
ll ans[MAX_N];
int pi[MAX_N];

ll dfs(int v, int p=-1) {
    ll ret = 1LL;
    for(int i=0;i<graph[v].size();++i) {
        int u = graph[v][i];
        if(u == p) {
            pi[v] = i;
            continue;
        }
        dp[v][i] = dfs(u, v);
        ret *= dp[v][i] + 1LL;
        ret %= m;
    }
    return ret;
}

void bfs(int v, ll res_p=0, int p=-1) {
    if(p != -1) {
        dp[v][pi[v]] = res_p;
    }
    vector<ll> dpl(graph[v].size()+1, 1LL);
    for(int i=0;i<graph[v].size();++i) {
        dpl[i+1] = dpl[i] * (dp[v][i]+1LL) % m;
    }
    vector<ll> dpr(graph[v].size()+1, 1LL);
    for(int i=graph[v].size()-1;i>=0;--i) {
        dpr[i] = dpr[i+1] * (dp[v][i]+1LL) % m;
    }
    ans[v] = dpr[0];
    for(int i=0;i<graph[v].size();++i) {
        int u = graph[v][i];
        if(u == p) continue;
        bfs(u, dpl[i]*dpr[i+1]%m, v);
    }
}

int main() {
    cin >> n >> m;
    int a, b;
    for(int i=0;i<n-1;++i) {
        cin >> a >> b;
        --a; --b;
        graph[a].push_back(b);
        graph[b].push_back(a);
    }

    dfs(0);
    bfs(0);

    for(int i=0;i<n;++i) {
        cout << ans[i] << endl;
    }
}

