const int NMAX = 100003;
int MOD;
vector<ll> pl[NMAX], pr[NMAX];

void dfsdown(int node, int dad, const vector<vector<int>> &g, vector<ll> &black_down) {
    black_down[node] = 1;
    for(auto it : g[node]) {
        if(it == dad)
            continue;
        dfsdown(it, node, g, black_down);

        black_down[node] = (black_down[node] * (black_down[it] + 1)) % MOD;
    }

    pl[node][0] = 1;
    for(int i = 0; i < g[node].size(); i ++) {
        if(g[node][i] == dad)
            pl[node][i + 1] = pl[node][i + 1 - 1];
        else
            pl[node][i + 1] = (pl[node][i + 1 - 1] * (black_down[g[node][i]] + 1)) % MOD;
    }

    pr[node][g[node].size() + 1] = 1;
    for(int i = g[node].size() - 1; i >= 0; i --) {
        if(g[node][i] == dad)
            pr[node][i + 1] = pr[node][i + 1 + 1];
        else
            pr[node][i + 1] = (pr[node][i + 1 + 1] * (black_down[g[node][i]] + 1)) % MOD;
    }
}

void dfsup(int node, int dad, const vector<vector<int>> &g, vector<ll> &black_up) {
    for(int i = 0; i < g[node].size(); i ++) {
        int it = g[node][i];
        if(it == dad)
            continue;

        black_up[it] =  (pl[node][i + 1 - 1] * pr[node][i + 1 + 1]) % MOD;
        black_up[it] = (black_up[it] * black_up[node] + 1) % MOD;

        dfsup(it, node, g, black_up);
    }
}

