#include<bits/stdc++.h>
using namespace std;
const int N = 1e5+5;
long long n;
long long mod;
long long dp[N];
vector< long long > g[N];
vector< long long > sm[N];
vector< long long > lz[N];
long long idx[N];
long long fr[N];
long long sz[N];
void upd(long long l,long long r,long long ll,long long rr,long long now,long long v,long long T)
{
    if(lz[T][now]!=1)
    {
        sm[T][now] = sm[T][now]*lz[T][now]%mod;
        if(l!=r)    lz[T][now<<1] = lz[T][now<<1]*lz[T][now]%mod,lz[T][now<<1|1] = lz[T][now<<1|1]*lz[T][now]%mod;
        lz[T][now] = 1;
    }
    if(l>r||l>rr||r<ll)  return ;
    if(l>=ll&&r<=rr)
    {
        sm[T][now] = sm[T][now]*v%mod;
        if(l!=r)   lz[T][now<<1] = lz[T][now<<1]*v%mod,lz[T][now<<1|1] = lz[T][now<<1|1]*v%mod;
        return ;
    }
    long long mid = (l+r) >> 1;
    upd(l,mid,ll,rr,now<<1,v,T); upd(mid+1,r,ll,rr,now<<1|1,v,T);
}
long long query(long long l,long long r,long long idx,long long now,long long T)
{
    if(lz[T][now]!=1)
    {
        sm[T][now] = sm[T][now]*lz[T][now]%mod;
        if(l!=r)    lz[T][now<<1] = lz[T][now<<1]*lz[T][now]%mod,lz[T][now<<1|1] = lz[T][now<<1|1]*lz[T][now]%mod;
        lz[T][now] = 1;
    }
    if(l>r||l>idx||r<idx)  return 1;
    if(l==r)    return sm[T][now];
    long long mid = (l+r) >> 1;
    return query(l,mid,idx,now<<1,T)*query(mid+1,r,idx,now<<1|1,T)%mod;
}
void solve(long long u,long long par = -1)
{
    long long cnt = 0;
    dp[u] = 1;
    long long all = g[u].size();
    for(long long i=1;i<=all*4+1;i++) sm[u].push_back(1),lz[u].push_back(1);
    for(auto &x:g[u])
    {
        if(x==par)  continue;
        idx[x] = ++cnt;
    }
    for(auto &x:g[u])
    {
        if(x==par)    continue;
        solve(x,u);
        fr[x] = cnt;
        dp[u] = dp[u]*(dp[x]+1)%mod;
        upd(1,cnt,1,idx[x]-1,1,dp[x]+1,u); upd(1,cnt,idx[x]+1,cnt,1,dp[x]+1,u);
    }
    sz[u] = cnt;
}
void reroot(long long u,long long par = -1)
{
    if(par!=-1)
    {
        long long now = (query(1,fr[u],idx[u],1,par)+1)%mod;
        dp[u] = dp[u]*now%mod,upd(1,sz[u],1,sz[u],1,now,u);
    }
    for(auto &x:g[u])
    {
        if(x==par)    continue;
        reroot(x,u);
    }
}
int main()
{
    scanf("%lld %lld",&n,&mod);
    for(long long i=1,u,v;i<n;i++)    scanf("%lld %lld",&u,&v),g[u].push_back(v),g[v].push_back(u);
    solve(1);
    reroot(1);
    for(long long i=1;i<=n;i++)   printf("%lld\n",dp[i]);
    return 0;
}

