// Mod int
// cf. https://www.youtube.com/watch?v=1Z6ofKN03_Y
struct mint {
  ll x;
  mint(ll x = 0) : x((x + MOD) % MOD) {}
  mint& operator+= (const mint a) {
    if ((x += a.x) >= MOD) x %= MOD;
    return *this;
  }
  mint operator+ (const mint a) const {
    mint res(*this);
    return res += a;
  }
  mint& operator-= (const mint a) {
    if ((x += MOD - a.x) >= MOD) x %= MOD;
    return *this;
  }
  mint operator- (const mint a) const {
    mint res(*this);
    return res -= a;
  }
  mint& operator*= (const mint a) {
    (x *= a.x) %= MOD;
    return *this;
  }
  mint operator* (const mint a) const {
    mint res(*this);
    return res *= a;
  }
  mint pow(ll t) const {
    if (!t) { return 1; }
    mint a = pow(t >> 1);
    a *= a;
    if (t & 1) a *= *this;
    return a;
  }

  // for prime mod
  mint inv() const {
    return pow(MOD-2);
  }
  mint& operator/= (const mint a) {
    return (*this) *= a.inv();
  }
  mint operator/ (const mint a) const {
    mint res(*this);
    return res /= a;
  }
};
istream& operator>>(istream& is, const mint& a) { return is >> a.x;}
ostream& operator<<(ostream& os, const mint& a) { return os << a.x;}

vector<vector<ll>> g;
vector<mint> dp;
vector<mint> ans;

void dfs(ll v, ll p=-1) {
  mint res(1);
  for (ll u : g[v]) {
    if (u == p) { continue; }
    dfs(u, v);
    res *= dp[u]+1;
  }
  dp[v] = res;
}

void bfs(ll v, ll p=-1) {
  ans[v] = 1;
  for (ll u : g[v]) {
    ans[v] *= dp[u]+1;
  }

  ll m = g[v].size();
  vector<mint> lft(m); // lft[i] .. [0,i]
  vector<mint> rht(m); // rht[i] .. [i,m]
  rep(i,m) {
    ll u = g[v][i];
    lft[i] = rht[i] = dp[u] + 1;
  }
  rep(i,m-1) {
    lft[i+1] *= lft[i];
  }
  for (ll i = m-2; i >= 0; --i) {
    rht[i] *= rht[i+1];
  }

  rep(i,m) {
    ll u = g[v][i];
    if (u == p) { continue; }
    mint now(1);
    if (i) { now *= lft[i-1]; }
    if (i<m-1) { now *= rht[i+1]; }
    dp[v] = now;
    bfs(u, v);
  }
}

