        v[a].push_back(b);
        v[b].push_back(a);
    }

    dfs(1);
    pre[1] = 1;
    suf[1] = 1;
    dfs2();
    for (int i = 1; i <= n; i++)
    {
        cout << add(ans[i], m) << '\n';
    }
    return 0;
}

