#include <bits/stdc++.h>

using namespace std;

#define white first
#define black second

typedef long long ll;
typedef long double ld;
typedef pair<int, int> pi;
typedef pair<long long, long long> pl;

const int MOD = 1e9 + 7;
const ll INF = 1e18;
const double EPS = 1e-6;
const int MAX_N = 1e5 + 5;

int N, M;
vector<int> adjList[MAX_N], children[MAX_N];
pi down[MAX_N], up[MAX_N];
vector<pi> downs[MAX_N], pre[MAX_N], su[MAX_N];

namespace modOp {
    int add(int a, int b, int mod = M) {return (a + b) % mod; /*int r = a + b; if (r >= mod) r -= mod; return r;*/}
    void ADD(int& a, int b, int mod = M) {a = (a + b) % mod; /*a += b; if (a >= mod) a -= mod;*/}
    int sub(int a, int b, int mod = M) {return (a - b + mod) % mod; /*int r = a - b; if (r < 0) r += mod; return r;*/}
    void SUB(int& a, int b, int mod = M) {a = (a - b + mod) % mod; /*a -= b; if (a < 0) a += mod;*/}
    int mul(int a, int b, int mod = M) {return (ll)a * b % mod;}
    void MUL(int& a, int b, int mod = M) {a = (ll)a * b % mod;}
}
using namespace modOp;

pi merge(pi& a, pi& b) {
	pi res;
	res.white = mul(a.white, b.white);
	res.black = add(mul(a.black, add(b.white, b.black)), mul(a.white, b.black));
	return res;
}

pi process(pi p) {
	return {p.white, add(p.black, p.white)};
}

void dfs1(int u, int p) {
	pi res = {1, 0};
	for (int v: adjList[u]) {
		if (v != p) {
			children[u].push_back(v);
			dfs1(v, u);
			res = merge(res, down[u]);
			downs[u].push_back(down[v]);
		}
	}
	int w = res.white;
	int b = add(res.black, res.white);
	down[u] = {w, b};
}

void dfs2(int u, int p) {
	for (int i = 0; i < children[u].size(); ++i) {
		pi res = {1, 0};
		if (i != 0) {
			res = merge(res, pre[u][i - 1]);
		}
		if (i != downs[u].size() - 1) {
			res = merge(res, su[u][i + 1]);
		}
		if (u != 1)  {
			res = merge(res, up[u]);
		}
		int v = children[u][i];
		up[v] = {res.white, add(res.black, res.white)};
		dfs2(v, u);
	}
}

int main() {
	ios_base::sync_with_stdio(0); cin.tie(0);

	cin >> N >> M;
