        suff[i] = all[u][i];
        mul(suff[i], suff[i+1]);
    }
    int pref = top, i = 0;
    for (int v : adj[u])
        if (v != p) {
            top = pref;
            mul(top, suff[i+1]);
            dfs2(v, u, add(top, 1));
            mul(pref, all[u][i++]);
