		dp1[u]*=dp1[v]+1;
	}
}

void dfs2(int u,int p){
	vector<mint> C;
	for(int v:T[u]) if(v!=p) C.emplace_back(dp1[v]+1);

	int k=C.size();
	vector<mint> rprod(k+1);
	rprod[k]=1;
	for(int i=k-1;i>=0;i--) rprod[i]=rprod[i+1]*C[i];

	mint lprod=1;
	int idx=0;
	for(int v:T[u]) if(v!=p) {
		dp2[v]=dp2[u]*lprod*rprod[idx+1]+1;
		dfs2(v,u);
		lprod*=C[idx];
		idx++;
	}
}

