unordered_map<llint, llint> memo;

llint dfs(int v, int pre)
{
	if(memo.count(v*H+pre)) return memo[v*H+pre];

	llint ret = 1;
	for(int i = 0; i < G[v].size(); i++){
		if(G[v][i] == pre) continue;
		ret *= dfs(G[v][i], v)+1, ret %= mod;
	}
	return memo[v*H+pre] = ret;
}

