int calc (int v) {
   if (dp2[v] != -1) return dp2[v];
   dp2[v] = 1;
   if (v == 1) return dp2[v];
   for (auto to : g[p[v]]) {
      if (to == v || to == p[p[v]]) continue;
      dp2[v] = mult (dp2[v], dp1[to] + 1);
   }
   dp2[v] = mult (dp2[v], calc (p[v]));
   dp2[v] = add (dp2[v], 1);
   return dp2[v];
}

