using namespace std;

const int mN = 100100;
int n, mod;
vector<int> graph[mN];

typedef long long LL;
LL cnt[mN], coef[mN];

int parent[mN];
void dfs(int u) {
    cnt[u] = coef[u] = 1;
    for (int v : graph[u]) if (parent[u] != v) {
        parent[v] = u;
        dfs(v);
        cnt[u] *= cnt[v] + 1;
        cnt[u] %= mod;
    }
}

void reconsider(int u) {
    int id = 0;
    int num = graph[u].size() + 2;
    LL prefix[num], suffix[num];
    fill(prefix, prefix+num, 1);
    fill(suffix, suffix+num, 1);
    prefix[0] = 1;
    for (int j=0; j<graph[u].size(); j++) {
        int v = graph[u][j];
        if (parent[u] == v) continue;
        prefix[++id] = (prefix[id-1] * (cnt[v]+1)) % mod;
    }
//    cerr << "total = " << id << ".";
    suffix[id+1] = 1;
    for (int j=graph[u].size()-1; j>=0; j--) {
        int v = graph[u][j];
        if (parent[u] == v) continue;
        suffix[id] = (suffix[id+1] * (cnt[v]+1)) % mod;
        --id;
    }
//    cerr << "prepare for node " << u << " completed: ";
//    for (int i=0; i<=graph[u].size()+1; i++) cerr << "(" << prefix[i] << "," << suffix[i] << ") ";
//    cerr << "\n";
    for (int j=0; j<graph[u].size(); j++) {
        int v = graph[u][j];
        if (parent[u] == v) continue;
        LL u_as_child = (prefix[id++] * suffix[id+1]) % mod;
        u_as_child *= coef[u], u_as_child %= mod;
        coef[v] = u_as_child + 1;
        cnt[v] *= coef[v];
        cnt[v] %= mod;
        //cnt[v] = cnt[v];
        parent[v] = u;
        reconsider(v);
    }
    //cerr << u << " : " << cnt[u] << " (*=" << coef[u] << " ed)\n";
}

