int num_nodes,M;
ll dp[MAXN],ans[MAXN],pref[MAXN],suff[MAXN];
vector<int> connections[MAXN];
vector<ll> v[MAXN];

ll dfs(int node, int prev){
	dp[node] = 1;
	for(int check:connections[node]){
		if(check == prev) continue;
		dp[node] = (dp[node]*(dfs(check,node)+1))%M;
	}
	return dp[node];
}

ll solve(int node, int prev){
	ans[node] = dp[node];
//	pref[node].resize(connections[node].size()+2);
//	suff[node].resize(connections[node].size()+2);
	pref[0] = suff[connections[node].size()+1] = 1;

	for(int i=1; i<=connections[node].size(); i++){
		int check = connections[node][i-1];
//		if(check == prev) continue;
		pref[i] = (pref[i-1]*(dp[check]+1))%M;
	}
	for(int i=(int)connections[node].size(); i>=1; i--){
		int check = connections[node][i-1];
//		if(check == prev) continue;
		suff[i] = (suff[i+1]*(dp[check]+1))%M;
	}
	v[node].resize(connections[node].size()+2);
	for(int i=1; i<=connections[node].size(); i++)
		v[node][i] = (pref[i-1]*suff[i+1])%M;
	ll ov1 = dp[node];
	for(int i=1; i<=connections[node].size(); i++){
		int check = connections[node][i-1];
		if(check == prev) continue;
		ll o_v = dp[check];

		ll n_v = v[node][i];
		dp[node] = n_v;

		n_v = ((n_v+1)*dp[check])%M;
		dp[check] = n_v;

		solve(check,node);
		dp[check] = o_v;
		dp[node] = ov1;
	}
}

int main(){
	scanf("%d %d",&num_nodes,&M);
	for(int i=1; i<num_nodes; i++){
		int a,b; scanf(" %d %d",&a,&b);
		connections[a].pb(b);
		connections[b].pb(a);
	}
	dfs(1,-1);
	solve(1,-1);
	for(int i=1; i<=num_nodes; i++)
		printf("%lld\n",ans[i]);
}

