const int maxn = 1e5+10;

long long int n, m;
vector<int> g[maxn];
long long int dp[maxn];
bool marked[maxn];
int p[maxn];
vector<long long int> psum[maxn];
vector<long long int> ssum[maxn];

void dfs1(int v){
	marked[v] = true;
	dp[v] = 1;
	for (int i = 0; i < g[v].size(); i++){
		int u = g[v].at(i);
		if (!marked[u]){
			p[u] = v;
			dfs1(u);
			dp[v] = dp[v] * (dp[u]+1) % m;
			psum[v].push_back(dp[v]);
			marked[u] = false;
		}
	}
	dp[v] = 1;
	for (int i = g[v].size()-1; i >= 0; i--){
		int u = g[v].at(i);
		if (!marked[u]){
			dp[v] = dp[v] * (dp[u]+1) % m;
			ssum[v].push_back(dp[v]);
			marked[u] = true;
		}
	}
}

void dfs2(int v, long long int x){
	marked[v] = true;
	dp[v] = dp[v] * (x + 1) % m;
	for (int i = 0; i < g[v].size(); i++){
		int u = g[v].at(i);
		if (!marked[u]){
			if (g[v].size() == 2){
				dfs2(u, (x+1)%m);
			}
			else if (i == 0){
				dfs2(u, ssum[v][g[v].size()-2] * (x+1) % m);
			}
			else if (i == g[0].size()-1){
				dfs2(u, psum[v][g[v].size()-2] * (x+1) % m);
			}
			else {
				dfs2(u, psum[0][i-1] * ssum[0][g[0].size()-i-2] % m * (x+1) % m);
			}
		}
	}
}
