}
void solve2(ll node,ll par_val,ll par){
    ll sz = adjlist[node].size();
    ll w=1;
    w = (dp1nonroot[node]*((1+par_val)%m))%m;
    dp2asroot[node] = w;
    vector<ll>chld;
    for(ll i=0;i<sz;i++){
        if(adjlist[node][i]==par){
            continue;
        }
        chld.push_back(adjlist[node][i]);
    }
    sz = chld.size();
    vector<ll>prefix(sz,1),suffix(sz,1);
    for(ll i=1;i<sz;i++){
        prefix[i] = (prefix[i-1]*((dp1nonroot[chld[i-1]]+1)%m))%m;
    }
    for(ll i=sz-2;i>=0;i--){
        suffix[i] = (suffix[i+1]*((dp1nonroot[chld[i+1]]+1)%m))%m;
    }

    for(ll i=0;i<sz;i++){
        ll u = chld[i];
        ll pv = (((prefix[i]*suffix[i])%m)*((par_val +1)%m))%m;
        solve2(u,pv,node);
    }
    return;
}

