/// dp[i] là số cách để tổ cho cây con gốc i thỏa mãn đề và đỉnh i màu đen.

void DFS1(int i , int j)
{
    dp[i] = 1;
    REP(s , g[i].size())
    {
        int u = g[i][s];
        if(u != j)
        {
            DFS1(u , i);
            dp[i] = (dp[i] * (dp[u] + 1)) % mod;
        }
    }
