int getpre(int u , int v , int s)
{
    if(s >= 1 && g[u].size() >= 1 && g[u][s - 1] != v)
        return g[u][s - 1];
    if(s >= 2 && g[u].size() >= 2 && g[u][s - 2] != v)
        return g[u][s - 2];
    return 0;
}

int getsuf(int u , int v , int s)
{
    int x = g[u].size();
    x -= 2;
    if(s <= x && g[u].size() >= 1 && g[u][s + 1] != v)
        return g[u][s + 1];
    if(s <= x - 1 && g[u].size() >= 2 && g[u][s + 2] != v)
        return g[u][s + 2];
    return 0;
}

void DFS2(int i , int j , int val)
{
    ans[i] = (dp[i] * val) % mod;
    REP(s , g[i].size())
    {
        int u = g[i][s];
        if(u != j)
        {
            int v = getpre(i , j , s);
            prefix[u] = (prefix[v] * (dp[u] + 1)) % mod;
        }
    }
    int x = g[i].size();
    FORD(s , x - 1 , 0)
    {
        int u = g[i][s];
        if(u != j)
        {
            int v = getsuf(i , j , s);
            suffix[u] = (suffix[v] * (dp[u] + 1)) % mod;
        }
    }
    REP(s , g[i].size())
    {
        int u = g[i][s];
        if(u != j)
        {
            int x = getpre(i , j , s) , y = getsuf(i , j , s);
            DFS2(u , i , (((prefix[x] * suffix[y]) % mod) * val + 1) % mod);
        }
    }
}

