ll dp_down[N], dp_up[N];

void dfs0(int v, int par) {
    dp_down[v] = 1;
    for (int to : g[v]) if (to != par) {
        dfs0(to, v);
        dp_down[v] = (dp_down[v] * (1LL + dp_down[to])) % M;
    }
}


void dfs1(int v, int par) {
    vl pref(g[v].size());
    vl suf(g[v].size());
    vl vals(g[v].size());
    fori (i, g[v].size()) {
        int to = g[v][i];
        if (to == par) {
            vals[i] = 1;
            continue;
        }
        vals[i] = (dp_down[to] + 1LL) % M;
    }
    pref[0] = vals[0];
    for (int i = 1; i < vals.size(); ++i) {
        pref[i] = (pref[i - 1] * vals[i]) % M;
    }
    suf.back() = vals.back();
    for (int i = SZ(vals) - 2; i >= 0; --i) {
        suf[i] = (suf[i + 1] * vals[i]) % M;
    }
    for (int i = 0; i < g[v].size(); ++i) {
        int to = g[v][i];
        if (to == par) continue;
        dp_up[to] = dp_up[v];
        if (i) dp_up[to] = dp_up[to] * pref[i - 1] % M;
        if (i != SZ(g[v]) - 1) dp_up[to] = dp_up[to] * suf[i + 1] % M;
        dp_up[to] = (dp_up[to] + 1) % M;
        dfs1(to, v);
    }
}

