{
    int res = 1;
    ft[u].erase(v);
    for(auto it = ft[u].begin(); it != ft[u].end(); it++){
        int x = *it;
        res *= dp[x];
        modo(res);
    }
    res++; modo(res);
    dp[u] = res;
    dp[v]--; modo(dp[v]);
    dp[v] *= res;
    ft[v].insert(u);
    dp[v]++;
    modo(dp[v]);
