  for(long long to : edge[now])
    if(!reachd[to]) (res *= dfs(to) + 1) %= m;
  return dp[now] = res;
}

void dfs2(long long now) {
  reachd[now] = 1;
  long long res = 1, esize = edge[now].size(), bf = dp[now];
  for(long long to : edge[now]) (res *= dp[to] + 1) %= m;
  ans[now] = res;
  vector<long long> pre, suf;
  pre.assign(esize, 0);
  suf.assign(esize, 0);
  for(int i = 0; i < esize; ++i) {
    long long to = edge[now][i];
    if(i != 0) {
      pre[i] = pre[i - 1];
      suf[esize - 1 - i] = suf[esize - i];
    }
    else
      pre[i] = suf[esize - 1] = 1;
    (pre[i] *= dp[to] + 1) %= m;
    (suf[esize - 1 - i] *=
     dp[edge[now][esize - 1 - i]] + 1) %= m;
  }
  for(int i = 0; i < esize; ++i) {
    long long to = edge[now][i];
    if(!reachd[to]) {
      dp[now] = 1;
      if(i != 0) (dp[now] *= pre[i - 1]) %= m;
      if(i != esize - 1) (dp[now] *= suf[i + 1]) %= m;
      dfs2(to);
    }
  }
  dp[now] = bf;
}

