vi suff[MAXN][2];
vvi adj(MAXN);
int N,MOD;

int dfs(int u, int p, int col) {
    int ppos = lower_bound(ALL(adj[u]), p) - adj[u].begin();

    if(dp[u][col][ppos] >= 0)
        return dp[u][col][ppos];

    if(pref[u][col][ppos] < 0) {
        int idx = ppos;
        while(pref[u][col][idx-1] < 0)
            idx--;
        RNG(i,idx,ppos) {
            ll rez = dfs(adj[u][i-1], u, col);
            rez *= pref[u][col][i-1];
            pref[u][col][i] = rez%MOD;
        }
    }
    if(suff[u][col][ppos+1] < 0) {
        int idx = ppos+1;
        while(suff[u][col][idx+1] < 0)
            idx++;
        REV(i,idx,ppos+1) {
            ll rez = dfs(adj[u][i], u, col);
            rez *= suff[u][col][i+1];
            suff[u][col][i] = rez%MOD;
        }
    }

    ll res = 1LL * suff[u][col][ppos+1] * pref[u][col][ppos];
    if(col==0)
        res += dfs(u, p, 1);

    return dp[u][col][ppos]=res%MOD;
}

