 * base: if parent is 1 --> array[parent][cur_node] = down[children]/down[cur_node]
 * for other cases array[parent][cur_node] = down[children]/down[cur_node] * array[grand_parent][parent]
 */

const int nax = 1e5+5;
ll down[nax], up[nax];
