unordered_map<int, vint> dict;
vint parent, dp_up, dp_down;
vector<bool> visit;
int m;

void dfs(int node, int p){
	parent[node] = p;
	for(int i:dict[node]){
		if(i==p)
			continue;
		dfs(i, node);
	}
}

pint calculate_up(int node, int prev){
	if(dp_up[node]!=0)
		return make_pair(dp_up[node], 1);

	if(node==0)
		return make_pair(0, 1);

	int ans=1;
	for(int i:dict[node]){
		if(i==prev)
			continue;
		pint p = calculate_up(i, node);
		ans*=(p.first+p.second);
		ans%=m;
	}
	dp_up[node] = ans;
	return make_pair(ans, 1);
}

pint calculate_down(int node){
	if(dp_down[node]!=0)
		return make_pair(dp_down[node], 1);

	int ans=1;
	for(int i:dict[node]){
		if(i==parent[node])
			continue;
		pint p = calculate_down(i);
		ans*=(p.first+p.second);
		ans%=m;
	}
	dp_down[node] = ans;
	return make_pair(ans, 1);
}

