vector<vector<int>> es;
vector<int> par;
vector<ll> dp0, dp1;

void erase(vector<int>& v, int x) { v.erase(remove(v.begin(), v.end(), x), v.end()); }

void dfs1(int u, int p)
{
	par[u] = p;
	erase(es[u], p);
	for (int v : es[u]) dfs1(v, u);
}

// par[0]=-1 は常に白とする
// dp0[u]=(uを黒, par[u]を白に塗る場合の数)
ll dfs2(int u)
{
	dp0[u] = 1L;
	for (int v : es[u]) dp0[u] = dp0[u] * (dfs2(v) + 1) % Mod;
	return dp0[u];
}

// dp1[u]=(uを白, par[u]を黒に塗る場合の数)
void dfs3(int u)
{
	int W = es[u].size();
	vector<ll> x(W + 1, 1);
	vector<ll> y(W + 1, 1);
	for (int i = 0; i < W; i++) x[i + 1] = x[i] * (dp0[es[u][i]] + 1) % Mod; // 前からの累積積, x[i] = t[0]*...*t[i-1]
	for (int i = W - 1; i >= 0; i--) y[i] = y[i + 1] * (dp0[es[u][i]] + 1) % Mod; // 後ろからの累積積, y[i] = t[i]*...*t[W-1]
	for (int i = 0; i < W; i++) dp1[es[u][i]] = (dp1[u] + 1) * x[i] % Mod * y[i + 1] % Mod;
	for (int v : es[u]) dfs3(v);
}

int main()
{
	cin.tie(0);
	ios::sync_with_stdio(false);
	cin >> V >> Mod;
	for (int i = 0; i < V; i++) { es.emplace_back(vector<int>()); par.emplace_back(0); dp0.emplace_back(0); dp1.emplace_back(0); }
	for (int i = 0; i < V - 1; i++)
	{
		int x, y; cin >> x >> y;
		es[x - 1].push_back(y - 1);
		es[y - 1].push_back(x - 1);
	}
	dfs1(0, -1);
	dfs2(0);
	dfs3(0);
	for (int u = 0; u < V; u++) cout << dp0[u] * (dp1[u] + 1) % Mod << endl;
    return 0;
}

