template <typename T>
struct ReRooting
{
  using F = function<T(T)>;
  using M = function<T(T, T)>;
  static const int MAX_V = 200010;
  int V;
  vector<int> E[MAX_V];
  vector<T> dp[MAX_V];
  //遷移：dp[vの子]にfを作用させてmergeでまとめる
  F f;
  M merge;
  T mi; //mergeの単位元
  int root;

  ReRooting(int V_, F f_, M merge_, T mi_) : V(V_), f(f_), merge(merge_), mi(mi_) {}

  void add_E(int a, int b)
  {
    E[a].push_back(b);
    E[b].push_back(a);
  }

  //上から下
  ll dfs1(int p, int v)
  {
    ll res = mi;
    rep(i, E[v].size())
    {
      if (E[v][i] == p)
        continue;
      dp[v][i] = dfs1(v, E[v][i]);
      res = merge(res, f(dp[v][i]));
    }

    return res;
  }

  //下から上
  void dfs2(int p, int v, T add)
  {
    //上から持ってきた値を清算
    rep(i, E[v].size())
    {
      if (E[v][i] == p)
      {
        dp[v][i] = add;
        break;
      }
    }

    //左右からの累積を作っておく
    vector<T> pL(E[v].size() + 1), pR(E[v].size() + 1);
    pL[0] = mi;
    rep(i, E[v].size()) pL[i + 1] = merge(pL[i], f(dp[v][i]));
    pR[E[v].size()] = 1;
    for (int i = E[v].size(); i > 0; --i)
      pR[i - 1] = merge(pR[i], f(dp[v][i - 1]));

    rep(i, E[v].size())
    {
      if (E[v][i] == p)
        continue;
      T val = merge(pL[i], pR[i + 1]);
      dfs2(v, E[v][i], val);
    }
  }

  void calc(int root = 0)
  {
    rep(i, V) dp[i].resize(E[i].size());
    dfs1(-1, root);
    dfs2(-1, root, 0);
  }

  T solve(int v)
  {
    T ans = mi;
    rep(i, E[v].size())
    {
      ans = merge(ans, f(dp[v][i]));
    }
    return ans;
  }
};

int main()
{
  cin.tie(0);
  ios::sync_with_stdio(false);
  cout << setprecision(30) << setiosflags(ios::fixed);

  ll n, m;
  cin >> n >> m;
  auto f = [](ll a) { return a + 1; };
  auto g = [&](ll a, ll b) { return a * b % m; };
  ReRooting<ll> re(n, f, g, 1);
  rep(i, n - 1)
  {
    int a, b;
    cin >> a >> b;
    a--, b--;
    re.add_E(a, b);
  }
  re.calc();
  rep(v, n) cout << re.solve(v) << endl;
  return 0;
}

