		ts1[i] = ts1[i - 1] * (1 + d[G[r][i]]);
		ts2[num - i - 1] = ts2[num - i] * (1 + d[G[r][num - i - 1]]);
	}
	for(int i = 0; i < num; ++i){
		s1[r].push_back(ts1[i]);
		s2[r].push_back(ts2[i]);
	}
	d[p] = t;
