		if(x < (int)G[p].size() - 1) a[r] = a[r] * s2[p][x + 1] % m;
		++a[r];
	}

	for(int i = 0; i < (int)G[r].size(); ++i){
		if(G[r][i] != p)
			dfs(G[r][i], r, i);
	}
}

