int to[200005],nxt[200005],head[200005],cnt;
int fa[200005];
long long dpi[200005],dp[200005];
inline void add(int x,int y){
	to[++cnt]=y;
	nxt[cnt]=head[x];
	head[x]=cnt; 
}
inline void DFSI(int x,int par){
	fa[x]=par;
	dpi[x]=1;
	for(int i=head[x];i;i=nxt[i]){
		int y=to[i];
		if(y==par){
			continue;
		}
		DFSI(y,x);
		dpi[x]=(dpi[x]*(dpi[y]+1))%m;
	}
}
inline void DFS(int x,int out){
	dp[x]=(dpi[x]*out)%m;
	vector<int> c;
	for(int i=head[x];i;i=nxt[i]){
		if(to[i]==fa[x]){
			continue;
		}
		c.push_back(to[i]);
	}
	vector<long long> pref(c.size()+1),suf(c.size()+1);
	pref[0]=1,suf[c.size()]=1;
	for(int i=0;i<c.size();++i){
		pref[i+1]=pref[i]*(dp[c[i]]+1);
	}
	for(int i=c.size()-1;i>=0;--i){
		suf[i]=suf[i+1]*(dp[c[i]]+1);
	}
	for(int i=0;i<c.size();++i){
		DFS(c[i],out*pref[i]*suf[i+1]+1);
	} 
}
