void dfs1(int now=1, int p=-1){
  dp1[now]=1;
  for(auto to: edges[now]){
    if(p==to)continue;
    dfs1(to, now);
    dp1[now] = dp1[now]*dp1[to]%m;
  }
  dp1[now]++;
}

void dfs2(int now=1, int p=-1){
  if(p==-1)dp2[now]=1;
  int ec = edges[now].size();

  vector<ll>rprod(ec);
  rep(i, ec){
    int to = edges[now][i];
    rprod[i]=1;
    if(i)rprod[i] = rprod[i-1];
    if(to==p)continue;
    rprod[i] = rprod[i]*dp1[to]%m;
  }

  vector<ll>lprod(ec);
  rrep(i, ec){
    int to = edges[now][i];
    lprod[i]=1;
    if(i<ec-1)lprod[i] = lprod[i+1];
    if(to==p)continue;
    lprod[i] = lprod[i]*dp1[to]%m;
  }

  rep(i, ec){
    int to = edges[now][i];
    if(to==p)continue;
    dp2[to] = dp2[now];
    if(i)dp2[to] = dp2[to] * rprod[i-1] % m;
    if(i<ec-1)dp2[to] = dp2[to] * lprod[i+1] % m;
    dp2[to] = (dp2[to] + 1)%m;
    dfs2(to, now);
  }
}

void dfs3(int now=1, int p=-1){
  ans[now] = dp2[now];
  for(int to:edges[now]){
    if(to==p)continue;
    ans[now] = ans[now]*dp1[to]%m;
    dfs3(to, now);
  }
}

