const int N = 1e5 + 5;
int n, mod;
int dp[N], sol[N];
vector<int> g[N], pre[N], suf[N];

void dfs(int node, int parent)
{
	pre[node].resize(g[node].size());
	suf[node].resize(g[node].size());
	int cur = 1;
	for(int i = 0; i < g[node].size(); i++)
	{
		int child = g[node][i];
		if(child != parent){
			dfs(child, node);
			cur = (1ll * cur * dp[child]) % mod;
		}
		pre[node][i] = cur;
	}
	cur = 1;
	for(int i = (int)g[node].size() - 1; i >= 0; i--)
	{
		int child = g[node][i];
		if(child != parent){
			dfs(child, node);
			cur = (1ll * cur * dp[child]) % mod;
		}
		suf[node][i] = cur;
	}
	dp[node] = cur + 1;
	if(dp[node] >= mod)
		dp[node] -= mod;
}

void dfs2(int node, int parent, int val_parent)
{
	dp[node]--;
	if(dp[node] < 0)
		dp[node] += mod;
	dp[node] = (1ll * dp[node] * val_parent) % mod;
	dp[node]++;
	if(dp[node] >= mod)
		dp[node] -= mod;
	sol[node] = dp[node];
	for(int i = 0; i < g[node].size(); i++)
	{
		int child = g[node][i];
		if(child != parent){
			int p = 1, s = 1;
			if(i)
				p = pre[node][i - 1];
			if(i + 1 < g[node].size())
				s = suf[node][i + 1];
			int v = (1ll * p * s) % mod;
			v = (1ll * v * val_parent) % mod;
			v++;
			if(v >= mod)
				v -= mod;
			dfs2(child, node, v);
		}
	}
}

