void update(int id, int node, int l, int r, int pos, int val){
    if(l == r){ st[id][node] = val%m; return; }
    if(pos <= med) update(id,v1,l,med,pos,val);
    else update(id,v2,med+1,r,pos,val);
    st[id][node] = st[id][v1]*st[id][v2]%m;
}
void upd(int u, int v, int val){
    update(u,1,0,adj[u].size()-1,mapa[u][v],val);
}
