    dp[u] = 1;
    for(int v : adj[u]){
        if(v == p) continue;
        dfs(v,u);
        dp[u] = dp[u]*(1+dp[v])%m;
        upd(u,v,1+dp[v]);
    }
}
void go(int u, int p){
    res[u] = dp[u];
    for(int v : adj[u]){
        if(v == p) continue;
        upd(u,v,1);
        int ant = dp[v], cur = st[u][1]+1;
        dp[v] = dp[v]*cur%m;
        upd(v,u,cur);
        go(v,u);
        upd(v,u,1);
        dp[v] = ant;
        upd(u,v,ant+1);
    }
}
