            v[x].pb(u);
            dfs(u, x);
        }
    }
}
void dfs1(int x = 0) {
    d[x] = 1;
    for (auto u : v[x]) {            
        dfs1(u);
        d[x] = mult(d[x], (1 + d[u]));
    }
}
void dfs2(int x = 0) {
    vi p(v[x].size()), s(v[x].size());
    for (int i = 0; i < v[x].size(); i++) {
        p[i] = s[i] = sum(1, d[v[x][i]]);
        if(i)
            p[i] = mult(p[i], p[i - 1]);
    }
    for (int i = v[x].size() - 1; i >= 0; i--) {
        if(i != v[x].size() - 1)
            s[i] = mult(s[i], s[i + 1]);
    }
    for (int i = 0; i < v[x].size(); i++) {
        int res = 1;
        if(i)
            res = mult(res, p[i - 1]);
        if(i != v[x].size() - 1)
            res = mult(res, s[i + 1]);
        up[v[x][i]] = sum(1, mult(up[x], res));
    }
    for (auto u : v[x])
        dfs2(u);
    ans[x] = mult(d[x], up[x]);
}
