struct edge{
	int next, to;
	edge(int N=0,int T=0):next(N),to(T){}
}e[MAXN<<1];
int fir[MAXN], num = 0;
inline void join(int a, int b)
{
	e[++num].next = fir[a];
	fir[a] = num;
	e[num].to = b;
}

int f[MAXN], g[MAXN], ans[MAXN];
vector<int> in[MAXN], pre[MAXN], suf[MAXN];

void dfs1(int u, int fa)
{
	int cnt = 0;
	f[u]    = 1;
	in[u].push_back(1);
	for(int i=fir[u]; i; i=e[i].next)
	{
		int v = e[i].to;
		if(v == fa) continue;
		dfs1(v, u);
		f[u] = mul(f[u], add(f[v], 1));
		cnt++;
		in[u].push_back(v);
	}
	in[u].push_back(1);
	pre[u].resize(cnt + 2); suf[u].resize(cnt + 2);
	pre[u][0] = suf[u][cnt+1] = 1;
	for(int i=1; i<=cnt; i++)
		pre[u][i] = mul(pre[u][i-1], add(f[in[u][i]], 1));
	for(int i=cnt; i>=1; i--)
		suf[u][i] = mul(suf[u][i+1], add(f[in[u][i]], 1));
}
void dfs2(int u, int fa)
{
	int cnt = 0;
	for(int i=fir[u]; i; i=e[i].next)
	{
		int v = e[i].to;
		if(v == fa)continue;
		++cnt;
		g[v] = add(mul(g[u], mul(pre[u][cnt-1], suf[u][cnt+1])), 1);
		ans[v] = mul(g[v], f[v]);
		dfs2(v, u);
	}
}
