int gsuf(int u, int i){
	if(i+1 < suf[u].size())
		return suf[u][i+1]%m;
	return 1;
}

int dfs(int u, int p, int c){
	if(dp[u][c]  != -1) return dp[u][c]%m;
	dp[u][c] = 1;
	for(int v : adj[u]){
		if(v == p) continue;
		int res = 0;
		if(c == 0){//negro
			res = (dfs(v,u,0) + dfs(v,u,1))%m;
			dp[u][c] = (dp[u][c] * res) % m;
		}
		else{
			res = dfs(v,u,1)%m;
			dp[u][c] = (dp[u][c] * res)%m;
		}
		pref[u].pb(res);
		suf[u].pb(res);
	}
	//pref
	for(int i =1; i < pref[u].size(); i++) pref[u][i] = (pref[u][i] * pref[u][i-1])%m;
	for(int i = suf[u].size()-2; i >=0; i--) suf[u][i] = (suf[u][i] * suf[u][i+1])%m;
	return dp[u][c]%m;
}

