ll paint(ll v, ll u) {
    pair<int, int> key = {v, u};
    if (!dp.count(key)) {
        ll result = 1;
        for (int w : adj[v])
            if (w != u)
                result = result * (1 + paint(w, v)) % M;
        dp[key] = result;
    }
    return dp[key];
}

