const int inf = LLONG_MAX/2;
const int N = 1e5+1;
int n,m;
vector<vector<int>> adj(N);
vector<int> subtree(N);
vector<int> calc(N,1);

void dfs1(int node, int par){
	int sum = 1;
	for (int i:adj[node]){
		if (i != par){
			dfs1(i,node);
			sum *= (subtree[i]+1);
			sum %= m;
		}
	}
	subtree[node] = sum;
}

void dfs2(int node, int prev){
	int p1 = subtree[prev], p2 = subtree[node];
	subtree[prev] = 1;
	for (int i:adj[prev]){
		if (i != node) subtree[prev] *= (subtree[i]+1);
		subtree[prev] %= m;
	}
	subtree[node] = 1;
	for (int i:adj[node]){
		subtree[node] *= (subtree[i]+1);
		subtree[node] %= m;
	}
	calc[node] = subtree[node];
	for (int i:adj[node]){
		if (i != prev){
			dfs2(i,node);
		}
	}
	subtree[prev] = p1;
	subtree[node] = p2;
}

