ll multi(ll a, ll b){

	ll total = ( (a%m)*(b%m) )%m;
	return total;

}

ll calc(ll here, ll father){

	if(counter[father] >= 2 ){
		return 0;
	}

	if(counter[father] == 1){

		if(  (down[here]+1)%m == 0 ){
			return total[father];
		}
		else{
			return 0;
		}

	}


	return total[father]/ ( (down[here]+1 )%m );

}

void dfs(ll here, ll father){

	p[here] = father;

	ll f = tree[here].size();

	for(ll i = 0; i < f; i++){

		if( tree[here][i] != father ){
			dfs(tree[here][i], here);
			down[here] = multi( down[here], down[ tree[here][i]] + 1 );

			if( ((down[ tree[here][i]] + 1 )%m)  != 0 ){
				total[here]*= ((down[ tree[here][i]] + 1 )%m);
			} 
			else{
				counter[here]++;
			}

		}

	}

}


void dfs2(ll here, ll father){

	if(here != 1){
		up[here] = multi( up[father] , calc(here, father) );
		up[here] =  (up[here]+1)%m;
	}


	ll f = tree[here].size();

	for(ll i = 0; i < f ; i++){

		if( tree[here][i] != father ){
			dfs2(tree[here][i], here);
		}
	}


}

