void dfs1(LL u,LL f){
	dp[u] = 1 % N;
	for(LL i = hed[u];i;i = nxt[i]){
		LL v = to[i];
		if(v == f) continue;
		dfs1(v,u);
		dp[u] = dp[u] * (dp[v] + 1LL);
		dp[u] %= N;
	}
}

void dfs2(LL u,LL f){
	for(LL i = hed[u];i;i = nxt[i]){
		LL v = to[i];
		if(v == f) continue;
		dp[u] /= (dp[v] + 1);
		dp[v] *= (dp[u] + 1);
		ans[v] = dp[v];
		dfs2(v,u);
		dp[v] /= (dp[u] + 1);
		dp[u] *= (dp[v] + 1);
	}
}

