void dfs(ll u = 1,ll p = 0){
    dp[u] = 1;
    for (ll v :graph[u]){
        if (v == p) continue;
        dfs(v,u);
        dp[u] *= (dp[v]+1); 
        dp[u] %= mod;
    }
}

void dfs1(ll u,ll p,ll v){
    ans[u] = (dp[u]*(v+1))%m;
    pre[u].resize(graph[u].size()+1,1);
    suf[u].resize(graph[u].size()+1,1);
    for (int z=0;z<graph[u].size();z++){
        if (graph[u][z] == p){
            if (z != 0) pre[u][z] = pre[u][z-1];
        }
        else if (z == 0) pre[u][z] = dp[graph[u][z]]+1;
        else pre[u][z] = pre[u][z-1]*(dp[graph[u][z]]+1);
        pre[u][z] %= m;
    }
    for (int z=graph[u].size()-1;z>=0;z--){
        if (graph[u][z] == p){
            if (z != graph[u].size()-1) suf[u][z] = suf[u][z+1];
        }
        if (z == graph[u].size()-1) suf[u][z] = dp[graph[u][z]]+1;
        else suf[u][z] = suf[u][z+1]*(dp[graph[u][z]]+1);
        suf[u][z] %= m;
    }
    for (int z=0;z<graph[u].size();z++){
        if (graph[u][z] == p) continue;
        ll value = 1;
        if (z > 0) value *= pre[u][z-1];
        value %= m;
        if (z < graph[u].size()-1) value *= suf[u][z+1];
        value %= m;
        dfs1(graph[u][z],u,(value*(v+1))%m);
    }
}

