				if(mask&(1 << j))	tt += i;
			}

			ans += (dp[mask] * rej * tt);
			deb(rej);
		}

		deb(ans);

		ld tot = t * (t + 1);
		tot /= 2.0;
		return tot - ans;
	}
};

