void rec(int u, int par = -1){
	dp[u] = 1ll, sub[u] = 1;
	for(auto v : edges[u]){
		if(v != par){
			rec(v, u);
			sub[u] += sub[u];
			dp[u] = (dp[u] * (1ll + dp[v])) % m;
		}
	}
}

void dfs(int u, ll ans = 0, int par = -1){
	res[u] = ans;
	ll tmp;
