        adj[x].push_back(y);
        adj[y].push_back(x);
    }
    for (int i = 0; i < n; i++) sort(adj[i].begin(), adj[i].end());

    calcSTC(0, -1);
    for (int i = 0; i < n; i++) {
        int sz = adj[i].size();
        prodL[i].resize(sz); prodR[i].resize(sz);
        long long acc = 1;
        for (int j = 0; j < sz; j++) {
            prodL[i][j] = acc;
            if (adj[i][j] != parent[i])
                acc = acc * (1 + subtreeCount[adj[i][j]]) % m;
        }
        acc = 1;
        for (int j = sz-1; j >= 0; j--) {
            prodR[i][j] = acc;
            if (adj[i][j] != parent[i])
                acc = acc * (1 + subtreeCount[adj[i][j]]) % m;
        }
        // for (int j = 0; j < sz; j++) cerr << i << ' ' << j << ' ' << prodL[i][j] << ' ' << prodR[i][j] << endl;
    }

    calcRTC(0, -1);
    // for (int i = 0; i < n; i++) cerr << i << " " << revtreeCount[i] << endl;
    for (int i = 0; i < n; i++) {
        cout << subtreeCount[i] * revtreeCount[i] % m << endl;
