void dfs(int node, int dad){
	p[node] = dad;
	dp[node] = 1;
	REP(i, sz(e[node]))
		if (e[node][i] == dad){
			e[node].erase(e[node].begin() + i);
			break;
		}
	FORA(nxt, e[node]){
		dfs(nxt, node);
		dp[node] = mul(dp[node], sum(dp[nxt], 1));
		dpl[node].PB(sum(dp[nxt], 1));
		if (sz(dpl[node]) >= 2)
			dpl[ 	node].back() = mul(dpl[node].back(), dpl[node][sz(dpl[node]) - 2]);
	}
	reverse(all(e[node]));
	FORA(nxt, e[node]){
		dpr[node].PB(sum(dp[nxt], 1));
		if (sz(dpr[node]) >= 2)
			dpr[node].back() = mul(dpr[node].back(), dpr[node][sz(dpr[node]) - 2]);
	}
	reverse(all(e[node]));
	//cout << "Node:" _ node _ dp[node] << '\n';
}

