void dfs1(ll cur,ll pre,ll dp_p=0) {
  ll n=G[cur].size();
  vec mul1(n),mul2(n);
  for(ll i=0;i<n;i++) {
    ll nex=G[cur][i];
    if(nex==pre) {
      mul1[i]=mul2[i]=(dp_p+1)%m;
      dp[cur]*=dp_p+1;
      dp[cur]%=m;
    }
    else {
      mul1[i]=mul2[i]=(dp[nex]+1)%m;
    }
  }
  for(ll i=0;i+1<n;i++) {
    (mul1[i+1]*=mul1[i])%=m;
  }
  for(ll i=n-1;i-1>=0;i--) {
    (mul2[i-1]*=mul2[i])%=m;
  }
  for(ll i=0;i<n;i++) {
    ll nex=G[cur][i];
    if(nex==pre) continue;
    ll a=(i?mul1[i-1]:1);
    ll b=(i+1<n?mul2[i+1]:1);
    dfs1(nex,cur,a*b%m);
  }
}

