struct segTree{
    int sz;
    vector<int> m;
    set<int> podesen;
    void init(int n)
    {
        sz=n;
        m.resize(4*n,-1);
        for(int i=0;i<n;i++)
            podesen.insert(i);
    }
    void sett(int pos,int x,int l,int r,int i)
    {
        if(l>pos||r<pos)
            return;
        if(l==r&&l==pos){
            m[i]=x;
            return;
        }
        int mi=(l+r)>>1;
        sett(pos,x,l,mi,2*i);
        sett(pos,x,mi+1,r,2*i+1);
        m[i]=mul(m[2*i],m[2*i+1]);
    }
    void set1(int pos,int x)
    {
        //printf("Postavljam %i na %i\n",pos,x);
        podesen.erase(pos);
        sett(pos,x,0,sz-1,1);
    }
    int nije()
    {
        if(podesen.size()==sz)
            return -2;
        if(podesen.size()==0)
            return -1;
        assert(podesen.size()==1);
        return *podesen.begin();
    }
    int gett(int qs,int qe,int l,int r,int i)
    {
        if(qs>r||qe<l)
            return 1;
        if(qs<=l&&qe>=r)
        {
            return m[i];
        }
        int m=(l+r)>>1;
        return mul(gett(qs,qe,l,m,2*i),gett(qs,qe,m+1,r,2*i+1));
    }
    int get(int l,int r)
    {
        //printf("Getujem %i %i\n",l,r);
        return gett(l,r,0,sz-1,1);
    }
};
