long long dp[maxn];
vector<long long> pref[maxn];
vector<long long> suf[maxn];
long long sol[maxn];

long long dfs1(int pos, int parr) {
	dp[pos] = 1;
	pref[pos].push_back(1);
	suf[pos].push_back(1);

	for (int i = 0; i < graph[pos].size(); i++) {
		int tren = graph[pos][i];
		if (tren == parr) continue;

		long long ac = dfs1(tren, pos) + 1; ac %= m;
		dp[pos] *= ac, dp[pos] %= m;
		//if (pref[pos].size() == 0) pref[pos].push_back(ac);
		pref[pos].push_back((pref[pos].back() * ac) % m);
	}

	for (int i = graph[pos].size() - 1; i >= 0; i--) {
		int tren = graph[pos][i];
		if (tren == parr) continue;

		long long ac = dp[tren] + 1; ac %= m;
		//if (suf[pos].size() == 0) suf[pos].push_back(ac);
		suf[pos].push_back((suf[pos].back() * ac) % m);
	}
	reverse(suf[pos].begin(), suf[pos].end());
	return dp[pos];
}

void dfs2(int pos, int parr, long long solution) {
    sol[pos] = pref[pos].back() * solution, sol[pos] %= m;
    int ptr = 0;
    for (int i = 0; i < graph[pos].size(); i++) {
        int tren = graph[pos][i];
        if (tren == parr) continue;

        long long ac = pref[pos][ptr] * suf[pos][ptr + 1]; ac %= m;
        long long sen = ac * solution + 1; sen %= m;
        dfs2(tren, pos, sen);
        ptr++;
    }
}

