    //rerooting
    int pre_val;
    if(pre!=-1){
        //dp[pre]の再計算
        pre_val=1;
        for(auto to:edge[pre]){
            if(to!=v)
                pre_val *= dp[to]+1;
        }
    }

    for(auto to:edge[v]){
        if(to==pre) ans[v] *= pre_val+1;
        else ans[v] *= dp[to]+1;
        ans[v]%=M;
    }

    for(auto to:edge[v]){
        if(to!=pre)
            dfs_with_rerooting(to,v);
    }

}

