		else pre[node].pb((ll)pre[node][i-1]*(ll)(ans[son[node][i]]+1)%m);
	}
	for (int i=son[node].size()-1;i>=0;i--) {
		if (i==son[node].size()-1) suf[node].pb((ans[son[node][i]]+1)%m);
		else suf[node].pb((ll)suf[node][i-1]*(ll)(ans[son[node][i]]+1)%m);
	}
	reverse(suf[node].begin(),suf[node].end());
	return ans[node];
}

void getANS(int node,int lst,int cnt) {
	ANS[node]=(ll)ans[node]*(ll)(cnt+1)%m;
	for (int i=0;i<son[node].size();i++) {
		ll tmp=1ll;
		if (i) tmp*=(ll)pre[node][i-1];
		if (i<son[node].size()-1) tmp*=(ll)suf[node][i+1];
		tmp%=m;
