vector<map<int, int>> pos;
int n, mod, u, v;
void dfs(int v, int p)
{
    f[v] = 1;
    for (auto it : adj[v])
    {
        if (it == p)
            continue;
        tree[v].pb(it);
        dfs(it, v);
        f[v] *= (1 + f[it]);
        f[v] %= mod;
    }
    for (int i = 0; i < tree[v].size(); i++)
    {
        if (i == 0)
            prefix[v].pb(1 + f[tree[v][i]]);
        else
            prefix[v].pb(prefix[v].back() * (1 + f[tree[v][i]]));
        prefix[v].back() %= mod;
    }
    for (int i = (int)tree[v].size() - 1; i >= 0; i--)
    {
        if (i == (tree[v].size() - 1))
            suffix[v].pb(1 + f[tree[v][i]]);
        else
            suffix[v].pb(suffix[v].back() * (1 + f[tree[v][i]]));
        suffix[v].back() %= mod;
    }
    return;
}
void dfs2(int v, int p)
{
    for (int i = 0; i < tree[v].size(); i++)
    {
        int next = tree[v][i];
        g[next] = f[next];
        if (i > 0)
            g[next] *= prefix[v][i - 1];
        g[next] %= mod;
        if (i < (adj[v].size() - 1))
            g[next] *= suffix[v][tree[v].size() - i - 2];
        g[next]++;
        g[next] %= mod;
        dfs2(next, v);
    }
    return;
}
