    f.resize(n + 1, 1);
    g.resize(n + 1, 1);
    adj.resize(n + 1);
    prefix.resize(n + 1);
    suffix.resize(n + 1);
    pos.resize(n + 1);
    tree.resize(n + 1);
    for (int i = 1; i < n; i++)
    {
        cin >> u >> v;
        adj[u].pb(v);
        adj[v].pb(u);
    }
    dfs(1, 1);
    g[1] = 1;
    dfs2(1, 1);
    for (int i = 1; i <= n; i++)
        cout << ((f[i] * g[i]) % mod) << endl;
    return 0;
}

