int down[MAXN], up[MAXN], parent[MAXN];

int add(int a, int b) {

    a += b;
    if(a >= mod)
        a -= mod;
    return a;
}

int mul(int a, int b) {

    return ((ll)a * b) % mod;
}

void make_down(int u, int p) {

    down[u] = 1;
    parent[u] = p;
    for(int v: graph[u]) {
        if(v != p) {
            make_down(v, u);
            down[u] = mul(down[u], add(1, down[v]));
        }
    }
}

int make_up(int u) {

    if(up[u])
        return up[u];
    if(!u)
        return (up[u] = 1);

    int ans = 1;
    for(int v: graph[parent[u]])
        if(v != u && v != parent[parent[u]])
            ans = mul(ans, add(1, down[v]));

    return (up[u] = add(1, mul(ans, make_up(parent[u]))));
}

