long long dfs(vector< vector<int> > &G, vector<long long> &C, int v, int p, int M){
  long long ret = 1;
  for(size_t i = 0; i < G[v].size(); ++i){
    int v_ = G[v][i];
    if(v_ == p) continue;
    ret *= dfs(G,C,v_,v,M) + 1;
    ret %= M;
  }
  C[v] = ret;
  return ret;
}

void dfs2(vector< vector<int> > &G, vector<long long> &A, vector<long long> &C, int v, int p, int t, int M){
  A[v] = (t+1)*C[v]%M;
  int c = G[v].size();
  vector<long long> F(c+1), B(c+1);
  F[0] = 1;
  B[c] = 1;
  for(int i = 0; i < c; ++i){
    if(G[v][i] == p){
      F[i+1] = F[i];
      B[c-1-i] = B[c-i];
      continue;
    }
    F[i+1] = (F[i]*(C[G[v][i]]+1))%M;
    B[c-1-i] = (B[c-i]*(C[G[v][c-1-i]]+1))%M;
  }
  for(size_t i = 0; i < G[v].size(); ++i){
    int v_ = G[v][i];
    if(v_ == p) continue;
    int t_ = (t+1)*F[i]%M*B[i+1]%M;
    dfs2(G,A,C,v_,v,t_,M);
  }
}

