inline mint sum(pair<mint, mint> &p) {return p.first + p.second;}

pair<mint, mint> dfs1(int i, int j) {
  mint b(1), w(1);
  int siz = G[i].size();
  info[i].resize(siz);
  rep(id, siz) {
    int ne = G[i][id];
    if(ne == j) continue;
    mint bb, ww;
    tie(bb, ww) = dfs1(ne, i);
    info[i][id] = make_pair(bb, ww);
    b *= bb+ww;
    w *= ww;
  }
  return make_pair(b, w);
}
void dfs2(int i, int j, mint b, mint w) {
  //cout << P(i, j) << ' ' << b << ' ' << w << endl;
  int siz = G[i].size();
  vector<mint> lefb(siz+1), righb(siz+1), lefw(siz+1), righw(siz+1);
  lefb[0] = lefw[0] = righb[siz] = righw[siz] = 1;
  rep(id, siz) {
    if(G[i][id] == j) {
      lefb[id+1] = lefb[id] * (b+w);
      lefw[id+1] = lefw[id] * w;
    }
    else {
      lefb[id+1] = lefb[id] * sum(info[i][id]);
      lefw[id+1] = lefw[id] * info[i][id].second;
    }
    if(G[i][siz-id-1] == j) {
      righb[siz-id-1] = righb[siz-id] * (b+w);
      righw[siz-id-1] = righw[siz-id] * w;
    }
    else {
      righb[siz-id-1] = righb[siz-id] * sum(info[i][siz-id-1]);
      righw[siz-id-1] = righw[siz-id] * info[i][siz-id-1].second;
    }
  }
  rep(id, siz) {
    int ne = G[i][id];
    if(ne == j) {
      info[i][id] = make_pair(b, w);
      continue;
    }
    mint bb = lefb[id] * righb[id+1];
    mint ww = lefw[id] * righw[id+1];
    dfs2(ne, i, bb, ww);
  }
}

