ll pwr(ll a, ll p){
    if(p==0) return 1;
    ll t=pwr(a,p/2);
    t=t*t%mod;
    if(p%2) t=t*a%mod;
    return t;
}

ll dv(ll a, ll b){
    if(b==1) return a;
    a%=mod; b%=mod;
    ll g=__gcd(b,mod);
    a/=g; b/=g;
    b=pwr(b,fi-1);
    return (a*b)%mod;
}

