const int nmax = 100100;
ll N, M;
VL G[nmax], dp[nmax];

ll dfs1(ll now, ll par) {
    ll ret = 1;
    REP(i, G[now].size()) {
        ll to = G[now][i];
        if(to == par) continue;
        dp[now][i] = dfs1(to, now);
        (ret *= 1 + dp[now][i]) %= M;
    }
    return ret;
}

void dfs2(int cur, int pre, ll p) {
    REP(i, G[cur].size()) {
        int e = G[cur][i];
        if(e == pre) dp[cur][i] = p;
    }
    vector<ll> L(G[cur].size()), R(G[cur].size());
    REP(i, G[cur].size()) { L[i] = (i ? L[i - 1] : 1) * (1 + dp[cur][i]) % M; }
    for(int i = G[cur].size() - 1; i >= 0; i--) {
        R[i] =
            ((i < G[cur].size() - 1) ? (R[i + 1]) : 1) * (1 + dp[cur][i]) % M;
        if(G[cur][i] != pre) {
            ll tot = (i ? L[i - 1] : 1) *
                     ((i < G[cur].size() - 1) ? R[i + 1] : 1) % M;
            dfs2(G[cur][i], cur, tot);
        }
    }
}

