typedef long long ll;

const int maxn = 3e5+10;
const ll INF = 1e18;

ll mod;
vector<ll> g[maxn], pre[maxn], suf[maxn];
ll f[maxn], dp[maxn], d[maxn];
int par[maxn], pos[maxn];

void dfs(int v)
{
    f[v] = 1;

    for(auto u : g[v])
        if(u != par[v])
        {
            par[u] = v;
            dfs(u);
            pos[u] = pre[v].size();
            (f[v] *= (f[u]+1)) %= mod;
            if(pre[v].empty())
                pre[v].push_back((f[u]+1) % mod);
            else
                pre[v].push_back((pre[v].back() * (f[u]+1)) % mod);
        }

    if(g[v].size())
        for(int i = g[v].size()-1; i >= 0; i--)
        {
            int u = g[v][i];
            if(u != par[v])
            {
                if(suf[v].empty())
                    suf[v].push_back((f[u]+1) % mod);
                else
                    suf[v].push_back((suf[v].back() * (f[u]+1)) % mod);
            }
        }
    reverse(suf[v].begin(), suf[v].end());
}

void dfs_get_dp(int v)
{
    d[v] = 1;
    if(v != 1)
    {
        d[v] = d[par[v]];
        if(pos[v] >= 1)
            (d[v] *= pre[par[v]][pos[v]-1]) %= mod;
        if(pos[v] < pre[par[v]].size()-1)
            (d[v] *= suf[par[v]][pos[v]+1]) %= mod;
        (d[v] += 1) %= mod;
    }
    for(auto u : g[v])
        if(u != par[v])
            dfs_get_dp(u);
}

