ll dfs(ll v, ll color, ll already_black, ll p=-1){
    if(dp[v][color][already_black]!=-1)
        return dp[v][color][already_black];
    par[v]=p;
    ll ans=1;
    vector<ll> k;
    for(ll u: a[v]){
        if(u==p) continue;
        ll add=0;
        if(color==1)
            add=(dfs(u,0,1,v)+dfs(u,1,1,v))%m;
        else{
            if(already_black==0) add=dfs(u,1,1,v);
            add=(add+dfs(u,0,already_black,v))%m;
        }
        if(color==1){
            pos[u]=k.size();
            k.pb(add);
        }
        ans=(ans*add)%m;
    }
    int nk=k.size();
    if(color==1 && nk!=0){
        d[v].assign(nk,1);
        b[v].assign(nk,1);
        c[v].assign(nk,1);
        b[v][0]=k[0];
        for(int i=1;i<nk;i++)
            b[v][i]=(b[v][i-1]*k[i])%m;
        c[v][nk-1]=k[nk-1];
        for(int i=nk-2;i>=0;i--)
            c[v][i]=(c[v][i+1]*k[i])%m;
        d[v].assign(nk,1);
        if(nk>1) d[v][0]=c[v][1], d[v][nk-1]=b[v][nk-2];
        for(int i=1;i<nk-1;i++)
            d[v][i]=(b[v][i-1]*c[v][i+1])%m;
    }
    return dp[v][color][already_black]=ans;
}

