    ll mul;
    if(p==-1) mul=0;
    else mul=(d[p][pos[v]]*(prevmul+1))%m;
    dp[v][1][1]=(dp[v][1][1]*(mul+1))%m;
    for(ll u: a[v]){
        if(u==p) continue;
        dfs1(u,mul,v);
    }
}


