        it->second.prod1 = p;
        //h[it->first].prod1 = p;
        it->second.prodall = (p * it->first) % m;
      }
      // 「周りの全部の積、ただし自分除く」を作る（キャッシュに入れる値）
      forall(it, h) {
        long p = 1;
        forall(it2, h)
          if (it->first == it2->first)
            p = (p * it2->second.prod1) % m;
          else
            p = (p * it2->second.prodall) % m;
        it->second.prodme = (p + 1) % m;
      }
      // 各ノードにヒストグラムの値をコピー
      forall(it, dst[node])
        if (dst[it->first][node] == -1) {
          dst[it->first][node] = h[it->second].prodme;
          nextproc.push_back(it->first);
        }
    }
    proc.clear();
    forall(it, nextproc)
      proc.push_back(*it);
    nextproc.clear();
  }
  if (DBG2) {
    cout << "down from root done" << endl;
    forr(i,0,n-1) {
      cout << "i " << i << " ";
      forall(it, dst[i])
        cout << it->first << ":" << it->second << "  ";
      cout << endl;
    }
  }

  if (DBG) cout << "loop foo call" << endl;
  forr(i,0,n-1) {
    long p = 1;
    forall(it, dst[i])
      p = (p * it->second) % m;
    cout << p << endl;
    //cout << foo(i, -1) << endl;
  }
}

