using namespace std;
using Int = long long;
Int N, mod,root = 0;
vector<vector<Int>>edge;
vector<Int>ans,dis;
Int dfs(Int v, Int prev){
    if(edge[v].size() == 1 and v != root)
        return dis[v] = 1;
    dis[v] = 1;
    for(auto nv : edge[v]){
        if(nv == prev) continue;
        dis[v] *= (dfs(nv,v) + 1);
        dis[v] %= mod;
    }
    return dis[v];
}
auto build(const Int v){
    const Int deg = edge[v].size();
    vector<Int>r(deg),l(deg);
    for(Int i = 0; i < deg; ++i){
        r[i] = l[i] = (dis[edge[v][i]] + 1);
    }
    for(Int i = 0; i + 1 < deg; ++i)  l[i+1] *= l[i], l[i+1] %= mod;
    for(Int i = deg - 2; i >= 0 ; --i)  r[i] *= r[i + 1], r[i] %= mod;
    return make_pair(r,l);
}
void solve(Int v, Int dis_prev, Int prev){

    for(auto nv :edge[v]){
        ans[v] *= (nv == prev ?  dis_prev + 1 : dis[nv] + 1);
        ans[v] %= mod;
    }
    vector<Int>r,l;
    tie(r,l) = build(v);

    for(Int i = 0; i < edge[v].size(); ++i){
        Int nv = edge[v][i];
        if(nv == prev) continue;
        Int d_par = (i > 0 ? l[i-1] : 1) * ( i + 1 < edge[v].size() ? r[i+1] : 1);
        d_par %= mod;
        dis[v] = d_par;
        solve(nv,d_par,v);
    }
    return;
}
