vector<vector<ll>> dp;

ll memo_rec(int u, int parent = -1){
    ll res = 1;
    for(int i = 0; i < graph[u].size(); ++i){
        if(graph[u][i] != parent){
            dp[u][i] = memo_rec(graph[u][i], u);
            (res *= (dp[u][i] + 1)) %= m;
        }
    }
    return res;
}

void dfs(int u, ll add, int parent = -1){
    for(int i = 0; i < graph[u].size(); ++i){
        if(graph[u][i] == parent){
            dp[u][i] = add;
            break;
        }
    }

    int sz = graph[u].size();
    vector<ll> prefix(sz), suffix(sz);
    for(int i = 0; i < sz; ++i){
        suffix[i] = ((prefix[i] = (dp[u][i] + 1)) %= m);
    }
    for(int i = 1; i < sz; ++i){
        (prefix[i] *= prefix[i - 1]) %= m;
    }
    for(int i = sz - 2; i >= 0; --i){
        (suffix[i] *= suffix[i + 1]) %= m;
    }

    for(int i = 0; i < sz; ++i){
        if(graph[u][i] == parent) continue;

        ll add_c = 1;
        if(i != 0)  (add_c *= prefix[i - 1]) %= m;
        if(i != sz - 1) (add_c *= suffix[i + 1]) %= m;
        dfs(graph[u][i], add_c, u);
    }
}

