	long long total_d =1;
	pref[i].resize(adj[i].size());
	suff[i].resize(adj[i].size());
	for (auto x : adj[i])
	{
		if (x == p)
			continue;
		parent[x] = i;
		dfs_up_down(x, i);
		// if current node is black, each of i's children can be either black or while
		// if x (one of the children) is white, the entire subtree of x has to be white
		total_d = (total_d * (1 + DP_d[x]))%mod ;

		// case 1: p is white, all p's other children's subtree has to be white (1 way to color)
		// case 2: p is black, all p's other children (except i) can be either black or white
		// this can't be calculate at the moment so need 2nd dfs to update DP_u (depends on DP_d of sibilings)
	}
	DP_d[i] = total_d;

	//generate prefix and suffix array at node i
	long long tmp = 1;
	for(int j=0; j<adj[i].size(); j++)
	{
		tmp = (tmp * (1+DP_d[adj[i][j]])) % mod;
		pref[i][j] = tmp;
	}
	tmp = 1;
	for (int j = adj[i].size() - 1; j >= 0; j--)
	{
		tmp = (tmp * (1 + DP_d[adj[i][j]])) % mod;
		suff[i][j] = tmp;
	}
}

