ll hell=1e18+5;
inline ll mult(ll x,ll y){x%=hell;y%=hell;return (1LL*x*y)%hell;}
inline ll add(ll x,ll y){x+=y;return x%hell;}
inline ll powMod(ll base,ll expo){
	if(base==0)return 0;
	ll ans=1;
	while(expo){
		if(expo&1)ans=mult(ans,base);
		base=mult(base,base); 
		expo>>=1;
	}
	return ans;
}
void dfs(ll node,ll par){
	sub[node]=1;
	ll x=1;
	for(auto u : adj[node]){
		if(u==par)continue;
		child[node].pb(u);
		dfs(u,node);
		sub[node]=mult(sub[node],sub[u]+1);
		x=mult(x,sub[u]+1);
		pref[node].pb(x);
	}
	x=1;
	for(ll i=sz(adj[node])-1;i>=0;i--){
		if(adj[node][i]==par)continue;
		x=mult(x,sub[adj[node][i]]+1);
		suf[node].pb(x);
	}
	reverse(all(suf[node]));
}
void dfs2(ll node,ll up){
	ways[node]=(up+1)%hell;
	rep(i,0,sz(child[node])){
		ll newUp=(up+1);
		if(i!=0)newUp=mult(newUp,pref[node][i-1]);
		if(i!=sz(child[node])-1)newUp=mult(newUp,suf[node][i+1]);
		dfs2(child[node][i],newUp);
		ways[node]=mult(ways[node],(sub[child[node][i]]+1));
	}
}
void solve(){
	ll n, x, y;
	cin>>n>>hell;
	rep(i,1,n){
		cin>>x>>y;
		adj[x].pb(y);
		adj[y].pb(x);
