int n,mod;
const int MAXN = 100*1000+1;
vi V[MAXN];
LL dp[MAXN][2];
bool visited[MAXN];
int ans[MAXN];

void dfs(int x,int p) {
    visited[x]=1;
    for(auto nbh:V[x]) {
        if(!visited[nbh]) {
            dfs(nbh,x);
        }
    }
    if(p!=-1&&V[x].size()==1) {
        dp[x][1] = dp[x][0] = 1;
    }
    else {
        dp[x][1] = 1;
        dp[x][0] = 0;
        for(auto nbh:V[x]) {
            if(nbh!=p) {
                dp[x][1] = ((LL)dp[x][1]*(dp[nbh][1]+1))%mod;
                dp[x][0] = (dp[x][0]+dp[nbh][0]+dp[nbh][1])%mod;
            }
        }
    }
}

void dfs2(int x,int p) {
    visited[x]=1;
    ans[x] = dp[x][1];
    vector<LL> pref={1},suf={1};
    int pos = 0;
    for(auto nbh:V[x]) {
        pref.PB(((LL)pref.back()*(dp[nbh][1]+1))%mod);
        pos++;
    }
    for(int i=V[x].size()-1; i>=0; i--) {
        suf.PB((suf.back()*(dp[V[x][i]][1]+1))%mod);
    }
    reverse(suf.begin(),suf.end());
    pos=0;
    for(auto nbh:V[x]) {
        if(!visited[nbh]) {
            //changes
            dp[x][0] = (dp[x][0] - (dp[nbh][0]+dp[nbh][1]))%mod;
            dp[x][0] = (dp[x][0]+mod)%mod;
            dp[nbh][0] = (dp[nbh][0]+dp[x][0]+dp[x][1])%mod;
            dp[x][1] = (pref[pos]*suf[pos+1])%mod;
            dp[nbh][1] = (dp[nbh][1]*(dp[x][1]+1))%mod;
            dfs2(nbh,x);
            //roll back
            dp[nbh][0] = (dp[nbh][0]-dp[x][0]-dp[x][1])%mod;
            dp[nbh][0] = (dp[nbh][0]+mod)%mod;
            dp[x][0] = (dp[x][0]+dp[nbh][0]+dp[nbh][1])%mod;
            dp[x][1] = pref.back();
        }
        pos++;
    }
}

