        if(dp_blk[u][col][i]<0) {
            ll rez=1;
            RNG(j, idx_from, idx_to) {
                int to = adj[u][j];
                rez = rez * dfs(to, u, col) % MOD;
            }
            dp_blk[u][col][i] = rez;
        }

        res = res*dp_blk[u][col][i] % MOD;
    }

    if(p>=1 && col==0)
        res += dfs(u, p, 1);

    return dp[u][col]=res%MOD;
}

int main() {
    ios_base::sync_with_stdio(false); cin.tie(nullptr); cout.tie(nullptr);
    cin>>N>>MOD;
    FOR(i,N-1)
    {
        int a,b; cin>>a>>b;
        adj[a].push_back(b);
        adj[b].push_back(a);
    }

    RNG(u,1,N) {
        int blks = ((int)adj[u].size() + BLK-1) / BLK;
        FOR(i,2)
            dp_blk[u][i].resize(blks, -1);
        sort(ALL(adj[u]));
    }

    dfs1(1, -1);

    for(auto u : order) {
        ans[u] = dfs(u, -1, 0);
    }

    FOR(i,N) cout<<ans[i+1]<<'\n';

    return 0;
}

