// a^n mod を計算する
long long modpow(long long a, long long n, long long mod) {
        long long res = 1;
    while (n > 0) {
        if (n & 1) res = res * a % mod;
        a = a * a % mod;
        n >>= 1;
    }
    return res;
}

// a^{-1} mod を計算する
long long modinv(long long a, long long mod) {
    return modpow(a, mod - 2, mod);
}

// (a%MOD) * modinv(b, MOD) % MOD で　a/b;
long long moddiv(long long a, long long b, long long mod = 1e9+7){
    ll res = (a%mod) * modinv(b, mod) % mod;
    return (res+mod)%mod ;
}

int dfs(ll x, ll p){
    ll res = 1;
    for(auto v : G[x]){
        if(v == p) continue;
        res *= (dfs(v, x)+1);
        res %= M;
    }
    DP[x] = res;
    return DP[x];
}

void dfs2(ll x, ll p = -1){
    ll res = 1;
    for(auto v : G[x]){
        if(v == p) continue;
        DP2[v] = (DP2[x]/(DP[v]+1)+1) * DP[v];
        DP2[v] = ((( moddiv(DP2[x], (DP[v]+1), M) +1 ) % M ) * DP[v] ) % M;
    }
    for(auto v : G[x]){
        if(p != v)dfs2(v, x);
    }
}

