void exgcd(ll a, ll b, ll &d, ll &x, ll &y) {
  if (!b) {
    d = a;
    x = 1;
    y = 0;
    return;
  }
  exgcd(b, a % b, d, y, x);
  y -= x * (a / b);
}

ll inv(ll a, ll n) {
  ll d, x, y;
  exgcd(a, n, d, x, y);
  x = (x + n) % n;
  return d == 1 ? x : -1;
}

ll blackRoot(int x, int par) {
