	ll N,M; cin >> N >> M;
	corner(N==1,1);
	Lowest_Common_Ancestor tree(N);
	REP(i,N-1){
		int x,y; cin >> x >> y;
		x--,y--;
		tree.make_edge(x,y);
		tree.make_edge(y,x);
	}
	tree.make_depth(0);
	tree.make_child();
	tree.make_order();
	tree.make_parent();
	V<ll> dp1(N,1),dp2(N,0);
	for(int i = 0; i < N; ++i){
		int j = tree.order[i];
		for(auto k:tree.child[j]) (dp1[j] *= (dp1[k] + 1) ) %= M;
	}
	for(int i = N-1; 0 <= i; --i){
		int j = tree.order[i];
		V<ll> a;
		for(int k = 0; k < tree.child[j].size(); ++k) a.push_back(dp1[tree.child[j][k]]);
		a.push_back(dp2[j]);
		int K = a.size();
		if(K == 1) continue;
		V<ll> L(K),R(K);
		L[0] = a[0] + 1;
		for(int i = 1; i < K; ++i) L[i] = (L[i-1]*(a[i] + 1)) % M;
		R[K-1] = a[K-1] + 1;
		for(int i = K-2; 0 <= i; --i) R[i] = (R[i+1]*(a[i] + 1)) % M;

		for(int k = 0; k < tree.child[j].size(); ++k) {
			int l = tree.child[j][k];
			dp2[l] = 1;
			if(0<=k-1) (dp2[l] *= L[k-1]) %= M;
			if(k+1<K) (dp2[l] *= R[k+1]) %= M;
		}
	}

	V<ll> dp(N,1);
	for(int i = 0; i < N; ++i){
		(dp[i] *= (dp2[i] + 1) ) %= M;
		for(auto k:tree.child[i]) (dp[i] *= (dp1[k] + 1) ) %= M;
		cout << dp[i] << endl;
	}


	return 0;
}

