void bfs(){
    queue<tuple<int, int, long long>> que;
    que.push(make_tuple(0, -1, 1));
    while(!que.empty()){
        int cur, prv;
        long long mul;
        tie(cur, prv, mul) = que.front();
        que.pop();

        vector<int> chs;
        for(int nxt : G[cur]){
            if(nxt == prv) continue;
            chs.push_back(nxt);
        }
        int K = chs.size();
        vector<long long> cm0(K+2, 1), cm1(K+2, 1);
        for(int i=0; i<K; i++) cm0[i+1] = (cm0[i] * (dp[chs[i]] + 1) % M) % M;
        for(int i=K-1; i>=0; i--) cm1[i+1] = (cm1[i+2] * (dp[chs[i]] + 1) % M) % M;
        REP(i, K){
            long long tmp = ((mul * (cm0[i] * cm1[i+2]) % M) % M + 1) % M;
            dp[chs[i]] *= tmp;
            dp[chs[i]] %= M;
            que.push(make_tuple(chs[i], cur, tmp));
        }
    }
