void go(ll u, ll p = 0){
    vector<ll> vec, nodes;
    for(ll v : adj[u])
        if(v != p){
            nodes.push_back(v);
            vec.push_back(1 + down[v]);
        }

    vector<ll> pref(vec), suff(vec);
    for(ll i = 1; i < pref.size(); i++)
        pref[i] = (pref[i]*pref[i-1])%mod;
    for(ll i = ll(suff.size()) - 2; i >= 0; i--)
        suff[i] = (suff[i]*suff[i+1])%mod;

    for(ll i = 0; i < nodes.size(); i++){
        ll v = nodes[i];
        ll esq = (i-1 >= 0 ? pref[i-1] : 1);
        ll dir = (i+1 < vec.size() ? suff[i+1] : 1);
        esq = (esq*dir)%mod;
        //cout << u << " setando up de " << v << endl;
        up[v] = (1 + ((esq*up[u])%mod) )%mod;
