vector<vector<int>> tree;

vector<int> dp;
vector<bool> visited;
vector<int> res;

long long modinv(long long a, long long b) { return 1 < a ? b - modinv(b % a, a) * b / a : 1; }

int dfs(int start) {
    if (!visited[start]) {
        visited[start] = true;
        if (tree[start].empty())
            dp[start] = 1;
        else {
            long long cnt = 1LL;
            for (int child : tree[start])
                if (!visited[child])
                    cnt = (cnt * (dfs(child) + 1)) % m;

            dp[start] = (int)cnt;
        }
    }

    return dp[start];
}

void solve(int node, int parent) {
    if (parent == -1)
        res[node] = dp[node];
    else {
        long long factor = __gcd(res[parent], dp[node] + 1);
        long long num = res[parent] / factor;
        long long den = (dp[node] + 1) / factor;

        res[node] = (int)(((num * modinv(den, m) + 1) % m) * dp[node]) % m;
    }

    for (int child : tree[node])
        if (child != parent)
            solve(child, node);
}

