double cl4(double a, int t, double b) {
	switch (t)
	{
	case 0:
		return a + b;
	case 1:
		return a - b;
	case 2:
		return a * b;
	case 3:
		if (b == 0) { 
			return INF; }
		else 
			return a  / b;
	default:
		break;
	}
}
void clc5(double a, int t1, double b) {
	double ab = cl4(a, t1, b);
	if (ab != INF && ab > 0 && ab < 1000 && (int)ab == ab) {
		fnd[(int)ab] = 1;
	}
}
void clc4(double a, int t1, double b, int t2, double c) {

	double ab = cl4(a, t1, b);
	double bc = cl4(b, t2, c);
	if (ab != INF) {
		clc5(ab, t2, c);
	}
	if (bc != INF) {
		clc5(a, t1, bc);
	}
}

void clc3(double a,int t1, double b,int t2, double c,int t3, double d) {

	double ab = cl4(a, t1, b);
	double bc = cl4(b, t2, c);
	double cd = cl4(c, t3, d);
	if (ab != INF) {
		clc4(ab, t2, c, t3,d);
	}
	if (bc != INF) {
		clc4(a, t1, bc, t3, d);
	}
	if (cd != INF) {
		clc4(a, t1, b, t2, cd);
	}


}
void clc2(ll a, ll b, ll c, ll d) {

	for (size_t i = 0; i < 4; i++)
	{
		for (size_t j = 0; j < 4; j++)
		{
			for (size_t k = 0; k < 4; k++)
			{
				clc3(a, i, b, j, c, k, d);
			}
		}
	}
}
void clc(ll a, ll b, ll c, ll d) {

	ll t[] = { a,b,c,d };
	do {
		clc2(t[0], t[1], t[2], t[3]);
	} while (next_permutation(t,t+4));
}

