	dp1[u] = 1;
	vi nodes;
	for(auto &v : graph[u]){
		if(v == p)continue;
		nodes.pb(v);
		dfs(v,u);
	}
	if(nodes.empty())return;
	dp2[0] = dp1[nodes[0]]+1;
	for(int i = 1; i < nodes.size(); i++){
		dp2[i] = dp2[i-1];
		dp2[i] += ((dp2[i-1]%M)*(dp1[nodes[i]]%M))%M;
