void dfs(ll u , ll p)
{
    ans[u]=1;
    for(auto v:vec[u])
    {
        if(v==p)
            continue ;
        dfs(v,u);
        ans[u]*=1+ans[v];
        down[u].push_back({ans[v],v});
        ans[u]%=m;
    }
    ans[u]%=m;
    ll n=down[u].size();
    if(!n)
        return ;
    ll x=1;
    x*=1+down[u][0].fi;
    pre[u].push_back(x);
    for(ll i=1;i<n;i++)
    {
        x*=down[u][i].fi+1;
        x%=m;
        pre[u].push_back(x);
    }
    x=1;
    ll y=1;
    x*=down[u][n-1].fi+1;
    x%=m;
    suf[u].push_back(x);
    for(ll i=n-2;i>=0;i--)
    {
        x*=1+down[u][i].fi;
        y*=1+down[u][i].fi;
        y%=m;
        x%=m;
        suf[u].push_back(x);
        suf2[u].push_back(y);
    }
    suf2[u].push_back(1);
    reverse(suf[u].begin(),suf[u].end());
    reverse(suf2[u].begin(),suf2[u].end());

}


void dfs1(ll u , ll parent)
{
    ll n=down[u].size();
    for(ll i=0;i<n;i++)
    {
        ll v=down[u][i].se;
        ll x=1;
        if(i!=0)
            x*=pre[u][i-1];
        x%=m;
        if(i!=n-1)
        {
            if(x>1)
                x*=(suf2[u][i+1]%m)*(down[u][n-1].fi%m);
            else
                x*=suf[u][i+1];
        }
        x%=m;
        if(u!=1)
            x*=up[u]+1;
        x%=m;
        up[v]=x;
        ans[v]*=x+1;
        ans[v]%=m;
    }
    for(auto v:vec[u])
    {
        if(v!=parent)
            dfs1(v,u);
    }
}

