const int maxn = 1e5+5;
int size[maxn], parent[maxn], child[maxn], dp1[maxn], mod;
VI pre[maxn], suf[maxn], G1[maxn], G2[maxn]; map<PII,int> dp2;

int dfs0(const int u, const int p)
{
    size[u] = 1; parent[u] = p; int i = 0;
    FOR_ALL(v,G1[u]) if (*v != p) {
        size[u] += dfs0(*v,u);
        child[*v] = i++;
        G2[u].push_back(*v);
    }
    return size[u];
}

int getpre(const int u, const int i)
{ return i >= 0 ? pre[u][i] : 1; }
int getsuf(const int u, const int i)
{ return i < G2[u].size() ? suf[u][i] : 1; }

int dfs1(const int u)
{
    if (size[u] == 1)
        return 1;
    int& ans = dp1[u];
    if (-1 == ans) {
        ans = 1;
        FOR_ALL(v,G2[u]) 
            dfs1(*v);
        const int n = G2[u].size();
        pre[u] = suf[u] = VI(n,1);
        FOR(i,0,n) {
            pre[u][i] = 1LL * getpre(u,i-1) * dfs1(G2[u][i]) % mod;
            pre[u][i] += getpre(u,i-1);
            pre[u][i] %= mod;
        }
        FORR(i,n-1,-1) {
            suf[u][i] = 1LL * getsuf(u,i+1) * dfs1(G2[u][i]) % mod;
            suf[u][i] += getsuf(u,i+1);
            suf[u][i] %= mod;
        }
        ans = pre[u][n-1];
    }
    return ans;
}

int dfs2(const int u, const int c)
{
    if (u == 0)
        return 0;
    const PII k(u,c);
    if (in_(k,dp2))
        return dp2[k];
    int& ans = dp2[k] = 1LL * getpre(u,c-1) * getsuf(u,c+1) % mod;
    ans += 1LL * ans * dfs2(parent[u],child[u]) % mod;
    ans %= mod;
    return ans;
}

