ll dfs(int v, int p){
    dp[v] = 1;

    for(int w : G[v]){
        if(w == p){
            continue;
        }

        dp[v] = dp[v] * (dfs(w, v) + 1) % M;
    }

    return dp[v];
}

void dfs2(int v, int p, ll c){
    int deg = G[v].size();

    std::vector<ll> vl(deg + 1), vr(deg + 1);

    vl[0] = 1;

    for(int i=0;i<deg;++i){
        if(G[v][i] == p){
            vl[i+1] = vl[i] * (c + 1) % M;
        }else{
            vl[i+1] = vl[i] * (dp[G[v][i]] + 1) % M;
        }
    }

    vr[deg] = 1;

    for(int i=deg-1;i>=0;--i){
        if(G[v][i] == p){
            vr[i] = vr[i+1] * (c + 1) % M;
        }else{
            vr[i] = vr[i+1] * (dp[G[v][i]] + 1) % M;
        }
    }

    dp2[v] = vr[0];

    for(int i=0;i<deg;++i){
        int w = G[v][i];

        if(w == p){
            continue;
        }

        dfs2(w, v, vl[i] * vr[i+1] % M);
    }
}

