vector<int> G[100000];
long dp[100000];
long prerec(int from, int prev) {
  long ret = 1;
  for (int to : G[from]) {
    if (to == prev) continue;
    ret = ret * (1 + prerec(to, from)) % mod;
  }
  dp[from] = ret;
  return ret;
}

long ans[100000];
void rec(int from, int prev, long inher) {
  int m = G[from].size();
  vector<long> l(m + 1);
  vector<long> r(m + 1);
  l[0] = 1;
  r[m] = 1;
  for (int k = 0; k < m; ++k) {
    int to = G[from][k];
    long elem = 1 + (to == prev ? inher : dp[to]);
    l[k + 1] = elem;
    r[k] = elem;
  }

  for (int k = 0; k < m; ++k) l[k + 1] = l[k] * l[k + 1] % mod;
  for (int k = m; k > 0; --k) r[k - 1] = r[k] * r[k - 1] % mod;

  for (int k = 0; k < m; ++k) {
    int to = G[from][k];
    if (to == prev) continue;
    long nxt = l[k] * r[k + 1] % mod;
    rec(to, from, nxt);
  }
  ans[from] = l[m];
}

