int f[N], g[N];

void df(int v, int p) {
	for (int u: t[v]) if (u != p) df(u, v);
	f[v] = 1;
	for (int u: t[v]) if (u != p) f[v] *= f[u]+1, f[v] %= M;
}

void dg(int v, int p) {
	int n = t[v].size();
	int pre[n+1], suf[n+1];
	pre[0] = suf[0] = 1;
	rep(i, n) {
		int u = t[v][i];
		if (u == p) pre[i+1] = pre[i];
		else pre[i+1] = pre[i] * (f[u]+1), pre[i+1] %= M;
	}
	rep(i, n) {
		int u = t[v][n-1-i];
		if (u == p) suf[i+1] = suf[i];
		else suf[i+1] = suf[i] * (f[u]+1), suf[i+1] %= M;
	}
	rep(i, n) {
		int u = t[v][i];
		if (u != p) g[u] = pre[i] * suf[n-1-i] % M * (g[v] + 1) % M;
	}
	for (int u: t[v]) if (u != p) dg(u, v);
}

