std::vector<long long> ways;
std::vector<bool> vis;
std::vector<long long> par;
std::vector<long long> fin;
long long dfs(long long num)
{
	ways[num]=1;
	vis[num]=1;
	for(auto it:g[num])
	{
		if(!vis[it])
		{
			par[it]=num;
			ways[num]=((ways[num]*(dfs(it)+1))%mod);
		}
	}
	return ways[num];
}
pii eu(long long a,long long b)
{
	if(a==0){return {0,1};}
	if(b==0){return {1,0};}
	long long q=(a/b),r=(a%b);
	pii t=eu(b,r);
	return {t.y,((t.x)-(q*(t.y)))};

}
long long invi(long long num)
{
	if(__gcd(num,mod)!=1){return 0;}
	pii ans=eu(num,mod);
	ans.x=((((ans.x)%mod)+mod)%mod);
	return ans.x;
}
long long rec(long long ix)
{
	if(fin[ix]!=-1){return fin[ix];}
	long long p=par[ix];
	if(ways[p]=0||ways[ix]==0){fin[ix]=0;return 0;}
	long long g=__gcd(ways[ix]+1,mod);
	long long W=((ways[ix]+1)/g);
	fin[ix]=(ways[ix]*((((fin[p]/g)*invi(W))%mod)+1))%mod;
	return fin[ix];
}
long long solve()
{
	long long n,m;cin>>n>>m;
	mod=m;
	g.resize(n+1);ways.resize(n+1,1);fin.resize(n+1,-1);par.resize(n+1,0);
