	vis.resize(n+1,0);
	REP(i,0,n-2)
	{
		long long a,b;
		cin>>a>>b;
		g[a].pb(b);g[b].pb(a);
	}
	dfs(1);
	fin[1]=ways[1];
	REP(i,1,n)
	{
		rec(i);
		cout<<fin[i]<<"\n";
	}
}
signed main(){
