template<class T>
class Segtree{
	unsigned int n;
	unsigned int size;
	vector<T> node;
	T val;
	function< T(T,T)> f;
public:
	Segtree(unsigned int a_n, T a_val, function< T(T,T)> a_f) :n(1),val(a_val),f(a_f){
		while(n<a_n)n<<=1;
		size = n*2-1;
		node.assign(size,val);
	}
	void set(int i, T x){
		node[i+n-1]=x;
	}
	T get(int i){
		return node[i+n-1];
	}
	void update(){
		for(int i=n-2;i>=0;i--){
			node[i] = f(node[i*2+1],node[i*2+2]);
		}
	}
	void update(int i, T x){
		i += n-1;
		node[i]=x;
		while(i>0){
			i = (i-1)/2;
			node[i] = f(node[i*2+1],node[i*2+2]);
		}
	}
	T query(int a,int b){
		return _query(a,b,0,0,n);
	}
	T _query(int a,int b,int i,int l,int r){
		if(r<=a || b<=l) return val;
		if(a<=l && r<=b) return node[i];
		else{
			T vl = _query(a,b,i*2+1,l,(l+r)/2);
			T vr = _query(a,b,i*2+2,(l+r)/2,r);
			return f(vl,vr);
		}
	}
};


LL n,m;

VL links[100005];
LL dp1[100005] = {0};
LL dp2[100005] = {0};
map<LL,LL> dp1_sub[100005];
map<LL,LL> dp2_sub[100005];

void erase_parent(LL i, LL parent){
    if(parent != -1){
        links[i].erase(find(ALL(links[i]),parent));
    }
    for(LL child : links[i]){
        erase_parent(child, i);
    }
}

LL f(LL i){
    dp1[i] = 1;
    for(LL child : links[i]){
        dp1[i] *= (f(child) + 1) % m;
        dp1[i] %= m;
    }
	Segtree<LL> s(links[i].size(),1ll,
	    [](LL a,LL b){return (a*b)%m;});
    REP(j,links[i].size()){
        s.set(j, dp1[links[i][j]] + 1);
    }
    s.update();
    REP(j, links[i].size()){
        LL left = s.query(0,j);
        LL right = s.query(j+1,links[i].size());
        dp1_sub[i][links[i][j]] = (left * right) % m;
    }
    //for(LL j : links[i]){
    //    LL sub = 1;
    //    for(LL child : links[i]){
    //        if(child == j) continue;
    //        sub *= (dp1[child] + 1) % m;
    //        sub %= m;
    //    }
    //    dp1_sub[i][j] = sub;
    //}
    return dp1[i];
}

LL g(LL i, LL parent){
    dp2[i] = dp1[i];
    if(parent != -1){
        dp2[i] += dp1[i] * dp2_sub[parent][i];
        dp2[i] %= m;
    }
    for(LL j : links[i]){
        LL sub = dp1_sub[i][j];
        if(parent != -1){
            sub += dp1_sub[i][j] * dp2_sub[parent][i];
        }
        dp2_sub[i][j] = sub % m;
    }
    for(LL child : links[i]){
        g(child, i);
    }
    return dp2[i];
}

