const int mxn = 100010;
ll dp[mxn], tmp[mxn], ans[mxn], mod;
int N;

vector<int> adj[mxn];

void dfs_dp(int node,  int parent)
{
	for(auto x:adj[node])
		if(x!=parent) dfs_dp(x, node);

	dp[node] = 1ll; 
	for(auto x:adj[node])
		if(x!=parent) dp[node]*=(dp[x]+1), dp[node]%=mod;
}

void dfs_ans(int node, int parent)
{
	if(parent!=-1) {
		tmp[parent] = 1ll;
		for(auto x:adj[parent])
			if(x!=node) tmp[parent]*=(tmp[x]+1), tmp[parent]%=mod;
	}

	ans[node] = 1;
	for(auto x:adj[node])
		ans[node]*=(tmp[x]+1), ans[node]%=mod;

	for(auto x:adj[node])
		if(x!=parent) dfs_ans(x, node);

	tmp[node] = dp[node];
}

void process(int root)
{
	dfs_dp(root, -1);
	for(int i=1; i<=N; i++) tmp[i] = dp[i];
	dfs_ans(root, -1);
}

