using namespace std;

using ll = long long;

const ll MOD = 1000000007;

ll modpow(ll x, ll n, ll mod = MOD) {
	ll res = 1;
	while (n > 0) {
		if (n & 1) res = res * x % mod;
		x = x * x % mod;
		n >>= 1;
	}
	return res;
}

ll m;
vector< vector<int> > g;
vector<ll> L[100005];
vector<ll> R[100005];
ll dp[100005];

ll dfs(int cur, int par) {
	ll& res = dp[cur];
	if (res > 0) return res;

	res = 1;
	L[cur].push_back(1);
	for (int nex : g[cur]) {
		if (nex == par) continue;
		ll tmp = (dfs(nex, cur) + 1) % m;
		(res *= tmp) %= m;
		L[cur].push_back(tmp);
		R[cur].push_back(tmp);
	}
	R[cur].push_back(1);
	int sz = L[cur].size();
	for (int i = 1; i < sz; i++) {
		(L[cur][i] *= L[cur][i - 1]) %= m;
	}

	for (int i = sz - 2; i >= 0; i--) {
		(R[cur][i] *= R[cur][i + 1]) %= m;
	}
	return res;
}

ll dp2[100005];

void dfs2(int cur, ll d_par, int par) {
	if (dp2[cur] > 0) return;
	//cout << cur << " " << d_par << endl;
	dp2[cur] = (d_par + 1) % m;
	for (int i = 0, j = 0; i < g[cur].size(); i++) {
		int nex = g[cur][i];
		if (nex == par) continue;
		(dp2[cur] *= (dp[nex] + 1) % m) %= m;
		//cout << nex << " " << L[cur][j] << " " << R[cur][j + 1] << endl;
		dfs2(nex, L[cur][j] * R[cur][j + 1] % m * (d_par + 1) % m, cur);
		j++;
	}
}

