vector<vector<int>> g(100010);
vector<vector<ll>> cm1(100010), cm2(100010);
vector<ll> dp(100010), ans(100010);

ll cdp(int v, int p = -1) {
    ll res = 1;
    for (auto e : g[v])
        if (e != p) {
            res = res * (cdp(e, v) + 1) % mod;
        }
    return dp[v] = res;
}

void dfs(int v, int p = -1) {
    ans[v] = dp[v];
    rep(j, 0, g[v].size()) {
        int qq = j + 1;
        int to = g[v][j];
        if (to != p) {
            ll a = dp[v], b = dp[to];
            dp[v] = 1;

            if (cm1[v].empty()) {
                cm1[v].emplace_back(1);
                for (auto to2 : g[v]) {
                    cm1[v].emplace_back(dp[to2] + 1);
                }
                cm1[v].emplace_back(1);
                // dp[v] = dp[v] * (dp[to2] + 1) % mod;
                cm2[v] = cm1[v];
                int x = cm1[v].size();
                rep(i, 1, x) cm1[v][i] = cm1[v][i] * cm1[v][i - 1] % mod;
                for (int i = x - 1; i > 0; i--)
                    cm2[v][i - 1] = cm2[v][i - 1] * cm2[v][i] % mod;
            }
            dp[v] = (cm1[v][qq - 1] * cm2[v][qq + 1]) % mod;
            dp[to] = dp[to] * (dp[v] + 1) % mod;
            dfs(to, v);
            dp[v] = a;
            dp[to] = b;
        }
    }
}

