    if(pa_ch==v)  continue;
    if(pa_ch==papa) continue;
    ans*=(dp1.at(pa_ch)+1);
    ans%=mod;
  }
  ans++;
  ans%=mod;
  dp2.at(v)=ans;
  for(int i=0;i<sz(graph.at(v));i++){
    int nv=graph.at(v).at(i);
    if(nv==pa)  continue;
    dfs2(nv,v,pa);
  }
}

