int modexp(int x, unsigned int y){
  int res = 1;
  x %= MOD;
  if(!y) return 0;
  while(y > 0){
    if(y & 1) res = mul(res, x, MOD);
    y >>= 1;
    x = mul(x, x, MOD);
  }
  return res;
}

int modularInverse(int a){
