using namespace std;
using ll = long long;
const ll mxn = 100010;
ll dp[mxn], tmp[mxn], ans[mxn], mod;
ll N;

vector<ll> adj[mxn], pre[mxn], suff[mxn], children[mxn];

void dfs_dp(ll node, ll parent) {
	for(auto x:adj[node])
		if(x!=parent) dfs_dp(x, node);

	dp[node] = 1ll; 
	for(auto x:adj[node])
		if(x!=parent) {
			dp[node]*=(dp[x]+1);
			dp[node]%=mod;
			children[node].push_back(x);
		}
}

void calc_pre_suff() {
	for(ll node=1; node<=N; node++) {
		ll sz = (ll) children[node].size();
		if(!sz or sz==1) continue;
		pre[node].resize(sz);
		suff[node].resize(sz);
		pre[node][0] = dp[children[node][0]]+1;
		for(ll i=1; i<sz; i++)
			pre[node][i] = pre[node][i-1]*(dp[children[node][i]]+1)%mod;
		suff[node][sz-1] = dp[children[node][sz-1]]+1;
		for(ll i=sz-2; i>=0; i--)
			suff[node][i] = suff[node][i+1]*(dp[children[node][i]]+1)%mod;
	}
}

ll get_range(ll node, ll idx) {
	ll sz = (ll) children[node].size();
	if(sz==1) return 1ll;
	if(idx==0) return suff[node][1];
	if(idx==sz-1) return pre[node][sz-2];
	return suff[node][idx+1]*pre[node][idx-1]%mod;
}


void dfs_ans(ll node, ll parent, ll val_of_parent=0ll) { 
	ans[node] = val_of_parent+1;
	for(auto x:adj[node])
		if(x!=parent) ans[node]*=(dp[x]+1), ans[node]%=mod;

	for(ll i=0; i<(ll) children[node].size(); i++) {
		ll next = children[node][i];
		ll new_val = (val_of_parent+1)*get_range(node, i)%mod;
		dfs_ans(next, node, new_val);
	}
}

void process(ll root) {
	dfs_dp(root, -1);
	calc_pre_suff();
	dfs_ans(root, -1);
}

int main() {
	ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);

	cin>>N>>mod;
	for(ll i=0; i<N-1; i++) {
		ll x, y; cin>>x>>y;
		adj[x].push_back(y);
		adj[y].push_back(x);
	}

	process(N);

	for(ll i=1; i<=N; i++)
		cout << ans[i] << '\n';

	return 0;
}

