void dfs(int u, int p) {
	dp[u] = 1;
	pdp[u].pb(1);
	for (int v : adj[u]) 
		if (v != p) {
			dfs(v, u);
			dp[u] = (dp[u] * (dp[v] + 1)) % M;
			pdp[u].pb(dp[u]);
		}
