	reverse(adj[u].begin(), adj[u].end());
	for (int v : adj[u]) 
		if (v != p)
			sdp[u].pb(sdp[u].back() * (dp[v] + 1) % M); 
}

void dfs2(int u, int p, int val) {
	dp[u] = (dp[u] * (val + 1));
	reverse(adj[u].begin(), adj[u].end());
	int in = 0;
	int sin = (int)sdp[u].size() - 2;
	for (int v : adj[u]) 
		if (v != p)
			dfs2(v, u, (pdp[u][in++] * sdp[u][sin--] % M) * (val + 1) % M);
}

