void dfs(ll u, ll p)
{
    ans[u] = 1;
    for(ll i=0; i<adj[u].size(); i++){
        ll v = adj[u][i];
        if(v != p){
            dfs(v, u);
            ans[u] = ans[u] * (1+ans[v]);
            ans[u] = ans[u]%mod;
            prefix[u].push_back(ans[u]);
        }
    }
    ll c = 1;
    for(ll i=adj[u].size()-1; i>=0; i--){
        ll v = adj[u][i];
        if(v != p){
            c = c * (1+ans[v]);
            c = c%mod;
            suffix[u].push_back(c);
        }
    }
    reverse(suffix[u].begin(), suffix[u].end());
}

void dfs2(ll u, ll par, ll prop)
{
    ans[u] = ans[u]*(1+prop);
    ans[u] = ans[u]%mod;
    vector<ll> V;
    for(int i=0; i<adj[u].size(); i++){
        if(adj[u][i] == par) continue;
        else V.push_back(adj[u][i]);
        /*ll p = 1, s = 1;
        if(id != 0) p = p * prefix[u][id-1];
        if(id != adj[u].size()-1) s = s * suffix[u][id+1];
        ll val = (p*s)%mod;
        val = ((1+prop)*val)%mod;
        id++;
        dfs2(adj[u][i], u, val);*/
    }
    for(int i=0; i<V.size(); i++){
        ll p = 1, s = 1;
        if(i != 0) p = p * prefix[u][i-1];
        if(i != V.size()-1) s = s * suffix[u][i+1];
        ll val = (p*s)%mod;
        val = ((1+prop)*val)%mod;
        dfs2(V[i], u, val);
    }
}

