int n,m;

vector<int> g[N];

long long f[N]; bool calf[N];

void enter()
{
    cin >> n >> m;
    for (int i=1,u,v; i<n; i++)
    {
        cin >> u >> v;
        g[u].push_back(v);
        g[v].push_back(u);
    }
}

vector<long long> postf[N], pref[N];

void dfs1(int u, int p)
{
    f[u] = 1;
    for (int v : g[u])
    {
        if (v == p) continue;
        dfs1(v,u);
        f[u] = f[u] * (f[v] + 1) % m;
    }

    postf[u].resize(g[u].size());
    pref[u].resize(g[u].size());

    long long ff = 1;
    for (int j=0; j<g[u].size(); j++)
    {
        if (g[u][j] == p) continue;
        pref[u][j] = ff;
        ff = ff * (1+f[g[u][j]]) % m;
    }

    ff = 1;
    for (int j=g[u].size() - 1; j>=0; j--)
    {
        if (g[u][j] == p) continue;
        postf[u][j] = ff;
        ff = ff * (1+f[g[u][j]]) % m;
    }

    calf[u] = true;
}

long long r[N]; bool calr[N];

void dfs2(int u,int p, long long bb, long long pp)
{
    r[u] = (f[u] * bb)%m;
    for (int v,j=0; j<g[u].size(); j++)
    {
        v = g[u][j];
        if (v == p) continue;
        dfs2(v,u,bb + pp * (pref[u][j] * postf[u][j]) % m ,pp * (pref[u][j] * postf[u][j]) % m);
    }
}

int main()
{
    enter();
    dfs1(1, -1);
    dfs2(1, -1, 1,1);
    for (int i=1; i<=n; i++)
        cout << r[i] << endl;
    return 0;
}

