int MOD, b;
vector <int> s[100005];
vector <long long> bio[100005];
long long modz(long long x, long long y)
{
	if(x + y >= MOD)
	{
		return x+y-MOD;
	}
	return x+y;
}
long long f(int poz, int p)
{
	int lp;
	if(p != -1)
	{
		lp = (int)(lower_bound(s[poz].begin(), s[poz].end(), p)-s[poz].begin());
		if(bio[poz][lp] != -1)
		{
			return bio[poz][lp];
		}
    }
	long long u = 1;
	for(int i = 0; i < s[poz].size(); i++)
	{
		if(s[poz][i] != p)
		{
			u *= f(s[poz][i], poz);
			u %= MOD;
		}
	}
	if(p != -1)
	{
		return bio[poz][lp] = modz(u, 1);
	}
	else
	{
		return u;
	}
}
