//i를 색칠하고 i를 root로 하는 트리의 여집합(그것 역시 트리)을 칠하는 가짓수
ll solve2(int i){
	ll& ret=dp2[i];
	if(ret!=-1ll) return ret;
	if(i==1) return ret=1;
	ret=1;
	int j=p[i];
	ret=(ret*solve2(j))%m;
	for(int next:adj[j]){
		if(next!=i && next!=p[j]) ret=(ret*(1+solve1(next)))%m; 
	}
	ret=(ret+1)%m;
	return ret;
}

void dfs(int i,int prev){
	p[i]=prev;
	for(int next:adj[i])
		if(next!=prev) dfs(next,i);
