const int WHITE = 0;
const int BLACK = 1;

int solve(int cur, int col, int par=-1) {
    int &val = dp[cur][col];
    if(val >= 0) return val;

    val = 1;
    for(auto to : G[cur]) {
        if(to == par) continue;
        int white = solve(to, WHITE, cur);
        int black = solve(to, BLACK, cur);

        if(col == WHITE) {
            (val *= white) %= M;
        }
        if(col == BLACK) {
            (val *= (white + black)) %= M;
        }
    }
    return val;
}

