void rotate(int cur, int par=-1) {
    // dump_array(cur);
    ans[cur] = dp[cur][BLACK];

    int par_w = 1, par_b = 1;
    vector<int> info_w, info_b, nxt;
    for(auto to : G[cur]) {
        if(to == par) {
            par_w = dp[to][WHITE];
            par_b = (dp[to][BLACK] + dp[to][WHITE]) % M;
            // fprintf(stderr, "cur = %lld, par = %lld, white = %lld, black = %lld\n", cur, par, par_w, par_b);
            continue;
        }
        info_w.push_back(dp[to][WHITE]);
        info_b.push_back((dp[to][BLACK] + dp[to][WHITE]) % M);
        nxt.push_back(to);
    }

    vector<int> pre_w(1, 1), suf_w(1, 1), pre_b(1, 1), suf_b(1, 1);
    int L = info_w.size();
    for(int i=0; i<L; i++) {
        if(i == 0) {
            pre_w.push_back(info_w[i]);
            pre_b.push_back(info_b[i]);
        }
        else {
            pre_w.push_back(pre_w.back() * info_w[i] % M);
            pre_b.push_back(pre_b.back() * info_b[i] % M);
        }
    }
    for(int i=L-1; i>=0; i--) {
        if(i == L-1) {
            suf_w.push_back(info_w[i]);
            suf_b.push_back(info_b[i]);
        }
        else {
            suf_w.push_back(suf_w.back() * info_w[i] % M);
            suf_b.push_back(suf_b.back() * info_b[i] % M);
        }
    }
    reverse(suf_w.begin(), suf_w.end());
    reverse(suf_b.begin(), suf_b.end());

    int orig_w = dp[cur][WHITE], orig_b = dp[cur][BLACK];
    for(int i=0; i<L; i++) {
        int to = nxt[i];

        dp[cur][WHITE] = pre_w[i] * suf_w[i+1] % M * par_w % M;
        dp[cur][BLACK] = pre_b[i] * suf_b[i+1] % M * par_b % M;
        // fprintf(stderr, "cur = %lld, to = %lld, white = %lld, black = %lld\n", cur, to, dp[cur][WHITE], dp[cur][BLACK]);

        int orig_child_w = dp[to][WHITE], orig_child_b = dp[to][BLACK];
        (dp[to][WHITE] *= dp[cur][WHITE]) %= M;
        (dp[to][BLACK] *= dp[cur][WHITE] + dp[cur][BLACK]) %= M;
        rotate(to, cur);

        dp[to][WHITE] = orig_child_w;
        dp[to][BLACK] = orig_child_b;
    }
    dp[cur][WHITE] = orig_w;
    dp[cur][BLACK] = orig_b;
}

