    adj[x].push_back(y);
    adj[y].push_back(x);
  }
  dfs(1, -1);
  dfs1(1, -1);
  for (int i = 1; i <= n; i++) {
    printf("%d\n", (1ll * up[i] * down[i]) % mod);
  }
  return 0;
}

