ll dfs(int i,int last, vl &dp, vvi &g){
  for(auto &e:g[i]){
    if(e!=last) dp[i] = dp[i]*(1+dfs(e,i,dp,g)) % m;
  }
  return dp[i];
}
void dfs2(int i,int last, vl &dp, vl &dp2,vvi &gr){
  auto &g = gr[i];
  vl cum(g.size()+1,1), rcum(g.size()+1,1);
  REP(j,g.size()){
    if(last!=g[j]) cum[j+1] = cum[j]*(1+dp[g[j]])%m;
    else cum[j+1] = cum[j];
  }
  RREP(j,g.size()){
    if(last!=g[j]) rcum[j] = rcum[j+1]*(1+dp[g[j]])%m;
    else rcum[j] = rcum[j+1];
  }
  REP(j,g.size())if(last!=g[j]) dp2[g[j]] = (dp2[i]*cum[j]%m*rcum[j+1]+1)%m;
  REP(j,g.size())if(last!=g[j]) dfs2(g[j],i,dp,dp2,gr);
}
