long long dp[111111];
long long ep[111111];

void dfs(int s, int p=-1){
    long long res = 1;
    for(int t : adj[s]){
        if(t == p) continue;
        dfs(t, s);
        res *= (dp[t]+1);
        res %= M;
    }
    dp[s] = res;
}

void efs(int s, int p=-1){
    ep[s] = 1;
    for(int t : adj[s]){
        ep[s] *= dp[t]+1;
        ep[s] %= M;
    }

    int sz = adj[s].size();
    vector<long long> lef(sz+2, 1), rig(sz+2, 1);
    for(int i=0; i<sz; i++){
        lef[i+1] = (lef[i] * (dp[adj[s][i]] + 1)) % M;
        rig[sz-i] = (rig[sz-i+1] * (dp[adj[s][sz-i-1]] + 1)) % M;
    }

    for(int i=0; i<sz; i++){
        int t = adj[s][i];
        if(t == p) continue;
        dp[s] = (lef[i] * rig[i+2]) % M;
        efs(t, s);
    }
}


