struct Factorial {

  int modpow(int& a, u64 n) noexcept {
    if (n == 0) return 1;
    auto t = modpow(a, n / 2);
    t = (int)((i64)t * t % mod);
    if (n & 1) t = (int)((i64)t * a % mod);
    return t;
  }

  Factorial(int count, int mod) : mod(mod) {

    f.reserve(count + 1);
    fi.reserve(count + 1);

    f.push_back(1);
    fi.push_back(1);
    FOR(i, 1, count + 1) {
      f.push_back((int)(((i64)f[i - 1] * i) % mod));
      fi.push_back(modpow(f[i], mod - 2));
      //cout << i << " " << f[i] << " " << fi[i] << newl;
    }
    f[0] = 0;
