    //debug(fi[r]);
    //debug(fi[n - r]);
    return (int)((i64)f[n] * fi[r] % mod * fi[n - r] % mod);
  }

  int mod;

  // 階乗
  vector<int> f;

  // 階乗の逆元
  vector<int> fi;
};

