void dfs(long long dg, long long up) {
    dp[dg][0] = 1;
    for(long long i = 0; i < v[dg].size(); ++i) {
        if(v[dg][i].first != up) {
            dfs(v[dg][i].first, dg);
            (dp[dg][0] *= dp[v[dg][i].first][0] + 1) %= m;
        }
    }
    if(!v[dg].size()) return;
    for(long long i = 0; i < v[dg].size(); ++i) {
        if(v[dg][i].first != up) v[dg][i].second.first = dp[v[dg][i].first][0] + 1;
        else v[dg][i].second.first = 1;
        if(i) (v[dg][i].second.first *= v[dg][i - 1].second.first) %= m;
    }
    for(long long i = (int)v[dg].size() - 1; i > 0; --i) {
        v[dg][i].second.first = v[dg][i - 1].second.first;
    }
    v[dg][0].second.first = 1;
    for(long long i = (int)v[dg].size() - 1; i >= 0; --i) {
        if(v[dg][i].first != up) v[dg][i].second.second = dp[v[dg][i].first][0] + 1;
        else v[dg][i].second.second = 1;
        if(i + 1 < v[dg].size()) (v[dg][i].second.second *= v[dg][i + 1].second.second) %= m;
    }
    for(long long i = 0; i + 1 < v[dg].size(); ++i) {
        v[dg][i].second.second = v[dg][i + 1].second.second;
    }
    v[dg][v[dg].size() - 1].second.second = 1;
    for(long long i = 0; i < v[dg].size(); ++i) {
        (v[dg][i].second.first *= v[dg][i].second.second) %= m;
    }
}

void Dfs(long long dg, long long up, long long ri) {
    if(up) (dp[dg][1] = dp[up][1] * v[up][ri].second.first + 1) %= m;
    else dp[dg][1] = 1;
    for(long long i = 0; i < v[dg].size(); ++i) {
        if(v[dg][i].first != up) {
            Dfs(v[dg][i].first, dg, i);
        }
    }
}

