mint dp[101000];
mint dp2[101000];
vector<bool> visit(101000);
vector<SegmentTree<mint>> prod;

mint rec(vector<vector<int>> &tree, int cur, int par){
  if(visit[cur]) return dp[cur];
  visit[cur] = true;

  dp[cur] = 1;

  for(auto next : tree[cur]){
    if(next == par) continue;
    dp[cur] *= (rec(tree,next,cur)+1);
  }

  int c = tree[cur].size();
  if(par != -1) --c;

  prod[cur] = SegmentTree<mint>(c,1,[&](mint a, mint b){return a*b;}, [&](mint a, mint b){return b;});

  REP(i,c){
    prod[cur].update(i,dp[tree[cur][i]]+1);
  }

  return dp[cur];
}

mint rec2(vector<vector<int>> &tree, int cur, int par, int index){
  if(visit[cur]) return dp2[cur];
  visit[cur] = true;

  if(par == -1) dp2[cur] = 0;
  else dp2[cur] = (dp2[par]+1) * prod[par].query(0,index) * prod[par].query(index+1,tree[par].size());

  int i = 0;
  for(auto next : tree[cur]){
    if(next == par) continue;
    rec2(tree, next, cur, i);
    ++i;
  }

  return dp2[cur];
}

int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);

  cin >> N >> M;
  vector<vector<int>> tree(N);
  REP(i,N-1){
    int x,y; cin >> x >> y;
    --x, --y;
    tree[x].push_back(y);
    tree[y].push_back(x);
  }

  prod.resize(N);

  rec(tree, 0, -1);
  fill(ALL(visit),false);
  rec2(tree, 0, -1, 0);

  REP(i,N){
    mint ans = (dp2[i]+1) * dp[i];
    cout << ans << endl;
  }

  return 0;
}

