		pref[0] = vertices[v][0] == par ? 1 : (down[vertices[v][0]] + 1) % m;
		for (int i = 1; i < k; i++)
		{
			if (vertices[v][i] == par)
			{
				pref[i] = pref[i - 1];
			}
			else
			{
				pref[i] = pref[i - 1] * (down[vertices[v][i]] + 1) % m;
			}
		}

		suf[k - 1] = vertices[v][k - 1] == par ? 1 : (down[vertices[v][k - 1]] + 1) % m;
		for (int i = k - 2; i >= 0; i--)
		{
			if (vertices[v][i] == par)
			{
				suf[i] = suf[i + 1];
			}
			else
			{
				suf[i] = suf[i + 1] * (down[vertices[v][i]] + 1) % m;
			}
		}

		for (int i = 0; i < k; i++)
		{
			if (vertices[v][i] == par) continue;

			int calc = up[v];
			if (i - 1 >= 0)
			{
				calc = calc * pref[i - 1] % m;
			}
			if (i + 1 < k)
			{
				calc = calc * suf[i + 1] % m;
			}

			dfs2(vertices[v][i], calc, v);
		}
	}
}

