vector<vector<int> > dp;
vector<vector<int> > sum1;
vector<vector<int> > sum2;
vector<int> X;
map <pair<int, int>, int>  mp;

int solve(int a, int x) {

	//cerr << a << " " << x << endl;
	if (dp[a][x] == -1) {
		int ne = g[a][x];

		if (X[ne] == -1) {
			X[ne] = a;
			dp[a][x] = 1;
			for (int i = 0; i < g[ne].size(); i++) {
				if (g[ne][i] != a) {
					dp[a][x] = (dp[a][x] * solve(ne, i)) % M;
				}
			}
			dp[a][x]++;
		}
		else if (X[ne] != -2) {
			solve(ne, mp[make_pair(ne, X[ne])]);

			for (int i = 0; i < g[ne].size(); i++) {
				sum1[ne][i + 1] = (sum1[ne][i] * dp[ne][i]) % M;
			}
			for (int i = (int)g[ne].size() - 1; i >= 0; i--) {
				sum2[ne][i] = (sum2[ne][i + 1] * dp[ne][i]) % M;
			}

			X[ne] = -2;
		}
		if (X[ne] == -2) {
			int idx = mp[make_pair(ne, a)];
			dp[a][x] = (sum1[ne][idx] * sum2[ne][idx + 1]) % M;
			dp[a][x]++;
		}
	}
	return dp[a][x];
}
