	                     mul(a.all_white, b.sth_is_black, mod), mod);
	return p;
}

pii process(pii p) {
	return {p.all_white, add(p.sth_is_black, p.all_white, mod)};
}

void dfs_one(int u, int parent) {
	pii p = {1, 0};
	for (auto v : g[u]) {
		if (parent != v) {
			child[u].pb(v);
			dfs_one(v, u);
			p = merge(p, down[v]);
			downs[u].pb(down[v]);
		}
	}
	down[u] = process(p);
}

void dfs_two(int u) {
	for (int i = 0; i < sz(child[u]); i++) {
		pii p = {1, 0};
		if (i != 0) {
			p = merge(p, pref[u][i - 1]);
		}
		if (i != sz(downs[u]) - 1) {
			p = merge(p, suf[u][i + 1]);
		}
		if (u != 1) {
			p = merge(p, up[u]);
		}
		int v = child[u][i];
		up[v] = process(p);
		dfs_two(v);
	}
}

int solve() {
	int n = in();
	mod = in();
	for (int i = 0; i < n - 1; i++) {
		int u = in(), v = in();
		g[u].pb(v);
		g[v].pb(u);
	}
	dfs_one(1, -1);
	for (int u = 1; u <= n; u++) {
		int k = sz(downs[u]);
		pii p = {1, 0};
		for (int i = 0; i < k; i++) {
			p = merge(p, downs[u][i]);
			pref[u].pb(p);
		}
		p = {1, 0};
		for (int i = k - 1; i >= 0; i--) {
			p = merge(p, downs[u][i]);
			suf[u].pb(p);
		}
		reverse(all(suf[u]));
	}
	dfs_two(1);
	for (int u = 1; u <= n; u++) {
		pii p = {1, 0};
		if (u != 1) {
			p = merge(p, up[u]);
		}
		if (!child[u].empty()) {
			p = merge(p, pref[u].back());
		}
		p = process(p);
		printf("%d\n", p.sth_is_black);
	}
	return 0;
}

int main() {
	int test = 1, tc = 0;
	//scanf("%d", &test);
	while (test--) {
		//printf("Case %d: ", ++tc);
		solve();
	}
	return 0;
}

