void dfs1(vector<vector<int>> &da, vector<modint> &ans, int chi, int par = -1){
	rip(i, da[chi].size(), 0){
		if(da[chi][i] == par) continue;
		dfs1(da, ans, da[chi][i], chi);
		ans[chi] *= ans[da[chi][i]]+1;
	}
	ans[chi];
}

void dfs2(vector<vector<int>> &da, vector<modint> &ans, int chi, modint dp, int par = -1){
	if(par != -1) ans[chi] *= dp;
	int si = da[chi].size();
	vector<modint> dpL(si+1, modint(1,m)), dpR(si+1, modint(1, m));
	// cout << chi << endl
	rip(i, si, 0){
		dpL[i+1] = dpL[i];
		if(da[chi][i] == par) dpL[i+1] *= dp;
		else dpL[i+1] *= ans[da[chi][i]]+1;
	}
	for(int i = si;i>0;i--){
		dpR[i-1] = dpR[i];
		if(da[chi][i] == par) dpR[i-1] *= dp;
		else dpR[i-1] *= ans[da[chi][i-1]]+1;
	}
	rip(i, si, 0){
		if(da[chi][i] == par) continue;
		dfs2(da, ans, da[chi][i], dpL[i]*dpR[i+1]+1, chi);
	}
}

