#include <bits/stdc++.h>
using namespace std;

int n, m;
vector<vector<int>> tree;
vector<int> dp;

void dfs(int node, int parent) {
    long long cnt = 1;
    for (int child : tree[node]) {
        if (child != parent) {
            dfs(child, node);
            cnt *= dp[child] + 1;
            cnt %= m;
        }
    }

    dp[node] = cnt;
}

void update(int node, int parent, int parent_contrib = 1) {
    int p = tree[node].size();
    vector<int> pref_prods, suff_prods;

    pref_prods.reserve(p + 1);
    pref_prods.push_back(parent_contrib);
    for (int i = 0; i < p; ++i)
        if (tree[node][i] != parent)
            pref_prods.push_back(1LL * pref_prods.back() * (dp[tree[node][i]] + 1) % m);

    suff_prods.reserve(p + 1);
    suff_prods.push_back(1);
    for (int i = p - 1; i >= 0; --i)
        if (tree[node][i] != parent)
            suff_prods.push_back(1LL * suff_prods.back() * (dp[tree[node][i]] + 1) % m);

    reverse(suff_prods.begin(), suff_prods.end());
    for (int i = 0, j = 0; i < p; ++i) {
        if (tree[node][i] != parent) {
            dp[tree[node][i]] = ((1LL * pref_prods[j] * suff_prods[j + 1] + 1 % m) * dp[tree[node][i]] % m);
            update(tree[node][i], node, 1LL * pref_prods[j] * suff_prods[j + 1] + 1 % m);
            ++j;
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> m;
    tree.resize(n);
    for (int i = 0; i < n - 1; ++i) {
        int x, y;
        cin >> x >> y;
        tree[x - 1].push_back(y - 1);
        tree[y - 1].push_back(x - 1);
    }

    dp.resize(n);
    dfs(0, -1);
    update(0, -1);
    for (int i = 0; i < n; ++i)
        cout << dp[i] << "\n";

    return 0;
}

