template<typename WeightT>
struct edge {
  int from, to;
  WeightT weight;
  edge(int s, int d, WeightT w): from(s), to(d), weight(w) {}
};

template<typename WeightT>
using edges = std::vector<edge<WeightT> >;

template<typename WeightT>
using adjacency_list = std::vector<edges<WeightT> >;

template<typename WeightT>
void
add_undir_edge(adjacency_list<WeightT> &G, int u, int v, WeightT w) {
  G[u].emplace_back(u, v, w);
  G[v].emplace_back(v, u, w);
}

struct rooted_tree {
  size_t size;
  std::vector<size_t> topo;
  std::vector<size_t> par;
  std::vector<std::vector<size_t>> children;
};

template <typename WeightT>
rooted_tree make_rooted_tree(adjacency_list<WeightT> const &G, size_t root) {
  size_t N = G.size();
  std::vector<size_t> topo, par(N);
  par[root] = N + 1;
  std::vector<std::vector<size_t>> ch(N);

  std::vector<bool> used(N, false);
  std::stack<size_t> stk;
  stk.push(root); used[root] = true;
  while (!stk.empty()) {
    size_t const u = stk.top(); stk.pop();
    topo.push_back(u);
    for (auto &&e : G[u]) {
      if (used[e.to]) { continue; }
      stk.push(e.to); used[e.to] = true;
      par[e.to] = u;
      ch[u].push_back(e.to);
    }
  }
  return { N, topo, par, ch };
}

template <typename T, typename FnT>
struct product {
  explicit product(FnT const &app, T un, std::vector<T> const &seq):
    fn(app), prefix(seq.size()+1, un), suffix(seq.size()+1, un)
  {
    for (size_t i = 0; i < seq.size(); ++i) {
      prefix[i+1] = fn(prefix[i], seq[i]);
    }
    for (size_t i = seq.size(); i > 0; --i) {
      suffix[i-1] = fn(seq[i-1], suffix[i]);
    }
  }
  T value() const {
    return suffix[0];
  }
  T cut(size_t i) const {
    return fn(prefix[i], suffix[i+1]);
  }
  FnT fn;
  std::vector<T> prefix;
  std::vector<T> suffix;
};

using namespace std;

using Graph = adjacency_list<nullptr_t>;

lli M;
lli mult_modm(lli a, lli b) {
  return (a * b) % M;
}
using Product = product<lli, decltype(&mult_modm)>;

void solve(int N, Graph const &G) {
  auto const tree = make_rooted_tree(G, 0);
  vector<Product> dr(N, Product(mult_modm, 1, {}));
  RREP(i, tree.size) {
    size_t u = tree.topo[i];
    std::vector<lli> ch;
    for (auto &&v : tree.children[u]) {
      ch.push_back(dr[v].value() + 1);
    }
    dr[u] = Product(mult_modm, 1, ch);
  }

  vector<lli> dpar(N);
  dpar[0] = 0;
  for (auto &&u : tree.topo) {
    REP(j, tree.children[u].size()) {
      size_t v = tree.children[u][j];
      dpar[v] = mult_modm(dpar[u]+1, dr[u].cut(j));
    }
  }
  REP(u, N) {
    cout << mult_modm(dr[u].value(), dpar[u]+1) << endl;
  }
}

int main() {
  int N; cin >> N >> M;
  Graph G(N);
  REP(i, N-1) {
    int X, Y; cin >> X >> Y;
    add_undir_edge(G, --X, --Y, nullptr);
  }
  solve(N, G);
  return 0;
}

