vector<int> G[100000];
long ans[100000];
long DP[100000];
long buffer[100000];
long buffer2[100000];
void Calc(){
	int N = rei();
	long M = rel();
	for(int i=0;i<N-1;i++){
		int x = rei()-1;
		int y = rei()-1;
		G[x].push_back(y);
		G[y].push_back(x);
	}
	stack<pair<int,int>> sp1;
	sp1.push({0,-1});
	while(!sp1.empty()){
		int v = sp1.top().first;
		int f = sp1.top().second;
		sp1.pop();
		if(v >= N){
			v -= N;
			long c = 1;
			for(int t:G[v]){
				if(t != f){
					c *= (DP[t]+1);
					c %= M;
				}
			}
			DP[v] = c;
		}
		else{
			sp1.push({v+N,f});
			for(int t:G[v]){
				if(t != f){
					sp1.push({t,v});
				}
			}
		}
	}
	stack<tuple<int,int,long>> sp2;
	sp2.push(make_tuple(0,-1,1));
	while(!sp2.empty()){
		int v = get<0>(sp2.top());
		int f = get<1>(sp2.top());
		long par = get<2>(sp2.top());
		ans[v] = par * DP[v] % M;
		sp2.pop();
		int g = G[v].size();
		buffer[0] = 1;
		buffer2[g] = 1;
		for(int i=0;i<g;i++){
			int t = G[v][i];
			if(t != f){
				buffer[i+1] = buffer[i] * (DP[t] + 1) % M;
			}
			else{
				buffer[i+1] = buffer[i];
			}
		}
		for(int i=g-1;i>=0;i--){
			int t = G[v][i];
			if(t != f){
				buffer2[i] = buffer2[i+1] * (DP[t] + 1) % M;
			}
			else{
				buffer2[i] = buffer2[i+1];
			}
		}
		for(int i=0;i<g;i++){
			int t = G[v][i];
			if(t != f){
				long c = (buffer[i] * buffer2[i+1] % M * par + 1) % M; 
				sp2.push(make_tuple(t,v,c));
			}
		}
	}
	for(int i=0;i<N;i++){
		cout << ans[i] << endl;
	}
}
int main(int argc,char** argv){
	ios::sync_with_stdio(false), cin.tie(0);
	cout.tie(0); Calc(); return 0;
}

