  rep1(i,n-1) lft[i]=mu(lft[i-1],lft[i]);
  for(int i=n-2;i>=0;i--){
    rht[i] = mu(rht[i+1],rht[i]);
  }

  rep(i,n){
    if(g[v][i]==p) continue;
    cnt[v]=1;
    if(i>0) cnt[v]=mu(cnt[v],lft[i-1]);
    if(i+1<n) cnt[v]=mu(cnt[v],rht[i+1]);
    dfs2(v,g[v][i]);    
  }
}


