#include <bits/stdc++.h>

using namespace std;

using ll = long long;

constexpr int kMaxN = 1e5 + 3;

vector<int> edges[kMaxN];

ll mod;

ll add(ll a, ll b) {
  a += b;
  if (a >= mod) {
    a -= mod;
  }
  return a;
}

ll mul(ll a, ll b) {
  return a * b % mod;
}

using pll = pair<ll, ll>;

pll merge(pll a, pll b) {
  pll res;

  res.first = mul(a.first, b.first);
  res.second = add(
      mul(a.second, add(b.first, b.second)),
      mul(a.first, b.second)
  );

  return res;
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(0);
  cout.tie(0);

  ll n;
  cin >> n >> mod;

  for (int i = 1; i < n; ++i) {
    int x, y;
    cin >> x >> y;
    --x, --y;
    edges[x].emplace_back(y);
    edges[y].emplace_back(x);
  }

  vector<ll> ans(n);
  vector<pll> dp(n);

  function<pll(int, int)> dfs = [&] (int u, int p) {
    // first - white, second - black
    pll cur{1, 0};
    for (int v: edges[u]) {
      if (v != p) {
        auto res = dfs(v, u);
        cur = merge(cur, res);
      }
    }

    dp[u] = {cur.first, add(cur.first, cur.second)};

    return dp[u];
  };

  dfs(0, -1);

  function<void(int, int, pll)> fill_ans = [&] (int u, int p, pll up) {

    vector<pll> subtree;
    pll cur{1, 0};
    for (int v: edges[u]) {
      if (v != p) {
        subtree.emplace_back(dp[v]);
      }
    }

    vector<pll> pref, suf;
    cur = {1, 0};
    for (int i = 0; i < subtree.size(); ++i) {
      cur = merge(cur, subtree[i]);
      pref.emplace_back(cur);
    }

    cur = {1, 0};
    for (int i = subtree.size() - 1; i >= 0; --i) {
      cur = merge(cur, subtree[i]);
      suf.emplace_back(cur);
    }
    reverse(suf.begin(), suf.end());

    pll tmp = {1, 0};
    if (!pref.empty()) {
      tmp = merge(tmp, pref.back());
    }
    if (u) {
      tmp = merge(tmp, up);
    }
    ans[u] = add(tmp.first, tmp.second);

    int i = 0;
    for (int v: edges[u]) {
      if (v != p) {
        tmp = {1, 0};
        if (u) {
          tmp = merge(tmp, up);
        }
        if (i > 0) {
          tmp = merge(tmp, pref[i - 1]);
        }
        if (i + 1 < pref.size()) {
          tmp = merge(tmp, suf[i + 1]);
        }
        tmp.second = add(tmp.first, tmp.second);
        fill_ans(v, u, tmp);
        ++i;
      }
    }
  };

  fill_ans(0, -1, {1LL, 0LL});

  for (ll a: ans) {
    cout << a << '\n';
  }

  return 0;
}

