		else s1[u][i]=dp[v]+1;
		update(dp[u],dp[v]+1);
	}
	for (int i=g[u].size()-1;i>=0;i--) {
		int v=g[u][i];
		if (v==p) {
			if (i<g[u].size()-1)
				s2[u][i]=s2[u][i+1];
			else s2[u][i]=1;
			continue;
