        int nw = children[node][i];
        if( i+1<sz(children[node]) )
        {
            suffix_mul[node][i] = mul( suffix_mul[node][i+1] , dp[nw]+1 );
        }
    }

    if( node==1 ) {

        ans[node] = dp[node];int i = 0;
        for( int nw: children[node] ) {
            dfs_rooting( nw , mul(preffix_mul[node][i],suffix_mul[node][i]) );
