void solve2(vector<int> adj[], int n, int m, int u, int parent, ll pval){
    dp2[u] = ((1 + pval)*dp1[u])%m;

    vector<ll> prefix, suffix;
    for(int v : adj[u]){
        if(v != parent){
            prefix.push_back(1 + dp1[v]);
            suffix.push_back(1 + dp1[v]);
        }
    }
    for(int i=1;i<prefix.size();i++){
        prefix[i] = (prefix[i-1]*prefix[i])%m;
    }
    for(int i=suffix.size()-2;i>=0;i--){
        suffix[i] = (suffix[i+1]*suffix[i])%m;
    }

    int cn = 0;
    for(int v : adj[u]){
        if(v != parent){
            ll cval = (1 + pval);
            if(cn > 0) cval = (cval*(prefix[cn-1]))%m;
            if(cn < suffix.size() - 1) cval = (cval*(suffix[cn+1]))%m;
            solve2(adj, n, m, v, u, cval);
            cn++;
        }
    }
}
