      if (suf[v].size() == 0)
        suf[v].PB(1);
      else
        suf[v].PB(suf[v].back());
    }
    else {
      if (suf[v].size() == 0)
        suf[v].PB((1+d[c])%m);
      else
        suf[v].PB((suf[v].back()*(1+d[c]))%m);
    }
