  if (v != 1) {
    int oj = p[v];
    g[v] = 1+g[oj];
    int x1 = 0, x2 = pref[oj].size()-1, x3;
    while (x2-x1 > 1) {
      x3 = (x1+x2)/2;
      if (child[oj][x3] <= v)
        x1 = x3;
      else
        x2 = x3;
    }
    int co = x1;
    if (child[oj][x2] == v)
      co = x2;
    if (co > 0)
      g[v] = (g[v]*pref[oj][co-1])%m;
    if (co+1 < suf[oj].size())
      g[v] = (g[v]*suf[oj][co+1])%m;
  }
  for (int c: child[v])
    if (c != p[v])
      dfs2(c);
}

