		for (size_t j = 0; j < 4; j++)
		{
			for (size_t k = 0; k < 4; k++)
			{
				clc3(a, i, b, j, c, k, d);
			}
		}
	}
}
void clc(ll a, ll b, ll c, ll d) {

	ll t[] = { a,b,c,d };
	do {
		clc2(t[0], t[1], t[2], t[3]);
	} while (next_permutation(t,t+4));
}

double heron(ll a, ll b, ll c) {
	double s = (double)(a + b + c) / 2.0;
	return sqrt(s * (s - a) * (s - b) * (s - c));
}

double calcThreePS(double x1, double y1, double x2, double y2, double x3, double y3) {
	return abs((x1 * y2 + x2 * y3 + x3 * y1 - y1 * x2 - y2 * x3 - y3 * x1) / 2.0);
}
typedef vector<vl> mat;
class Matrix1 {

public:
	static const int M = INF;
	int n;
	mat mul(mat& A, mat& B) {
		mat C(A.size(), vl(B[0].size()));
		for (size_t i = 0; i < A.size(); i++)
		{
			for (size_t k = 0; k < B.size(); k++)
			{
				for (size_t j = 0; j < B[0].size(); j++)
				{
					C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % M;
				}
			}
		}
		return C;
	}

	mat pow(mat A, ll n) {
		mat B(A.size(), vl(A.size()));
		for (size_t i = 0; i < A.size(); i++)
		{
			B[i][i] = 1;
		}
		while (n > 0) {
			if (n & 1) B = mul(B, A);
			A = mul(A, A);
			n >>= 1;
		}


		return B;
	}

};
ll m;
vi es[100010];
vl dp[100010];
ll dfs(int x,int pre) {

	ll res = 1;
	int i = -1;
	dp[x] = vl(es[x].size());
	for (auto v : es[x]) {
		i++;
		if (v == pre) continue;
		dp[x][i] = dfs(v, x) + 1;
		res *= dp[x][i];
		res %= m;
	}

	return res;
}
void dfs2(int x, int pre, ll fv) {

	vector<ll> L(es[x].size());
	for (size_t i = 0; i < es[x].size(); i++)
	{
		if (pre == es[x][i]) {
			dp[x][i] = fv + 1;
		}
		L[i] = dp[x][i];
		if (i > 0)
			L[i] *= L[i - 1];
		L[i] %= m;
	}
	ll r = 1;
	for (int i = es[x].size() - 1; i >= 0 ;i--) {

		if (i < (es[x].size() - 1)) r *= dp[x][i + 1];
		if (es[x][i] == pre) continue;
		ll t = ((i == 0) ? 1LL : L[i - 1]) * r;
		t %= m;
		dfs2(es[x][i], x, t);
	}
}
