using namespace std;

int mod;

int add (int a, int b) {
  return (a + b) % mod;
}
int mul (int a, int b) {
  return (long long) a * b % mod;
}

const int nax = 1e5 + 5;
vector < int > edges[nax], children[nax];
vector < pair < int, int > > downs[nax], pref[nax], suf[nax];
pair < int ,int > down[nax], up[nax];

pair < int ,int > Merge (const pair < int , int >& a, const pair < int , int >& b) {
  pair < int , int > p;
  p.all_white = mul (a.all_white, b.all_white);
  p.sth_is_black = add (mul (a.sth_is_black, add (b.all_white, b.sth_is_black)),
                        mul (a.all_white, b.sth_is_black));
  return p;
}

pair < int , int > process (pair < int , int > p) {
  return {p.all_white, add (p.sth_is_black, p.all_white)};
}

void dfs_one (int a, int parent) {
  pair < int , int > p {1, 0};
  for (int b : edges[a])
    if (b != parent) {
      children[a].push_back (b);
      dfs_one (b, a);
      p = Merge (p, down[b]);
      downs[a].push_back (down[b]);
    }
  down[a] = process(p);
}

void dfs_two (int a, int parent) {
  for (int i = 0; i < (int)children[a].size(); ++i) {
    pair < int ,int > p {1, 0};
    if (i != 0)
      p = Merge (p, pref[a][i - 1]);
    if (i != (int) downs[a].size() - 1)
      p = Merge (p, suf[a][i + 1]);
    if (a != 1)
      p = Merge (p, up[a]);
    int b = children[a][i];
    up[b] = process(p);
    dfs_two(b, a);
  }
}

int main () {
  int n;
  cin >> n >> mod;
  for (int i = 0; i < n - 1; ++i) {
    int a, b;
    cin >> a >> b;
    edges[a].emplace_back (b);
    edges[b].emplace_back (a);
  }
  dfs_one (1, -1);
  for (int a = 1; a <= n; ++a) {
    int k = downs[a].size();
    pair < int , int > p {1, 0};
    for (int i = 0; i < k; ++i) {
      p = Merge (p, downs[a][i]);
      pref[a].push_back (p);
    }
    p = {1, 0};
    for (int i = k - 1; i >= 0; --i) {
      p = Merge (p, downs[a][i]);
      suf[a].push_back (p);
    }
    reverse (suf[a].begin(), suf[a].end());
  }
  dfs_two (1, -1);
  for (int a = 1; a <= n; ++a) {
    pair < int ,int > p {1, 0};
    if (a != 1)
      p = Merge (p, up[a]);
    if (!children[a].empty())
      p = Merge (p, pref[a].back());
    p = process(p);
    cout << p.sth_is_black << '\n';
  }
}

