ll solve(int node, vector<bool>& vis)
{
    ll ans = 1;
    vis[node] = 1;
    for(int child : adj[node])
    {
        if(!vis[child])
        {
            ans = (ans*(1 + solve(child, vis)))%M;
        }
    }
    return dp1[node] = ans%M;
}

void finalSolve(int node, vector<bool>& vis, ll parentAns)
{
    ll ans = 1;
    vis[node] = 1;
    vector<ll> val;

    for(int child : adj[node])
    {
        if(!vis[child])
        {
            ans = (ans*(1+dp1[child]))%M;
            val.push_back(dp1[child]);
        }
    }
    ans = (ans*(1+parentAns))%M;
    dp2[node] = ans%M;
    vector<ll> pre, suf(val.size()+1);
    pre.push_back(1);
    suf[val.size()] = (1+parentAns)%M;
    for(int i=0;i<val.size();i++)
        pre.push_back(1LL*((pre[i])*(1+val[i]))%M);
    for(int i=val.size()-1;i>=0;i--)
        suf[i] = (1LL*(suf[i+1])*(1+val[i]))%M;

    int cno = 0;
    for(int child : adj[node])
    {
        if(!vis[child])
        {
            //assert((pre[cno]*suf[cno]) == ans);
            finalSolve(child, vis, (1LL*pre[cno]*suf[cno+1])%M);
            cno++;
        }
    }

}

