int up[N], down[N];
vector<int> pre[N], suf[N];
int n,m;
vector<int> g[N];
int dfs1(int u, int p){
	int ans1 = 1, ans2 = 1;
	vector<int> t;
	for(auto v:g[u]){
		if(v!=p){
			t.pb(1+dfs1(v,u));
		}
	}
	rep(i,0,sz(t)){
		ans1 = (ans1*t[i])%m;
		pre[u].pb(ans1);
		ans2 = (ans2*t[sz(t)-i-1])%m;
		suf[u].pb(ans2);
	}
	down[u] = ans1;
	return ans1;
}
int vis[N];
int tin[N], tout[N];
int timer = 0;
void dfs(int u, int p){
	tin[u] = ++timer;

	for(auto v:g[u]){
		if(v!=p)
			dfs(v,u);
	}
	tout[u] = ++timer;
}
bool is_ancestor(int par, int child){
	if(par == 0) return true;
	if(child == 0) return false;
	if(tin[par]<=tin[child] and tout[par]>=tout[child]) return true;
	return false;
}

int dfs2(int u, int p){
	if(vis[u]) return up[u];
	// trace(u);
	vis[u] = 1;
	int ans = 1;
	ans = (ans*up[p])%m;
	for(auto v:g[p]) if(v!=u && !is_ancestor(v,p)) ans = (ans*(1+down[v]))%m;
	// trace(u,ans,up[p],p);
	up[u] = 1+ans;
	for(auto v:g[u]) if(v!=p) dfs2(v,u);
	return 1+ans;
}
