int n, modulo;
struct SegmentTree{
    struct node{
        node *l = nullptr;
        node *r = nullptr;
        ll val = 1;
        node(){}
    };
    node *root = new node();

    void update(node *cur,int l,int r,int p,int val){
        if(l==r){
            cur->val = val;
        }
        else{
            int m = (l+r)/2;
            if(p<=m){
                if(!cur->l){
                    cur->l = new node();
                }
                update(cur->l,l,m,p,val);
                cur->val = cur->l->val;
                if(cur->r) cur->val *= cur->r->val;
            }
            else{
                if(!cur->r){
                    cur->r = new node();
                }
                update(cur->r,m+1,r,p,val);
                cur->val = cur->r->val;
                if(cur->l) cur->val *= cur->l->val;
            }
        }
        cur->val %= modulo;
    }
    ll query(node *cur,int l,int r,int a,int b){
        if(!cur or r < a or l > b or a > b) return 1;
        if(l>=a && r<=b){
            return cur->val;
        }
        int m = (l+r)/2;
        return query(cur->l,l,m,a,b) * query(cur->r,m+1,r,a,b) % modulo;
    }   
};
vector<int> adj[200200];
vector<ll> ways(200200), dp(200200);
SegmentTree tree[200200];
void dfs(int u,int p){
	ways[u] = 1;
	for(int i=0;i<adj[u].size();i++){
		int v = adj[u][i];
		if(v!=p){
			dfs(v, u);
			tree[u].update(tree[u].root, 0, 200200, i, ways[v] + 1);
			ways[u] *= (ways[v] + 1);
			ways[u] %= modulo;
		}
	}
}
void go(int u,int p){
	//dp[u] = (dp[p] / (ways[u]+1) + 1) * ways[u];
	for(int i=0;i<adj[u].size();i++){
		int v = adj[u][i];
		if(v!=p){
			//dp[v] = dp[u] / (ways[u] + 1) + 1
			dp[v] = (tree[u].query(tree[u].root, 0, 200200, 0, i-1) * tree[u].query(tree[u].root, 0, 200200, i+1, adj[u].size()) + 1) % modulo;
			tree[v].update(tree[v].root, 0, 200200, adj[v].size(), dp[v]);
			dp[v] = dp[v] * ways[v] % modulo;
			go(v, u);
		}
	}
}
