int MOD;
const int MAXN = 100000;
ll dp[MAXN + 5]; // dp[i] = # of ways to color i's subtree black
ll res[MAXN + 5];

auto mult(auto a, auto b){return (a * b) % MOD;}

void dfs(graph &g, int i, int p = -1) {
  dp[i] = 1;
  trav(e, g[i]) if (e.to != p) {
    dfs(g, e.to, i);
    dp[i] = mult(dp[i], 1 + dp[e.to]);
  }
}

void calc(graph& g, int i, ll above = 1, int p = -1) {
  res[i] = mult(dp[i], above);
  vector<ll> pref_mult, suff_mult;
  rep(k, 0, sz(g[i])) {
    int to = g[i][k].to;
    if (to == p) continue;
    auto contrib = (1 + dp[to]) % MOD;
    pref_mult.PB(!pref_mult.empty() ? mult(pref_mult.back(), contrib) : contrib);
  }
  for (auto k = sz(g[i]) - 1; k >= 0; k--){
    int to = g[i][k].to;
    if (to == p) continue;
    auto contrib = (1 + dp[to]) % MOD;
    suff_mult.PB(!suff_mult.empty() ? mult(suff_mult.back(), contrib) : contrib);
  }
  reverse(all(suff_mult));
  /*
  cout << "At: " << i << " Above: " << above << endl;
  cout << "PRef: " << endl;
  trav(elem, pref_mult) {
    cout << elem << " "; 
  } cout << endl;
  cout << "Suff: " << endl;
  trav(elem, suff_mult)  cout << elem << " ";
  cout << endl;
  */
  int iter = 0;
  trav(e, g[i]) if (e.to != p) {
    auto before = iter ? pref_mult[iter - 1] : 1LL;
    auto after = iter + 1 < sz(suff_mult) ? suff_mult[iter + 1] : 1LL;
    auto exclude_this_subtree = mult(before, after);
    auto nabove = 1 + mult(above, exclude_this_subtree);
    //cout << "Looking at child: " << e.to << " on iter: " << iter << endl;
    //cout << "Before: " << before << " after: " << after << endl;
    calc(g, e.to, nabove, i);
    iter++;
  }
}

