const ll INF = 5e15;
const ll MOD = 1e9 + 7;

ll N, M;
vector<vector<ll>> edges(1e5 + 10);
vector<ll> dp(1e5 * 2 + 10);
map<P, ll> ID;

ll dfs1(ll now, ll pre){
    ll ret = 1;
    for(ll nxt : edges[now]){
        if(nxt == pre) continue;
        ret *= (dfs1(nxt, now) + 1);
        ret %= M;
    }
    return dp[ID[P(pre, now)]] = ret;
}

void dfs2(ll now, ll pre){
    ll ret = 1;
    vector<ll> multi(edges[now].size() + 1, 1);
    vector<ll> multir(edges[now].size() + 1, 1);
    for(ll i = 0; i < edges[now].size(); i++){
        ll nxt = edges[now][i];
        ll id = ID[P(now, nxt)];
        multi[i + 1] = multi[i] * (dp[id] + 1) % M;
    }
    for(ll i = edges[now].size(); i > 0; i--){
        ll nxt = edges[now][i - 1];
        ll id = ID[P(now, nxt)];
        multir[i - 1] = multir[i] * (dp[id] + 1) % M;
    }
    for(ll i = 0; i < edges[now].size(); i++){
        ll nxt = edges[now][i];
        if(nxt == pre) continue;
        ll id = ID[P(nxt, now)];
        dp[id] = multi[i] * multir[i + 1] % M;
    }
    for(ll nxt : edges[now]) if(nxt != pre) dfs2(nxt, now);
}

void dfs(){
    for(ll nxt : edges[0]) dfs1(nxt, 0);
    dfs2(0, -1);
}

