void dfs(ll v,ll p)
{
    f[v]=1;
    vector<int> pre,suf;
    for(auto to:G[v])
    {
        if(to==p) continue;
        dfs(to,v);
        f[v]=1LL*f[v]*(f[to]+1)%M;
    }
    pre.clear();suf.clear();
    for(auto to:G[v])
    {
        if(to==p) continue;
        pre.push_back(f[to]+1); suf.push_back(f[to]+1);
    }
    ll sz=(int)pre.size();
