using namespace std;
typedef long long ll;

const int MAXN = 100055;

ll dp[MAXN], du[MAXN], dl[MAXN], dr[MAXN];
int prt[MAXN];

vector<int> G[MAXN];

int N, MOD;

void f(int i) {
	if(prt[i]) G[i].erase(find(allv(G[i]), prt[i]));
	dp[i] = 1;
	for(int j = 0, n = sz(G[i]), v; j < n; j++) {
		v = G[i][j];
		prt[v] = i;
		f(v);
		dl[v] = (dp[v] + 1) % MOD;
		if(j) dl[v] = dl[v] * dl[G[i][j-1]] % MOD;
	}
	for(int n = sz(G[i]), j = n, v; j--;) {
		v = G[i][j];
		dr[v] = (dp[v] + 1) % MOD;
		if(j+1 < n) dr[v] = dr[v] * dr[G[i][j+1]] % MOD;
	}
	if(!G[i].empty()) dp[i] = dl[G[i].back()];
}

void g(int i) {
	for(int j = 0, n = sz(G[i]), v; j < n; j++) {
		v = G[i][j];
		du[v] = du[i];
		if(j) du[v] = du[v] * dl[G[i][j-1]] % MOD;
		if(j+1 < n) du[v] = du[v] * dr[G[i][j+1]] % MOD;
		du[v] = (du[v] + 1) % MOD;
		g(v);
	}
}

