vector<unordered_map<int, int>> dp;

int dfs(int node, int parent) {
    if (dp[node].find(parent) != dp[node].end()) {
        return dp[node][parent];
    } else {
        long long cnt = 1;
        for (auto child : graph[node]) {
            if (child != parent) {
                cnt *= dfs(child, node) + 1;
                cnt %= m;
            }
        }

        dp[node][parent] = cnt;
        return cnt;
    }
}

