void precalc(ll v, ll p){
    wh[v] = 1;
    bl[v] = 1;
    for(auto u : g[v]){
        if(u == p)
            continue;
        precalc(u, v);
        bl[v] *= (bl[u]+wh[u])%m;
        bl[v] %= m;

        wh[v] *= wh[u];
        wh[u] %= m;
    }
}
void calc(ll v, ll p){
    ans[v] = bl[v];
    vector<ll> vecwh;
    vector<ll> vecbl;
    ll cur = 0;
    for(auto u : g[v]){
        vecwh.pb(wh[u]);
        vecbl.pb((bl[u]+wh[u])%m);
        ++cur;
    }
    for(int i = vecwh.size()-2; i >= 0; --i){
        vecwh[i] = vecwh[i]*vecwh[i+1]%m;
        vecbl[i] = vecbl[i]*vecbl[i+1]%m;
    }
    ll befwh = 1;
    ll befbl = 1;
    cur = 0;
    for(auto u : g[v]){
        ++cur;
        if(u == p){
            befbl = befbl*((bl[u]+wh[u])%m)%m;
            befwh = befwh*wh[u]%m;
            continue;
        }
        ll oldblv = bl[v];
        ll oldwhv = wh[v];
        ll oldblu = bl[u];
        ll oldwhu = wh[u];

        bl[v] = befbl;
        wh[v] = befwh;
        if(cur < vecwh.size()){
            bl[v] = bl[v]*vecbl[cur]%m;
            wh[v] = wh[v]*vecwh[cur]%m;
        }
        //cout << u << " " << v <<" " << bl[v] << " " << wh[v] << "\n";
        wh[u] = wh[u]*wh[v]%m;
        bl[u] = bl[u]*((bl[v]+wh[v])%m)%m;
        calc(u, v);
        bl[v] = oldblv;
        wh[v] = oldwhv;
        bl[u] = oldblu;
        wh[u] = oldwhu;
        befbl = befbl*((bl[u]+wh[u])%m)%m;
        befwh = befwh*wh[u]%m;
    }
}
