ll mod;
struct mint {
  ll x; // typedef long long ll;
  mint(ll x=0):x((x%mod+mod)%mod){}
  mint operator-() const { return mint(-x);}
  mint& operator+=(const mint a) {
    if ((x += a.x) >= mod) x -= mod;
    return *this;
  }
  mint& operator-=(const mint a) {
    if ((x += mod-a.x) >= mod) x -= mod;
    return *this;
  }
  mint& operator*=(const mint a) { (x *= a.x) %= mod; return *this;}
  mint operator+(const mint a) const { return mint(*this) += a;}
  mint operator-(const mint a) const { return mint(*this) -= a;}
  mint operator*(const mint a) const { return mint(*this) *= a;}
  mint pow(ll t) const {
    if (!t) return 1;
    mint a = pow(t>>1);
    a *= a;
    if (t&1) a *= *this;
    return a;
  }

  // for prime mod
  mint inv() const { return pow(mod-2);}
  mint& operator/=(const mint a) { return *this *= a.inv();}
  mint operator/(const mint a) const { return mint(*this) /= a;}
};
istream& operator>>(istream& is, const mint& a) { return is >> a.x;}
ostream& operator<<(ostream& os, const mint& a) { return os << a.x;}

int mainsolve(){

	ll n,m;
	cin >> n >> m;
	mod = m;

	vector<vector<ll>> to(n);

	rep(i,n-1){
		ll x,y;
		cin >> x >> y;
		--x; --y;
		to[x].push_back(y);
		to[y].push_back(x);
	}

	vector<vector<mint>> dp(n); // 要素数 2(n-1)
	rep(i,n) dp[i] = vector<mint>(to[i].size()); // vの子から始まる部分木（vの子自身を含む）

	// まず普通にdfsして子方向へのdpを埋める
	function<mint(ll,ll)> dfs = [&](ll v, ll p){
		mint res = 1;
		rep(i,to[v].size()){
			ll u = to[v][i];
			if(u != p){
				dp[v][i] = dfs(u,v); // uがrootである部分木
				res *= dp[v][i] + 1;
			}
		}
		return res;
	};
	dfs(0,-1);

	vector<mint> ans(n);
	function<void(ll,ll,mint)> dfs2 = [&](ll v, ll p, mint dpP){

		ll deg = to[v].size();
  		rep(i,deg) if (to[v][i] == p) dp[v][i] = dpP;

		vector<mint> dpLeft(deg+1,1), dpRight(deg+1,1);
		rep(i,deg) dpLeft[i+1] = dpLeft[i] * (dp[v][i] + 1);
		for (int i = deg-1; i >= 0; --i) dpRight[i] = dpRight[i+1] * (dp[v][i] + 1);

		ans[v] = dpLeft[deg];

		rep(i,deg){
			ll u = to[v][i];
			if(u == p) continue;
			dfs2(u, v, dpLeft[i] * dpRight[i+1]);
		}
	};	
	dfs2(0,-1,1);

	rep(i,n) cout << ans[i] << endl;
	return 0;
}

