  for(int i=(int)childs[u].size()-1 ; i>=0 ; i--)
    suffix[u][i] = res = (res + res*childs[u][i]%m)%m;

  return ans[u] = res;
}
void calc(int u, int p){

  int idx = lower_bound(all(adjList[p]), u) - adjList[p].begin();

  int left  = idx==0 ? 1 : prefix[p][idx-1];
  int right = idx==suffix[p].size()-1 ? 1 : suffix[p][idx+1];

  par[u] = left*right%m;
  par[u] = (par[u] + par[u]*par[p]%m)%m;

  ans[u] = (ans[u] + ans[u]*par[u]%m)%m;

  for(auto v:adjList[u])
    if(v!=p)
      calc(v, u);
}
