ll bp(ll a, ll b){
    ll res = 1;
    while(b){
        if(b % 2) res = (res * a) % mod;
        a = (a * a) %mod;
        b = b / 2;
    }
    return res;
}


void dfs1(int a, int par){
    d[a] = 1;
    if(adj[a].size() == 1 && par != -1){
        return;
    }
    for(int i: adj[a]){
        if(i != par){
            dfs1(i, a);
            d[a] *= (d[i] + 1);
            d[a] %= mod;
        }
    }
}

void dfs2(int a, int par, ll pard){
    ans[a] = 1;
    for(int i: adj[a]){
        if(i != par)
            ans[a] *= (d[i] + 1);
        ans[a] %= mod;
    }
    ans[a] *= (pard + 1);
    ans[a] %= mod;
    for(int i: adj[a]){
        if(i == par) continue;
        ll pardi = 1;
        for(int k: adj[a]){
            if(k == par || k == i) continue;
            pardi *= d[k] + 1;
            pardi %= mod;
        }
        pardi *= pard + 1;
        pardi %= mod;
        dfs2(i, a, pardi);
    }
}

