void dfs2(int node, int p)
{
    ans[node] = dp[node];

    coef[node] = 1;
    if (p != -1)
    {
        coef[node] = coef[p];
        for (auto& ch : children[p])
        {
            if (ch == node)
                continue;
            coef[node] *= (dp[ch] + 1);
            coef[node] %= m;
        }
        coef[node] += 1;
        coef[node] %= m;
    }
    ans[node] *= coef[node];
    ans[node] %= m;

    for (auto& v : adj[node])
    {
        if (v == p)
            continue;
        dfs2(v, node);
    }
}

