        cin >> x >> y;
        x--; y--;
        adj[x].push_back(y);
        adj[y].push_back(x);
    }
    dfs(0, -1);
    dfs2(0, -1);
    for (int i = 0; i < n; i++)
        cout << ans[i] << endl;
}

