	ll sz=G[i].size();
	for(ll j=0;j<sz;++j)
	{
		pprod=(pprod*(B[G[i][j]]+1))%mod;
		sprod=(sprod*(B[G[i][sz-1-j]]+1))%mod;
		pref.pb(pprod);
		suff.pb(sprod);
	}
	reverse(suff.begin(),suff.end());
	for(ll j=0;j<sz;++j)
	{
		if(G[i][j]!=par)
		{
			ll t1=B[i],t2=B[G[i][j]];
			if(j==0 && j==sz-1)
			{
				B[i]=1;
			}
			else if(j==0)
			{
				B[i]=suff[j+1];
			}
			else if(j==sz-1)
			{
				B[i]=pref[j-1];
			}
			else
			{
				B[i]=(pref[j-1]*suff[j+1])%mod;
			}
			B[G[i][j]]=(B[G[i][j]]*(B[i]+1))%mod;
			ans[G[i][j]]=B[G[i][j]];
			rerooting(G[i][j],i);
			B[i]=t1;
			B[G[i][j]]=t2;
		}
	}
}
void solve()
{
	cin>>n>>mod;
	for(ll i=1;i<=n-1;++i)
	{
		ll u,v;
		cin>>u>>v;
		u--;
		v--;
		G[u].pb(v);
		G[v].pb(u);
	}
	dfs(0,0);
	ans[0]=B[0];
	rerooting(0,0);
	print1D(ans,n);
}
int main()
{
	ios_base::sync_with_stdio(false),cin.tie(NULL),cout.tie(NULL);
	ll t=1;
	// cin>>t;
	while(t--)
	{
		solve();
	}
}

