void dfs1(int idx,int par)
{
	int res=1;
	int cnt=0;
	vector<int> sv;
	for(auto e:G[idx])
	{
		if(e==par)continue;
		dfs1(e,idx);
		VI[idx][e]=cnt;
		sv.push_back(e);
		res*=(DP[e]+1);
		res%=MOD;
		cnt++;
	}
	DP[idx]=res;
	vector<int> LV(SZ(sv),1),RV(SZ(sv),1);
	rep(i,0,SZ(sv))
	{
		LV[i]=(LV[i]*(DP[sv[i]]+1))%MOD;
		if(0<i)LV[i]=(LV[i]*LV[i-1])%MOD;
	}
	rrep(i,0,SZ(sv))
	{
		RV[i]=(RV[i]*(DP[sv[i]]+1))%MOD;
		if(i<SZ(sv)-1)RV[i]=(RV[i]*RV[i+1])%MOD;
	}
	rep(i,0,SZ(sv))
	{
		int t=1;
		if(0<i)t=(t*LV[i-1])%MOD;
		if(i<SZ(sv)-1)t=(t*RV[i+1])%MOD;
		SDP[idx].push_back(t);
	}
}

void dfs2(int idx,int par)
{
	if(par!=-1)
	{
		DP[idx]=(DP[idx]*(SDP[par][VI[par][idx]]+1))%MOD;
		for(auto& v:SDP[idx])
		{
			v=(v*(SDP[par][VI[par][idx]]+1))%MOD;
		}
	}
	for(auto e:G[idx])
	{
		if(e==par)continue;
		dfs2(e,idx);
	}
}

