int dfs(vector< vector<int> > &G, vector<int> &C, int v, int p, int M){
    int ret = 1;
    for(size_t i = 0; i < G[v].size(); ++i){
        int v_ = G[v][i];
        if(v_ == p) continue;
        ret *= dfs(G,C,v_,v,M) + 1;
        ret %= M;
    }
    C[v] = ret;
    return ret;
}

