ll dp2[100010];//dp2[i]=iを根としたとき、サイズが1小さい部分木であって0を含むものに対する塗り方
int flag[100010];

ll calc(int k){
	ll ans=1;
	//塗り方はΠ(dp1[*]+1)通り(+1は塗らない分)
	rep(i,g.id[k],g.id[k+1])if(g.e[i].g!=root[k]){
		ans=ans*(calc(g.e[i].g)+1)%MOD;
	}
	return dp1[k]=ans;
}

ll sub(int v,int k){
	//自分の親vについて、自分を除くΠ(dp*[*]+1)を求める
	if(flag[k])return dp2[k];
	flag[k]=1;
	ll ans=1;
	rep(i,g.id[v],g.id[v+1]){
		if(g.e[i].g==root[v]){
			ans=ans*(sub(root[v],v)+1)%MOD;
		}else if(g.e[i].g!=k){
			ans=ans*(dp1[g.e[i].g]+1)%MOD;
		}
	}
	return dp2[k]=ans;
}


ll calc2(int k){
	//dp2[k]を求める
	//答えはこれのdp1[k]倍
	return dp1[k]*(sub(root[k],k)+1)%MOD;
}

