#include<stdio.h>
#include<stdlib.h>
#include<stdint.h>
#include<inttypes.h>

typedef struct directed_edge {
  int32_t vertex;
  int32_t next;
} graph_edge;

typedef struct directedGraph {
  graph_edge *edge;
  int32_t *start;
  int32_t pointer;
  int32_t vertex_num;
  int32_t edge_max_size;
} graph;

graph* new_graph (const int vertex_num) {
  graph *g = (graph *) calloc (1, sizeof (graph));
  g->edge = (graph_edge *) calloc (1, sizeof (graph_edge));
  g->start = (int32_t *) calloc (vertex_num, sizeof (int32_t));
  g->pointer = 0;
  g->vertex_num = vertex_num;
  g->edge_max_size = 1;
  for (int32_t i = 0; i < vertex_num; ++i) {
    g->start[i] = -1;
  }
  return g;
}

void add_edge (graph *g, int32_t from, int32_t to) {
  if (g->pointer == g->edge_max_size) {
    g->edge_max_size *= 2;
    g->edge = (graph_edge *) realloc (g->edge, sizeof (graph_edge) * g->edge_max_size);
  }
  g->edge[g->pointer] = (graph_edge) {to, g->start[from]};
  g->start[from] = g->pointer++;
}

typedef int32_t i32;
typedef int64_t i64;

i32 topological_sort (graph *g, i32 src, i32 *q, i32 *parent) {
  i32 front = 0, last = 0;
  q[last++] = src;
  parent[src] = -1;
  while (front < last) {
    const i32 v = q[front++];
    for (i32 p = g->start[v]; p != -1; p = g->edge[p].next) {
      const i32 u = g->edge[p].vertex;
      if (u == parent[v]) continue;
      q[last++] = u;
      parent[u] = v;
    }
  }
  return last;
}

void run (void) {
  i32 n, mod;
  scanf ("%" SCNi32 "%" SCNi32, &n, &mod);
  graph *g = new_graph (n);
  for (i32 i = 1;i < n; ++i) {
    i32 x, y;
    scanf ("%" SCNi32 "%" SCNi32, &x, &y);
    x--;
    y--;
    add_edge (g, x, y);
    add_edge (g, y, x);
  }
  i32 *q = (i32 *) calloc (5 * n, sizeof (i32));
  i32 *parent = q + n;
  topological_sort (g, 0, q, parent);
  i32 *dp1 = parent + n;
  for (i32 i = n - 1; i >= 0; --i) {
    const i32 v = q[i];
    i32 local = 1;
    for (i32 p = g->start[v]; p != -1; p = g->edge[p].next) {
      const i32 u = g->edge[p].vertex;
      if (u == parent[v]) continue;
      local = (i64) local * dp1[u] % mod;
    }
    dp1[v] = (local + 1) % mod;
  }
  i32 *dp2 = dp1 + n;
  i32 *acc = dp2 + n;
  dp2[0] = 1;
  for (i32 i = 0; i < n; ++i) {
    const i32 v = q[i];
    i32 len = 0;
    for (i32 p = g->start[v]; p != -1; p = g->edge[p].next) {
      const i32 u = g->edge[p].vertex;
      if (u == parent[v]) continue;
      acc[len++] = dp1[u];
    }
    acc[len] = dp2[v];
    for (i32 i = len - 1; i >= 0; --i) {
      acc[i] = (i64) acc[i] * acc[i + 1] % mod;
    }
    for (i32 p = g->start[v], j = 1, mul = 1; p != -1; p = g->edge[p].next, ++j) {
      const i32 u = g->edge[p].vertex;
      if (u == parent[v]) continue;
      dp2[u] = ((i64) mul * acc[j] + 1) % mod;
      mul = (i64) mul * dp1[u] % mod;
    }
  }
  for (i32 i = 0; i < n; ++i) {
    i32 ans = (i64) (dp1[i] + mod - 1) * dp2[i] % mod;
    printf ("%" PRIi32 "\n", ans);
  }
}

int main (void) {
  run();
  return 0;
}

