} list;

int main()
{
	int i, N, M, u, w;
	list *adj[100001] = {}, e[200001], *p;
	scanf("%d %d", &N, &M);
	for (i = 0; i < N - 1; i++) {
		scanf("%d %d", &u, &w);
		e[i*2].v = w;
		e[i*2+1].v = u;
		e[i*2].num = -1;
		e[i*2+1].num = -1;
		e[i*2].next = adj[u];
		e[i*2+1].next = adj[w];
		adj[u] = &(e[i*2]);
		adj[w] = &(e[i*2+1]);
	}

	int par[100001] = {}, q[100001], head, tail;
	long long ans, dp[100001] = {};
	for (i = 1; i <= N; i++) {
		ans = 1;
		q[0] = i;
		par[i] = i;
		for (head = 0, tail = 1; head < tail; head++) {
			u = q[head];
			for (p = adj[u]; p != NULL; p = p->next) {
				if (p->num == -1 && par[p->v] == 0) {
					par[p->v] = u;
					q[tail++] = p->v;
				}
			}
		}
		for (head--; head >= 0; head--) {
			u = q[head];
			dp[u] = 1;
			for (p = adj[u]; p != NULL; p = p->next) {
				if (p->v == par[u]) continue;
				else {
					if (p->num == -1) p->num = dp[p->v];
					dp[u] = dp[u] * (p->num + 1) % M;
				}
			}
		}

		printf("%lld\n", dp[i]);
		for (head++; head < tail; head++) {
			u = q[head];
			par[u] = 0;
			dp[u] = 0;
		}
	}

	fflush(stdout);
	return 0;
}

