typedef struct {
	int t, h;
	long long num;
} edge;

int main()
{
	int i, N, M, u, w, *adj[100001], deg[100001] = {}, q[100001] = {};
	long long *block[100001] = {};
	edge e[200001];
	scanf("%d %d", &N, &M);
	for (i = 0; i < N - 1; i++) {
		scanf("%d %d", &u, &w);
		e[i*2].t = u;
		e[i*2].h = w;
		e[i*2+1].t = w;
		e[i*2+1].h = u;
		e[i*2].num = -1;
		e[i*2+1].num = -1;
		deg[u]++;
		deg[w]++;
	}
	for (i = 1; i <= N; i++) {
		adj[i] = (int*)malloc(sizeof(int) * deg[i]);
		if (deg[i] > SIZE) block[i] = (long long*)malloc(sizeof(long long) * ((deg[i] + SIZE - 1) / SIZE));
	}
	for (i = 0; i < N - 1; i++) {
		u = e[i*2].t;
		w = e[i*2].h;
		adj[u][q[u]++] = i * 2;
		adj[w][q[w]++] = i * 2 + 1;
	}

	int par[100001] = {}, head, tail;
	long long dp[100001] = {};
	par[1] = 1;
	q[0] = 1;
	for (head = 0, tail = 1; head < tail; head++) {
		u = q[head];
		for (i = 0; i < deg[u]; i++) {
			w = e[adj[u][i]].h;
			if (par[w] == 0) {
				par[w] = u;
				q[tail++] = w;
			}
		}
	}
	for (head--; head >= 0; head--) {
		u = q[head];
		dp[u] = 1;
		for (i = 0; i < deg[u]; i++) {
			w = e[adj[u][i]].h;
