ll MOD;

//辺の情報を個別に持つタイプ
typedef struct edge{ll s,g;}E;
typedef struct graph{
	ll vcnt,ecnt;
	E  e[200010];//適宜変える
	ll id[100010];//適宜変える
}G;
G g;

int esort(const void*a,const void*b){
	E*p=(E*)a,*q=(E*)b;
	if((*p).s<(*q).s)return -1;
	if((*p).s>(*q).s)return  1;
	if((*p).g<(*q).g)return -1;
	return 1;
}

ll root[100010];
int st[100010],ptr;
void dfs(int k){
	st[ptr++]=k;
	rep(i,g.id[k],g.id[k+1])if(g.e[i].g!=root[k]){
		root[g.e[i].g]=k;
		dfs(g.e[i].g);
	}
}

void readgraph(){
	//適宜変える
	ll n;
	scanf("%lld%lld",&n,&MOD);
	rep(i,0,n-1){
		ll x,y;
		scanf("%lld%lld",&x,&y);
		x--,y--;
		g.e[2*i].s=x;
		g.e[2*i].g=y;
		g.e[2*i+1].s=y;
		g.e[2*i+1].g=x;
	}
	g.vcnt=n;
	g.ecnt=2*n-2;
	qsort(g.e,g.ecnt,sizeof(E),esort);

	int p=0;
	rep(i,0,g.vcnt){
		while(p<g.ecnt&&g.e[p].s<i)p++;
		g.id[i]=p;
	}
	g.id[g.vcnt]=g.ecnt;//一応番兵
	dfs(0);
}

ll dp1[100010];//dp1[i]=0を根とする根付き木とみて、頂点iを黒く塗るときの部分木の塗り方
ll dp2[100010];//dp2[i]=iを根として黒くしたとき、サイズが1小さい部分木であって0を含むものに対する塗り方

ll calc(int k){
	ll ans=1;
	//塗り方はΠ(dp1[*]+1)通り(+1は塗らない分)
	rep(i,g.id[k],g.id[k+1])if(g.e[i].g!=root[k]){
		ans=ans*(calc(g.e[i].g)+1)%MOD;
	}
	return dp1[k]=ans;
}

void f(int l,int r,ll s,int v){
	if(r-l==1){
		if(g.e[l].g==root[v])return;
		dp2[g.e[l].g]=s;
		return;
	}
	int m=(l+r)/2;
	ll temp=1;
	rep(i,l,m){
		if(g.e[i].g==root[v])temp=temp*(dp2[v]+1)%MOD;
		else temp=temp*(dp1[g.e[i].g]+1)%MOD;
	}
	f(m,r,s*temp%MOD,v);

	temp=1;
	rep(i,m,r){
		if(g.e[i].g==root[v])temp=temp*(dp2[v]+1)%MOD;
		else temp=temp*(dp1[g.e[i].g]+1)%MOD;
	}
	f(l,m,s*temp%MOD,v);
}

void calc2(int v){
	//dp2[*]を求める
	//vの子kについて、dp2[k]=Π(dp*[*]+1)である(積はkを除くvとつながってるやつ)
	//再帰的にえいえいするとO(NlogN)とかになりそう？なって
	ll l=g.id[v],r=g.id[v+1];
	if(l==r)return;
	f(l,r,1,v);
}


int main(){
	readgraph();
	printf("%lld\n",calc(0));
	rep(i,0,g.vcnt)calc2(st[i]);
	rep(i,1,g.vcnt)printf("%lld\n",dp1[i]*(dp2[i]+1)%MOD);
	return 0;
}

