void coordinate_comp(int a[],int n){
  int i,c=0;
  sd dat[524288];
  for(i=0;i<n;i++){
    dat[i].val=a[i];
    dat[i].node=i;
  }
  qsort(dat,n,sizeof(dat[0]),sdsortfnc);
  a[dat[0].node]=c;
  for(i=1;i<n;i++){
    if(dat[i-1].val!=dat[i].val){c++;}
    a[dat[i].node]=c;
  }
}

typedef struct{
    long long st;
    long long fi;
    long long kr;
    long long id;
    long long rev;
}rs;

typedef struct{
    long long st;
    long long kz;
}mkj;

int sortfnc(const void *a,const void *b){
if(((rs*)a)->st > ((rs*)b)->st){return 1;}
if(((rs*)a)->st < ((rs*)b)->st){return -1;}
if(((rs*)a)->fi > ((rs*)b)->fi){return 1;}
if(((rs*)a)->fi < ((rs*)b)->fi){return -1;}
return 0;
}

int revsortfnc(const void *a,const void *b){
long long p,q,r,s,t;
p=((rs*)a)->st;
q=((rs*)a)->fi;
r=((rs*)b)->st;
s=((rs*)b)->fi;
if(p>q){t=p;p=q;q=t;}
if(r>s){t=r;r=s;s=t;}
if(p<r){return -1;}
if(p>r){return 1;}
if(q<s){return -1;}
if(q>s){return 1;}
return 0;
}

void makemkj(rs g[],mkj x[],long long n){
    long long i,ms=0,nst=g[0].st;
    for(i=1;i<n;i++){
        if(g[i].st!=g[i-1].st){
            x[nst].kz=i-ms;
            x[nst].st=ms;
            nst=g[i].st;ms=i;
        }
    }
    x[nst].kz=n-ms;
    x[nst].st=ms;
}

long long inmod;

long long calcfl[524288]={0};
long long credef[524288]={0};
long long dp[524288];
long long sta[524288];
long long bksta[524288];

//repdp(v,-1,g,x) := pattern(v is a painted node)
long long repdp(long long v,long long bk,rs g[],mkj x[]){
  //printf("(%lld %lld)\n",v,bk);
  long long i,p,nr=1,ne,nrev,mem;

  //DP getsubtree
  for(i=x[v].st;i<x[v].st+x[v].kz;i++){
    if(g[i].fi==bk){mem=g[i].id;continue;}
    p=i-x[v].st;
    ne=g[i].rev;
    if(calcfl[ne]==0){
      repdp(g[i].fi,v,g,x);
    }
    if(bk==-1){
      sta[p]=(dp[ne]+1)%inmod;
      bksta[p]=(dp[ne]+1)%inmod;
    }
    nr*=(dp[ne]+1);nr%=inmod;
  }

  //DP spread
  if(bk!=-1){
    dp[mem]=nr;
    calcfl[mem]=1;
    credef[mem]++;
    if(credef[mem]>2){assert(false);}
    //printf("%lld -> %lld : %lld\n",g[mem].st,g[mem].fi,dp[mem]);
  }
  else{
    for(i=1;i<x[v].kz;i++){
      sta[i]*=sta[i-1];
      sta[i]%=inmod;
    }
    for(i=x[v].kz-2;i>=0;i--){
      bksta[i]*=bksta[i+1];
      bksta[i]%=inmod;
    }
    for(i=x[v].st;i<x[v].st+x[v].kz;i++){
      p=i-x[v].st;
      ne=g[i].id;
      dp[ne]=1;
      if(p!=0){dp[ne]*=sta[p-1];dp[ne]%=inmod;}
      if(p!=x[v].kz-1){dp[ne]*=bksta[p+1];dp[ne]%=inmod;}
      calcfl[ne]=1;
      credef[ne]++;
      if(credef[ne]>2){assert(false);}
      //printf("%lld -> %lld : %lld\n",g[ne].st,g[ne].fi,dp[ne]);
    }
  }

  return nr;
}

int main(void){
  long long i,j,n,m,k,a,b,c,h,w,r=0,l,t,cnt=0;
  rs g[524288];
  mkj x[524288];
  scanf("%lld%lld",&n,&inmod);
  for(i=0;i<(n-1);i++){
    scanf("%lld%lld",&g[cnt].st,&g[cnt].fi);
    g[cnt].kr=1;
    cnt++;
    g[cnt]=g[cnt-1];
    llswap(&g[cnt].st,&g[cnt].fi);
    cnt++;
  }
  qsort(g,cnt,sizeof(g[0]),sortfnc);
  for(i=0;i<cnt;i++){
    g[i].id=i;
  }
  qsort(g,cnt,sizeof(g[0]),revsortfnc);
  for(i=0;i<cnt;i+=2){
    g[i].rev=g[i+1].id;
    g[i+1].rev=g[i].id;
  }
  qsort(g,cnt,sizeof(g[0]),sortfnc);
  makemkj(g,x,cnt);

  for(i=1;i<=n;i++){
    printf("%lld\n",repdp(i,-1,g,x));
  }
  return 0;
}

