        void dfs(int x, int pi) {
            long prod = 1;
            int ch = 0;
            for (int y : G.get(x)) {
                if (y == pi) continue;
                dfs(y, x);
                ch++;
                prod = (prod * (1 + dp[y])) % mod;
            }
            dp[x] = prod;
        }

        long[] ans;

        void soln(int x, int pi, long top) {
            debug(x, " : ", pi, ", top = ", top);
            long prod = 1 + top;

            ArrayList<Integer> adj = G.get(x);
            adj.remove(Integer.valueOf(pi));

            long[] part = new long[adj.size() + 1];
            part[0] = prod;

            for (int j = 0; j < adj.size(); j++) {
                int y = adj.get(j);
                if (y == pi) continue;
                prod = (prod * (1 + dp[y])) % mod;
                part[j + 1] = prod;
            }

            debug(x, " :adj ", adj);
            debug(x, " :part ", a2s(part));

            ans[x] = prod;

            prod = 1l;

            for (int j = adj.size() - 1; j >= 0; j--) {
                int y = adj.get(j);
                if (y == pi) continue;
                long cur = (prod * part[j]) % mod;
                soln(y, x, cur);
                prod = (prod * (1 + dp[y])) % mod;
            }
