public class Main{
	static ArrayList<Integer>[] edge;
	static long[][] dp;
	static int m;
	static ArrayList<Long>[] fcum;
	static ArrayList<Long>[] bcum;
	static long[] ans;
	public static void main(String[] args){
		Scanner sc=new Scanner(System.in);
		int n=sc.nextInt();
		m=sc.nextInt();
		//0が白、１が黒
		dp=new long[n][2];
		edge=new ArrayList[n];
		fcum=new ArrayList[n];
		bcum=new ArrayList[n];
		for(int i=0; i<n; i++){
			dp[i][0]=dp[i][1]=1;
			bcum[i]=new ArrayList<>();
			edge[i]=new ArrayList<>();
			fcum[i]=new ArrayList<>();
		}
		for(int i=1; i<n; i++){
			int x=sc.nextInt()-1;
			int y=sc.nextInt()-1;
			edge[x].add(y);
			edge[y].add(x);
		}
		dfs1(0,0);
		ans=new long[n];
		ans[0]=dp[0][1];
		dfs2(0,0,1);
		PrintWriter pw=new PrintWriter(System.out);
		for(int i=0; i<n; i++){
			pw.println(ans[i]);
		}
		pw.flush();
	}
	static void dfs2(int now,int from,long mu){
		int index=1;
		for(int i:edge[now]){
			if(i!=from){
				long tmu=(1+mu*((fcum[now].get(index-1)*bcum[now].get(fcum[now].size()-1-index))%m))%m;
				ans[i]=dp[i][1]*tmu%m;
				index++;
				dfs2(i,now,tmu);
			}
		}
	}
	static void dfs1(int now,int from){
		fcum[now].add(1L);
		bcum[now].add(1L);
		for(int i:edge[now]){
			if(i!=from){
				dfs1(i,now);
				dp[now][0]=dp[now][0]*dp[i][0]%m;
				dp[now][1]=dp[now][1]*(dp[i][0]+dp[i][1])%m;
			}
		}
		long cum=1;
		for(int i=0; i<edge[now].size(); i++){
			if(edge[now].get(i)!=from){
				cum=cum*(dp[edge[now].get(i)][1]+1)%m;
				fcum[now].add(cum);
			}
		}
		cum=1;
		for(int i=edge[now].size()-1; i>=0; i--){
			if(edge[now].get(i)!=from){
				cum=cum*(dp[edge[now].get(i)][1]+1)%m;
				bcum[now].add(cum);
			}
		}
	}
}

import java.io.*;
import java.util.*;

class Main {

	private static int[] dp;
	private static int[] answer;
	private static List<Integer>[] g;
	private static int m;

	public static void main(String[] args) throws Exception {
		final Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		m = sc.nextInt();

		g = new ArrayList[n];
		for (int i = 0; i < n; i++) {
			g[i] = new ArrayList<>();
		}

		for (int i = 0; i < n - 1; i++) {
			int x = sc.nextInt() - 1;
			int y = sc.nextInt() - 1;
			g[x].add(y);
			g[y].add(x);
		}

		dp = new int[n];
		answer = new int[n];
		dfs1(0, -1);
		dfs2(0, -1);

		StringBuilder sb = new StringBuilder();
		for (int v = 0; v < n; v++) {
			sb.append(answer[v]).append("\n");
		}

		System.out.print(sb.toString());
	}

	private static void dfs1(int v, int p) {
		dp[v] = 1;
		for (int to : g[v]) {
			if (to == p) continue;
			dfs1(to, v);
			dp[v] = (dp[v] * (dp[to] + 1)) % m;
		}
	}

	private static void dfs2(int v, int p) {
		List<Integer> lm = new ArrayList<>();
		List<Integer> rm = new ArrayList<>();
		lm.add(1);
		rm.add(1);
		for (int i = 0; i < g[v].size(); i++) {
			int last = lm.get(lm.size() - 1);
			lm.add(last * (1 + dp[g[v].get(i)]) % m);
		}

		for (int i = g[v].size() - 1; i >= 0; i--) {
			int last = rm.get((rm.size() - 1));
			rm.add(last * (1 + dp[g[v].get(i)]) % m);
		}

		answer[v] = rm.get(rm.size() - 1);
		for (int i = 0; i < g[v].size(); i++) {
			if (g[v].get(i) == p) continue;
			int t1 = dp[v];
			int t2 = dp[g[v].get(i)];
			int a = lm.get(i) * rm.get(rm.size() - 1 - i - 1) % m;
			dp[v] = a;
			dp[g[v].get(i)] = dp[g[v].get(i)] * (dp[v] + 1) % m;
			dfs2(g[v].get(i), v);
			dp[v] = t1;
			dp[g[v].get(i)] = t2;
		}
	}
}

