class ModCalculator {
  private final long mod;
  private final ModCombinationCache modCombinationCache;

  ModCalculator(long mod) {
    this.mod = mod;
    this.modCombinationCache = new ModCombinationCache();
  }

  public long add(long a, long b) {
    return (a + b) % mod;
  }

  public long sub(long a, long b) {
    return (a - b + mod) % mod;
  }

  public long mul(long a, long b) {
    a %= mod;
    b %= mod;
    return (a * b) % mod;
  }

  public long pow(long a, long b) {
    if (b == 0) {
      return 1;
    }
    long v = pow(mul(a, a), b / 2);
    if (b % 2 == 1) {
      return mul(v, a);
    } else {
      return v;
    }
  }

  public long inverse(long a) {
    return pow(a, mod - 2);
  }

  public long div(long a, long b) {
    return mul(a, inverse(b));
  }

  public long getF(int n) {
    return modCombinationCache.getF(n);
  }

  public long getP(int n, int r) {
    return modCombinationCache.getP(n, r);
  }

  public long getC(int n, int k) {
    return modCombinationCache.getC(n, k);
  }

  class ModCombinationCache {
    private final List<Long> factorialCache;
    private final List<Long> factorialInverseCache;

    public ModCombinationCache() {
      factorialCache = new ArrayList<>();
      factorialCache.add(1L);
      factorialInverseCache = new ArrayList<>();
      factorialInverseCache.add(1L);
    }

    private void resize(int n) {
      for (int i = factorialCache.size() - 1; i < n; i++) {
        long v = mul(factorialCache.get(i), i + 1);
        factorialCache.add(v);
        factorialInverseCache.add(inverse(v));
      }
    }

    long getF(int n) {
      resize(n);
      return factorialCache.get(n);
    }

    long getP(int n, int r) {
      resize(n);
      return mul(factorialCache.get(n), factorialInverseCache.get(n - r));
    }

    long getC(int n, int k) {
      resize(n);
      return mul(factorialCache.get(n), mul(factorialInverseCache.get(k), factorialInverseCache.get(n-k)));
    }
  }
}

import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.List;
import java.io.BufferedWriter;
import java.io.Writer;
import java.io.OutputStreamWriter;
import java.util.InputMismatchException;
import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author prakharjain
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        VSubtree solver = new VSubtree();
        solver.solve(1, in, out);
        out.close();
    }

    static class VSubtree {
        List[] g;
        int n;
        int m;
        long[] sub;
        long[] dp;
        long[] ans;

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            n = in.nextInt();

            m = in.nextInt();

            g = new List[n];

            in.readUndirectedGraph(g, n, n - 1, 1);

            sub = new long[n];
            dp = new long[n];
            ans = new long[n];

            dfs(0, -1);

            dfs2(0, -1, -1, -1);

            for (int i = 0; i < n; i++) {
                out.println(ans[i]);
            }

        }

        void dfs(int u, int p) {
            sub[u] = 1;
            for (int i = 0; i < g[u].size(); i++) {
                int v = (int) g[u].get(i);

                if (v != p) {
                    dfs(v, u);
                    sub[u] *= (1 + sub[v]);
                    sub[u] %= m;
                }
            }
        }

        void dfs2(int u, int p, long prep, long sufp) {

            if (u == 0) {
                dp[0] = 1;
                ans[0] = sub[0];
            } else {
                long val = ((prep * sufp) % m) * dp[p];
                dp[u] = 1 + val;
                dp[u] %= m;

                ans[u] += (sub[u] * dp[u]) % m;
                ans[u] %= m;
            }

            int cc = g[u].size();

            if (u != 0) {
                cc--;
            }

            if (cc == 0)
                return;

            long[] val = new long[cc];
            long[] pre = new long[cc + 1];
            long[] suf = new long[cc + 2];

            for (int i = 0, j = 0; i < g[u].size(); i++) {
                int v = (int) g[u].get(i);

                if (v != p) {
                    val[j] = 1 + sub[v];
                    val[j] %= m;
                    j++;
                }
            }

            pre[0] = 1;

            for (int i = 0; i < cc; i++) {
                pre[i + 1] = pre[i] * val[i];
                pre[i + 1] %= m;
            }

            suf[cc + 1] = 1;

            for (int i = cc - 1; i >= 0; i--) {
                suf[i + 1] = suf[i + 2] * val[i];
                suf[i + 1] %= m;
            }

            for (int i = 0, j = 1; i < g[u].size(); i++) {
                int v = (int) g[u].get(i);

                if (v != p) {
                    dfs2(v, u, pre[j - 1], suf[j + 1]);
                    j++;
                }
            }
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public void readUndirectedGraph(List[] g, int numOfVertices, int numOfEdges, int offset) {
            for (int i = 0; i < numOfVertices; i++) {
                g[i] = new ArrayList();
            }

            for (int i = 0; i < numOfEdges; i++) {
                int u = nextInt() - offset;
                int v = nextInt() - offset;

                g[u].add(v);
                g[v].add(u);
            }
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void close() {
            writer.close();
        }

        public void println(long i) {
            writer.println(i);
        }

    }
}

import java.io.*;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.StringJoiner;
import java.util.StringTokenizer;

public class Main {

    static int N, M;
    static int[] X, Y;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        M = sc.nextInt();
        X = new int[N-1];
        Y = new int[N-1];
        for (int i = 0; i < N - 1; i++) {
            X[i] = sc.nextInt()-1;
            Y[i] = sc.nextInt()-1;
        }

        writeLines(solve());
    }

    static long[] solve() {
        int root = 0;
        int[][] G = adjB(N, X, Y);
        long[] dp = new long[N];
        for (Node node : orderFromLeaf(N, G, root)) {
            long b = 1;
            for (int next : G[node.a]) {
                if( next != node.parent ) {
                    b *= dp[next]+1;
                    b %= M;
                }
            }
            dp[node.a] = b;
        }

        long[] ans = new long[N];
        long[][] cp = new long[N][]; // 累積積を利用した結果
        for (Node node : orderFromRoot(N, G, root)) {
            ans[node.a] = calcCp(node, dp, cp, G);
        }

        return ans;
    }

    static long calcCp(Node node, long[] dp, long[][] cp, int[][] G) {
        long p;
        if( node.parent < 0 ) {
            p = 1;
        } else {
            p = cp[node.parent][node.i];
        }

        int[] nodes = G[node.a];
        int n = nodes.length;
        long[] cp_l = new long[n+1];
        cp_l[0] = 1;
        for (int i = 0; i < n; i++) {
            int next = nodes[i];
            long v = next == node.parent ? p : dp[next];
            cp_l[i+1] = cp_l[i] * (v + 1);
            cp_l[i+1] %= M;
        }
        long[] cp_r = new long[n+1];
        cp_r[n] = 1;
        for (int i = n-1; i >= 0; i--) {
            int next = nodes[i];
            long v = next == node.parent ? p : dp[next];
            cp_r[i] = cp_r[i+1] * (v + 1);
            cp_r[i] %= M;
        }

        long[] cpcp = new long[n];
        for (int i = 0; i < n; i++) {
            cpcp[i] = cp_l[i] * cp_r[i+1] % M;
        }
        cp[node.a] = cpcp;
        return cp_r[0];
    }

    static int[][] adjB(int n, int[] from, int[] to) {
        int[][] adj = new int[n][];
        int[] cnt = new int[n];
        for (int f : from) {
            cnt[f]++;
        }
        for (int t : to) {
            cnt[t]++;
        }
        for (int i = 0; i < n; i++) {
            adj[i] = new int[cnt[i]];
        }
        for (int i = 0; i < from.length; i++) {
            adj[from[i]][--cnt[from[i]]] = to[i];
            adj[to[i]][--cnt[to[i]]] = from[i];
        }
        return adj;
    }

    static Node[] orderFromRoot(int N, int[][] G, int root) {
        ArrayDeque<Node> q = new ArrayDeque<>();
        Node[] ret = new Node[N];
        int idx = 0;
        q.add(new Node(-1, -1, root));
        while(!q.isEmpty()) {
            Node n = q.poll();
            ret[idx++] = n;
            for (int i = 0; i < G[n.a].length; i++) {
                int next = G[n.a][i];
                if( next == n.parent ) continue;

                q.add(new Node(n.a, i, next));
            }
        }
        return ret;
    }

    static Node[] orderFromLeaf(int N, int[][] G, int root) {
        ArrayDeque<Node> q = new ArrayDeque<>();
        Node[] ret = new Node[N];
        int idx = N-1;
        q.add(new Node(-1, -1, root));
        while(!q.isEmpty()) {
            Node n = q.poll();
            ret[idx--] = n;

            for (int i = 0; i < G[n.a].length; i++) {
                int next = G[n.a][i];
                if( next == n.parent ) continue;

                q.add(new Node(n.a, i, next));
            }
        }
        return ret;
    }

    static class Node {
        int parent, i, a;

        public Node(int parent, int i, int a) {
            this.parent = parent;
            this.i = i;
            this.a = a;
        }
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) a[i] = nextInt();
            return a;
        }

        int[] nextIntArray(int n, int delta) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) a[i] = nextInt() + delta;
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++) a[i] = nextLong();
            return a;
        }
    }

    static void writeLines(int[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (int a : as) pw.println(a);
        pw.flush();
    }

    static void writeLines(long[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (long a : as) pw.println(a);
        pw.flush();
    }

    static void writeSingleLine(int[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (int i = 0; i < as.length; i++) {
            if (i != 0) pw.print(" ");
            pw.print(i);
        }
        pw.println();
        pw.flush();
    }

    static int max(int... as) {
        int max = Integer.MIN_VALUE;
        for (int a : as) max = Math.max(a, max);
        return max;
    }

    static int min(int... as) {
        int min = Integer.MAX_VALUE;
        for (int a : as) min = Math.min(a, min);
        return min;
    }

    static void debug(Object... args) {
        StringJoiner j = new StringJoiner(" ");
        for (Object arg : args) {
            if (arg instanceof int[]) j.add(Arrays.toString((int[]) arg));
            else if (arg instanceof long[]) j.add(Arrays.toString((long[]) arg));
            else if (arg instanceof double[]) j.add(Arrays.toString((double[]) arg));
            else if (arg instanceof Object[]) j.add(Arrays.toString((Object[]) arg));
            else j.add(arg == null ? "null" : arg.toString());
        }
        System.err.println(j.toString());
    }

    static void printSingleLine(int[] array) {
        for (int i = 0; i < array.length; i++) {
            if (i != 0) System.out.print(" ");
            System.out.print(array[i]);
        }
        System.out.println();
    }

    static int lowerBound(int[] array, int value) {
        int low = 0, high = array.length, mid;
        while (low < high) {
            mid = ((high - low) >>> 1) + low;
            if (array[mid] < value) low = mid + 1;
            else high = mid;
        }
        return low;
    }

    static int upperBound(int[] array, int value) {
        int low = 0, high = array.length, mid;
        while (low < high) {
            mid = ((high - low) >>> 1) + low;
            if (array[mid] <= value) low = mid + 1;
            else high = mid;
        }
        return low;
    }
}

import java.io.InputStream;
import java.util.Arrays;
import java.util.function.IntUnaryOperator;
import java.util.function.LongUnaryOperator;

public class Main {
    public static void main(String[] args) throws Exception {
        ExtendedScanner sc = new ExtendedScanner();
        FastPrintStream pw = new FastPrintStream();
        solve(sc, pw);
        sc.close();
        pw.flush();
        pw.close();
    }

    public static void solve(ExtendedScanner sc, FastPrintStream pw) {
        int n = sc.nextInt();
        long m = sc.nextLong();
        var tb = new TreeBuilder(n);
        for (int i = 1; i < n; i++) {
            int u = sc.nextInt() - 1;
            int v = sc.nextInt() - 1;
            tb.addEdge(u, v);
        }
        var t = tb.build();
        var ma = new ModArithmetic(m);
        var r = new Rerooting(
            t, 1, new Rerooting.AddChild(){
                @Override
                public long add(long dpSum, long dp, int child, int parent) {
                    return ma.mul(dpSum, dp + 1);
                }
            }, new Rerooting.AddSubtreeRoot(){
                @Override
                public long add(long dpSum, int root, int parent) {
                    return dpSum;
                }
            }, new Rerooting.MergeChildren(){
                @Override
                public long merge(long dpSumL, long dpSumR) {
                    return ma.mul(dpSumL, dpSumR);
                }
            }, new Rerooting.AddRoot(){
                @Override
                public long add(long dpSum, int root) {
                    return dpSum;
                }
            }
        );
        for (long ans : r.dp()) {
            pw.println(ans);
        }
    }
}

