			long[] right=new long[list[v].size()+1];
			left[0]=1;
			right[right.length-1]=1;
			for (int i = 1; i < right.length; i++) {
				if (list[v].get(i-1).to==p) {
					left[i]=left[i-1];
					continue;
				}
				left[i]=left[i-1]*dp1[list[v].get(i-1).to];
				left[i]%=M;
			}
			for (int i = right.length-2; i >= 0; i--) {
				if (list[v].get(i).to==p) {
					right[i]=right[i+1];
					continue;
