	private static void solve() {
		int n = sc.nextInt();
		int m = sc.nextInt();

		int[][] xy = sc.nextIntArrays(2, n - 1);

		RoutedTree rt = new RoutedTree(n);
		for (int i = 0; i < n - 1; i++) {
			int x = xy[0][i] - 1;
			int y = xy[1][i] - 1;

			rt.addEdge(x, y);
		}

		int root = 0;
		rt.dfs(root);

		List<List<Long>> dp3 = new ArrayList<>(n);
		List<List<Long>> dp4 = new ArrayList<>(n);
		List<List<Long>> dp5 = new ArrayList<>(n);
		for (int i = 0; i < n; i++) {
			dp3.add(new ArrayList<>());
		}
		for (int i = 0; i < n; i++) {
			dp4.add(new ArrayList<>());
			dp5.add(new ArrayList<>());
		}

		long[] dp = new long[n];
		for (int i = n - 1; i >= 0; i--) {
			int e = rt.preorder[i];

			long tmp = 1;
			for (int next : rt.edges.get(e)) {
				if (next == rt.p[e]) {
					continue;
				}

				tmp *= dp[next] + 1;
				tmp %= m;

				if (i == root) {
					dp3.get(i).add(dp[next]);
				}
			}
			dp[e] = tmp;
		}

		long[] dp2 = Arrays.copyOf(dp, dp.length);
		for (int e : rt.preorder) {
			if (e == root) {
				dp4.get(e).add(1L);
				for (int i = 0, size = rt.edges.get(e).size(); i < size; i++) {
					dp4.get(e).add(dp4.get(e).get(i) * (dp3.get(e).get(i) + 1) % m);
				}
				for (int i = 0, size = rt.edges.get(e).size(); i < size + 1; i++) {
					dp5.get(e).add(1L);
				}
				for (int i = rt.edges.get(e).size() - 1; i >= 0; i--) {
					dp5.get(e).set(i, dp5.get(e).get(i + 1) * (dp3.get(e).get(i) + 1) % m);
				}

				continue;
			}

			int p = rt.p[e];

			long tmp = 1;
			/*
			for (int i = 0, size = rt.edges.get(p).size(); i < size; i++) {
				int c = rt.edges.get(p).get(i);

				if (c == e) {
					continue;
				}

				tmp *= dp3.get(p).get(i) + 1;
				tmp %= m;
			}
			*/
			int index = Collections.binarySearch(rt.edges.get(p), e);
			tmp *= dp4.get(p).get(index);
			tmp %= m;
			tmp *= dp5.get(p).get(index + 1);
			tmp %= m;

			for (int i = 0, size = rt.edges.get(e).size(); i < size; i++) {
				int c = rt.edges.get(e).get(i);

				if (c == p) {
					dp3.get(e).add(tmp);
				} else {
					dp3.get(e).add(dp[c]);
				}
			}
			dp4.get(e).add(1L);
			for (int i = 0, size = rt.edges.get(e).size(); i < size; i++) {
				dp4.get(e).add(dp4.get(e).get(i) * (dp3.get(e).get(i) + 1) % m);
			}
			for (int i = 0, size = rt.edges.get(e).size(); i < size + 1; i++) {
				dp5.get(e).add(1L);
			}
			for (int i = rt.edges.get(e).size() - 1; i >= 0; i--) {
				dp5.get(e).set(i, dp5.get(e).get(i + 1) * (dp3.get(e).get(i) + 1) % m);
			}

			dp2[e] *= tmp + 1;
			dp2[e] %= m;
		}

		for (long e : dp2) {
			pr.println(e);
		}
	}

	static class RoutedTree {
		int n;
		int m;
		List<List<Integer>> edges;

		int root;
		int[] p;
		int[] d;
		int[] preorder;

		RoutedTree(int n) {
			this.n = n;
			edges = new ArrayList<>(n);
			for (int i = 0; i < n; i++) {
				edges.add(new ArrayList<>());
			}

			root = -1;
			p = new int[n];
			d = new int[n];
			preorder = new int[n];
		}

		void addEdge(int u, int v) {
			edges.get(u).add(v);
			edges.get(v).add(u);
			m++;
		}

		void dfs(int root) {
			if (this.root == root) {
				return;
			}

			for (int i = 0; i < n; i++) {
				Collections.sort(edges.get(i));
			}

			this.root = root;
			Arrays.fill(p, 0);
			Arrays.fill(d, 0);
			boolean[] used = new boolean[n];
			Deque<Integer> st = new ArrayDeque<>();
			st.push(root);
			p[root] = -1;
			d[root] = 0;
			int prei = 0;
			while (!st.isEmpty()) {
				int e = st.peek();

				if (used[e]) {
					// postorder

					st.pop();
				} else {
					// preorder
					for (int next : edges.get(e)) {
						if (next == p[e]) {
							continue;
						}

						p[next] = e;
						d[next] = d[e] + 1;
						st.push(next);
					}

					used[e] = true;
					preorder[prei++] = e;
				}
			}
		}
	}

