import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		Scanner in = new Scanner(new BufferedReader(new InputStreamReader(System.in)));
		int n = in.nextInt();
		int m = in.nextInt();
		Map<Integer, List<Integer>> edges = getEdges(in, n - 1, false);
		long[] r = solve(n, m, edges);
		System.out.println(str(r));
		in.close();
	}

	private static long[] solve(int n, int m, Map<Integer, List<Integer>> edges) {
		long[] up = new long[n + 1];
		long[] sub = new long[n + 1];
		mod = m;
		dfs1(edges, sub, 0, 1);
		dfs3(edges, sub, up, new long[0], new long[0], 0, 1, 0);
		long[] r = new long[n];
		for (int i = 0; i < r.length; i++) {
			r[i] = mul(up[i + 1], sub[i + 1]);
		}
		return r;
	}

	private static long[] solve1(int n, int m, Map<Integer, List<Integer>> edges) {
		long[] dp = new long[n + 1];
		long[] sub = new long[n + 1];
		mod = m;
		dfs1(edges, sub, 0, 1);
		dfs2(edges, sub, dp, 0, 1);
		return Arrays.copyOfRange(dp, 1, dp.length);
	}

	static void dfs1(Map<Integer, List<Integer>> edges, long[] sub, int par, int cur) {
		sub[cur] = 1;
		List<Integer> adjV = edges.get(cur);
		if (adjV != null) {
			for (int v : adjV) {
				if (v != par) {
					dfs1(edges, sub, cur, v);
					sub[cur] = mul(sub[cur], (sub[v] + 1));
				}
			}
		}
	}

	static void dfs2(Map<Integer, List<Integer>> edges, long[] sub, long[] dp, int par, int cur) {
		dp[cur] = sub[cur] * (dp[par] / (sub[cur] + 1) + 1);
		List<Integer> adjV = edges.get(cur);
		if (adjV != null) {
			for (int v : adjV) {
				if (v != par) {
					dfs2(edges, sub, dp, cur, v);
				}
			}
		}
	}

	static void dfs3(Map<Integer, List<Integer>> edges, long[] sub, long[] up, long[] prefixProd, long[] suffixProd,
			int par, int cur, int i) {
		up[cur] = 1;
		if (i > 0) {
			up[cur] = mul(up[cur], prefixProd[i - 1]);
		}
		if (i < prefixProd.length - 1) {
			up[cur] = mul(up[cur], suffixProd[i + 1]);
		}
		up[cur] = add(mul(up[cur], up[par]), 1);
		List<Integer> adjV = edges.get(cur);
		adjV.remove((Integer) par);
		prefixProd = new long[adjV.size()];
		suffixProd = new long[adjV.size()];
		for (int j = 0; j < adjV.size(); j++) {
			if (j == 0) {
				prefixProd[j] = add(sub[adjV.get(j)], 1);
				suffixProd[adjV.size() - j - 1] = add(sub[adjV.get(adjV.size() - j - 1)], 1);
			} else {
				prefixProd[j] = mul(add(sub[adjV.get(j)], 1), prefixProd[j - 1]);
				suffixProd[adjV.size() - j - 1] = mul(add(sub[adjV.get(adjV.size() - j - 1)], 1),
						suffixProd[adjV.size() - j]);
			}
		}
		for (int j = 0; j < adjV.size(); j++) {
			dfs3(edges, sub, up, prefixProd, suffixProd, cur, adjV.get(j), j);
		}
	}

	static long mod = 1000000007;

	static long add(long a, long b) {
		long r = a + b;
		if (r < 0) {
			r += mod;
		}
		return r % mod;
	}

	static long mul(long a, long b) {
		return (a * b) % mod;
	}

	static String str(long[] a) {
		String[] str = new String[a.length];
		for (int i = 0; i < a.length; i++) {
			str[i] = a[i] + "";
		}
		return String.join(" ", str);
	}

	static int[] getIntArr(Scanner in, int size) {
		int[] arr = new int[size];
		for (int i = 0; i < size; i++) {
			arr[i] = in.nextInt();
		}
		return arr;
	}

	static int[][] getIntArr(Scanner in, int row, int col) {
		int[][] arr = new int[row][];
		for (int i = 0; i < row; i++) {
			arr[i] = getIntArr(in, col);
		}
		return arr;
	}

	static char[] getCharArr(Scanner in, int size) {
		char[] arr = in.next().toCharArray();
		return arr;
	}

	static String[] getStringArr(Scanner in, int size) {
		String[] arr = new String[size];
		for (int i = 0; i < size; i++) {
			arr[i] = in.next();
		}
		return arr;
	}

	static Map<Integer, List<Integer>> getEdges(Scanner in, int size, boolean directed) {
		Map<Integer, List<Integer>> edges = new HashMap<>();
		for (int i = 0; i < size; i++) {
			int from = in.nextInt();
			int to = in.nextInt();
			if (!edges.containsKey(from)) {
				edges.put(from, new ArrayList<Integer>());
			}
			edges.get(from).add(to);
			if (!directed) {
				if (!edges.containsKey(to)) {
					edges.put(to, new ArrayList<Integer>());
				}
				edges.get(to).add(from);
			}

		}
		return edges;
	}
}

import java.io.*;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.StringJoiner;
import java.util.StringTokenizer;
import java.util.function.IntToLongFunction;

public class Main {

    static int N, M;
    static int[] X, Y;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        M = sc.nextInt();
        X = new int[N-1];
        Y = new int[N-1];
        for (int i = 0; i < N - 1; i++) {
            X[i] = sc.nextInt()-1;
            Y[i] = sc.nextInt()-1;
        }

        writeLines(solve());
    }

    static long[] solve() {
        int root = 0;
        int[][] G = adjB(N, X, Y);
        long[] dp = new long[N];
        for (Node node : orderFromLeaf(N, G, root)) {
            long b = 1;
            for (int next : G[node.a]) {
                if( next != node.parent ) {
                    b *= (dp[next]+1);
                    b %= M;
                }
            }
            dp[node.a] = b;
        }

        long[] ans = new long[N];
        long[][][] cp = new long[N][2][]; // 累積積
        for (Node node : orderFromRoot(N, G, root)) {
            calcCp(node.a, cp, G, no -> {
                if( no == node.parent ) {
                    return useCp(node, cp, G);
                } else {
                    return dp[no];
                }
            });
            ans[node.a] = cp[node.a][1][0];
        }

        return ans;
    }

    static long useCp(Node node, long[][][] cp, int[][] G) {
        long[] left = cp[node.parent][0];
        long[] right = cp[node.parent][1];

        int[] nodes = G[node.parent];
        for (int i = 0; i < nodes.length; i++) {
            if( nodes[i] == node.a ) {
                return left[i] * right[i+1] % M;
            }
        }
        throw new IllegalArgumentException("wtf");
    }

    static void calcCp(int a, long[][][] cp, int[][] G, IntToLongFunction nodeToCnt) {
        int[] nodes = G[a];
        int n = nodes.length;
        long[] cp_l = new long[n+1];
        cp_l[0] = 1;
        for (int i = 0; i < n; i++) {
            int next = nodes[i];
            cp_l[i+1] = cp_l[i] * (nodeToCnt.applyAsLong(next) + 1);
            cp_l[i+1] %= M;
        }
        long[] cp_r = new long[n+1];
        cp_r[n] = 1;
        for (int i = n-1; i >= 0; i--) {
            int next = nodes[i];
            cp_r[i] = cp_r[i+1] * (nodeToCnt.applyAsLong(next) + 1);
            cp_r[i] %= M;
        }
        cp[a][0] = cp_l;
        cp[a][1] = cp_r;
    }

    static int[][] adjB(int n, int[] from, int[] to) {
        int[][] adj = new int[n][];
        int[] cnt = new int[n];
        for (int f : from) {
            cnt[f]++;
        }
        for (int t : to) {
            cnt[t]++;
        }
        for (int i = 0; i < n; i++) {
            adj[i] = new int[cnt[i]];
        }
        for (int i = 0; i < from.length; i++) {
            adj[from[i]][--cnt[from[i]]] = to[i];
            adj[to[i]][--cnt[to[i]]] = from[i];
        }
        return adj;
    }

    static Node[] orderFromRoot(int N, int[][] G, int root) {
        ArrayDeque<Node> q = new ArrayDeque<>();
        Node[] ret = new Node[N];
        int idx = 0;
        q.add(new Node(-1, root));
        while(!q.isEmpty()) {
            Node n = q.poll();
            ret[idx++] = n;
            for (int next : G[n.a]) {
                if( next == n.parent ) continue;

                q.add(new Node(n.a, next));
            }
        }
        return ret;
    }

    static Node[] orderFromLeaf(int N, int[][] G, int root) {
        ArrayDeque<Node> q = new ArrayDeque<>();
        Node[] ret = new Node[N];
        int idx = N-1;
        q.add(new Node(-1, root));
        while(!q.isEmpty()) {
            Node n = q.poll();
            ret[idx--] = n;
            for (int next : G[n.a]) {
                if( next == n.parent ) continue;

                q.add(new Node(n.a, next));
            }
        }
        return ret;
    }

    static class Node {
        int parent, a;

        public Node(int parent, int a) {
            this.parent = parent;
            this.a = a;
        }
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) a[i] = nextInt();
            return a;
        }

        int[] nextIntArray(int n, int delta) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) a[i] = nextInt() + delta;
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++) a[i] = nextLong();
            return a;
        }
    }

    static void writeLines(int[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (int a : as) pw.println(a);
        pw.flush();
    }

    static void writeLines(long[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (long a : as) pw.println(a);
        pw.flush();
    }

    static void writeSingleLine(int[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (int i = 0; i < as.length; i++) {
            if (i != 0) pw.print(" ");
            pw.print(i);
        }
        pw.println();
        pw.flush();
    }

    static int max(int... as) {
        int max = Integer.MIN_VALUE;
        for (int a : as) max = Math.max(a, max);
        return max;
    }

    static int min(int... as) {
        int min = Integer.MAX_VALUE;
        for (int a : as) min = Math.min(a, min);
        return min;
    }

    static void debug(Object... args) {
        StringJoiner j = new StringJoiner(" ");
        for (Object arg : args) {
            if (arg instanceof int[]) j.add(Arrays.toString((int[]) arg));
            else if (arg instanceof long[]) j.add(Arrays.toString((long[]) arg));
            else if (arg instanceof double[]) j.add(Arrays.toString((double[]) arg));
            else if (arg instanceof Object[]) j.add(Arrays.toString((Object[]) arg));
            else j.add(arg == null ? "null" : arg.toString());
        }
        System.err.println(j.toString());
    }

    static void printSingleLine(int[] array) {
        for (int i = 0; i < array.length; i++) {
            if (i != 0) System.out.print(" ");
            System.out.print(array[i]);
        }
        System.out.println();
    }

    static int lowerBound(int[] array, int value) {
        int low = 0, high = array.length, mid;
        while (low < high) {
            mid = ((high - low) >>> 1) + low;
            if (array[mid] < value) low = mid + 1;
            else high = mid;
        }
        return low;
    }

    static int upperBound(int[] array, int value) {
        int low = 0, high = array.length, mid;
        while (low < high) {
            mid = ((high - low) >>> 1) + low;
            if (array[mid] <= value) low = mid + 1;
            else high = mid;
        }
        return low;
    }
}

import java.io.*;
import java.util.*;

class Solver {
  final int n;
  final long m;
  final int[][] xys;

  List<List<Integer>> graph;
  List<Map<Integer, Integer>> graphChildIndexMap;

  ModCalculator mc;
  long[][] countMatrix;
  long[][] countMulFromHeadMatrix;
  long[][] countMulFromTailMatrix;

  Solver(int n, long m, int[][] xys) {
    this.n = n;
    this.m = m;
    this.xys = xys;
  }

  private long calculateCountMulFromHead(int index, int childIndexPosition) {
    if (childIndexPosition < 0) {
      return 1L;
    }
    long cacheMulValue = countMulFromHeadMatrix[index][childIndexPosition];
    if (cacheMulValue >= 0) {
      return cacheMulValue;
    }
    long cacheValue = countMatrix[index][childIndexPosition];
    if (cacheValue < 0) {
      int childIndex = graph.get(index).get(childIndexPosition);
      cacheValue = mc.add(calculateCount(childIndex, index), 1);
      countMatrix[index][childIndexPosition] = cacheValue;
    }
    long countMulValue = mc.mul(cacheValue, calculateCountMulFromHead(index, childIndexPosition - 1));
    countMulFromHeadMatrix[index][childIndexPosition] = countMulValue;
    return countMulValue;
  }

  private long calculateCountMulFromTail(int index, int childIndexPosition) {
    if (childIndexPosition >= graph.get(index).size()) {
      return 1L;
    }
    long cacheMulValue = countMulFromTailMatrix[index][childIndexPosition];
    if (cacheMulValue >= 0) {
      return cacheMulValue;
    }
    long cacheValue = countMatrix[index][childIndexPosition];
    if (cacheValue < 0) {
      int childIndex = graph.get(index).get(childIndexPosition);
      cacheValue = mc.add(calculateCount(childIndex, index), 1);
      countMatrix[index][childIndexPosition] = cacheValue;
    }
    long countMulValue = mc.mul(cacheValue, calculateCountMulFromTail(index, childIndexPosition + 1));
    countMulFromTailMatrix[index][childIndexPosition] = countMulValue;
    return countMulValue;
  }

  private long calculateCount(int index, int parentIndex) {
    int parentIndexPosition = graphChildIndexMap.get(index).get(parentIndex);
    long v1 = calculateCountMulFromHead(index, parentIndexPosition - 1);
    long v2 = calculateCountMulFromTail(index, parentIndexPosition + 1);
    return mc.mul(v1, v2);
  }

  private long solve(int index) {
    return calculateCountMulFromHead(index, graph.get(index).size() - 1);
  }

  public List<Long> solve() {
    graph = new ArrayList<>();
    graphChildIndexMap = new ArrayList<>();
    for (int i = 0; i <= n; i++) {
      graph.add(new ArrayList<>());
      graphChildIndexMap.add(new HashMap<>());
    }
    for (int[] xy : xys) {
      int x = xy[0];
      int y = xy[1];
      graphChildIndexMap.get(x).put(y, graph.get(x).size());
      graph.get(x).add(y);
      graphChildIndexMap.get(y).put(x, graph.get(y).size());
      graph.get(y).add(x);
    }

    countMatrix = new long[n + 1][];
    countMulFromHeadMatrix = new long[n + 1][];
    countMulFromTailMatrix = new long[n + 1][];
    for (int i = 0; i <= n; i++) {
      countMatrix[i] = new long[graph.get(i).size()];
      countMulFromHeadMatrix[i] = new long[graph.get(i).size()];
      countMulFromTailMatrix[i] = new long[graph.get(i).size()];
      Arrays.fill(countMatrix[i], -1);
      Arrays.fill(countMulFromHeadMatrix[i], -1);
      Arrays.fill(countMulFromTailMatrix[i], -1);
    }

    mc = new ModCalculator(m);

    List<Long> answers = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
      answers.add(solve(i));
    }
    return answers;
  }
}

public class Main {
  private static void execute(ContestReader reader, PrintWriter out) {
    int n = reader.nextInt();
    long m = reader.nextLong();
    int[][] xys = reader.nextInt(n - 1, 2);
    for (long answer : new Solver(n, m, xys).solve()) {
      out.println(answer);
    }
  }

  public static void main(String[] args) {
    ContestReader reader = new ContestReader(System.in);
    PrintWriter out = new PrintWriter(System.out);
    execute(reader, out);
    out.flush();
  }
}

