     * @param monoid function for merging results and the identity element of it.
     * @param addNode the function acted on merged result. (adding information about the node to the result.)
     * @param deg degrees of the vertices. (for cutting cost of memory)
     */
    public Rerooting(final int n, final LongMonoid monoid, final LongIntToLongFunction addNode) {
        this.n = n;
        this.mn = monoid;
        this.addNode = addNode;
        this.adj = new int[n][];
        this.inv = new int[n][];
        this.par = new int[n];
        this.sub = new long[n][];
        this.ord = new int[n];
        this.res = new long[n];
        Arrays.fill(res, monoid.e);
    }

    /**
     * add edges.
     * 
     * @param edges array (m, 2). edge[i] connects edges[i][0] with edges[i][1].
     */
    public void addEdges(final int[][] edges) {
        int[] deg = new int[n];
        for (int[] e : edges) {
            int u = e[0], v = e[1];
            deg[u]++; deg[v]++;
        }
        for (int i = 0; i < n; i++) {
            adj[i] = new int[deg[i]];
            inv[i] = new int[deg[i]];
            sub[i] = new long[deg[i]];
        }
        int[] size = new int[n];
        for (int[] e : edges) {
            int u = e[0], v = e[1];
            int su = size[u], sv = size[v];
            inv[u][su] = sv; inv[v][sv] = su;
            adj[u][su] =  v; adj[v][sv] =  u;
            size[u]++; size[v]++;
        }
    }

    /**
     * 
     * @return the result of the rerooting.
     */
    public long[] rerooting() {
        down();
        up();
        calc();
        return res;
    }

    /**
     * Execute DFS and record the order of visiting and the parent of each vertex.
     */
    private void down() {
        int k = 0;
        IntDeque st = new IntDeque(n);
        st.addLast(0);
        while (st.size() > 0) {
            int u = st.removeLast();
            ord[k++] = u;
            for (int v : adj[u]) {
                if (v == par[u]) continue;
                par[v] = u;
                st.addLast(v);
            }
        }
    }

    /**
     * calc sub[v][i] (i: children of v) in DFS-leaving order.
     * sub[v][pv] (pv: parent of v) is not calculated in this method.
     */
    private void up() {
        for (int i = n - 1; i > 0; i--) {
            int u = ord[i];
            int pu = par[u];
            long res = mn.e;
            int pj = -1;
            for (int j = 0; j < adj[u].length; j++) {
                int v = adj[u][j];
                if (v == pu) {
                    pj = j;
                } else {
                    res = mn.apply(res, sub[u][j]);
                }
            }
            sub[pu][inv[u][pj]] = addNode.apply(res, u);
        }
    }

    /**
     * calc sub[v][pv] (pv: the parent of v) and res[v].
     */
    private void calc() {
        for (int u : ord) {
            long[] pd = new long[adj[u].length];
            if (adj[u].length >= 1) pd[adj[u].length - 1] = mn.e;
            for (int j = adj[u].length - 1; j > 0; j--) {
                pd[j - 1] = mn.apply(pd[j], sub[u][j]);
            }
            long dp = mn.e;
            for (int j = 0; j < adj[u].length; j++) {
                int v = adj[u][j];
                long res = addNode.apply(mn.apply(dp, pd[j] - 1), u);
                sub[v][inv[u][j]] = res;
                dp = mn.apply(dp, sub[u][j]);
            }
            res[u] = addNode.apply(dp, u);
        }
    }
}

