import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		Scanner in = new Scanner(new BufferedReader(new InputStreamReader(System.in)));
		int n = in.nextInt();
		int m = in.nextInt();
		Map<Integer, List<Integer>> edges = getEdges(in, n - 1, false);
		long[] r = solve(n, m, edges);
		System.out.println(str(r));
		in.close();
	}

	private static long[] solve(int n, int m, Map<Integer, List<Integer>> edges) {
		long[] up = new long[n + 1];
		long[] sub = new long[n + 1];
		mod = m;
		dfs1(edges, sub, 0, 1);
		dfs3(edges, sub, up, -1, 0, 1);
		long[] r = new long[n];
		for (int i = 0; i < r.length; i++) {
			r[i] = mul(up[i + 1], sub[i + 1]);
		}
		return r;
	}

	private static long[] solve1(int n, int m, Map<Integer, List<Integer>> edges) {
		long[] dp = new long[n + 1];
		long[] sub = new long[n + 1];
		mod = m;
		dfs1(edges, sub, 0, 1);
		dfs2(edges, sub, dp, 0, 1);
		return Arrays.copyOfRange(dp, 1, dp.length);
	}

	static void dfs1(Map<Integer, List<Integer>> edges, long[] sub, int par, int cur) {
		sub[cur] = 1;
		List<Integer> adjV = edges.get(cur);
		if (adjV != null) {
			for (int v : adjV) {
				if (v != par) {
					dfs1(edges, sub, cur, v);
					sub[cur] = mul(sub[cur], (sub[v] + 1));
				}
			}
		}
	}

	static void dfs2(Map<Integer, List<Integer>> edges, long[] sub, long[] dp, int par, int cur) {
		dp[cur] = sub[cur] * (dp[par] / (sub[cur] + 1) + 1);
		List<Integer> adjV = edges.get(cur);
		if (adjV != null) {
			for (int v : adjV) {
				if (v != par) {
					dfs2(edges, sub, dp, cur, v);
				}
			}
		}
	}

	static void dfs3(Map<Integer, List<Integer>> edges, long[] sub, long[] up, int grandPar, int par, int cur) {
		List<Integer> adjV = edges.get(par);
		up[cur] = 1;
		if (adjV != null) {
			for (int v : adjV) {
				if (v != cur && v != grandPar) {
					up[cur] = mul(up[cur], add(sub[v], 1));
				}
			}
			up[cur] = add(mul(up[cur], up[par]), 1);
		}
		adjV = edges.get(cur);
		if (adjV != null) {
			for (int v : adjV) {
				if (v != par) {
					dfs3(edges, sub, up, par, cur, v);
				}
			}
		}
	}

	static long mod = 1000000007;

	static long add(long a, long b) {
		long r = a + b;
		if (r < 0) {
			r += mod;
		}
		return r % mod;
	}

	static long mul(long a, long b) {
		return (a * b) % mod;
	}

	static String str(long[] a) {
		String[] str = new String[a.length];
		for (int i = 0; i < a.length; i++) {
			str[i] = a[i] + "";
		}
		return String.join(" ", str);
	}

	static int[] getIntArr(Scanner in, int size) {
		int[] arr = new int[size];
		for (int i = 0; i < size; i++) {
			arr[i] = in.nextInt();
		}
		return arr;
	}

	static int[][] getIntArr(Scanner in, int row, int col) {
		int[][] arr = new int[row][];
		for (int i = 0; i < row; i++) {
			arr[i] = getIntArr(in, col);
		}
		return arr;
	}

	static char[] getCharArr(Scanner in, int size) {
		char[] arr = in.next().toCharArray();
		return arr;
	}

	static String[] getStringArr(Scanner in, int size) {
		String[] arr = new String[size];
		for (int i = 0; i < size; i++) {
			arr[i] = in.next();
		}
		return arr;
	}

	static Map<Integer, List<Integer>> getEdges(Scanner in, int size, boolean directed) {
		Map<Integer, List<Integer>> edges = new HashMap<>();
		for (int i = 0; i < size; i++) {
			int from = in.nextInt();
			int to = in.nextInt();
			if (!edges.containsKey(from)) {
				edges.put(from, new ArrayList<Integer>());
			}
			edges.get(from).add(to);
			if (!directed) {
				if (!edges.containsKey(to)) {
					edges.put(to, new ArrayList<Integer>());
				}
				edges.get(to).add(from);
			}

		}
		return edges;
	}
}

import java.io.*;
import java.util.*;


public class Main {

	private static Scanner sc;
	private static Printer pr;

	private static void solve() {
		int n = sc.nextInt();
		int m = sc.nextInt();

		int[][] xy = sc.nextIntArrays(2, n - 1);

		RoutedTree rt = new RoutedTree(n);
		for (int i = 0; i < n - 1; i++) {
			int x = xy[0][i] - 1;
			int y = xy[1][i] - 1;

			rt.addEdge(x, y);
		}

		int root = 0;
		rt.dfs(root);

		List<List<Long>> dp3 = new ArrayList<>(n);
		for (int i = 0; i < n; i++) {
			dp3.add(new ArrayList<>());
		}

		long[] dp = new long[n];
		for (int i = n - 1; i >= 0; i--) {
			int e = rt.preorder[i];

			long tmp = 1;
			for (int next : rt.edges.get(e)) {
				if (next == rt.p[e]) {
					continue;
				}

				tmp *= dp[next] + 1;
				tmp %= m;

				dp3.get(i).add(dp[next]);
			}
			dp[e] = tmp;
		}


		long[] dp2 = Arrays.copyOf(dp, dp.length);
		for (int e : rt.preorder) {
			if (e == root) {
				continue;
			}

			int p = rt.p[e];
			long tmp = 1;
			for (int i = 0, size = rt.edges.get(p).size(); i < size; i++) {
				int c = rt.edges.get(p).get(i);

				if (c == e) {
					continue;
				}

				tmp *= dp3.get(p).get(i) + 1;
				tmp %= m;
			}

			for (int i = 0, size = rt.edges.get(e).size(); i < size; i++) {
				int c = rt.edges.get(e).get(i);

				if (c == p) {
					dp3.get(e).add(tmp);
				} else {
					dp3.get(e).add(dp[c]);
				}
			}

			dp2[e] *= tmp + 1;
			dp2[e] %= m;
		}

		for (long e : dp2) {
			pr.println(e);
		}
	}

	static class RoutedTree {
		int n;
		int m;
		List<List<Integer>> edges;

		int root;
		int[] p;
		int[] d;
		int[] preorder;

		RoutedTree(int n) {
			this.n = n;
			edges = new ArrayList<>(n);
			for (int i = 0; i < n; i++) {
				edges.add(new ArrayList<>());
			}

			root = -1;
			p = new int[n];
			d = new int[n];
			preorder = new int[n];
		}

		void addEdge(int u, int v) {
			edges.get(u).add(v);
			edges.get(v).add(u);
			m++;
		}

		void dfs(int root) {
			if (this.root == root) {
				return;
			}

			this.root = root;
			Arrays.fill(p, 0);
			Arrays.fill(d, 0);
			boolean[] used = new boolean[n];
			Deque<Integer> st = new ArrayDeque<>();
			st.push(root);
			p[root] = -1;
			d[root] = 0;
			int prei = 0;
			while (!st.isEmpty()) {
				int e = st.peek();

				if (used[e]) {
					// postorder

					st.pop();
				} else {
					// preorder
					for (int next : edges.get(e)) {
						if (next == p[e]) {
							continue;
						}

						p[next] = e;
						d[next] = d[e] + 1;
						st.push(next);
					}

					used[e] = true;
					preorder[prei++] = e;
				}
			}
		}
	}

