	static void dfs2(int now,int from,long mu){
		int index=1;
		for(int i:edge[now]){
			if(i!=from){
				long tmu=1+mu*fcum[now].get(index-1)*bcum[now].get(fcum[now].size()-1-index)%m;
				ans[i]=dp[i][1]*tmu%m;
				index++;
				dfs2(i,now,tmu);
			}
		}
	}
	static void dfs1(int now,int from){
		fcum[now].add(1L);
		bcum[now].add(1L);
		for(int i:edge[now]){
			if(i!=from){
				dfs1(i,now);
				dp[now][0]=dp[now][0]*dp[i][0]%m;
				dp[now][1]=dp[now][1]*(dp[i][0]+dp[i][1])%m;
			}
		}
		long cum=1;
		for(int i=0; i<edge[now].size(); i++){
			if(edge[now].get(i)!=from){
				cum=cum*(dp[edge[now].get(i)][1]+1)%m;
				fcum[now].add(cum);
			}
		}
		cum=1;
		for(int i=edge[now].size()-1; i>=0; i--){
			if(edge[now].get(i)!=from){
				cum=cum*(dp[edge[now].get(i)][1]+1)%m;
				bcum[now].add(cum);
			}
		}
	}
