	public static void main(String[] args) {
	    n = sc.nextInt();
	    m = sc.nextInt();
	    edges = new ArrayList[n+1];
	    ans = new long[n+1];
	    dp = new long[n+1];

	    for(int i=0;i<edges.length;++i) edges[i] = new ArrayList<>();
	    for(int i=1;i<n;++i) {
	    	int u = sc.nextInt();
	    	int v = sc.nextInt();
	    	edges[u].add(v);
	    	edges[v].add(u);
	    }

	    dfs(1,0);
	    reroot(1,0,1);
