/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) throws Exception {
        Thread thread = new Thread(null, new TaskAdapter(), "", 1 << 27);
        thread.start();
        thread.join();
    }

    static class TaskAdapter implements Runnable {
        @Override
        public void run() {
            InputStream inputStream = System.in;
            OutputStream outputStream = System.out;
            FastInput in = new FastInput(inputStream);
            FastOutput out = new FastOutput(outputStream);
            TaskV solver = new TaskV();
            solver.solve(1, in, out);
            out.close();
        }
    }

    static class TaskV {
        Modular mod;

        public void solve(int testNumber, FastInput in, FastOutput out) {
            int n = in.readInt();
            int m = in.readInt();
            mod = new Modular(m);
            Node[] nodes = new Node[n + 1];
            for (int i = 1; i <= n; i++) {
                nodes[i] = new Node();
            }
            for (int i = 1; i < n; i++) {
                Node a = nodes[in.readInt()];
                Node b = nodes[in.readInt()];
                a.next.add(b);
                b.next.add(a);
            }
            dfs(nodes[1], null);
            answer(nodes[1], null);
            for (int i = 1; i <= n; i++) {
                out.println(nodes[i].ans);
            }
        }

        public void dfs(Node root, Node p) {
            root.next.remove(p);
            for (Node node : root.next) {
                dfs(node, root);
            }
            root.dp[0] = 1;
            root.dp[1] = 1;
            for (Node node : root.next) {
                root.dp[1] = mod.mul(root.dp[1], mod.plus(node.dp[0], node.dp[1]));
            }
            for (Node node : root.next) {
                root.dp[2] = mod.plus(root.dp[2], mod.plus(node.dp[1], node.dp[2]));
            }
        }

        public void answer(Node root, Node p) {
            int dp1 = 1;
            int dp2 = 0;
            if (p != null) {
                dp1 = mod.plus(p.dp[0], p.dp[1]);
                dp2 = mod.plus(p.dp[1], p.dp[2]);
            }
            root.ans = mod.mul(root.dp[1], dp1);
            int originDp2 = mod.plus(root.dp[2], dp2);

            int[] pre = new int[root.next.size()];
            int[] post = new int[root.next.size()];
            for (int i = 0; i < root.next.size(); i++) {
                Node node = root.next.get(i);
                pre[i] = mod.plus(node.dp[0], node.dp[1]);
                if (i > 0) {
                    pre[i] = mod.mul(pre[i], pre[i - 1]);
                }
            }
            for (int i = root.next.size() - 1; i >= 0; i--) {
                Node node = root.next.get(i);
                post[i] = mod.plus(node.dp[0], node.dp[1]);
                if (i + 1 < root.next.size()) {
                    post[i] = mod.mul(post[i], post[i + 1]);
                }
            }
            for (int i = 0; i < root.next.size(); i++) {
                Node node = root.next.get(i);
                root.dp[1] = dp1;
                if (i > 0) {
                    root.dp[1] = mod.mul(root.dp[1], pre[i - 1]);
                }
                if (i + 1 < root.next.size()) {
                    root.dp[1] = mod.mul(root.dp[1], post[i + 1]);
                }
                root.dp[2] = mod.subtract(originDp2, mod.plus(node.dp[1], node.dp[2]));
                answer(node, root);
            }
        }

    }

    static class Node {
        List<Node> next = new ArrayList<>();
        int[] dp = new int[3];
        int ans;

    }

    static class FastOutput implements AutoCloseable, Closeable {
        private StringBuilder cache = new StringBuilder(10 << 20);
        private final Writer os;

        public FastOutput(Writer os) {
            this.os = os;
        }

        public FastOutput(OutputStream os) {
            this(new OutputStreamWriter(os));
        }

        public FastOutput println(int c) {
            cache.append(c).append('\n');
            return this;
        }

        public FastOutput flush() {
            try {
                os.append(cache);
                os.flush();
                cache.setLength(0);
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
            return this;
        }

        public void close() {
            flush();
            try {
                os.close();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        public String toString() {
            return cache.toString();
        }

    }

    static class Modular {
        int m;

        public Modular(int m) {
            this.m = m;
        }

        public Modular(long m) {
            this.m = (int) m;
            if (this.m != m) {
                throw new IllegalArgumentException();
            }
        }

        public Modular(double m) {
            this.m = (int) m;
            if (this.m != m) {
                throw new IllegalArgumentException();
            }
        }

        public int valueOf(int x) {
            x %= m;
            if (x < 0) {
                x += m;
            }
            return x;
        }

        public int valueOf(long x) {
            x %= m;
            if (x < 0) {
                x += m;
            }
            return (int) x;
        }

        public int mul(int x, int y) {
            return valueOf((long) x * y);
        }

        public int plus(int x, int y) {
            return valueOf(x + y);
        }

        public int subtract(int x, int y) {
            return valueOf(x - y);
        }

        public String toString() {
            return "mod " + m;
        }

    }

    static class FastInput {
        private final InputStream is;
        private byte[] buf = new byte[1 << 13];
        private int bufLen;
        private int bufOffset;
        private int next;

        public FastInput(InputStream is) {
            this.is = is;
        }

        private int read() {
            while (bufLen == bufOffset) {
                bufOffset = 0;
                try {
                    bufLen = is.read(buf);
                } catch (IOException e) {
                    bufLen = -1;
                }
                if (bufLen == -1) {
                    return -1;
                }
            }
            return buf[bufOffset++];
        }

        public void skipBlank() {
            while (next >= 0 && next <= 32) {
                next = read();
            }
        }

        public int readInt() {
            int sign = 1;

            skipBlank();
            if (next == '+' || next == '-') {
                sign = next == '+' ? 1 : -1;
                next = read();
            }

            int val = 0;
            if (sign == 1) {
                while (next >= '0' && next <= '9') {
                    val = val * 10 + next - '0';
                    next = read();
                }
            } else {
                while (next >= '0' && next <= '9') {
                    val = val * 10 - next + '0';
                    next = read();
                }
            }

            return val;
        }

    }
}

import java.io.*;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.StringJoiner;
import java.util.StringTokenizer;
import java.util.function.IntToLongFunction;

public class Main {

    static int N, M;
    static int[] X, Y;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        M = sc.nextInt();
        X = new int[N-1];
        Y = new int[N-1];
        for (int i = 0; i < N - 1; i++) {
            X[i] = sc.nextInt()-1;
            Y[i] = sc.nextInt()-1;
        }

        writeLines(solve());
    }

    static long[] solve() {
        int root = 0;
        int[][] G = adjB(N, X, Y);
        long[] dp = new long[N];
        for (Node node : orderFromLeaf(N, G, root)) {
            int b = 1;
            for (int next : G[node.a]) {
                if( next != node.parent ) {
                    b *= (dp[next]+1);
                    b %= M;
                }
            }
            dp[node.a] = b;
        }

        long[] ans = new long[N];
        long[][][] cp = new long[N][2][]; // 累積積
        for (Node node : orderFromRoot(N, G, root)) {
            calcCp(node.a, cp, G, no -> {
                if( no == node.parent ) {
                    return useCp(node, cp, G);
                } else {
                    return dp[no];
                }
            });
            ans[node.a] = cp[node.a][1][0];
        }

        return ans;
    }

    static long useCp(Node node, long[][][] cp, int[][] G) {
        long[] left = cp[node.parent][0];
        long[] right = cp[node.parent][1];

        int[] nodes = G[node.parent];
        for (int i = 0; i < nodes.length; i++) {
            if( nodes[i] == node.a ) {
                return left[i] * right[i+1] % M;
            }
        }
        throw new IllegalArgumentException("wtf");
    }

    static void calcCp(int a, long[][][] cp, int[][] G, IntToLongFunction nodeToCnt) {
        int[] nodes = G[a];
        int n = nodes.length;
        long[] cp_l = new long[n+1];
        cp_l[0] = 1;
        for (int i = 0; i < n; i++) {
            int next = nodes[i];
            cp_l[i+1] = cp_l[i] * (nodeToCnt.applyAsLong(next) + 1);
            cp_l[i+1] %= M;
        }
        long[] cp_r = new long[n+1];
        cp_r[n] = 1;
        for (int i = n-1; i >= 0; i--) {
            int next = nodes[i];
            cp_r[i] = cp_r[i+1] * (nodeToCnt.applyAsLong(next) + 1);
            cp_r[i] %= M;
        }
        cp[a][0] = cp_l;
        cp[a][1] = cp_r;
    }

    static int[][] adjB(int n, int[] from, int[] to) {
        int[][] adj = new int[n][];
        int[] cnt = new int[n];
        for (int f : from) {
            cnt[f]++;
        }
        for (int t : to) {
            cnt[t]++;
        }
        for (int i = 0; i < n; i++) {
            adj[i] = new int[cnt[i]];
        }
        for (int i = 0; i < from.length; i++) {
            adj[from[i]][--cnt[from[i]]] = to[i];
            adj[to[i]][--cnt[to[i]]] = from[i];
        }
        return adj;
    }

    static Node[] orderFromRoot(int N, int[][] G, int root) {
        ArrayDeque<Node> q = new ArrayDeque<>();
        Node[] ret = new Node[N];
        int idx = 0;
        q.add(new Node(-1, root));
        while(!q.isEmpty()) {
            Node n = q.poll();
            ret[idx++] = n;
            for (int next : G[n.a]) {
                if( next == n.parent ) continue;

                q.add(new Node(n.a, next));
            }
        }
        return ret;
    }

    static Node[] orderFromLeaf(int N, int[][] G, int root) {
        ArrayDeque<Node> q = new ArrayDeque<>();
        Node[] ret = new Node[N];
        int idx = N-1;
        q.add(new Node(-1, root));
        while(!q.isEmpty()) {
            Node n = q.poll();
            ret[idx--] = n;
            for (int next : G[n.a]) {
                if( next == n.parent ) continue;

                q.add(new Node(n.a, next));
            }
        }
        return ret;
    }

    static class Node {
        int parent, a;

        public Node(int parent, int a) {
            this.parent = parent;
            this.a = a;
        }
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) a[i] = nextInt();
            return a;
        }

        int[] nextIntArray(int n, int delta) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) a[i] = nextInt() + delta;
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++) a[i] = nextLong();
            return a;
