import java.io.*;
import java.util.*;

public class Main {
    public static void main(String args[]) throws Exception {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        N = sc.nextInt();
        mod = sc.nextInt();
        adjList = new ArrayList[N];
        for (int i = 0; i < N; i++) {
            adjList[i] = new ArrayList<>();
        }

        for (int i = 0; i < N - 1; i++) {
            int u = sc.nextInt() - 1;
            int v = sc.nextInt() - 1;
            adjList[u].add(v);
            adjList[v].add(u);
        }

        dpDown = new long[N];
        dpUp = new long[N];
        solveDown(0, 0);
        solveUp(0, 0);

        for (int i = 0; i < N; i++) {
            long ans = dpUp[i] * dpDown[i];
            ans %= mod;
            out.println(ans);
        }

        out.close();
    }

    static int N, mod;
    static ArrayList<Integer>[] adjList;
    static long[] dpUp;
    static long[] dpDown;
    // dpDown[node] stores the number of ways for a node's subtree to be colored
    // in a connected way, with node ALWAYS being colored
    // Transition: use all our children + 1, since each one can also be uncolored

    static long solveDown(int node, int par) {
        long ways = 1;
        for (int adj : adjList[node]) {
            if (adj != par) {
                ways *= (solveDown(adj, node) + 1);
                ways %= mod;
            }
        }
        return dpDown[node] = ways;
    }

    static void solveUp(int node, int par) {
        if (node == 0) {
            dpUp[node] = 1;
        }
        else {
            dpUp[node] = dpUp[par] * dpDown[par] / (dpDown[node] + 1) + 1;
            dpUp[node] %= mod;
        }
        for (int adj : adjList[node]) {
            if (adj != par) {
                solveUp(adj, node);
            }
        }
    }

