	//	System.out.println(map.get(cur));
		if(par!=-1)map.get(cur).remove(par);


		dp.put(cur, new long[map.get(cur).size()] );



		int i = 0 ;
  		for(int nbr : map.get(cur)) {
			if(nbr==par)continue;

			long temp = dfs(nbr ,cur)+1;

			temp%=m;
			dp.get(cur)[i] = temp;


			ans = (ans * temp)%m;
			i++;
		}
		 an[cur] = ans;

		 return ans;

	}
