	public long[][] mult(long[][] a, long[][] b) {
		int n = a.length;
		long[][] c = new long[n][n];
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < n; j++) {
				for (int k = 0; k < n; k++) {
					c[i][j] += a[i][k] * b[k][j];
					c[i][j] %= mod;
				}
			}
		}
		return c;
	}

	public long[][] pow(long[][] x, long p) {
		if (p == 0) {
			long[][] e = new long[x.length][x.length];
			for (int i = 0; i < e.length; i++) {
				e[i][i] = 1;
			}
			return e;
		}
		long[][] ans = pow(x, p / 2);
		ans = mult(ans, ans);
		if (p % 2 == 1) {
			ans = mult(ans, x);
		}
		return ans;
	}

	public void dfsUp(int v, int prev) {
		up[v] = BigInteger.ONE;
		for (int i : to[v]) {
			if (i != prev) {
				dfsUp(i, v);
				up[v] = up[v].multiply(up[i].add(BigInteger.ONE));
			}
		}
	}

	public void dfsAns(int v, int prev) {
		if (prev == -1) {
			ans[v] = up[v];
		} else {
			ans[v] = ans[prev].subtract(ans[prev].divide(up[v].add(BigInteger.ONE))).add(up[v]);
		}
		for (int i : to[v]) {
			if (i != prev) {
				dfsAns(i, v);
			}
		}
	}

