public class Main {
	static PrintWriter out;
	static StringBuilder sb;
	static int mod = 1000000007;
	static int inf = (int) 1e15;
	static ArrayList<Integer>[] ad;
	static int n, m;
	static long[] par, ans;

	public static void main(String[] args) throws Exception {
		Scanner sc = new Scanner(System.in);
		out = new PrintWriter(System.out);
		n = sc.nextInt();
		m = sc.nextInt();
		ad = new ArrayList[n];
		for (int i = 0; i < n; i++)
			ad[i] = new ArrayList<>();
		for (int i = 0; i < n - 1; i++) {
			int a = sc.nextInt() - 1;
			int b = sc.nextInt() - 1;
			ad[a].add(b);
			ad[b].add(a);
		}
		par = new long[n];
		ans = new long[n];
		dfs(0, -1);
		ans[0] = par[0];
//	System.out.println(Arrays.toString(par));
		reroot(0,-1);
		for(int i=0;i<n;i++)
			out.println(ans[i]%m);
		out.flush();
	}

	static void dfs(int u, int p) {
		par[u] = 1;
		for (int v : ad[u])
			if (v != p) {
				dfs(v, u);
				par[u] = par[u] * (par[v] + 1) ;
			}
	}

	static void reroot(int u, int p) {
		if (p != -1) {
			ans[u] = ans[p] /(par[u]+1);
			ans[u]=(ans[u]+1)*par[u];
		}
		for (int v : ad[u])
			if (v != p)
				reroot(v, u);
	}

	static long modPow(long a, long e)

	{
		long res = 1;
		while (e > 0) {
			if ((e & 1) == 1)
				res = (res * a) % mod;
			a = (a * a) % mod;
			e >>= 1;
		}
		return res;
	}

