			for(int i=0;i<li[a].Count;i++){
				if(li[a][i]!=p){
					hs[a].Add(li[a][i],Fu(li[a][i],a)+1);
					mm[a]*=hs[a][li[a][i]];
				}
			}
			return mm[a];
		}
		else if(c[a]==p){return mm[a];}
		else{
			hs[a].Add(c[a],Fu(c[a],a)+1);
			mm[a]*=hs[a][c[a]];
			c[a]=-1;
			return mm[a]/hs[a][p];
		}
	}
}

