internal partial class Solver {
    public void Run() {
        var n = ni();
        var m = ni();
        var adj = Enumerable.Range(0, n).Select(_ => new List<int>()).ToArray();
        for (int i = 0; i < n - 1; i++) {
            var x = ni() - 1;
            var y = ni() - 1;
            adj[x].Add(y);
            adj[y].Add(x);
        }

        var pattern = new long?[n];
        var parent = new int[n];

        Func<int, int, long> dfs = null;
        dfs = (pos, par) => {
            parent[pos] = par;
            long ret = 1;

            foreach (var c in adj[pos]) {
                if (c == par) continue;
                ret *= (dfs(c, pos) + 1);
                ret %= m;
            }
            pattern[pos] = ret;
            return ret;
        };
        dfs(0, -1);

        var ans = new long[n];

        Action<int, int, long> dfs2 = null;
        dfs2 = (pos, par, dparent) => {
            long ret = 1 + dparent;

            var v = new List<Tuple<int, long>>();

            foreach (var c in adj[pos]) {
                if (c == par) continue;
                var p = 1 + pattern[c].Value;
                v.Add(Tuple.Create(c, p));
                ret *= p;
                ret %= m;
            }
            if (v.Count > 0) {
                var left = new long[v.Count];
                var right = new long[v.Count];

                for (int i = 0; i < left.Length; i++) {
                    left[i] = v[i].Item2;
                    if (i - 1 >= 0) left[i] *= left[i - 1];
                    left[i] %= m;
                }

                for (int i = right.Length - 1; i >= 0; i--) {
                    right[i] = v[i].Item2;
                    if (i + 1 < right.Length) right[i] *= right[i + 1];
                    right[i] %= m;
                }

                for (int i = 0; i < v.Count; i++) {
                    var c = v[i].Item1;
                    var d = 1 + dparent;
                    if (i - 1 >= 0) { d *= left[i - 1]; d %= m; }
                    if (i + 1 < right.Length) { d *= right[i + 1]; d %= m; }
                    dfs2(c, pos, d);
                }
            }
            ans[pos] = ret % m;
        };

        dfs2(0, -1, 0);

        cout.WriteLine(string.Join("\n", ans));
    }
}

