        {
            Cin.Input(out int N, out long M);
            var G = new List<List<int>>();
            for (var i = 0; i < N; i++) G.Add(new List<int>());
            for(var i = 0; i < N - 1; i++)
            {
                Cin.Input(out int a, out int b);
                a--;b--;
                G[a].Add(b);
                G[b].Add(a);
            }
            var dp = new long[N];
            long dfs1(int v,int pre)
            {
                if (dp[v] != 0) return dp[v];
                long ret = 1;
                foreach(var nx in G[v])
                {
                    if (nx == pre) continue;
                    ret = (ret * (dfs1(nx, v) + 1)) % M;
                }
                dp[v] = ret;
                return ret;
            }
            var ans = new long[N];
            ans[0] = dfs1(0, -1);
