            {
                //OutL($"v={v},pre={pre},cum={cum}");
                long ret = 1;
                foreach(var nx in G[v])
                {
                    if (nx == pre)
                    {
                        ret = (ret * (cum + 1)) % M;
                    }
                    else
                    {
                        ret = (ret * (dp[nx] + 1)) % M;
                    }
                }
                ans[v] = ret;
                int L = G[v].Count();
                var sum_front = new long[L + 1];
                var sum_back = new long[L + 1];
                sum_front[0] = 1;
                sum_back[0] = 1;
                int itr = 0;
                for(var i = 0; i < L; i++)
                {
                    if (G[v][i] == pre) continue;
                    sum_front[itr + 1] = (sum_front[itr] * (dp[G[v][i]] + 1)) % M;
                    itr++;
                }
                itr = 0;
                for(var i = 0; i < L; i++)
                {
                    if (G[v][L - 1 - i] == pre) continue;
                    sum_back[itr + 1] = (sum_back[i] * (dp[G[v][L - 1 - i]] + 1)) % M;
                    itr++;
                }
                itr = 0;
                for(var i = 0; i < L; i++)
                {
                    if (G[v][i] == pre) continue;
                    dfs2(G[v][i], v, (sum_front[itr] * sum_back[L - 1 - itr]) % M);
                    itr++;
                }
            }
            dfs2(0, -1, -1);
            Out_Sep(ans, "\n");
        }
