        for (int i = 0; i < c; i++)
        {
            if (edge[p][i] == par) {
                continue;
            }
            a[i] = dfs(edge[p][i], p) % m;
            memo[edge[p][i]] = a[i];
        }
        var mull = new long[c + 1];
        var mulr = new long[c + 1];
        mull[0] = 1;
