class K
{
	int[] G => ReadLine().Split().Select(int.Parse).ToArray();
	public K()
	{
		SetOut(new StreamWriter(OpenStandardOutput()) { AutoFlush = false });
		Solve();
		Out.Flush();
	}
	int V, Mod;
	List<int>[] es;
	void Solve()
	{
		var I = G;
		V = I[0];
		Mod = I[1];
		es = new List<int>[V];
		for (var u = 0; u < V; u++) es[u] = new List<int>();
		for (var e = 0; e < V - 1; e++)
		{
			I = G;
			es[I[0] - 1].Add(I[1] - 1);
			es[I[1] - 1].Add(I[0] - 1);
		}
		var dp0 = DFS0(0, V);
		var dp1 = DFS1(0, dp0);
		for (var u = 0; u < V; u++) WriteLine(dp0[u] * (dp1[u] + 1) % Mod);
	}
	long[] DFS0(int u, int p)
	{
		var dp = new long[V];
		var st = new Stack<A0>();
		st.Push(new A0(u, p));
		while (st.Count > 0)
		{
			var f = st.Pop();
			if (f.p >= 0)
			{
				dp[f.u] = 1L;
				es[f.u].Remove(f.p);
				if (es[f.u].Count == 0) continue;
				st.Push(new A0(f.u, -1));
				foreach (var v in es[f.u]) st.Push(new A0(v, f.u));
			}
			else foreach (var v in es[f.u]) dp[f.u] = dp[f.u] * (dp[v] + 1) % Mod;
		}
		return dp;
	}
	long[] DFS1(int u, long[] dp0)
	{
		var dp = new long[V];
		var st = new Stack<int>();
		st.Push(u);
		var y = new long[V];
		while (st.Count > 0)
		{
			u = st.Pop();
			var W = es[u].Count;
			if (W == 0) continue;
			y[W - 1] = 1;
			for (var i = W - 2; i >= 0; i--) y[i] = y[i + 1] * (dp0[es[u][i + 1]] + 1) % Mod;
			var x = 1L;
			for (var i = 0; i < W; i++)
			{
				dp[es[u][i]] = (dp[u] + 1) * x % Mod * y[i + 1] % Mod;
				x = x * (dp0[es[u][i]] + 1) % Mod;
			}
			foreach (var v in es[u]) st.Push(v);
		}
		return dp;
	}
}
