        {
            for (int j = 0; j < 2; j++)
            {
                dp[i, j] = -1;
            }
        }

        for (int i = 0; i < N; i++)
        {
            long p = 1;
            foreach (var e2 in es[i])
            {
                if (A[e2] == i) p *= (dfs(e2, 0) + 1);
                else p *= dfs(e2, 1) + 1;
                p %= mod;

            }
            Console.WriteLine(p);
        }

    }


    long dfs(int e, int t)
    {
