            }
            for (var i = 0; i < N - 1; ++i)
            {
                var t = Sarray();
                --t[0];--t[1];
                a[t[0]].Add(t[1]);
                a[t[1]].Add(t[0]);
                dpedge[t[0]].Add(1);
                dpedge[t[1]].Add(1);
            }

