        for (int i = 0; i < N; i++)
        {
            long p = 1;
            foreach (var e2 in es[i])
            {
                if (A[e2] == i) p *= (dfs(e2, 0) + 1);
                else p *= dfs(e2, 1) + 1;
                p %= mod;

            }
            Console.WriteLine(p);
        }

    }

    long dfs(int e, int t)
    {
        if (dp[e, t] != 0) return dp[e, t];
        int pre, a;
        if (t == 0)
        {
            pre = A[e];
            a = B[e];
        }
        else
        {
            pre = B[e];
            a = A[e];
        }

        long p = 1;
        foreach (var e2 in es[a])
        {
            if (e2 == e) continue;
            if (A[e2] == a) p *= (dfs(e2, 0) + 1);
            else p *= dfs(e2, 1) + 1;
            p %= mod;

        }
        return dp[e, t] = p;
    }



