            public void Dfs1(Vertex parent, long mod)
            {
                ChildrenCount = Edges.Count - (parent == null ? 0 : 1);
                Value = 1;
                if (ChildrenCount > 0)
                {
                    GroupSize = (int) Math.Sqrt(ChildrenCount);
                    GroupsCount = (ChildrenCount + GroupSize - 1) / GroupSize;

                    ChildrenValues = new long[ChildrenCount];
                    // GroupValues = Enumerable.Repeat(1L, GroupsCount).ToArray();
                    OuterGroupValues = Enumerable.Repeat(1L, GroupsCount).ToArray();

                    int index = 0;
                    foreach (Vertex vertex in Edges)
                    {
                        if (vertex != parent)
                        {
                            vertex.Dfs1(this, mod);

                            long multValue = vertex.Value + 1;

                            ChildrenValues[index] = multValue % mod;

                            int groupId = index / GroupSize;
                            for (int i = 0; i < GroupsCount; i++)
                            {
                                if (i != groupId)
