                                    OuterGroupValues[i] = OuterGroupValues[i] * multValue % mod;
                                }
                            }
                            // GroupValues[groupId] = GroupValues[groupId] * (vertex.Value + 1) % mod;

                            Value = Value * multValue % mod;

                            index++;
                        }
                    }
                }
            }

            public void Dfs2(Vertex parent, long upValue, long mod)
            {
                Answer = Value * upValue % mod;

                int index = 0;
                foreach (Vertex vertex in Edges)
                {
                    if (vertex != parent)
                    {
                        int groupId = index / GroupSize;

                        long vUp = upValue * OuterGroupValues[groupId] % mod;

                        int childMaxId = Math.Min((groupId + 1) * GroupSize, ChildrenCount);
                        for (int i = groupId * GroupSize; i < childMaxId; i++)
                        {
                            if (i != index)
                            {
                                vUp = vUp * ChildrenValues[i] % mod;
                            }
                        }

                        vUp++;
                        if (vUp >= mod)
                        {
                            vUp -= mod;
                        }

                        vertex.Dfs2(this, vUp, mod);

                        index++;
                    }
                }
            }
