class Program{
	const int mod=1000000007;
	static List<int>[] li;
	static long[][] dp;
	static void Main(){
		int[] s=Array.ConvertAll(Console.ReadLine().Split(),int.Parse);
		int n=s[0];
		long[] ans=new long[n];
		li=new List<int>[n+1];
		dp=new long[n+1][];
		for(int i=1;i<=n;i++){li[i]=new List<int>();}
		for(int i=0;i<n-1;i++){
			int[] q=Array.ConvertAll(Console.ReadLine().Split(),int.Parse);
			li[q[0]].Add(q[1]);
			li[q[1]].Add(q[0]);
		}
		for(int i=1;i<=n;i++){dp[i]=new long[li[i].Count];}
		for(int i=1;i<=n;i++){ans[i-1]=Fu(i,0)%s[1];}
		Console.WriteLine(String.Join("\n",ans));
	}
	static long Fu(int a,int p){
		long q=1;
		for(int i=0;i<li[a].Count;i++){
			if(li[a][i]!=p){
				if(dp[a][i]==0){dp[a][i]=Fu(li[a][i],a)+1;}
				q*=dp[a][i];
			}
		}
		return q;
	}
	static long Mi(long a){
		long b=mod,u=1,v=0;
		while(b>0){
			long t=a/b;
			a-=t*b;a^=b;b^=a;a^=b;
			u-=t*v;u^=v;v^=u;u^=v;
		}
		u%=mod;
		if(u<0){u+=mod;}
		return u%mod;
	}
}

