        }

        for (int i = 0; i < N; i++)
        {
            if (G[u][i] == p)
            {
                continue;
            }
            dp[u] = 1;
            if (0 <= i - 1)
            {
                dp[u] *= L[i - 1];
                dp[u] %= mod;
            }
            if (i + 1 < N)
            {
                dp[u] *= R[i + 1];
                dp[u] %= mod;
            }
            zenhoui(G[u][i], u);
        }
    }
