		Solve();
		Out.Flush();
	}
	int V, Mod;
	List<int>[] es;
	void Solve()
	{
		var I = G;
		V = I[0];
		Mod = I[1];
		es = new List<int>[V];
		for (var u = 0; u < V; u++) es[u] = new List<int>();
		for (var e = 0; e < V - 1; e++)
		{
			I = G;
			es[I[0] - 1].Add(I[1] - 1);
			es[I[1] - 1].Add(I[0] - 1);
		}
		// var par = DFS1Exe(0, -1);
		var dp0 = DFS2Exe(0, -1);
		var dp1 = DFS3Exe(0, dp0);
		for (var u = 0; u < V; u++) WriteLine(dp0[u] * (dp1[u] + 1) % Mod);
	}
	int[] DFS1Exe(int u, int p)
	{
		var par = new int[V];
		var st = new Stack<object>();
		st.Push(new A0 { u = u, p = p });
		while (st.Count > 0)
		{
			var f = st.Pop();
			if (f is A0)
			{
				var g = (A0)f;
				es[g.u].Remove(par[g.u] = g.p);
				st.Push(new A1 { u = g.u, p = g.p, i = 0 });
			}
			else
			{
				var g = (A1)f;
				if (g.i < es[g.u].Count)
				{
					st.Push(new A1 { u = g.u, p = g.p, i = g.i + 1 });
					st.Push(new A0 { u = es[g.u][g.i], p = g.u });
				}
			}
		}
		return par;
	}
	long[] DFS2Exe(int u, int p)
	{
		var dp0 = new long[V];
		var st = new Stack<object>();
		st.Push(new B0 { u = u, p = p });
		while (st.Count > 0)
		{
			var f = st.Pop();
			if (f is B0)
			{
				var g = (B0)f;
				dp0[g.u] = 1L;
				es[g.u].Remove(g.p);
				st.Push(new B1 { u = g.u, i = 0 });
			}
			else if (f is B1)
			{
				var g = (B1)f;
				if (g.i < es[g.u].Count)
				{
					st.Push(new B2 { u = g.u, p = g.p, i = g.i });
					st.Push(new B0 { u = es[g.u][g.i], p = g.u });
				}
			}
			else
			{
				var g = (B2)f;
				dp0[g.u] = dp0[g.u] * (dp0[es[g.u][g.i]] + 1) % Mod;
				st.Push(new B1 { u = g.u, p = g.p, i = g.i + 1 });
			}
		}
		return dp0;
	}
	long[] DFS3Exe(int u, long[] dp0)
	{
		var dp1 = new long[V];
		var st = new Stack<object>();
		st.Push(new C0 { u = u });
		while (st.Count > 0)
		{
			var f = st.Pop();
			if (f is C0)
			{
				var g = (C0)f;
				var W = es[g.u].Count;
				var x = new long[W + 1];
				var y = new long[W + 1];
				x[0] = y[W] = 1;
				for (var i = 0; i < W; i++) x[i + 1] = x[i] * (dp0[es[g.u][i]] + 1) % Mod;
				for (var i = W - 1; i >= 0; i--) y[i] = y[i + 1] * (dp0[es[g.u][i]] + 1) % Mod;
				for (var i = 0; i < W; i++) dp1[es[g.u][i]] = (dp1[g.u] + 1) * x[i] % Mod * y[i + 1] % Mod;
				x = y = null;
				st.Push(new C1 { u = g.u, i = 0 });
			}
			else
			{
				var g = (C1)f;
				if (g.i < es[g.u].Count)
				{
					st.Push(new C1 { u = g.u, i = g.i + 1 });
					st.Push(new C0 { u = es[g.u][g.i] });
				}
			}
		}
		return dp1;
	}
}
