using System.Text;//テキストの高速出力に必要
class Program
{
static string[] input = Console.ReadLine().Split(' ');
static int n = int.Parse(input[0]);
static long m = long.Parse(input[1]);
static List<int>[] nextList = new List<int>[n];//隣接リスト（リストの入った配列）
static long[] dp = new long[n];
static int[] lookedVertex = new int[n];

	static void Main()
	{
    for(int i = 0; i < n; i++)
    {
      nextList[i] = new List<int>();//リストの宣言
      dp[i] = -1;
    }
    for(int i = 0; i < n-1; i++)
    {
      int[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),int.Parse);
      nextList[nums[0]-1].Add(nums[1]-1);//隣接リストへ追加。
      nextList[nums[1]-1].Add(nums[0]-1);
    }

		Console.WriteLine(DP(0)%m);
	}

  static long DP(int vertexNum)
  {
    if(dp[vertexNum] != -1) return dp[vertexNum];

    dp[vertexNum] = 1;
    lookedVertex[vertexNum] = 1;//木の逆走を防ぐ

    for(int i = 0; i < nextList[vertexNum].Count; i++)
    {
      int partnerNum = nextList[vertexNum][i];
      if(lookedVertex[partnerNum] == 0)//木の逆走を防ぐ
      {
        dp[vertexNum] *= 1+DP(partnerNum);
        dp[vertexNum] %= m;
      }
    }
    //Console.WriteLine(vertexNum+" "+dp[vertexNum]);
    return dp[vertexNum];
  }
}

