namespace AtCoder.DP
{
    class EDPC_V
    {
        public class Node
        {
            public int Parent;
            public List<int> Next;
            public Node()
            {
                Next = new List<int>();
            }
        }

        public static int[] GetSortedTreeNodeIndex(int root, Node[] nodes)
        {
            int[] sorted = new int[nodes.Length];
            var queue = new Queue<int>();
            queue.Enqueue(root);
            int count = 0;
            while (queue.Any())
            {
                var i = queue.Dequeue();
                sorted[count++] = i;
                foreach (var next in nodes[i].Next)
                {
                    if (next == nodes[i].Parent)
                        continue;
                    nodes[next].Parent = i;
                    queue.Enqueue(next);
                }
            }
            return sorted;
        }

        public static void Main()
        {
            var nm = Console.ReadLine().Split(' ').Select(i => int.Parse(i)).ToArray();
            var n = nm[0];
            var m = nm[1];
            if (n == 1)
            {
                Console.WriteLine(1);
                return;
            }

            var nodes = new Node[n];

            for (int i = 0; i < n - 1; i++)
            {
                var xy = Console.ReadLine().Split(' ').Select(j => int.Parse(j) - 1).ToArray();
                if (nodes[xy[0]] == null)
                    nodes[xy[0]] = new Node();
                if (nodes[xy[1]] == null)
                    nodes[xy[1]] = new Node();
                nodes[xy[0]].Next.Add(xy[1]);
                nodes[xy[1]].Next.Add(xy[0]);
            }

            var sortedIndex = GetSortedTreeNodeIndex(0, nodes); // メモ化再帰だとStackOverflowの可能性

            nodes[0].Parent = -1;
            nodes[0].Next.Add(-1);
            var dpf = new long[n]; // Forward
            for (int i = n - 1; i >= 0; i--)
            {
                int j = sortedIndex[i];
                dpf[j] = 1;
                if (nodes[j].Next.Count == 1)
                    continue;
                foreach (var next in nodes[j].Next)
                {
                    if (next == nodes[j].Parent)
                        continue;
                    dpf[j] = dpf[j] * (dpf[next] + 1) % m;
                }
            }

            var cumprodL = new long[n + 2];
            var cumprodR = new long[n + 2];
            var dpr = new long[n]; // Reverse
            dpr[0] = 1;
            for (int i = 0; i < n; i++)
            {
                int j = sortedIndex[i];
                var next = nodes[j].Next;

                cumprodL[0] = 1;
                cumprodR[next.Count] = 1;
                for (int l = 0; l < next.Count; l++)
                {
                    int r = next.Count - l;
                    cumprodL[l + 1] = cumprodL[l];
                    cumprodR[r - 1] = cumprodR[r];
                    if (next[l] != nodes[j].Parent)
                        cumprodL[l + 1] = cumprodL[l + 1] * (dpf[next[l]] + 1) % m;
                    if (next[r - 1] != nodes[j].Parent)
                        cumprodR[r - 1] = cumprodR[r - 1] * (dpf[next[r - 1]] + 1) % m;
                }

                for (int k = 0; k < next.Count; k++)
                    if (next[k] != nodes[j].Parent)
                        dpr[next[k]] = (cumprodL[k] * cumprodR[k + 1] % m * dpr[j] + 1) % m;
            }

            Console.WriteLine(dpf[0]);
            for (int i = 1; i < n; i++)
                Console.WriteLine(dpf[i] * dpr[i]);
        }

    }
}

