        static public List<long> Slist() { return ReadLine().Split().Select(long.Parse).ToList(); }

        static readonly long Mod = 1000000000 + 7;
        static void Main(string[] args)
        {
            var NM = Sarray();
            N = NM[0];
            M = NM[1];
            a = new int[N].Select(_ => new List<long>()).ToArray();
            for (var i = 0; i < N - 1; ++i)
            {
                var t = Sarray();
                a[t[0] - 1].Add(t[1] - 1);
                a[t[1] - 1].Add(t[0] - 1);
            }
            dpnode = new int[N].Select(_ => 1L).ToArray();
            dpedge = new int[N].Select(_ => new List<long>()).ToArray();
            parent = new long[N];

            dfs(0, -1);
            dpa = new int[N].Select(_ => 1L).ToArray();
            ruil = new long[2 * N + 1];
            ruir = new long[2 * N + 1];

            dfs3(0, -1, 0, 0);
            for (var i = 0; i < N; ++i)
                WriteLine(dpnode[i]);
        }
        static List<long>[] a;
        static long N;
        static long M;
        static long[] dpnode;
        static long[] dpa;
        static List<long>[] dpedge;
        static long[] parent;
        static void dfs(long v, long p)
        {
            var cnt = 0;
            parent[v] = p;
            foreach (var n in a[v])
            {
                if (n == p)
                {
                    dpedge[v].Add(1);
                    continue;
                }
                cnt++;
                dfs(n, v);
                dpedge[v].Add((dpnode[n] + 1) % M);
                dpnode[v] = dpnode[v] * (dpnode[n] + 1) % M;
            }
        }
        static long[] ruil;
        static long[] ruir;
        static void dfs3(long v, long p, long pv, long s)//pv:親の情報
        {
            var num = a[v].Count;

            for (var i = 0; i < num; ++i)
                if (p == a[v][i])
                {
                    dpedge[v][i] = (pv + 1) % M;
                    break;
                }
            ruil[s] = 1;
            ruir[s] = 1;
            for (var i = 0; i < num; ++i)
            {
                ruil[s + i + 1] = ruil[s + i] * dpedge[v][i] % M;
                ruir[s + i + 1] = ruir[s + i] * dpedge[v][num - i - 1] % M;
            }
            dpnode[v] = ruil[s + num];
            for (var i = 0; i < num; ++i)
            {
                if (a[v][i] == p)
                    continue;
                dfs3(a[v][i], v, ruil[s + i] * ruir[s + num - i - 1], s + num + 1);
            }
        }
    }
}

