class Program
{
    static StreamWriter sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
    static Scan sc = new Scan();
    const int M = 1000000007;
    const int M2 = 998244353;
    const long LM = (long)1e18;
    const double eps = 1e-11;
    static readonly int[] dd = { 0, 1, 0, -1, 0 };
    const string dstring = "RDLU";
    static void Main()
    {
        int n;
        sc.Multi(out n, out m);
        edge = new List<int>[n];
        ans = new long[n];
        parc = new long[n];
        rem = new long[n];
        memo = new long[n];
        for (int i = 0; i < n; i++)
        {
            edge[i] = new List<int>();
        }
        for (int i = 0; i < n - 1; i++)
        {
            int a, b;
            sc.Multi(out a, out b);
            --a;
            --b;
            edge[a].Add(b);
            edge[b].Add(a);
        }
        var r = new Random();
        int p = r.Next(n);
        ans[p] = dfs(p, -1);
        dfs2(p, -1);
        foreach (var item in ans)
        {
            Prt(item);
        }
        sw.Flush();
    }
    static int m;
    static List<int>[] edge;
    static long[] ans, parc, rem, memo;
    static long dfs(int p, int par) {
        int c = edge[p].Count;
        var a = new long[c];
        for (int i = 0; i < c; i++)
        {
            if (edge[p][i] == par) {
                continue;
            }
            a[i] = dfs(edge[p][i], p);
            memo[edge[p][i]] = a[i];
        }
        var mull = new long[c + 1];
        var mulr = new long[c + 1];
        mull[0] = 1;
        mulr[c] = 1;
        for (int i = 0; i < c; i++)
        {
            mull[i + 1] = mull[i] * (a[i] + 1) % m;
            mulr[c - i - 1] = mulr[c - i] * (a[c - i - 1] + 1) % m;
        }
        for (int i = 0; i < c; i++)
        {
            if (edge[p][i] == par) continue;
            rem[edge[p][i]] = mull[i] * mulr[i + 1] % m;
            // parc[edge[p][i]] = parc[p] * mull[i] % m * mulr[i + 1] % m;
            // ans[edge[p][i]] = a[i] * (1 + parc[edge[p][i]]) % m;
        }
        return mull[c];
    }
    static void dfs2(int p, int par) {
        foreach (var item in edge[p])
        {
            if (item == par) continue;
            parc[item] = ((parc[p] + 1) * rem[item]) % m;
            ans[item] = memo[item] * (1 + parc[item]) % m;
            dfs2(item, p);
        }
    }

