		var cs = es[u].ToList();
		foreach (var v in cs) t.Add(Calc0(v) + 1);
		var seg = new SegmentTree(t);
		for (var i = 0; i < cs.Count; i++) dp1[cs[i]] = (dp1[u] + 1) * seg.Product(0, i) % Mod * seg.Product(i + 1, cs.Count) % Mod;
		foreach (var v in cs) DFS2(v);
	}
	void DFS(int u, int p)
	{
		par[u] = p;
		es[u].Remove(p);
		foreach (var v in es[u]) DFS(v, u);
	}
}
class SegmentTree
{
	public static int Mod;
	readonly int N2;
	readonly long[] segtree;
	public SegmentTree(int N) : this(new long[N]) { }
	public SegmentTree(IList<long> array)
	{
		N2 = 1;
		while (N2 < array.Count) N2 <<= 1;
		segtree = new long[2 * N2 - 1];
		for (var i = 0; i < 2 * N2 - 1; i++) segtree[i] = 1;
		for (var i = 0; i < array.Count; i++) segtree[i + N2 - 1] = array[i] % Mod;
		for (var i = N2 - 2; i >= 0; i--) segtree[i] = segtree[2 * i + 1] * segtree[2 * i + 2] % Mod;
	}
	public long Product(int from, int to) => Product(from, to, 0, 0, N2);
	long Product(int from, int to, int node, int l, int r)
	{
		if (to <= l || r <= from) return 1;
		if (from <= l && r <= to) return segtree[node];
		return Product(from, to, 2 * node + 1, l, (l + r) >> 1) * Product(from, to, 2 * node + 2, (l + r) >> 1, r) % Mod;
	}
}

using System.Collections.Generic;
