	int V, Mod;
	List<int>[] es;
	long[] dp0, dp1;
	void Solve()
	{
		var I = G;
		V = I[0];
		Mod = I[1];
		es = new List<int>[V];
		dp0 = new long[V];
		dp1 = new long[V];
		for (var u = 0; u < V; u++) es[u] = new List<int>();
		for (var e = 0; e < V - 1; e++)
		{
			I = G;
			es[I[0] - 1].Add(I[1] - 1);
			es[I[1] - 1].Add(I[0] - 1);
		}
		DFS0(0, -1);
		DFS1(0);
		for (var u = 0; u < V; u++) WriteLine(dp0[u] * (dp1[u] + 1) % Mod);
	}
	long DFS0(int u, int p)
	{
		dp0[u] = 1L;
		es[u].Remove(p);
		foreach (var v in es[u]) dp0[u] = dp0[u] * (DFS0(v, u) + 1) % Mod;
		return dp0[u];
	}
	void DFS1(int u)
	{
		var W = es[u].Count;
		var x = new long[W + 1];
		var y = new long[W + 1];
		x[0] = y[W] = 1;
		for (var i = 0; i < W; i++) x[i + 1] = x[i] * (dp0[es[u][i]] + 1) % Mod;
		for (var i = W - 1; i >= 0; i--) y[i] = y[i + 1] * (dp0[es[u][i]] + 1) % Mod;
		for (var i = 0; i < W; i++) dp1[es[u][i]] = (dp1[u] + 1) * x[i] % Mod * y[i + 1] % Mod;
		x = y = null;
		foreach (var v in es[u]) DFS1(v);
	}
