internal partial class Solver {
    public void Run() {
        var n = ni();
        var m = ni();
        var adj = Enumerable.Range(0, n).Select(_ => new List<int>()).ToArray();
        for (int i = 0; i < n - 1; i++) {
            var x = ni() - 1;
            var y = ni() - 1;
            adj[x].Add(y);
            adj[y].Add(x);
        }

        var pattern = new long[n];

        Func<int, int, long> dfs = null;
        dfs = (pos, par) => {
            long ret = 1;

            foreach (var c in adj[pos]) {
                if (c == par) continue;
                ret *= (dfs(c, pos) + 1);
                ret %= m;
            }
            pattern[pos] = ret;
            return ret;
        };
        dfs(0, -1);

        var ans = new long?[n];

        var st = new Stack<Tuple<int, int, long>>();

        st.Push(Tuple.Create(0, -1, 0L));

        while (st.Count > 0) {
            var pos = st.Peek().Item1;
            var par = st.Peek().Item2;
            var dparent = st.Peek().Item3;
            st.Pop();

            var v = new List<Tuple<int, long>>(adj[pos].Count);

            foreach (var c in adj[pos]) {
                if (c == par) {
                    v.Add(Tuple.Create(c, 1 + dparent));
                } else {
                    var p = 1 + pattern[c];
                    v.Add(Tuple.Create(c, p));
                }
            }
            var left = new long[v.Count];
            var right = new long[v.Count];

            for (int i = 0; i < left.Length; i++) {
                left[i] = v[i].Item2;
                if (i - 1 >= 0) left[i] *= left[i - 1];
                left[i] %= m;
            }

            for (int i = right.Length - 1; i >= 0; i--) {
                right[i] = v[i].Item2;
                if (i + 1 < right.Length) right[i] *= right[i + 1];
                right[i] %= m;
            }

            for (int i = 0; i < v.Count; i++) {
                var c = v[i].Item1;
                if (c == par) continue;
                var d = 1L;
                if (i - 1 >= 0) { d *= left[i - 1]; d %= m; }
                if (i + 1 < right.Length) { d *= right[i + 1]; d %= m; }
                st.Push(Tuple.Create(c, pos, d));
            }
            if (ans[pos].HasValue) throw new Exception();
            ans[pos] = (left.Length == 0 ? 1 : left[v.Count - 1]) % m;
        }

        cout.WriteLine(string.Join("\n", ans));
    }
}

