            R[i] = R[i + 1] * (dp[G[u][i]] + 1);
            R[i] %= M;
        }

        for (int i = 0; i < N; i++)
        {
            if (G[u][i] == p)
            {
                continue;
            }
            dp[u] = 1;
            if (0 <= i - 1)
            {
                dp[u] *= L[i - 1];
                dp[u] %= mod;
            }
            if (i + 1 < N)
            {
                dp[u] *= R[i + 1];
                dp[u] %= mod;
            }
            zenhoui(G[u][i], u);
        }
    }
    void solve()
    {
        int N = cin.nextint;
        if (N == 1)
        {
            WriteLine(1);
            return;
        }
        M = cin.nextint;
        G = new List<int>[N];
        for (int i = 0; i < N; i++)
        {
            G[i] = new List<int>();
        }
        for (int i = 0; i < N - 1; i++)
        {
            int a = cin.nextint - 1;
            int b = cin.nextint - 1;
            G[a].Add(b);
            G[b].Add(a);
        }
        dp = new long[N];
        calc(0, -1);
        ans = new long[N];
        zenhoui(0, -1);
        foreach (var item in ans)
        {
            WriteLine(item);
        }  
    }

}


