        static public List<long> Slist() { return ReadLine().Split().Select(long.Parse).ToList(); }

        static readonly long Mod = 1000000000 + 7;
        static void Main(string[] args)
        {
            var NM = Sarray();
            N = NM[0];
            M = NM[1];
            a = new int[N].Select(_ => new List<long>()).ToArray();
            for (var i = 0; i < N - 1; ++i)
            {
                var t = Sarray();
                a[t[0] - 1].Add(t[1] - 1);
                a[t[1] - 1].Add(t[0] - 1);
            }
            dpnode = new int[N].Select(_ => 1L).ToArray();
            dpoyaof = new long[N];

            dfs(0, -1);
            dpoyaof[0] = 1;
            dfs3(0);
            SetOut(new StreamWriter(OpenStandardOutput()) { AutoFlush = false });
            for (var i = 0; i < N; ++i)
                WriteLine(dpoyaof[i] * dpnode[i] % M);
            Out.Flush();
        }
        static List<long>[] a;
        static long N;
        static long M;
        static long[] dpnode;
        static long[] dpoyaof;
        static void dfs(long v, long p)
        {
            a[v].Remove(p);
            foreach (var n in a[v])
            {
                dfs(n, v);
                dpnode[v] = dpnode[v] * (dpnode[n] + 1) % M;
            }
