class Solver
{
    List<int>[] g;
    ModInt[] dp, res;
    public void Solve(Scanner sc)
    {
        int N, M;
        sc.Make(out N, out M);
        ModInt.MOD = M;
        g = Create(N, () => new List<int>());
        for (int i = 0; i < N-1; i++)
        {
            int x, y;
            sc.Make(out x, out y);
            x--;y--;
            g[x].Add(y);g[y].Add(x);
        }
        dp = new ModInt[N];
        res = new ModInt[N];
        dfs(0, -1);
        calc();
        Console.WriteLine(string.Join("\n", res));
    }
    ModInt dfs(int i,int p)
    {
        ModInt rt = 1;
        foreach (var e in g[i])
            if (e != p)
            {
                rt *= dfs(e, i) + 1;
            }
        return dp[i] = rt;
    }
    void calc()
    {
        Queue<Pair<int, int, ModInt>> Q=new Queue<Pair<int, int, ModInt>>();
        Q.Enqueue(new Pair<int, int, ModInt>(0, -1, 0));
        while (Q.Any())
        {
            int i = Q.Peek().v1, p = Q.Peek().v2;var now = Q.Dequeue().v3;
            res[i] = (now + 1) * dp[i];
            ModInt[] L = new ModInt[g[i].Count + 1]; L[0] = 1;
            for (int j = 0; j < g[i].Count; j++)
            {
                if (g[i][j] == p) { L[j + 1] = L[j]; continue; }
                L[j + 1] = L[j] * (dp[g[i][j]] + 1);
            }
            ModInt[] R = new ModInt[g[i].Count + 1]; R[g[i].Count] = 1;
            for (int j = g[i].Count - 1; j >= 0; j--)
            {
                if (g[i][j] == p) { R[j] = R[j + 1]; continue; }
                R[j] = R[j + 1] * (dp[g[i][j]] + 1);
            }
            for (int j = 1; j <= g[i].Count; j++)
            {
                if (g[i][j - 1] == p) continue;
                Q.Enqueue(new Pair<int, int, ModInt>(g[i][j - 1], i, L[j - 1] * R[j] * (now + 1)));
            }
        }

    }
}

public struct ModInt
{
    public static long MOD = (int)1e9 + 7;
    //public const long MOD = 998244353;
    public long Value { get; set; }
    public ModInt(long n = 0) { Value = n; }
    private static ModInt[] fac;//階乗
    private static ModInt[] inv;//逆数
    private static ModInt[] facinv;//1/(i!)
    public override string ToString() => Value.ToString();
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static ModInt operator +(ModInt l, ModInt r)
    {
        l.Value += r.Value;
        if (l.Value >= MOD) l.Value -= MOD;
        return l;
    }
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static ModInt operator -(ModInt l, ModInt r)
    {
        l.Value -= r.Value;
        if (l.Value < 0) l.Value += MOD;
        return l;
    }
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static ModInt operator *(ModInt l, ModInt r) => new ModInt(l.Value * r.Value % MOD);
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static ModInt operator /(ModInt l, ModInt r) => l * Pow(r, MOD - 2);
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static implicit operator long(ModInt l) => l.Value;
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static implicit operator ModInt(long n)
    {
        n %= MOD; if (n < 0) n += MOD;
        return new ModInt(n);
    }

    public static ModInt Pow(ModInt m, long n)
    {
        if (n == 0) return 1;
        if (n % 2 == 0) return Pow(m * m, n >> 1);
        else return Pow(m * m, n >> 1) * m;
    }

    public static void Build(int n)
    {
        fac = new ModInt[n + 1];
        facinv = new ModInt[n + 1];
        inv = new ModInt[n + 1];
        inv[1] = 1;
        fac[0] = fac[1] = 1;
        facinv[0] = facinv[1] = 1;
        for (var i = 2; i <= n; i++)
        {
            fac[i] = fac[i - 1] * i;
            inv[i] = MOD - inv[MOD % i] * (MOD / i);
            facinv[i] = facinv[i - 1] * inv[i];
        }
    }
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static ModInt Fac(ModInt n) => fac[n];
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static ModInt Inv(ModInt n) => inv[n];
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static ModInt FacInv(ModInt n) => facinv[n];
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static ModInt Comb(ModInt n, ModInt r)
    {
        if (n < r) return 0;
        if (n == r) return 1;
        var calc = fac[n];
        calc = calc * facinv[r];
        calc = calc * facinv[n - r];
        return calc;
    }
}
