        static readonly long Mod = 1000000000 + 7;
        static void Main(string[] args)
        {
            var NM = Sarray();
            N = NM[0];
            M = NM[1];
            a = new int[N].Select(_ => new List<long>()).ToArray();
            for (var i = 0; i < N - 1; ++i)
            {
                var t = Sarray();
                a[t[0] - 1].Add(t[1] - 1);
                a[t[1] - 1].Add(t[0] - 1);
            }
            dpnode = new int[N].Select(_ => 1L).ToArray();
            dpedge = new int[N].Select(_ => new List<long>()).ToArray();
            parent = new long[N];

            dfs(0, -1);
            dpa = new int[N].Select(_ => 1L).ToArray();
            dfs3(0, -1, 0);
            SetOut(new StreamWriter(OpenStandardOutput()) { AutoFlush = false });
            for (var i = 0; i < N; ++i)
                WriteLine(dpnode[i]);
            Out.Flush();
        }
        static List<long>[] a;
        static long N;
        static long M;
        static long[] dpnode;
        static long[] dpa;
        static List<long>[] dpedge;
        static long[] parent;
        static void dfs(long v, long p)
        {
            var cnt = 0;
            parent[v] = p;
            foreach (var n in a[v])
            {
                if (n == p)
                {
                    dpedge[v].Add(1);
                    continue;
                }
                cnt++;
                dfs(n, v);
                dpedge[v].Add((dpnode[n] + 1) % M);
                dpnode[v] = dpnode[v] * (dpnode[n] + 1) % M;
            }
        }
        static void dfs3(long v, long p, long pv)//pv:親の情報
        {
            var num = a[v].Count;
            var ruil = new long[num + 1];
            var ruir = new long[num + 1];

            for (var i = 0; i < num; ++i)
                if (p == a[v][i])
                {
                    dpedge[v][i] = (pv + 1) % M;
                    break;
                }

            ruil[0] = 1;
            ruir[0] = 1;
            for (var i = 0; i < num; ++i)
            {
                ruil[i + 1] = ruil[i] * dpedge[v][i] % M;
                ruir[i + 1] = ruir[i] * dpedge[v][num - i - 1] % M;
            }
            dpnode[v] = ruil[num];
            for (var i = 0; i < num; ++i)
            {
                if (a[v][i] == p)
                    continue;
                dfs3(a[v][i], v, ruil[i] * ruir[num - i - 1]);
            }
        }
    }
