    long calc(int u, int p)
    {
        dp[u] = 1L;
        foreach (var v in G[u])
        {
            if (v == p)
            {
                continue;
            }            
            dp[u] *= calc(v, u) + 1;
            dp[u] %= M;
        }
        return dp[u];
    }
    void zenhoui(int u, int p)
    {
        ans[u] = 1L;
        foreach (var v in G[u])
        {
            ans[u] *= dp[v] + 1;
            ans[u] %= M;
        }

        int N = G[u].Count;
        var L = new long[N];
        var R = new long[N];
        for (int i = 0; i < N; i++)
        {
            L[i] = R[i] = dp[G[u][i]] + 1;
        }
        for (int i = 1; i < N; i++)
        {
            L[i] *= L[i - 1];
            L[i] %= M;
        }
        for (int i = N - 2; i >= 0; i--)
        {
            R[i] *= R[i + 1];
            R[i] %= M;
        }

        for (int i = 0; i < N; i++)
        {
            if (G[u][i] == p)
            {
                continue;
            }
            dp[u] = 1L;
            if (0 <= i - 1)
            {
                dp[u] *= L[i - 1];
            }
            if (i + 1 < N)
            {
                dp[u] *= R[i + 1];
            }
            dp[u] = dp[u] % M;
            zenhoui(G[u][i], u);
        }
    }
