            }

            public int Id;

            public List<Vertex> Edges = new List<Vertex>();

            public long Value;

            public long Answer;

            public int ChildrenCount;

            public int GroupSize;

            public int GroupsCount;

            public void Dfs1(Vertex parent, long mod)
            {
                ChildrenCount = Edges.Count - (parent == null ? 0 : 1);
                Value = 1;
                if (ChildrenCount > 0)
                {
                    GroupSize = (int) Math.Sqrt(ChildrenCount);
                    GroupsCount = (ChildrenCount + GroupSize - 1) / GroupSize;

                    ChildrenValues[Id] = new long[ChildrenCount];
                    OuterGroupValues[Id] = Enumerable.Repeat(1L, GroupsCount).ToArray();

                    int index = 0;
                    foreach (Vertex vertex in Edges)
                    {
                        if (vertex != parent)
                        {
                            vertex.Dfs1(this, mod);

                            long multValue = vertex.Value + 1;

                            ChildrenValues[Id][index] = multValue % mod;

                            int groupId = index / GroupSize;
                            for (int i = 0; i < GroupsCount; i++)
                            {
                                if (i != groupId)
                                {
                                    OuterGroupValues[Id][i] = OuterGroupValues[Id][i] * multValue % mod;
                                }
                            }
                            // GroupValues[groupId] = GroupValues[groupId] * (vertex.Value + 1) % mod;

                            Value = Value * multValue % mod;

                            index++;
                        }
                    }
                }
            }

            public void Dfs2(Vertex parent, long upValue, long mod)
            {
                Answer = Value * upValue % mod;

                int index = 0;
                foreach (Vertex vertex in Edges)
                {
                    if (vertex != parent)
                    {
                        int groupId = index / GroupSize;

                        long vUp = upValue * OuterGroupValues[Id][groupId] % mod;

                        int childMaxId = Math.Min((groupId + 1) * GroupSize, ChildrenCount);
                        for (int i = groupId * GroupSize; i < childMaxId; i++)
                        {
                            if (i != index)
                            {
                                vUp = vUp * ChildrenValues[Id][i] % mod;
                            }
                        }

                        vUp++;
                        if (vUp >= mod)
                        {
                            vUp -= mod;
                        }

                        vertex.Dfs2(this, vUp, mod);

                        index++;
                    }
                }
            }
        }

