        var pattern = new long[n];

        Func<int, int, long> dfs = null;
        dfs = (pos, par) => {
            long ret = 1;

            foreach (var c in adj[pos]) {
                if (c == par) continue;
                ret *= (dfs(c, pos) + 1);
                ret %= m;
            }
            pattern[pos] = ret;
            return ret;
        };
        dfs(0, -1);

        var ans = new long?[n];

        Action<int, int, long> dfs2 = null;
        dfs2 = (pos, par, dparent) => {
            var v = new List<Tuple<int, long>>();

            foreach (var c in adj[pos]) {
                if (c == par) {
                    v.Add(Tuple.Create(c, 1 + dparent));
                } else {
                    var p = 1 + pattern[c];
                    v.Add(Tuple.Create(c, p));
                }
            }
            var left = new long[v.Count];
            var right = new long[v.Count];

            for (int i = 0; i < left.Length; i++) {
                left[i] = v[i].Item2;
                if (i - 1 >= 0) left[i] *= left[i - 1];
                left[i] %= m;
            }

            for (int i = right.Length - 1; i >= 0; i--) {
                right[i] = v[i].Item2;
                if (i + 1 < right.Length) right[i] *= right[i + 1];
                right[i] %= m;
            }

            for (int i = 0; i < v.Count; i++) {
                var c = v[i].Item1;
                if (c == par) continue;
                var d = 1L;
                if (i - 1 >= 0) { d *= left[i - 1]; d %= m; }
                if (i + 1 < right.Length) { d *= right[i + 1]; d %= m; }
                dfs2(c, pos, d);
            }
            if (ans[pos].HasValue) throw new Exception();
            ans[pos] = (left.Length == 0 ? 1 : left[v.Count - 1]) % m;
        };

        dfs2(0, -1, 0);

        cout.WriteLine(string.Join("\n", ans));
    }
