    readonly int mod = 1000000007;
    readonly int dom = 998244353;
    bool chmax<T>(ref T a, T b) where T : IComparable<T> { if (a.CompareTo(b) < 0) { a = b; return true; } return false; }
    bool chmin<T>(ref T a, T b) where T : IComparable<T> { if (b.CompareTo(a) < 0) { a = b; return true; } return false; }

    List<int>[] G;
    long[] dp;
    int M;
    long[] ans;
    long calc(int u, int p)
    {
        dp[u] = 1L;
        foreach (var v in G[u])
        {
            if (v == p)
            {
                continue;
            }            
            dp[u] *= calc(v, u) + 1;
            dp[u] %= M;
        }
        return dp[u];
    }
    void zenhoui(int u, int p)
    {
        int N = G[u].Count;
        var L = new long[N];
        var R = new long[N];
        for (int i = 0; i < N; i++)
        {
            L[i] = R[i] = dp[G[u][i]] + 1;
        }
        for (int i = 1; i < N; i++)
        {
            L[i] *= L[i - 1];
            L[i] %= M;
        }
        for (int i = N - 2; i >= 0; i--)
        {
            R[i] *= R[i + 1];
            R[i] %= M;
        }

        for (int i = 0; i < N; i++)
        {
            int v = G[u][i]; //ans[v]を求める
            if (v == p)
            {
                continue;
            }
            dp[u] = 1L;
            if (0 <= i - 1)
            {
                dp[u] *= L[i - 1];
            }
            if (i + 1 < N)
            {
                dp[u] *= R[i + 1];
            }
            dp[u] = dp[u] % M;
            ans[v] = dp[v] * (dp[u] + 1) % M;
            zenhoui(v, u);
        }
    }
    void solve()
    {
        int N = cin.nextint;
        M = cin.nextint;
        G = new List<int>[N];
        for (int i = 0; i < N; i++)
        {
            G[i] = new List<int>();
