        for (int i = 0; i < N - 1; i++)
        {
            int a = cin.nextint - 1;
            int b = cin.nextint - 1;
            G[a].Add(b);
            G[b].Add(a);
        }
        dp = new long[N];
        calc(0, -1);
        ans = new long[N];
        ans[0] = dp[0];
        zenhoui(0, -1);
        foreach (var item in ans)
        {
            WriteLine(item);
        }  
    }
}


