            int[]uv=Console.ReadLine().Split().Select(int.Parse).ToArray();
            int u=uv[0]-1;
            int v=uv[1]-1;
            graph[u].Add(v);
            graph[v].Add(u);
        }

        Action<int,int>dfs=null;
        int[]prt=new int[n];
        dfs=(x,p)=>{
            prt[x]=p;
            foreach (int y in graph[x]){
                if(y==p)continue;
                dfs(y,x);
            }
        };
        dfs(0,0);
        for(int x=1;x<n;x++){
            graph[x].Remove(prt[x]);
        }

        Action<int>efs=null;
        long[]dp=new long[n];
        for(int i=0;i<n;i++)dp[i]=1;
        efs=x=>{
            foreach(int y in graph[x]){
                efs(y);
                dp[x]*=dp[y]+1;
                dp[x]%=mod;
            }
        };
        efs(0);

        long[]ep=new long[n];
        ep[0]=1;
        long[]a=new long[n+1];
        long[]b=new long[n+1];
        efs=x=>{
            int sz=graph[x].Count;
            a[0]=1; b[0]=1;
            for(int i=0;i<sz;i++){
                a[i+1]=b[sz-i]=1+dp[graph[x][i]];
            }
            for(int i=1;i<=sz;i++){
                a[i]=a[i]*a[i-1]%mod;
                b[i]=b[i]*b[i-1]%mod;
            }
            for(int i=0;i<sz;i++){
                int y=graph[x][i];
                ep[y]=ep[x];
                ep[y]*=a[i];
                ep[y]%=mod;
                ep[y]*=b[sz-1-i];
                ep[y]+=1;
                ep[y]%=mod;
            }
            foreach(int y in graph[x])efs(y);
        };
        efs(0);

        for(int i=0;i<n;i++){
            // Console.WriteLine($"[dp ep {i}] {dp[i]} {ep[i]}");
            Console.WriteLine((dp[i]*ep[i])%mod);
        }
    }
