public class ReRooting<TMonoid> {
    private readonly TMonoid _identity;
    private readonly Func<TMonoid, TMonoid, TMonoid> _merge;
    private readonly Func<TMonoid, int, TMonoid> _appendNode;

    public ReRooting(Func<TMonoid, TMonoid, TMonoid> merge,
        Func<TMonoid, int, TMonoid> appendNode,
        TMonoid identity) {
        _merge = merge;
        _appendNode = appendNode;
        _identity = identity;
    }

    public TMonoid[] Solve(List<int>[] adj) {
        var n = adj.Length;
        var ans = new TMonoid[n];
        var parents = new int[n];
        var permutation = new List<int>();
        var visited = new bool[n];
        var stack = new Stack<int>();
        int root = 0;
        stack.Push(root);
        while (stack.Count > 0) {
            var current = stack.Pop();
            if (visited[current]) continue;
            visited[current] = true;
            permutation.Add(current);
            foreach (var child in adj[current]) {
                if (!visited[child]) {
                    parents[child] = current;
                    stack.Push(child);
                }
            }
        }
        var dp = new TMonoid[n];
        foreach (var p in permutation.AsEnumerable().Reverse()) {
            var val = _identity;
            foreach (var child in adj[p]) {
                if (child == parents[p]) continue;
                val = _merge(val, dp[child]);
            }
            dp[p] = _appendNode(val, p);
        }
        var fromParent = new TMonoid[n];
        var accumulateFromTail = new TMonoid[n + 1];
        var subTreeResult = new TMonoid[n];
        foreach (var p in permutation) {
            int count = adj[p].Count;
            var accumulate = _identity;
            if (count > 0) {
                for (int i = 0; i < count; i++) {
                    var child = adj[p][i];
                    subTreeResult[i] = child == parents[p] ? fromParent[p] : dp[child];
                }
                accumulateFromTail[count] = _identity;
                for (int i = count - 1; i >= 0; i--) {
                    accumulateFromTail[i] = _merge(subTreeResult[i], accumulateFromTail[i + 1]);
                }
                for (int i = 0; i < count; i++) {
                    var child = adj[p][i];
                    if (child != parents[p]) {
                        fromParent[child] = _appendNode(_merge(accumulate, accumulateFromTail[i + 1]), child);
                    }
                    accumulate = _merge(accumulate, subTreeResult[i]);
                }
            }
            ans[p] = _appendNode(accumulate, p);
        }
        return ans;
    }
}
