using System;
using System.Collections.Generic;
using System.Linq;
class Program{
	static int mod=0;
	static List<int>[] li;
	static Dictionary<int,int>[] hs2;
	static int[] m,c;
	static long[][] dat;
	static void Main(){
		int[] s=Array.ConvertAll(Console.ReadLine().Split(),int.Parse);
		int n=s[0];
		mod=s[1];
		long[] ans=new long[n];
		li=new List<int>[n+1];
		hs2=new Dictionary<int,int>[n+1];
		m=new int[n+1];
		c=new int[n+1];
		dat=new long[n+1][];
		for(int i=1;i<=n;i++){
			li[i]=new List<int>();
			hs2[i]=new Dictionary<int,int>();
		}
		for(int i=0;i<n-1;i++){
			int[] q=Array.ConvertAll(Console.ReadLine().Split(),int.Parse);
			li[q[0]].Add(q[1]);
			li[q[1]].Add(q[0]);
		}
		for(int i=1;i<=n;i++){
			int z=li[i].Count;
			m[i]=1;
			while(m[i]<=z){m[i]*=2;}
			dat[i]=new long[z+m[i]-1];
		}
		if(n==1){Console.WriteLine(1);}
		else{
			for(int i=1;i<=n;i++){ans[i-1]=Fu(i,0)%mod;}
			Console.WriteLine(String.Join("\n",ans));
		}
	}
	static long Fu(int a,int p){
		if(c[a]==-1){
			if(p==0){return dat[a][0]%mod;}
			return (fdg(0,hs2[a][p]-1,0,0,m[a]-1,a)*fdg(hs2[a][p]+1,li[a].Count-1,0,0,m[a]-1,a))%mod;
		}
		else if(c[a]==0){
			if(p==0){c[a]=-1;}
			else{c[a]=p;}
			dat[a][0]=1;
			for(int i=0;i<li[a].Count;i++){
				hs2[a].Add(li[a][i],i);
				if(li[a][i]!=p){fdu(a,i,(Fu(li[a][i],a)+1)%mod);}
			}
			return dat[a][0]%mod;
		}
		else if(c[a]==p){return dat[a][0]%mod;}
		else{
			fdu(a,hs2[a][c[a]],(Fu(c[a],a)+1)%mod);
			c[a]=-1;
			if(p==0){return dat[a][0]%mod;}
			return (fdg(0,hs2[a][p]-1,0,0,m[a]-1,a)*fdg(hs2[a][p]+1,li[a].Count-1,0,0,m[a]-1,a))%mod;
		}
	}
	static void fdu(int c,int q,long b){
		q+=m[c]-1;
		dat[c][q]=b%mod;
		while(q>0){
			if(dat[c][(q-1)/2]==0){dat[c][(q-1)/2]=b;}
			else{dat[c][(q-1)/2]=(dat[c][(q-1)/2]*b)%mod;}
			q=(q-1)/2;
		}
	}
	static long fdg(int a,int b,int k,int l,int r,int c){
		if(r<a||b<l){return 1;}
		if(a<=l&&r<=b){return dat[c][k]%mod;}
		else{return (fdg(a,b,k*2+1,l,(l+r)/2,c)*fdg(a,b,k*2+2,(l+r+1)/2,r,c))%mod;}
	}
}

