using pair = Pair<long, long>;

class Program
{
    static void Main()
    {
        SetOut(new StreamWriter(OpenStandardOutput()) { AutoFlush = false });
        new Program().solve();
        Out.Flush();
    }
    readonly Scanner cin = new Scanner();
    readonly int[] dd = { 0, 1, 0, -1, 0 }; //→↓←↑
    readonly int mod = 1000000007;
    readonly int dom = 998244353;
    bool chmax<T>(ref T a, T b) where T : IComparable<T> { if (a.CompareTo(b) < 0) { a = b; return true; } return false; }
    bool chmin<T>(ref T a, T b) where T : IComparable<T> { if (b.CompareTo(a) < 0) { a = b; return true; } return false; }

    List<int>[] G;
    long[] dp;
    int M;
    long[] ans;
    long calc(int u, int p)
    {
        var ret = 1L;
        foreach (var v in G[u])
        {
            if (v == p)
            {
                continue;
            }            
            ret *= calc(v, u) + 1;
            ret %= M;
        }
        return dp[u] = ret;
    }
    void zenhoui(int u, int p)
    {
        var ret = 1L;
        foreach (var v in G[u])
        {
            ret *= dp[v] + 1;
            ret %= M;
        }
        ans[u] = ret;

        int N = G[u].Count;
        var L = new long[N];
        var R = new long[N];
        L[0] = dp[G[u][0]] + 1;
        for (int i = 1; i < N; i++)
        {
            L[i] = L[i - 1] * (dp[G[u][i]] + 1);
            L[i] %= M;
        }
        R[N - 1] = dp[G[u][N - 1]] + 1;
        for (int i = N - 2; i >= 0; i--)
        {
            R[i] = R[i + 1] * (dp[G[u][i]] + 1);
            R[i] %= M;
        }

        for (int i = 0; i < N; i++)
        {
            if (G[u][i] == p)
            {
                continue;
            }
            var tmp = 1L;
            if (0 <= i - 1)
            {
                tmp *= L[i - 1];
            }
            if (i + 1 < N)
            {
                tmp *= R[i + 1];
            }
            dp[u] = tmp % mod;
            zenhoui(G[u][i], u);
        }
    }
    void solve()
    {
        int N = cin.nextint;
        if (N == 1)
        {
            WriteLine(1);
            return;
        }
        M = cin.nextint;
        G = new List<int>[N];
        for (int i = 0; i < N; i++)
        {
            G[i] = new List<int>();
        }
        for (int i = 0; i < N - 1; i++)
        {
            int a = cin.nextint - 1;
            int b = cin.nextint - 1;
            G[a].Add(b);
            G[b].Add(a);
        }
        dp = new long[N];
        calc(0, -1);
        ans = new long[N];
        zenhoui(0, -1);
        foreach (var item in ans)
        {
            WriteLine(item);
        }  
    }

    long[] A, B;
    //a^b(mod p) solution works in O(logb).
    long powmod(long a, long b, long p)
    {
        if (b == 0) return 1;
        if (b % 2 == 0)
        {
            long d = powmod(a, b / 2, p);
            return d * d % p;
        }
        else
        {
            return a * powmod(a, b - 1, p) % p;
        }
    }
    void table(int n)
    {
        A = new long[n + 1];
        B = new long[n + 1];
        A[0] = 1;
        for (int i = 0; i < n; i++)
        {
            A[i + 1] = A[i] * (i + 1) % mod;
        }
        B[n] = powmod(A[n], mod - 2, mod);
        //modが合成数の場合
        //extgcd(A[n], mod, out long x, out long y);
        //B[n] = ((x % mod) + mod) % mod;
        for (int i = 0; i < n; i++)
        {
            B[n - i - 1] = B[n - i] * (n - i) % mod;
        }
    }
    long combi(int n, int r)
    {
        return A[n] * B[r] % mod * B[n - r] % mod;
    }
}


