    long[,] dp;
    List<int>[] es;
    int[] A;
    int[] B;

    long mod;

    int[] NCNT;
    long[][] muls;

    int[,] pos;

    void calc()
    {
        cin = new Scanner();
        N = cin.nextInt();
        mod = cin.nextInt();

        es = new List<int>[N];
        for (int i = 0; i < N; i++)
        {
            es[i] = new List<int>();
        }
        A = new int[N - 1];
        B = new int[N - 1];
        pos = new int[N - 1, 2];

        for (int i = 0; i < N - 1; i++)
        {
            A[i] = cin.nextInt() - 1;
            B[i] = cin.nextInt() - 1;

            pos[i, 0] = es[B[i]].Count;
            pos[i, 1] = es[A[i]].Count;

            es[A[i]].Add(i);
            es[B[i]].Add(i);
        }

        dp = new long[N - 1, 2];
        for (int i = 0; i < N - 1; i++)
        {
            for (int j = 0; j < 2; j++)
            {
                dp[i, j] = -1;
            }
        }

        NCNT = new int[N];
        muls = new long[N][];

        for (int i = 0; i < N; i++)
        {
            long p = 1;
            foreach (var e2 in es[i])
            {
                if (A[e2] == i) p *= (dfs(e2, 0) + 1);
                else p *= dfs(e2, 1) + 1;
                p %= mod;

            }
            Console.WriteLine(p);
        }

    }


    long dfs(int e, int t)
    {
        if (dp[e, t] != -1) return dp[e, t];
        int pre, a;
        if (t == 0)
        {
            pre = A[e];
            a = B[e];
        }
        else
        {
            pre = B[e];
            a = A[e];
        }



        NCNT[a]++;
        if (NCNT[a] >= 3 && es[a].Count >= 10)
        {
            int len = (int)Math.Sqrt(es[a].Count);
            int N = (es[a].Count + len - 1) / len;
            if (NCNT[a] == 3)
            {
                muls[a] = new long[N];
                for (int i = 0; i < N; i++)
                {
                    muls[a][i] = 1;
                }

                for (int i = 0; i < es[a].Count; i++)
                {
                    int e2 = es[a][i];
                    long pp;
                    if (A[e2] == a) pp = (dp[e2, 0] + 1);
                    else pp = dp[e2, 1] + 1;
                    muls[a][i / len] *= pp;
                    muls[a][i / len] %= mod;
                }
            }


            long p = 1;
            for (int i = 0; i < N; i++)
            {
                if (pos[e, t] / len != i)
                {
                    p *= muls[a][i];
                    p %= mod;
                }
                else
                {
                    for (int j = i * len; j < Math.Min((i + 1) * len, es[a].Count); j++)
                    {
                        int e2 = es[a][j];
                        if (e2 == e) continue;
                        if (A[e2] == a) p *= (dp[e2, 0] + 1);
                        else p *= dp[e2, 1] + 1;
                        p %= mod;
                    }
                }
            }

            return dp[e, t] = p;
        }
        else
        {
            long p = 1;
            foreach (var e2 in es[a])
            {
                if (e2 == e) continue;
                if (A[e2] == a) p *= (dfs(e2, 0) + 1);
                else p *= dfs(e2, 1) + 1;
                p %= mod;

            }
            return dp[e, t] = p;
        }
    }



}


