public static class Program {
    static long mod;
    public static void Main() {
        int[]nm=Console.ReadLine().Split().Select(int.Parse).ToArray();
        int n=nm[0];
        mod=(long)nm[1];
        List<int>[]graph=Enumerable.Range(0,n)
            .Select(_=>new List<int>()).ToArray();
        for(int i=0;i<n-1;i++){
            int[]uv=Console.ReadLine().Split().Select(int.Parse).ToArray();
            int u=uv[0]-1;
            int v=uv[1]-1;
            graph[u].Add(v);
            graph[v].Add(u);
        }

        Action<int,int>dfs=null;
        int[]prt=new int[n];
        dfs=(x,p)=>{
            prt[x]=p;
            foreach (int y in graph[x]){
                if(y==p)continue;
                dfs(y,x);
            }
        };
        dfs(0,0);
        for(int x=0;x<n;x++){
            graph[x].Remove(prt[x]);
        }

        Action<int>efs=null;
        long[]dp=new long[n];
        for(int i=0;i<n;i++)dp[i]=1;
        efs=x=>{
            foreach(int y in graph[x]){
                efs(y);
                dp[x]*=dp[y]+1;
            }
            dp[x]%=mod;
        };
        efs(0);

        long[]ep=new long[n];
        ep[0]=1;
        efs=x=>{
            int sz=graph[x].Count;
            long[]a=new long[sz+1];
            long[]b=new long[sz+1];
            a[0]=1; b[0]=1;
            for(int i=0;i<sz;i++){
                a[i+1]=1+dp[graph[x][i]];
                b[sz-i]=1+dp[graph[x][i]];
            }
            for(int i=1;i<=sz;i++){
                a[i]=a[i]*a[i-1]%mod;
                b[i]=b[i]*b[i-1]%mod;
            }
            for(int i=0;i<sz;i++){
                ep[graph[x][i]]=ep[x];
                ep[graph[x][i]]*=a[i];
                ep[graph[x][i]]%=mod;
                ep[graph[x][i]]*=b[sz-1-i];
                ep[graph[x][i]]+=1;
                ep[graph[x][i]]%=mod;
            }
            foreach(int y in graph[x])efs(y);
        };
        efs(0);

        for(int i=0;i<n;i++){
            // Console.WriteLine($"[dp ep {i}] {dp[i]} {ep[i]}");
            Console.WriteLine((dp[i]*ep[i])%mod);
        }
    }
}

