namespace AtCoder
{
    class Program
    {
        static public long[] Sarray() { return ReadLine().Split().Select(long.Parse).ToArray(); }
        static public List<long> Slist() { return ReadLine().Split().Select(long.Parse).ToList(); }

        static readonly long Mod = 1000000000 + 7;
        static void Main(string[] args)
        {
            var NM = Sarray();
            N = NM[0];
            M = NM[1];
            a = new int[N].Select(_ => new List<long>()).ToArray();
            for (var i = 0; i < N - 1; ++i)
            {
                var t = Sarray();
                a[t[0] - 1].Add(t[1] - 1);
                a[t[1] - 1].Add(t[0] - 1);
            }
            dpc = new int[N].Select(_ => 1L).ToArray();
            dp2 = new int[N].Select(_ => new List<long>()).ToArray();
            parent = new long[N];

            //ある頂点を親としたとき、子の取る数を求めていく(dp2)
            //子が葉なら2(自分が黒のとき、子は白、黒の2通り)
            //子の子･･･とあるなら子が取る数+1(子が黒の時、子が白の時)

            dfs(0, -1);
            dpa = new int[N].Select(_ => 1L).ToArray();
            dfs2(0, -1);
            for (var i = 0; i < N; ++i)
                WriteLine(dpa[i]);
        }
        static List<long>[] a;
        static long N;
        static long M;
        static long[] dpc;
        static long[] dpa;
        static List<long>[] dp2;
        static long[] parent;
        static void dfs(long v, long p)
        {
            var cnt = 0;
            parent[v] = p;
            foreach(var n in a[v])
            {
                if (n == p)
                {
                    dp2[v].Add(0);
                    continue;
                }
                cnt++;
                dfs(n, v);
                dp2[v].Add(dpc[n] + 1);
                dpc[v] = dpc[v] * (dpc[n] + 1) % M;
            }
        }
        static void dfs2(long v, long p)
        {
            for (var j = 0; j < a[v].Count; ++j) 
            {
                //親について求める
                var n = a[v][j];
                if (n == p)
                {
                    long t = 1;
                    for (var i = 0; i < a[p].Count; ++i)
                    {
                        if (a[p][i] == v) continue;//自分への枝は無視
                        t = t * dp2[p][i] % M;
                    }
                    dp2[v][j] = (t + 1) % M;
                }
                //伸びる枝に対して
                dpa[v] = dpa[v] * dp2[v][j] % M;
            }
            foreach (var n in a[v])
            {
                if (n == p) continue;
                dfs2(n, v);
            }
        }
    }
}

