		var seg = new SegmentTree(t);
		for (var i = 0; i < W; i++) dp1[es[u][i]] = (dp1[u] + 1) * seg.Product(0, i) % Mod * seg.Product(i + 1, W) % Mod;
		foreach (var v in es[u]) DFS3(v);
	}
