class SegmentTree
{
	public static int Mod;
	readonly int N;
	readonly long[] arr;
	public SegmentTree(IList<long> array)
	{
		N = 1;
		while (N < array.Count) N <<= 1;
		arr = new long[2 * N - 1];
		for (var i = 0; i < 2 * N - 1; i++) arr[i] = 1;
		for (var i = 0; i < array.Count; i++) arr[i + N - 1] = array[i];
		for (var i = N - 2; i >= 0; i--) arr[i] = arr[2 * i + 1] * arr[2 * i + 2] % Mod;
	}
	public long Product(int from, int to) => Product(from, to, 0, 0, N);
	long Product(int from, int to, int node, int l, int r)
	{
		if (to <= l || r <= from) return 1;
		if (from <= l && r <= to) return arr[node];
		return Product(from, to, 2 * node + 1, l, (l + r) >> 1) * Product(from, to, 2 * node + 2, (l + r) >> 1, r) % Mod;
	}
}

