package main

import "fmt"

var CYCLE int64
var N int

// var w [100000]int64
var b [100000]int64
var p [100000]int64
var bp [100000]int64
var visited [100000]bool
var edges [100000][]int

func getChildren(i int) []int {
	possibleChildren := edges[i]
	visited[i] = true
	result := make([]int, 0, len(possibleChildren))
	for _, c := range possibleChildren {
		if !visited[c] {
			result = append(result, c)
		}
	}
	return result
}

func add(x, y int64) int64 {
	return (x + y) % CYCLE
}

func sub(x, y int64) int64 {
	return (x - y + CYCLE) % CYCLE
}

func mul(x, y int64) int64 {
	return (x * y) % CYCLE
}

func solve1(i int) {
	children := getChildren(i)
	b[i] = int64(1)
	for _, c := range children {
		solve1(c)
		b[i] = mul(b[i], b[c]+1)
	}
}

func solve2(i int) {
	children := getChildren(i)
	for _, j := range children {
		bp[j] = sub(add(add(bp[i], b[j]), 1), p[j])
		solve2(j)
	}
}

func clearVisited() {
	for i := 0; i < N; i++ {
		visited[i] = false
	}
