func parseInt(s string) int {
	return int(parseInt64(s))
}

func parseInt64(s string) int64 {
	x, _ := strconv.ParseInt(s, 10, 64)
	return x
}

var reader *bufio.Reader

func readLine() string {
	s, _ := reader.ReadString('\n')
	return strings.TrimSuffix(s, "\n")
}

var CYCLE int64
var N int

// var w [100000]int64
var b [100000]int64
var p [100000]int64
var visited [100000]bool
var edges [100000][]int

func getChildren(i int) []int {
	possibleChildren := edges[i]
	visited[i] = true
	result := make([]int, 0, len(possibleChildren))
	for _, c := range possibleChildren {
		if !visited[c] {
			result = append(result, c)
		}
	}
	return result
}

func add(x, y int64) int64 {
	return (x + y) % CYCLE
}

func mul(x, y int64) int64 {
	return (x * y) % CYCLE
}

func solve1(i int) {
	children := getChildren(i)
	b[i] = int64(1)
	for _, c := range children {
		solve1(c)
		b[i] = mul(b[i], b[c]+1)
	}
}

func solve2(i int) {
	children := getChildren(i)
	a := int64(1)
	for j := 0; j < len(children); j++ {
		c := children[j]
		p[c] = mul(p[i], a)
		a = mul(a, b[c]+1)
	}
	a = int64(1)
	for j := len(children) - 1; j >= 0; j-- {
		c := children[j]
		p[c] = mul(p[c], a)
		a = mul(a, b[c]+1)
	}
	for _, c := range children {
		p[c] = add(p[c], 1)
		solve2(c)
	}
}

func clearVisited() {
	for i := 0; i < N; i++ {
		visited[i] = false
	}
}

