	fmt.Scan(&N, &CYCLE)
	for i := 0; i < N-1; i++ {
		fields := strings.Fields(readLine())
		x := parseInt(fields[0])
		y := parseInt(fields[1])
		edges[x-1] = append(edges[x-1], y-1)
		edges[y-1] = append(edges[y-1], x-1)
	}

	solve1(0)
	clearVisited()
	p[0] = 1
	solve2(0)

