var (
	n, m int

	G       [100000 + 50][]int
	dp      [100000 + 50]int
	answers [100000 + 50]int
)

func main() {
	n, m = ReadInt2()
	for i := 0; i < n-1; i++ {
		x, y := ReadInt2()
		x--
		y--

		G[x] = append(G[x], y)
		G[y] = append(G[y], x)
	}

	dfs(0, -1)
	PrintfDebug("%v\n", dp[:n])
	rdfs(0, -1, 0)

	for i := 0; i < n; i++ {
		fmt.Println(answers[i])
	}
}

func rdfs(cid, pid int, dpar int) {
	// cidの答えを求める
	ans := 1
	for _, nid := range G[cid] {
		if nid == pid {
			ans = modgen(ans*(dpar+1), m)
			continue
		}
		ans = modgen(ans*(dp[nid]+1), m)
	}
	answers[cid] = ans

	// 子についてすすめる
	cdp := []int{1}
	nexts := []int{-1}
	for _, nid := range G[cid] {
		if nid == pid {
			continue
		}
		cdp = append(cdp, dp[nid])
		nexts = append(nexts, nid)
	}
	cdp = append(cdp, 1)
	nexts = append(nexts, -1)

	N := len(cdp)
	L, R := make([]int, N), make([]int, N)
	L[0], R[0], L[N-1], R[N-1] = 1, 1, 1, 1
	for i := 1; i <= N-2; i++ {
		L[i] = modgen(L[i-1]*(cdp[i]+1), m)
	}
	for i := N - 2; i >= 1; i-- {
		R[i] = modgen(R[i+1]*(cdp[i]+1), m)
	}

	for i := 1; i <= N-2; i++ {
		nid := nexts[i]
		ndpar := modgen(L[i-1]*R[i+1], m)
		ndpar = modgen(ndpar*(dpar+1), m)
		rdfs(nid, cid, ndpar)
	}
}

func dfs(cid, pid int) {
	res := 1

	for _, nid := range G[cid] {
		if nid == pid {
			continue
		}

		dfs(nid, cid)

		res = modgen(res*(dp[nid]+1), m)
	}

	dp[cid] = res
}

func modgen(val, m int) int {
	res := val % m
	if res < 0 {
		res += m
	}
	return res
}

