type T int

type ReRootingSolver struct {
	NodeCount int

	Adjacents         [][]int
	IndexForAdjacents [][]int

	Res []T
	DP  [][]T

	Identity    T
	Operate     func(l, r T) T
	OperateNode func(v T, p int) T
}

func NewReRootingSolver(
	nodeCount int, edges [][]int, identity T, operate func(l, r T) T, operateNode func(v T, parent int) T,
) *ReRootingSolver {
	solver := new(ReRootingSolver)

	solver.NodeCount = nodeCount
	solver.Identity = identity
	solver.Operate = operate
	solver.OperateNode = operateNode

	solver.Adjacents = make([][]int, nodeCount)
	solver.IndexForAdjacents = make([][]int, nodeCount)
	for _, e := range edges {
		solver.IndexForAdjacents[e[0]] = append(solver.IndexForAdjacents[e[0]], len(solver.Adjacents[e[1]]))
		solver.IndexForAdjacents[e[1]] = append(solver.IndexForAdjacents[e[1]], len(solver.Adjacents[e[0]]))
		solver.Adjacents[e[0]] = append(solver.Adjacents[e[0]], e[1])
		solver.Adjacents[e[1]] = append(solver.Adjacents[e[1]], e[0])
	}

	solver.DP = make([][]T, len(solver.Adjacents))
	solver.Res = make([]T, len(solver.Adjacents))

	for i := 0; i < len(solver.Adjacents); i++ {
		solver.DP[i] = make([]T, len(solver.Adjacents[i]))
	}

	if solver.NodeCount > 1 {
		solver.Initialize()
	} else {
		solver.Res[0] = solver.OperateNode(solver.Identity, 0)
	}

	return solver
}

func (s *ReRootingSolver) Query(node int) T {
	return s.Res[node]
}

func (s *ReRootingSolver) Initialize() {
	parents, order := make([]int, s.NodeCount), make([]int, s.NodeCount)

	// InitOrderedTree
	index := 0
	stack := []int{}
	stack = append(stack, 0)
	parents[0] = -1
	for len(stack) > 0 {
		node := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		order[index] = node
		index++
		for i := 0; i < len(s.Adjacents[node]); i++ {
			adjacent := s.Adjacents[node][i]
			if adjacent == parents[node] {
				continue
			}
			stack = append(stack, adjacent)
			parents[adjacent] = node
		}
	}

	// fromLeaf
	for i := len(order) - 1; i >= 1; i-- {
		node := order[i]
		parent := parents[node]

		accum := s.Identity
		parentIndex := -1
		for j := 0; j < len(s.Adjacents[node]); j++ {
			if s.Adjacents[node][j] == parent {
				parentIndex = j
				continue
			}
			accum = s.Operate(accum, s.DP[node][j])
		}
		s.DP[parent][s.IndexForAdjacents[node][parentIndex]] = s.OperateNode(accum, node)
	}

	// toLeaf
	for i := 0; i < len(order); i++ {
		node := order[i]
		accum := s.Identity
		accumsFromTail := make([]T, len(s.Adjacents[node]))
		accumsFromTail[len(accumsFromTail)-1] = s.Identity
		for j := len(accumsFromTail) - 1; j >= 1; j-- {
			accumsFromTail[j-1] = s.Operate(s.DP[node][j], accumsFromTail[j])
		}
		for j := 0; j < len(accumsFromTail); j++ {
			s.DP[s.Adjacents[node][j]][s.IndexForAdjacents[node][j]] = s.OperateNode(s.Operate(accum, accumsFromTail[j]), node)
			accum = s.Operate(accum, s.DP[node][j])
		}
		s.Res[node] = s.OperateNode(accum, node)
	}
}

const MAX_STACK_SIZE = 2000000

type Stack struct {
	dat [MAX_STACK_SIZE]int
	top int
}

func NewStack() *Stack {
	s := new(Stack)
	s.top = 0
	return s
}

func (s *Stack) IsEmpty() bool {
	return s.top == 0
}

func (s *Stack) IsFull() bool {
	return s.top >= MAX_STACK_SIZE-1
}

func (s *Stack) Push(x int) {
	// check IsFull()
	s.top++
	s.dat[s.top] = x
}

func (s *Stack) Pop() int {
	// check IsEmpty()
	s.top--
	return s.dat[s.top+1]
}

