        int xi, yi;
        scan(xi, yi);
        xi--, yi--;
        adj[xi] ~= yi;
        adj[yi] ~= xi;
    }

    auto size = new Mint[](N);
    auto ch = new int[][](N, 0);

    Mint dfs(int v, int p) {
        size[v] = 1;
        foreach (u ; adj[v]) if (u != p) {
            ch[v] ~= u;
            dfs(u, v);
            size[v] *= size[u];
        }
        size[v] += 1;
        return size[v];
    }

    dfs(0, -1);

    auto ans = new Mint[](N);

    void rert(int v, int p, Mint c) {
        debug {
            writefln("v: %s, p: %s, c: %s", v, p, c);
        }
        auto s = ch[v].length.to!int;
        auto l = new Mint[](s + 1);
        auto r = new Mint[](s + 1);

        l[0] = 1;
        foreach (i ; 1 .. s + 1) {
            l[i] = l[i - 1] * size[ch[v][i - 1]];
        }

        r[s] = 1;
        foreach_reverse (i ; 0 .. s) {
            r[i] = r[i + 1] * size[ch[v][i]];
        }

        ans[v] = l[s] * c + 1;

        foreach (i ; 0 .. s) {
            int u = ch[v][i];
            rert(u, v, l[i] * r[i + 1] * c + 1);
        }
    }

    rert(0, -1, Mint(1));

    debug {
        writeln(size);
    }

