alias MD = ModInt_D;

void main() {
  long n, m;
  readlnTo(n, m);
  auto g = new long[][](n, 0);
  foreach (_; iota(n - 1)) {
    long x, y;
    readlnTo(x, y);
    --x;
    --y;
    g[x] ~= y;
    g[y] ~= x;
  }
  auto x = new MD[](n);
  auto p = new long[](n);
  MD dfs(long u, long prev) {
    auto ans = MD(1, m);
    p[u] = prev;
    foreach (v; g[u]) {
      if (v == prev) {
        continue;
      }
      ans *= (dfs(v, u) + 1);
    }
    x[u] = ans;
    return ans;
  }

  dfs(0, -1);

  auto y = new MD[](n);
  y[] = MD(0, m);
  auto y_done = new bool[](n);
  MD calc_y(long u) {
    if (y_done[u]) {
      return y[u];
    }
    if (p[u] < 0) {
      y[u] = MD(0, m);
    } else {
      y[u] = calc_y(p[u]) + 1;
      foreach (v; g[p[u]]) {
        if (v == u || v == p[p[u]]) {
          continue;
        }
        y[u] *= (x[v] + 1);
      }
    }
    y_done[u] = true;
    return y[u];
  }

  foreach (i; iota(n)) {
    calc_y(i);
  }

  foreach(i; iota(n)) {
    writeln(x[i] * (y[i]+1));
  }
}

