void dfs0(int u, int p) {
  foreach (v; graph[u]) {
    if (v != p) {
      children[u] ~= v;
    }
  }
  foreach (v; children[u]) {
    dfs0(v, u);
  }
  dp0[u] = 1;
  foreach (v; children[u]) {
    (dp0[u] *= (dp0[v] + 1)) %= M;
  }
}

void dfs1(int u) {
  foreach (j, v; children[u]) {
    dp1[v] = 1;
    (dp1[v] *= dp1[u]) %= M;
    (dp1[v] *= ls[u][j]) %= M;
    (dp1[v] *= rs[u][j + 1]) %= M;
    ++dp1[v];
  }
  foreach (v; children[u]) {
    dfs1(v);
  }
}

