	ans[u] = dp[u];
	for(auto z : adj[u])
	{
		if(z == p)
			continue;
		int temp2 = dp[u];
		dp[u] = mul(dp[u], modinv (add(1, dp[z]),   mod));
		int temp = dp[z];
		dp[z] = mul(dp[z], add(1, dp[u]));
		dfs2(z, u);
		dp[z] = temp;
		dp[u] = temp2;
	}
}
