// basic operations
int mul( int a , int b ) {
    return 1ll*a*b%mod;
}
int add( int a , int b ) {
    return (a+b)%mod;
}

vvi g , children , preffix_mul , suffix_mul;
vi ans , v , dp;



void dfs( int node , int p = -1 ) {

    for( int nw : g[node] ) {
        if( nw!=p ) {
            children[node].pb( nw );
            preffix_mul[node].pb( 1 );
            suffix_mul[node].pb( 1 );
            dfs( nw , node );
            dp[node] = mul( dp[node] , dp[nw]+1 );
        }
    }

}

void dfs_rooting( int node, int p_value=-1 ) {
    // pref_part
    for( int i = 0 ; i < sz(children[node]) ; i++ ) {
        int nw = children[node][i];
        if( i>0 )
        {
            preffix_mul[node][i] = mul( preffix_mul[node][i-1] , dp[nw]+1 );
        }
    }
    //suf_part
    for( int i = (int)sz(children[node])-1 ; i >= 0 ; i-- ) {
        int nw = children[node][i];
        if( i+1<sz(children[node]) )
        {
            suffix_mul[node][i] = mul( suffix_mul[node][i+1] , dp[nw]+1 );
        }
    }

    if( node==1 ) {

        ans[node] = dp[node];int i = 0;
        for( int nw: children[node] ) {
            dfs_rooting( nw , mul(preffix_mul[node][i],suffix_mul[node][i]) );
            i++;
        }

    } else {
//        if( node==2 ) {
//            cout<<dp[node]<<" "<<p_value<<"\n";
//        }
        ans[node] = mul( dp[node] , p_value+1 );
        int i = 0;
        for( int nw: children[node] ) {
            dfs_rooting( nw , mul( mul(preffix_mul[node][i],suffix_mul[node][i]), p_value+1 ) );
            i++;
        }

    }

}

