template useModInt*(p: Positive) =
  type ModInt* {.inject.} = distinct int

  proc toModInt*(n: int): ModInt {.inline.} =
    if n >= p + p:
      ModInt(n mod p)
    elif n >= p:
      ModInt(n - p)
    elif n >= 0:
      ModInt(n)
    elif n >= -p:
      ModInt(n + p)
    else:
      ModInt((n mod p + p) mod p)

  # proc inverse*(n: range[1 .. p - 1]): ModInt {.inline.} =
  #   var (sx, tx, s, t) = (0, 1, p, n)
  #   while t != 1:
  #     let k = s div t
