block:
  var st = newSeq[tuple[v: int, pr: ModInt]]()
  st.add((1, ModInt(1)))
  while st.len > 0:
    let (v, pr) = st.pop()
    let K = child[v].high
    var cumr = newSeq[ModInt](K + 1) & @[ModInt(1)]
    for i in countdown(K, 0):
      let u = child[v][i]
      cumr[i] = cumr[i + 1] * (dp[u] + 1)
    var cuml = ModInt(1)
    for i, u in child[v]:
      let k = cuml * cumr[i + 1] * pr + 1
      cuml *= dp[u] + 1
      dp[u] *= k
      st.add((u, k))

