    for j in g[i]:
      if j == p:
        continue
      dp[i] = dp[i] * (dfs(j, i) + 1) mod m
    return dp[i]
  discard dfs(0, -1)
  # echo dp
  var ans = newSeq[int64](n)
  proc solve(i, p: int, a: int64)=
    # echo i, " ", p, " ", a
    ans[i] = a mod m
    for j in g[i]:
      if j == p:
        continue
      ans[i] = ans[i] * (dp[j] + 1) mod m
    for j in g[i]:
      if j == p:
        continue
      var b = a
      for k in g[i]:
        if k == p or k == j:
          continue
        b = b * (dp[k] + 1) mod m
      solve(j, i, b + 1)
  solve(0, -1, 1)
  echo ans.mapIt($it).join("\n")
