      if mode == parents[node]:
        continue
      order.append(mode)
      parents[mode] = node
  def merge1(a, b):
    return a*b%mod
  def addnode1(a, id):
    return a+1
  for node in order[1::][::-1]:
    parent = parents[node]
    ans = identify
    indexparent = -1
    for j in range(len(edges[node])):
      mode = edges[node][j]
      if parent == mode:
        indexparent = j
        continue
      ans = merge1(ans, subdp[node][j])
    subdp[parent][indexedges[node][indexparent]] = addnode1(ans, node)
  def merge2(a,b):
    return a*b%mod
  def addnode2(a, id):
    return a+1
  for node in order:
    b = [identify]*len(edges[node])
    for i in range(len(edges[node])-1,0,-1):
