    bb = identify
    for i in range(len(edges[node])):
      ans = merge2(bb, b[i])
      subdp[edges[node][i]][indexedges[node][i]] = addnode2(ans, node)
      bb = merge2(bb, subdp[node][i])
    dp[node] = addnode2(bb, node)
  return dp
