from collections import deque

def solve():
    input = sys.stdin.readline
    N, M = map(int, input().split())
    Edge = [[] for _ in range(N)]
    for _ in range(N-1):
        x, y = map(int, input().split())
        Edge[x-1].append(y-1)
        Edge[y-1].append(x-1)
    Par = [-1] * N
    Son = [[] for _ in range(N)]
    SonNum = [0] * N
    q = deque()
    for s in Edge[0]: q.append((s, 0))
    while q:
        nn, pn = q.popleft()
        Par[nn] = pn
        Son[pn].append(nn)
        SonNum[pn] += 1
        for ne in Edge[nn]:
            if ne != pn: q.append((ne, nn))

    DP = [1 for i in range(N)]
    visited = [0] * N
    for i, s in enumerate(SonNum):
        if s == 0 and Par[i] > -1:
            q.append((Par[i], 1))
            DP[i] = 1
    while q:
        nn, v = q.popleft()
        DP[nn] *= v + 1
        visited[nn] += 1
        if visited[nn] == SonNum[nn] and nn > 0: q.append((Par[nn], DP[nn]))

    for s in Son[0]: q.append((s, DP[0]))
    while q:
        nn, v = q.popleft()
        DP[nn] *= v // (DP[nn] + 1) + 1
        for s in Son[nn]: q.append((s, DP[nn]))

    for i, d in enumerate(DP): print(d % M)

    return 0

