    sub = [0] * N

    def dfs(node, parent):
        r = 1
        for child in adj[node]:
            if child == parent:
                continue
            r = (r * (1 + dfs(child, node))) % M
        sub[node] = r
        return r

    dfs(0, -1)
    ans = [0] * N
    ans[0] = sub[0]

    def dfs2(node, parent):
        if parent != -1:
            ans[node] = sub[node]  # parent is white
            ans[node] += ans[parent] // (sub[node] + 1) * sub[node]

        for child in adj[node]:
            if child == parent:
                continue
            dfs2(child, node)

    dfs2(0, -1)
    return ans


