from types import GeneratorType


def bootstrap(f, stack=[]):
    def wrappedfunc(*args, **kwargs):
        if stack:
            return f(*args, **kwargs)
        else:
            to = f(*args, **kwargs)
            while True:
                if type(to) is GeneratorType:
                    stack.append(to)
                    to = next(to)
                else:
                    stack.pop()
                    if not stack:
                        break
                    to = stack[-1].send(to)
            return to

    return wrappedfunc


def main():
    n, m = map(int, input().split())

    tree = [[] for _ in range(n)]
    for _ in range(n - 1):
        x, y = map(int, input().split())
        tree[x - 1].append(y - 1)
        tree[y - 1].append(x - 1)

    memo = {}

    @bootstrap
    def dfs(node, parent):
        try:
            yield memo[node, parent]
        except:
            cnt = 1
            for child in tree[node]:
                if child is not parent:
                    call = yield dfs(child, node)
                    cnt = (cnt * (call + 1)) % m
            memo[node, parent] = cnt
            yield cnt

    for i in range(n):
        print(dfs(i, -1))


