fn dfs1(pos: usize, pre: usize, to: &Vec<Vec<usize>>, dp: &mut Vec<usize>, m: usize) {
    dp[pos] = 1;
    for &next in &to[pos] {
        if pre == next {
            continue;
        }
        // println!("{} -> {}", pos, next);
        dfs1(next, pos, &to, dp, m);
        dp[pos] *= dp[next] + 1;
    }
}

fn dfs2(
    pos: usize,
    pre: usize,
    par: usize,
    to: &Vec<Vec<usize>>,
    dp1: &Vec<usize>,
    dp2: &mut Vec<usize>,
    m: usize,
) {
    dp2[pos] = dp1[pos] * (par + 1);
    for &next in &to[pos] {
        if pre == next {
            continue;
        }
        let par = dp2[pos] / (dp1[next] + 1);
        dfs2(next, pos, par, to, dp1, dp2, m);
    }
}

