fn dfs(t: &Vec<Vec<usize>>, r: usize, p: usize, mem: &mut HashMap<(usize, usize), usize>, m: usize) -> usize {
    let mut ret = 1;
    for i in 0..t[r].len() {
        let c = t[r][i];
        if c == p {
            continue;
        }
        if let Some(&n) = mem.get(&(r, c)) {
            ret = ret * (n + 1) % m;
        } else {
            let tmp = dfs(t, c, r, mem, m);
            mem.insert((r, c), tmp);
            ret = ret * (tmp + 1) % m;
        }
    }
    ret
}

