use std::collections::HashMap;
use std::collections::HashSet;
use std::error::Error;
use std::io;

pub fn main() {
    if let Err(_e) = run() {
        panic!("failed.");
    }
}

fn run() -> Result<(), Box<Error>> {
    let mut input = String::new();
    io::stdin().read_line(&mut input);
    let nm: Vec<i64> = input
        .trim()
        .split_whitespace()
        .map(|s| s.parse::<i64>().unwrap())
        .collect();
    let n = nm[0];
    let m = nm[1];
    input.clear();

    let mut edges = HashMap::new();
    for _i in 0..n - 1 {
        io::stdin().read_line(&mut input);
        let edge: Vec<i64> = input
            .trim()
            .split_whitespace()
            .map(|s| s.parse::<i64>().unwrap())
            .collect();
        {
            let tos: &mut HashSet<i64> = edges.entry(edge[0]).or_insert_with(HashSet::new);
            tos.insert(edge[1]);
        }
        {
            let tos: &mut HashSet<i64> = edges.entry(edge[1]).or_insert_with(HashSet::new);
            tos.insert(edge[0]);
        }

        input.clear();
    }
    // dp from -> to -> variations(is_black)
    let mut dp: HashMap<i64, HashMap<i64, HashMap<bool, i64>>> = HashMap::new();
    for i in 1..n + 1 {
        if !edges.contains_key(&i) {
            println!("{}", 1 % m);
            continue;
        }

        let targets = edges.get(&i).unwrap();
        let mut result = 1;
        for &to in targets {
            let mut sub_result = 0;
            sub_result += solve_dp(i, to, true, m, &mut dp, &edges);
            sub_result %= m;
            sub_result += solve_dp(i, to, false, m, &mut dp, &edges);
            sub_result %= m;
            result *= sub_result;
            result %= m;
        }
        println!("{}", result);
    }

    Ok(())
}

fn solve_dp(
    from: i64,
    to: i64,
    is_black: bool,
    m: i64,
    dp: &mut HashMap<i64, HashMap<i64, HashMap<bool, i64>>>,
    edges: &HashMap<i64, HashSet<i64>>,
) -> i64 {
    if !is_black {
        return 1;
    }
    if !edges.contains_key(&to) {
        return 1;
    }
    if let Some(map) = dp.get(&from) {
        if let Some(map) = map.get(&to) {
            if let Some(&value) = map.get(&is_black) {
                return value;
            }
        }
    }

    let mut result = 1;
    let tos = edges.get(&to).unwrap();
    for &next in tos {
        if from == next {
            continue;
        }
        let mut sub_result = 0;
        if is_black {
            sub_result += solve_dp(to, next, true, m, dp, edges);
            sub_result %= m;
        }
        sub_result += solve_dp(to, next, false, m, dp, edges);
        sub_result %= m;
        result *= sub_result;
        result %= m;
    }
    let value = dp
        .entry(from)
        .or_insert(HashMap::new())
        .entry(to)
        .or_insert(HashMap::new())
        .entry(is_black)
        .or_insert(0);
    *value = result;
    result
}

// ---------- begin Rerooting ----------
pub trait RerootingOperator {
    type Value: Clone;
    type Edge: Clone;
    fn init(&mut self, v: usize) -> Self::Value;
    fn merge(
        &mut self,
        parent: &Self::Value,
        child: &Self::Value,
        edge: &Self::Edge,
    ) -> Self::Value;
}

pub struct Rerooting<R: RerootingOperator> {
    manager: R,
    size: usize,
    edge: Vec<(usize, usize, R::Edge, R::Edge)>,
}

impl<R: RerootingOperator> Rerooting<R> {
    pub fn new(size: usize, manager: R) -> Self {
        Rerooting {
            manager: manager,
            size: size,
            edge: vec![],
        }
    }
    #[allow(dead_code)]
    pub fn add_edge(&mut self, a: usize, b: usize, cost: R::Edge) {
        assert!(a < self.size && b < self.size && a != b);
        self.add_edge_bi(a, b, cost.clone(), cost);
    }
    #[allow(dead_code)]
    pub fn add_edge_bi(&mut self, a: usize, b: usize, ab: R::Edge, ba: R::Edge) {
        assert!(a < self.size && b < self.size && a != b);
        self.edge.push((a, b, ab, ba));
    }
    pub fn solve(&mut self) -> Vec<R::Value> {
        let size = self.size;
        let mut graph = vec![vec![]; size];
        for e in self.edge.iter() {
            graph[e.0].push((e.1, e.2.clone()));
            graph[e.1].push((e.0, e.3.clone()));
        }
        let root = 0;
        let mut topo = vec![];
        let mut parent = vec![root; size];
        let mut stack = vec![root];
        let mut parent_edge: Vec<Option<R::Edge>> = (0..size).map(|_| None).collect();
        while let Some(v) = stack.pop() {
            topo.push(v);
            if let Some(k) = graph[v].iter().position(|e| e.0 == parent[v]) {
                let (_, c) = graph[v].remove(k);
                parent_edge[v] = Some(c);
            }
            for e in graph[v].iter() {
                parent[e.0] = v;
                stack.push(e.0);
            }
        }
        assert!(topo.len() == size);
        let manager = &mut self.manager;
        let mut down: Vec<_> = (0..size).map(|v| manager.init(v)).collect();
        for &v in topo.iter().rev() {
            for e in graph[v].iter() {
                down[v] = manager.merge(&down[v], &down[e.0], &e.1);
            }
        }
        let mut up: Vec<_> = (0..size).map(|v| manager.init(v)).collect();
        let mut stack = vec![];
        for &v in topo.iter() {
            if let Some(e) = parent_edge[v].take() {
                let ini = manager.init(v);
                up[v] = manager.merge(&ini, &up[v], &e);
            }
            if !graph[v].is_empty() {
                stack.push((graph[v].as_slice(), up[v].clone()));
                while let Some((g, val)) = stack.pop() {
                    if g.len() == 1 {
                        up[g[0].0] = val;
                    } else {
                        let m = g.len() / 2;
                        let (a, b) = g.split_at(m);
                        for (a, b) in [(a, b), (b, a)].iter() {
                            let mut p = val.clone();
                            for a in a.iter() {
                                p = manager.merge(&p, &down[a.0], &a.1);
                            }
                            stack.push((b, p));
                        }
                    }
                }
            }
            for e in graph[v].iter() {
                up[v] = manager.merge(&up[v], &down[e.0], &e.1);
            }
        }
        up
    }
}
// ---------- end Rerooting ----------

struct DP(usize);

impl RerootingOperator for DP {
    type Value = usize;
    type Edge = ();
    fn init(&mut self, _v: usize) -> Self::Value {
        1
    }
    fn merge(
        &mut self,
        parent: &Self::Value,
        child: &Self::Value,
        _edge: &Self::Edge,
    ) -> Self::Value {
        parent * (child + 1) % self.0
    }
}

use std::io::Read;
use std::io::Write;

fn run() {
    let mut s = String::new();
    std::io::stdin().read_to_string(&mut s).unwrap();
    let mut it = s.trim().split_whitespace();
    let n: usize = it.next().unwrap().parse().unwrap();
    let p = DP(it.next().unwrap().parse().unwrap());
    let mut solver = Rerooting::new(n, p);
    for _ in 1..n {
        let a: usize = it.next().unwrap().parse().unwrap();
        let b: usize = it.next().unwrap().parse().unwrap();
        solver.add_edge(a - 1, b - 1, ());
    }
    let ans = solver.solve();
    let out = std::io::stdout();
    let mut out = std::io::BufWriter::new(out.lock());
    for a in ans {
        writeln!(out, "{}", a).ok();
    }
}

fn main() {
    run();
}

