        dp2[pos] %= m;
    }

    let mut lm = vec![1; to[pos].len()];
    let mut rm = vec![1; to[pos].len()];
    for i in 0..to[pos].len() {
        if i > 0 {
            lm[i] = lm[i - 1];
        }
        lm[i] *= dp1[to[pos][i]] + 1;
        lm[i] %= m;
        // println!("{}, {}, {}", pos, i, lm[i]);
    }

    for i in (0..to[pos].len()).rev() {
        if i + 1 < to[pos].len() {
            rm[i] = rm[i + 1];
        }
        rm[i] *= dp1[to[pos][i]] + 1;
        rm[i] %= m;
        // println!("{}, {}, {}", pos, i, rm[i]);
    }

    let dpold = dp1[pos];

    for (i, &next) in to[pos].iter().enumerate() {
        if pre == next {
            continue;
        }
        dp1[pos] = 1;

        for &nnext in &to[pos] {
            if nnext == next {
                continue;
            }
            dp1[pos] *= dp1[nnext] + 1;
            dp1[pos] %= m;
        }
        dfs2(next, pos, to, dp1, dp2, m);
    }
    dp1[pos] = dpold;
}

fn solve() {
    input! {
        n: usize, m: usize,
        edges: [(usize1, usize1); n - 1],
    }
    let mut to = vec![vec![]; n];
    let mut dp = vec![0; n];
    for &(f, t) in &edges {
        to[f].push(t);
        to[t].push(f);
    }
    dfs1(0, 0, &to, &mut dp, m);

    let mut dp2 = vec![0; n];
    dfs2(0, 0, &to, &mut dp, &mut dp2, m);

    for &v in &dp2 {
        println!("{}", v % m);
    }

}

fn main() {
    solve();
}

