            *self = *self / other;
        }
    }
    impl std::fmt::Debug for ModInt {
        fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
            write!(f, "{}", self.value)
        }
    }
    impl std::fmt::Display for ModInt {
        fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
            write!(f, "{}", self.value)
        }
    }
}

fn dfs1(
    node: usize,
    parent: usize,
    nodes: &Vec<Vec<usize>>,
    dp: &mut Vec<ModInt>,
    m: usize,
) -> ModInt {
    let mut res = ModInt::new(1, m);
    for &next in &nodes[node] {
        if next == parent {
            continue;
        }
        res *= dfs1(next, node, nodes, dp, m) + 1;
    }
    dp[node] = res;
    res
}

fn dfs2(
    node: usize,
    parent: usize,
    nodes: &Vec<Vec<usize>>,
    dp: &Vec<ModInt>,
    res: &mut Vec<ModInt>,
    pval: ModInt,
    m: usize,
) {
    let mut muls = vec![vec![ModInt::new(1, m); 2]; nodes[node].len() + 1];
    for (i, &next) in nodes[node].iter().enumerate() {
        muls[i + 1][0] = muls[i][0]
            * if next == parent {
                pval + 1
            } else {
                dp[next] + 1
            };
    }
    for (i, &next) in nodes[node].iter().enumerate().rev() {
        muls[i][1] = muls[i + 1][1]
            * if next == parent {
                pval + 1
            } else {
                dp[next] + 1
            };
    }
    let mut r = pval + 1;
    for (i, &next) in nodes[node].iter().enumerate().rev() {
        if next == parent {
            continue;
        }
        r *= dp[next] + 1;
        dfs2(next, node, nodes, dp, res, muls[i][0] * muls[i + 1][1], m);
    }
    res[node] = r;
}

fn solve() {
    let (n, m) = get!(usize, usize);
    let xy = get!(usize, usize; n-1);

    let mut nodes = vec![Vec::new(); n + 1];
    for (x, y) in xy {
        nodes[x].push(y);
        nodes[y].push(x);
    }

    let mut dp = vec![ModInt::new(0, m); n + 1];
    let mut res = vec![ModInt::new(1, m); n + 1];
    dfs1(1, 0, &nodes, &mut dp, m);
    dfs2(1, 0, &nodes, &dp, &mut res, ModInt::new(0, m), m);
    for i in 1..n + 1 {
        println!("{}", res[i]);
    }
}

