use std::cmp::{max, min};
use std::collections::HashMap;

fn main() {
    input! {
        n: usize,
        m: usize,
        es: [(usize1, usize1); n-1],
    }

    let mut g = vec![vec![]; n];
    for (u, v) in es {
        g[u].push(v);
        g[v].push(u);
    }

    let mut tbl = HashMap::new();

    for i in 0..n {
        let ans = rec(i, None, true, m, &g, &mut tbl);
        println!("{}", ans);
    }
}

fn rec(
    pos: usize,
    prev: Option<usize>,
    col: bool,
    m: usize,
    g: &Vec<Vec<usize>>,
    tbl: &mut HashMap<(usize, Option<usize>, bool), usize>,
) -> usize {
    if col == false {
        return 1;
    }

    let key = (pos, prev, col);

    if let Some(ret) = tbl.get(&key) {
        return *ret;
    }

    let mut ret = 1;
    for &next in g[pos].iter() {
        if Some(next) == prev {
            continue;
        }

        ret = ret * (rec(next, Some(pos), true, m, g, tbl) + 1) % m;
    }
    ret %= m;

    tbl.insert(key, ret);
    ret
}

