fn dfs1(pos: usize, pre: usize, to: &Vec<Vec<usize>>, dp: &mut Vec<usize>, m: usize) {
    dp[pos] = 1;
    for &next in &to[pos] {
        if pre == next {
            continue;
        }
        // println!("{} -> {}", pos, next);
        dfs1(next, pos, &to, dp, m);
        dp[pos] *= dp[next] + 1;
        dp[pos] %= m;
    }
}

fn dfs2(
    pos: usize,
    pre: usize,
    to: &Vec<Vec<usize>>,
    dp1: &mut Vec<usize>,
    dp2: &mut Vec<usize>,
    m: usize,
) {
    dp2[pos] = 1;
    for &next in &to[pos] {
        dp2[pos] *= dp1[next] + 1;
        dp2[pos] %= m;
    }

    let mut lm = vec![1; to[pos].len()];
    let mut rm = vec![1; to[pos].len()];
    for i in 0..to[pos].len() {
        if i > 0 {
            lm[i] = lm[i - 1];
        }
        lm[i] *= dp1[to[pos][i]] + 1;
        lm[i] %= m;
        // println!("{}, {}, {}", pos, i, lm[i]);
    }

    for i in (0..to[pos].len()).rev() {
        if i + 1 < to[pos].len() {
            rm[i] = rm[i + 1];
        }
        rm[i] *= dp1[to[pos][i]] + 1;
        rm[i] %= m;
        // println!("{}, {}, {}", pos, i, rm[i]);
    }

    let dpold = dp1[pos];

    for (i, &next) in to[pos].iter().enumerate() {
        if pre == next {
            continue;
        }
        dp1[pos] = 1;

        for &nnext in &to[pos] {
            if nnext == next {
                continue;
            }
            dp1[pos] *= dp1[nnext] + 1;
            dp1[pos] %= m;
        }
        dfs2(next, pos, to, dp1, dp2, m);
    }
    dp1[pos] = dpold;
