struct Rec {
    dp: Vec<u64>,
    g: Vec<Vec<usize>>,
    par: Vec<Option<usize>>,
    M: u64,
}
impl Rec {
    // vが黒か白かの場合の数
    fn solve(&mut self, v: usize) -> u64 {
        // 黒の場合
        let mut b = 1;
        for &u in &self.g[v].clone() {
            if let Some(p) = self.par[v] {
                if u == p { continue; }
            }
            b *= self.solve(u);
            b %= M;
        }
        // 白の場合のため+1
        let res = b+1;
        self.dp[v]=res;
        res
    }
}
fn solve() {
    input!{
        N:usize,M:u64,
        xy:[(usize,usize);N-1]
    }
    let mut g = vec![vec![];N];
    for (x,y) in xy {
        g[x-1].push(y-1);
        g[y-1].push(x-1);
    }
    let (depth,par) = dfs_tree(N,0,&g);
    let mut dp = vec![0 as u64;N];
    let mut rec = Rec {
        dp: dp,
        g: g,
        par: par.clone(),
    };
    rec.solve(0);
    let dp = rec.dp;

    let mut as_root=vec![1<<60;N];
    as_root[0]=dp[0]-1;

    let mut V=vec![];
    for i in 0..N {
        V.push((depth[i],i));
    }
    // 浅い順にたどる
    V.sort();

    for (d,v) in V {
        if v==0 { continue; }

        let p = par[v].unwrap();
        // 自分を取り除く
        let a = as_root[p] / dp[v];
        // 白の場合を取り除く
        let b = dp[v]-1;
        // vをルートにした黒だけを求める
        as_root[v]=b*(a+1);
    }

    for i in 0..N {
        println!("{}",as_root[i]%M);
    }
}
fn dfs_tree(n: usize, root: usize, g: &[Vec<usize>]) -> (Vec<usize>, Vec<Option<usize>>) {
    let mut depth = vec![n;n];
    let mut stack = vec![root];
    let mut visited = vec![false;n];
    let mut par = vec![None;n];
    depth[root]=0;
    par[root]=None;
    visited[root]=true;
    while !stack.is_empty() {
        let r = stack.pop().unwrap();
        let cs = &g[r];
        for &c in cs {
            if visited[c] { continue; }
            visited[c]=true;
            par[c]=Some(r);
            depth[c]=depth[r]+1;
            stack.push(c);
        }
    }
    (depth,par)
}

use std::io::Read;
use std::io::Write;

fn run() {
    let out = std::io::stdout();
    let mut out = std::io::BufWriter::new(out.lock());
    let mut s = String::new();
    std::io::stdin().read_to_string(&mut s).unwrap();
    let mut it = s.trim().split_whitespace();
    let n: usize = it.next().unwrap().parse().unwrap();
    let m: u64 = it.next().unwrap().parse().unwrap();
    let mut g = vec![std::collections::BTreeSet::new(); n + 1];
    for _ in 1..n {
        let x: usize = it.next().unwrap().parse().unwrap();
        let y: usize = it.next().unwrap().parse().unwrap();
        g[x].insert(y);
        g[y].insert(x);
    }
    let mut q = vec![];
    let mut stack = vec![(1, 1)];
    while let Some((v, p)) = stack.pop() {
        q.push(v);
        g[v].remove(&p);
        for &u in &g[v] {
            stack.push((u, v));
        }
    }
    let mut dp_down = vec![1; n + 1];
    for &v in q.iter().rev() {
        for &u in &g[v] {
            dp_down[v] = dp_down[v] * (dp_down[u] + 1) % m;
        }
    }
    let mut dp_up = vec![1; n + 1];
    for &v in q.iter() {
        let mut stack = vec![dp_up[v]];
        for &u in &g[v] {
            let val = *stack.last().unwrap() * (dp_down[u] + 1) % m;
            stack.push(val);
        }
        stack.pop();
        let mut mul = 1;
        for &u in g[v].iter().rev() {
            dp_up[u] = (mul * *stack.last().unwrap() + 1) % m;
            mul = mul * (dp_down[u] + 1) % m;
            stack.pop();
        }
    }
    for i in 1..(n + 1) {
        let ans = dp_down[i] * dp_up[i] % m;
        writeln!(out, "{}", ans).ok();
    }
}

fn main() {
    run();
}

use std::collections::HashMap;
use std::collections::HashSet;
use std::error:Error;
use std::io;

pub fn main() {
    if let Err(_e) = run() {
        panic!("failed.");
    }
}

fn run() -> Result<(), Box<Error>> {
    let mut input = String::new();
    io::stdin().read_line(&mut input);
    let nm: Vec<i32> = input
        .trim()
        .split_whitespace()
        .map(|s| s.parse::<i32>().unwrap())
        .collect();
    let n = nm[0];
    let m = nm[1];
    input.clear();

    let mut edges = HashMap::new();
    for _i in 0..n - 1 {
        io::stdin().read_line(&mut input);
        let edge: Vec<i32> = input
            .trim()
            .split_whitespace()
            .map(|s| s.parse::<i32>().unwrap())
            .collect();
        let tos: &mut HashSet<i32> = edges.entry(edge[0]).or_insert_with(HashSet::new);
        tos.insert(edge[1]);
        let tos: &mut HashSet<i32> = edges.entry(edge[1]).or_insert_with(HashSet::new);
        tos.insert(edge[0]);
        input.clear();
    }
    // dp from -> to -> variations(is_black)
    let mut dp: HashMap<i32, HashMap<i32, HashMap<bool, i32>>> = HashMap::new();
    for i in 1..=n {
        if !edges.contains_key(&i) {
            println!("{}", 1 % m);
            continue;
        }

        let targets = edges.get(&i).unwrap();
        let mut result = 1;
        for &to in targets {
            let mut sub_result = 0;
            sub_result += solve_dp(i, to, true, m, &mut dp, &edges);
            sub_result %= m;
            sub_result += solve_dp(i, to, false, m, &mut dp, &edges);
            sub_result %= m;
            result *= sub_result;
            result %= m;
        }
        println!("{}", result);
    }

    Ok(())
}

fn solve_dp(
    from: i32,
    to: i32,
    is_black: bool,
    m: i32,
    dp: &mut HashMap<i32, HashMap<i32, HashMap<bool, i32>>>,
    edges: &HashMap<i32, HashSet<i32>>,
) -> i32 {
    if let Some(map) = dp.get(&from) {
        if let Some(map) = map.get(&to) {
            if let Some(&value) = map.get(&is_black) {
                return value;
            }
        }
    }
    let mut result = 1;
    if !edges.contains_key(&to) {
        return 1;
    }
    let tos = edges.get(&to).unwrap();
    for &next in tos {
        if from == next {
            continue;
        }
        let mut sub_result = 0;
        if is_black {
            sub_result += solve_dp(to, next, true, m, dp, edges);
            sub_result %= m;
        }
        sub_result += solve_dp(to, next, false, m, dp, edges);
        sub_result %= m;
        result *= sub_result;
        result %= m;
    }
    let value = dp
        .entry(from)
        .or_insert(HashMap::new())
        .entry(to)
        .or_insert(HashMap::new())
        .entry(is_black)
        .or_insert(0);
    *value = result;
    result
}

