const M: usize = 1_000_000_007;

fn dfs1(pos: usize, pre: usize, to: &Vec<Vec<usize>>, dp: &mut Vec<usize>, m: usize) {
    dp[pos] = 1;
    for &next in &to[pos] {
        if pre == next {
            continue;
        }
        // println!("{} -> {}", pos, next);
        dfs1(next, pos, &to, dp, m);
        dp[pos] *= dp[next] + 1;
        dp[pos] %= m;
    }
}

fn gcd(a: usize, b: usize) -> usize {
    if b != 0 {
        gcd(b, a % b)
    } else {
        a
    }
}

fn lcm(a: usize, b: usize) -> usize {
    a / gcd(a, b) * b
}

pub fn extgcd(a: i64, b: i64) -> (i64, i64, i64) {
    if b == 0 {
        (a, 1, 0)
    } else {
        let (gcd, x, y) = extgcd(b, a % b);
        (gcd, y, x - (a / b) * y)
    }
}

pub fn mod_inverse(a: usize, m: usize) -> usize {
    let (_, x, _) = extgcd(a as i64, m as i64);
    ((m as i64 + x) as usize % m) % m
}

fn dfs2(
    pos: usize,
    pre: usize,
    par: usize,
    to: &Vec<Vec<usize>>,
    dp1: &Vec<usize>,
    dp2: &mut Vec<usize>,
    m: usize,
) {
    dp2[pos] = dp1[pos] * (par + 1);
    dp2[pos] %= m;
    for &next in &to[pos] {
        if pre == next {
            continue;
        }
        let par = dp2[pos] * mod_inverse(dp1[next] + 1, m);
        // println!("{}", par);
        dfs2(next, pos, par, to, dp1, dp2, m);
    }
}

fn main() {
    input! {
        n: usize, m: usize,
        edges: [(usize1, usize1); n - 1],
    }
    let mut to = vec![vec![]; n];
    let mut dp = vec![0; n];
    for &(f, t) in &edges {
        to[f].push(t);
        to[t].push(f);
    }
    dfs1(0, 0, &to, &mut dp, M);

