use std::collections::HashMap;

fn main() {
    input!{
        n: usize,
        m: usize,
        v: [[usize1; 2]; n - 1]
    }
    let mut tree: Vec<Vec<usize>> = vec![Vec::new(); n];
    for i in 0..n - 1 {
        tree[v[i][0]].push(v[i][1]);
        tree[v[i][1]].push(v[i][0]);
    }
    let mut tab: HashMap<(usize, usize), usize> = HashMap::new();
    let mut q: Vec<(usize, usize)> = Vec::new();
    let mut ans: Vec<usize> = vec![0; n];
    ans[0] = dfs(&tree, 0, 0, &mut tab, m, &mut q);
    // tab.insert((0, 0), ans[0]);
    for i in 1..n {
        ans[q[i].0] = dfs2(&tree, q[i].0, q[i].1, &mut tab, m);
    }
    for i in 0..n {
        println!("{}", ans[i]);
    }
}

fn dfs(t: &Vec<Vec<usize>>, r: usize, p: usize, mem: &mut HashMap<(usize, usize), usize>, m: usize, q: &mut Vec<(usize, usize)>) -> usize {
    q.push((r, p));
    let mut ret = 1;
    for i in 0..t[r].len() {
        let c = t[r][i];
        if c == p {
            continue;
        }
        let tmp = dfs(t, c, r, mem, m, q);
        mem.insert((r, c), tmp);
        ret = ret * (tmp + 1) % m;
    }
    ret
}

fn dfs2(t: &Vec<Vec<usize>>, r: usize, p: usize, mem: &mut HashMap<(usize, usize), usize>, m: usize) -> usize {
    let mut ret = 1;
    for i in 0..t[p].len() {
        let c = t[p][i];
        if c == r {
            continue;
        }
        let n = *mem.get(&(p, c)).unwrap();
        ret = ret * (n + 1) % m;
    }
    mem.insert((r, p), ret);
    (ret + 1) * *mem.get(&(p, r)).unwrap() % m
}

