static mut M: u64 = 0;
fn solve() {
    input!{
        n:usize,m:u64,
        xy:[(usize,usize);n-1]
    }
    unsafe {
        M = m;
    }
    let mut reroot: ReRooting<F> = ReRooting::new(n);
    for (x,y) in xy {
        reroot.connect(x-1, y-1, 1, 1);
    }

    let dp = reroot.build();
    for u in 0..n {
        println!("{}", dp[u]);
    }
}
struct F {}
impl Foldable for F {
    type T = u64;
    type Sum = u64;
    fn identity() -> u64 {
        1
    }
    fn fold(acc: u64, x: u64) -> u64 {
        unsafe {
            (acc + x) % M
        }
    }
    fn merge(a: u64, b: u64) -> u64 {
        unsafe {
            (a * b) % M
        }
    }
}
trait Foldable {
    type Sum: Copy + std::fmt::Debug;
    type T: Copy + std::fmt::Debug;
    fn identity() -> Self::Sum;
    fn merge(x: Self::Sum, y: Self::Sum) -> Self::Sum;
    fn fold(acc: Self::Sum, x: Self::T) -> Self::Sum;
}
#[derive(Clone, Copy)]
struct Edge<T, Sum> {
    to: usize,
    data: T,
    dp: Sum,
    ndp: Sum,
}
struct ReRooting<F: Foldable> {
    subdp: Vec<F::Sum>,
    dp: Vec<F::Sum>,
    g: Vec<Vec<Edge<F::T, F::Sum>>>,
}
impl <F: Foldable> ReRooting<F> {
    pub fn new(n: usize) -> ReRooting<F> {
        ReRooting {
            subdp: vec![F::identity(); n],
            dp: vec![F::identity(); n],
            g: vec![vec![]; n],
        }
    }
    pub fn connect(&mut self, u: usize, v: usize, d: F::T, e: F::T) {
        self.g[u].push(Edge {
            to: v,
            data: d,
            dp: F::identity(),
            ndp: F::identity(),
        });
        self.g[v].push(Edge {
            to: u,
            data: e,
            dp: F::identity(),
            ndp: F::identity(),
        });
    }
    fn dfs_sub(&mut self, u: usize, par: Option<usize>) {
        for i in 0..self.g[u].len() {
            let e = self.g[u][i];
            if Some(e.to) == par { continue; }
            self.dfs_sub(e.to, Some(u));
            self.subdp[u] = F::merge(self.subdp[u], F::fold(self.subdp[e.to], e.data));
        }
    }
    fn dfs_all(&mut self, u: usize, par: Option<usize>, top: F::Sum) {
        let mut buf = F::identity();
        for i in 0..self.g[u].len() {
            let e = &mut self.g[u][i];
            e.ndp = buf;
            e.dp = F::fold(if Some(e.to) == par { top } else { self.subdp[e.to] }, e.data);
            buf = F::merge(buf, e.dp);
        }
        self.dp[u] = buf;
        buf = F::identity();
        for i in (0..self.g[u].len()).rev() {
            let e = self.g[u][i];
            if Some(e.to) != par {
                self.dfs_all(e.to, Some(u), F::merge(e.ndp, buf));
            }
            let e = &mut self.g[u][i];
            e.ndp = F::merge(e.ndp, buf);
            buf = F::merge(buf, e.dp);
        }
    }
    pub fn build(&mut self) -> Vec<F::Sum> {
        self.dfs_sub(0, None);
        self.dfs_all(0, None, F::identity());
        self.dp.clone()
    }
}

use std::collections::HashMap;
use std::collections::HashSet;
use std::error::Error;
use std::io;

pub fn main() {
    if let Err(_e) = run() {
        panic!("failed.");
    }
}

fn run() -> Result<(), Box<Error>> {
    let mut input = String::new();
    io::stdin().read_line(&mut input);
    let nm: Vec<i32> = input
        .trim()
        .split_whitespace()
        .map(|s| s.parse::<i32>().unwrap())
        .collect();
    let n = nm[0];
    let m = nm[1];
    input.clear();

    let mut edges = HashMap::new();
    for _i in 0..n - 1 {
        io::stdin().read_line(&mut input);
        let edge: Vec<i32> = input
            .trim()
            .split_whitespace()
            .map(|s| s.parse::<i32>().unwrap())
            .collect();
        let tos: &mut HashSet<i32> = edges.entry(edge[0]).or_insert_with(HashSet::new);
        tos.insert(edge[1]);
        let tos: &mut HashSet<i32> = edges.entry(edge[1]).or_insert_with(HashSet::new);
        tos.insert(edge[0]);
        input.clear();
    }
    // dp from -> to -> variations(is_black)
    let mut dp: HashMap<i32, HashMap<i32, HashMap<bool, i32>>> = HashMap::new();
    for i in 1..=n {
        if !edges.contains_key(&i) {
            println!("{}", 1 % m);
            continue;
        }

        let targets = edges.get(&i).unwrap();
        let mut result = 1;
        for &to in targets {
            let mut sub_result = 0;
            sub_result += solve_dp(i, to, true, m, &mut dp, &edges);
            sub_result %= m;
            sub_result += solve_dp(i, to, false, m, &mut dp, &edges);
            sub_result %= m;
            result *= sub_result;
            result %= m;
        }
        println!("{}", result);
    }

    Ok(())
}

fn solve_dp(
    from: i32,
    to: i32,
    is_black: bool,
    m: i32,
    dp: &mut HashMap<i32, HashMap<i32, HashMap<bool, i32>>>,
    edges: &HashMap<i32, HashSet<i32>>,
) -> i32 {
    if let Some(map) = dp.get(&from) {
        if let Some(map) = map.get(&to) {
            if let Some(&value) = map.get(&is_black) {
                return value;
            }
        }
    }
    let mut result = 1;
    if !edges.contains_key(&to) {
        return 1;
    }
    let tos = edges.get(&to).unwrap();
    for &next in tos {
        if from == next {
            continue;
        }
        let mut sub_result = 0;
        if is_black {
            sub_result += solve_dp(to, next, true, m, dp, edges);
            sub_result %= m;
        }
        sub_result += solve_dp(to, next, false, m, dp, edges);
        sub_result %= m;
        result *= sub_result;
        result %= m;
    }
    let value = dp
        .entry(from)
        .or_insert(HashMap::new())
        .entry(to)
        .or_insert(HashMap::new())
        .entry(is_black)
        .or_insert(0);
    *value = result;
    result
}

