struct Rec {
    dp: Vec<u64>,
    g: Vec<Vec<usize>>,
    par: Vec<Option<usize>>,
}
impl Rec {
    // vが黒か白かの場合の数
    fn solve(&mut self, v: usize) -> u64 {
        // 黒の場合
        let mut b = 1;
        for &u in &self.g[v].clone() {
            if let Some(p) = self.par[v] {
                if u == p { continue; }
            }
            b *= self.solve(u);
        }
        // 白の場合のため+1
        let res = b+1;
        self.dp[v]=res;
        res
    }
}
fn solve() {
    input!{
        N:usize,M:u64,
        xy:[(usize,usize);N-1]
    }
    let mut g = vec![vec![];N];
    for (x,y) in xy {
        g[x-1].push(y-1);
        g[y-1].push(x-1);
    }
    let (depth,par) = dfs_tree(N,0,&g);
    let mut dp = vec![0 as u64;N];
    let mut rec = Rec {
        dp: dp,
        g: g,
        par: par.clone(),
    };
    rec.solve(0);
    let dp = rec.dp;

    let mut as_root=vec![1<<60;N];
    as_root[0]=dp[0]-1;

    let mut V=vec![];
    for i in 0..N {
        V.push((depth[i],i));
    }
    // 浅い順にたどる
    V.sort();

    for (d,v) in V {
        if v==0 { continue; }

        let p = par[v].unwrap();
        // 自分を取り除く
        let a = as_root[p] / dp[v];
        // 白の場合を取り除く
        let b = dp[v]-1;
        // vをルートにした黒だけを求める
        as_root[v]=b*(a+1);
    }

    for i in 0..N {
        println!("{}",as_root[i]%M);
    }
}
fn dfs_tree(n: usize, root: usize, g: &[Vec<usize>]) -> (Vec<usize>, Vec<Option<usize>>) {
    let mut depth = vec![n;n];
    let mut stack = vec![root];
    let mut visited = vec![false;n];
    let mut par = vec![None;n];
    depth[root]=0;
    par[root]=None;
    visited[root]=true;
    while !stack.is_empty() {
        let r = stack.pop().unwrap();
        let cs = &g[r];
        for &c in cs {
            if visited[c] { continue; }
            visited[c]=true;
            par[c]=Some(r);
            depth[c]=depth[r]+1;
            stack.push(c);
        }
    }
    (depth,par)
}

fn main() {
    use std::collections::HashMap;

    let stdin = std::io::stdin();
    let mut stdin = my::io::InputReader::new(stdin.lock());

    let N: usize = stdin.read();
    let M: u64 = stdin.read();
    let mut graph = vec![Vec::<usize>::new(); N];
    let mut dp = HashMap::<(Option<usize>, usize), u64>::new();
    for i in 0..N - 1 {
        let mut x: usize = stdin.read();
        let mut y: usize = stdin.read();
        x -= 1;
        y -= 1;
        graph[x].push(y);
        graph[y].push(x);
    }

    fn f(parent: Option<usize>, v: usize, M: u64, graph: &Vec<Vec<usize>>, dp: &mut HashMap<(Option<usize>, usize), u64>) -> u64 {
        if dp.contains_key(&(parent, v)) {
            return dp[&(parent, v)];
        }
        let mut result: u64 = 1;
        for &w in &graph[v] {
            if Some(w) == parent { continue; }
            result = (result * (1 + f(Some(v), w, M, graph, dp))) % M;
        }
        dp.insert((parent, v), result);
        result
    }
    for v in 0..N {
        println!("{}", f(None, v, M, &graph, &mut dp));
    }
}

mod my {
    pub mod io {
        use std::io::{BufRead, ErrorKind, Result};
        use std::str::{FromStr, from_utf8};
        use std::fmt::Debug;

        pub fn read_word<R: BufRead>(r: &mut R, buf: &mut Vec<u8>)
                                              -> Result<usize> {
            let mut read = 0;
            loop {
                let (done, used) = {
                    let available = match r.fill_buf() {
                        Ok(n) => n,
                        Err(ref e) if e.kind() == ErrorKind::Interrupted => continue,
                        Err(e) => return Err(e)
                    };
                    match available.iter().position(|&x| x == b'\n' || x == b' ') {
                        Some(i) => {
                            buf.extend_from_slice(&available[..i]);
                            (true, i + 1)
                        }
                        None => {
                            buf.extend_from_slice(available);
                            (false, available.len())
                        }
                    }
                };
                r.consume(used);
                read += used;
                if done || used == 0 {
                    return Ok(read);
                }
            }
        }

        pub struct InputReader<R: BufRead> {
            reader: R,
            buf: Vec<u8>,
        }

        impl<R: BufRead> InputReader<R> {
            pub fn new(reader: R) -> InputReader<R> {
                InputReader {
                    reader: reader,
                    buf: Vec::<u8>::new(),
                }
            }

            pub fn read_word(&mut self) {
                read_word(&mut self.reader, &mut self.buf);
            }

            pub fn read<T>(&mut self) -> T
                where T: FromStr,
                      T::Err: Debug
            {
                self.buf.clear();
                self.read_word();
                from_utf8(&self.buf).unwrap().trim().parse().unwrap()
            }
        }
    }
}

