macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String {
            bytes
                .by_ref()
                .map(|r| r.unwrap() as char)
                .skip_while(|c| c.is_whitespace())
                .take_while(|c| !c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

use std::collections::BTreeMap;

fn main() {
    input!{
        n: usize,
        m: usize,
        v: [[usize1; 2]; n - 1]
    }
    let mut tree: Vec<Vec<usize>> = vec![Vec::new(); n];
    for i in 0..n - 1 {
        tree[v[i][0]].push(v[i][1]);
        tree[v[i][1]].push(v[i][0]);
    }
    let mut tab: BTreeMap<(usize, usize), usize> = BTreeMap::new();
    for i in 0..n {
        println!("{}", dfs(&tree, i, i, &mut tab, m));
    }
}

fn dfs(t: &Vec<Vec<usize>>, r: usize, p: usize, mem: &mut BTreeMap<(usize, usize), usize>, m: usize) -> usize {
    let mut ret = 1;
    for i in 0..t[r].len() {
        let c = t[r][i];
        if c == p {
            continue;
        }
        if let Some(&n) = mem.get(&(r, c)) {
            ret = ret * (n + 1) % m;
        } else {
            let tmp = dfs(t, c, r, mem, m);
            mem.insert((r, c), tmp);
            ret = ret * (tmp + 1) % m;
        }
    }
    ret
}

