fn dfs(u: usize, p: usize, m: usize, graph: &Vec<Vec<usize>>, dp: &mut Vec<Vec<usize>>) {
    dp[u][0] = (dp[p][0] + 1) % m;
    dp[u][1] = 1;
    for &v in &graph[u] {
        if v == p {
            continue;
        }
        dfs(v, u, m, graph, dp);
        dp[u][1] *= dp[v][1] + 1;
        dp[u][1] %= m;
    }
}
fn dfs2(u: usize, p: usize, m: usize, graph: &Vec<Vec<usize>>, dp: &mut Vec<Vec<usize>>) {
    let mut ch = vec![dp[p][2] + 1];
    for &v in &graph[u] {
        if v == p {
            continue;
        }
        ch.push((dp[v][1] + 1) % m);
    }
    let n = ch.len();
    let mut left = vec![1; n];
    let mut right = vec![1; n];
    for i in 0..(n - 1) {
        left[i + 1] = left[i] * ch[i] % m;
        right[n - 2 - i] = right[n - 1 - i] * ch[n - 1 - i] % m;
    }
    let mut i = 1;
    for &v in &graph[u] {
        if v == p {
            continue;
        }
        dp[u][2] = left[i] * right[i] % m;
        dfs2(v, u, m, graph, dp);
        i += 1;
    }
    dp[u][2] = (dp[p][2] + 1) * dp[u][1];
    dp[u][2] %= m;
}
fn main() {
    input! { n, m, xy: [(usize, usize); n-1] };
    let mut dp = vec![vec![0; 3]; n + 1];
    let mut graph = vec![vec![]; n + 1];
    for &(x, y) in &xy {
        graph[x].push(y);
        graph[y].push(x);
    }
    dfs(1, 0, m, &graph, &mut dp);
    dfs2(1, 0, m, &graph, &mut dp);
    with_bufwriter(|out| {
        for v in 1..(n + 1) {
            writeln!(out, "{}", dp[v][2])?;
        }
        Ok(())
    })
    .unwrap();
}

