struct Rec {
    dp: Vec<u64>,
    g: Vec<Vec<usize>>,
    par: Vec<Option<usize>>,
    M: u64,
}
impl Rec {
    // vが黒か白かの場合の数
    fn solve(&mut self, v: usize) -> u64 {
        // 黒の場合
        let mut b = 1;
        for &u in &self.g[v].clone() {
            if let Some(p) = self.par[v] {
                if u == p { continue; }
            }
            b *= self.solve(u);
            b %= self.M;
        }
        // 白の場合のため+1
        let res = b+1;
        self.dp[v]=res;
        res
    }
}
fn solve() {
    input!{
        N:usize,M:u64,
        xy:[(usize,usize);N-1]
    }
    let mut g = vec![vec![];N];
    for (x,y) in xy {
        g[x-1].push(y-1);
        g[y-1].push(x-1);
    }
    let (depth,par) = dfs_tree(N,0,&g);
    let mut dp = vec![0 as u64;N];
    let mut rec = Rec {
        dp: dp,
        g: g,
        par: par.clone(),
        M: M,
    };
    rec.solve(0);
    let dp = rec.dp;

    let mut as_root=vec![1<<60;N];
    as_root[0]=dp[0]-1;

    let mut V=vec![];
    for i in 0..N {
        V.push((depth[i],i));
    }
    // 浅い順にたどる
    V.sort();

    for (d,v) in V {
        if v==0 { continue; }

        let p = par[v].unwrap();
        // 自分を取り除く
        let a = as_root[p] / dp[v];
        // 白の場合を取り除く
        let b = dp[v]-1;
        // vをルートにした黒だけを求める
        as_root[v]=b*(a+1);
    }

    for i in 0..N {
