use std::io::Write;

fn run() {
    let out = std::io::stdout();
    let mut out = std::io::BufWriter::new(out.lock());
    input! {
        n: usize,
        m: u64,
        e: [(usize1, usize1); n - 1],
    }
    let mut g = vec![vec![]; n];
    for (a, b) in e {
        g[a].push(b);
        g[b].push(a);
    }
    let mut parent = vec![n; n];
    let mut q = Vec::with_capacity(n);
    let mut s = vec![];
    s.push(0);
    while let Some(v) = s.pop() {
        q.push(v);
        for &u in g[v].iter() {
            if u == parent[v] {
                continue;
            }
            parent[u] = v;
            s.push(u);
        }
    }
    let mut dp = vec![0; n];
    for &v in q.iter().rev() {
        let mut way = 1;
        for &u in g[v].iter() {
            if u == parent[v] {
                continue;
            }
            way = way * (dp[u] + 1) % m;
        }
        dp[v] = way;
    }
    let mut dp2 = vec![0; n];
    for &v in q.iter() {
        let mut child = vec![];
        for &u in g[v].iter() {
            if u == parent[v] {
                continue;
            }
            child.push(u);
        }
        let len = child.len();
        let mut left = vec![1; len + 2];
        let mut right = vec![1; len + 2];
        for (i, &u) in child.iter().enumerate() {
            let i = i + 1;
            left[i] = left[i - 1] * (dp[u] + 1) % m;
        }
        for (i, &u) in child.iter().enumerate().rev() {
            let i = i + 1;
            right[i] = right[i + 1] * (dp[u] + 1) % m;
        }
        for (i, &u) in child.iter().enumerate() {
            let i = i + 1;
            dp2[u] = (dp2[v] + 1) * left[i - 1] % m * right[i + 1] % m;
        }
    }
    for i in 0..n {
        let ans = dp[i] * (dp2[i] + 1) % m;
        writeln!(out, "{}", ans).unwrap();
    }
}

fn main() {
    run();
}

