macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };

    ($next:expr, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, bytes) => {
        read_value!($next, String).into_bytes()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

fn dfs1(pos: usize, pre: usize, to: &Vec<Vec<usize>>, dp: &mut Vec<usize>, m: usize) {
    dp[pos] = 1;
    for &next in &to[pos] {
        if pre == next {
            continue;
        }
        // println!("{} -> {}", pos, next);
        dfs1(next, pos, &to, dp, m);
        dp[pos] *= dp[next] + 1;
        dp[pos] %= m;
    }
}

fn dfs2(
    pos: usize,
    pre: usize,
    to: &Vec<Vec<usize>>,
    dp1: &mut Vec<usize>,
    dp2: &mut Vec<usize>,
    m: usize,
) {
    dp2[pos] = 1;
    for &next in &to[pos] {
        dp2[pos] *= dp1[next] + 1;
        dp2[pos] %= m;
    }

    let mut lm = vec![1; to[pos].len()];
    let mut rm = vec![1; to[pos].len()];
    for i in 0..to[pos].len() {
        if i > 0 {
            lm[i] = lm[i - 1];
        }
        lm[i] *= dp1[to[pos][i]] + 1;
        lm[i] %= m;
        // println!("{}, {}, {}", pos, i, lm[i]);
    }

    for i in (0..to[pos].len()).rev() {
        if i + 1 < to[pos].len() {
            rm[i] = rm[i + 1];
        }
        rm[i] *= dp1[to[pos][i]] + 1;
        rm[i] %= m;
        // println!("{}, {}, {}", pos, i, rm[i]);
    }

    for (i, &next) in to[pos].iter().enumerate() {
        if pre == next {
            continue;
        }
        dp1[pos] = 1;
        // if i > 0 {
        //     dp1[pos] *= lm[i - 1];
        //     dp1[pos] %= m;
        // }
        // if i + 1 < to[pos].len() {
        //     dp1[pos] *= rm[i + 1];
        //     dp1[pos] %= m;
        // }

        for (j, &nnext) in to[pos].iter().enumerate() {
            if nnext == next {
                continue;
            }
            dp1[pos] *= dp1[to[pos][j]] + 1;
            dp1[pos] %= m;
        }
        dfs2(next, pos, to, dp1, dp2, m);
    }
}

fn main() {
    input! {
        n: usize, m: usize,
        edges: [(usize1, usize1); n - 1],
    }
    let mut to = vec![vec![]; n];
    let mut dp = vec![0; n];
    for &(f, t) in &edges {
        to[f].push(t);
        to[t].push(f);
    }
    dfs1(0, 0, &to, &mut dp, m);

    let mut dp2 = vec![0; n];
    dfs2(0, 0, &to, &mut dp, &mut dp2, m);

    for &v in &dp2 {
        println!("{}", v % m);
    }
}

