use std::collections::HashMap;

fn main() {
    input!{
        n: usize,
        m: usize,
        v: [[usize1; 2]; n - 1]
    }
    let mut tree: Vec<Vec<usize>> = vec![Vec::new(); n];
    for i in 0..n - 1 {
        tree[v[i][0]].push(v[i][1]);
        tree[v[i][1]].push(v[i][0]);
    }
    let mut tab: Vec<HashMap<usize, usize>> = vec![HashMap::new(); n];
    let mut map: HashMap<usize, usize> = HashMap::new();
    let mut q: Vec<(usize, usize)> = Vec::new();
    let mut ans: Vec<usize> = vec![0; n];
    ans[0] = dfs(&tree, 0, 0, &mut tab, m, &mut q);
    let mut acl: Vec<Vec<usize>> = vec![vec![1]; n];
    let mut acr: Vec<Vec<usize>> = vec![Vec::new(); n];
    for i in 0..n {
        for j in 0..tree[i].len() {
            if let Some(&x) = tab[i].get(&tree[i][j]) {
                map.insert(tree[i][j], acr[i].len());
                acl[i].push(x);
                acr[i].push(x);
            }
        }
        acr[i].push(1);
        let l = acl[i].len();
        for j in 1..l {
            acl[i][j] = acl[i][j - 1] * (acl[i][j] + 1) % m;
            acr[i][l - j - 1] = acr[i][l - j] * (acr[i][l - j - 1] + 1) % m;
        }
    }
    let mut par: Vec<usize> = vec![0; n];
    for i in 1..n {
        let r = q[i].0;
        let p = q[i].1;
        ans[r] = *tab[p].get(&r).unwrap();
        let idx = *map.get(&r).unwrap();
        par[r] = acl[p][idx] % m * acr[p][idx + 1] % m * (par[p] + 1) % m;
        ans[r] = ans[r] * (par[r] + 1) % m;
    }
    for i in 0..n {
        println!("{}", ans[i]);
    }
}

fn dfs(t: &Vec<Vec<usize>>, r: usize, p: usize, mem: &mut Vec<HashMap<usize, usize>>, m: usize, q: &mut Vec<(usize, usize)>) -> usize {
    q.push((r, p));
    let mut ret = 1;
    for i in 0..t[r].len() {
        let c = t[r][i];
        if c == p {
            continue;
        }
        let tmp = dfs(t, c, r, mem, m, q);
        mem[r].insert(c, tmp);
        ret = ret * (tmp + 1) % m;
    }
    ret
}

// ---------- begin Rerooting ----------
pub trait RerootingOperator {
    type Value: Clone;
    type Edge: Clone;
    fn init(&mut self, v: usize) -> Self::Value;
    fn merge(
        &mut self,
        parent: &Self::Value,
        child: &Self::Value,
        edge: &Self::Edge,
    ) -> Self::Value;
}

pub struct Rerooting<R: RerootingOperator> {
    manager: R,
    size: usize,
    edge: Vec<(usize, usize, R::Edge, R::Edge)>,
}

impl<R: RerootingOperator> Rerooting<R> {
    pub fn new(size: usize, manager: R) -> Self {
        Rerooting {
            manager: manager,
            size: size,
            edge: vec![],
        }
    }
    #[allow(dead_code)]
    pub fn add_edge(&mut self, a: usize, b: usize, cost: R::Edge) {
        assert!(a < self.size && b < self.size && a != b);
        self.add_edge_bi(a, b, cost.clone(), cost);
    }
    #[allow(dead_code)]
    pub fn add_edge_bi(&mut self, a: usize, b: usize, ab: R::Edge, ba: R::Edge) {
        assert!(a < self.size && b < self.size && a != b);
        self.edge.push((a, b, ab, ba));
    }
    pub fn solve(&mut self) -> Vec<R::Value> {
        let size = self.size;
        let mut graph = vec![vec![]; size];
        for e in self.edge.iter() {
            graph[e.0].push((e.1, e.2.clone()));
            graph[e.1].push((e.0, e.3.clone()));
        }
        let root = 0;
        let mut topo = vec![];
        let mut parent = vec![root; size];
        let mut stack = vec![root];
        let mut parent_edge: Vec<Option<R::Edge>> = (0..size).map(|_| None).collect();
        while let Some(v) = stack.pop() {
            topo.push(v);
            if let Some(k) = graph[v].iter().position(|e| e.0 == parent[v]) {
                let (_, c) = graph[v].remove(k);
                parent_edge[v] = Some(c);
            }
            for e in graph[v].iter() {
                parent[e.0] = v;
                stack.push(e.0);
            }
        }
        assert!(topo.len() == size);
        let manager = &mut self.manager;
        let mut down: Vec<_> = (0..size).map(|v| manager.init(v)).collect();
        for &v in topo.iter().rev() {
            for e in graph[v].iter() {
                down[v] = manager.merge(&down[v], &down[e.0], &e.1);
            }
        }
        let mut up: Vec<_> = (0..size).map(|v| manager.init(v)).collect();
        let mut stack = vec![];
        for &v in topo.iter() {
            if let Some(e) = parent_edge[v].take() {
                let ini = manager.init(v);
                up[v] = manager.merge(&ini, &up[v], &e);
            }
            if !graph[v].is_empty() {
                stack.push((graph[v].as_slice(), up[v].clone()));
                while let Some((g, val)) = stack.pop() {
                    if g.len() == 1 {
                        up[g[0].0] = val;
                    } else {
                        let m = g.len() / 2;
                        let (a, b) = g.split_at(m);
                        for a in [(a, b), (b, a)].iter() {
                            let mut p = val.clone();
                            for a in a.0.iter() {
                                p = manager.merge(&p, &down[a.0], &a.1);
                            }
                            stack.push((a.1, p));
                        }
                    }
                }
            }
            for e in graph[v].iter() {
                up[v] = manager.merge(&up[v], &down[e.0], &e.1);
            }
        }
        up
    }
}
// ---------- end Rerooting ----------

struct DP(usize);

impl RerootingOperator for DP {
    type Value = usize;
    type Edge = ();
    fn init(&mut self, _v: usize) -> Self::Value {
        1
    }
    fn merge(
        &mut self,
        parent: &Self::Value,
        child: &Self::Value,
        _edge: &Self::Edge,
    ) -> Self::Value {
        parent * (child + 1) % self.0
    }
}

