fn main() {
    use std::io::Write;

    let stdin = std::io::stdin();
    let mut stdin = my::io::InputReader::new(stdin.lock());
    let stdout = std::io::stdout();
    let mut stdout = std::io::BufWriter::new(stdout.lock());

    let N: usize = stdin.read();
    let M: u64 = stdin.read();
    let mut graph = vec![Vec::<(usize, usize)>::new(); N];
    let mut dp = vec![None; 2 * (N - 1) + N];
    for i in 0..N - 1 {
        let mut x: usize = stdin.read();
        let mut y: usize = stdin.read();
        x -= 1;
        y -= 1;
        graph[x].push((y, 2 * i));
        graph[y].push((x, 2 * i + 1));
    }

    fn f(parent: Option<usize>, v: usize, edge_id: usize, M: u64, graph: &Vec<Vec<(usize, usize)>>, dp: &mut Vec<Option<u64>>) -> u64 {
        if let Some(result) = dp[edge_id] {
            return result;
        }
        let mut result: u64 = 1;
        for &(w, edge_id_vw) in &graph[v] {
            if Some(w) == parent { continue; }
            result = (result * (1 + f(Some(v), w, edge_id_vw, M, graph, dp))) % M;
        }
        dp[edge_id] = Some(result);
        result
    }
    for v in 0..N {
        writeln!(stdout, "{}", f(None, v, 2 * (N - 1) + v, M, &graph, &mut dp));
    }
    stdout.flush();
}

mod my {
    pub mod io {
        use std::io::{BufRead, ErrorKind, Result};
        use std::str::{FromStr, from_utf8};
        use std::fmt::Debug;

        pub fn read_word<R: BufRead>(r: &mut R, buf: &mut Vec<u8>)
                                              -> Result<usize> {
            let mut read = 0;
            loop {
                let (done, used) = {
                    let available = match r.fill_buf() {
                        Ok(n) => n,
                        Err(ref e) if e.kind() == ErrorKind::Interrupted => continue,
                        Err(e) => return Err(e)
                    };
                    match available.iter().position(|&x| x == b'\n' || x == b' ') {
                        Some(i) => {
                            buf.extend_from_slice(&available[..i]);
                            (true, i + 1)
                        }
                        None => {
                            buf.extend_from_slice(available);
                            (false, available.len())
                        }
                    }
                };
                r.consume(used);
                read += used;
                if done || used == 0 {
                    return Ok(read);
                }
            }
        }

        pub struct InputReader<R: BufRead> {
            reader: R,
            buf: Vec<u8>,
        }

        impl<R: BufRead> InputReader<R> {
            pub fn new(reader: R) -> InputReader<R> {
                InputReader {
                    reader: reader,
                    buf: Vec::<u8>::new(),
                }
            }

            pub fn read_word(&mut self) {
                read_word(&mut self.reader, &mut self.buf);
            }

            pub fn read<T>(&mut self) -> T
                where T: FromStr,
                      T::Err: Debug
            {
                self.buf.clear();
                self.read_word();
                from_utf8(&self.buf).unwrap().trim().parse().unwrap()
            }
        }
    }
}

