struct Rec {
    dp: Vec<u64>,
    g: Vec<Vec<usize>>,
    par: Vec<Option<usize>>,
    M: u64,
}
impl Rec {
    // vが黒か白かの場合の数
    fn solve(&mut self, v: usize) -> u64 {
        // 黒の場合
        let mut b = 1;
        for &u in &self.g[v].clone() {
            if let Some(p) = self.par[v] {
                if u == p { continue; }
            }
            b *= self.solve(u);
            b %= self.M;
        }
        // 白の場合のため+1
        let mut res = b+1;
        self.dp[v]=res%self.M;
        self.dp[v]
    }
}

