    input! { n, m: i64, xy: [(usize1, usize1); n-1] };
    let mut graph = Graph::new(n);
    let one = AnyMod::new(1, m);
    let mut re = ReRooting::new(n, AnyMonoid::new(one, |&d0, &d1| d0 * d1), |&x, _| x + one);
    for &(a, b) in &xy {
        graph.add_undirected_edge(a, b);
    }
    re.rerooting(&graph);
    for i in 0..n {
        println!("{}", re.dp[i] - one);
    }
}
